-- ----------------------------
-- Procedure structure for Consulta_Top_Clientes
-- ----------------------------
DROP PROCEDURE IF EXISTS `Consulta_Top_Clientes`;
delimiter ;;
CREATE PROCEDURE `Consulta_Top_Clientes`(IN `dFechaDesde` DATE,IN `dFechaHasta` DATE,IN `sAlmacen` INT)
  SQL SECURITY INVOKER
BEGIN

SELECT 
clientes.razonsocial AS descripcion,	
SUM( CASE WHEN facturas.sri_documentoscodigo='04' THEN -facturas.subtotalneto ELSE facturas.subtotalneto END ) AS sum_Total
FROM 
facturas
INNER JOIN
clientes
ON facturas.clientesid = clientes.clientesid
WHERE 
DATE(facturas.emision) BETWEEN dFechaDesde AND dFechaHasta
AND ( sAlmacen IS NULL OR facturas.almacenesid = sAlmacen)
AND facturas.anulado = 0
GROUP BY 
clientes.razonsocial
ORDER BY 
sum_Total DESC
LIMIT 10;

END
;;
delimiter ;

-- ----------------------------
-- Procedure structure for Consulta_Top_Productos
-- ----------------------------
DROP PROCEDURE IF EXISTS `Consulta_Top_Productos`;
delimiter ;;
CREATE PROCEDURE `Consulta_Top_Productos`(IN `dFechaDesde` DATE,IN `dFechaHasta` DATE,IN `sAlmacen` INT)
  SQL SECURITY INVOKER
BEGIN
#Routine body goes here...
SELECT 
productos.descripcion AS descripcion,	
SUM(CASE WHEN (facturas.sri_documentoscodigo=04) THEN  (facturas_detalles.cantidad *-1) ELSE (facturas_detalles.cantidad )END) AS Cantidad_Detalle
FROM 
productos
LEFT OUTER JOIN
(
facturas
INNER JOIN
facturas_detalles
ON facturas.facturasid = facturas_detalles.facturasid
)
ON productos.productosid = facturas_detalles.productosid
WHERE 
DATE(facturas.emision) BETWEEN dFechaDesde AND dFechaHasta
AND ( sAlmacen IS NULL OR facturas.almacenesid = sAlmacen)
AND facturas.anulado = 0
AND	facturas_detalles.compuestoid = 0
GROUP BY 
productos.descripcion
ORDER BY 
Cantidad_Detalle DESC
LIMIT 10;
END
;;
delimiter ;

-- ----------------------------
-- Procedure structure for Consulta_Ventas_Almacenes
-- ----------------------------
DROP PROCEDURE IF EXISTS `Consulta_Ventas_Almacenes`;
delimiter ;;
CREATE PROCEDURE `Consulta_Ventas_Almacenes`(IN `dFechaDesde` DATE,IN `dFechaHasta` DATE,IN `sAlmacen` INT)
  SQL SECURITY INVOKER
BEGIN
#Routine body goes here...
SELECT 
almacenes.descripcion AS nombres,
SUM( CASE WHEN facturas.sri_documentoscodigo='04' THEN -1*(facturas.total) ELSE facturas.total END ) AS sum_Total
FROM 
facturas 
INNER JOIN 
almacenes ON almacenes.almacenesid = facturas.almacenesid
WHERE 
DATE(facturas.emision) BETWEEN dFechaDesde  AND dFechaHasta
AND 
(sAlmacen IS NULL OR facturas.almacenesid = sAlmacen)	
AND 
facturas.anulado = 0		
GROUP BY 
almacenes.descripcion;			
END
;;
delimiter ;

-- ----------------------------
-- Procedure structure for Consulta_Ventas_Anios
-- ----------------------------
DROP PROCEDURE IF EXISTS `Consulta_Ventas_Anios`;
delimiter ;;
CREATE PROCEDURE `Consulta_Ventas_Anios`(IN `dAnio` int,IN `sAlmacen` INT)
  SQL SECURITY INVOKER
BEGIN

SELECT TMeses.mes,IFNULL(T1.totales,0) AS totales FROM
 (SELECT 1 AS mes UNION
 SELECT 2 AS mes UNION
 SELECT 3 AS mes UNION
 SELECT 4 AS mes UNION
 SELECT 5 AS mes UNION
 SELECT 6 AS mes UNION
 SELECT 7 AS mes UNION
 SELECT 8 AS mes UNION
 SELECT 9 AS mes UNION
 SELECT 10 AS mes UNION
 SELECT 11 AS mes UNION
 SELECT 12 AS mes) TMeses
LEFT JOIN
    (SELECT MONTH(facturas.emision) AS mes, SUM( CASE WHEN facturas.sri_documentoscodigo='04' THEN -1*facturas.total ELSE facturas.total END ) AS Totales FROM facturas WHERE YEAR(facturas.emision)=dAnio AND ( sAlmacen IS NULL OR facturas.almacenesid = sAlmacen) GROUP BY mes) T1
ON T1.mes = TMeses.mes;
END
;;
delimiter ;

-- ----------------------------
-- Procedure structure for Consulta_Ventas_Facturador
-- ----------------------------
DROP PROCEDURE IF EXISTS `Consulta_Ventas_Facturador`;
delimiter ;;
CREATE PROCEDURE `Consulta_Ventas_Facturador`(IN `dFechaDesde` DATE,IN `dFechaHasta` DATE,IN `sAlmacen` INT)
  SQL SECURITY INVOKER
BEGIN

SELECT 
facturadores.nombres AS nombres,
SUM(CASE WHEN facturas.sri_documentoscodigo='04' THEN -1*(facturas.totalneto) ELSE facturas.totalneto END ) AS sum_Total
FROM 
facturas  INNER JOIN facturadores ON facturadores.facturadoresid = facturas.facturadoresid
WHERE 
DATE(facturas.emision) BETWEEN dFechaDesde  AND dFechaHasta
AND 
(sAlmacen IS NULL OR facturas.almacenesid = sAlmacen)
AND 
facturas.anulado = 0
GROUP BY 
facturadores.nombres;

END
;;
delimiter ;

-- ----------------------------
-- Procedure structure for Consulta_Ventas_Hora
-- ----------------------------
DROP PROCEDURE IF EXISTS `Consulta_Ventas_Hora`;
delimiter ;;
CREATE PROCEDURE `Consulta_Ventas_Hora`(IN `dFechaDesde` DATE,IN `dFechaHasta` DATE ,IN `nAlmacenid` bigint)
  SQL SECURITY INVOKER
BEGIN

SELECT 
HOUR(facturas.fechacreacion) AS Hora,
SUM( CASE WHEN facturas.sri_documentoscodigo='04' THEN -facturas.total ELSE facturas.total END ) AS sum_Total
FROM 
facturas INNER JOIN facturadores ON facturadores.facturadoresid = facturas.facturadoresid
WHERE 
DATE(facturas.emision) BETWEEN dFechaDesde  AND dFechaHasta			
AND (nAlmacenid IS NULL OR facturas.almacenesid=nAlmacenid)
AND facturas.anulado = 0
GROUP BY 
HOUR(facturas.fechacreacion);

END
;;
delimiter ;

-- ----------------------------
-- Procedure structure for Consulta_Ventas_Totales
-- ----------------------------
DROP PROCEDURE IF EXISTS `Consulta_Ventas_Totales`;
delimiter ;;
CREATE PROCEDURE `Consulta_Ventas_Totales`(IN `dFechaDesde` DATE,IN `dFechaHasta` DATE,IN `sAlmacen` INT)
  SQL SECURITY INVOKER
BEGIN
#Routine body goes here...
SELECT 
SUM(cuentasporcobrar.importe ) AS sCredito,	
SUM(CASE WHEN ( cuentasporcobrar.forma_pago_empresaid =  1)  THEN cuentasporcobrar.importe  END ) AS sEfectivo,			
(SELECT SUM(IFNULL(( CASE WHEN facturas.forma_pago_empresaid = 1 THEN (CASE WHEN facturas.sri_documentoscodigo='04' THEN -1*(facturas.totalneto) END) END),0)) FROM facturas WHERE DATE(facturas.emision) BETWEEN dFechaDesde AND dFechaHasta AND ( sAlmacen IS NULL OR facturas.almacenesid = sAlmacen)) AS NcsEfectivo,
SUM(CASE WHEN ( cuentasporcobrar.forma_pago_empresaid =  3)  THEN cuentasporcobrar.importe  END ) AS sCheque,	
SUM(CASE WHEN ( cuentasporcobrar.forma_pago_empresaid =  4)  THEN cuentasporcobrar.importe  END ) AS sTarjeta,
SUM(CASE WHEN ( cuentasporcobrar.forma_pago_empresaid =  5)  THEN cuentasporcobrar.importe  END ) AS sDeposito	
FROM cuentasporcobrar
WHERE
cuentasporcobrar.origen IN ('Facturacion')
AND cuentasporcobrar.emision  BETWEEN dFechaDesde AND dFechaHasta
AND cuentasporcobrar.documentosid IN (SELECT facturas.facturasid  FROM  facturas  WHERE ( sAlmacen IS NULL OR facturas.almacenesid = sAlmacen)	) ; 
END
;;
delimiter ;

-- ----------------------------
-- Procedure structure for Consulta_Ventas_Vendedor
-- ----------------------------
DROP PROCEDURE IF EXISTS `Consulta_Ventas_Vendedor`;
delimiter ;;
CREATE PROCEDURE `Consulta_Ventas_Vendedor`(IN `dFechaDesde` DATE,IN `dFechaHasta` DATE,IN `sAlmacen` INT)
  SQL SECURITY INVOKER
BEGIN

SELECT 
facturadores.nombres AS nombres,
SUM( CASE WHEN facturas.sri_documentoscodigo='04' THEN -1*(facturas.total) ELSE facturas.total END ) AS sum_Total
FROM 
facturas  INNER JOIN facturadores ON facturadores.facturadoresid = facturas.vendedoresid
WHERE 
DATE(facturas.emision) BETWEEN dFechaDesde  AND dFechaHasta
AND 
(sAlmacen IS NULL OR facturas.almacenesid = sAlmacen)
AND 
facturas.anulado = 0
GROUP BY 
facturadores.nombres;

END
;;
delimiter ;

-- ----------------------------
-- Procedure structure for SP_Actualizar_Kardex_Desde_Fecha
-- ----------------------------
DROP PROCEDURE IF EXISTS `SP_Actualizar_Kardex_Desde_Fecha`;
delimiter ;;
CREATE PROCEDURE `SP_Actualizar_Kardex_Desde_Fecha`(IN pid BIGINT,
  IN fecha_documento DATE,
  IN sDecimales INT)
procedimiento: BEGIN
  -- Declaraciones
  DECLARE done INT DEFAULT FALSE;
  DECLARE mid BIGINT;
  DECLARE f DATETIME(3);
  DECLARE tipo INT;
  DECLARE cant DECIMAL(20,8);
  DECLARE costo DECIMAL(20,8);
  DECLARE costeam INT;
  -- Cursor para movimientos desde fecha_documento
  DECLARE cur CURSOR FOR
    SELECT m.movinventariosid, m.fechamovimiento, t.tipocalculo, m.cantidad, m.costo, t.costea
    FROM movinventarios m
    INNER JOIN movinventarios_tipos t ON t.movinventarios_tiposid = m.movinventarios_tiposid
    INNER JOIN productos p ON m.productosid = p.productosid
    WHERE m.productosid = pid AND m.anulado = 0 AND p.servicio = 0 AND DATE(m.fechamovimiento) >= fecha_documento
    ORDER BY m.fechamovimiento, t.orden, m.movinventariosid;

  -- Handler único
  DECLARE CONTINUE HANDLER FOR NOT FOUND SET done = TRUE;
  DECLARE exit handler FOR SQLEXCEPTION, SQLWARNING
  BEGIN
  ROLLBACK;
  RESIGNAL;
  END;  

  -- Intentar obtener último estado antes de la fecha
  -- Variables acumuladas
  SET @stock := 0.00000000;
  SET @costo_total := 0.00000000;
  SET @costo_promedio := 0.00000000;
  SET @costo_actual := 0.00000000;  
  SET @reinicio := FALSE;
  SET @contador := 0;
  SET done = FALSE;

  SELECT stock_acumulado, costo_real
  INTO @stock, @costo_promedio
  FROM movinventarios
  WHERE productosid = pid AND anulado = 0 AND Date(fechamovimiento) < fecha_documento
  ORDER BY fechamovimiento DESC, movinventariosid DESC
  LIMIT 1;

  IF done THEN
    CALL SP_Actualizar_Kardex_Por_Producto_Suma(pid, sDecimales);
    LEAVE procedimiento;
  END IF;

  SET @costo_total := ROUND(@stock * @costo_promedio, sDecimales);
  SET done = FALSE;

  -- Crear tabla temporal
  CREATE TEMPORARY TABLE tmp_kardex (
    movinventariosid BIGINT PRIMARY KEY,
    stock_acumulado DECIMAL(20,8),
    costo_real DECIMAL(20,8),
costo_actual DECIMAL(20,8)    
  );

 START TRANSACTION;
  -- Procesar movimientos desde fecha_documento
  OPEN cur;

  read_loop: LOOP
    FETCH cur INTO mid, f, tipo, cant, costo, costeam;
    IF done THEN
      LEAVE read_loop;
    END IF;

    SET @contador := @contador + 1;

    IF tipo = 1 THEN -- Entradas
      SET @stocksumado := ABS(@stock) + ABS(cant);
      SET @stock := @stock + cant;
      SET @costo_totalsuma := ABS(@costo_total) + ROUND(ABS(cant * costo), sDecimales);

      IF @stock = 0 THEN
        SET @stock := 0.00000000;
        SET @costo_total := 0.00000000;
        SET @costo_promedio := ROUND(costo, sDecimales);
      ELSE
        IF @contador = 1 AND NOT @reinicio AND @costo_totalsuma = 0 THEN
          SET @costo_promedio := ROUND(costo, sDecimales);
        ELSE
          SET @costo_promedio := ROUND(@costo_totalsuma / @stocksumado, sDecimales);
        END IF;
        SET @costo_total := ROUND(@costo_promedio * @stock, sDecimales);
      END IF;
  SET @costo_actual := ROUND(costo,sDecimales);
    ELSE -- Salidas
      SET @stocksumado := ABS(@stock) + ABS(cant);
      SET @stock := @stock - cant;
      SET @costo_totalsuma := ABS(@costo_total) + ROUND(ABS(cant * costo), sDecimales);
      SET @costo_total := ROUND(@costo_total - (cant * costo), sDecimales);

      IF costeam = 1 THEN
        IF @stock = 0 THEN
          SET @costo_promedio := 0;
        ELSE
          SET @costo_promedio := @costo_total / @stock;
        END IF;

        IF @reinicio THEN
          SET @costo_promedio := ROUND(costo, sDecimales);
        END IF;
SET @costo_actual := ROUND(costo,sDecimales);        
      ELSE
        SET @costo_actual := ROUND(@costo_promedio ,sDecimales);
        SET @costo_promedio := ROUND(@costo_actual, sDecimales);
      END IF;

      IF @stock = 0 THEN
        SET @stock := 0.00000000;
        SET @costo_total := 0.00000000;
        SET @reinicio := TRUE;
      END IF;
    END IF;

    --  Insertar en tabla temporal
    INSERT INTO tmp_kardex (movinventariosid, stock_acumulado, costo_real,costo_actual)
    VALUES (mid, @stock, ROUND(@costo_promedio, sDecimales),@costo_actual);

    IF tipo = 1 AND @reinicio THEN
      SET @reinicio := FALSE;
    END IF;

  END LOOP;

  CLOSE cur;

  -- Actualización en bloque
  UPDATE movinventarios m
  JOIN tmp_kardex k ON m.movinventariosid = k.movinventariosid
  SET m.stock_acumulado = k.stock_acumulado,
      m.costo_real = k.costo_real,
       m.costo = k.costo_actual;

  DROP TEMPORARY TABLE tmp_kardex;
 COMMIT;  
END procedimiento
;;
delimiter ;

-- ----------------------------
-- Procedure structure for SP_Actualizar_Kardex_Por_Producto_Suma
-- ----------------------------
DROP PROCEDURE IF EXISTS `SP_Actualizar_Kardex_Por_Producto_Suma`;
delimiter ;;
CREATE PROCEDURE `SP_Actualizar_Kardex_Por_Producto_Suma`(IN pid INT, IN sDecimales INT)
BEGIN
    -- Declaraciones obligatorias al inicio
  DECLARE done INT DEFAULT FALSE;
  DECLARE mid BIGINT;
  DECLARE f DATETIME(3);
  DECLARE tipo INT;
  DECLARE cant DECIMAL(20,8);
  DECLARE costo DECIMAL(20,8);
  DECLARE costeam INT;

  -- Cursor y handler
  DECLARE cur CURSOR FOR
    SELECT m.movinventariosid, m.fechamovimiento, t.tipocalculo, m.cantidad, m.costo, t.costea
    FROM movinventarios m
    INNER JOIN movinventarios_tipos t ON t.movinventarios_tiposid = m.movinventarios_tiposid
    INNER JOIN productos ON m.productosid = productos.productosid
    WHERE m.productosid =pid AND m.anulado = 0 AND productos.servicio = 0
    ORDER BY productos.productosid, m.fechamovimiento, t.orden, m.movinventariosid;

  DECLARE CONTINUE HANDLER FOR NOT FOUND SET done = TRUE;
  DECLARE exit handler FOR SQLEXCEPTION, SQLWARNING
  BEGIN
  ROLLBACK;
  RESIGNAL;
  END;
  -- Variables acumuladas
  SET @stock := 0.00000000;
  SET @costo_total := 0.00000000;
  SET @costo_promedio := 0.00000000;
  SET @reinicio := TRUE;
  SET @contador := 0;

  -- Crear tabla temporal
  CREATE TEMPORARY TABLE tmp_kardex (
    movinventariosid BIGINT PRIMARY KEY,
    stock_acumulado DECIMAL(20,8),
    costo_real DECIMAL(20,8)
  );

  START TRANSACTION;
  -- Procesar movimientos
  OPEN cur;

  read_loop: LOOP
    FETCH cur INTO mid, f, tipo, cant, costo, costeam;
    IF done THEN
      LEAVE read_loop;
    END IF;

    SET @contador := @contador + 1;

    IF tipo = 1 THEN -- Entradas
      SET @stocksumado := ABS(@stock) + ABS(cant);
      SET @stock := @stock + cant;
      SET @costo_totalsuma := ABS(@costo_total) + ROUND(ABS(cant * costo), sDecimales);

      IF @stock = 0 THEN
        SET @stock := 0.00000000;
        SET @costo_total := 0.00000000;
        SET @costo_promedio := ROUND(costo, sDecimales);
      ELSE
        IF @contador = 1 THEN
          SET @costo_promedio := ROUND(costo, sDecimales);
        ELSE
          SET @costo_promedio := ROUND(@costo_totalsuma / @stocksumado, sDecimales);
        END IF;
        SET @costo_total := ROUND(@costo_promedio * @stock, sDecimales);
      END IF;

    ELSE -- Salidas
      SET @stocksumado := ABS(@stock) + ABS(cant);
      SET @stock := @stock - cant;
      SET @costo_totalsuma := ABS(@costo_total) + ROUND(ABS(cant * costo), sDecimales);
      SET @costo_total := ROUND(@costo_total - (cant * costo), sDecimales);

      IF costeam = 1 THEN
        IF @stock = 0 THEN
          SET @costo_promedio := 0;
        ELSE
          SET @costo_promedio := @costo_total / @stock;
        END IF;

        IF @reinicio THEN
          SET @costo_promedio := ROUND(costo, sDecimales);
        END IF;
      ELSE
        SET @costo_promedio := ROUND(costo, sDecimales);
      END IF;

      IF @stock = 0 THEN
        SET @stock := 0.00000000;
        SET @costo_total := 0.00000000;
        SET @reinicio := TRUE;
      END IF;
    END IF;

    -- Insertar en tabla temporal
    INSERT INTO tmp_kardex (movinventariosid, stock_acumulado, costo_real)
    VALUES (mid, @stock, ROUND(@costo_promedio, sDecimales));

    IF tipo = 1 AND @reinicio THEN
      SET @reinicio := FALSE;
    END IF;

  END LOOP;

  CLOSE cur;

  -- Actualización en bloque
  UPDATE movinventarios m
  JOIN tmp_kardex k ON m.movinventariosid = k.movinventariosid
  SET m.stock_acumulado = k.stock_acumulado,
      m.costo_real = k.costo_real;

  DROP TEMPORARY TABLE tmp_kardex;
  COMMIT;  
END
;;
delimiter ;

-- ----------------------------
-- Procedure structure for SP_Actualizar_Kardex_Todos_Productos
-- ----------------------------
DROP PROCEDURE IF EXISTS `SP_Actualizar_Kardex_Todos_Productos`;
delimiter ;;
CREATE PROCEDURE `SP_Actualizar_Kardex_Todos_Productos`()
BEGIN
  DECLARE done INT DEFAULT FALSE;
  DECLARE pid BIGINT;
  DECLARE pDecimales BIGINT; 
  DECLARE cur CURSOR FOR
    SELECT DISTINCT productosid
    FROM movinventarios
    WHERE anulado = 0;

  DECLARE CONTINUE HANDLER FOR NOT FOUND SET done = TRUE;
  set pDecimales=IFNULL((SELECT 	
fdc_costos 
FROM 
parametros_empresa),0);


  OPEN cur;

  read_loop: LOOP
    FETCH cur INTO pid;
    IF done THEN
      LEAVE read_loop;
    END IF;

    CALL SP_Actualizar_Kardex_Por_Producto_Suma(pid,pDecimales);
  END LOOP;

  CLOSE cur;
END
;;
delimiter ;

-- ----------------------------
-- Procedure structure for SP_Actualiza_Secuencias_Internas
-- ----------------------------
DROP PROCEDURE IF EXISTS `SP_Actualiza_Secuencias_Internas`;
delimiter ;;
CREATE PROCEDURE `SP_Actualiza_Secuencias_Internas`(IN sTabla VARCHAR(255))
  MODIFIES SQL DATA 
  SQL SECURITY INVOKER
BEGIN
  UPDATE secuenciales  SET valor=(valor+1) WHERE secuencial=sTabla;
END
;;
delimiter ;

-- ----------------------------
-- Procedure structure for SP_almacenes_ABC
-- ----------------------------
DROP PROCEDURE IF EXISTS `SP_almacenes_ABC`;
delimiter ;;
CREATE PROCEDURE `SP_almacenes_ABC`(IN pAccion varchar(1), IN pRegistrosJson json)
BEGIN
  DECLARE vJsonEsValido int;
  DECLARE vItems int;
  DECLARE vIndex bigint UNSIGNED DEFAULT 0;
  DECLARE vErrorMensaje text;
  DECLARE vRegistroAnterior longtext;


  # VARIABLES DE LOS DATOS DE LA TABLA
  DECLARE p_descripcion varchar(20) DEFAULT '';
  DECLARE p_almacenesid int(11);
  DECLARE p_estado tinyint(4) DEFAULT 0;
  DECLARE p_acumulativo tinyint(4) DEFAULT 0;
  DECLARE p_disponibleventa tinyint(4) DEFAULT 0;
  DECLARE p_meta decimal(12, 2) DEFAULT 0.00;
  DECLARE p_fechacreacion datetime(3) DEFAULT '0000-00-00 00:00:00.000';
  DECLARE p_usuariocreacion varchar(25) DEFAULT '';
  DECLARE p_fechamodificacion datetime(3) DEFAULT '0000-00-00 00:00:00.000';
  DECLARE p_usuariomodificacion varchar(25) DEFAULT '';


  # VARIABLE DE LOS DATOS DE LA AUDITORIA
  DECLARE p_sis_subcategoriasid int(11) DEFAULT 0;
  DECLARE p_sis_empresasid int(11) DEFAULT 0;
  DECLARE p_sis_usuariosid varchar(20) DEFAULT '';
  DECLARE p_equipo varchar(50) DEFAULT '';
  DECLARE p_tipooperacion varchar(50) DEFAULT '';
  DECLARE p_detalle longtext;

  # CONTROLAMOS SI HAY ERROR
  DECLARE EXIT HANDLER FOR SQLEXCEPTION, SQLWARNING
  BEGIN
    GET DIAGNOSTICS CONDITION 1 vErrorMensaje = MESSAGE_TEXT;
    SELECT
      CASE WHEN LOCATE('Cannot delete or update a parent row',vErrorMensaje)>0 THEN JSON_ARRAYAGG(JSON_OBJECT('procesado', FALSE, 'mensaje', 'No Se Puede Eliminar Almacen en Uso')) ELSE JSON_ARRAYAGG(JSON_OBJECT('procesado', FALSE, 'mensaje', vErrorMensaje)) END AS resultado;
    ROLLBACK;
  END;
  # VALIDAMOS SI EL OBJETO JSON ES VALIDO 
  SET vJsonEsValido = JSON_VALID(pRegistrosJson);

  IF vJsonEsValido = 0 THEN
    # EL OBJETO JSON NO ES VALIDO
    SELECT
      JSON_ARRAYAGG(JSON_OBJECT('procesado', FALSE, 'mensaje', 'Json no es valido')) AS resultado;
  ELSE

    # VALIDAMOS QUE TENGA ALMENOS UN ELEMENTO
    SET vItems = JSON_LENGTH(pRegistrosJson, '$.cabecera');

    IF vItems > 0 THEN
      START TRANSACTION;
        WHILE vIndex < vItems DO

          # DATOS TABLA
          SET p_descripcion = IFNULL(JSON_UNQUOTE(JSON_EXTRACT(pRegistrosJson, CONCAT('$.cabecera[', vIndex, '].descripcion'))), p_descripcion);
          SET p_almacenesid = IFNULL(JSON_UNQUOTE(JSON_EXTRACT(pRegistrosJson, CONCAT('$.cabecera[', vIndex, '].almacenesid'))), p_almacenesid);
          SET p_estado = IFNULL(JSON_UNQUOTE(JSON_EXTRACT(pRegistrosJson, CONCAT('$.cabecera[', vIndex, '].estado'))), p_estado);
          SET p_acumulativo = IFNULL(JSON_UNQUOTE(JSON_EXTRACT(pRegistrosJson, CONCAT('$.cabecera[', vIndex, '].acumulativo'))), p_acumulativo);
          SET p_disponibleventa = IFNULL(JSON_UNQUOTE(JSON_EXTRACT(pRegistrosJson, CONCAT('$.cabecera[', vIndex, '].disponibleventa'))), p_disponibleventa);
          SET p_meta = IFNULL(JSON_UNQUOTE(JSON_EXTRACT(pRegistrosJson, CONCAT('$.cabecera[', vIndex, '].meta'))), p_meta);


          # DATOS AUDITORIA
          SET p_sis_subcategoriasid = JSON_UNQUOTE(JSON_EXTRACT(pRegistrosJson, CONCAT('$.cabecera[', vIndex, '].sis_subcategoriasid')));
          SET p_sis_empresasid = JSON_UNQUOTE(JSON_EXTRACT(pRegistrosJson, CONCAT('$.cabecera[', vIndex, '].sis_empresasid')));
          SET p_sis_usuariosid = JSON_UNQUOTE(JSON_EXTRACT(pRegistrosJson, CONCAT('$.cabecera[', vIndex, '].sis_usuariosid')));
          SET p_equipo = JSON_UNQUOTE(JSON_EXTRACT(pRegistrosJson, CONCAT('$.cabecera[', vIndex, '].equipo')));


          CASE pAccion
            WHEN 'C' THEN SET p_tipooperacion = 'N';
                SET p_fechacreacion = NOW(3);
                SET p_usuariocreacion = JSON_UNQUOTE(JSON_EXTRACT(pRegistrosJson, CONCAT('$.cabecera[', vIndex, '].usuariocreacion')));
                SET p_fechamodificacion = NULL;
                SET p_usuariomodificacion = '';
                SET p_detalle = REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(JSON_INSERT('{}', '$.almacenes', JSON_EXTRACT(pRegistrosJson, CONCAT('$.cabecera[', vIndex, ']'))), '"[', '['), ']"', ']'), '\\', ''), '"{', '{'), '}"', '}');

                # INSERTAMOS LOS REGISTROS
                INSERT INTO almacenes (descripcion, almacenesid, estado, acumulativo, disponibleventa, meta, fechacreacion, usuariocreacion, fechamodificacion, usuariomodificacion)
                  VALUES (p_descripcion, p_almacenesid, p_estado, p_acumulativo, p_disponibleventa, p_meta, p_fechacreacion, p_usuariocreacion, p_fechamodificacion, p_usuariomodificacion);
SET p_almacenesid = LAST_INSERT_ID();
            WHEN 'M' THEN SET p_tipooperacion = 'M';
                SET p_fechamodificacion = NOW(3);
                SET p_usuariomodificacion = JSON_UNQUOTE(JSON_EXTRACT(pRegistrosJson, CONCAT('$.cabecera[', vIndex, '].usuariomodificacion')));


                SET vRegistroAnterior = (SELECT
                    JSON_OBJECT
                    (
                    'descripcion', descripcion,
                    'almacenesid', almacenesid,
                    'estado', estado,
                    'acumulativo', acumulativo,
                    'disponibleventa',disponibleventa,
                    'meta', meta,
                    'fechamodificacion', fechamodificacion,
                    'usuariomodificacion', usuariomodificacion
                    )
                  FROM almacenes
                  WHERE almacenes.almacenesid = p_almacenesid);

                SET p_detalle = REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(JSON_INSERT('{}', '$.almacenes', vRegistroAnterior), '"[', '['), ']"', ']'), '\\', ''), '"{', '{'), '}"', '}');

                # ACTUALIZAMOS LOS REGISTROS
                UPDATE almacenes
                SET descripcion = p_descripcion,
                    almacenesid = p_almacenesid,
                    estado = p_estado,
                    acumulativo = p_acumulativo,
                    disponibleventa = p_disponibleventa,
                    meta = p_meta,
                    fechamodificacion = p_fechamodificacion,
                    usuariomodificacion = p_usuariomodificacion
                WHERE  almacenesid = p_almacenesid;

            WHEN 'E' THEN SET p_tipooperacion = 'E';
                SET p_detalle = REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(JSON_INSERT('{}', '$.almacenes', JSON_EXTRACT(pRegistrosJson, CONCAT('$.cabecera[', vIndex, ']'))), '"[', '['), ']"', ']'), '\\', ''), '"{', '{'), '}"', '}');

                # ELIMINAMOS LOS REGISTROS
                DELETE
                  FROM almacenes
                WHERE almacenesid = p_almacenesid;

          END CASE;

          # INSERTAMOS LA AUDITORIA
          CALL sistemaperseo.SP_ABC_sis_log_sistema(p_sis_subcategoriasid, p_sis_empresasid, p_sis_usuariosid, p_tipooperacion, p_detalle, p_equipo);

          SET vIndex = vIndex + 1;
        END WHILE;
      COMMIT;

# RETORNAMOS LA RESPUESTAS
      IF pAccion IN ('C', 'M') THEN

SELECT
almacenes.almacenesid, 
almacenes.descripcion, 
almacenes.estado, 
almacenes.acumulativo, 
almacenes.meta, 
almacenes.disponibleventa, 
almacenes.fechacreacion, 
almacenes.usuariocreacion, 
almacenes.fechamodificacion, 
almacenes.usuariomodificacion,
          (SELECT
              JSON_ARRAYAGG(JSON_OBJECT('procesado', TRUE, 'mensaje', 'Completado con Éxito'))) AS resultado
        FROM
almacenes
        WHERE almacenes.almacenesid = p_almacenesid;

      ELSE
        SELECT
          JSON_ARRAYAGG(JSON_OBJECT('procesado', TRUE, 'mensaje', 'Completado con Éxito')) AS resultado;
      END IF;
    END IF;
  END IF;
END
;;
delimiter ;

-- ----------------------------
-- Procedure structure for SP_almacenes_ConsultarID
-- ----------------------------
DROP PROCEDURE IF EXISTS `SP_almacenes_ConsultarID`;
delimiter ;;
CREATE PROCEDURE `SP_almacenes_ConsultarID`(IN p_almacenesid int(11))
BEGIN

  SELECT
    almacenes.descripcion,
    almacenes.almacenesid,
    almacenes.estado,
    almacenes.acumulativo,
    almacenes.disponibleventa, 
    almacenes.meta,
    almacenes.fechacreacion,
    almacenes.usuariocreacion,
    almacenes.fechamodificacion,
    almacenes.usuariomodificacion
  FROM almacenes
  WHERE almacenes.almacenesid = p_almacenesid;
END
;;
delimiter ;

-- ----------------------------
-- Procedure structure for SP_bancos_ABC
-- ----------------------------
DROP PROCEDURE IF EXISTS `SP_bancos_ABC`;
delimiter ;;
CREATE PROCEDURE `SP_bancos_ABC`(IN pAccion varchar(1), IN pRegistrosJson json)
BEGIN
  DECLARE vJsonEsValido int;
  DECLARE vItems int;
  DECLARE vIndex bigint UNSIGNED DEFAULT 0;
  DECLARE vErrorMensaje text;
  DECLARE vRegistroAnterior longtext;


  # VARIABLES DE LOS DATOS DE LA TABLA
  DECLARE p_bancosid int(11);
  DECLARE p_codigocontable varchar(30) DEFAULT '';
  DECLARE p_descripcion varchar(50) DEFAULT '';
  DECLARE p_tipocuenta tinyint(4) DEFAULT 0;
  DECLARE p_cuenta varchar(20) DEFAULT '';
  DECLARE p_fechaapertura date DEFAULT '0000-00-00';
  DECLARE p_secuencialcheque bigint(20) DEFAULT 0;
  DECLARE p_estado tinyint(4) DEFAULT 0;
  DECLARE p_tipousuario tinyint(3) DEFAULT 0;
  DECLARE p_titularcuenta varchar(50) DEFAULT '';
  DECLARE p_telefonooficialcuenta varchar(50) DEFAULT '';
  DECLARE p_fechacreacion datetime(3) DEFAULT '0000-00-00 00:00:00.000';
  DECLARE p_usuariocreacion varchar(25) DEFAULT '';
  DECLARE p_fechamodificacion datetime(3) DEFAULT '0000-00-00 00:00:00.000';
  DECLARE p_usuariomodificacion varchar(25) DEFAULT '';


  # VARIABLE DE LOS DATOS DE LA AUDITORIA
  DECLARE p_sis_subcategoriasid int(11) DEFAULT 0;
  DECLARE p_sis_empresasid int(11) DEFAULT 0;
  DECLARE p_sis_usuariosid varchar(20) DEFAULT '';
  DECLARE p_equipo varchar(50) DEFAULT '';
  DECLARE p_tipooperacion varchar(50) DEFAULT '';
  DECLARE p_detalle longtext;

  # CONTROLAMOS SI HAY ERROR
  DECLARE EXIT HANDLER FOR SQLEXCEPTION, SQLWARNING
  BEGIN
    GET DIAGNOSTICS CONDITION 1 vErrorMensaje = MESSAGE_TEXT;
    SELECT
      CASE WHEN LOCATE('Cannot delete or update a parent row',vErrorMensaje)>0 THEN JSON_ARRAYAGG(JSON_OBJECT('procesado', FALSE, 'mensaje', 'No Se Puede Eliminar, Banco en Uso')) ELSE JSON_ARRAYAGG(JSON_OBJECT('procesado', FALSE, 'mensaje', vErrorMensaje)) END AS resultado;
    ROLLBACK;
  END;
  
  # VALIDAMOS SI EL OBJETO JSON ES VALIDO 
  SET vJsonEsValido = JSON_VALID(pRegistrosJson);

  IF vJsonEsValido = 0 THEN
    # EL OBJETO JSON NO ES VALIDO
    SELECT
      JSON_ARRAYAGG(JSON_OBJECT('procesado', FALSE, 'mensaje', 'Json no es valido')) AS resultado;
  ELSE

    # VALIDAMOS QUE TENGA ALMENOS UN ELEMENTO
    SET vItems = JSON_LENGTH(pRegistrosJson, '$.cabecera');

    IF vItems > 0 THEN
      START TRANSACTION;
        WHILE vIndex < vItems DO

          # DATOS TABLA
          SET p_bancosid = IFNULL(JSON_UNQUOTE(JSON_EXTRACT(pRegistrosJson, CONCAT('$.cabecera[', vIndex, '].bancosid'))), p_bancosid);
          SET p_codigocontable = IFNULL(JSON_UNQUOTE(JSON_EXTRACT(pRegistrosJson, CONCAT('$.cabecera[', vIndex, '].codigocontable'))), p_codigocontable);
          SET p_descripcion = IFNULL(JSON_UNQUOTE(JSON_EXTRACT(pRegistrosJson, CONCAT('$.cabecera[', vIndex, '].descripcion'))), p_descripcion);
          SET p_tipocuenta = IFNULL(JSON_UNQUOTE(JSON_EXTRACT(pRegistrosJson, CONCAT('$.cabecera[', vIndex, '].tipocuenta'))), p_tipocuenta);
          SET p_cuenta = IFNULL(JSON_UNQUOTE(JSON_EXTRACT(pRegistrosJson, CONCAT('$.cabecera[', vIndex, '].cuenta'))), p_cuenta);
          SET p_fechaapertura = IFNULL(JSON_UNQUOTE(JSON_EXTRACT(pRegistrosJson, CONCAT('$.cabecera[', vIndex, '].fechaapertura'))), p_fechaapertura);
          SET p_secuencialcheque = IFNULL(JSON_UNQUOTE(JSON_EXTRACT(pRegistrosJson, CONCAT('$.cabecera[', vIndex, '].secuencialcheque'))), p_secuencialcheque);
          SET p_estado = IFNULL(JSON_UNQUOTE(JSON_EXTRACT(pRegistrosJson, CONCAT('$.cabecera[', vIndex, '].estado'))), p_estado);
          SET p_tipousuario = IFNULL(JSON_UNQUOTE(JSON_EXTRACT(pRegistrosJson, CONCAT('$.cabecera[', vIndex, '].tipousuario'))), p_tipousuario);
          SET p_titularcuenta = IFNULL(JSON_UNQUOTE(JSON_EXTRACT(pRegistrosJson, CONCAT('$.cabecera[', vIndex, '].titularcuenta'))), p_titularcuenta);
          SET p_telefonooficialcuenta = IFNULL(JSON_UNQUOTE(JSON_EXTRACT(pRegistrosJson, CONCAT('$.cabecera[', vIndex, '].telefonooficialcuenta'))), p_telefonooficialcuenta);


          # DATOS AUDITORIA
          SET p_sis_subcategoriasid = JSON_UNQUOTE(JSON_EXTRACT(pRegistrosJson, CONCAT('$.cabecera[', vIndex, '].sis_subcategoriasid')));
          SET p_sis_empresasid = JSON_UNQUOTE(JSON_EXTRACT(pRegistrosJson, CONCAT('$.cabecera[', vIndex, '].sis_empresasid')));
          SET p_sis_usuariosid = JSON_UNQUOTE(JSON_EXTRACT(pRegistrosJson, CONCAT('$.cabecera[', vIndex, '].sis_usuariosid')));
          SET p_equipo = JSON_UNQUOTE(JSON_EXTRACT(pRegistrosJson, CONCAT('$.cabecera[', vIndex, '].equipo')));


          CASE pAccion
            WHEN 'C' THEN SET p_tipooperacion = 'N';
                SET p_fechacreacion = NOW(3);
                SET p_usuariocreacion = JSON_UNQUOTE(JSON_EXTRACT(pRegistrosJson, CONCAT('$.cabecera[', vIndex, '].usuariocreacion')));
                SET p_fechamodificacion = NULL;
                SET p_usuariomodificacion = '';
                SET p_detalle = REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(JSON_INSERT('{}', '$.bancos', JSON_EXTRACT(pRegistrosJson, CONCAT('$.cabecera[', vIndex, ']'))), '"[', '['), ']"', ']'), '\\', ''), '"{', '{'), '}"', '}');


                # INSERTAMOS LOS REGISTROS
                INSERT INTO bancos (bancosid, codigocontable, descripcion, tipocuenta, cuenta, fechaapertura, secuencialcheque, estado, tipousuario, titularcuenta, telefonooficialcuenta, fechacreacion, usuariocreacion, fechamodificacion, usuariomodificacion)
                  VALUES (p_bancosid, p_codigocontable, p_descripcion, p_tipocuenta, p_cuenta, p_fechaapertura, p_secuencialcheque, p_estado, p_tipousuario, p_titularcuenta, p_telefonooficialcuenta, p_fechacreacion, p_usuariocreacion, p_fechamodificacion, p_usuariomodificacion);

SET p_bancosid = LAST_INSERT_ID();
            WHEN 'M' THEN SET p_tipooperacion = 'M';
                SET p_fechamodificacion = NOW(3);
                SET p_usuariomodificacion = JSON_UNQUOTE(JSON_EXTRACT(pRegistrosJson, CONCAT('$.cabecera[', vIndex, '].usuariomodificacion')));


                SET vRegistroAnterior = (SELECT
                    JSON_OBJECT
                    (
                    'bancosid', bancosid,
                    'codigocontable', codigocontable,
                    'descripcion', descripcion,
                    'tipocuenta', tipocuenta,
                    'cuenta', cuenta,
                    'fechaapertura', fechaapertura,
                    'secuencialcheque', secuencialcheque,
                    'estado', estado,
                    'tipousuario', tipousuario,
                    'titularcuenta', titularcuenta,
                    'telefonooficialcuenta', telefonooficialcuenta,
                    'fechamodificacion', fechamodificacion,
                    'usuariomodificacion', usuariomodificacion
                    )
                  FROM bancos
                  WHERE bancos.bancosid = p_bancosid);

                SET p_detalle = REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(JSON_INSERT('{}', '$.bancos', vRegistroAnterior), '"[', '['), ']"', ']'), '\\', ''), '"{', '{'), '}"', '}');

                # ACTUALIZAMOS LOS REGISTROS
                UPDATE bancos
                SET bancosid = p_bancosid,
                    codigocontable = p_codigocontable,
                    descripcion = p_descripcion,
                    tipocuenta = p_tipocuenta,
                    cuenta = p_cuenta,
                    fechaapertura = p_fechaapertura,
                    secuencialcheque = p_secuencialcheque,
                    estado = p_estado,
                    tipousuario = p_tipousuario,
                    titularcuenta = p_titularcuenta,
                    telefonooficialcuenta = p_telefonooficialcuenta,
                    fechamodificacion = p_fechamodificacion,
                    usuariomodificacion = p_usuariomodificacion
                WHERE bancosid = p_bancosid;

            WHEN 'E' THEN SET p_tipooperacion = 'E';
                SET p_detalle = REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(JSON_INSERT('{}', '$.bancos', JSON_EXTRACT(pRegistrosJson, CONCAT('$.cabecera[', vIndex, ']'))), '"[', '['), ']"', ']'), '\\', ''), '"{', '{'), '}"', '}');

                # ELIMINAMOS LOS REGISTROS
                DELETE
                  FROM bancos
                WHERE bancosid = p_bancosid;

          END CASE;

          # INSERTAMOS LA AUDITORIA
          CALL sistemaperseo.SP_ABC_sis_log_sistema(p_sis_subcategoriasid, p_sis_empresasid, p_sis_usuariosid, p_tipooperacion, p_detalle, p_equipo);

          SET vIndex = vIndex + 1;
        END WHILE;
      COMMIT;


      # RETORNAMOS LA RESPUESTAS
      IF pAccion IN ('C', 'M') THEN

        SELECT
          bancos.bancosid,
          bancos.codigocontable,
cuentas_contables.descripcion AS cuentanombre,
          bancos.descripcion,
          bancos.tipocuenta,
          bancos.cuenta,
          bancos.fechaapertura,
          bancos.secuencialcheque,
          bancos.estado,
          bancos.tipousuario,
          bancos.titularcuenta,
          bancos.telefonooficialcuenta,
          bancos.fechacreacion,
          bancos.usuariocreacion,
          bancos.fechamodificacion,
          bancos.usuariomodificacion,
          (SELECT
              JSON_ARRAYAGG(JSON_OBJECT('procesado', TRUE, 'mensaje', 'Completado con Éxito'))) AS resultado
        FROM bancos INNER JOIN cuentas_contables ON bancos.codigocontable=cuentas_contables.codigocontable
        WHERE bancos.bancosid = p_bancosid;

      ELSE
        SELECT
          JSON_ARRAYAGG(JSON_OBJECT('procesado', TRUE, 'mensaje', 'Completado con Éxito')) AS resultado;
      END IF;
    END IF;
  END IF;
END
;;
delimiter ;

