-- ----------------------------
-- Procedure structure for SP_cajas_ABC
-- ----------------------------
DROP PROCEDURE IF EXISTS `SP_cajas_ABC`;
delimiter ;;
CREATE PROCEDURE `SP_cajas_ABC`(IN pAccion varchar(1), IN pRegistrosJson json)
BEGIN
  DECLARE vJsonEsValido int;
  DECLARE vItems int;
  DECLARE vIndex bigint UNSIGNED DEFAULT 0;
  DECLARE vErrorMensaje text;
  DECLARE vRegistroAnterior longtext;


  # VARIABLES DE LOS DATOS DE LA TABLA
  DECLARE p_cajasid int(11);
  DECLARE p_codigocontable varchar(30) DEFAULT '';
  DECLARE p_descripcion varchar(50) DEFAULT '';
  DECLARE p_controlasaldos tinyint(4) DEFAULT 0;
  DECLARE p_estado tinyint(4) DEFAULT 0;
  DECLARE p_deuna_id int(11) DEFAULT 0;
  DECLARE p_valorapertura decimal(14, 2) DEFAULT 0.00;
  DECLARE p_fechacreacion datetime(3) DEFAULT '0000-00-00 00:00:00.000';
  DECLARE p_usuariocreacion varchar(25) DEFAULT '';
  DECLARE p_fechamodificacion datetime(3) DEFAULT '0000-00-00 00:00:00.000';
  DECLARE p_usuariomodificacion varchar(25) DEFAULT '';


  # VARIABLE DE LOS DATOS DE LA AUDITORIA
  DECLARE p_sis_subcategoriasid int(11) DEFAULT 0;
  DECLARE p_sis_empresasid int(11) DEFAULT 0;
  DECLARE p_sis_usuariosid varchar(20) DEFAULT '';
  DECLARE p_equipo varchar(50) DEFAULT '';
  DECLARE p_tipooperacion varchar(50) DEFAULT '';
  DECLARE p_detalle longtext;

  # CONTROLAMOS SI HAY ERROR
  DECLARE EXIT HANDLER FOR SQLEXCEPTION, SQLWARNING
  BEGIN
    GET DIAGNOSTICS CONDITION 1 vErrorMensaje = MESSAGE_TEXT;
    SELECT
      CASE WHEN LOCATE('Cannot delete or update a parent row',vErrorMensaje)>0 THEN JSON_ARRAYAGG(JSON_OBJECT('procesado', FALSE, 'mensaje', 'No Se Puede Eliminar, Caja en Uso')) ELSE JSON_ARRAYAGG(JSON_OBJECT('procesado', FALSE, 'mensaje', vErrorMensaje)) END AS resultado;
    ROLLBACK;
  END;
  # VALIDAMOS SI EL OBJETO JSON ES VALIDO 
  SET vJsonEsValido = JSON_VALID(pRegistrosJson);

  IF vJsonEsValido = 0 THEN
    # EL OBJETO JSON NO ES VALIDO
    SELECT
      JSON_ARRAYAGG(JSON_OBJECT('procesado', FALSE, 'mensaje', 'Json no es valido')) AS resultado;
  ELSE

    # VALIDAMOS QUE TENGA ALMENOS UN ELEMENTO
    SET vItems = JSON_LENGTH(pRegistrosJson, '$.cabecera');

    IF vItems > 0 THEN
      START TRANSACTION;
        WHILE vIndex < vItems DO

          # DATOS TABLA
          SET p_cajasid = IFNULL(JSON_UNQUOTE(JSON_EXTRACT(pRegistrosJson, CONCAT('$.cabecera[', vIndex, '].cajasid'))), p_cajasid);
          SET p_codigocontable = IFNULL(JSON_UNQUOTE(JSON_EXTRACT(pRegistrosJson, CONCAT('$.cabecera[', vIndex, '].codigocontable'))), p_codigocontable);
          SET p_descripcion = IFNULL(JSON_UNQUOTE(JSON_EXTRACT(pRegistrosJson, CONCAT('$.cabecera[', vIndex, '].descripcion'))), p_descripcion);
          SET p_controlasaldos = IFNULL(JSON_UNQUOTE(JSON_EXTRACT(pRegistrosJson, CONCAT('$.cabecera[', vIndex, '].controlasaldos'))), p_controlasaldos);
          SET p_estado = IFNULL(JSON_UNQUOTE(JSON_EXTRACT(pRegistrosJson, CONCAT('$.cabecera[', vIndex, '].estado'))), p_estado);
          SET p_deuna_id = IFNULL(JSON_UNQUOTE(JSON_EXTRACT(pRegistrosJson, CONCAT('$.cabecera[', vIndex, '].deuna_id'))), p_deuna_id);
          SET p_valorapertura = IFNULL(JSON_UNQUOTE(JSON_EXTRACT(pRegistrosJson, CONCAT('$.cabecera[', vIndex, '].valorapertura'))), p_valorapertura);


          # DATOS AUDITORIA
          SET p_sis_subcategoriasid = JSON_UNQUOTE(JSON_EXTRACT(pRegistrosJson, CONCAT('$.cabecera[', vIndex, '].sis_subcategoriasid')));
          SET p_sis_empresasid = JSON_UNQUOTE(JSON_EXTRACT(pRegistrosJson, CONCAT('$.cabecera[', vIndex, '].sis_empresasid')));
          SET p_sis_usuariosid = JSON_UNQUOTE(JSON_EXTRACT(pRegistrosJson, CONCAT('$.cabecera[', vIndex, '].sis_usuariosid')));
          SET p_equipo = JSON_UNQUOTE(JSON_EXTRACT(pRegistrosJson, CONCAT('$.cabecera[', vIndex, '].equipo')));


          CASE pAccion
            WHEN 'C' THEN SET p_tipooperacion = 'N';
                SET p_fechacreacion = NOW(3);
                SET p_usuariocreacion = JSON_UNQUOTE(JSON_EXTRACT(pRegistrosJson, CONCAT('$.cabecera[', vIndex, '].usuariocreacion')));
                SET p_fechamodificacion = NULL;
                SET p_usuariomodificacion = '';
                SET p_detalle = REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(JSON_INSERT('{}', '$.cajas', JSON_EXTRACT(pRegistrosJson, CONCAT('$.cabecera[', vIndex, ']'))), '"[', '['), ']"', ']'), '\\', ''), '"{', '{'), '}"', '}');

                # INSERTAMOS LOS REGISTROS
                INSERT INTO cajas (cajasid, codigocontable, descripcion, controlasaldos, estado,deuna_id, valorapertura, fechacreacion, usuariocreacion, fechamodificacion, usuariomodificacion)
                  VALUES (p_cajasid, p_codigocontable, p_descripcion, p_controlasaldos, p_estado,p_deuna_id, p_valorapertura, p_fechacreacion, p_usuariocreacion, p_fechamodificacion, p_usuariomodificacion);

SET p_cajasid = LAST_INSERT_ID();

            WHEN 'M' THEN SET p_tipooperacion = 'M';
                SET p_fechamodificacion = NOW(3);
                SET p_usuariomodificacion = JSON_UNQUOTE(JSON_EXTRACT(pRegistrosJson, CONCAT('$.cabecera[', vIndex, '].usuariomodificacion')));


                SET vRegistroAnterior = (SELECT
                    JSON_OBJECT
                    (
                    'cajasid', cajasid,
                    'codigocontable', codigocontable,
                    'descripcion', descripcion,
                    'controlasaldos', controlasaldos,
                    'estado', estado,
                    'deuna_id', deuna_id,
                    'valorapertura', valorapertura,
                    'fechamodificacion', fechamodificacion,
                    'usuariomodificacion', usuariomodificacion
                    )
                  FROM cajas
                  WHERE cajas.cajasid = p_cajasid);

                SET p_detalle = REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(JSON_INSERT('{}', '$.cajas', vRegistroAnterior), '"[', '['), ']"', ']'), '\\', ''), '"{', '{'), '}"', '}');

                # ACTUALIZAMOS LOS REGISTROS
                UPDATE cajas
                SET cajasid = p_cajasid,
                    codigocontable = p_codigocontable,
                    descripcion = p_descripcion,
                    controlasaldos = p_controlasaldos,
                    estado = p_estado,
                    deuna_id = p_deuna_id,
                    valorapertura = p_valorapertura,
                    fechamodificacion = p_fechamodificacion,
                    usuariomodificacion = p_usuariomodificacion
                WHERE cajasid = p_cajasid;

            WHEN 'E' THEN SET p_tipooperacion = 'E';
                SET p_detalle = REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(JSON_INSERT('{}', '$.cajas', JSON_EXTRACT(pRegistrosJson, CONCAT('$.cabecera[', vIndex, ']'))), '"[', '['), ']"', ']'), '\\', ''), '"{', '{'), '}"', '}');

                # ELIMINAMOS LOS REGISTROS
                DELETE
                  FROM cajas
                WHERE cajasid = p_cajasid;

          END CASE;

          # INSERTAMOS LA AUDITORIA
          CALL sistemaperseo.SP_ABC_sis_log_sistema(p_sis_subcategoriasid, p_sis_empresasid, p_sis_usuariosid, p_tipooperacion, p_detalle, p_equipo);

          SET vIndex = vIndex + 1;
        END WHILE;
      COMMIT;

       # RETORNAMOS LA RESPUESTAS
      IF pAccion IN ('C', 'M') THEN

        SELECT
    cajas.cajasid,
    cajas.codigocontable,
    cajas.descripcion,
cuentas_contables.codigocontable,
cuentas_contables.descripcion as cuentanombre,
    cajas.controlasaldos,
    cajas.estado,
    cajas.deuna_id,
    cajas.valorapertura,
    cajas.fechacreacion,
    cajas.usuariocreacion,
    cajas.fechamodificacion,
    cajas.usuariomodificacion,
    (SELECT
              JSON_ARRAYAGG(JSON_OBJECT('procesado', TRUE, 'mensaje', 'Completado con Éxito'))) AS resultado
  FROM cajas INNER JOIN cuentas_contables on cajas.codigocontable=cuentas_contables.codigocontable
  WHERE cajas.cajasid = p_cajasid;

      ELSE
        SELECT
          JSON_ARRAYAGG(JSON_OBJECT('procesado', TRUE, 'mensaje', 'Completado con Éxito')) AS resultado;
      END IF;
    END IF;
  END IF;
END
;;
delimiter ;

-- ----------------------------
-- Procedure structure for SP_cajas_ConsultarID
-- ----------------------------
DROP PROCEDURE IF EXISTS `SP_cajas_ConsultarID`;
delimiter ;;
CREATE PROCEDURE `SP_cajas_ConsultarID`(IN p_cajasid int(11))
BEGIN

  SELECT
    cajas.cajasid,
    cajas.codigocontable,
    cajas.descripcion,
 cuentas_contables.codigocontable,
 cuentas_contables.descripcion as cuentanombre,
    cajas.controlasaldos,
    cajas.estado,
    cajas.deuna_id,
    cajas.valorapertura,
    cajas.fechacreacion,
    cajas.usuariocreacion,
    cajas.fechamodificacion,
    cajas.usuariomodificacion
  FROM cajas LEFT JOIN cuentas_contables on cajas.codigocontable=cuentas_contables.codigocontable
  WHERE cajas.cajasid = p_cajasid;

END
;;
delimiter ;

-- ----------------------------
-- Procedure structure for SP_centros_costos_ABC
-- ----------------------------
DROP PROCEDURE IF EXISTS `SP_centros_costos_ABC`;
delimiter ;;
CREATE PROCEDURE `SP_centros_costos_ABC`(IN pAccion varchar(1), IN pRegistrosJson json)
centros_costos:BEGIN
  DECLARE vJsonEsValido int;
  DECLARE vItems int;
  DECLARE vIndex bigint UNSIGNED DEFAULT 0;
  DECLARE vErrorMensaje text;
  DECLARE vRegistroAnterior longtext;


  # VARIABLES DE LOS DATOS DE LA TABLA
  DECLARE p_centros_costosid int(11);
  DECLARE p_centro_costocodigo varchar(20) DEFAULT '';
  DECLARE p_descripcion varchar(50) DEFAULT '';
  DECLARE p_avance decimal(5, 2) DEFAULT 0.00;
  DECLARE p_nivel varchar(1) DEFAULT '';
  DECLARE p_estado tinyint(4) DEFAULT 0;
  DECLARE p_fechacreacion datetime(3) DEFAULT '0000-00-00 00:00:00.000';
  DECLARE p_usuariocreacion varchar(25) DEFAULT '';
  DECLARE p_fechamodificacion datetime(3) DEFAULT '0000-00-00 00:00:00.000';
  DECLARE p_usuariomodificacion varchar(25) DEFAULT '';


  # VARIABLE DE LOS DATOS DE LA AUDITORIA
  DECLARE p_sis_subcategoriasid int(11) DEFAULT 0;
  DECLARE p_sis_empresasid int(11) DEFAULT 0;
  DECLARE p_sis_usuariosid varchar(20) DEFAULT '';
  DECLARE p_equipo varchar(50) DEFAULT '';
  DECLARE p_tipooperacion varchar(50) DEFAULT '';
  DECLARE p_detalle longtext;

 
  # CONTROLAMOS SI HAY ERROR
  DECLARE EXIT HANDLER FOR SQLEXCEPTION, SQLWARNING
  BEGIN
    GET DIAGNOSTICS CONDITION 1 vErrorMensaje = MESSAGE_TEXT;
   SELECT
      CASE WHEN LOCATE('Cannot delete or update a parent row',vErrorMensaje)>0 THEN JSON_ARRAYAGG(JSON_OBJECT('procesado', FALSE, 'mensaje', 'No Se Puede Eliminar, Centro de Costos en Uso')) ELSE JSON_ARRAYAGG(JSON_OBJECT('procesado', FALSE, 'mensaje', vErrorMensaje)) END AS resultado;
    ROLLBACK;
  END;
  # VALIDAMOS SI EL OBJETO JSON ES VALIDO 
  SET vJsonEsValido = JSON_VALID(pRegistrosJson);

  IF vJsonEsValido = 0 THEN
    # EL OBJETO JSON NO ES VALIDO
    SELECT
      JSON_ARRAYAGG(JSON_OBJECT('procesado', FALSE, 'mensaje', 'Json no es valido')) AS resultado;
  ELSE

    # VALIDAMOS QUE TENGA ALMENOS UN ELEMENTO
    SET vItems = JSON_LENGTH(pRegistrosJson, '$.cabecera');

    IF vItems > 0 THEN
      START TRANSACTION;
        WHILE vIndex < vItems DO

          # DATOS TABLA
          SET p_centros_costosid = IFNULL(JSON_UNQUOTE(JSON_EXTRACT(pRegistrosJson, CONCAT('$.cabecera[', vIndex, '].centros_costosid'))), p_centros_costosid);
          SET p_centro_costocodigo = IFNULL(JSON_UNQUOTE(JSON_EXTRACT(pRegistrosJson, CONCAT('$.cabecera[', vIndex, '].centro_costocodigo'))), p_centro_costocodigo);
          SET p_descripcion = IFNULL(JSON_UNQUOTE(JSON_EXTRACT(pRegistrosJson, CONCAT('$.cabecera[', vIndex, '].descripcion'))), p_descripcion);
          SET p_avance = IFNULL(JSON_UNQUOTE(JSON_EXTRACT(pRegistrosJson, CONCAT('$.cabecera[', vIndex, '].avance'))), p_avance);
          SET p_nivel = IFNULL(JSON_UNQUOTE(JSON_EXTRACT(pRegistrosJson, CONCAT('$.cabecera[', vIndex, '].nivel'))), p_nivel);
          SET p_estado = IFNULL(JSON_UNQUOTE(JSON_EXTRACT(pRegistrosJson, CONCAT('$.cabecera[', vIndex, '].estado'))), p_estado);


          # DATOS AUDITORIA
          SET p_sis_subcategoriasid = JSON_UNQUOTE(JSON_EXTRACT(pRegistrosJson, CONCAT('$.cabecera[', vIndex, '].sis_subcategoriasid')));
          SET p_sis_empresasid = JSON_UNQUOTE(JSON_EXTRACT(pRegistrosJson, CONCAT('$.cabecera[', vIndex, '].sis_empresasid')));
          SET p_sis_usuariosid = JSON_UNQUOTE(JSON_EXTRACT(pRegistrosJson, CONCAT('$.cabecera[', vIndex, '].sis_usuariosid')));
          SET p_equipo = JSON_UNQUOTE(JSON_EXTRACT(pRegistrosJson, CONCAT('$.cabecera[', vIndex, '].equipo')));


          CASE pAccion
            WHEN 'C' THEN SET p_tipooperacion = 'N';
                SET p_fechacreacion = NOW(3);
                SET p_usuariocreacion = JSON_UNQUOTE(JSON_EXTRACT(pRegistrosJson, CONCAT('$.cabecera[', vIndex, '].usuariocreacion')));
                SET p_fechamodificacion = NULL;
                SET p_usuariomodificacion = '';
                SET p_detalle = REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(JSON_INSERT('{}', '$.centros_costos', JSON_EXTRACT(pRegistrosJson, CONCAT('$.cabecera[', vIndex, ']'))), '"[', '['), ']"', ']'), '\\', ''), '"{', '{'), '}"', '}');

                # INSERTAMOS LOS REGISTROS
                INSERT INTO centros_costos (centros_costosid, centro_costocodigo, descripcion, avance, nivel, estado, fechacreacion, usuariocreacion, fechamodificacion, usuariomodificacion)
                  VALUES (p_centros_costosid, p_centro_costocodigo, p_descripcion, p_avance, p_nivel, p_estado, p_fechacreacion, p_usuariocreacion, p_fechamodificacion, p_usuariomodificacion);

                SET p_centros_costosid = LAST_INSERT_ID();

            WHEN 'M' THEN SET p_tipooperacion = 'M';
                SET p_fechamodificacion = NOW(3);
                SET p_usuariomodificacion = JSON_UNQUOTE(JSON_EXTRACT(pRegistrosJson, CONCAT('$.cabecera[', vIndex, '].usuariomodificacion')));


                SET vRegistroAnterior = (SELECT
                    JSON_OBJECT
                    (
                    'centros_costosid', centros_costosid,
                    'centro_costocodigo', centro_costocodigo,
                    'descripcion', descripcion,
                    'avance', avance,
                    'nivel', nivel,
                    'estado', estado,
                    'fechamodificacion', fechamodificacion,
                    'usuariomodificacion', usuariomodificacion
                    )
                  FROM centros_costos
                  WHERE centros_costos.centros_costosid = p_centros_costosid);

                SET p_detalle = REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(JSON_INSERT('{}', '$.centros_costos', vRegistroAnterior), '"[', '['), ']"', ']'), '\\', ''), '"{', '{'), '}"', '}');

                # ACTUALIZAMOS LOS REGISTROS
                UPDATE centros_costos
                SET centros_costosid = p_centros_costosid,
                    centro_costocodigo = p_centro_costocodigo,
                    descripcion = p_descripcion,
                    avance = p_avance,
                    nivel = p_nivel,
                    estado = p_estado,
                    fechamodificacion = p_fechamodificacion,
                    usuariomodificacion = p_usuariomodificacion
                WHERE centros_costosid = p_centros_costosid;

            WHEN 'E' THEN SET p_tipooperacion = 'E';
                SET p_detalle = REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(JSON_INSERT('{}', '$.centros_costos', JSON_EXTRACT(pRegistrosJson, CONCAT('$.cabecera[', vIndex, ']'))), '"[', '['), ']"', ']'), '\\', ''), '"{', '{'), '}"', '}');

SET @p_docid = (SELECT DISTINCT COUNT(centros_costosid) as centros_costosid FROM centros_costos WHERE centros_costos.centro_costocodigo LIKE 	CONCAT(p_centro_costocodigo,'%') );

IF @p_docid > 1 THEN
SELECT
JSON_ARRAYAGG(JSON_OBJECT('procesado', FALSE, 'mensaje', 'El Centro de costo tiene Sub-centros de costo')) AS resultado;
LEAVE centros_costos;
ELSE	
                # ELIMINAMOS LOS REGISTROS
                DELETE
                  FROM centros_costos
                WHERE centros_costosid = p_centros_costosid;
END IF;
          END CASE;

          # INSERTAMOS LA AUDITORIA
          CALL sistemaperseo.SP_ABC_sis_log_sistema(p_sis_subcategoriasid, p_sis_empresasid, p_sis_usuariosid, p_tipooperacion, p_detalle, p_equipo);

          SET vIndex = vIndex + 1;
        END WHILE;
      COMMIT;


      # RETORNAMOS LA RESPUESTAS
      IF pAccion IN ('C', 'M') THEN

        SELECT
          centros_costos.centros_costosid,
          centros_costos.centro_costocodigo,
          centros_costos.descripcion,
          centros_costos.avance,
          centros_costos.nivel,
          centros_costos.estado,
          centros_costos.fechacreacion,
          centros_costos.usuariocreacion,
          centros_costos.fechamodificacion,
          centros_costos.usuariomodificacion,
          (SELECT
              JSON_ARRAYAGG(JSON_OBJECT('procesado', TRUE, 'mensaje', 'Completado con Éxito'))) AS resultado
        FROM centros_costos
        WHERE centros_costos.centros_costosid = p_centros_costosid;

      ELSE
        SELECT
          JSON_ARRAYAGG(JSON_OBJECT('procesado', TRUE, 'mensaje', 'Completado con Éxito')) AS resultado;
      END IF;
    END IF;
  END IF;

END
;;
delimiter ;

