-- ----------------------------
-- Procedure structure for SP_clientes_bancos_ABC
-- ----------------------------
DROP PROCEDURE IF EXISTS `SP_clientes_bancos_ABC`;
delimiter ;;
CREATE PROCEDURE `SP_clientes_bancos_ABC`(IN pAccion varchar(1), IN pRegistrosJson json)
clientes_bancos:BEGIN
  DECLARE vJsonEsValido int;
  DECLARE vItems int;
  DECLARE vIndex bigint UNSIGNED DEFAULT 0;
  DECLARE vErrorMensaje text;
  DECLARE vRegistroAnterior longtext;


  # VARIABLES DE LOS DATOS DE LA TABLA
  DECLARE p_clientes_bancosid int(11);
  DECLARE p_descripcion varchar(30) DEFAULT '';
  DECLARE p_codigo varchar(5) DEFAULT '';
DECLARE p_tipooperacion varchar(50) DEFAULT '';

 

   # CONTROLAMOS SI HAY ERROR
  DECLARE EXIT HANDLER FOR SQLEXCEPTION, SQLWARNING
  BEGIN
    GET DIAGNOSTICS CONDITION 1 vErrorMensaje = MESSAGE_TEXT;
   SELECT
      CASE WHEN LOCATE('Cannot delete or update a parent row',vErrorMensaje)>0 THEN JSON_ARRAYAGG(JSON_OBJECT('procesado', FALSE, 'mensaje', 'No Se Puede Eliminar, Banco en Uso')) ELSE JSON_ARRAYAGG(JSON_OBJECT('procesado', FALSE, 'mensaje', vErrorMensaje)) END AS resultado;
    ROLLBACK;
  END;
  # VALIDAMOS SI EL OBJETO JSON ES VALIDO 
  SET vJsonEsValido = JSON_VALID(pRegistrosJson);

  IF vJsonEsValido = 0 THEN
    # EL OBJETO JSON NO ES VALIDO
    SELECT
      JSON_ARRAYAGG(JSON_OBJECT('procesado', FALSE, 'mensaje', 'Json no es valido')) AS resultado;
  ELSE

    # VALIDAMOS QUE TENGA ALMENOS UN ELEMENTO
    SET vItems = JSON_LENGTH(pRegistrosJson, '$.cabecera');

    IF vItems > 0 THEN
      START TRANSACTION;
        WHILE vIndex < vItems DO

          # DATOS TABLA
          SET p_clientes_bancosid = IFNULL(JSON_UNQUOTE(JSON_EXTRACT(pRegistrosJson, CONCAT('$.cabecera[', vIndex, '].clientes_bancosid'))), p_clientes_bancosid);
          SET p_descripcion = IFNULL(JSON_UNQUOTE(JSON_EXTRACT(pRegistrosJson, CONCAT('$.cabecera[', vIndex, '].descripcion'))), p_descripcion);
          SET p_codigo = IFNULL(JSON_UNQUOTE(JSON_EXTRACT(pRegistrosJson, CONCAT('$.cabecera[', vIndex, '].codigo'))), p_codigo);


         

          CASE pAccion
            WHEN 'C' THEN SET p_tipooperacion = 'N';

                # INSERTAMOS LOS REGISTROS
                INSERT INTO clientes_bancos (clientes_bancosid, descripcion, codigo)
                  VALUES (p_clientes_bancosid, p_descripcion, p_codigo);

                SET p_clientes_bancosid = LAST_INSERT_ID();

            WHEN 'M' THEN SET p_tipooperacion = 'M';
               

                SET vRegistroAnterior = (SELECT
                    JSON_OBJECT
                    (
                    'clientes_bancosid', clientes_bancosid,
                    'descripcion', descripcion,
                    'codigo', codigo
                    )
                  FROM clientes_bancos
                  WHERE clientes_bancos.clientes_bancosid = p_clientes_bancosid);

                

                # ACTUALIZAMOS LOS REGISTROS
                UPDATE clientes_bancos
                SET clientes_bancosid = p_clientes_bancosid,
                    descripcion = p_descripcion,
                    codigo = p_codigo
                WHERE clientes_bancosid = p_clientes_bancosid;

            WHEN 'E' THEN SET p_tipooperacion = 'E';
                
SET @p_docid = (SELECT DISTINCT COUNT(movcaja.bancotarjetaid) as bancotarjetaid FROM movcaja WHERE	movcaja.forma_pago_empresaid = 3 AND
movcaja.bancotarjetaid = p_clientes_bancosid);

IF @p_docid > 0 THEN

SELECT
JSON_ARRAYAGG(JSON_OBJECT('procesado', FALSE, 'mensaje', 'El Banco del Cliente ya tiene documentos asociados')) AS resultado;
LEAVE clientes_bancos;


ELSE	
# ELIMINAMOS LOS REGISTROS
DELETE
FROM clientes_bancos
WHERE clientes_bancosid = p_clientes_bancosid;
END IF;
          END CASE;

        

          SET vIndex = vIndex + 1;
        END WHILE;
      COMMIT;


      # RETORNAMOS LA RESPUESTAS
      IF pAccion IN ('C', 'M') THEN

        SELECT
          clientes_bancos.clientes_bancosid,
          clientes_bancos.descripcion,
          clientes_bancos.codigo,
          (SELECT
              JSON_ARRAYAGG(JSON_OBJECT('procesado', TRUE, 'mensaje', 'Completado con Éxito'))) AS resultado
        FROM clientes_bancos
        WHERE clientes_bancos.clientes_bancosid = p_clientes_bancosid;

      ELSE
        SELECT
          JSON_ARRAYAGG(JSON_OBJECT('procesado', TRUE, 'mensaje', 'Completado con Éxito')) AS resultado;
      END IF;
    END IF;
  END IF;

END
;;
delimiter ;

