-- ----------------------------
-- Procedure structure for SP_clientes_sucursales_ABC
-- ----------------------------
DROP PROCEDURE IF EXISTS `SP_clientes_sucursales_ABC`;
delimiter ;;
CREATE PROCEDURE `SP_clientes_sucursales_ABC`(IN pAccion varchar(1), IN pRegistrosJson json)
clientes_sucursales:BEGIN
  DECLARE vJsonEsValido int;
  DECLARE vItems int;
  DECLARE vIndex bigint UNSIGNED DEFAULT 0;
  DECLARE vErrorMensaje text;
  DECLARE vRegistroAnterior longtext;

  # VARIABLES DE LOS DATOS DE LA TABLA
  DECLARE p_clientes_sucursalesid bigint(20);
  DECLARE p_clientesid bigint(20) DEFAULT 1;
  DECLARE p_provinciasid varchar(4) DEFAULT '';
  DECLARE p_ciudadesid varchar(4) DEFAULT '';
  DECLARE p_parroquiasid varchar(6) DEFAULT '';
  DECLARE p_descripcion varchar(50) DEFAULT '';
  DECLARE p_direccion varchar(100) DEFAULT '';
  DECLARE p_telefono1 varchar(15) DEFAULT '';
  DECLARE p_telefono2 varchar(15) DEFAULT '';
  DECLARE p_cupocredito decimal(14,2) DEFAULT 0;
  DECLARE p_clave varchar(300) DEFAULT '';  
  DECLARE p_principal tinyint(4) DEFAULT 0;
  DECLARE p_estado tinyint(3) DEFAULT 1;
  DECLARE p_vendedoresid int(11) DEFAULT 1;  
  DECLARE p_fechacreacion datetime(3) DEFAULT '0000-00-00 00:00:00.000';
  DECLARE p_usuariocreacion varchar(25) DEFAULT '';
  DECLARE p_fechamodificacion datetime(3) DEFAULT '0000-00-00 00:00:00.000';
  DECLARE p_usuariomodificacion varchar(25) DEFAULT '';


  # VARIABLE DE LOS DATOS DE LA AUDITORIA
  DECLARE p_sis_subcategoriasid int(11) DEFAULT 0;
  DECLARE p_sis_empresasid int(11) DEFAULT 0;
  DECLARE p_sis_usuariosid varchar(20) DEFAULT '';
  DECLARE p_equipo varchar(50) DEFAULT '';
  DECLARE p_tipooperacion varchar(50) DEFAULT '';
  DECLARE p_detalle longtext;


  # CONTROLAMOS SI HAY ERROR
  DECLARE EXIT HANDLER FOR SQLEXCEPTION, SQLWARNING
  BEGIN
    GET DIAGNOSTICS CONDITION 1 vErrorMensaje = MESSAGE_TEXT;
  SELECT
      CASE WHEN LOCATE('Cannot delete or update a parent row',vErrorMensaje)>0 THEN JSON_ARRAYAGG(JSON_OBJECT('procesado', FALSE, 'mensaje', 'No Se Puede Eliminar, Sucursal en Uso')) ELSE JSON_ARRAYAGG(JSON_OBJECT('procesado', FALSE, 'mensaje', vErrorMensaje)) END AS resultado;
    ROLLBACK;
  END;
  # VALIDAMOS SI EL OBJETO JSON ES VALIDO 
  SET vJsonEsValido = JSON_VALID(pRegistrosJson);

  IF vJsonEsValido = 0 THEN
    # EL OBJETO JSON NO ES VALIDO
    SELECT
      JSON_ARRAYAGG(JSON_OBJECT('procesado', FALSE, 'mensaje', 'Json no es valido')) AS resultado;
  ELSE

    # VALIDAMOS QUE TENGA ALMENOS UN ELEMENTO
    SET vItems = JSON_LENGTH(pRegistrosJson, '$.cabecera');

    IF vItems > 0 THEN
      START TRANSACTION;
        WHILE vIndex < vItems DO

          # DATOS TABLA
          SET p_clientes_sucursalesid = IFNULL(JSON_UNQUOTE(JSON_EXTRACT(pRegistrosJson, CONCAT('$.cabecera[', vIndex, '].clientes_sucursalesid'))), p_clientes_sucursalesid);
          SET p_clientesid = IFNULL(JSON_UNQUOTE(JSON_EXTRACT(pRegistrosJson, CONCAT('$.cabecera[', vIndex, '].clientesid'))), p_clientesid);
          SET p_provinciasid = IFNULL(JSON_UNQUOTE(JSON_EXTRACT(pRegistrosJson, CONCAT('$.cabecera[', vIndex, '].provinciasid'))), p_provinciasid);
          SET p_ciudadesid = IFNULL(JSON_UNQUOTE(JSON_EXTRACT(pRegistrosJson, CONCAT('$.cabecera[', vIndex, '].ciudadesid'))), p_ciudadesid);
          SET p_parroquiasid = IFNULL(JSON_UNQUOTE(JSON_EXTRACT(pRegistrosJson, CONCAT('$.cabecera[', vIndex, '].parroquiasid'))), p_parroquiasid);
          SET p_descripcion = IFNULL(JSON_UNQUOTE(JSON_EXTRACT(pRegistrosJson, CONCAT('$.cabecera[', vIndex, '].descripcion'))), p_descripcion);
          SET p_direccion = IFNULL(JSON_UNQUOTE(JSON_EXTRACT(pRegistrosJson, CONCAT('$.cabecera[', vIndex, '].direccion'))), p_direccion);
          SET p_telefono1 = IFNULL(JSON_UNQUOTE(JSON_EXTRACT(pRegistrosJson, CONCAT('$.cabecera[', vIndex, '].telefono1'))), p_telefono1);
          SET p_telefono2 = IFNULL(JSON_UNQUOTE(JSON_EXTRACT(pRegistrosJson, CONCAT('$.cabecera[', vIndex, '].telefono2'))), p_telefono2);
          SET p_cupocredito = IFNULL(JSON_UNQUOTE(JSON_EXTRACT(pRegistrosJson, CONCAT('$.cabecera[', vIndex, '].cupocredito'))), p_cupocredito);
          SET p_clave = IFNULL(JSON_UNQUOTE(JSON_EXTRACT(pRegistrosJson, CONCAT('$.cabecera[', vIndex, '].clave'))), p_clave);                    
          SET p_principal = IFNULL(JSON_UNQUOTE(JSON_EXTRACT(pRegistrosJson, CONCAT('$.cabecera[', vIndex, '].principal'))), p_principal);
          SET p_estado = IFNULL(JSON_UNQUOTE(JSON_EXTRACT(pRegistrosJson, CONCAT('$.cabecera[', vIndex, '].estado'))), p_estado);
  SET p_vendedoresid = IFNULL(JSON_UNQUOTE(JSON_EXTRACT(pRegistrosJson, CONCAT('$.cabecera[', vIndex, '].vendedoresid'))), p_vendedoresid);          


          # DATOS AUDITORIA
          SET p_sis_subcategoriasid = JSON_UNQUOTE(JSON_EXTRACT(pRegistrosJson, CONCAT('$.cabecera[', vIndex, '].sis_subcategoriasid')));
          SET p_sis_empresasid = JSON_UNQUOTE(JSON_EXTRACT(pRegistrosJson, CONCAT('$.cabecera[', vIndex, '].sis_empresasid')));
          SET p_sis_usuariosid = JSON_UNQUOTE(JSON_EXTRACT(pRegistrosJson, CONCAT('$.cabecera[', vIndex, '].sis_usuariosid')));
          SET p_equipo = JSON_UNQUOTE(JSON_EXTRACT(pRegistrosJson, CONCAT('$.cabecera[', vIndex, '].equipo')));


          CASE pAccion
            WHEN 'C' THEN SET p_tipooperacion = 'N';
                SET p_fechacreacion = NOW(3);
                SET p_usuariocreacion = JSON_UNQUOTE(JSON_EXTRACT(pRegistrosJson, CONCAT('$.cabecera[', vIndex, '].usuariocreacion')));
                SET p_fechamodificacion = NULL;
                SET p_usuariomodificacion = '';
                SET p_detalle = REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(JSON_INSERT('{}', '$.clientes_sucursales', JSON_EXTRACT(pRegistrosJson, CONCAT('$.cabecera[', vIndex, ']'))), '"[', '['), ']"', ']'), '\\', ''), '"{', '{'), '}"', '}');

                # INSERTAMOS LOS REGISTROS
                INSERT INTO clientes_sucursales (clientes_sucursalesid, clientesid, provinciasid, ciudadesid, descripcion, direccion, telefono1, telefono2,cupocredito, clave, principal, estado, vendedoresid, fechacreacion, usuariocreacion, fechamodificacion, usuariomodificacion, parroquiasid)
                  VALUES (p_clientes_sucursalesid, p_clientesid, p_provinciasid, p_ciudadesid, p_descripcion, p_direccion, p_telefono1, p_telefono2,p_cupocredito, p_clave, p_principal, p_estado, p_vendedoresid, p_fechacreacion, p_usuariocreacion, p_fechamodificacion, p_usuariomodificacion, p_parroquiasid);

                SET p_clientes_sucursalesid = LAST_INSERT_ID();

            WHEN 'M' THEN SET p_tipooperacion = 'M';
                SET p_fechamodificacion = NOW(3);
                SET p_usuariomodificacion = JSON_UNQUOTE(JSON_EXTRACT(pRegistrosJson, CONCAT('$.cabecera[', vIndex, '].usuariomodificacion')));


                SET vRegistroAnterior = (SELECT
                    JSON_OBJECT
                    (
                    'clientes_sucursalesid', clientes_sucursalesid,
                    'clientesid', clientesid,
                    'provinciasid', provinciasid,
                    'ciudadesid', ciudadesid,
                    'descripcion', descripcion,
                    'direccion', direccion,
                    'telefono1', telefono1,
                    'telefono2', telefono2,
                    'cupocredito', cupocredito,
                    'clave', clave,
                    'principal', principal,
                    'estado', estado,
'vendedoresid', vendedoresid,                    
                    'fechamodificacion', fechamodificacion,
                    'usuariomodificacion', usuariomodificacion,
'parroquiasid', parroquiasid                    
                    )
                  FROM clientes_sucursales
                  WHERE clientes_sucursales.clientes_sucursalesid = p_clientes_sucursalesid);

                SET p_detalle = REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(JSON_INSERT('{}', '$.clientes_sucursales', vRegistroAnterior), '"[', '['), ']"', ']'), '\\', ''), '"{', '{'), '}"', '}');

                # ACTUALIZAMOS LOS REGISTROS
                UPDATE clientes_sucursales
                SET clientes_sucursalesid = p_clientes_sucursalesid,
                    clientesid = p_clientesid,
                    provinciasid = p_provinciasid,
                    ciudadesid = p_ciudadesid,
                    descripcion = p_descripcion,
                    direccion = p_direccion,
                    telefono1 = p_telefono1,
                    telefono2 = p_telefono2,
                    cupocredito = p_cupocredito,
                    clave = p_clave,
                    principal = p_principal,
                    estado = p_estado,
                    vendedoresid = p_vendedoresid,                    
                    fechamodificacion = p_fechamodificacion,
                    usuariomodificacion = p_usuariomodificacion,
parroquiasid = p_parroquiasid                    
                WHERE clientes_sucursalesid = p_clientes_sucursalesid;

            WHEN 'E' THEN SET p_tipooperacion = 'E';
                SET p_detalle = REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(JSON_INSERT('{}', '$.clientes_sucursales', JSON_EXTRACT(pRegistrosJson, CONCAT('$.cabecera[', vIndex, ']'))), '"[', '['), ']"', ']'), '\\', ''), '"{', '{'), '}"', '}');

SET @p_docid = (
SELECT DISTINCT	COUNT(facturasid) as facturasid
FROM	facturas	
WHERE	facturas.clientes_sucursalesid = p_clientes_sucursalesid);


SET @p_docpedidosid = (
SELECT DISTINCT	COUNT(pedidosid) as pedidosid
FROM	pedidos	
WHERE	pedidos.clientes_sucursalesid = p_clientes_sucursalesid);


IF @p_docid > 0 OR @p_docpedidosid > 0 THEN
SELECT
JSON_ARRAYAGG(JSON_OBJECT('procesado', FALSE, 'mensaje', 'La sucursal ya tiene documentos asociados')) AS resultado;
LEAVE clientes_sucursales;
ELSE	
                # ELIMINAMOS LOS REGISTROS
                DELETE
                  FROM clientes_sucursales
                WHERE clientes_sucursalesid = p_clientes_sucursalesid;
END IF;
          END CASE;

          # INSERTAMOS LA AUDITORIA
          CALL sistemaperseo.SP_ABC_sis_log_sistema(p_sis_subcategoriasid, p_sis_empresasid, p_sis_usuariosid, p_tipooperacion, p_detalle, p_equipo);

          SET vIndex = vIndex + 1;
        END WHILE;
      COMMIT;


      # RETORNAMOS LA RESPUESTAS
      IF pAccion IN ('C', 'M') THEN

        SELECT
          clientes_sucursales.clientes_sucursalesid,
          clientes_sucursales.clientesid,
          clientes_sucursales.provinciasid,
          clientes_sucursales.ciudadesid,
          clientes_sucursales.descripcion,
          clientes_sucursales.direccion,
          clientes_sucursales.telefono1,
          clientes_sucursales.telefono2,
          clientes_sucursales.cupocredito,
          clientes_sucursales.clave,
          clientes_sucursales.principal,
          clientes_sucursales.estado,
          clientes_sucursales.vendedoresid,     
          clientes_sucursales.parroquiasid,     
          clientes_sucursales.fechacreacion,
          clientes_sucursales.usuariocreacion,
          clientes_sucursales.fechamodificacion,
          clientes_sucursales.usuariomodificacion,
          (SELECT
              JSON_ARRAYAGG(JSON_OBJECT('procesado', TRUE, 'mensaje', 'Completado con Éxito'))) AS resultado
        FROM clientes_sucursales
        WHERE clientes_sucursales.clientes_sucursalesid = p_clientes_sucursalesid;

      ELSE
        SELECT
          JSON_ARRAYAGG(JSON_OBJECT('procesado', TRUE, 'mensaje', 'Completado con Éxito')) AS resultado;
      END IF;
    END IF;
  END IF;
END
;;
delimiter ;

