    clientes_zonas.usuariomodificacion,
    clientes_zonas.fechamodificacion
  FROM clientes_zonas
  WHERE clientes_zonas.clientes_zonasid = p_clientes_zonasid;


END
;;
delimiter ;

-- ----------------------------
-- Procedure structure for SP_Comparativo
-- ----------------------------
DROP PROCEDURE IF EXISTS `SP_Comparativo`;
delimiter ;;
CREATE PROCEDURE `SP_Comparativo`(IN sCaso VARCHAR(25), IN sCuentaContable VARCHAR(25) , IN dFechaDesde DATE, IN dFechaHasta DATE)
  SQL SECURITY INVOKER
BEGIN

CASE sCaso
-- ---------------------------------------------------------------------------------------------------------------
--  Caja
-- ---------------------------------------------------------------------------------------------------------------
WHEN "CAJA" THEN
IF sCuentaContable = "" THEN

-- trae todo lo que está en movcaja que no está en librodiario, es decir que no constan con asientos contables
SELECT
movcaja.fechamovimiento AS Fecha,
cajas.codigocontable AS codigocontable,
movcaja.asientocontable AS libros_diariosid,
movcaja.centros_costosid AS CentroCostoID,
(CASE WHEN movcaja.documentosid = 0 THEN movcaja.movcajasid ELSE movcaja.documentosid END) AS ModuloID,
movcaja.documentoorigen AS Documento,
movcaja.concepto AS concepto,
movcaja.origen AS origen,
movcaja.importe AS importemodulo,
0 AS Importecontabilidad,
'' AS codigoasiento
FROM
cajas
INNER JOIN
(movcaja
) ON movcaja.cajasid = cajas.cajasid
WHERE
movcaja.fechamovimiento BETWEEN dFechaDesde AND dFechaHasta
AND movcaja.asientocontable = 0;
ELSE
/*esta primera parte trae todo lo que haya en libro diario referente a la cuenta seleccionada en el periodo seleccionado */
/*************************************************************************************************************/
/*ESTA EN CONTABILIDAD Y EN MODULO*/
SELECT 
movcaja.fechamovimiento AS Fecha,
libros_diarios_detalles.codigocontable AS codigocontable,
libros_diarios_detalles.libros_diariosid AS libros_diariosid, 
libros_diarios_detalles.centros_costosid AS CentroCostoID,
(CASE WHEN movcaja.documentosid = 0 THEN movcaja.movcajasid ELSE movcaja.documentosid END) AS ModuloID,
movcaja.documentoorigen AS documento,
libros_diarios_detalles.concepto AS concepto,
libros_diarios.origen AS origen,
(	SELECT 
SUM(IFNULL(movc.importe,0)) AS importemodulo
FROM  movcaja as movc
WHERE
movc.asientocontable= movcaja.asientocontable
) AS importemodulo,

(	SELECT
SUM(IFNULL(libros_diarios_detalles.importe,0)) AS Importecontabilidad
FROM libros_diarios_detalles , libros_diarios AS lib
WHERE 
libros_diarios_detalles.libros_diariosid=lib.libros_diariosid
AND libros_diarios_detalles.codigocontable = sCuentaContable
AND lib.fecha BETWEEN dFechaDesde AND dFechaHasta
AND lib.libros_diariosid =libros_diarios.libros_diariosid
) AS Importecontabilidad,
libros_diarios.codigoasiento AS codigoasiento
FROM 
libros_diarios_detalles , libros_diarios ,  movcaja 
WHERE libros_diarios_detalles.libros_diariosid=libros_diarios.libros_diariosid
AND libros_diarios.libros_diariosid=movcaja.asientocontable
AND libros_diarios_detalles.codigocontable = sCuentaContable
AND movcaja.fechamovimiento BETWEEN dFechaDesde AND dFechaHasta
AND libros_diarios.anulado = 0
and libros_diarios.mayorizado = 1
group by
libros_diarios_detalles.libros_diariosID
UNION ALL
/*************************************************************************************************************/
/*trae todo lo que está en movcaja que no está en librodiario, es decir que no constan con asientos contables*/
/*NO CONTABILIDAD Y EN MODULO*/
SELECT
movcaja.fechamovimiento AS Fecha,
cajas.codigocontable AS codigocontable,
movcaja.asientocontable AS asientocontable,
movcaja.centros_costosid AS CentroCostoID,
(CASE WHEN movcaja.documentosid = 0 THEN movcaja.movcajasid ELSE movcaja.documentosid END) AS ModuloID,
movcaja.documentoorigen AS Documento,
movcaja.concepto AS concepto,
movcaja.origen AS origen,
SUM(IFNULL(movcaja.importe,0)) AS importemodulo,
0 AS Importecontabilidad,
IFNULL(libros_diarios.codigoasiento,'') AS CodigoAsiento
FROM
cajas
INNER JOIN
(movcaja
LEFT JOIN
(libros_diarios
) ON movcaja.asientocontable = libros_diarios.libros_diariosid
) ON movcaja.cajasid = cajas.cajasid
WHERE
cajas.codigocontable = sCuentaContable
AND movcaja.fechamovimiento BETWEEN dFechaDesde AND dFechaHasta
AND (libros_diarios.libros_diariosid IS NULL 
OR libros_diarios.mayorizado = 0)
GROUP BY movcaja.documentosid
union all
/*************************************************************************************************************/	
/*En CONTABILIDAD EN EL MODULO PERO ELIMINADO EL MOVCAJA */
SELECT 
libros_diarios.fecha AS Fecha,
libros_diarios_detalles.codigocontable AS codigocontable,
libros_diarios_detalles.libros_diariosid AS libros_diariosid, 
libros_diarios_detalles.centros_costosid AS CentroCostoID,
IFNULL((CASE WHEN movcaja.documentosid = 0 THEN movcaja.movcajasid ELSE movcaja.documentosid END),0) AS ModuloID,
libros_diarios_detalles.referencia AS documento,
libros_diarios_detalles.concepto AS concepto,
libros_diarios.origen AS origen,
(	SELECT 
SUM(IFNULL(movc.importe,0)) AS importemodulo
FROM  movcaja as movc
WHERE
movc.asientocontable= movcaja.asientocontable
) AS importemodulo,

(	SELECT
SUM(IFNULL(libros_diarios_detalles.importe,0)) AS Importecontabilidad
FROM libros_diarios_detalles , libros_diarios AS lib
WHERE 
libros_diarios_detalles.libros_diariosid=lib.libros_diariosid
AND libros_diarios_detalles.codigocontable = sCuentaContable
AND lib.fecha BETWEEN dFechaDesde AND dFechaHasta
AND lib.libros_diariosid =libros_diarios.libros_diariosid
) AS Importecontabilidad,

libros_diarios.codigoasiento AS codigoasiento
FROM 
movcaja 
RIGHT JOIN (libros_diarios INNER JOIN libros_diarios_detalles on libros_diarios_detalles.libros_diariosid=libros_diarios.libros_diariosid ) on libros_diarios.libros_diariosid=movcaja.asientocontable 
AND movcaja.fechamovimiento BETWEEN dFechaDesde AND dFechaHasta
WHERE 
libros_diarios_detalles.codigocontable = sCuentaContable
AND libros_diarios.anulado = 0
AND libros_diarios.mayorizado = 1
AND libros_diarios.origen IN ('Caja', 'Contabilidad')
group by
libros_diarios_detalles.libros_diariosID
HAVING importemodulo is NULL AND Importecontabilidad > 0
ORDER BY Fecha;

/*************************************************************************************************************/	
/* 
en caso de haber asiento y no cuenta
union all
select 
libros_diarios.Fecha AS Fecha,
'%1' AS codigocontable,
libros_diarios.libros_diariosid AS libros_diariosid, 
movcaja.centros_costosid AS CentroCostoID,
(case when movcaja.origen <> 'Caja' then (case when movcaja.origen = 'Depositos' then movcaja.depositosid ELSE movcaja.documentosid end) else movcaja.movcajasid end)  AS ModuloID,
movcaja.documentoorigen AS Documento,
movcaja.concepto AS concepto,
libros_diarios.origen AS origen,
0 AS importemodulo,
(select sum(ld.importe) as total  from libros_diarios_detalles ld WHERE ld.libros_diariosid = libros_diarios.libros_diariosid and ld.codigocontable = '%1' ) AS Importecontabilidad,
libros_diarios.codigoasiento AS codigoasiento
FROM
movcaja
INNER JOIN libros_diarios on movcaja.asientocontable = libros_diarios.libros_diariosid
WHERE
movcaja.cajasid not in (select cajas.cajasid from cajas where cajas.codigocontable = '%1')
and libros_diarios.libros_diariosid in (select DISTINCT ldd.libros_diariosid from libros_diarios_detalles ldd 
where ldd.codigocontable = '%1' )
AND libros_diarios.anulado = 0
and libros_diarios.Fecha BETWEEN  '%2' AND '%3'
*/
/* los asientos del banco sin cuenta correcta
union all
SELECT 
libros_diarios.Fecha AS Fecha,
'%1' AS codigocontable,
libros_diarios_detalles.libros_diariosid AS libros_diariosid, 
libros_diarios_detalles.centros_costosid AS CentroCostoID,
IFNULL(CASE WHEN movbanco.origen = 'Bancos' THEN movbanco.movbancosid ELSE movbanco.documentosid END,0) AS ModuloID,
movbanco.documentoorigen AS documento,
libros_diarios_detalles.concepto AS concepto,
libros_diarios.origen AS origen,
IFNULL(movbanco.importe,0) AS importemodulo,
(0) AS Importecontabilidad,
libros_diarios.codigoasiento AS codigoasiento
FROM 
libros_diarios_detalles
INNER JOIN
(libros_diarios
INNER JOIN
movbanco
ON libros_diarios.libros_diariosid=movbanco.asientocontable 
)
ON libros_diarios_detalles.libros_diariosid=libros_diarios.libros_diariosid
WHERE 
libros_diarios.Fecha BETWEEN '%2' AND '%3'
AND libros_diarios.anulado = 0
AND libros_diarios.libros_diariosid NOT IN (
SELECT DISTINCT det.libros_diariosid 
FROM libros_diarios_detalles det  WHERE det.codigocontable = '%1'
)	
AND movbanco.bancosid  in (select bancos.bancosid from bancos where bancos.codigocontable = '%1')	
group by 
libros_diarios.libros_diariosid
HAVING
libros_diarios.fecha IS NOT NULL
*/
/* 
 asientos con cuenta incorrecta
union all
SELECT 
libros_diarios.Fecha AS Fecha,
'%1' AS codigocontable,
libros_diarios_detalles.libros_diariosid AS libros_diariosid, 
libros_diarios_detalles.centros_costosid AS CentroCostoID,
IFNULL(CASE WHEN movcaja.origen = 'Cajas' THEN movcaja.movcajasid ELSE movcaja.documentosid END,0) AS ModuloID,
movcaja.documentoorigen AS documento,
libros_diarios_detalles.concepto AS concepto,
libros_diarios.origen AS origen,
IFNULL(movcaja.importe,0) AS importemodulo,
(0) AS Importecontabilidad,
libros_diarios.codigoasiento AS codigoasiento
FROM 
libros_diarios_detalles
INNER JOIN
(libros_diarios
INNER JOIN
movcaja
ON libros_diarios.libros_diariosid=movcaja.asientocontable 
)
ON libros_diarios_detalles.libros_diariosid=libros_diarios.libros_diariosid
WHERE 
libros_diarios.Fecha BETWEEN '%2' AND '%3'
AND libros_diarios.anulado = 0
AND libros_diarios.libros_diariosid NOT IN (
SELECT DISTINCT det.libros_diariosid 
FROM libros_diarios_detalles det  WHERE det.codigocontable = '%1'
)	
AND movcaja.cajasid  in (select cajas.cajasid from cajas where cajas.codigocontable = '%1')	
group by 
libros_diarios.libros_diariosid
HAVING
libros_diarios.fecha IS NOT NULL
*/


END IF;
-- ---------------------------------------------------------------------------------------------------------------
--  Bancos
-- ---------------------------------------------------------------------------------------------------------------
WHEN "BANCOS" THEN
IF sCuentaContable = "" THEN
/*trae todos los movimientos de la cuenta en movbanco que no han sido contabilizados */
SELECT
movbanco.fechamovimiento AS Fecha,
bancos.codigocontable AS codigocontable,
movbanco.asientocontable AS libros_diariosid,
movbanco.centros_costosid AS CentroCostoID,
(CASE WHEN movbanco.origen = 'Bancos' THEN movbanco.movbancosid ELSE (case when movbanco.origen = 'Bancos'then movbanco.movbancosid else  movbanco.documentosid end) END ) AS ModuloID,
movbanco.documentoorigen AS Documento,
movbanco.concepto AS concepto,
movbanco.origen AS origen,
movbanco.importe AS importemodulo,
0 AS Importecontabilidad,
'' AS codigoasiento
FROM
bancos
INNER JOIN
(movbanco
) ON movbanco.bancosid=bancos.bancosid
WHERE
movbanco.fechamovimiento BETWEEN dFechaDesde AND dFechaHasta
AND movbanco.asientocontable = 0;

ELSE
/***********************************************************************************************/
/*trae los movimientos contables de la cuenta seleccionada en el periodo seleccionado */
/*EN CONTABILIDAD Y EN MODULO*/
SELECT 
movbanco.fechamovimiento AS Fecha,
libros_diarios_detalles.codigocontable AS codigocontable,
libros_diarios_detalles.libros_diariosid AS libros_diariosid, 
libros_diarios_detalles.centros_costosid AS CentroCostoID,
(CASE WHEN movbanco.origen = 'Bancos' THEN movbanco.movbancosid ELSE movbanco.documentosid END ) AS ModuloID,
movbanco.documentoorigen AS Documento,
libros_diarios_detalles.concepto AS concepto,
libros_diarios.origen AS origen,

(	SELECT 
SUM(IFNULL(movb.importe,0)) AS importemodulo
FROM  movbanco as movb
WHERE
movb.asientocontable= movbanco.asientocontable
) AS importemodulo,

(	SELECT
SUM(IFNULL(libros_diarios_detalles.importe,0)) AS Importecontabilidad
FROM libros_diarios_detalles , libros_diarios AS lib
WHERE 
libros_diarios_detalles.libros_diariosid=lib.libros_diariosid
AND libros_diarios_detalles.codigocontable = sCuentaContable
AND lib.fecha BETWEEN dFechaDesde AND dFechaHasta
AND lib.libros_diariosid =libros_diarios.libros_diariosid
) AS Importecontabilidad,

libros_diarios.codigoasiento AS codigoasiento
FROM 	libros_diarios_detalles , libros_diarios, movbanco
WHERE 
libros_diarios_detalles.libros_diariosid=libros_diarios.libros_diariosid
AND libros_diarios.libros_diariosid=movbanco.asientocontable
AND libros_diarios_detalles.codigocontable = sCuentaContable
AND movbanco.fechamovimiento BETWEEN dFechaDesde AND dFechaHasta
AND libros_diarios.anulado = 0	
and libros_diarios.mayorizado = 1
group by
libros_diarios_detalles.libros_diariosid
UNION ALL

/******************************************************************************************/
/*EN CONTABILIDAD Y NO MODULO*/
SELECT 
libros_diarios.fecha AS Fecha,
libros_diarios_detalles.codigocontable AS codigocontable,
libros_diarios_detalles.libros_diariosid AS libros_diariosid, 
libros_diarios_detalles.centros_costosid AS CentroCostoID,
IFNULL((CASE WHEN movbanco.documentosid = 0 THEN movbanco.movbancosid ELSE movbanco.documentosid END),0) AS ModuloID,
libros_diarios_detalles.referencia AS documento,
libros_diarios.concepto AS concepto,
libros_diarios.origen AS origen,
(	SELECT 
SUM(IFNULL(movb.importe,0)) AS importemodulo
FROM  movbanco as movb
WHERE
movb.asientocontable= movbanco.asientocontable
) AS importemodulo,

(	SELECT
SUM(IFNULL(libros_diarios_detalles.importe,0)) AS Importecontabilidad
FROM libros_diarios_detalles , libros_diarios AS lib
WHERE 
libros_diarios_detalles.libros_diariosid=lib.libros_diariosid
AND libros_diarios_detalles.codigocontable = sCuentaContable
AND lib.fecha BETWEEN dFechaDesde AND dFechaHasta
AND lib.libros_diariosid =libros_diarios.libros_diariosid
) AS Importecontabilidad,

libros_diarios.codigoasiento AS codigoasiento
FROM 
movbanco 
RIGHT JOIN (libros_diarios INNER JOIN libros_diarios_detalles on libros_diarios_detalles.libros_diariosid=libros_diarios.libros_diariosid 
and libros_diarios.fecha BETWEEN  dFechaDesde AND dFechaHasta ) on libros_diarios.libros_diariosid=movbanco.asientocontable 
AND movbanco.fechamovimiento BETWEEN dFechaDesde AND dFechaHasta
WHERE 
libros_diarios_detalles.codigocontable = sCuentaContable
AND libros_diarios.origen IN ('Contabilidad', 'Bancos')
AND libros_diarios.anulado = 0
AND libros_diarios.mayorizado = 1
group by
libros_diarios_detalles.libros_diariosID
HAVING importemodulo is NULL  AND Importecontabilidad > 0
UNION ALL

/******************************************************************************************/
/*trae todos los movimientos de la cuenta en movbanco que no han sido contabilizados */
/* NO CONTABILIDAD Y EN MODULO*/ 
SELECT
movbanco.fechamovimiento AS Fecha,
bancos.codigocontable AS codigocontable,
movbanco.asientocontable AS asientocontable,
movbanco.centros_costosid AS CentroCostoID,
(CASE WHEN movbanco.documentosid = 0 THEN movbanco.movbancosid ELSE movbanco.documentosid END ) AS ModuloID,
movbanco.documentoorigen AS Documento,
movbanco.concepto AS concepto,
movbanco.origen AS origen,
movbanco.importe AS importemodulo,
0 AS Importecontabilidad,
IFNULL(libros_diarios.codigoasiento,'') AS codigoasiento
FROM
bancos
INNER JOIN
(movbanco
LEFT JOIN
(libros_diarios
) ON movbanco.asientocontable=libros_diarios.libros_diariosid
) ON movbanco.bancosid=bancos.bancosid
WHERE
bancos.codigocontable = sCuentaContable
AND movbanco.fechamovimiento BETWEEN dFechaDesde AND dFechaHasta
AND (libros_diarios.libros_diariosid IS NULL 
OR libros_diarios.mayorizado = 0)
ORDER BY Fecha;


/***********************************************************************************************/
/**
trae los asientos con la cuenta que no corresponde al banco del movimiento
UNION ALL

select 
libros_diarios.Fecha AS Fecha,
'%1' AS codigocontable,
libros_diarios.libros_diariosid AS libros_diariosid, 
movbanco.centros_costosid AS CentroCostoID,
(case when movbanco.origen <> 'Bancos' then movbanco.documentosid else movbanco.movbancosid end)  AS ModuloID,
movbanco.comprobante AS Documento,
movbanco.concepto AS concepto,
libros_diarios.origen AS origen,
0 AS importemodulo,
(select sum(ld.importe) as total  from libros_diarios_detalles ld WHERE ld.libros_diariosid = libros_diarios.libros_diariosid and ld.codigocontable = '%1' ) AS Importecontabilidad,
libros_diarios.codigoasiento AS codigoasiento
FROM
movbanco
INNER JOIN libros_diarios on movbanco.asientocontable = libros_diarios.libros_diariosid
WHERE
movbanco.bancosid not in (select bancos.bancosid from bancos where bancos.codigocontable = '%1')
and libros_diarios.libros_diariosid in (select DISTINCT ldd.libros_diariosid from libros_diarios_detalles ldd 
where ldd.codigocontable = '%1' )
AND libros_diarios.anulado = 0
and libros_diarios.Fecha BETWEEN  '%2' AND '%3'
*/
/*
traen los asientos del banco sin cuenta correcta
union all
SELECT 
libros_diarios.Fecha AS Fecha,
'%1' AS codigocontable,
libros_diarios_detalles.libros_diariosid AS libros_diariosid, 
libros_diarios_detalles.centros_costosid AS CentroCostoID,
IFNULL(CASE WHEN movbanco.origen = 'Bancos' THEN movbanco.movbancosid ELSE movbanco.documentosid END,0) AS ModuloID,
movbanco.documentoorigen AS documento,
libros_diarios_detalles.concepto AS concepto,
libros_diarios.origen AS origen,
IFNULL(movbanco.importe,0) AS importemodulo,
(0) AS Importecontabilidad,
libros_diarios.codigoasiento AS codigoasiento
FROM 
libros_diarios_detalles
INNER JOIN
(libros_diarios
INNER JOIN
movbanco
ON libros_diarios.libros_diariosid=movbanco.asientocontable 
)
ON libros_diarios_detalles.libros_diariosid=libros_diarios.libros_diariosid
WHERE 
libros_diarios.Fecha BETWEEN '%2' AND '%3'
AND libros_diarios.anulado = 0
AND libros_diarios.libros_diariosid NOT IN (
SELECT DISTINCT det.libros_diariosid 
FROM libros_diarios_detalles det  WHERE det.codigocontable = '%1'
)	
AND movbanco.bancosid  in (select bancos.bancosid from bancos where bancos.codigocontable = '%1')	
group by 
libros_diarios.libros_diariosid
HAVING
libros_diarios.fecha IS NOT NULL
*/
END IF;
-- ---------------------------------------------------------------------------------------------------------------
--  Facturación
-- ---------------------------------------------------------------------------------------------------------------
WHEN "FACTURACION" THEN
IF sCuentaContable = "" THEN
SELECT
facturas.emision AS Fecha,
productos.cuentacontable_ventas AS codigocontable,
facturas.asientocontable AS libros_diariosid,
facturas_detalles.centros_costosid AS CentroCostoID,
facturas.facturasid AS ModuloID,
facturas.secuencial AS Documento,
facturas.concepto AS concepto,
'Facturación' AS origen,
SUM(IFNULL(CASE WHEN facturas.sri_documentoscodigo='04' THEN (ROUND(facturas_detalles.cantidad*facturas_detalles.precio,5)-ROUND(facturas_detalles.cantidad*facturas_detalles.precio*facturas_detalles.descuento/100,5)) ELSE -(ROUND(facturas_detalles.cantidad*facturas_detalles.precio,5)-ROUND(facturas_detalles.cantidad*facturas_detalles.precio*facturas_detalles.descuento/100,5))  END,0)) AS importemodulo,
0 AS Importecontabilidad,
'' AS CodigoAsiento
FROM	
productos
INNER JOIN
(
facturas_detalles
INNER JOIN
(
facturas
)ON facturas_detalles.facturasid=facturas.facturasid
)ON productos.productosid=facturas_detalles.productosid
WHERE
facturas.asientocontable = 0 
AND DATE(facturas.emision) BETWEEN dFechaDesde AND dFechaHasta
AND facturas.anulado = 0
GROUP BY
facturas.facturasid;

ELSE
/*trae tosa las ventas de contabilidad aunque no consten en facturación*/
SELECT 
facturas.emision AS Fecha,
libros_diarios_detalles.codigocontable AS codigocontable,
libros_diarios_detalles.libros_diariosid AS libros_diariosid, 
libros_diarios_detalles.centros_costosid AS CentroCostoID,
facturas.facturasid AS ModuloID,
facturas.secuencial AS documento,
libros_diarios_detalles.concepto AS concepto,
libros_diarios.origen AS origen,

(
SELECT 
SUM((ROUND(det.cantidad*det.precio,5)-ROUND(det.cantidad*det.precio*det.descuento/100,5)) *(CASE WHEN fac.sri_documentoscodigo='04' THEN 1 ELSE -1 END ))  as n
FROM
facturas as fac, facturas_detalles as det 
WHERE
fac.facturasid=det.facturasid
AND fac.facturasid=facturas.facturasid
-- AND det.servicio=0
)  AS importemodulo,

(
SELECT
SUM(IFNULL(libdet.importe,0)) AS Importecontabilidad
FROM libros_diarios_detalles libdet, libros_diarios AS lib
WHERE
libdet.libros_diariosid=lib.libros_diariosid
AND libdet.codigocontable =  sCuentaContable
AND lib.fecha BETWEEN   dFechaDesde AND dFechaHasta
AND lib.libros_diariosid =libros_diarios.libros_diariosid
) AS Importecontabilidad,
libros_diarios.codigoasiento AS codigoasiento	
FROM 
libros_diarios_detalles 
INNER JOIN
(libros_diarios
LEFT OUTER JOIN
facturas
INNER JOIN 
(facturas_detalles
INNER JOIN
(productos
)ON (facturas_detalles.productosid=productos.productosid AND productos.cuentacontable_ventas=sCuentaContable)
)ON (facturas.facturasid=facturas_detalles.facturasid AND facturas.anulado = 0)
ON libros_diarios.libros_diariosid = facturas.asientocontable
)
ON libros_diarios_detalles.libros_diariosid = libros_diarios.libros_diariosid
WHERE 
libros_diarios_detalles.codigocontable = sCuentaContable
AND DATE(facturas.emision) BETWEEN   dFechaDesde AND dFechaHasta
AND libros_diarios.anulado = 0
and libros_diarios.mayorizado = 1
GROUP BY
libros_diarios.libros_diariosid
/*************************************************************************************/
UNION ALL
SELECT
facturas.emision AS Fecha,
productos.cuentacontable_ventas AS codigocontable,
facturas.asientocontable AS asientocontable,
facturas_detalles.centros_costosid AS CentroCostoID,
facturas.facturasid AS ModuloID,
facturas.secuencial AS Documento,
facturas.concepto AS concepto,
'Facturacion' AS origen,
SUM(IFNULL(CASE WHEN facturas.sri_documentoscodigo='04' THEN (ROUND(facturas_detalles.cantidad*facturas_detalles.precio,5)-ROUND(facturas_detalles.cantidad*facturas_detalles.precio*facturas_detalles.descuento/100,5)) ELSE -(ROUND(facturas_detalles.cantidad*facturas_detalles.precio,5)-ROUND(facturas_detalles.cantidad*facturas_detalles.precio*facturas_detalles.descuento/100,5))  END,0)) AS importemodulo,
0 AS Importecontabilidad,

IFNULL(libros_diarios.codigoasiento,'') AS CodigoAsiento
FROM	
productos
INNER JOIN
(
facturas_detalles
INNER JOIN
(
facturas
LEFT JOIN
(libros_diarios) ON (facturas.asientocontable=libros_diarios.libros_diariosid)
)ON facturas_detalles.facturasid=facturas.facturasid
)ON productos.productosid=facturas_detalles.productosid
WHERE
(libros_diarios.libros_diariosid IS NULL 
OR libros_diarios.mayorizado = 0)
AND productos.cuentacontable_ventas = sCuentaContable
AND DATE(facturas.emision) BETWEEN  dFechaDesde AND dFechaHasta
AND facturas.anulado = 0
GROUP BY
facturas.facturasid	

/*************************************************************************************/
/** ventas no contabilizadas **/
UNION ALL
SELECT 
libros_diarios.Fecha AS Fecha,
sCuentaContable AS codigocontable,
libros_diarios.libros_diariosid AS libros_diariosid, 
libros_diarios_detalles.centros_costosid AS CentroCostoID,
facturas.facturasid AS ModuloID,
facturas.secuencial AS documento,
libros_diarios_detalles.concepto AS concepto,
libros_diarios.origen AS origen,
SUM(IFNULL( (ROUND(facturas_detalles.cantidad*facturas_detalles.precio,5)-ROUND(facturas_detalles.cantidad*facturas_detalles.precio*facturas_detalles.descuento/100,5)) *(CASE WHEN facturas.sri_documentoscodigo='04' THEN 1 ELSE -1 END ),0)) AS importemodulo,
(0) AS Importecontabilidad,
libros_diarios.codigoasiento AS codigoasiento	
FROM 
libros_diarios_detalles 
INNER JOIN
(libros_diarios
INNER JOIN
(facturas
INNER JOIN 
(facturas_detalles
INNER JOIN
(productos
)ON (facturas_detalles.productosid=productos.productosid AND productos.cuentacontable_ventas= sCuentaContable)
)ON (facturas.facturasid=facturas_detalles.facturasid AND facturas.anulado = 0)
)ON libros_diarios.libros_diariosid = facturas.asientocontable
)	ON libros_diarios_detalles.libros_diariosid = libros_diarios.libros_diariosid
WHERE 
libros_diarios.Fecha BETWEEN  dFechaDesde AND dFechaHasta
AND libros_diarios.anulado = 0
AND libros_diarios.libros_diariosid NOT IN (
SELECT DISTINCT det.libros_diariosid 
FROM libros_diarios_detalles det  WHERE det.codigocontable = sCuentaContable
)
HAVING
libros_diarios.fecha is not null 
-- ---------------------------------------
-- contabilidad y no en modulo
-- -------------------------------------
UNION ALL
SELECT 
libros_diarios.fecha AS Fecha,
libros_diarios_detalles.codigocontable AS codigocontable,
libros_diarios_detalles.libros_diariosid AS libros_diariosid, 
libros_diarios_detalles.centros_costosid AS CentroCostoID,
0 AS ModuloID,
libros_diarios_detalles.referencia AS documento,
libros_diarios_detalles.concepto AS concepto,
libros_diarios.origen AS origen,
'0.00' AS importemodulo,

(	SELECT
SUM(IFNULL(libros_diarios_detalles.importe,0)) AS Importecontabilidad
FROM libros_diarios_detalles , libros_diarios AS lib
WHERE 
libros_diarios_detalles.libros_diariosid=lib.libros_diariosid
AND libros_diarios_detalles.codigocontable = sCuentaContable
AND lib.fecha  BETWEEN  dFechaDesde AND dFechaHasta
AND lib.libros_diariosid =libros_diarios.libros_diariosid
) AS Importecontabilidad,

libros_diarios.codigoasiento AS codigoasiento
FROM 
libros_diarios INNER JOIN libros_diarios_detalles on libros_diarios_detalles.libros_diariosid=libros_diarios.libros_diariosid 

WHERE 
libros_diarios_detalles.codigocontable = sCuentaContable
AND libros_diarios.anulado = 0
AND libros_diarios.fecha BETWEEN  dFechaDesde AND dFechaHasta
AND libros_diarios.mayorizado = 1
AND libros_diarios.libros_diariosid NOT IN (SELECT cxc.asientocontable FROM cuentasporcobrar cxc WHERE cxc.emision BETWEEN  dFechaDesde AND dFechaHasta) 
AND libros_diarios.origen IN ('Contabilidad','Facturacion')
group by
libros_diarios_detalles.libros_diariosID

HAVING  Importecontabilidad <> 0
ORDER BY Fecha;

END IF;
-- ---------------------------------------------------------------------------------------------------------------
--  Inventario
-- ---------------------------------------------------------------------------------------------------------------	
WHEN "INVENTARIO" THEN
IF sCuentaContable = "" THEN
SELECT
compras.emision AS Fecha,
productos.cuentacontable_inventarios AS codigocontable,
compras.asientocontable AS libros_diariosid,
compras_detalles.centros_costosid AS CentroCostoID,
compras.comprasid AS ModuloID,
compras.secuencia AS Documento,
compras.concepto AS concepto,
'Compras' AS origen,
SUM(IFNULL(CASE WHEN compras.sri_documentoscodigo<>'04' THEN compras_detalles.costoneto * compras_detalles.cantidaddigitada*compras_detalles.cantidadfactor ELSE -compras_detalles.costoneto * compras_detalles.cantidaddigitada*compras_detalles.cantidadfactor  END,0)) AS importemodulo,
0 AS Importecontabilidad,
'' AS codigoasiento
FROM
(	productos
INNER JOIN
(	compras_detalles
INNER JOIN
(	compras
)ON (compras_detalles.comprasid=compras.comprasid AND compras_detalles.movinventarios_tiposid<>2)
)ON (productos.productosid=compras_detalles.productosid AND productos.bien=0 AND productos.servicio=0)
)
WHERE
compras.asientocontable = 0
AND DATE(compras.emision) BETWEEN dFechaDesde AND dFechaHasta
GROUP BY
compras.comprasid
UNION ALL 
SELECT
ingresos.Fecha AS Fecha,
productos.cuentacontable_inventarios AS codigocontable,
ingresos.asientocontable AS libros_diariosid,
ingresos_detalles.centros_costosid AS CentroCostoID,
ingresos.ingresosid  AS ModuloID,
ingresos.ingresoscodigo AS Documento,
ingresos.concepto AS concepto,
'Ingresos' AS origen,
SUM(IFNULL(ingresos_detalles.costo*ingresos_detalles.cantidad,0)) AS importemodulo,
0 AS Importecontabilidad,
'' AS codigoasiento
FROM
(	productos
INNER JOIN
(	ingresos_detalles
INNER JOIN
(	ingresos
)ON ingresos_detalles.ingresosid=ingresos.ingresosid
)ON (productos.productosid=ingresos_detalles.productosid AND productos.bien=0 AND productos.servicio=0)
)
WHERE
ingresos.asientocontable = 0
AND DATE(ingresos.Fecha) BETWEEN dFechaDesde AND dFechaHasta
GROUP BY
ingresos.ingresosid
UNION ALL
SELECT 
facturas.emision AS Fecha,
productos.cuentacontable_inventarios AS codigocontable,
facturas.asientocosto AS libros_diariosid,
facturas_detalles.centros_costosid AS CentroCostoID,
facturas.facturasid AS ModuloID,
facturas.secuencial AS Documento,
facturas.concepto AS concepto,
'Costo de Venta' AS origen,
SUM(IFNULL(CASE WHEN facturas.sri_documentoscodigo='04' THEN facturas_detalles.costo*facturas_detalles.cantidad ELSE -facturas_detalles.costo*facturas_detalles.cantidad  END,0)) AS importemodulo,
0 AS Importecontabilidad,
'' AS codigoasiento
FROM

(	productos
INNER JOIN
(	facturas_detalles
INNER JOIN
(	facturas
)ON (facturas_detalles.facturasid=facturas.facturasid AND facturas.anulado=0)
)ON (productos.productosid=facturas_detalles.productosid AND productos.bien=0 AND productos.servicio=0)
)
WHERE
facturas.asientocosto = 0
AND DATE(facturas.emision) BETWEEN dFechaDesde AND dFechaHasta
GROUP BY
facturas.facturasid
UNION ALL
SELECT
salidas.Fecha AS Fecha,
productos.cuentacontable_inventarios AS codigocontable,
salidas.asientocontable AS libros_diariosid,
salidas_detalles.centros_costosid AS CentroCostoID,
salidas.salidasid AS ModuloID,
salidas.salidascodigo AS Documento,
salidas.concepto AS concepto,
'Salidas' AS origen,
SUM(IFNULL(salidas_detalles.costo*salidas_detalles.cantidad,0)) AS importemodulo,
0 AS Importecontabilidad,
'' AS codigoasiento
FROM
(	productos
INNER JOIN
(	salidas_detalles
INNER JOIN
(	salidas
)ON salidas_detalles.salidasid=salidas.salidasid
)ON (productos.productosid=salidas_detalles.productosid AND productos.bien=0 AND productos.servicio=0)
)
WHERE
salidas.asientocontable = 0
AND DATE(salidas.Fecha) BETWEEN dFechaDesde AND dFechaHasta
GROUP BY
salidas.salidasid;

ELSE
/*********************************************************************************************/
/*** EN CONTABILIDAD Y EN MODULO ***/
/** COMPRAS**/
SELECT 
libros_diarios.fecha AS Fecha,
libros_diarios_detalles.codigocontable AS codigocontable,
libros_diarios_detalles.libros_diariosid AS libros_diariosid, 
libros_diarios_detalles.centros_costosid AS CentroCostoID,
compras.comprasid AS ModuloID,
compras.secuencia AS documento,
libros_diarios_detalles.concepto AS concepto,
libros_diarios.origen AS origen,

(
SELECT 	
ROUND(SUM(IFNULL(CASE WHEN mov_inv.movinventarios_tiposid=1 THEN mov_inv.costo*mov_inv.cantidad ELSE -mov_inv.costo*mov_inv.cantidad END,0)),5) AS importemodulo 	
FROM 	
movinventarios as mov_inv , compras as comp
WHERE 	
 mov_inv.documentosid = comp.comprasid
AND comp.comprasid =compras.comprasid
AND mov_inv.movinventarios_tiposid in (1,2)
AND mov_inv.servicio =0
) as importemodulo,

(
SELECT
ROUND(SUM(det.importe),5) AS Importecontabilidad
FROM libros_diarios_detalles as det , libros_diarios  AS lib
WHERE 
det.libros_diariosid = lib.libros_diariosid
AND det.codigocontable = sCuentaContable
AND lib.fecha BETWEEN dFechaDesde AND dFechaHasta
and lib.libros_diariosid =libros_diarios.libros_diariosid
) AS Importecontabilidad,

libros_diarios.codigoasiento AS codigoasiento
FROM 	
libros_diarios_detalles , libros_diarios , compras , movinventarios
WHERE 
libros_diarios.origen='Compras'
AND libros_diarios_detalles.codigocontable = sCuentaContable
AND libros_diarios.fecha BETWEEN dFechaDesde AND dFechaHasta
AND libros_diarios.anulado = 0
AND libros_diarios.libros_diariosid = compras.asientocontable
AND libros_diarios_detalles.libros_diariosid = libros_diarios.libros_diariosid	
GROUP BY
libros_diarios_detalles.libros_diariosid

/*********************************************************************************************/	
/*** EN CONTABILIDAD Y EN MODULO ***/
/** INGRESOS**/
UNION ALL
SELECT 
ingresos.fecha AS Fecha,
libros_diarios_detalles.codigocontable AS codigocontable,
libros_diarios_detalles.libros_diariosid AS libros_diariosid, 
libros_diarios_detalles.centros_costosid AS CentroCostoID,
ingresos.ingresosid  AS ModuloID,
ingresos.ingresoscodigo AS Documento,
libros_diarios_detalles.concepto AS concepto,
libros_diarios.origen AS origen,

(
SELECT 	
ROUND(SUM(IFNULL(mov_inv.costo*mov_inv.cantidad ,0)),5) AS importemodulo 	
FROM 	movinventarios as mov_inv , ingresos as ingr
WHERE 	
 mov_inv.documentosid = ingr.ingresosid
AND ingr.ingresosid = ingresos.ingresosid 
AND mov_inv.movinventarios_tiposid=7	
) as importemodulo,

(
SELECT
ROUND(SUM(det.importe),5) AS Importecontabilidad
FROM libros_diarios_detalles as det , libros_diarios  AS lib
WHERE 
det.libros_diariosid = lib.libros_diariosid
AND det.codigocontable = sCuentaContable
AND lib.fecha BETWEEN dFechaDesde AND dFechaHasta
and lib.libros_diariosid =libros_diarios.libros_diariosid
) AS Importecontabilidad,

libros_diarios.codigoasiento AS codigoasiento
FROM 	
libros_diarios_detalles , libros_diarios , ingresos
WHERE 
libros_diarios.origen='Ingresos'
AND libros_diarios_detalles.codigocontable = sCuentaContable
AND DATE(ingresos.fecha) BETWEEN dFechaDesde AND dFechaHasta
AND libros_diarios.anulado = 0
AND libros_diarios.libros_diariosid = ingresos.asientocontable
AND libros_diarios_detalles.libros_diariosid = libros_diarios.libros_diariosid
GROUP BY
libros_diarios_detalles.libros_diariosid

/*********************************************************************************************/
/*** EN CONTABILIDAD Y EN MODULO ***/
/** SALIDAS**/	
UNION ALL
SELECT 
salidas.fecha AS Fecha,
libros_diarios_detalles.codigocontable AS codigocontable,
libros_diarios_detalles.libros_diariosid AS libros_diariosid, 
libros_diarios_detalles.centros_costosid AS CentroCostoID,
salidas.salidasid AS ModuloID,
salidas.salidascodigo AS Documento,
libros_diarios_detalles.concepto AS concepto,
libros_diarios.origen AS origen,

(
SELECT 	
ROUND(SUM(IFNULL(-mov_inv.costo*mov_inv.cantidad ,0)),5) AS importemodulo 	
FROM 	movinventarios as mov_inv , salidas as sal
WHERE 	
 mov_inv.documentosid = sal.salidasid
AND sal.salidasid = salidas.salidasid 	
AND mov_inv.movinventarios_tiposid=8
) as importemodulo,

(
SELECT
ROUND(SUM(det.importe),5) AS Importecontabilidad
FROM libros_diarios_detalles as det , libros_diarios  AS lib
WHERE 
det.libros_diariosid = lib.libros_diariosid
AND det.codigocontable = sCuentaContable
AND lib.fecha BETWEEN dFechaDesde AND dFechaHasta
and lib.libros_diariosid =libros_diarios.libros_diariosid
) AS Importecontabilidad,

libros_diarios.codigoasiento AS codigoasiento
FROM
libros_diarios_detalles,
libros_diarios,
salidas
WHERE 
libros_diarios.origen='SALIDAS'
AND libros_diarios_detalles.codigocontable = sCuentaContable
AND DATE(salidas.fecha) BETWEEN dFechaDesde AND dFechaHasta
AND libros_diarios.anulado = 0
AND libros_diarios.libros_diariosid = salidas.asientocontable
AND libros_diarios_detalles.libros_diariosid = libros_diarios.libros_diariosid	
GROUP BY libros_diarios_detalles.libros_diariosid

/*********************************************************************************************/	
/*** EN CONTABILIDAD Y EN MODULO ***/
/** Costo de venta**/
UNION ALL
SELECT 
facturas.emision AS Fecha,
libros_diarios_detalles.codigocontable AS codigocontable,
libros_diarios_detalles.libros_diariosid AS libros_diariosid, 
libros_diarios_detalles.centros_costosid AS CentroCostoID,
facturas.facturasid AS ModuloID,
facturas.secuencial AS Documento,
libros_diarios_detalles.concepto AS concepto,
libros_diarios.origen AS origen,

(
SELECT 	
ROUND(SUM(IFNULL(CASE WHEN mov_inv.movinventarios_tiposid=4 THEN mov_inv.costo*mov_inv.cantidad ELSE -mov_inv.costo*mov_inv.cantidad END,0)),5) AS importemodulo 	
FROM 	movinventarios as mov_inv , facturas as fact
WHERE 	
 mov_inv.documentosid = fact.facturasid
AND fact.facturasid =facturas.facturasid
AND mov_inv.movinventarios_tiposid IN (3,4)
) as importemodulo,

(
SELECT
ROUND(SUM(det.importe),5) AS Importecontabilidad
FROM libros_diarios_detalles as det , libros_diarios  AS lib
WHERE 
det.libros_diariosid = lib.libros_diariosid
AND det.codigocontable = sCuentaContable
AND lib.fecha BETWEEN dFechaDesde AND dFechaHasta
and lib.libros_diariosid =libros_diarios.libros_diariosid
) AS Importecontabilidad,

libros_diarios.codigoasiento AS codigoasiento
FROM 	
libros_diarios_detalles , libros_diarios , facturas

WHERE 
libros_diarios.origen='Costo de Venta'
AND libros_diarios_detalles.codigocontable = sCuentaContable
AND DATE(facturas.emision) BETWEEN dFechaDesde AND dFechaHasta
AND libros_diarios.anulado = 0
AND libros_diarios.libros_diariosid = facturas.asientocosto
AND libros_diarios_detalles.libros_diariosid = libros_diarios.libros_diariosid
GROUP BY
libros_diarios_detalles.libros_diariosid

/*********************************************************************************************/	
