/*********************************************************************************************/
/*** EN CONTABILIDAD Y NO MODULO ***/
/** COMPRAS**/
UNION ALL	
SELECT
compras.emision AS Fecha,
productos.cuentacontable_inventarios AS codigocontable,
compras.asientocontable AS asientocontable,
compras_detalles.centros_costosid AS CentroCostoID,
compras.comprasid AS ModuloID,
compras.secuencia AS Documento,
compras.concepto AS concepto,
'Compras' AS origen,
SUM(IFNULL(CASE WHEN compras.sri_documentoscodigo<>'04' THEN compras_detalles.costoneto * compras_detalles.cantidaddigitada*compras_detalles.cantidadfactor ELSE -compras_detalles.costoneto * compras_detalles.cantidaddigitada*compras_detalles.cantidadfactor  END,0)) AS importemodulo,
0 AS Importecontabilidad,
IFNULL(libros_diarios.codigoasiento,'') AS CodigoAsiento
FROM
(	productos
INNER JOIN
(	compras_detalles
INNER JOIN
(	compras
RIGHT JOIN
(libros_diarios) ON (compras.asientocontable=libros_diarios.libros_diariosid)
)ON (compras_detalles.comprasid=compras.comprasid AND compras_detalles.movinventarios_tiposid<>2)
)ON (productos.productosid=compras_detalles.productosid AND productos.bien=0 AND productos.servicio=0)
)
WHERE
(libros_diarios.libros_diariosid IS NULL or libros_diarios.mayorizado = 0)
AND productos.cuentacontable_inventarios = sCuentaContable
AND DATE(compras.emision) BETWEEN dFechaDesde AND dFechaHasta
GROUP BY
compras.comprasid

/*********************************************************************************************/
/*** EN CONTABILIDAD Y NO MODULO ***/
/** ingresos**/
UNION ALL 
SELECT
ingresos.Fecha AS Fecha,
productos.cuentacontable_inventarios AS codigocontable,
ingresos.asientocontable AS asientocontable,
ingresos_detalles.centros_costosid AS CentroCostoID,
ingresos.ingresosid  AS ModuloID,
ingresos.ingresoscodigo AS Documento,
ingresos.concepto AS concepto,
'Ingresos' AS origen,
SUM(IFNULL(ingresos_detalles.costo*ingresos_detalles.cantidad,0)) AS importemodulo,
0 AS Importecontabilidad,
IFNULL(libros_diarios.codigoasiento,'') AS asientocontable
FROM
(	productos
INNER JOIN
(	ingresos_detalles
INNER JOIN
(	ingresos
RIGHT JOIN
(libros_diarios) ON (ingresos.asientocontable=libros_diarios.libros_diariosid)
)ON ingresos_detalles.ingresosid=ingresos.ingresosid
)ON (productos.productosid=ingresos_detalles.productosid AND productos.bien=0 AND productos.servicio=0)
)
WHERE
(libros_diarios.libros_diariosid IS NULL or libros_diarios.mayorizado = 0)
AND productos.cuentacontable_inventarios = sCuentaContable
AND DATE(ingresos.Fecha) BETWEEN dFechaDesde AND dFechaHasta
GROUP BY
ingresos.ingresosid

/*********************************************************************************************/
/*** EN CONTABILIDAD Y NO MODULO ***/
/** costo de ventas**/
UNION ALL
SELECT 
facturas.emision AS Fecha,
productos.cuentacontable_inventarios AS codigocontable,
facturas.asientocosto AS asientocontable,
facturas_detalles.centros_costosid AS CentroCostoID,
facturas.facturasid AS ModuloID,
facturas.secuencial AS Documento,
facturas.concepto AS concepto,
'Costo de Venta' AS origen,
SUM(IFNULL(CASE WHEN facturas.sri_documentoscodigo='04' THEN facturas_detalles.costo*facturas_detalles.cantidad ELSE -facturas_detalles.costo*facturas_detalles.cantidad  END,0)) AS importemodulo,
0 AS Importecontabilidad,
IFNULL(libros_diarios.codigoasiento,'') AS CodigoAsiento
FROM

(	productos
INNER JOIN
(	facturas_detalles
INNER JOIN
(	facturas
RIGHT JOIN
(libros_diarios) ON (facturas.asientocosto=libros_diarios.libros_diariosid)
)ON (facturas_detalles.facturasid=facturas.facturasid AND facturas.anulado=0)
)ON (productos.productosid=facturas_detalles.productosid AND productos.bien=0 AND productos.servicio=0)
)
WHERE
 (libros_diarios.libros_diariosid IS NULL or libros_diarios.mayorizado = 0)
AND productos.cuentacontable_inventarios = sCuentaContable
AND DATE(facturas.emision) BETWEEN dFechaDesde AND dFechaHasta
GROUP BY
facturas.facturasid

/*********************************************************************************************/
/*** EN CONTABILIDAD Y NO MODULO ***/
/** salidas**/
UNION ALL
SELECT
salidas.Fecha AS Fecha,
productos.cuentacontable_inventarios AS codigocontable,
salidas.asientocontable AS asientocontable,
salidas_detalles.centros_costosid AS CentroCostoID,
salidas.salidasid AS ModuloID,
salidas.salidascodigo AS Documento,
salidas.concepto AS concepto,
'Salidas' AS origen,
SUM(IFNULL(salidas_detalles.costo*salidas_detalles.cantidad,0)) AS importemodulo,
0 AS Importecontabilidad,
IFNULL(libros_diarios.codigoasiento,'') AS CodigoAsiento
FROM
(	productos
INNER JOIN
(	salidas_detalles
INNER JOIN
(	salidas
RIGHT JOIN
(libros_diarios) ON (salidas.asientocontable=libros_diarios.libros_diariosid)
)ON salidas_detalles.salidasid=salidas.salidasid
)ON (productos.productosid=salidas_detalles.productosid AND productos.bien=0 AND productos.servicio=0)
)
WHERE
(libros_diarios.libros_diariosid IS NULL or libros_diarios.mayorizado = 0)
AND productos.cuentacontable_inventarios = sCuentaContable
AND DATE(salidas.Fecha) BETWEEN dFechaDesde AND dFechaHasta
GROUP BY
salidas.salidasid
ORDER BY Fecha;


END IF;
-- ---------------------------------------------------------------------------------------------------------------
--  Cuentas por Cobrar
-- ---------------------------------------------------------------------------------------------------------------
WHEN "CUENTAS POR COBRAR" THEN
IF sCuentaContable = "" THEN
SELECT
facturas.emision AS Fecha,
clientes.codigocontable AS codigocontable,
facturas.asientocontable AS libros_diariosid,
facturas.centros_costosid AS centros_costosid,
facturas.facturasid AS ModuloID,

facturas.secuencial AS Documento,
facturas.concepto AS concepto,
'Facturacion' AS origen,
SUM(IFNULL(cuentasporcobrar.importe,0)) AS importemodulo,
0 AS Importecontabilidad,
'' AS CodigoAsiento
FROM
(
clientes
INNER JOIN
(
cuentasporcobrar
INNER JOIN
(
facturas
)ON (cuentasporcobrar.relaciondocumentoid=facturas.facturasid AND cuentasporcobrar.origen ='Facturacion' )
)ON clientes.clientesid=cuentasporcobrar.clientesid
)
WHERE
facturas.asientocontable = 0
AND DATE(facturas.emision) BETWEEN dFechaDesde AND dFechaHasta
GROUP BY
facturas.facturasid
UNION ALL
SELECT
cuentasporcobrar.emision AS Fecha,
clientes.codigocontable AS codigocontable,
cuentasporcobrar.asientocontable AS libros_diariosid,
cuentasporcobrar.centros_costosid AS centros_costosid,
cuentasporcobrar.documentosid AS ModuloID,
cuentasporcobrar.secuencial AS Documento,
cuentasporcobrar.concepto AS concepto,
'Facturacion Ret' AS origen,
SUM(IFNULL(cuentasporcobrar.importe,0)) AS importemodulo,
0 AS Importecontabilidad,
'' AS CodigoAsiento
FROM
(
clientes
INNER JOIN
(
cuentasporcobrar	
)ON clientes.clientesid=cuentasporcobrar.clientesid  AND cuentasporcobrar.origen = 'Cobros' AND cuentasporcobrar.tipo='IR'
)
WHERE
cuentasporcobrar.asientocontable = 0
AND cuentasporcobrar.emision BETWEEN dFechaDesde AND dFechaHasta
GROUP BY
cuentasporcobrar.documentosid
UNION ALL
SELECT
cobros.fechaemision AS Fecha,
clientes.codigocontable AS codigocontable,
cobros.asientocontable AS libros_diariosid,
1 AS centros_costosid,
cobros.cobrosid AS ModuloID,
cobros.cobroscodigo AS Documento,
cobros.concepto AS concepto,
'Cobros' AS origen,
SUM(IFNULL(cuentasporcobrar.importe,0)) AS importemodulo,
0 AS Importecontabilidad,
'' AS CodigoAsiento
FROM
(
clientes
INNER JOIN
(
cuentasporcobrar
INNER JOIN
(
cobros
)ON (cuentasporcobrar.cobrosid = cobros.cobrosid AND cuentasporcobrar.origen = 'Cobros' )
)ON clientes.clientesid=cuentasporcobrar.clientesid 
)
WHERE
cobros.asientocontable = 0 AND cuentasporcobrar.concepto not LIKE 'CRUCE ANTIC%'
AND	cobros.fechaemision BETWEEN dFechaDesde AND dFechaHasta
GROUP BY
cobros.cobrosid
UNION ALL
SELECT
cuentasporcobrar.emision AS Fecha,
clientes.codigocontable AS codigocontable,
0 AS libros_diariosid, 
cuentasporcobrar.centros_costosid AS centros_costosid,
cuentasporcobrar.cuentasporcobrarid AS ModuloID,
cuentasporcobrar.secuencial AS Documento,
cuentasporcobrar.concepto AS concepto,
'Ajuste CXC' AS origen,
ROUND(SUM(IFNULL(cuentasporcobrar.importe,0)),5) AS importemodulo,
(0) AS Importecontabilidad,
'' AS codigoasiento
FROM
clientes
INNER JOIN
(
cuentasporcobrar
)ON (clientes.clientesid = cuentasporcobrar.clientesid AND cuentasporcobrar.origen='Cobros' AND cuentasporcobrar.tipo='NC')
WHERE
cuentasporcobrar.asientocontable = 0  AND cuentasporcobrar.concepto LIKE 'CRUCE ANTIC%'
AND cuentasporcobrar.emision BETWEEN dFechaDesde AND dFechaHasta
GROUP BY
cuentasporcobrar.cuentasporcobrarid
UNION ALL
SELECT
cuentasporcobrar.emision AS Fecha,
clientes.codigocontable AS codigocontable,
0 AS libros_diariosid, 
cuentasporcobrar.centros_costosid AS centros_costosid,
cuentasporcobrar.cuentasporcobrarid AS ModuloID,
cuentasporcobrar.secuencial AS Documento,
cuentasporcobrar.concepto AS concepto,
'Ajuste CXC' AS origen,
ROUND(SUM(IFNULL(cuentasporcobrar.importe,0)),5) AS importemodulo,
(0) AS Importecontabilidad,
'' AS codigoasiento
FROM
clientes
INNER JOIN
(
cuentasporcobrar
)ON (clientes.clientesid = cuentasporcobrar.clientesid AND cuentasporcobrar.origen='Cobros' AND cuentasporcobrar.tipo='ND' )
WHERE
cuentasporcobrar.asientocontable = 0 AND cuentasporcobrar.concepto LIKE 'CRUCE ANTIC%'
AND cuentasporcobrar.emision BETWEEN dFechaDesde AND dFechaHasta
GROUP BY
cuentasporcobrar.cuentasporcobrarid;

ELSE
/*EN CONTABILIDA Y EN MODULO */
SELECT 
facturas.emision AS Fecha,
libros_diarios_detalles.codigocontable AS codigocontable,
libros_diarios_detalles.libros_diariosid AS libros_diariosid, 
libros_diarios_detalles.centros_costosid AS centros_costosid,
facturas.facturasid AS ModuloID,
libros_diarios.concepto AS documento,
libros_diarios_detalles.concepto AS concepto,
libros_diarios.origen AS origen,

(	SELECT 
ROUND(SUM(IFNULL(cxc.importe,0)),5) AS importemodulo
FROM  cuentasporcobrar as cxc
WHERE
cxc.asientocontable= libros_diarios.libros_diariosid
AND cxc.documentosid=facturas.facturasid
) AS importemodulo,

(	SELECT
SUM(IFNULL(libros_diarios_detalles.importe,0)) AS Importecontabilidad
FROM libros_diarios_detalles , libros_diarios AS lib
WHERE 
libros_diarios_detalles.libros_diariosid=lib.libros_diariosid
AND libros_diarios_detalles.codigocontable = sCuentaContable
AND lib.fecha  BETWEEN dFechaDesde AND dFechaHasta
AND lib.libros_diariosid =libros_diarios.libros_diariosid
) AS Importecontabilidad,

libros_diarios.codigoasiento AS codigoasiento
FROM 	
libros_diarios_detalles , libros_diarios , facturas ,cuentasporcobrar 

WHERE 
 
libros_diarios_detalles.libros_diariosid = libros_diarios.libros_diariosid

AND  libros_diarios.origen ='Facturacion' 
--  Caso de Facturacion a Credito 

AND  cuentasporcobrar.documentosid = facturas.facturasid 
AND cuentasporcobrar.relaciondocumentoid=0 
AND libros_diarios.libros_diariosid = facturas.asientocontable	

AND libros_diarios_detalles.codigocontable = sCuentaContable
AND DATE(facturas.emision) BETWEEN dFechaDesde AND dFechaHasta
AND libros_diarios.anulado = 0
and libros_diarios.mayorizado = 1
AND facturas.sri_documentoscodigo <> "04"
GROUP BY	
libros_diarios_detalles.libros_diariosid
/**********************************************************************************************************/
UNION ALL
SELECT 
facturas.emision AS Fecha,
libros_diarios_detalles.codigocontable AS codigocontable,
libros_diarios_detalles.libros_diariosid AS libros_diariosid, 
libros_diarios_detalles.centros_costosid AS centros_costosid,
facturas.facturasid AS ModuloID,
libros_diarios.referencia AS documento,
libros_diarios.concepto AS concepto,
libros_diarios.origen AS origen,

(	SELECT 
ROUND(SUM(IFNULL(cxc.importe,0)),5) AS importemodulo
FROM  cuentasporcobrar as cxc
WHERE
cxc.asientocontable= cuentasporcobrar.asientocontable
 AND facturas.facturasid = cxc.documentosid 
 AND cxc.clientesid = cuentasporcobrar.clientesid
) AS importemodulo,

(	SELECT
SUM(IFNULL(libros_diarios_detalles.importe,0)) AS Importecontabilidad
FROM libros_diarios_detalles , libros_diarios AS lib
WHERE 
libros_diarios_detalles.libros_diariosid=lib.libros_diariosid
AND libros_diarios_detalles.codigocontable = sCuentaContable
AND lib.fecha  BETWEEN dFechaDesde AND dFechaHasta
AND lib.libros_diariosid =libros_diarios.libros_diariosid
) AS Importecontabilidad,

libros_diarios.codigoasiento AS codigoasiento
FROM 	
libros_diarios_detalles , libros_diarios , facturas ,cuentasporcobrar LEFT JOIN cobros ON cuentasporcobrar.cobrosid =cobros.cobrosid  ,clientes 
WHERE 
 
libros_diarios_detalles.libros_diariosid = libros_diarios.libros_diariosid

AND  libros_diarios.origen ='Facturacion Ret' 
-- Caso de retencion de Factura pantalla cobros 		

AND cuentasporcobrar.clientesid=clientes.clientesid
AND facturas.facturasid = cuentasporcobrar.documentosid 
AND cuentasporcobrar.relaciondocumentoid=0 
AND libros_diarios.libros_diariosid = cuentasporcobrar.asientocontable	 


AND libros_diarios_detalles.codigocontable = sCuentaContable
AND DATE(facturas.emision) BETWEEN dFechaDesde AND dFechaHasta
AND libros_diarios.anulado = 0
and libros_diarios.mayorizado = 1
GROUP BY	
libros_diarios_detalles.libros_diariosid
/**********************************************************************************************************/
UNION ALL
SELECT 
cuentasporcobrar.emision AS Fecha,
libros_diarios_detalles.codigocontable AS codigocontable,
libros_diarios_detalles.libros_diariosid AS libros_diariosid, 
libros_diarios_detalles.centros_costosid AS centros_costosid,
cobros.cobrosid AS ModuloID,
libros_diarios.referencia AS documento,
libros_diarios_detalles.concepto AS concepto,
libros_diarios.origen AS origen,

(	SELECT 
ROUND(SUM(IFNULL(cxc.importe,0)),5) AS importemodulo
FROM  cuentasporcobrar as cxc
WHERE
cxc.asientocontable= cuentasporcobrar.asientocontable
-- AND facturas.facturasid = cxc.documentosid 
AND cxc.clientesid = cuentasporcobrar.clientesid

) AS importemodulo,

(	SELECT
SUM(IFNULL(libros_diarios_detalles.importe,0)) AS Importecontabilidad
FROM libros_diarios_detalles , libros_diarios AS lib
WHERE 
libros_diarios_detalles.libros_diariosid=lib.libros_diariosid
AND libros_diarios_detalles.codigocontable = sCuentaContable
AND lib.fecha  BETWEEN dFechaDesde AND dFechaHasta
AND lib.libros_diariosid =libros_diarios.libros_diariosid
) AS Importecontabilidad,

libros_diarios.codigoasiento AS codigoasiento
FROM 	
libros_diarios_detalles , libros_diarios , cuentasporcobrar LEFT JOIN cobros ON cuentasporcobrar.cobrosid =cobros.cobrosid  ,clientes 
WHERE 
 
libros_diarios_detalles.libros_diariosid = libros_diarios.libros_diariosid

AND  libros_diarios.origen ='Cobros' 
-- Caso de cobros pantalla cobros		
AND cuentasporcobrar.clientesid=clientes.clientesid
AND cobros.cobrosid = cuentasporcobrar.cobrosid
AND libros_diarios.libros_diariosid = cobros.asientocontable 


AND libros_diarios_detalles.codigocontable = sCuentaContable
AND cuentasporcobrar.emision BETWEEN dFechaDesde AND dFechaHasta
AND libros_diarios.anulado = 0
and libros_diarios.mayorizado = 1
GROUP BY	
libros_diarios_detalles.libros_diariosid
/**********************************************************************************************************/
UNION ALL
SELECT 
cuentasporcobrar.emision AS Fecha,
libros_diarios_detalles.codigocontable AS codigocontable,
libros_diarios_detalles.libros_diariosid AS libros_diariosid, 
libros_diarios_detalles.centros_costosid AS centros_costosid,
cobros.cobrosid AS ModuloID,
libros_diarios.referencia AS documento,
libros_diarios_detalles.concepto AS concepto,
libros_diarios.origen AS origen,

(	SELECT 
ROUND(SUM(IFNULL(cxc.importe,0)),5) AS importemodulo
FROM  cuentasporcobrar as cxc
WHERE
cxc.asientocontable= cuentasporcobrar.asientocontable
-- AND facturas.facturasid = cxc.documentosid 
AND cxc.clientesid = cuentasporcobrar.clientesid
--  AND cxc.origen='Cobros'
) AS importemodulo,

(	SELECT
SUM(IFNULL(libros_diarios_detalles.importe,0)) AS Importecontabilidad
FROM libros_diarios_detalles , libros_diarios AS lib
WHERE 
libros_diarios_detalles.libros_diariosid=lib.libros_diariosid
AND libros_diarios_detalles.codigocontable = sCuentaContable
AND lib.fecha  BETWEEN dFechaDesde AND dFechaHasta
AND lib.libros_diariosid =libros_diarios.libros_diariosid
) AS Importecontabilidad,

libros_diarios.codigoasiento AS codigoasiento
FROM 	
libros_diarios_detalles , libros_diarios , cuentasporcobrar LEFT JOIN cobros ON cuentasporcobrar.cobrosid =cobros.cobrosid  ,clientes 
WHERE 
 
libros_diarios_detalles.libros_diariosid = libros_diarios.libros_diariosid

AND  libros_diarios.origen ='Ajuste CxC' 
-- Caso de anticipo a cobro pantalla cobros 
AND cuentasporcobrar.clientesid = clientes.clientesid
AND libros_diarios.libros_diariosid = cuentasporcobrar.asientocontable 


AND libros_diarios_detalles.codigocontable = sCuentaContable
AND cuentasporcobrar.emision BETWEEN dFechaDesde AND dFechaHasta
AND libros_diarios.anulado = 0
and libros_diarios.mayorizado = 1
GROUP BY	
libros_diarios_detalles.libros_diariosid	

/******************************************************************************/
/*EN CONTABILIDAD Y NO EN MODULO*/

UNION ALL
SELECT 
libros_diarios.fecha AS Fecha,
libros_diarios_detalles.codigocontable AS codigocontable,
libros_diarios_detalles.libros_diariosid AS libros_diariosid, 
libros_diarios_detalles.centros_costosid AS CentroCostoID,
'0' AS ModuloID,
libros_diarios_detalles.referencia AS documento,
libros_diarios_detalles.concepto AS concepto,
libros_diarios.origen AS origen,
'0.00' AS importemodulo,

(	SELECT
SUM(IFNULL(libros_diarios_detalles.importe,0)) AS Importecontabilidad
FROM libros_diarios_detalles , libros_diarios AS lib
WHERE 
libros_diarios_detalles.libros_diariosid=lib.libros_diariosid
AND libros_diarios_detalles.codigocontable = sCuentaContable
AND lib.fecha  BETWEEN dFechaDesde AND dFechaHasta
AND lib.libros_diariosid =libros_diarios.libros_diariosid
) AS Importecontabilidad,

libros_diarios.codigoasiento AS codigoasiento
FROM 
libros_diarios inner join libros_diarios_detalles on libros_diarios_detalles.libros_diariosid=libros_diarios.libros_diariosid
WHERE 
libros_diarios_detalles.codigocontable = sCuentaContable
AND libros_diarios.origen in ('Contabilidad','Facturacion')
AND libros_diarios.fecha BETWEEN dFechaDesde AND dFechaHasta
AND libros_diarios.libros_diariosid NOT IN (SELECT cxc.asientocontable from cuentasporcobrar cxc WHERE cxc.emision BETWEEN dFechaDesde AND dFechaHasta)
AND libros_diarios.anulado = 0
AND libros_diarios.mayorizado = 1

group by
libros_diarios_detalles.libros_diariosID
HAVING Importecontabilidad <> 0


/********************************************************************************/
/***SIN CONTABILIZAR LA FACTURA   ****/
UNION ALL
SELECT
facturas.emision AS Fecha,
clientes.codigocontable AS codigocontable,
facturas.asientocontable AS asientocontable,
facturas.centros_costosid AS centros_costosid,
