(libros_diarios) ON (facturas.asientocontable=libros_diarios.libros_diariosid)
)ON (cuentasporcobrar.documentosid=facturas.facturasid AND cuentasporcobrar.relaciondocumentoid=0 AND cuentasporcobrar.origen = 'Facturacion' )
)ON clientes.clientesid=cuentasporcobrar.clientesid AND clientes.codigocontable= sCuentaContable
)
