)ON (clientes.clientesid = cuentasporcobrar.clientesid AND clientes.codigocontable =sCuentaContable AND cuentasporcobrar.origen='Cobros' AND cuentasporcobrar.tipo='ND'  and cuentasporcobrar.concepto  like 'CRUCE ANT%')
WHERE
