'' AS CodigoAsiento
FROM
(
proveedores
INNER JOIN
(
cuentasporpagar
INNER JOIN
(
compras
)ON (cuentasporpagar.documentosid=compras.comprasid AND cuentasporpagar.relaciondocumentoid=0 AND cuentasporpagar.origen LIKE 'Compr%')
)ON proveedores.proveedoresid=cuentasporpagar.proveedoresid
)
WHERE
compras.asientocontable = 0
AND DATE(compras.emision) BETWEEN dFechaDesde AND dFechaHasta
GROUP BY
compras.comprasid 
UNION ALL
SELECT
compras.emision AS Fecha,
