)ON proveedores.proveedoresid=cuentasporpagar.proveedoresid
)
WHERE
pagos.asientocontable = 0
AND	pagos.fechaemision BETWEEN dFechaDesde AND dFechaHasta
GROUP BY
pagos.pagosid
UNION ALL
SELECT
cuentasporpagar.emision AS Fecha,
proveedores.codigocontable AS codigocontable,
0 AS libros_diariosid, 
