ROUND(SUM(IFNULL(cuentasporpagar.importe,0)),5) AS importemodulo,
(0) AS Importecontabilidad,
'' AS codigoasiento
FROM
proveedores
INNER JOIN
(
cuentasporpagar
)ON (proveedores.proveedoresid = cuentasporpagar.proveedoresid AND cuentasporpagar.origen='Pagos' AND cuentasporpagar.tipo='NC'  AND cuentasporpagar.concepto LIKE 'CRUCE ANTIC%')
WHERE
cuentasporpagar.asientocontable = 0
AND cuentasporpagar.emision BETWEEN dFechaDesde AND dFechaHasta
GROUP BY
cuentasporpagar.cuentasporpagarid
UNION ALL
SELECT
cuentasporpagar.emision AS Fecha,
proveedores.codigocontable AS codigocontable,
0 AS libros_diariosid, 
cuentasporpagar.centros_costosid AS CentroCostoID,
cuentasporpagar.cuentasporpagarid AS ModuloID,
cuentasporpagar.secuencia AS Documento,
cuentasporpagar.concepto AS concepto,
'Ajuste CXP' AS origen,
ROUND(SUM(IFNULL(cuentasporpagar.importe,0)),5) AS importemodulo,
(0) AS Importecontabilidad,
'' AS codigoasiento
FROM
proveedores
INNER JOIN
(
cuentasporpagar
)ON (proveedores.proveedoresid = cuentasporpagar.proveedoresid AND cuentasporpagar.origen='Pagos' AND cuentasporpagar.tipo='ND'  AND cuentasporpagar.concepto LIKE 'CRUCE ANTIC%')
WHERE
cuentasporpagar.asientocontable = 0
AND cuentasporpagar.emision BETWEEN dFechaDesde AND dFechaHasta
GROUP BY
cuentasporpagar.cuentasporpagarid;

ELSE
/*EN CONTABILIDAD Y EN MODULO*/
SELECT 
compras.emision AS Fecha,
libros_diarios_detalles.codigocontable AS codigocontable,
libros_diarios_detalles.libros_diariosid AS libros_diariosid, 
libros_diarios_detalles.centros_costosid AS CentroCostoID,
compras.comprasid AS ModuloID,
libros_diarios.referencia AS documento,
libros_diarios_detalles.concepto AS concepto,
libros_diarios.origen AS origen,

(	SELECT 
ROUND(SUM(IFNULL(cxp.importe,0)),5) AS importemodulo
FROM  cuentasporpagar as cxp
WHERE
cxp.asientocontable= cuentasporpagar.asientocontable
 AND compras.comprasid = cxp.documentosid 
 		AND cxp.proveedoresid = cuentasporpagar.proveedoresid
) AS importemodulo,

(	SELECT
SUM(IFNULL(libros_diarios_detalles.importe,0)) AS Importecontabilidad
FROM libros_diarios_detalles , libros_diarios AS lib
WHERE 
libros_diarios_detalles.libros_diariosid=lib.libros_diariosid
AND libros_diarios_detalles.codigocontable = sCuentaContable
AND lib.fecha  BETWEEN dFechaDesde AND dFechaHasta
AND lib.libros_diariosid =libros_diarios.libros_diariosid
) AS Importecontabilidad,

libros_diarios.codigoasiento AS codigoasiento
FROM 	
libros_diarios_detalles,  libros_diarios , compras , cuentasporpagar LEFT JOIN pagos ON cuentasporpagar.pagosid =pagos.pagosid  , proveedores 

WHERE 
cuentasporpagar.proveedoresid=proveedores.proveedoresid
and cuentasporpagar.proveedoresid= compras.proveedoresid
AND libros_diarios.origen ='Compras' 
-- Pantalla de Compras 
AND compras.comprasid = cuentasporpagar.documentosid 
AND cuentasporpagar.relaciondocumentoid=0 
AND libros_diarios.libros_diariosid = compras.asientocontable
AND libros_diarios_detalles.libros_diariosid = libros_diarios.libros_diariosid
AND libros_diarios_detalles.codigocontable = sCuentaContable
AND compras.asientocontable=cuentasporpagar.asientocontable

AND DATE(compras.emision) BETWEEN dFechaDesde AND dFechaHasta
AND libros_diarios.anulado = 0
AND libros_diarios.mayorizado = 1
GROUP BY
libros_diarios_detalles.libros_diariosid

/***********************************************************************************/
UNION ALL
SELECT 
pagos.fechaemision AS Fecha,
libros_diarios_detalles.codigocontable AS codigocontable,
libros_diarios_detalles.libros_diariosid AS libros_diariosid, 
libros_diarios_detalles.centros_costosid AS CentroCostoID,
pagos.pagosid AS ModuloID,
libros_diarios.referencia AS documento,
libros_diarios_detalles.concepto AS concepto,
libros_diarios.origen AS origen,

(	SELECT 
ROUND(SUM(IFNULL(cxp.importe,0)),5) AS importemodulo
FROM  cuentasporpagar as cxp
WHERE
cxp.asientocontable= cuentasporpagar.asientocontable
AND cxp.proveedoresid = cuentasporpagar.proveedoresid
) AS importemodulo,

(	SELECT
SUM(IFNULL(libros_diarios_detalles.importe,0)) AS Importecontabilidad
FROM libros_diarios_detalles , libros_diarios AS lib
WHERE 
libros_diarios_detalles.libros_diariosid=lib.libros_diariosid
AND libros_diarios_detalles.codigocontable = sCuentaContable
AND lib.fecha  BETWEEN dFechaDesde AND dFechaHasta
AND lib.libros_diariosid =libros_diarios.libros_diariosid
) AS Importecontabilidad,

libros_diarios.codigoasiento AS codigoasiento
FROM 	
libros_diarios_detalles,  libros_diarios ,  cuentasporpagar LEFT JOIN pagos ON cuentasporpagar.pagosid =pagos.pagosid  , proveedores 

WHERE 
cuentasporpagar.proveedoresid=proveedores.proveedoresid
AND  libros_diarios.origen ='Pagos' 
-- Pantalla de pagos 
AND pagos.pagosid = cuentasporpagar.pagosid 
AND libros_diarios.libros_diariosid = pagos.asientocontable
AND libros_diarios_detalles.libros_diariosid = libros_diarios.libros_diariosid
-- AND proveedores.codigocontable = '%1'
AND libros_diarios_detalles.codigocontable =sCuentaContable
AND cuentasporpagar.emision BETWEEN dFechaDesde AND dFechaHasta
AND libros_diarios.anulado = 0
and libros_diarios.mayorizado = 1
GROUP BY
libros_diarios_detalles.libros_diariosid

/***********************************************************************************/
/*EN CONTABILIDAD Y NO MODULO*/
UNION ALL
SELECT 
libros_diarios.Fecha AS Fecha,
libros_diarios_detalles.codigocontable AS codigocontable,
libros_diarios_detalles.libros_diariosid AS libros_diariosid, 
libros_diarios_detalles.centros_costosid AS CentroCostoID,
0 AS ModuloID,
'' AS Documento,
libros_diarios_detalles.concepto AS concepto,
libros_diarios.origen AS origen,


(	SELECT 
SUM(IFNULL(cxp.importe,0)) AS importemodulo
FROM  cuentasporpagar as cxp
WHERE
cxp.asientocontable= cuentasporpagar.asientocontable
) AS importemodulo,

(	SELECT
SUM(IFNULL(libros_diarios_detalles.importe,0)) AS Importecontabilidad
FROM libros_diarios_detalles , libros_diarios AS lib
WHERE 
libros_diarios_detalles.libros_diariosid=lib.libros_diariosid
AND libros_diarios_detalles.codigocontable = sCuentaContable
AND lib.fecha  BETWEEN dFechaDesde AND dFechaHasta
AND lib.libros_diariosid =libros_diarios.libros_diariosid
) AS Importecontabilidad,
libros_diarios.codigoasiento AS codigoasiento

FROM 
cuentasporpagar 
RIGHT JOIN (libros_diarios INNER JOIN libros_diarios_detalles on libros_diarios_detalles.libros_diariosid=libros_diarios.libros_diariosid ) 
on libros_diarios.libros_diariosid=cuentasporpagar.asientocontable 
AND cuentasporpagar.emision BETWEEN dFechaDesde AND dFechaHasta
WHERE 
libros_diarios_detalles.codigocontable = sCuentaContable
AND libros_diarios.origen in ('Contabilidad','Compras')
AND libros_diarios.anulado = 0
AND libros_diarios.mayorizado = 1
group by
libros_diarios_detalles.libros_diariosID
HAVING importemodulo is NULL AND Importecontabilidad <> 0	

/***********************************************************************************/
/***NO CONTABILIDAD Y EN MODULO ***/
UNION ALL
SELECT
compras.emision AS Fecha,
proveedores.codigocontable AS codigocontable,
compras.asientocontable AS asientocontable,
compras.centros_costosid AS CentroCostoID,
compras.comprasid  AS ModuloID,
compras.secuencia AS Documento,
compras.concepto AS concepto,
'Compras' AS origen,
SUM(IFNULL(cuentasporpagar.importe,0)) AS importemodulo,
0 AS Importecontabilidad,
IFNULL(libros_diarios.codigoasiento,'') AS CodigoAsiento
FROM
(
proveedores
INNER JOIN
(
cuentasporpagar
INNER JOIN
(
compras
LEFT JOIN
(libros_diarios) ON (compras.asientocontable=libros_diarios.libros_diariosid)
)ON (cuentasporpagar.relaciondocumentoid=compras.comprasid AND cuentasporpagar.origen LIKE 'Compr%' )
)ON proveedores.proveedoresid=cuentasporpagar.proveedoresid AND proveedores.codigocontable=sCuentaContable
)
WHERE
(libros_diarios.libros_diariosid IS NULL 
OR libros_diarios.mayorizado = 0)
AND DATE(compras.emision) BETWEEN dFechaDesde AND dFechaHasta
GROUP BY
compras.comprasid

/******************************************************************************************/
/*EN CONTABILIDAD, EN EL MODULO NO ESTA LA TRANSACCION*/
UNION ALL
SELECT 
libros_diarios.Fecha AS Fecha,
libros_diarios_detalles.codigocontable AS codigocontable,
libros_diarios_detalles.libros_diariosid AS libros_diariosid, 
libros_diarios_detalles.centros_costosid AS CentroCostoID,
pagos.pagosid AS ModuloID,
libros_diarios.referencia AS Documento,
libros_diarios_detalles.concepto AS concepto,
libros_diarios.origen AS origen,
0 AS importemodulo,
libros_diarios_detalles.importe AS Importecontabilidad,
libros_diarios.codigoasiento AS codigoasiento
FROM 	
libros_diarios_detalles
INNER JOIN
(	libros_diarios	
RIGHT JOIN 
(pagos
)ON libros_diarios.libros_diariosid = pagos.asientocontable
)ON libros_diarios_detalles.libros_diariosid = libros_diarios.libros_diariosid	
WHERE 
libros_diarios.origen='Compras'
AND libros_diarios_detalles.codigocontable = sCuentaContable
AND libros_diarios.Fecha BETWEEN dFechaDesde AND dFechaHasta
AND libros_diarios.anulado = 0
and libros_diarios.mayorizado = 1
and pagos.pagosid is null
GROUP BY
libros_diarios_detalles.libros_diarios_detallesid

/***********************************************************************************/
/** ASIENTO COLGADO **/
UNION ALL
SELECT 
libros_diarios.Fecha AS Fecha,
libros_diarios_detalles.codigocontable AS codigocontable,
libros_diarios_detalles.libros_diariosid AS libros_diariosid, 
libros_diarios_detalles.centros_costosid AS CentroCostoID,
pagos.pagosid AS ModuloID,
libros_diarios.referencia AS Documento,
concat(libros_diarios_detalles.concepto,' asiento colgado') AS concepto,
libros_diarios.origen AS origen,
0 AS importemodulo,
libros_diarios_detalles.importe AS Importecontabilidad,
libros_diarios.codigoasiento AS codigoasiento
FROM 	
libros_diarios_detalles
INNER JOIN
(	libros_diarios	
left JOIN
(pagos
)ON libros_diarios.libros_diariosid = pagos.asientocontable
)ON libros_diarios_detalles.libros_diariosid = libros_diarios.libros_diariosid	
WHERE 
libros_diarios.origen='Pagos'
AND libros_diarios_detalles.codigocontable = sCuentaContable
AND libros_diarios.Fecha BETWEEN dFechaDesde AND dFechaHasta
AND libros_diarios.anulado = 0
and libros_diarios.mayorizado = 1
and pagos.pagosid is null
GROUP BY
libros_diarios_detalles.libros_diarios_detallesid

/***********************************************************************************/
/* CRUCE DE PAGOS DESDE LA PANTALLA DE ESTD. CUEN. PROVEE EM BOTON RELACION SALDOS CONTABILIZADO **/
union all
SELECT 
libros_diarios.Fecha AS Fecha,
libros_diarios_detalles.codigocontable AS codigocontable,
libros_diarios_detalles.libros_diariosid AS libros_diariosid, 
libros_diarios_detalles.centros_costosid AS CentroCostoID,
cuentasporpagar.cuentasporpagarid AS ModuloID,
cuentasporpagar.secuencia AS Documento,
libros_diarios_detalles.concepto AS concepto,
libros_diarios.origen AS origen,

(	SELECT 
ROUND(SUM(IFNULL(cxp.importe,0)),5) AS importemodulo
FROM  cuentasporpagar as cxp
WHERE
cxp.asientocontable= cuentasporpagar.asientocontable
) AS importemodulo,


(	SELECT
SUM(IFNULL(libros_diarios_detalles.importe,0)) AS Importecontabilidad
FROM libros_diarios_detalles , libros_diarios AS lib
WHERE 
libros_diarios_detalles.libros_diariosid=lib.libros_diariosid
AND libros_diarios_detalles.codigocontable = sCuentaContable
AND lib.fecha  BETWEEN dFechaDesde AND dFechaHasta
AND lib.libros_diariosid =libros_diarios.libros_diariosid
) AS Importecontabilidad,

libros_diarios.codigoasiento AS codigoasiento
FROM 	
libros_diarios_detalles
INNER JOIN
(	libros_diarios	
LEFT JOIN
(cuentasporpagar
INNER JOIN
(proveedores
)ON (cuentasporpagar.proveedoresid = proveedores.proveedoresid AND cuentasporpagar.origen = 'Pagos'  AND cuentasporpagar.concepto LIKE 'CRUCE ANTIC%')
)ON (libros_diarios.libros_diariosid = cuentasporpagar.asientocontable AND cuentasporpagar.origen = 'Pagos'  AND cuentasporpagar.concepto LIKE 'CRUCE ANTIC%')
)ON libros_diarios_detalles.libros_diariosid = libros_diarios.libros_diariosid	
WHERE 
libros_diarios.origen='Ajuste CXP'
 	AND cuentasporpagar.tipo IN ( 'NC', 'ND')
AND libros_diarios_detalles.codigocontable =sCuentaContable
AND libros_diarios.Fecha BETWEEN dFechaDesde AND dFechaHasta
AND libros_diarios.anulado = 0
and libros_diarios.mayorizado = 1
GROUP BY
libros_diarios_detalles.libros_diariosid

