UNION ALL
SELECT
pagos.fechaemision AS Fecha,
proveedores.codigocontable AS codigocontable,
pagos.asientocontable AS asientocontable,
1 AS CentroCostoID,
pagos.pagosid AS ModuloID,
pagos.pagoscodigo AS Documento,
pagos.concepto AS concepto,
'Pagos' AS origen,
SUM(IFNULL(cuentasporpagar.importe,0)) AS importemodulo,
0 AS Importecontabilidad,
IFNULL(libros_diarios.codigoasiento,'') AS CodigoAsiento
FROM
(
proveedores
INNER JOIN
(
cuentasporpagar
INNER JOIN
(
pagos
LEFT JOIN
(libros_diarios) ON (pagos.asientocontable=libros_diarios.libros_diariosid)
)ON (cuentasporpagar.pagosid = pagos.pagosid)
)ON proveedores.proveedoresid=cuentasporpagar.proveedoresid AND proveedores.codigocontable= sCuentaContable
)
WHERE
(libros_diarios.libros_diariosid IS NULL 
OR libros_diarios.mayorizado = 0)
AND	pagos.fechaemision BETWEEN dFechaDesde AND dFechaHasta
GROUP BY
pagos.pagosid
