ROUND(SUM(IFNULL(cuentasporpagar.importe,0)),2) AS importemodulo,
(0) AS Importecontabilidad,
libros_diarios.codigoasiento AS codigoasiento
FROM 	
(	libros_diarios	
INNER JOIN
(cuentasporpagar
INNER JOIN
(proveedores
)ON (cuentasporpagar.proveedoresid = proveedores.proveedoresid AND cuentasporpagar.origen = 'pagos' and cuentasporpagar.tipo= 'ND' AND cuentasporpagar.concepto LIKE 'CRUCE ANTIC%')
)ON (libros_diarios.libros_diariosid = cuentasporpagar.asientocontable AND cuentasporpagar.origen = 'pagos' and cuentasporpagar.tipo= 'ND' AND cuentasporpagar.concepto LIKE 'CRUCE ANTIC%')
)
WHERE 
libros_diarios.Fecha BETWEEN  '%2' AND '%3'
AND libros_diarios.anulado = 0
AND libros_diarios.libros_diariosid NOT IN (
SELECT DISTINCT det.libros_diariosid 
FROM libros_diarios_detalles det  WHERE det.codigocontable = '%1'
)
GROUP BY
libros_diarios.libros_diariosid	
HAVING
libros_diarios.fecha is not null
*/

END if ;

