-- ----------------------------
-- Procedure structure for SP_Consulta_Secuencias_Internas
-- ----------------------------
DROP PROCEDURE IF EXISTS `SP_Consulta_Secuencias_Internas`;
delimiter ;;
CREATE PROCEDURE `SP_Consulta_Secuencias_Internas`(IN sTabla VARCHAR(255), OUT sSecuencia VARCHAR(10))
  READS SQL DATA 
  DETERMINISTIC
  SQL SECURITY INVOKER
BEGIN
 
  SET sSecuencia=( SELECT CONCAT(secuenciales.prefijo,LPAD(secuenciales.valor,secuenciales.numeroceros,'0')) as secuencial FROM secuenciales WHERE secuenciales.secuencial=sTabla);

END
;;
delimiter ;

-- ----------------------------
-- Procedure structure for SP_Contabiliza_Activos_Fijos_Agrupado
-- ----------------------------
DROP PROCEDURE IF EXISTS `SP_Contabiliza_Activos_Fijos_Agrupado`;
delimiter ;;
CREATE PROCEDURE `SP_Contabiliza_Activos_Fijos_Agrupado`(IN dFechaDesde DATE, IN dFechaHasta DATE, IN sUsuario VARCHAR(25))
  MODIFIES SQL DATA 
BEGIN

-- Declaramos variables de Cursor
DECLARE termino INT DEFAULT FALSE;
-- DECLARE fechamovimiento date;
DECLARE usuariocreacion varchar(25);
DECLARE centros_costosid int(11);
-- DECLARE concepto varchar(200);
-- DECLARE referencia varchar(15);
DECLARE valor decimal(16,8) DEFAULT 0;
DECLARE codigocontable varchar(30);
DECLARE codigoasiento varchar(15);
DECLARE gravocabecera INT DEFAULT FALSE;
DECLARE libros_diariosid bigint DEFAULT 0;
DECLARE debe  decimal(16,8) DEFAULT 0;
DECLARE haber decimal(16,8) DEFAULT 0;
DECLARE diferencia decimal(12,2) DEFAULT 0;
DECLARE verificado INT DEFAULT TRUE;
DECLARE cuenta_fija bigint DEFAULT 0;

DECLARE Datos_Asiento CURSOR FOR
select
activos.centros_costosid AS centros_costosid,
sum(activos_depreciaciones.depreciacionmensual) AS valor,
activos.codigocontable_debe as codigocontable
from
activos 
inner join activos_depreciaciones on activos.activosid = activos_depreciaciones.activosid
where
activos_depreciaciones.libros_diariosid = 0
AND activos_depreciaciones.fecha BETWEEN dFechaDesde AND dFechaHasta
GROUP BY
activos.codigocontable_debe,
activos.centros_costosid
HAVING
SUM(activos_depreciaciones.depreciacionmensual)<>0
union
SELECT
activos.centros_costosid AS centros_costosid,
-SUM(activos_depreciaciones.depreciacionmensual) AS valor,
activos.codigocontable_haber AS codigocontable
FROM
activos 
INNER JOIN activos_depreciaciones ON activos.activosid = activos_depreciaciones.activosid
WHERE
activos_depreciaciones.libros_diariosid = 0
AND activos_depreciaciones.Fecha BETWEEN dFechaDesde AND dFechaHasta
GROUP BY
activos.codigocontable_haber,
activos.centros_costosid
HAVING
-SUM(activos_depreciaciones.depreciacionmensual)<>0;



-- Controlamos si hubo error
DECLARE exit handler FOR SQLEXCEPTION, SQLWARNING
  BEGIN
  	SHOW WARNINGS limit 1;
    ROLLBACK;
    RESIGNAL;
  END;

-- Declaramos el control de salida del loop
DECLARE CONTINUE HANDLER FOR NOT FOUND SET termino = TRUE;

-- Abrimos el Cursor
OPEN Datos_Asiento;

-- Iniciamos la Transaccion
START TRANSACTION;

-- Leeemos el Cursor
read_loop: LOOP
FETCH Datos_Asiento INTO centros_costosid, valor, codigocontable;

-- Verificamos si no hay mas registros
IF termino THEN
LEAVE read_loop;
END IF;

SET diferencia = ROUND(diferencia+(Round(valor,2)),2);
-- Sumamos valores de debe y haber
IF valor<0 THEN
  SET haber = (haber + (Abs((valor))));
ELSE
  SET debe  = (debe + (Abs((valor))));
END IF;

-- INSERTAMOS LA CABECERA DEL ASIENTO
  IF gravocabecera=FALSE THEN
    -- Optenemos el nuevo secuencial
    call SP_Consulta_Secuencias_Internas('LIBRODIARIO',codigoasiento);

    -- Insertamos Registro Cabecera
    INSERT INTO libros_diarios 
    (
      codigoasiento, 
      fecha, 
      referencia, 
      concepto, 
      origen, 
      usuariocreacion, 
      fechacreacion
    ) 
    VALUES 
    (
      codigoasiento,
      dFechaDesde,
      codigoasiento, 
      CONCAT('Depreciaciones Activos Fijos del ',DATE_FORMAT(dFechaDesde,"%d-%m-%Y"),' al ',DATE_FORMAT(dFechaHasta,"%d-%m-%Y")),
      'Activos Fijos', 
      sUsuario, 
      NOW()
    );
   
   -- obtenemos el ultimo ID insertado
    SET libros_diariosid=(select LAST_INSERT_ID());
    
    -- Actualizamos el secuencial de libros diarios
    call SP_Actualiza_Secuencias_Internas('LIBRODIARIO');

    -- Ponemos que gravo la cabecera
    SET gravocabecera=TRUE;

  END IF;


-- INSERTAMOS LOS DETALLES
set valor = round(valor,2);
INSERT INTO libros_diarios_detalles
( 	
libros_diariosid,	
codigocontable,	
centros_costosid,	
referencia,	
concepto,	
importe
)
VALUES
( 
libros_diariosid,	
codigocontable,	
centros_costosid,	
codigoasiento,	
CONCAT('Depreciaciones Activos Fijos del ',DATE_FORMAT(dFechaDesde,"%d-%m-%Y"),' al ',DATE_FORMAT(dFechaHasta,"%d-%m-%Y")),	
valor
 );

-- Toma la primer cuenta del asiento contable
IF cuenta_fija=0 THEN 
SET cuenta_fija = (select LAST_INSERT_ID());
END IF;

END LOOP;

CALL SP_Contabiliza_Verificar_Asiento(libros_diariosid,verificado);


-- Cuadramos el asiento contable si esta descuadrado
IF diferencia<0.11 AND diferencia>-0.11 AND diferencia<>0  THEN
UPDATE libros_diarios_detalles
SET
libros_diarios_detalles.importe = libros_diarios_detalles.importe-diferencia
WHERE
libros_diarios_detalles.libros_diarios_detallesid = cuenta_fija;
SET diferencia=0;
END IF;

-- Verificamos si el asiento esta cuadrado
IF diferencia<>0 THEN
SET verificado=0;
END IF;

-- Actualizamos el libro diario
SET debe = Round(debe,2);
SET haber = Round(haber,2);
UPDATE 
libros_diarios
SET
libros_diarios.debito = debe,
libros_diarios.credito = haber,
libros_diarios.mayorizado = verificado,
libros_diarios.verificado = verificado
WHERE
libros_diarios.libros_diariosid = libros_diariosid;


-- Actualizamos el ID del libro diario a la depresiación del activo fijo

UPDATE
activos_depreciaciones 
SET
activos_depreciaciones.libros_diariosid = libros_diariosid
WHERE
activos_depreciaciones.libros_diariosid = 0
AND activos_depreciaciones.fecha BETWEEN dFechaDesde AND dFechaHasta;

-- Finalizamos la transaccion
COMMIT;

-- Cerramos el Cursor
CLOSE Datos_Asiento;

-- Devolvemos el ID del Asiento Contable
select libros_diariosid;

END
;;
delimiter ;

-- ----------------------------
-- Procedure structure for SP_Contabiliza_Activos_Fijos_Individual
-- ----------------------------
DROP PROCEDURE IF EXISTS `SP_Contabiliza_Activos_Fijos_Individual`;
delimiter ;;
CREATE PROCEDURE `SP_Contabiliza_Activos_Fijos_Individual`(IN nDocumentoid BIGINT, IN dFecha DATE, IN sUsuario VARCHAR(25))
  MODIFIES SQL DATA 
BEGIN

-- Declaramos variables de Cursor
DECLARE termino INT DEFAULT FALSE;
DECLARE fechamovimiento date;
DECLARE usuariocreacion varchar(25);
DECLARE centros_costosid int(11);
DECLARE concepto varchar(200);
-- DECLARE referencia varchar(15);
DECLARE valor decimal(16,8) DEFAULT 0;
DECLARE codigocontable varchar(30);
DECLARE codigoasiento varchar(15);
DECLARE gravocabecera INT DEFAULT FALSE;
DECLARE libros_diariosid bigint DEFAULT 0;
DECLARE debe  decimal(16,8) DEFAULT 0;
DECLARE haber decimal(16,8) DEFAULT 0;
DECLARE diferencia decimal(12,2) DEFAULT 0;
DECLARE verificado INT DEFAULT TRUE;
DECLARE cuenta_fija bigint DEFAULT 0;

DECLARE Datos_Asiento CURSOR FOR
select
activos.centros_costosid AS centros_costosid,
LEFT (CONCAT("Depreciación Activo fijo ",activos.descripcion," ",MONTH(activos_depreciaciones.fecha),"-",YEAR(activos_depreciaciones.fecha)),200) AS concepto,
sum(activos_depreciaciones.depreciacionmensual) AS valor,
activos.codigocontable_debe as codigocontable
from
activos 
inner join activos_depreciaciones on activos.activosid = activos_depreciaciones.activosid
where
activos_depreciaciones.libros_diariosid = 0 and activos_depreciaciones.activosid = nDocumentoid
AND YEAR(activos_depreciaciones.fecha) = YEAR(dFecha) AND MONTH(activos_depreciaciones.fecha)  = MONTH(dFecha)
GROUP BY
activos.codigocontable_debe,
activos.centros_costosid
HAVING
SUM(activos_depreciaciones.depreciacionmensual)<>0
union
SELECT
activos.centros_costosid AS centros_costosid,
LEFT (CONCAT("Depreciación Activo fijo ",activos.descripcion," ",MONTH(activos_depreciaciones.fecha),"-",YEAR(activos_depreciaciones.fecha)),200) AS concepto,
-SUM(activos_depreciaciones.depreciacionmensual) AS valor,
activos.codigocontable_haber AS codigocontable
FROM
activos 
INNER JOIN activos_depreciaciones ON activos.activosid = activos_depreciaciones.activosid
WHERE
activos_depreciaciones.libros_diariosid = 0 and activos_depreciaciones.activosid = nDocumentoid
AND YEAR(activos_depreciaciones.fecha) = YEAR(dFecha) AND MONTH(activos_depreciaciones.fecha)  = MONTH(dFecha)
GROUP BY
activos.codigocontable_haber,
activos.centros_costosid
HAVING
-SUM(activos_depreciaciones.depreciacionmensual)<>0;

-- Controlamos si hubo error
DECLARE exit handler FOR SQLEXCEPTION, SQLWARNING
  BEGIN
  	SHOW WARNINGS limit 1;
    ROLLBACK;
    RESIGNAL;
  END;

-- Declaramos el control de salida del loop
DECLARE CONTINUE HANDLER FOR NOT FOUND SET termino = TRUE;

-- Abrimos el Cursor
OPEN Datos_Asiento;

-- Iniciamos la Transaccion
START TRANSACTION;

-- Leeemos el Cursor
read_loop: LOOP
FETCH Datos_Asiento INTO centros_costosid, concepto, valor, codigocontable;

-- Verificamos si no hay mas registros
IF termino THEN
LEAVE read_loop;
END IF;

SET diferencia = ROUND(diferencia+(Round(valor,2)),2);
-- Sumamos valores de debe y haber
IF valor<0 THEN
  SET haber = (haber + (Abs((valor))));
ELSE
  SET debe  = (debe + (Abs((valor))));
END IF;

-- INSERTAMOS LA CABECERA DEL ASIENTO
  IF gravocabecera=FALSE THEN
    -- Optenemos el nuevo secuencial
    call SP_Consulta_Secuencias_Internas('LIBRODIARIO',codigoasiento);
  
    -- Insertamos Registro Cabecera
    INSERT INTO libros_diarios 
    (
      codigoasiento, 
      fecha, 
      referencia, 
      concepto, 
      origen, 
      usuariocreacion, 
      fechacreacion
    ) 
    VALUES 
    (
      codigoasiento,
      dFecha,
      codigoasiento, 
      concepto,
      'Activos Fijos', 
      sUsuario, 
      NOW(3)
    );
   
   -- obtenemos el ultimo ID insertado
    SET libros_diariosid=(select LAST_INSERT_ID());
    
    -- Actualizamos el secuencial de libros diarios
    call SP_Actualiza_Secuencias_Internas('LIBRODIARIO');

    -- Ponemos que gravo la cabecera
    SET gravocabecera=TRUE;

  END IF;

-- INSERTAMOS LOS DETALLES
set valor = round(valor,2);
INSERT INTO libros_diarios_detalles
( 	
libros_diariosid,	
codigocontable,	
centros_costosid,	
referencia,	
concepto,	
importe
)
VALUES
( 
libros_diariosid,	
codigocontable,	
centros_costosid,	
codigoasiento,	
concepto,	
valor
 );

-- Toma la primer cuenta del asiento contable
IF cuenta_fija=0 THEN 
SET cuenta_fija = (select LAST_INSERT_ID());
END IF;

END LOOP;

CALL SP_Contabiliza_Verificar_Asiento(libros_diariosid,verificado);


-- Cuadramos el asiento contable si esta descuadrado
IF diferencia<0.11 AND diferencia>-0.11 AND diferencia<>0  THEN
UPDATE libros_diarios_detalles
SET
libros_diarios_detalles.importe = libros_diarios_detalles.importe-diferencia
WHERE
libros_diarios_detalles.libros_diarios_detallesid = cuenta_fija;
SET diferencia=0;
END IF;

-- Verificamos si el asiento esta cuadrado
IF diferencia<>0 THEN
SET verificado=0;
END IF;

-- Actualizamos el libro diario
SET debe = Round(debe,2);
SET haber = Round(haber,2);
UPDATE 
libros_diarios
SET
libros_diarios.debito = debe,
libros_diarios.credito = haber,
libros_diarios.mayorizado = verificado,
libros_diarios.verificado = verificado
WHERE
libros_diarios.libros_diariosid = libros_diariosid;


-- Actualizamos el ID del libro diario a el movimiento de Caja
UPDATE 
salidas 
SET 
salidas.asientocontable = libros_diariosid
WHERE 
salidas.movinventarios_tiposid <> 6 
AND salidas.asientocontable = 0 
AND salidas.salidasid = nDocumentoid;

UPDATE
activos_depreciaciones 
SET
activos_depreciaciones.libros_diariosid = libros_diariosid
WHERE
activos_depreciaciones.libros_diariosid = 0 AND activos_depreciaciones.activosid = nDocumentoid
AND YEAR(activos_depreciaciones.fecha) = year(dFecha) AND MONTH(activos_depreciaciones.fecha)  = MONTH(dFecha);

-- Finalizamos la transaccion
COMMIT;

-- Cerramos el Cursor
CLOSE Datos_Asiento;

-- Devolvemos el ID del Asiento Contable
select libros_diariosid;

END
;;
delimiter ;

-- ----------------------------
-- Procedure structure for SP_Contabiliza_Anular_Asiento
-- ----------------------------
DROP PROCEDURE IF EXISTS `SP_Contabiliza_Anular_Asiento`;
delimiter ;;
CREATE PROCEDURE `SP_Contabiliza_Anular_Asiento`(IN nDocumentoid BIGINT, IN sOrigen VARCHAR(255))
  SQL SECURITY INVOKER
BEGIN

  DECLARE vFechaAsiento date DEFAULT '0000-00-00';
  DECLARE vFechadesde date DEFAULT '0000-00-00';
  DECLARE vFechahasta date DEFAULT '0000-00-00';
  DECLARE vOrigenMod varchar(21) DEFAULT '';
  -- Controlamos si hubo error
  DECLARE EXIT HANDLER FOR SQLEXCEPTION, SQLWARNING
  BEGIN
  	SHOW WARNINGS limit 1;
    -- Cancelamos la transaccion
    ROLLBACK;
    -- Devolvemos el error de la transaccion
    RESIGNAL;
  END;
CASE sOrigen
    WHEN 'Facturacion' THEN SET vOrigenMod = 'Facturacion';
    WHEN 'Costo de Venta' THEN SET vOrigenMod = 'Facturacion';
    WHEN 'Entregas' THEN SET vOrigenMod = 'Facturacion';
    WHEN ('Caja') THEN SET vOrigenMod = 'Caja';
    WHEN ('Cobros') THEN SET vOrigenMod = 'Cartera';
    WHEN ('Compras') THEN SET vOrigenMod = 'Compras';
WHEN ('Retenciones') THEN SET vOrigenMod = 'Compras';    
    WHEN ('Pagos') THEN SET vOrigenMod = 'Pagos';
    WHEN ('Banco') THEN SET vOrigenMod = 'Bancos';
    WHEN ('Ingresos') THEN SET vOrigenMod = 'Ingresos';
    WHEN ('Salidas') THEN SET vOrigenMod = 'Salidas';
    WHEN ('Depositos') THEN SET vOrigenMod = 'Depositos';
    WHEN ('Tarjetas_Retenciones') THEN SET vOrigenMod = 'Vouchers';
    WHEN ('Nomina') THEN SET vOrigenMod = 'Nomina';
    WHEN ('Activos') THEN SET vOrigenMod = 'Activos';
    WHEN 'Garantias' THEN SET vOrigenMod = 'Garantias';
    WHEN 'Talleres' THEN SET vOrigenMod = 'Talleres';
    WHEN ('Contabilidad') THEN SET vOrigenMod = 'Contabilidad'; 
    ELSE SET vOrigenMod = sOrigen;
  END CASE;
  	
  SET vFechaAsiento = (SELECT
      libros_diarios.fecha
    FROM libros_diarios
    WHERE libros_diarios.libros_diariosid = nDocumentoid
    LIMIT 1);

  SET vFechahasta =IFNULL( (SELECT
      contabilidad_bloqueo.fecha_bloqueo 
    FROM contabilidad_bloqueo
    WHERE contabilidad_bloqueo.modulos = vOrigenMod
    LIMIT 1), '2000-12-31');

  IF vFechaAsiento > vFechahasta THEN
  -- Iniciamos la Transaccion
  START TRANSACTION;

  -- Actualiza el Detalles del asiento colocando anulados
  UPDATE libros_diarios_detalles SET	libros_diarios_detalles.anulado = 1	WHERE	libros_diarios_detalles.libros_diariosid = nDocumentoid;

  -- Elimina la Cabecera del asiento
  UPDATE libros_diarios	SET	libros_diarios.mayorizado = 0, libros_diarios.verificado = 0,	libros_diarios.anulado = 1 WHERE libros_diarios.libros_diariosid = nDocumentoid;

 -- Ejecutamos la limpieza de los modulos
CASE 

WHEN sOrigen IN ('Facturacion') THEN
      UPDATE facturas					      SET facturas.asientocontable = 0				        WHERE facturas.asientocontable = nDocumentoid;
      UPDATE movcaja 					      SET movcaja.asientocontable = 0 				        WHERE movcaja.asientocontable = nDocumentoid;
    	UPDATE movbanco 				      SET movbanco.asientocontable = 0 				        WHERE movbanco.asientocontable = nDocumentoid;
    	UPDATE cuentasporcobrar 		  SET cuentasporcobrar.asientocontable = 0 		    WHERE cuentasporcobrar.asientocontable = nDocumentoid;
WHEN sOrigen IN ('Costo de Venta') THEN
      UPDATE facturas					      SET facturas.asientocosto = 0				        WHERE facturas.asientocosto = nDocumentoid;

WHEN sOrigen IN ('Entregas') THEN
    UPDATE entregas					      SET entregas.asientocontable = 0				        WHERE entregas.asientocontable = nDocumentoid;

WHEN sOrigen IN ('Cobros') THEN
    	UPDATE cobros					        SET cobros.asientocontable = 0					        WHERE cobros.asientocontable = nDocumentoid;
        UPDATE movcaja 					      SET movcaja.asientocontable = 0 				        WHERE movcaja.asientocontable = nDocumentoid;
    	  UPDATE movbanco 				      SET movbanco.asientocontable = 0 				        WHERE movbanco.asientocontable = nDocumentoid;
    	  UPDATE cuentasporcobrar 		  SET cuentasporcobrar.asientocontable = 0 		    WHERE cuentasporcobrar.asientocontable = nDocumentoid;

WHEN sOrigen IN ('Compras') THEN
 UPDATE compras SET compras.asientocontable_retencion = 0       WHERE compras.asientocontable_retencion = nDocumentoid AND compras.asientocontable = compras.asientocontable_retencion;

    	UPDATE compras					      SET compras.asientocontable = 0					        WHERE compras.asientocontable = nDocumentoid;
    	UPDATE compras_recepciones		SET compras_recepciones.asientocontable = 0		  WHERE compras_recepciones.asientocontable = nDocumentoid;
      UPDATE movcaja 					      SET movcaja.asientocontable = 0 				        WHERE movcaja.asientocontable = nDocumentoid;
    	UPDATE movbanco 				      SET movbanco.asientocontable = 0 				        WHERE movbanco.asientocontable = nDocumentoid;
      UPDATE cuentasporpagar 			  SET cuentasporpagar.asientocontable = 0			    WHERE cuentasporpagar.asientocontable = nDocumentoid;
 WHEN sOrigen IN ('Retenciones') THEN
UPDATE compras					      SET compras.asientocontable = 0				          WHERE compras.asientocontable_retencion = nDocumentoid AND compras.asientocontable = compras.asientocontable_retencion; 
       UPDATE movcaja               SET movcaja.asientocontable = 0  WHERE movcaja.asientocontable = nDocumentoid;
        UPDATE movbanco SET movbanco.asientocontable = 0   WHERE movbanco.asientocontable = nDocumentoid;

 
    	UPDATE compras					      SET compras.asientocontable_retencion = 0				WHERE compras.asientocontable_retencion = nDocumentoid;
      UPDATE cuentasporpagar 			  SET cuentasporpagar.asientocontable = 0			    WHERE cuentasporpagar.asientocontable = nDocumentoid;
WHEN sOrigen IN ('Pagos') THEN
      UPDATE pagos					        SET pagos.asientocontable = 0					          WHERE pagos.asientocontable = nDocumentoid;
      UPDATE movcaja 					      SET movcaja.asientocontable = 0 				        WHERE movcaja.asientocontable = nDocumentoid;
    	UPDATE movbanco 				      SET movbanco.asientocontable = 0 				        WHERE movbanco.asientocontable = nDocumentoid;
      UPDATE cuentasporpagar 			  SET cuentasporpagar.asientocontable = 0			    WHERE cuentasporpagar.asientocontable = nDocumentoid;

WHEN sOrigen IN ('Salidas') THEN
    	UPDATE salidas					      SET salidas.asientocontable = 0					        WHERE salidas.asientocontable = nDocumentoid;

WHEN sOrigen IN ('Ingresos') THEN
    	UPDATE ingresos					      SET ingresos.asientocontable = 0				        WHERE ingresos.asientocontable = nDocumentoid;

WHEN sOrigen IN ('Depositos') THEN
    	UPDATE depositos				      SET	depositos.asientocontable = 0				        WHERE depositos.asientocontable = nDocumentoid;
      UPDATE movcaja 					      SET movcaja.asientocontable = 0 				        WHERE movcaja.asientocontable = nDocumentoid;
    	UPDATE movbanco 				      SET movbanco.asientocontable = 0 				        WHERE movbanco.asientocontable = nDocumentoid;

WHEN sOrigen IN ('Tarjetas_Retenciones') THEN
    	UPDATE tarjetas_retenciones		SET	tarjetas_retenciones.asientocontable = 0	  WHERE tarjetas_retenciones.asientocontable = nDocumentoid;
      UPDATE movcaja 					      SET movcaja.asientocontable = 0 				        WHERE movcaja.asientocontable = nDocumentoid;
    	UPDATE movbanco 				      SET movbanco.asientocontable = 0 				        WHERE movbanco.asientocontable = nDocumentoid;

WHEN sOrigen IN ('Nomina') THEN
      UPDATE nomina_roles				    SET	nomina_roles.asientocontable = 0			      WHERE nomina_roles.asientocontable = nDocumentoid;
      UPDATE movcaja 					      SET movcaja.asientocontable = 0 				        WHERE movcaja.asientocontable = nDocumentoid;
    	UPDATE movbanco 				      SET movbanco.asientocontable = 0 				        WHERE movbanco.asientocontable = nDocumentoid;

WHEN sOrigen IN ('Activos') THEN
      UPDATE activos_depreciaciones SET	activos_depreciaciones.libros_diariosid=0 	WHERE activos_depreciaciones.libros_diariosid = nDocumentoid;

WHEN sOrigen IN ('Talleres') THEN
    UPDATE talleres_seguimientos  SET talleres_seguimientos.asientocontable=0     WHERE talleres_seguimientos.asientocontable = nDocumentoid;
WHEN sOrigen IN ('Banco') THEN
    	UPDATE movbanco 				      SET movbanco.asientocontable = 0 				        WHERE movbanco.asientocontable = nDocumentoid;
WHEN sOrigen IN ('Caja') THEN
      UPDATE movcaja 					      SET movcaja.asientocontable = 0 				        WHERE movcaja.asientocontable = nDocumentoid;
WHEN sOrigen IN ('Garantias') THEN
    UPDATE garantias_seguimientos  SET garantias_seguimientos.asientocontable=0     WHERE garantias_seguimientos.asientocontable = nDocumentoid;
 
WHEN sOrigen IN ('Contabilidad') THEN
    	UPDATE tarjetas_retenciones		SET	tarjetas_retenciones.asientocontable = 0	  WHERE tarjetas_retenciones.asientocontable = nDocumentoid;
     	 UPDATE movcaja 					      SET movcaja.asientocontable = 0 				        WHERE movcaja.asientocontable = nDocumentoid;
    	UPDATE movbanco 				      SET movbanco.asientocontable = 0 				        WHERE movbanco.asientocontable = nDocumentoid;
     	 UPDATE nomina_roles				    SET	nomina_roles.asientocontable = 0			      WHERE nomina_roles.asientocontable = nDocumentoid;

UPDATE activos_depreciaciones SET	activos_depreciaciones.libros_diariosid=0 	WHERE activos_depreciaciones.libros_diariosid = nDocumentoid;
    UPDATE talleres_seguimientos  SET talleres_seguimientos.asientocontable=0     WHERE talleres_seguimientos.asientocontable = nDocumentoid;

    	UPDATE ingresos					      SET ingresos.asientocontable = 0				        WHERE ingresos.asientocontable = nDocumentoid;

    	UPDATE salidas					      SET salidas.asientocontable = 0					        WHERE salidas.asientocontable = nDocumentoid;

    	UPDATE depositos				      SET	depositos.asientocontable = 0				        WHERE depositos.asientocontable = nDocumentoid;	

     	UPDATE pagos					        SET pagos.asientocontable = 0					          WHERE pagos.asientocontable = nDocumentoid;

      	UPDATE cuentasporpagar 			  SET cuentasporpagar.asientocontable = 0			    WHERE cuentasporpagar.asientocontable = nDocumentoid;

    	UPDATE compras					      SET compras.asientocontable = 0					        WHERE compras.asientocontable = nDocumentoid;
UPDATE compras					      SET compras.asientocontable_retencion = 0			WHERE compras.asientocontable_retencion = nDocumentoid;    	
UPDATE compras_recepciones		SET compras_recepciones.asientocontable = 0		  where compras_recepciones.asientocontable = nDocumentoid;
    UPDATE cobros					        SET cobros.asientocontable = 0					        WHERE cobros.asientocontable = nDocumentoid;

    	UPDATE cuentasporcobrar 		  SET cuentasporcobrar.asientocontable = 0 		    WHERE cuentasporcobrar.asientocontable = nDocumentoid;
    UPDATE entregas					      SET entregas.asientocontable = 0				        WHERE entregas.asientocontable = nDocumentoid;
UPDATE facturas					      SET facturas.asientocontable = 0				        WHERE facturas.asientocontable = nDocumentoid;
      	UPDATE facturas					      SET facturas.asientocosto = 0				        WHERE facturas.asientocosto = nDocumentoid;
UPDATE garantias_seguimientos SET garantias_seguimientos.asientocontable=0     WHERE garantias_seguimientos.asientocontable = nDocumentoid;
 
END CASE;

  -- Finalizamos la transaccion
  COMMIT;

  SELECT 1 AS resultado;
  ELSE

  SELECT 0 AS resultado;
  END IF;

END
;;
delimiter ;

-- ----------------------------
-- Procedure structure for SP_Contabiliza_Anular_Asiento_Agrupado
-- ----------------------------
DROP PROCEDURE IF EXISTS `SP_Contabiliza_Anular_Asiento_Agrupado`;
delimiter ;;
CREATE PROCEDURE `SP_Contabiliza_Anular_Asiento_Agrupado`(IN nDocumentoid longtext, IN sOrigen VARCHAR(255), IN sRegistro JSON)
  SQL SECURITY INVOKER
BEGIN
DECLARE vFechaAsiento date DEFAULT '0000-00-00';
 	DECLARE vFechadesde date DEFAULT '0000-00-00';
  	DECLARE vFechahasta date DEFAULT '0000-00-00';
 	DECLARE vContador INT DEFAULT FALSE;
  
# VARIABLE DE LOS DATOS DE LA AUDITORIA
  DECLARE p_sis_subcategoriasid int(11) DEFAULT 0;
  DECLARE p_sis_empresasid int(11) DEFAULT 0;
  DECLARE p_sis_usuariosid varchar(20) DEFAULT '';
  DECLARE p_equipo varchar(50) DEFAULT '';
  DECLARE p_tipooperacion varchar(50) DEFAULT '';
  DECLARE p_detalle longtext;  

  -- Controlamos si hubo error
  DECLARE EXIT HANDLER FOR SQLEXCEPTION, SQLWARNING
  BEGIN
    SHOW WARNINGS LIMIT 1;
    -- Cancelamos la transaccion
    ROLLBACK;
    -- Devolvemos el error de la transaccion
    RESIGNAL;
  END;

  #Se ubica los origenes de contabilidad con los de bloqueo de periodos

   -- Iniciamos la Transaccion
   
   START TRANSACTION;
-- Eliminamos la tabla usuario_temporal

-- verificamos el periodo de bloqueo
    DROP TEMPORARY TABLE IF EXISTS tabla_temporal_anular_bloqueo;

CREATE TEMPORARY TABLE tabla_temporal_anular_bloqueo AS
SELECT *
FROM JSON_TABLE(nDocumentoid, -- Reemplaza esto con tu arreglo JSON de IDs
  '$[*]' COLUMNS(libros_diariosid INT PATH '$')
) AS jt;

-- creamos la tabla con datos filtrados el contabilidad_bloqueo
DROP TEMPORARY TABLE IF EXISTS tabla_temporal_anular;

CREATE TEMPORARY TABLE tabla_temporal_anular AS
SELECT tabla_temporal_anular_bloqueo.libros_diariosid FROM tabla_temporal_anular_bloqueo INNER JOIN libros_diarios ON tabla_temporal_anular_bloqueo.libros_diariosid=libros_diarios.libros_diariosid LEFT JOIN contabilidad_bloqueo
ON (CASE WHEN libros_diarios.origen='Recepciones' THEN 'Compras' WHEN libros_diarios.origen='Entregas' THEN 'Facturacion' WHEN libros_diarios.origen='Costo de Venta' THEN 'Facturacion' WHEN libros_diarios.origen='Cobros' THEN 'Cartera' WHEN libros_diarios.origen='Ajuste CXC' THEN 'Cartera' WHEN libros_diarios.origen='Ajuste CXP' THEN 'Pagos' WHEN libros_diarios.origen='Facturacion Ret' THEN 'Cartera' WHEN libros_diarios.origen='Retencion AC' THEN 'Cartera' WHEN libros_diarios.origen='Retencion AJ' THEN 'Cartera' WHEN libros_diarios.origen='Activos Fijos' THEN 'Activos' WHEN libros_diarios.origen='Retenciones' THEN 'Compras' WHEN libros_diarios.origen='Retenciones Vou' THEN 'Vouchers' ELSE libros_diarios.origen END)=contabilidad_bloqueo.modulos WHERE (contabilidad_bloqueo.modulos IS NULL OR libros_diarios.fecha>contabilidad_bloqueo.fecha_bloqueo OR contabilidad_bloqueo.fecha_bloqueo is NULL);
SET vContador = (SELECT COUNT(*) AS cantidad_registros FROM tabla_temporal_anular);


UPDATE libros_diarios_detalles INNER JOIN tabla_temporal_anular ON libros_diarios_detalles.libros_diariosid=tabla_temporal_anular.libros_diariosid  SET	libros_diarios_detalles.anulado = 1;

  -- Elimina la Cabecera del asiento
  UPDATE libros_diarios INNER JOIN tabla_temporal_anular ON libros_diarios.libros_diariosid=tabla_temporal_anular.libros_diariosid 	SET	libros_diarios.mayorizado = 0, libros_diarios.verificado = 0,	libros_diarios.anulado = 1;



CASE 
 
WHEN sOrigen IN ('Contabilidad') THEN
UPDATE tarjetas_retenciones INNER JOIN tabla_temporal_anular ON tarjetas_retenciones.asientocontable=tabla_temporal_anular.libros_diariosid
            SET tarjetas_retenciones.asientocontable = 0;
            UPDATE movcaja INNER JOIN tabla_temporal_anular ON tabla_temporal_anular.libros_diariosid=movcaja.asientocontable
            SET movcaja.asientocontable = 0;
            UPDATE movbanco INNER JOIN tabla_temporal_anular ON tabla_temporal_anular.libros_diariosid=movbanco.asientocontable
            SET movbanco.asientocontable = 0;
            UPDATE nomina_roles INNER JOIN tabla_temporal_anular ON tabla_temporal_anular.libros_diariosid=nomina_roles.asientocontable
            SET nomina_roles.asientocontable = 0; 

            UPDATE activos_depreciaciones
            SET activos_depreciaciones.libros_diariosid = 0
            WHERE activos_depreciaciones.libros_diariosid IN (SELECT tabla_temporal_anular.libros_diariosid FROM tabla_temporal_anular);

            UPDATE talleres_seguimientos INNER JOIN tabla_temporal_anular ON tabla_temporal_anular.libros_diariosid=talleres_seguimientos.asientocontable
            SET talleres_seguimientos.asientocontable = 0;

            UPDATE ingresos INNER JOIN tabla_temporal_anular ON tabla_temporal_anular.libros_diariosid=ingresos.asientocontable
            SET ingresos.asientocontable = 0; 

            UPDATE salidas INNER JOIN tabla_temporal_anular ON tabla_temporal_anular.libros_diariosid=salidas.asientocontable
            SET salidas.asientocontable = 0; 

            UPDATE depositos INNER JOIN tabla_temporal_anular ON tabla_temporal_anular.libros_diariosid=depositos.asientocontable
            SET depositos.asientocontable = 0;

            UPDATE pagos INNER JOIN tabla_temporal_anular ON tabla_temporal_anular.libros_diariosid=pagos.asientocontable
            SET pagos.asientocontable = 0;

            UPDATE cuentasporpagar INNER JOIN tabla_temporal_anular ON tabla_temporal_anular.libros_diariosid=cuentasporpagar.asientocontable
            SET cuentasporpagar.asientocontable = 0;

            UPDATE compras INNER JOIN tabla_temporal_anular ON tabla_temporal_anular.libros_diariosid=compras.asientocontable
            SET compras.asientocontable = 0; 
    		UPDATE compras INNER JOIN tabla_temporal_anular ON tabla_temporal_anular.libros_diariosid=compras.asientocontable_retencion
            SET compras.asientocontable_retencion = 0; 
            
            UPDATE compras_recepciones INNER JOIN tabla_temporal_anular ON tabla_temporal_anular.libros_diariosid=compras_recepciones.asientocontable
            SET compras_recepciones.asientocontable = 0;
            UPDATE cobros INNER JOIN tabla_temporal_anular ON tabla_temporal_anular.libros_diariosid=cobros.asientocontable
            SET cobros.asientocontable = 0;

            UPDATE cuentasporcobrar INNER JOIN tabla_temporal_anular ON tabla_temporal_anular.libros_diariosid=cuentasporcobrar.asientocontable
            SET cuentasporcobrar.asientocontable = 0;
            UPDATE entregas INNER JOIN tabla_temporal_anular ON tabla_temporal_anular.libros_diariosid=entregas.asientocontable
            SET entregas.asientocontable = 0;
            UPDATE facturas INNER JOIN tabla_temporal_anular ON tabla_temporal_anular.libros_diariosid=facturas.asientocontable
            SET facturas.asientocontable = 0; 
UPDATE facturas INNER JOIN tabla_temporal_anular ON tabla_temporal_anular.libros_diariosid=facturas.asientocosto
            SET facturas.asientocosto = 0;
            UPDATE garantias_seguimientos INNER JOIN tabla_temporal_anular ON tabla_temporal_anular.libros_diariosid=garantias_seguimientos.asientocontable
            SET garantias_seguimientos.asientocontable = 0;
END CASE;

IF vContador > 0 THEN
SET p_sis_subcategoriasid = JSON_UNQUOTE(JSON_EXTRACT(sRegistro, '$.m_sis_subcategoriasid'));
        SET p_sis_empresasid = JSON_UNQUOTE(JSON_EXTRACT(sRegistro, '$.m_sis_empresasid'));
        SET p_sis_usuariosid = JSON_UNQUOTE(JSON_EXTRACT(sRegistro, '$.m_sis_usuariosid'));
        SET p_equipo = JSON_UNQUOTE(JSON_EXTRACT(sRegistro, '$.m_equipo'));
SET p_detalle =JSON_UNQUOTE(JSON_EXTRACT(sRegistro, '$.m_detalle'));
SET p_tipooperacion = 'E';
# INSERTAMOS LA AUDITORIA
         CALL sistemaperseo.SP_ABC_sis_log_sistema(p_sis_subcategoriasid, p_sis_empresasid, p_sis_usuariosid, p_tipooperacion, p_detalle, p_equipo);
END IF;
 COMMIT;

  SELECT 1 AS resultado;

END
;;
delimiter ;

-- ----------------------------
-- Procedure structure for SP_Contabiliza_Banco_Agrupado
-- ----------------------------
DROP PROCEDURE IF EXISTS `SP_Contabiliza_Banco_Agrupado`;
delimiter ;;
CREATE PROCEDURE `SP_Contabiliza_Banco_Agrupado`(IN dFechaDesde DATE, IN dFechaHasta DATE, IN sUsuario VARCHAR(25))
  MODIFIES SQL DATA 
BEGIN

-- Declaramos variables de Cursor
DECLARE termino INT DEFAULT FALSE;
-- DECLARE fechamovimiento date;
DECLARE usuariocreacion varchar(25);
DECLARE centros_costosid int(11);
DECLARE concepto varchar(200);
DECLARE referencia varchar(15);
DECLARE valor decimal(16,8) DEFAULT 0;
DECLARE codigocontable varchar(30);
DECLARE codigoasiento varchar(10);
DECLARE gravocabecera INT DEFAULT FALSE;
DECLARE libros_diariosid bigint DEFAULT 0;
DECLARE debe  decimal(16,8) DEFAULT 0;
DECLARE haber decimal(16,8) DEFAULT 0;
DECLARE diferencia decimal(12,2) DEFAULT 0;
DECLARE verificado INT DEFAULT TRUE;
DECLARE cuenta_fija bigint DEFAULT 0;

DECLARE Datos_Asiento CURSOR FOR
SELECT
movbanco.centros_costosid AS centros_costosid,
LEFT(concat(movbanco.concepto,' ',movbanco.beneficiario),200)  AS concepto,
movbanco.documentoorigen AS referencia,
SUM(movbanco.importe) AS valor,
bancos.codigocontable AS codigocontable
FROM
bancos
INNER JOIN
movbanco
ON (bancos.bancosid = movbanco.bancosid)
WHERE
movbanco.origen = 'Bancos'
AND movbanco.fechamovimiento BETWEEN dFechaDesde AND dFechaHasta 
AND movbanco.asientocontable = 0
GROUP BY
bancos.codigocontable
HAVING
SUM(movbanco.importe)<>0
union
SELECT
movbanco.centros_costosid AS centros_costosid,
LEFT(concat(movbanco.concepto,' ',movbanco.beneficiario),200)  AS concepto,
movbanco.documentoorigen AS referencia,
SUM(-movbanco.importe) AS valor,
movimientos_conceptos.codigocontable AS codigocontable
FROM
movimientos_conceptos
INNER JOIN
movbanco
ON (movimientos_conceptos.movimientos_conceptosid = movbanco.movimientos_conceptosid)
WHERE
movbanco.origen = 'Bancos'
AND movbanco.fechamovimiento BETWEEN dFechaDesde AND dFechaHasta 
AND movbanco.asientocontable = 0
GROUP BY
movimientos_conceptos.codigocontable
HAVING
SUM(movbanco.importe)<>0;



-- Controlamos si hubo error
DECLARE exit handler FOR SQLEXCEPTION, SQLWARNING
  BEGIN
  	SHOW WARNINGS limit 1;
    ROLLBACK;
    RESIGNAL;
  END;

-- Declaramos el control de salida del loop
DECLARE CONTINUE HANDLER FOR NOT FOUND SET termino = TRUE;

-- Abrimos el Cursor
OPEN Datos_Asiento;

-- Iniciamos la Transaccion
START TRANSACTION;

-- Leeemos el Cursor
read_loop: LOOP
FETCH Datos_Asiento INTO centros_costosid, concepto, referencia, valor, codigocontable;

-- Verificamos si no hay mas registros
IF termino THEN
LEAVE read_loop;
END IF;

SET diferencia = diferencia+(Round(valor,2));
-- Sumamos valores de debe y haber
IF valor<0 THEN
  SET haber = (haber + (Abs((valor))));
ELSE
  SET debe  = (debe + (Abs((valor))));
END IF;

-- INSERTAMOS LA CABECERA DEL ASIENTO
  IF gravocabecera=FALSE THEN
    -- Optenemos el nuevo secuencial
    call SP_Consulta_Secuencias_Internas('LIBRODIARIO',codigoasiento);
  
    -- Insertamos Registro Cabecera
    INSERT INTO libros_diarios 
    (
      codigoasiento, 
      fecha, 
      referencia, 
      concepto, 
      origen, 
      usuariocreacion, 
      fechacreacion
    ) 
    VALUES 
    (
      codigoasiento,
      dFechaHasta,
      codigoasiento, 
      CONCAT('Movimientos de Bancos de ',DATE_FORMAT(dFechaDesde,"%d-%m-%Y"),' a ',DATE_FORMAT(dFechaHasta,"%d-%m-%Y")),
      'Bancos', 
      sUsuario, 
      NOW()
    );
   
   -- obtenemos el ultimo ID insertado
    SET libros_diariosid=(select LAST_INSERT_ID());
    
    -- Actualizamos el secuencial de libros diarios
    call SP_Actualiza_Secuencias_Internas('LIBRODIARIO');

    -- Ponemos que gravo la cabecera
    SET gravocabecera=TRUE;

  END IF;

-- INSERTAMOS LOS DETALLES
set valor = round(valor,2);
INSERT INTO libros_diarios_detalles
( 	
libros_diariosid,	
codigocontable,	
centros_costosid,	
referencia,	
concepto,	
importe
)
VALUES
( 
libros_diariosid,	
codigocontable,	
centros_costosid,	
referencia,	
concepto,	
valor
 );

-- Toma la primer cuenta del asiento contable
IF cuenta_fija=0 THEN 
SET cuenta_fija = (select LAST_INSERT_ID());
END IF;

END LOOP;

CALL SP_Contabiliza_Verificar_Asiento(libros_diariosid,verificado);


-- Cuadramos el asiento contable si esta descuadrado
IF diferencia<0.11 AND diferencia>-0.11 AND diferencia<>0  THEN
UPDATE libros_diarios_detalles
SET
libros_diarios_detalles.importe = libros_diarios_detalles.importe-diferencia
WHERE
libros_diarios_detalles.libros_diarios_detallesid = cuenta_fija;
SET diferencia=0;
END IF;

-- Verificamos si el asiento esta cuadrado
IF diferencia<>0 THEN
SET verificado=0;
END IF;

-- Actualizamos el libro diario
SET debe = Round(debe,2);
SET haber = Round(haber,2);
UPDATE 
libros_diarios
SET
libros_diarios.debito = debe,
libros_diarios.credito = haber,
libros_diarios.mayorizado = verificado,
libros_diarios.verificado = verificado
WHERE
libros_diarios.libros_diariosid = libros_diariosid;


-- Actualizamos el ID del libro diario a el movimiento de Caja
UPDATE
movbanco 
SET
movbanco.asientocontable=libros_diariosid,
movbanco.fechamodificacion = movbanco.fechamodificacion 
WHERE
movbanco.asientocontable = 0
AND movbanco.fechamovimiento BETWEEN dFechaDesde AND dFechaHasta
AND movbanco.origen = 'Bancos';


-- Finalizamos la transaccion
COMMIT;

-- Cerramos el Cursor
CLOSE Datos_Asiento;

-- Devolvemos el ID del Asiento Contable
select libros_diariosid;

END
;;
delimiter ;

-- ----------------------------
-- Procedure structure for SP_Contabiliza_Banco_Individual
-- ----------------------------
DROP PROCEDURE IF EXISTS `SP_Contabiliza_Banco_Individual`;
delimiter ;;
CREATE PROCEDURE `SP_Contabiliza_Banco_Individual`(IN nDocumentoid BIGINT, IN sUsuario VARCHAR(25), IN ssorigen VARCHAR(25))
  MODIFIES SQL DATA 
BEGIN

-- Declaramos variables de Cursor
DECLARE termino INT DEFAULT FALSE;
DECLARE fechamovimiento date;
DECLARE usuariocreacion varchar(25);
DECLARE centros_costosid int(11);
DECLARE concepto varchar(200);
DECLARE referencia varchar(15);
DECLARE valor decimal(16,8) DEFAULT 0;
DECLARE codigocontable varchar(30);
DECLARE codigoasiento varchar(10);
DECLARE gravocabecera INT DEFAULT FALSE;
DECLARE libros_diariosid bigint DEFAULT 0;
DECLARE debe  decimal(16,8) DEFAULT 0;
DECLARE haber decimal(16,8) DEFAULT 0;
DECLARE diferencia decimal(12,2) DEFAULT 0;
DECLARE verificado INT DEFAULT TRUE;
DECLARE cuenta_fija bigint DEFAULT 0;
DECLARE sorigen varchar(30) DEFAULT('Bancos');
DECLARE Datos_Asiento CURSOR FOR
SELECT
movbanco.fechamovimiento AS fechamovimiento,
movbanco.centros_costosid AS centros_costosid,
LEFT(CONCAT(movbanco.concepto,' ',movbanco.beneficiario),200)  AS concepto,
movbanco.documentoorigen AS referencia,
SUM(movbanco.importe) AS valor,
bancos.codigocontable AS codigocontable
FROM
bancos
INNER JOIN
movbanco
ON (bancos.bancosid = movbanco.bancosid)
WHERE
movbanco.origen = sorigen
AND movbanco.movbancosid = nDocumentoid
AND movbanco.movimientos_conceptosid NOT IN(29,30,33)
AND movbanco.asientocontable = 0
group by
bancos.codigocontable
HAVING
SUM(movbanco.importe)<>0

UNION
SELECT
  movbanco.fechamovimiento AS fechamovimiento,
movbanco.centros_costosid AS centros_costosid,
LEFT(CONCAT(movbanco.concepto,' ',movbanco.beneficiario),200)  AS concepto,
movbanco.documentoorigen AS referencia,
SUM(-movbanco.importe) AS valor,
movimientos_conceptos.codigocontable AS codigocontable
FROM
movimientos_conceptos
INNER JOIN
movbanco
ON (movimientos_conceptos.movimientos_conceptosid = movbanco.movimientos_conceptosid)
WHERE
movbanco.origen = sorigen
AND movbanco.movbancosid = nDocumentoid
AND movbanco.movimientos_conceptosid NOT IN(29,30,33)
AND movbanco.asientocontable = 0
group by
movimientos_conceptos.codigocontable
HAVING
SUM(movbanco.importe)<>0

UNION

SELECT
movbanco.fechamovimiento AS fechamovimiento,
movbanco.centros_costosid AS centros_costosid,
LEFT(CONCAT(movbanco.concepto,' ',movbanco.beneficiario),200)  AS concepto,
movbanco.documentoorigen AS referencia,
SUM(movbanco.importe) AS valor,
bancos.codigocontable AS codigocontable
FROM
bancos
INNER JOIN
movbanco
ON (bancos.bancosid = movbanco.bancosid)

WHERE
movbanco.origen = sorigen
AND movbanco.movimientos_conceptosid IN (29,30)
AND movbanco.documentosid = nDocumentoid
AND movbanco.asientocontable = 0
group by
bancos.codigocontable
HAVING
SUM(movbanco.importe)<>0

UNION
SELECT
  cobros.fechaemision AS fechamovimiento,
cobros.centros_costosid AS centros_costosid,
LEFT(CONCAT(cobros.concepto,' ',cobros.cobroscodigo),200)  AS concepto,
movbanco.documentoorigen AS referencia,
-SUM(movbanco.importe) AS valor,
movimientos_conceptos.codigocontable AS codigocontable
FROM
movimientos_conceptos
INNER JOIN
movbanco
ON (movimientos_conceptos.movimientos_conceptosid = movbanco.movimientos_conceptosid),
cobros
WHERE
movbanco.origen = sorigen
AND cobros.cobrosid = movbanco.documentosid
AND movbanco.movimientos_conceptosid IN (29,30)
AND movbanco.documentosid =  nDocumentoid
AND movbanco.asientocontable = 0
group by
movimientos_conceptos.codigocontable
HAVING
SUM(movbanco.importe)<>0



UNION

SELECT
movbanco.fechamovimiento AS fechamovimiento,
movbanco.centros_costosid AS centros_costosid,
LEFT(CONCAT(movbanco.concepto,' ',movbanco.beneficiario),200)  AS concepto,
movbanco.documentoorigen AS referencia,
SUM(movbanco.importe) AS valor,
bancos.codigocontable AS codigocontable
FROM
bancos
INNER JOIN
movbanco
ON (bancos.bancosid = movbanco.bancosid),
cobros

WHERE
movbanco.origen = sorigen
AND movbanco.movimientos_conceptosid IN (33)
AND movbanco.documentosid = nDocumentoid
AND cobros.cobrosid = movbanco.documentosid
AND movbanco.asientocontable = 0
group by
bancos.codigocontable
HAVING
SUM(movbanco.importe)<>0

UNION
SELECT
  cobros.fechaemision AS fechamovimiento,
cobros.centros_costosid AS centros_costosid,
LEFT(CONCAT(cobros.concepto,' ',cobros.cobroscodigo),200)  AS concepto,
movbanco.documentoorigen AS referencia,
CASE WHEN cobros.tipo = 'AB' THEN 
-SUM(cobros_detalles.capital) 
ELSE 
SUM(cobros_detalles.capital) 
END AS valor,
movimientos_conceptos.codigocontable AS codigocontable
FROM
movimientos_conceptos
INNER JOIN
movbanco
ON (movimientos_conceptos.movimientos_conceptosid = 30),
cobros
INNER JOIN 
cobros_detalles
ON (cobros.cobrosid = cobros_detalles.cobrosid)
WHERE
movbanco.origen = sorigen
AND cobros.cobrosid = movbanco.documentosid
AND movbanco.movimientos_conceptosid IN (33)
AND movbanco.documentosid =  nDocumentoid
AND movbanco.asientocontable = 0
group by
movimientos_conceptos.codigocontable
HAVING
SUM(cobros_detalles.capital)<>0
UNION

SELECT
  cobros.fechaemision AS fechamovimiento,
cobros.centros_costosid AS centros_costosid,
LEFT(CONCAT(cobros.concepto,' ',cobros.cobroscodigo),200)  AS concepto,
movbanco.documentoorigen AS referencia,
CASE WHEN cobros.tipo = 'AB' THEN 
-SUM(cobros_detalles.interes)
ELSE 
SUM(cobros_detalles.interes)
END AS valor,
movimientos_conceptos.codigocontable AS codigocontable
FROM
movimientos_conceptos
INNER JOIN
movbanco
ON (movimientos_conceptos.movimientos_conceptosid = 32),
cobros
INNER JOIN 
cobros_detalles
ON (cobros.cobrosid = cobros_detalles.cobrosid)
WHERE
movbanco.origen = sorigen
AND movbanco.documentosid = nDocumentoid
AND cobros.cobrosid = movbanco.documentosid
AND movbanco.movimientos_conceptosid IN (33)
AND movbanco.asientocontable = 0
group by
movimientos_conceptos.codigocontable
HAVING
SUM(cobros_detalles.interes)<>0


UNION

SELECT
  cobros.fechaemision AS fechamovimiento,
cobros.centros_costosid AS centros_costosid,
LEFT(CONCAT(cobros.concepto,' ',cobros.cobroscodigo),200)  AS concepto,
movbanco.documentoorigen AS referencia,
CASE WHEN cobros.tipo = 'AB' THEN 
-SUM(cobros_detalles.importe)
ELSE 
SUM(cobros_detalles.importe)
END AS valor,
movimientos_conceptos.codigocontable AS codigocontable
FROM
movimientos_conceptos
INNER JOIN
movbanco
ON (movimientos_conceptos.movimientos_conceptosid = 6),
cobros
INNER JOIN 
cobros_detalles
ON (cobros.cobrosid = cobros_detalles.cobrosid)
WHERE
movbanco.origen = sorigen
AND movbanco.documentosid = nDocumentoid
AND cobros.cobrosid = movbanco.documentosid
AND movbanco.movimientos_conceptosid IN (33)
AND cobros_detalles.tipo = 5
AND movbanco.asientocontable = 0
group by
movimientos_conceptos.codigocontable
HAVING
SUM(cobros_detalles.importe)<>0;







-- Controlamos si hubo error
DECLARE exit handler FOR SQLEXCEPTION, SQLWARNING
  BEGIN
  	SHOW WARNINGS limit 1;
    ROLLBACK;
    RESIGNAL;
  END;

-- Declaramos el control de salida del loop
DECLARE CONTINUE HANDLER FOR NOT FOUND SET termino = TRUE;
IF ssorigen <> '' THEN
 SET sorigen = ssorigen;
 END IF;
-- Abrimos el Cursor
OPEN Datos_Asiento;

-- Iniciamos la Transaccion
START TRANSACTION;

-- Leeemos el Cursor
read_loop: LOOP
FETCH Datos_Asiento INTO fechamovimiento,centros_costosid, concepto, referencia, valor, codigocontable;

-- Verificamos si no hay mas registros
IF termino THEN
LEAVE read_loop;
END IF;

SET diferencia = diferencia+(Round(valor,2));
-- Sumamos valores de debe y haber
IF valor<0 THEN
  SET haber = (haber + (Abs((valor))));
ELSE
  SET debe  = (debe + (Abs((valor))));
END IF;

-- INSERTAMOS LA CABECERA DEL ASIENTO
  IF gravocabecera=FALSE THEN
    -- Optenemos el nuevo secuencial
    call SP_Consulta_Secuencias_Internas('LIBRODIARIO',codigoasiento);
  
    -- Insertamos Registro Cabecera
    INSERT INTO libros_diarios 
    (
      codigoasiento, 
      fecha, 
      referencia, 
      concepto, 
      origen, 
      usuariocreacion, 
      fechacreacion
    ) 
    VALUES 
    (
      codigoasiento,
      fechamovimiento,
      referencia, 
      concepto,
      sorigen, 
      sUsuario, 
      NOW(3)
    );
   
   -- obtenemos el ultimo ID insertado
    SET libros_diariosid=(select LAST_INSERT_ID());
    
    -- Actualizamos el secuencial de libros diarios
    call SP_Actualiza_Secuencias_Internas('LIBRODIARIO');

    -- Ponemos que gravo la cabecera
    SET gravocabecera=TRUE;

  END IF;

-- INSERTAMOS LOS DETALLES
set valor = round(valor,2);
INSERT INTO libros_diarios_detalles
( 	
libros_diariosid,	
codigocontable,	
centros_costosid,	
referencia,	
concepto,	
importe
)
VALUES
( 
libros_diariosid,	
codigocontable,	
centros_costosid,	
referencia,	
concepto,	
valor
 );

-- Toma la primer cuenta del asiento contable
IF cuenta_fija=0 THEN 
SET cuenta_fija = (select LAST_INSERT_ID());
END IF;

END LOOP;

CALL SP_Contabiliza_Verificar_Asiento(libros_diariosid,verificado);


-- Cuadramos el asiento contable si esta descuadrado
IF diferencia<0.11 AND diferencia>-0.11 AND diferencia<>0  THEN
UPDATE libros_diarios_detalles
SET
libros_diarios_detalles.importe = libros_diarios_detalles.importe-diferencia
WHERE
libros_diarios_detalles.libros_diarios_detallesid = cuenta_fija;
SET diferencia=0;
END IF;

-- Verificamos si el asiento esta cuadrado
IF diferencia<>0 THEN
SET verificado=0;
END IF;

-- Actualizamos el libro diario
SET debe = Round(debe,2);
SET haber = Round(haber,2);
UPDATE 
libros_diarios
SET
libros_diarios.debito = debe,
libros_diarios.credito = haber,
libros_diarios.mayorizado = verificado,
libros_diarios.verificado = verificado
WHERE
libros_diarios.libros_diariosid = libros_diariosid;


-- Actualizamos el ID del libro diario a el movimiento de Caja

IF ssorigen <> '' THEN 

UPDATE
movbanco 
SET
movbanco.asientocontable = libros_diariosid,
movbanco.fechamodificacion = movbanco.fechamodificacion
WHERE
movbanco.asientocontable = 0
AND movbanco.documentosid = nDocumentoid
AND movbanco.origen = 'Caja A';

UPDATE
 cobros 
SET
 cobros.asientocontable = libros_diariosid,
 cobros.fechamodificacion = cobros.fechamodificacion 
WHERE
 cobros.cobrosid = nDocumentoid 
 AND cobros.asientocontable = 0;

ELSE
UPDATE
movbanco 
SET
movbanco.asientocontable = libros_diariosid,
movbanco.fechamodificacion = movbanco.fechamodificacion
WHERE
movbanco.asientocontable = 0
AND movbanco.movbancosid = nDocumentoid
AND movbanco.origen = 'Bancos';

END IF;



-- Finalizamos la transaccion
COMMIT;

-- Cerramos el Cursor
CLOSE Datos_Asiento;

-- Devolvemos el ID del Asiento Contable
select libros_diariosid;

END
;;
delimiter ;

-- ----------------------------
-- Procedure structure for SP_Contabiliza_Caja_Agrupado
-- ----------------------------
DROP PROCEDURE IF EXISTS `SP_Contabiliza_Caja_Agrupado`;
delimiter ;;
CREATE PROCEDURE `SP_Contabiliza_Caja_Agrupado`(IN dFechaDesde DATE, IN dFechaHasta DATE, IN sUsuario VARCHAR(25))
  MODIFIES SQL DATA 
  SQL SECURITY INVOKER
BEGIN

-- Declaramos variables de Cursor
DECLARE termino INT DEFAULT FALSE;
DECLARE fechamovimiento date;
DECLARE usuariocreacion varchar(25);
DECLARE centros_costosid int(11);
DECLARE concepto varchar(200);
DECLARE referencia varchar(15);
DECLARE valor decimal(16,8) DEFAULT 0;
DECLARE codigocontable varchar(30);
DECLARE codigoasiento varchar(15);
DECLARE gravocabecera INT DEFAULT FALSE;
DECLARE libros_diariosid bigint DEFAULT 0;
DECLARE debe  decimal(16,8) DEFAULT 0;
DECLARE haber decimal(16,8) DEFAULT 0;
DECLARE diferencia decimal(12,2) DEFAULT 0;
DECLARE verificado INT DEFAULT TRUE;
DECLARE cuenta_fija bigint DEFAULT 0;

DECLARE Datos_Asiento CURSOR FOR
SELECT
movcaja.centros_costosid AS centros_costosid,
left(movcaja.concepto,200) as concepto,
movcaja.documentoorigen AS referencia,
SUM(movcaja.importe) AS valor,
cajas.codigocontable AS codigocontable
FROM
cajas
INNER JOIN
movcaja
ON (cajas.cajasid = movcaja.cajasid)
WHERE
movcaja.origen = 'Caja'
AND movcaja.fechamovimiento BETWEEN dFechaDesde AND dFechaHasta
AND movcaja.asientocontable=0
HAVING
SUM(movcaja.importe)<>0
UNION
SELECT
movcaja.centros_costosid AS centros_costosid,
LEFT(CONCAT(movcaja.concepto,' ',movcaja.comprobante),200) AS concepto,
movcaja.documentoorigen AS referencia,
SUM(-movcaja.importe) AS valor,
movimientos_conceptos.codigocontable AS codigocontable
FROM
movimientos_conceptos
INNER JOIN
movcaja
ON (movimientos_conceptos.movimientos_conceptosid = movcaja.movimientos_conceptosid)
WHERE
movcaja.origen = 'Caja'
AND movcaja.fechamovimiento BETWEEN dFechaDesde AND dFechaHasta
AND movcaja.asientocontable=0
HAVING
SUM(movcaja.importe)<>0;



-- Controlamos si hubo error
DECLARE exit handler FOR SQLEXCEPTION, SQLWARNING
  BEGIN
  	SHOW WARNINGS limit 1;
    ROLLBACK;
    RESIGNAL;
  END;

-- Declaramos el control de salida del loop
DECLARE CONTINUE HANDLER FOR NOT FOUND SET termino = TRUE;

-- Abrimos el Cursor
OPEN Datos_Asiento;

-- Iniciamos la Transaccion
START TRANSACTION;

-- Leeemos el Cursor
read_loop: LOOP
FETCH Datos_Asiento INTO centros_costosid, concepto, referencia, valor, codigocontable;

-- Verificamos si no hay mas registros
IF termino THEN
LEAVE read_loop;
END IF;

SET diferencia = diferencia+(Round(valor,2));
-- Sumamos valores de debe y haber
IF valor<0 THEN
  SET haber = (haber + (Abs((valor))));
ELSE
  SET debe  = (debe + (Abs((valor))));
END IF;

-- INSERTAMOS LA CABECERA DEL ASIENTO
  IF gravocabecera=FALSE THEN
    -- Optenemos el nuevo secuencial
    call SP_Consulta_Secuencias_Internas('LIBRODIARIO',codigoasiento);
  
    -- Insertamos Registro Cabecera
    INSERT INTO libros_diarios 
    (
      codigoasiento, 
      fecha, 
      referencia, 
      concepto, 
      origen, 
      usuariocreacion, 
      fechacreacion
    ) 
    VALUES 
    (
      codigoasiento,
      dFechaDesde,
      codigoasiento, 
      CONCAT('Movimientos de Caja de ',DATE_FORMAT(dFechaDesde,"%d-%m-%Y"),' a ',DATE_FORMAT(dFechaHasta,"%d-%m-%Y")),
      'Caja', 
      sUsuario, 
      NOW()
    );
   
   -- obtenemos el ultimo ID insertado
    SET libros_diariosid=(select LAST_INSERT_ID());
    
    -- Actualizamos el secuencial de libros diarios
    call SP_Actualiza_Secuencias_Internas('LIBRODIARIO');

    -- Ponemos que gravo la cabecera
    SET gravocabecera=TRUE;

  END IF;

-- INSERTAMOS LOS DETALLES
set valor = round(valor,2);
INSERT INTO libros_diarios_detalles
( 	
libros_diariosid,	
codigocontable,	
centros_costosid,	
referencia,	
concepto,	
importe
)
VALUES
( 
libros_diariosid,	
codigocontable,	
centros_costosid,	
referencia,	
concepto,	
valor
 );

-- Toma la primer cuenta del asiento contable
IF cuenta_fija=0 THEN 
SET cuenta_fija = (select LAST_INSERT_ID());
END IF;

END LOOP;

CALL SP_Contabiliza_Verificar_Asiento(libros_diariosid,verificado);


-- Cuadramos el asiento contable si esta descuadrado
IF diferencia<0.11 AND diferencia>-0.11 AND diferencia<>0  THEN
UPDATE libros_diarios_detalles
SET
libros_diarios_detalles.importe = libros_diarios_detalles.importe-diferencia
WHERE
libros_diarios_detalles.libros_diarios_detallesid = cuenta_fija;
SET diferencia=0;
END IF;

-- Verificamos si el asiento esta cuadrado
IF diferencia<>0 THEN
SET verificado=0;
END IF;

-- Actualizamos el libro diario
SET debe = Round(debe,2);
SET haber = Round(haber,2);
UPDATE 
libros_diarios
SET
libros_diarios.debito = debe,
libros_diarios.credito = haber,
libros_diarios.mayorizado = verificado,
libros_diarios.verificado = verificado
WHERE
libros_diarios.libros_diariosid = libros_diariosid;


-- Actualizamos el ID del libro diario a el movimiento de Caja
UPDATE
   movcaja 
SET
   movcaja.asientocontable = libros_diariosid,
   movcaja.fechamodificacion = movcaja.fechamodificacion
WHERE
   movcaja.fechamovimiento BETWEEN dFechaDesde AND dFechaHasta
   AND movcaja.asientocontable = 0 
   AND movcaja.origen = 'Caja';



-- Finalizamos la transaccion
COMMIT;

-- Cerramos el Cursor
CLOSE Datos_Asiento;

-- Devolvemos el ID del Asiento Contable
select libros_diariosid;

END
;;
delimiter ;

-- ----------------------------
-- Procedure structure for SP_Contabiliza_Caja_Individual
-- ----------------------------
DROP PROCEDURE IF EXISTS `SP_Contabiliza_Caja_Individual`;
delimiter ;;
CREATE PROCEDURE `SP_Contabiliza_Caja_Individual`(IN nDocumentoid BIGINT, IN sUsuario VARCHAR(25), IN ssorigen VARCHAR(25))
  MODIFIES SQL DATA 
  SQL SECURITY INVOKER
BEGIN

-- Declaramos variables de Cursor
DECLARE termino INT DEFAULT FALSE;
DECLARE fechamovimiento date;
DECLARE usuariocreacion varchar(25);
DECLARE centros_costosid int(11);
DECLARE concepto varchar(200);
DECLARE referencia varchar(15);
DECLARE valor decimal(16,8) DEFAULT 0;
DECLARE codigocontable varchar(30);
DECLARE codigoasiento varchar(10);
DECLARE gravocabecera INT DEFAULT FALSE;
DECLARE libros_diariosid bigint DEFAULT 0;
DECLARE debe  decimal(16,8) DEFAULT 0;
DECLARE haber decimal(16,8) DEFAULT 0;
DECLARE diferencia decimal(12,2) DEFAULT 0;
DECLARE verificado INT DEFAULT TRUE;
DECLARE cuenta_fija bigint DEFAULT 0;
DECLARE sorigen varchar(30) DEFAULT('Caja');
DECLARE Datos_Asiento CURSOR FOR
SELECT
  movcaja.fechamovimiento AS fechamovimiento,
movcaja.centros_costosid AS centros_costosid,
LEFT(CONCAT(movcaja.concepto,' ',movcaja.comprobante),200)  AS concepto,
movcaja.documentoorigen AS referencia,
SUM(movcaja.importe) AS valor,
cajas.codigocontable AS codigocontable
FROM
cajas
INNER JOIN
movcaja
ON (cajas.cajasid = movcaja.cajasid)
WHERE
movcaja.origen = sorigen
AND movcaja.movimientos_conceptosid NOT IN(29,30,33)
AND movcaja.movcajasid = nDocumentoid
AND movcaja.asientocontable=0
HAVING
SUM(movcaja.importe)<>0

UNION
SELECT
  movcaja.fechamovimiento AS fechamovimiento,
movcaja.centros_costosid AS centros_costosid,
LEFT(CONCAT(movcaja.concepto,' ',movcaja.comprobante),200)  AS concepto,
movcaja.documentoorigen AS referencia,
SUM(-movcaja.importe) AS valor,
movimientos_conceptos.codigocontable AS codigocontable
FROM
movimientos_conceptos
INNER JOIN
movcaja
ON (movimientos_conceptos.movimientos_conceptosid = movcaja.movimientos_conceptosid)
WHERE
movcaja.origen = sorigen
AND movcaja.movimientos_conceptosid NOT IN(29,30,33)
AND movcaja.movcajasid = nDocumentoid
AND movcaja.asientocontable=0
HAVING
SUM(movcaja.importe)<>0
UNION
SELECT
  movcaja.fechamovimiento AS fechamovimiento,
movcaja.centros_costosid AS centros_costosid,
LEFT(CONCAT(movcaja.concepto,' ',movcaja.comprobante),200)  AS concepto,
movcaja.documentoorigen AS referencia,
SUM(movcaja.importe) AS valor,
cajas.codigocontable AS codigocontable
FROM
cajas
INNER JOIN
movcaja
ON (cajas.cajasid = movcaja.cajasid)
WHERE
movcaja.origen = sorigen
AND movcaja.movimientos_conceptosid IN(29,30)
AND movcaja.documentosid = nDocumentoid
AND movcaja.asientocontable=0
HAVING
SUM(movcaja.importe)<>0

UNION
SELECT
  cobros.fechaemision AS fechamovimiento,
cobros.centros_costosid AS centros_costosid,
LEFT(CONCAT(cobros.concepto,' ',cobros.cobroscodigo),200)  AS concepto,
movcaja.documentoorigen AS referencia,
CASE WHEN cobros.tipo = 'AB' THEN 
SUM(movcaja.importe) 
ELSE 
-SUM(movcaja.importe) 
END
AS valor,
movimientos_conceptos.codigocontable AS codigocontable
FROM
movimientos_conceptos
INNER JOIN
movcaja
ON (movimientos_conceptos.movimientos_conceptosid = 29),
cobros

WHERE
movcaja.origen = sorigen
AND cobros.cobrosid = movcaja.documentosid
AND movcaja.movimientos_conceptosid IN(29,30)
AND movcaja.documentosid = nDocumentoid
AND movcaja.asientocontable=0
HAVING
SUM(movcaja.importe)<>0


UNION

SELECT
  movcaja.fechamovimiento AS fechamovimiento,
movcaja.centros_costosid AS centros_costosid,
LEFT(CONCAT(movcaja.concepto,' ',movcaja.comprobante),200)  AS concepto,
movcaja.documentoorigen AS referencia,
SUM(movcaja.importe) AS valor,
cajas.codigocontable AS codigocontable
FROM
cajas
INNER JOIN
movcaja
ON (cajas.cajasid = movcaja.cajasid),
cobros
WHERE
movcaja.origen = sorigen
AND movcaja.movimientos_conceptosid IN(33)
AND movcaja.documentosid = nDocumentoid
AND cobros.cobrosid = movcaja.documentosid
AND movcaja.asientocontable=0
HAVING
SUM(movcaja.importe)<>0


UNION
SELECT
  cobros.fechaemision AS fechamovimiento,
cobros.centros_costosid AS centros_costosid,
LEFT(CONCAT(cobros.concepto,' ',cobros.cobroscodigo),200)  AS concepto,
movcaja.documentoorigen AS referencia,
CASE WHEN cobros.tipo = 'AB' THEN 
-SUM(cobros_detalles.capital) 
ELSE 
SUM(cobros_detalles.capital) 
END
AS valor,
movimientos_conceptos.codigocontable AS codigocontable
FROM
movimientos_conceptos
INNER JOIN
movcaja
ON (movimientos_conceptos.movimientos_conceptosid = 29),
cobros
INNER JOIN 
cobros_detalles
ON (cobros.cobrosid = cobros_detalles.cobrosid)
WHERE
movcaja.origen = sorigen
AND cobros.cobrosid = movcaja.documentosid
AND movcaja.movimientos_conceptosid IN(33)
AND movcaja.documentosid = nDocumentoid
AND movcaja.asientocontable=0
HAVING
SUM(cobros_detalles.capital)<>0

UNION
SELECT
  cobros.fechaemision AS fechamovimiento,
cobros.centros_costosid AS centros_costosid,
LEFT(CONCAT(cobros.concepto,' ',cobros.cobroscodigo),200)  AS concepto,
movcaja.documentoorigen AS referencia,
CASE WHEN cobros.tipo = 'AB' THEN 
-SUM(cobros_detalles.interes)
ELSE 
SUM(cobros_detalles.interes)
END
 AS valor,
movimientos_conceptos.codigocontable AS codigocontable
FROM
movimientos_conceptos
INNER JOIN
movcaja
ON (movimientos_conceptos.movimientos_conceptosid = 31),
cobros
INNER JOIN 
cobros_detalles
ON (cobros.cobrosid = cobros_detalles.cobrosid)
WHERE
movcaja.origen = sorigen
AND cobros.cobrosid = movcaja.documentosid
AND movcaja.movimientos_conceptosid IN(33)
AND movcaja.documentosid = nDocumentoid
AND movcaja.asientocontable=0
HAVING
SUM(cobros_detalles.interes)<>0


UNION
SELECT
  cobros.fechaemision AS fechamovimiento,
cobros.centros_costosid AS centros_costosid,
LEFT(CONCAT(cobros.concepto,' ',cobros.cobroscodigo),200)  AS concepto,
movcaja.documentoorigen AS referencia,
CASE WHEN cobros.tipo = 'AB' THEN 
-SUM(cobros_detalles.importe)
ELSE 
SUM(cobros_detalles.importe)
END
 AS valor,
movimientos_conceptos.codigocontable AS codigocontable
FROM
movimientos_conceptos
INNER JOIN
movcaja
ON (movimientos_conceptos.movimientos_conceptosid = 6),
cobros
INNER JOIN 
cobros_detalles
ON (cobros.cobrosid = cobros_detalles.cobrosid)
WHERE
movcaja.origen = sorigen
AND cobros.cobrosid = movcaja.documentosid
AND movcaja.movimientos_conceptosid IN(33)
AND movcaja.documentosid = nDocumentoid
AND cobros_detalles.tipo = 5 
AND movcaja.asientocontable=0
HAVING
SUM(cobros_detalles.importe)<>0;






-- Controlamos si hubo error
DECLARE exit handler FOR SQLEXCEPTION, SQLWARNING
  BEGIN
  	SHOW WARNINGS limit 1;
    ROLLBACK;
    RESIGNAL;
  END;

-- Declaramos el control de salida del loop
DECLARE CONTINUE HANDLER FOR NOT FOUND SET termino = TRUE;
IF ssorigen <> '' THEN
 SET sorigen = ssorigen;
 END IF;
-- Abrimos el Cursor
OPEN Datos_Asiento;

-- Iniciamos la Transaccion
START TRANSACTION;

-- Leeemos el Cursor
read_loop: LOOP
FETCH Datos_Asiento INTO fechamovimiento,centros_costosid, concepto, referencia, valor, codigocontable;

-- Verificamos si no hay mas registros
IF termino THEN
LEAVE read_loop;
END IF;

SET diferencia = diferencia+(Round(valor,2));
-- Sumamos valores de debe y haber
IF valor<0 THEN
  SET haber = (haber + (Abs((valor))));
ELSE
  SET debe  = (debe + (Abs((valor))));
END IF;

-- INSERTAMOS LA CABECERA DEL ASIENTO
  IF gravocabecera=FALSE THEN
    -- Optenemos el nuevo secuencial
    call SP_Consulta_Secuencias_Internas('LIBRODIARIO',codigoasiento);
  
    -- Insertamos Registro Cabecera
    INSERT INTO libros_diarios 
    (
      codigoasiento, 
      fecha, 
      referencia, 
      concepto, 
      origen, 
      usuariocreacion, 
      fechacreacion
    ) 
    VALUES 
    (
      codigoasiento,
      fechamovimiento,
      referencia, 
      concepto,
      sorigen, 
      sUsuario, 
      NOW(3)
    );
   
   -- obtenemos el ultimo ID insertado
    SET libros_diariosid=(select LAST_INSERT_ID());
    
    -- Actualizamos el secuencial de libros diarios
    call SP_Actualiza_Secuencias_Internas('LIBRODIARIO');

    -- Ponemos que gravo la cabecera
    SET gravocabecera=TRUE;

  END IF;

-- INSERTAMOS LOS DETALLES
set valor = round(valor,2);
INSERT INTO libros_diarios_detalles
( 	
libros_diariosid,	
codigocontable,	
centros_costosid,	
referencia,	
concepto,	
importe
)
VALUES

( 
libros_diariosid,	
codigocontable,	
centros_costosid,	
referencia,	
concepto,	
valor
 );

-- Toma la primer cuenta del asiento contable
IF cuenta_fija=0 THEN 
SET cuenta_fija = (select LAST_INSERT_ID());
END IF;

END LOOP;

CALL SP_Contabiliza_Verificar_Asiento(libros_diariosid,verificado);


-- Cuadramos el asiento contable si esta descuadrado
IF diferencia<0.11 AND diferencia>-0.11 AND diferencia<>0  THEN
UPDATE libros_diarios_detalles
SET
libros_diarios_detalles.importe = libros_diarios_detalles.importe-diferencia
WHERE
libros_diarios_detalles.libros_diarios_detallesid = cuenta_fija;
SET diferencia=0;
END IF;

-- Verificamos si el asiento esta cuadrado
IF diferencia<>0 THEN
SET verificado=0;
END IF;

-- Actualizamos el libro diario
SET debe = Round(debe,2);
SET haber = Round(haber,2);
UPDATE 
libros_diarios
SET
libros_diarios.debito = debe,
libros_diarios.credito = haber,
libros_diarios.mayorizado = verificado,
libros_diarios.verificado = verificado
WHERE
libros_diarios.libros_diariosid = libros_diariosid;


-- Actualizamos el ID del libro diario a el movimiento de Caja
IF ssorigen <> '' THEN
UPDATE
 movcaja 
SET
 movcaja.asientocontable = libros_diariosid,
 movcaja.fechamodificacion = movcaja.fechamodificacion 
WHERE
 movcaja.documentosid = nDocumentoid 
 AND movcaja.asientocontable = 0
 AND movcaja.origen = 'Caja A';
 
UPDATE
 cobros 
SET
 cobros.asientocontable = libros_diariosid,
 cobros.fechamodificacion = cobros.fechamodificacion 
WHERE
 cobros.cobrosid = nDocumentoid 
 AND cobros.asientocontable = 0;

 
ELSE
UPDATE
 movcaja 
SET
 movcaja.asientocontable = libros_diariosid,
 movcaja.fechamodificacion = movcaja.fechamodificacion 
WHERE
 movcaja.movcajasid = nDocumentoid 
 AND movcaja.asientocontable = 0
 AND movcaja.origen = 'Caja';
END IF;


-- Finalizamos la transaccion
COMMIT;

-- Cerramos el Cursor
CLOSE Datos_Asiento;

-- Devolvemos el ID del Asiento Contable
select libros_diariosid;

END
;;
delimiter ;

-- ----------------------------
-- Procedure structure for SP_Contabiliza_Cobro_Agrupado
-- ----------------------------
DROP PROCEDURE IF EXISTS `SP_Contabiliza_Cobro_Agrupado`;
delimiter ;;
CREATE PROCEDURE `SP_Contabiliza_Cobro_Agrupado`(IN dFechaDesde DATE, IN dFechaHasta DATE, IN sCCAnticipo VARCHAR(255), IN sUsuario VARCHAR(25))
  MODIFIES SQL DATA 
BEGIN

-- Declaramos variables de Cursor
DECLARE termino INT DEFAULT FALSE;
DECLARE fechamovimiento date;
DECLARE usuariocreacion varchar(25);
DECLARE centros_costosid int(11);
DECLARE concepto varchar(200);
DECLARE referencia varchar(15);
DECLARE valor decimal(16,8) DEFAULT 0;
DECLARE codigocontable varchar(30);
DECLARE codigoasiento varchar(15);
DECLARE gravocabecera INT DEFAULT FALSE;
DECLARE libros_diariosid bigint DEFAULT 0;
DECLARE debe  decimal(16,8) DEFAULT 0;
DECLARE haber decimal(16,8) DEFAULT 0;
DECLARE diferencia decimal(12,2) DEFAULT 0;
DECLARE verificado INT DEFAULT TRUE;
DECLARE cuenta_fija bigint DEFAULT 0;

DECLARE Datos_Asiento CURSOR FOR
SELECT
cobros.centros_costosid AS centros_costosid,
cobros.concepto AS concepto,
cobros.cobroscodigo AS referencia,
-SUM(cuentasporcobrar.importe) AS valor,
movimientos_conceptos.codigocontable AS codigocontable
FROM
cobros
INNER JOIN
cuentasporcobrar
ON (cobros.cobrosid = cuentasporcobrar.cobrosid 
AND cuentasporcobrar.tipo = 'AB' 
AND cuentasporcobrar.forma_pago_empresaid = 9 
AND cuentasporcobrar.origen = 'Cobros')
INNER JOIN 
movimientos_conceptos on (cobros.movimientos_conceptosid = movimientos_conceptos.movimientos_conceptosid)
WHERE
(cobros.asientocontable = 0	)
AND cobros.tipo = 'AB'
AND cobros.fechaemision BETWEEN dFechaDesde AND dFechaHasta
HAVING
SUM(cuentasporcobrar.importe)<>0

union

SELECT
cobros.centros_costosid  AS centros_costosid,
cobros.concepto AS concepto,
cobros.cobroscodigo AS referencia,
-SUM(cuentasporcobrar.importe) AS valor,
movimientos_conceptos.codigocontable AS codigocontable
FROM
cobros
INNER JOIN
cuentasporcobrar
ON (cobros.cobrosid = cuentasporcobrar.cobrosid 
AND cuentasporcobrar.tipo = 'AB' 
AND cuentasporcobrar.forma_pago_empresaid = 10 
AND cuentasporcobrar.origen = 'Cobros')
INNER JOIN 
movimientos_conceptos on (cobros.movimientos_conceptosid = movimientos_conceptos.movimientos_conceptosid)
WHERE
(cobros.asientocontable = 0	)
AND cobros.tipo = 'AB'
AND cobros.fechaemision BETWEEN dFechaDesde AND dFechaHasta
HAVING
SUM(cuentasporcobrar.importe)<>0

UNION

SELECT
cobros.centros_costosid AS centros_costosid,
cobros.concepto AS concepto,
cobros.cobroscodigo AS referencia,
SUM(movcaja.importe) AS valor,
cajas.codigocontable AS codigocontable
FROM
cajas
INNER JOIN
(	movcaja
INNER JOIN
(	cobros)ON (cobros.cobrosid = movcaja.documentosid AND movcaja.origen = 'Cobros' AND movcaja.concepto <> 'AJUSTE RETENCIONES ATRASADAS')
)ON cajas.cajasid = movcaja.cajasid
WHERE	
(cobros.asientocontable = 0	)
AND cobros.fechaemision BETWEEN dFechaDesde AND dFechaHasta
GROUP BY
cajas.codigocontable
HAVING
SUM(movcaja.importe)<>0

UNION

SELECT
cobros.centros_costosid AS centros_costosid,
cobros.concepto AS concepto,
cobros.cobroscodigo AS referencia,
SUM(movbanco.importe) AS valor,
bancos.codigocontable AS codigocontable
FROM
bancos
INNER JOIN
(	movbanco
INNER JOIN
(	cobros)ON (cobros.cobrosid = movbanco.documentosid AND movbanco.origen = 'Cobros')
)ON bancos.bancosid = movbanco.bancosid
WHERE	
(cobros.asientocontable = 0	)
AND cobros.fechaemision BETWEEN dFechaDesde AND dFechaHasta
GROUP BY
bancos.codigocontable
HAVING
SUM(movbanco.importe)<>0

UNION

SELECT
cobros.centros_costosid AS centros_costosid,
cobros.concepto AS concepto,
cobros.cobroscodigo AS referencia,
-SUM(cobros.importe) AS valor,
movimientos_conceptos.codigocontable AS codigocontable
FROM
movimientos_conceptos
INNER JOIN
cobros
ON (movimientos_conceptos.movimientos_conceptosid = cobros.movimientos_conceptosid AND movimientos_conceptos.movimientos_conceptosid <> 4)
WHERE
cobros.tipo = 'ND'
AND cobros.fechaemision BETWEEN dFechaDesde AND dFechaHasta
and cobros.movimientos_conceptosid <> 5
HAVING
SUM(-cobros.importe)<>0

UNION

SELECT
cobros.centros_costosid AS centros_costosid,
cobros.concepto AS concepto,
cobros.cobroscodigo AS referencia,
sum(CASE WHEN ((cobros.tipo = 'ND' ) OR (cobros.tipo='AB' AND cobros.forma_pago_empresaid = 10)) THEN cobros.importe ELSE -(cobros.importe-cobros.anticipo) END) AS valor,
clientes.codigocontable  AS codigocontable
FROM
cobros,
clientes 
WHERE
cobros.clientesid = clientes.clientesid			
AND cobros.movimientos_conceptosid<>4
AND cobros.tipo <>'NC'
AND cobros.asientocontable = 0
AND cobros.fechaemision BETWEEN dFechaDesde AND dFechaHasta
GROUP BY
clientes.codigocontable
HAVING
sum(CASE WHEN ((cobros.tipo = 'ND' ) OR (cobros.tipo='AB' AND cobros.forma_pago_empresaid = 10)) THEN cobros.importe ELSE -(cobros.importe-cobros.anticipo) END)<>0

UNION

SELECT
cobros.centros_costosid AS centros_costosid,
cobros.concepto AS concepto,
cobros.cobroscodigo AS referencia,
-sum(cobros.importe) AS valor,
sCCAnticipo AS codigocontable
FROM
cobros
WHERE
cobros.asientocontable = 0
AND cobros.tipo ='NC'
AND cobros.fechaemision BETWEEN dFechaDesde AND dFechaHasta
HAVING
sum(cobros.importe)<>0

UNION

SELECT
cobros.centros_costosid AS centros_costosid,
cobros.concepto AS concepto,
cobros.cobroscodigo AS referencia,
-sum(cobros.anticipo) AS valor,
sCCAnticipo  AS codigocontable
FROM
cobros
WHERE
cobros.asientocontable = 0
AND cobros.fechaemision BETWEEN dFechaDesde AND dFechaHasta
HAVING
sum(cobros.anticipo)<>0;



-- Controlamos si hubo error
DECLARE exit handler FOR SQLEXCEPTION, SQLWARNING
  BEGIN
  	SHOW WARNINGS limit 1;
    ROLLBACK;
    RESIGNAL;
  END;

-- Declaramos el control de salida del loop
DECLARE CONTINUE HANDLER FOR NOT FOUND SET termino = TRUE;

-- Abrimos el Cursor
OPEN Datos_Asiento;

-- Iniciamos la Transaccion
START TRANSACTION;

-- Leeemos el Cursor
read_loop: LOOP
FETCH Datos_Asiento INTO centros_costosid, concepto, referencia, valor, codigocontable;

-- Verificamos si no hay mas registros
IF termino THEN
LEAVE read_loop;
END IF;

SET diferencia = diferencia+(Round(valor,2));
-- Sumamos valores de debe y haber
IF valor<0 THEN
  SET haber = (haber + (Abs((valor))));
ELSE
  SET debe  = (debe + (Abs((valor))));
END IF;

-- INSERTAMOS LA CABECERA DEL ASIENTO
  IF gravocabecera=FALSE THEN
    -- Optenemos el nuevo secuencial
    call SP_Consulta_Secuencias_Internas('LIBRODIARIO',codigoasiento);
  
    -- Insertamos Registro Cabecera
    INSERT INTO libros_diarios 
    (
      codigoasiento, 
      fecha, 
      referencia, 
      concepto, 
      origen, 
      usuariocreacion, 
      fechacreacion
    ) 
    VALUES 
    (
      codigoasiento,
      dFechaDesde,
      codigoasiento, 
      CONCAT('Cobros de ',DATE_FORMAT(dFechaDesde,"%d-%m-%Y"),' a ',DATE_FORMAT(dFechaHasta,"%d-%m-%Y")),
      'Cobros', 
      sUsuario, 
      NOW()
    );
   
   -- obtenemos el ultimo ID insertado
    SET libros_diariosid=(select LAST_INSERT_ID());
    
    -- Actualizamos el secuencial de libros diarios
    call SP_Actualiza_Secuencias_Internas('LIBRODIARIO');

    -- Ponemos que gravo la cabecera
    SET gravocabecera=TRUE;

  END IF;

-- INSERTAMOS LOS DETALLES
set valor = round(valor,2);
INSERT INTO libros_diarios_detalles
( 	
libros_diariosid,	
codigocontable,	
centros_costosid,	
referencia,	
concepto,	
importe
)
VALUES
( 
libros_diariosid,	
codigocontable,	
centros_costosid,	
referencia,	
concepto,	
valor
 );

-- Toma la primer cuenta del asiento contable
IF cuenta_fija=0 THEN 
SET cuenta_fija = (select LAST_INSERT_ID());
END IF;

END LOOP;

CALL SP_Contabiliza_Verificar_Asiento(libros_diariosid,verificado);


-- Cuadramos el asiento contable si esta descuadrado
IF diferencia<0.11 AND diferencia>-0.11 AND diferencia<>0  THEN
UPDATE libros_diarios_detalles
SET
libros_diarios_detalles.importe = libros_diarios_detalles.importe-diferencia
WHERE
libros_diarios_detalles.libros_diarios_detallesid = cuenta_fija;
SET diferencia=0;
END IF;

-- Verificamos si el asiento esta cuadrado
IF diferencia<>0 THEN
SET verificado=0;
END IF;

-- Actualizamos el libro diario
SET debe = Round(debe,2);
SET haber = Round(haber,2);
UPDATE 
libros_diarios
SET
libros_diarios.debito = debe,
libros_diarios.credito = haber,
libros_diarios.mayorizado = verificado,
libros_diarios.verificado = verificado,
libros_diarios.fechamodificacion = libros_diarios.fechamodificacion
WHERE
libros_diarios.libros_diariosid = libros_diariosid;


-- Actualizamos el ID del libro diario a el movimiento de Caja
UPDATE
movcaja 
SET
movcaja.asientocontable=libros_diariosid,
movcaja.fechamodificacion = movcaja.fechamodificacion
WHERE
movcaja.asientocontable = 0
AND movcaja.origen = 'Cobros'
AND movcaja.fechamovimiento BETWEEN dFechaDesde AND dFechaHasta;
UPDATE
movbanco 
SET
movbanco.asientocontable=libros_diariosid,
movbanco.fechamodificacion = movbanco.fechamodificacion
WHERE
movbanco.asientocontable = 0
AND movbanco.fechamovimiento BETWEEN dFechaDesde AND dFechaHasta
AND movbanco.origen = 'Cobros';
UPDATE
cuentasporcobrar 
SET
cuentasporcobrar.asientocontable=libros_diariosid,
cuentasporcobrar.fechamodificacion = cuentasporcobrar.fechamodificacion
WHERE
cuentasporcobrar.origen = 'Cobros'
AND cuentasporcobrar.asientocontable = 0
AND cuentasporcobrar.emision BETWEEN dFechaDesde AND dFechaHasta
AND cuentasporcobrar.concepto NOT LIKE 'CRUCE ANTICIPO %';
UPDATE
cobros
SET
cobros.asientocontable = libros_diariosid,
cobros.fechamodificacion = cobros.fechamodificacion
WHERE
cobros.fechaemision BETWEEN dFechaDesde AND dFechaHasta
AND cobros.asientocontable = 0;



-- Finalizamos la transaccion
COMMIT;

-- Cerramos el Cursor
CLOSE Datos_Asiento;

-- Devolvemos el ID del Asiento Contable
select libros_diariosid;

END
;;
delimiter ;

-- ----------------------------
-- Procedure structure for SP_Contabiliza_Cobro_Individual
-- ----------------------------
DROP PROCEDURE IF EXISTS `SP_Contabiliza_Cobro_Individual`;
delimiter ;;
CREATE PROCEDURE `SP_Contabiliza_Cobro_Individual`(IN nDocumentoid BIGINT, IN sCCAnticipo VARCHAR(255), IN sUsuario VARCHAR(25))
  MODIFIES SQL DATA 
BEGIN

-- Declaramos variables de Cursor
DECLARE termino INT DEFAULT FALSE;
DECLARE fechamovimiento date;
DECLARE usuariocreacion varchar(25);
DECLARE centros_costosid int(11);
DECLARE concepto varchar(200);
DECLARE referencia varchar(15);
DECLARE valor decimal(16,8) DEFAULT 0;
DECLARE codigocontable varchar(30);
DECLARE codigoasiento varchar(10);
DECLARE gravocabecera INT DEFAULT FALSE;
DECLARE libros_diariosid bigint DEFAULT 0;
DECLARE debe  decimal(16,8) DEFAULT 0;
DECLARE haber decimal(16,8) DEFAULT 0;
DECLARE diferencia decimal(12,2) DEFAULT 0;
DECLARE verificado INT DEFAULT TRUE;
DECLARE cuenta_fija bigint DEFAULT 0;

DECLARE Datos_Asiento CURSOR FOR
SELECT
cobros.fechaemision as fechamovimiento,
cobros.centros_costosid AS centros_costosid,
cobros.concepto AS concepto,
cobros.cobroscodigo AS referencia,
-SUM(cuentasporcobrar.importe) AS valor,
movimientos_conceptos.codigocontable AS codigocontable
FROM
cobros
INNER JOIN	cuentasporcobrar	on (cobros.cobrosid = cuentasporcobrar.cobrosid 
and cuentasporcobrar.tipo = 'AB' 
and cuentasporcobrar.forma_pago_empresaid = 9 
and cuentasporcobrar.origen = 'Cobros')
INNER JOIN 
movimientos_conceptos on (cobros.movimientos_conceptosid = movimientos_conceptos.movimientos_conceptosid)
WHERE
cobros.tipo = 'AB'
and cobros.cobrosid = nDocumentoid
HAVING
SUM(cuentasporcobrar.importe)<>0

union

SELECT
cobros.fechaemision as fechamovimiento,
cobros.centros_costosid AS centros_costosid,
cobros.concepto AS concepto,
cobros.cobroscodigo AS referencia,
-SUM(cuentasporcobrar.importe) AS valor,
movimientos_conceptos.codigocontable AS codigocontable
FROM
cobros
INNER JOIN
cuentasporcobrar
on (cobros.cobrosid = cuentasporcobrar.cobrosid 
and cuentasporcobrar.tipo = 'AB' 
and cuentasporcobrar.forma_pago_empresaid = 10 
and cuentasporcobrar.origen = 'Cobros')
INNER JOIN 
movimientos_conceptos on (cobros.movimientos_conceptosid = movimientos_conceptos.movimientos_conceptosid)
WHERE
cobros.tipo = 'AB'
and cobros.cobrosid = nDocumentoid
and cobros.movimientos_conceptosid <> 5
HAVING
SUM(cuentasporcobrar.importe)<>0

union

SELECT
cobros.fechaemision as fechamovimiento,
cobros.centros_costosid AS centros_costosid,
cobros.concepto AS concepto,
cobros.cobroscodigo AS referencia,
SUM(movcaja.importe) AS valor,
cajas.codigocontable AS codigocontable
FROM
cajas
INNER JOIN
(	movcaja
INNER JOIN
(	cobros)on (cobros.cobrosid = movcaja.documentosid and movcaja.origen = 'Cobros' AND movcaja.concepto <> 'AJUSTE RETENCIONES ATRASADAS')
)on cajas.cajasid = movcaja.cajasid
WHERE	
(cobros.asientocontable = 0	)
AND cobros.cobrosid = nDocumentoid
having
SUM(movcaja.importe)<>0

union

SELECT
cobros.fechaemision as fechamovimiento,
cobros.centros_costosid AS centros_costosid,
cobros.concepto AS concepto,
cobros.cobroscodigo AS referencia,
SUM(movbanco.importe) AS valor,
bancos.codigocontable AS codigocontable
FROM
bancos
INNER JOIN
(	movbanco
INNER JOIN
(	cobros)on (cobros.cobrosid = movbanco.documentosid and movbanco.origen = 'Cobros')
)on bancos.bancosid = movbanco.bancosid
WHERE	
(cobros.asientocontable = 0	)
AND cobros.cobrosid = nDocumentoid
GROUP BY
bancos.codigocontable
having
SUM(movbanco.importe)<>0

UNION

SELECT
cobros.fechaemision as fechamovimiento,
cobros.centros_costosid AS centros_costosid,
cobros.concepto AS concepto,
cobros.cobroscodigo AS referencia,
-SUM(cobros.importe) AS valor,
movimientos_conceptos.codigocontable AS codigocontable
FROM
movimientos_conceptos
INNER JOIN
cobros
ON (movimientos_conceptos.movimientos_conceptosid = cobros.movimientos_conceptosid AND movimientos_conceptos.movimientos_conceptosid <> 4)
WHERE
cobros.tipo = 'ND'
and cobros.cobrosid = nDocumentoid
and cobros.movimientos_conceptosid <> 5
HAVING
SUM(-cobros.importe)<>0

union

SELECT
cobros.fechaemision as fechamovimiento,
cobros.centros_costosid AS centros_costosid,
cobros.concepto AS concepto,
cobros.cobroscodigo AS referencia,
(CASE when ((cobros.tipo = 'ND' ) OR (cobros.tipo='AB' and cobros.forma_pago_empresaid = 10)) then cobros.importe else -(cobros.importe-cobros.anticipo) end) AS valor,
clientes.codigocontable AS codigocontable
FROM
cobros,
clientes 
WHERE
cobros.clientesid = clientes.clientesid			
and cobros.movimientos_conceptosid<>4
and cobros.tipo <>'NC'
AND cobros.asientocontable = 0
AND cobros.cobrosid = nDocumentoid
GROUP BY
clientes.codigocontable

union

SELECT
cobros.fechaemision as fechamovimiento,
cobros.centros_costosid AS centros_costosid,
cobros.concepto AS concpeto,
cobros.cobroscodigo AS referencia,
-(cobros.importe) AS valor,
sCCAnticipo AS codigocontable
FROM
cobros
WHERE
cobros.asientocontable = 0
AND cobros.tipo ='NC'
AND cobros.cobrosid = nDocumentoid
HAVING
sum(cobros.importe)<>0

UNION

SELECT
cobros.fechaemision as fechamovimiento,
cobros.centros_costosid AS centros_costosid,
cobros.concepto AS concepto,
cobros.cobroscodigo AS referencia,
-(cobros.anticipo) AS valor,
sCCAnticipo AS codigocontable
FROM
cobros
WHERE
cobros.asientocontable = 0
AND cobros.cobrosid = nDocumentoid
HAVING
SUM(cobros.anticipo)<>0;



-- Controlamos si hubo error
DECLARE exit handler FOR SQLEXCEPTION, SQLWARNING
  BEGIN
  	SHOW WARNINGS limit 1;
    ROLLBACK;
    RESIGNAL;
  END;

-- Declaramos el control de salida del loop
DECLARE CONTINUE HANDLER FOR NOT FOUND SET termino = TRUE;

-- Abrimos el Cursor
OPEN Datos_Asiento;

-- Iniciamos la Transaccion
START TRANSACTION;

-- Leeemos el Cursor
read_loop: LOOP
FETCH Datos_Asiento INTO fechamovimiento,centros_costosid, concepto, referencia, valor, codigocontable;

-- Verificamos si no hay mas registros
IF termino THEN
LEAVE read_loop;
END IF;

SET diferencia = diferencia+(Round(valor,2));
-- Sumamos valores de debe y haber
IF valor<0 THEN
  SET haber = (haber + (Abs((valor))));
ELSE
  SET debe  = (debe + (Abs((valor))));
END IF;

-- INSERTAMOS LA CABECERA DEL ASIENTO
  IF gravocabecera=FALSE THEN
    -- Optenemos el nuevo secuencial
    call SP_Consulta_Secuencias_Internas('LIBRODIARIO',codigoasiento);
  
    -- Insertamos Registro Cabecera
    INSERT INTO libros_diarios 
    (
      codigoasiento, 
      fecha, 
      referencia, 
      concepto, 
      origen, 
      usuariocreacion, 
      fechacreacion
    ) 
    VALUES 
    (
      codigoasiento,
      fechamovimiento,
      referencia, 
      concepto,
      'Cobros', 
      sUsuario, 
      NOW(3)
    );
   
   -- obtenemos el ultimo ID insertado
    SET libros_diariosid=(select LAST_INSERT_ID());
    
    -- Actualizamos el secuencial de libros diarios
    call SP_Actualiza_Secuencias_Internas('LIBRODIARIO');

    -- Ponemos que gravo la cabecera
    SET gravocabecera=TRUE;

  END IF;

-- INSERTAMOS LOS DETALLES
set valor = round(valor,2);
INSERT INTO libros_diarios_detalles
( 	
libros_diariosid,	
codigocontable,	
centros_costosid,	
referencia,	
concepto,	
importe
)
VALUES
( 
libros_diariosid,	
codigocontable,	
centros_costosid,	
referencia,	
concepto,	
valor
 );

-- Toma la primer cuenta del asiento contable
IF cuenta_fija=0 THEN 
SET cuenta_fija = (select LAST_INSERT_ID());
END IF;

END LOOP;

CALL SP_Contabiliza_Verificar_Asiento(libros_diariosid,verificado);


-- Cuadramos el asiento contable si esta descuadrado
IF diferencia<0.11 AND diferencia>-0.11 AND diferencia<>0  THEN
UPDATE libros_diarios_detalles
SET
libros_diarios_detalles.importe = libros_diarios_detalles.importe-diferencia
WHERE
libros_diarios_detalles.libros_diarios_detallesid = cuenta_fija;
SET diferencia=0;
END IF;

-- Verificamos si el asiento esta cuadrado
IF diferencia<>0 THEN
SET verificado=0;
END IF;

-- Actualizamos el libro diario
SET debe = Round(debe,2);
SET haber = Round(haber,2);
UPDATE 
libros_diarios
SET
libros_diarios.debito = debe,
libros_diarios.credito = haber,
libros_diarios.mayorizado = verificado,
libros_diarios.verificado = verificado,
libros_diarios.fechamodificacion = libros_diarios.fechamodificacion
WHERE
libros_diarios.libros_diariosid = libros_diariosid;


-- Actualizamos el ID del libro diario a el cobro
UPDATE
movcaja 
SET
movcaja.asientocontable=libros_diariosid,
movcaja.fechamodificacion = movcaja.fechamodificacion
WHERE
movcaja.asientocontable = 0
AND movcaja.origen = 'Cobros'
AND movcaja.documentosid = nDocumentoid;
UPDATE
movbanco 
SET
movbanco.asientocontable=libros_diariosid,
movbanco.fechamodificacion = movbanco.fechamodificacion
WHERE
movbanco.asientocontable = 0
AND movbanco.documentosid = nDocumentoid
AND movbanco.origen = 'Cobros';
UPDATE
cuentasporcobrar 
SET
cuentasporcobrar.asientocontable=libros_diariosid,
cuentasporcobrar.fechamodificacion = cuentasporcobrar.fechamodificacion
WHERE
cuentasporcobrar.origen = 'Cobros'
AND cuentasporcobrar.asientocontable = 0
AND cuentasporcobrar.cobrosid = nDocumentoid;
UPDATE
cobros
SET
cobros.asientocontable = libros_diariosid,
cobros.fechamodificacion = cobros.fechamodificacion
WHERE
cobros.cobrosid = nDocumentoid
AND cobros.asientocontable = 0;



-- Finalizamos la transaccion
COMMIT;

-- Cerramos el Cursor
CLOSE Datos_Asiento;

-- Devolvemos el ID del Asiento Contable
select libros_diariosid;

END
;;
delimiter ;

-- ----------------------------
-- Procedure structure for SP_Contabiliza_Compras_Agrupado
-- ----------------------------
DROP PROCEDURE IF EXISTS `SP_Contabiliza_Compras_Agrupado`;
delimiter ;;
CREATE PROCEDURE `SP_Contabiliza_Compras_Agrupado`(IN dFechaDesde DATE, IN dFechaHasta DATE, IN sCCIvaCompras VARCHAR(255), IN sCCIceCompras VARCHAR(255), IN sCCIvaPresuntivo VARCHAR(255), IN sCCRentaPresuntivo VARCHAR(255), IN sCCAsumeRenta VARCHAR(255), IN sCCRecepcion VARCHAR(255), IN sUsuario VARCHAR(25), in sTipo INT)
  MODIFIES SQL DATA 
BEGIN

-- Declaramos variables de Cursor
DECLARE termino INT DEFAULT FALSE;
-- DECLARE fechamovimiento date;
DECLARE usuariocreacion varchar(25);
DECLARE centros_costosid int(11);
DECLARE concepto varchar(200);
DECLARE referencia varchar(15);
DECLARE valor decimal(16,8) DEFAULT 0;
DECLARE codigocontable varchar(30);
DECLARE codigoasiento varchar(10);
DECLARE gravocabecera INT DEFAULT FALSE;
DECLARE libros_diariosid bigint DEFAULT 0;
DECLARE debe  decimal(16,8) DEFAULT 0;
DECLARE haber decimal(16,8) DEFAULT 0;
DECLARE diferencia decimal(12,2) DEFAULT 0;
DECLARE verificado INT DEFAULT TRUE;
DECLARE cuenta_fija bigint DEFAULT 0;
DECLARE vTipo INT DEFAULT 0; 
DECLARE VCuadrarH  decimal(12,2) DEFAULT 0;
DECLARE VCuadrarD  decimal(12,2) DEFAULT 0;

DECLARE Datos_Asiento CURSOR FOR
SELECT -- productos
compras_detalles.centros_costosid AS centros_costosid,
compras.concepto AS concepto,
compras.secuencia AS referencia,
ROUND(SUM(CASE WHEN compras.movinventarios_tiposid <> 2 THEN ((compras_detalles.costoneto * compras_detalles.cantidad))
ELSE -((compras_detalles.costoneto * compras_detalles.cantidad	) )	END	),8) AS valor,
  productos.cuentacontable_inventarios AS codigocontable
--	'Productos' as consulta
FROM
compras,
compras_detalles,
productos
WHERE
compras.comprasid = compras_detalles.comprasid
and compras_detalles.origen <> 2
AND compras.asientocontable = 0
AND productos.productosid = compras_detalles.productosid
AND DATE(compras.emision) BETWEEN dFechaDesde AND dFechaHasta
GROUP BY
compras_detalles.centros_costosid,
productos.cuentacontable_inventarios
having
SUM(CASE WHEN compras.movinventarios_tiposid <> 2 THEN ((compras_detalles.costoneto * compras_detalles.cantidad))
ELSE - ((compras_detalles.costoneto * compras_detalles.cantidad	) )	END	)<>0 

UNION

  SELECT
compras_detalles.centros_costosid AS centros_costosid,
compras.concepto AS concepto,
compras.secuencia AS referencia,
ROUND(SUM(CASE WHEN compras.movinventarios_tiposid <> 2 THEN ((compras_detalles.costoneto * compras_detalles.cantidad))
ELSE -((compras_detalles.costoneto * compras_detalles.cantidad	) )	END	),8) AS valor,
-- 'Productos' as consulta
  sCCRecepcion AS codigocontable
FROM
compras,
compras_detalles,
productos
WHERE
compras.comprasid = compras_detalles.comprasid
and compras_detalles.origen = 2
AND compras.asientocontable = 0
AND productos.productosid = compras_detalles.productosid
AND DATE(compras.emision) BETWEEN dFechaDesde AND dFechaHasta
GROUP BY
compras_detalles.centros_costosid,
productos.cuentacontable_inventarios
having	
SUM(CASE WHEN compras.movinventarios_tiposid <> 2 THEN ((compras_detalles.costoneto * compras_detalles.cantidad))
ELSE - ((compras_detalles.costoneto * compras_detalles.cantidad	) )	END	)<>0 

UNION

  SELECT
compras.centros_costosid AS CentroCostoID,
compras.concepto AS concepto,
compras.retencionsecuencia AS referencia,
-SUM(compras_retenciones.valor) AS valor,
-- 'Retenciones' AS consulta
  compras_retenciones.codigocontable AS codigocontable
FROM
compras,
compras_retenciones
WHERE
compras.comprasid = compras_retenciones.comprasid
AND compras.asientocontable = 0
AND compras_retenciones.anulado =0
AND vTipo <> 1  and compras.asientocontable = compras.asientocontable_retencion
AND DATE(compras.emision) BETWEEN dFechaDesde AND dFechaHasta
GROUP BY
compras_retenciones.codigocontable,
compras.centros_costosid
HAVING
SUM(compras_retenciones.valor)<>0

UNION

  SELECT
compras.centros_costosid AS CentroCostoID,
compras.concepto AS concepto,
compras.secuencia AS referencia,
SUM(CASE	WHEN compras.movinventarios_tiposid <> 2 THEN	((compras.total_iva + compras.total_iva2))	ELSE -((compras.total_iva + compras.total_iva2))	END) AS valor,
-- 'IVA' AS consulta
  sCCIvaCompras AS codigocontable
FROM
compras
WHERE
DATE(compras.emision) BETWEEN dFechaDesde AND dFechaHasta
AND compras.asientocontable = 0
AND (compras.total_iva + compras.total_iva2 )<>0
GROUP BY
compras.centros_costosid 
HAVING
SUM(CASE	WHEN compras.movinventarios_tiposid <> 2 THEN	compras.total_iva	ELSE - compras.total_iva	END)<>0

UNION

  SELECT
compras.centros_costosid AS CentroCostoID,
compras.concepto AS concepto,
compras.secuencia AS referencia,
SUM(CASE	WHEN compras.movinventarios_tiposid <> 2 THEN	compras.total_ice	ELSE -compras.total_ice	END) AS valor,
-- 'ICE' AS consulta
  sCCIceCompras AS codigocontable
FROM
compras
WHERE
DATE(compras.emision) BETWEEN dFechaDesde AND dFechaHasta
AND compras.asientocontable = 0
AND compras.total_ice<>0
GROUP BY
compras.centros_costosid 
HAVING
SUM(CASE	WHEN compras.movinventarios_tiposid <> 2 THEN	compras.total_ice	ELSE - compras.total_ice	END)<>0

UNION

  SELECT
compras.centros_costosid AS CentroCostoID,
compras.concepto AS concepto,
compras.secuencia AS referencia,
SUM(CASE	WHEN compras.movinventarios_tiposid <> 2 THEN	compras.ivapresuntivo	ELSE -compras.ivapresuntivo	END) AS valor,
-- 'IVA Presuntivo' AS consulta
  sCCIvaPresuntivo AS codigocontable
FROM
compras
WHERE
DATE(compras.emision) BETWEEN dFechaDesde AND dFechaHasta
AND compras.asientocontable = 0
AND compras.ivapresuntivo<>0
GROUP BY
compras.centros_costosid 
HAVING
SUM(CASE	WHEN compras.movinventarios_tiposid <> 2 THEN	compras.ivapresuntivo	ELSE - compras.ivapresuntivo	END)<>0

UNION

  SELECT
compras.centros_costosid AS CentroCostoID,
compras.concepto AS concepto,
compras.secuencia AS referencia,
SUM(CASE	WHEN compras.movinventarios_tiposid <> 2 THEN	(compras.rentapresuntivo)	ELSE -(compras.rentapresuntivo)	END) AS valor,
-- 'IRBP Renta Presuntivo' AS consulta
  sCCRentaPresuntivo AS codigocontable
FROM
compras
WHERE
DATE(compras.emision) BETWEEN dFechaDesde AND dFechaHasta
AND compras.asientocontable = 0
AND compras.rentapresuntivo<>0
GROUP BY
compras.centros_costosid 
HAVING
SUM(CASE	WHEN compras.movinventarios_tiposid <> 2 THEN	compras.rentapresuntivo	ELSE - compras.rentapresuntivo	END)<>0

UNION

  SELECT
compras.centros_costosid AS CentroCostoID,
compras.concepto AS concepto,
compras.secuencia AS referencia,
SUM(compras.retenciontotal) AS valor,
-- 'Retención Asumida' AS consulta
  sCCAsumeRenta AS codigocontable
FROM
compras
WHERE
DATE(compras.emision) BETWEEN dFechaDesde AND dFechaHasta
AND compras.asientocontable = 0
AND compras.asumirretencion<>0
AND compras.retenciontotal<>0
AND vTipo <> 1 and compras.asientocontable = compras.asientocontable_retencion
GROUP BY
compras.centros_costosid 
HAVING
SUM(compras.retenciontotal)<>0

UNION 

  SELECT
movcaja.centros_costosid AS centros_costosid,
movcaja.concepto AS concepto,
movcaja.documentoorigen AS referencia,
SUM(movcaja.importe) AS valor,	
-- 'Caja' AS consulta
  cajas.codigocontable AS codigocontable
FROM
cajas,
movcaja
WHERE
cajas.cajasid = movcaja.cajasid
AND movcaja.asientocontable = 0
AND (
movcaja.forma_pago_empresaid = 1 
AND
movcaja.fechamovimiento BETWEEN dFechaDesde AND dFechaHasta
)
AND movcaja.origen = 'Compras'
GROUP BY
cajas.codigocontable
HAVING
SUM(movcaja.importe)<>0

UNION

  SELECT
cuentasporpagar.centros_costosid AS centros_costosid,
cuentasporpagar.concepto AS concepto,
cuentasporpagar.secuencia AS referencia,
-SUM(cuentasporpagar.importe) AS valor,
-- 'Banco' AS consulta
  bancos.codigocontable AS codigocontable
FROM
bancos,
cuentasporpagar
WHERE
bancos.bancosid = cuentasporpagar.bancosid
AND cuentasporpagar.asientocontable = 0
AND (
cuentasporpagar.forma_pago_empresaid IN (3,5,7)
AND cuentasporpagar.emision BETWEEN dFechaDesde AND dFechaHasta
AND cuentasporpagar.origen = 'Compras'
)
GROUP BY
bancos.codigocontable
HAVING
SUM(cuentasporpagar.importe)<>0

UNION
SELECT
compras.centros_costosid AS CentroCostoID,
compras.concepto AS concepto,
compras.secuencia AS referencia,
SUM(
   CASE WHEN (
              
                (cuentasporpagar.documentosid = compras.comprasid 
                AND cuentasporpagar.tipo NOT IN ( 'NC', 'ND','IR' ) 
                AND compras.sri_documentoscodigo NOT IN ( '04', '05', '372', '373', '47', '48' ) 
                AND cuentasporpagar.relaciondocumentoid = 0
            
              ) 
              OR
            (
                cuentasporpagar.relaciondocumentoid = compras.comprasid 
                AND cuentasporpagar.tipo IN ( 'NC', 'ND' ) 
                AND compras.sri_documentoscodigo IN ( '04', '05', '372', '373', '47', '48' )
            )
          ) THEN cuentasporpagar.importe  

   WHEN (
              cuentasporpagar.tipo = 'IR' 
              AND ((compras.asumirretencion = 1 AND vTipo = 1 ) or (vTipo = 0 and compras.asientocontable = compras.asientocontable_retencion))
              AND 
                (
                  (
                      cuentasporpagar.relaciondocumentoid = compras.comprasid 
                      AND compras.sri_documentoscodigo IN ( '04', '05', '372', '373', '47', '48' )
                  ) 
                  OR 
                  (
                    cuentasporpagar.documentosid = compras.comprasid 
                    AND compras.sri_documentoscodigo NOT IN ( '04', '05', '372', '373', '47', '48' ) 
                    AND cuentasporpagar.relaciondocumentoid = 0 
                  ) 
                )  
            ) THEN cuentasporpagar.importe
              
        
  ELSE 0 
    END 
) AS valor,
-- 'Proveedor' AS consulta
  proveedores.codigocontable AS codigocontable
FROM
cuentasporpagar,
compras,
proveedores
WHERE
proveedores.proveedoresid = compras.proveedoresid
AND cuentasporpagar.origen = 'Compras'
AND compras.asientocontable = 0
AND DATE(compras.emision) BETWEEN dFechaDesde AND dFechaHasta
GROUP BY
proveedores.codigocontable,
compras.centros_costosid
HAVING
SUM(
  CASE WHEN (
              
                (cuentasporpagar.documentosid = compras.comprasid 
                AND cuentasporpagar.tipo NOT IN ( 'NC', 'ND','IR' ) 
                AND compras.sri_documentoscodigo NOT IN ( '04', '05', '372', '373', '47', '48' ) 
                AND cuentasporpagar.relaciondocumentoid = 0
            
              ) 
              OR
            (
                cuentasporpagar.relaciondocumentoid = compras.comprasid 
                AND cuentasporpagar.tipo IN ( 'NC', 'ND' ) 
                AND compras.sri_documentoscodigo IN ( '04', '05', '372', '373', '47', '48' )
            )
          ) THEN cuentasporpagar.importe  

   WHEN (
              cuentasporpagar.tipo = 'IR' 
              AND ((compras.asumirretencion = 1 AND vTipo = 1 ) or (vTipo = 0 and compras.asientocontable = compras.asientocontable_retencion))
              AND 
                (
                  (
                      cuentasporpagar.relaciondocumentoid = compras.comprasid 
                      AND compras.sri_documentoscodigo IN ( '04', '05', '372', '373', '47', '48' )
                  ) 
                  OR 
                  (
                    cuentasporpagar.documentosid = compras.comprasid 
                    AND compras.sri_documentoscodigo NOT IN ( '04', '05', '372', '373', '47', '48' ) 
                    AND cuentasporpagar.relaciondocumentoid = 0 
                  ) 
                )  
            ) THEN cuentasporpagar.importe
              
        
  ELSE 0 
    END 
) <>0


UNION

  SELECT
compras.centros_costosid AS centros_costosid,
compras.concepto AS concepto,
compras.secuencia AS referencia,
-sum(compras.total_gastoImportacion) as valor,
-- 'Importación' AS consulta
  compras.codigocontable_gastoimportacion AS codigocontable
FROM
compras
WHERE
compras.asientocontable = 0
and DATE(compras.emision) BETWEEN dFechaDesde AND dFechaHasta
HAVING
sum(compras.total_gastoImportacion)<>0;



-- Controlamos si hubo error
DECLARE exit handler FOR SQLEXCEPTION, SQLWARNING
  BEGIN
  	SHOW WARNINGS limit 1;
    ROLLBACK;
    RESIGNAL;
  END;

-- Declaramos el control de salida del loop
DECLARE CONTINUE HANDLER FOR NOT FOUND SET termino = TRUE;
SET vTipo = sTipo;
-- Abrimos el Cursor
OPEN Datos_Asiento;

-- Iniciamos la Transaccion
START TRANSACTION;

-- Leeemos el Cursor
read_loop: LOOP
FETCH Datos_Asiento INTO centros_costosid, concepto, referencia, valor, codigocontable;

-- Verificamos si no hay mas registros
IF termino THEN
LEAVE read_loop;
END IF;

SET diferencia = ROUND(diferencia+(Round(valor,2)),2);
-- Sumamos valores de debe y haber
IF valor<0 THEN
  SET haber = (haber + (Abs((valor))));
ELSE
  SET debe  = (debe + (Abs((valor))));
END IF;

-- INSERTAMOS LA CABECERA DEL ASIENTO
  IF gravocabecera=FALSE THEN
    -- Optenemos el nuevo secuencial
    call SP_Consulta_Secuencias_Internas('LIBRODIARIO',codigoasiento);
  
    -- Insertamos Registro Cabecera
    INSERT INTO libros_diarios 
    (
      codigoasiento, 
      fecha, 
      referencia, 
      concepto, 
      origen, 
      usuariocreacion, 
      fechacreacion
    ) 
    VALUES 
    (
      codigoasiento,
      dFechaHasta,
      codigoasiento, 
      CONCAT('Compras de ',DATE_FORMAT(dFechaDesde,"%d-%m-%Y"),' a ',DATE_FORMAT(dFechaHasta,"%d-%m-%Y")),
      'Compras', 
      sUsuario, 
      NOW()
    );
   
   -- obtenemos el ultimo ID insertado
    SET libros_diariosid=(select LAST_INSERT_ID());
    
    -- Actualizamos el secuencial de libros diarios
    call SP_Actualiza_Secuencias_Internas('LIBRODIARIO');

    -- Ponemos que gravo la cabecera
    SET gravocabecera=TRUE;

  END IF;

-- INSERTAMOS LOS DETALLES
set valor = round(valor,2);
INSERT INTO libros_diarios_detalles
( 	
libros_diariosid,	
codigocontable,	
centros_costosid,	
referencia,	
concepto,	
importe
)
VALUES
( 
libros_diariosid,	
codigocontable,	
centros_costosid,	
codigoasiento,	
CONCAT('Compras de ',DATE_FORMAT(dFechaDesde,"%d-%m-%Y"),' a ',DATE_FORMAT(dFechaHasta,"%d-%m-%Y")),
ROUND(valor,2)
 );

-- Toma la primer cuenta del asiento contable
IF cuenta_fija=0 THEN 
SET cuenta_fija = (select LAST_INSERT_ID());
END IF;

END LOOP;

CALL SP_Contabiliza_Verificar_Asiento(libros_diariosid,verificado);


-- Cuadramos el asiento contable si esta descuadrado
IF diferencia<0.11 AND diferencia>-0.11 AND diferencia<>0  THEN
UPDATE libros_diarios_detalles
SET
libros_diarios_detalles.importe = libros_diarios_detalles.importe-diferencia
WHERE
libros_diarios_detalles.libros_diarios_detallesid = cuenta_fija;
SET diferencia=0;
END IF;

-- Verificamos si el asiento esta cuadrado
IF diferencia<>0 THEN
SET verificado=0;
END IF;


-- Actualizamos el libro diario
set VCuadrarH = (SELECT SUM(libros_diarios_detalles.importe) FROM libros_diarios_detalles WHERE libros_diarios_detalles.libros_diariosid = libros_diariosid AND libros_diarios_detalles.importe < 0);
set VCuadrarD = (SELECT SUM(libros_diarios_detalles.importe) FROM libros_diarios_detalles WHERE libros_diarios_detalles.libros_diariosid = libros_diariosid AND libros_diarios_detalles.importe > 0);

-- Actualizamos el libro diario 
SET haber =ABS(ROUND(VCuadrarH,2));
SET debe = ABS(ROUND(VCuadrarD,2));

UPDATE 
libros_diarios
SET
libros_diarios.debito = debe,
libros_diarios.credito = haber,
libros_diarios.mayorizado = verificado,
libros_diarios.verificado = verificado,
libros_diarios.fechamodificacion = libros_diarios.fechamodificacion
WHERE
libros_diarios.libros_diariosid = libros_diariosid;


-- Actualizamos el ID del libro diario a los movimientos de la compra
UPDATE
movcaja 
SET
movcaja.asientocontable=libros_diariosid,
movcaja.fechamodificacion=movcaja.fechamodificacion
WHERE
movcaja.asientocontable = 0
AND movcaja.origen = 'Compras'
AND movcaja.fechamovimiento BETWEEN dFechaDesde AND dFechaHasta;
UPDATE
movbanco 
SET
movbanco.asientocontable=libros_diariosid,
movbanco.fechamodificacion=movbanco.fechamodificacion
WHERE
movbanco.asientocontable = 0
AND movbanco.fechamovimiento BETWEEN dFechaDesde AND dFechaHasta
AND movbanco.origen = 'Compras';
UPDATE
cuentasporpagar 
SET
cuentasporpagar.asientocontable=libros_diariosid,
cuentasporpagar.fechamodificacion=cuentasporpagar.fechamodificacion 
WHERE
cuentasporpagar.origen = 'Compras'
AND cuentasporpagar.asientocontable = 0
AND cuentasporpagar.emision BETWEEN dFechaDesde AND dFechaHasta;
UPDATE
compras
SET
compras.asientocontable = libros_diariosid,
compras.fechamodificacion = compras.fechamodificacion
WHERE
DATE(compras.emision) BETWEEN dFechaDesde AND dFechaHasta
AND compras.asientocontable = 0;

UPDATE
compras
SET
compras.asientocontable_retencion = libros_diariosid
WHERE
DATE(compras.emision) BETWEEN dFechaDesde AND dFechaHasta
AND compras.asientocontable_retencion = 0;

-- Finalizamos la transaccion
COMMIT;

-- Cerramos el Cursor
CLOSE Datos_Asiento;

-- Devolvemos el ID del Asiento Contable
select libros_diariosid;


END
;;
delimiter ;

-- ----------------------------
-- Procedure structure for SP_Contabiliza_Compras_Individual
-- ----------------------------
DROP PROCEDURE IF EXISTS `SP_Contabiliza_Compras_Individual`;
delimiter ;;
CREATE PROCEDURE `SP_Contabiliza_Compras_Individual`(IN nDocumentoid BIGINT, IN sCCIvaCompras VARCHAR(255), IN sCCIceCompras VARCHAR(255), IN sCCIvaPresuntivo VARCHAR(255), IN sCCRentaPresuntivo VARCHAR(255), IN sCCAsumeRenta VARCHAR(255), IN sCCRecepcion VARCHAR(255), IN sUsuario VARCHAR(25), IN sTipo INT)
  MODIFIES SQL DATA 
BEGIN

-- Declaramos variables de Cursor
DECLARE termino INT DEFAULT FALSE;
DECLARE fechamovimiento date;
DECLARE usuariocreacion varchar(25);
DECLARE centros_costosid int(11);
DECLARE concepto varchar(200);
DECLARE referencia varchar(15);
DECLARE valor decimal(16,8) DEFAULT 0;
DECLARE codigocontable varchar(30);
DECLARE codigoasiento varchar(15);
DECLARE gravocabecera INT DEFAULT FALSE;
DECLARE libros_diariosid bigint DEFAULT 0;
DECLARE debe  decimal(16,8) DEFAULT 0;
DECLARE haber decimal(16,8) DEFAULT 0;
DECLARE diferencia decimal(12,2) DEFAULT 0;
DECLARE verificado INT DEFAULT TRUE;
DECLARE cuenta_fija bigint DEFAULT 0;
DECLARE VCuadrarH  decimal(12,2) DEFAULT 0;
DECLARE VCuadrarD  decimal(12,2) DEFAULT 0;
DECLARE vTipo INT DEFAULT 0;

DECLARE Datos_Asiento CURSOR FOR
SELECT
 DATE(compras.emision) as fechamovimiento,
compras_detalles.centros_costosid AS centros_costosid,
compras.concepto AS concepto,
compras.secuencia AS referencia,
ROUND(SUM(	CASE	WHEN compras.movinventarios_tiposid <> 2 THEN ((compras_detalles.costoneto * compras_detalles.cantidad))
ELSE	- ((compras_detalles.costoneto * compras_detalles.cantidad))	END	),8) AS valor,
-- 'Productos' AS consulta
  productos.cuentacontable_inventarios AS codigocontable
FROM
compras,
compras_detalles,
productos
WHERE
compras.comprasid = compras_detalles.comprasid
AND compras_detalles.origen <> 2
AND compras.asientocontable = 0
AND productos.productosid = compras_detalles.productosid
AND compras.comprasid = nDocumentoid
GROUP BY
compras_detalles.centros_costosid,
productos.cuentacontable_inventarios	
HAVING
SUM(	CASE	WHEN compras.movinventarios_tiposid <> 2 THEN((compras_detalles.costoneto * compras_detalles.cantidad))
ELSE	- ((compras_detalles.costoneto * compras_detalles.cantidad))	END	)<>0

UNION

  SELECT
DATE(compras.emision) as fechamovimiento,
compras_detalles.centros_costosid AS centros_costosid,
compras.concepto AS concepto,
compras.secuencia AS referencia,
ROUND(SUM(	CASE	WHEN compras.movinventarios_tiposid <> 2 THEN ((compras_detalles.costoneto * compras_detalles.cantidad))
ELSE	- ((compras_detalles.costoneto * compras_detalles.cantidad))	END	),8) AS valor,
-- 'Productos recepcion' AS consulta
  sCCRecepcion AS codigocontable
FROM
compras,
compras_detalles,
productos
WHERE
compras.comprasid = compras_detalles.comprasid
AND compras_detalles.origen = 2
AND compras.asientocontable = 0
AND productos.productosid = compras_detalles.productosid
AND compras.comprasid = nDocumentoid
GROUP BY
compras_detalles.centros_costosid,
productos.cuentacontable_inventarios	
HAVING
SUM(	CASE	WHEN compras.movinventarios_tiposid <> 2 THEN((compras_detalles.costoneto * compras_detalles.cantidad))
ELSE	- ((compras_detalles.costoneto * compras_detalles.cantidad))	END	)<>0

UNION

  SELECT
DATE(compras.emision) as fechamovimiento,
compras.centros_costosid AS CentroCostoID,
compras.concepto AS concepto,
compras.retencionsecuencia AS referencia,
-SUM(compras_retenciones.valor) AS valor,
-- 'Retencion' AS consulta
  compras_retenciones.codigocontable AS codigocontable
FROM
compras,
compras_retenciones
WHERE
compras.comprasid = compras_retenciones.comprasid
AND compras.asientocontable = 0
AND compras_retenciones.anulado =0
AND compras.comprasid = nDocumentoid
AND vTipo <> 1 and compras.asientocontable=compras.asientocontable_retencion
GROUP BY
compras_retenciones.codigocontable,
compras.centros_costosid
HAVING
SUM(compras_retenciones.valor) <> 0 

UNION

  SELECT
DATE(compras.emision) as fechamovimiento,
compras.centros_costosid AS CentroCostoID,
  compras.concepto AS concepto,
compras.secuencia AS referencia,
SUM(CASE	WHEN compras.movinventarios_tiposid <> 2 THEN	((compras.total_iva + compras.total_iva2))	ELSE -((compras.total_iva + compras.total_iva2)) END) AS valor,
-- 'IVA' AS consulta
sCCIvaCompras AS codigocontable
FROM
compras
WHERE
compras.comprasid = nDocumentoid
AND compras.asientocontable = 0
AND (compras.total_iva + compras.total_iva2 )<>0
GROUP BY
compras.centros_costosid 

UNION

  SELECT
DATE(compras.emision) as fechamovimiento,
  compras.centros_costosid AS CentroCostoID,
compras.concepto AS concepto,
compras.secuencia AS referencia,
SUM(CASE	WHEN compras.movinventarios_tiposid <> 2 THEN	(compras.total_ice)	ELSE - (compras.total_ice)	END) AS valor,
-- 'ICE' AS consulta
  sCCIceCompras AS codigocontable
FROM
compras
WHERE
compras.comprasid = nDocumentoid
AND compras.asientocontable = 0
AND compras.total_ice<>0
GROUP BY
compras.centros_costosid 

UNION

  SELECT
DATE(compras.emision) as fechamovimiento,
compras.centros_costosid AS CentroCostoID,
compras.concepto AS concepto,
compras.secuencia AS referencia,
SUM(CASE	WHEN compras.movinventarios_tiposid <> 2 THEN	(compras.ivapresuntivo)	ELSE -(compras.ivapresuntivo)	END) AS valor,
  -- 'IVA Presuntivo' AS consulta
sCCIvaPresuntivo AS codigocontable
FROM
compras
WHERE
compras.comprasid = nDocumentoid
AND compras.asientocontable = 0
AND compras.ivapresuntivo<>0
GROUP BY
compras.centros_costosid 

UNION

  SELECT
DATE(compras.emision) as fechamovimiento,
compras.centros_costosid AS CentroCostoID,
compras.concepto AS concepto,
compras.secuencia AS referencia,
SUM(CASE	WHEN compras.movinventarios_tiposid <> 2 THEN	(compras.rentapresuntivo)	ELSE -(compras.rentapresuntivo)	END) AS valor,
-- 'IRBP Renta Presuntivo' AS consulta
sCCRentaPresuntivo AS codigocontable
FROM
compras
WHERE
compras.comprasid = nDocumentoid
AND compras.asientocontable = 0
AND compras.rentapresuntivo<>0
GROUP BY
compras.centros_costosid 

UNION

  SELECT
DATE(compras.emision) as fechamovimiento,
compras.centros_costosid AS CentroCostoID,
compras.concepto AS concepto,
compras.secuencia AS referencia,
SUM(compras.retenciontotal) AS valor,
-- 'Retencion asumida' AS consulta
sCCAsumeRenta AS codigocontable
FROM
compras
WHERE
compras.comprasid = nDocumentoid
AND compras.asientocontable = 0
AND compras.asumirretencion<>0
AND compras.retenciontotal<>0
AND vTipo <> 1 and compras.asientocontable=compras.asientocontable_retencion
GROUP BY
compras.centros_costosid 

UNION

  SELECT
movcaja.fechamovimiento AS fechamovimiento,
  movcaja.centros_costosid AS centros_costosid,
movcaja.concepto AS concepto,
movcaja.documentoorigen AS referencia,
SUM(movcaja.importe) AS valor,	
-- 'Caja' AS consulta
cajas.codigocontable AS codigocontable
FROM
cajas,
movcaja
WHERE
cajas.cajasid = movcaja.cajasid
AND movcaja.asientocontable = 0
AND (
movcaja.forma_pago_empresaid = 1
AND movcaja.documentosid = nDocumentoid
)
AND movcaja.origen = 'Compras'
GROUP BY
cajas.codigocontable
HAVING
SUM(movcaja.importe)<>0

UNION

  SELECT
cuentasporpagar.emision as fechamovimiento,
  cuentasporpagar.centros_costosid AS centros_costosid,
cuentasporpagar.concepto AS concepto,
cuentasporpagar.secuencia AS referencia,
-SUM(cuentasporpagar.importe) AS valor,	
-- 'Banco' AS consulta
bancos.codigocontable AS codigocontable
FROM
bancos,
cuentasporpagar
WHERE
bancos.bancosid = cuentasporpagar.bancosid
AND cuentasporpagar.asientocontable = 0
AND (
cuentasporpagar.forma_pago_empresaid IN (3,5,7)
AND cuentasporpagar.documentosid = nDocumentoid
AND cuentasporpagar.origen = 'Compras'
)
GROUP BY
bancos.codigocontable
HAVING
SUM(cuentasporpagar.importe)<>0

UNION

 SELECT DATE
  ( compras.emision ) AS fechamovimiento,
  compras.centros_costosid AS CentroCostoID,
  compras.concepto AS concepto,
  compras.secuencia AS referencia,
  SUM(
  CASE
      WHEN (
              
                (cuentasporpagar.documentosid = compras.comprasid 
                AND cuentasporpagar.tipo NOT IN ( 'NC', 'ND','IR' ) 
                AND compras.sri_documentoscodigo NOT IN ( '04', '05', '372', '373', '47', '48' ) 
                AND cuentasporpagar.relaciondocumentoid = 0
            
              ) 
              OR
            (
                cuentasporpagar.relaciondocumentoid = compras.comprasid 
                AND cuentasporpagar.tipo IN ( 'NC', 'ND' ) 
                AND compras.sri_documentoscodigo IN ( '04', '05', '372', '373', '47', '48' )
            )
          ) THEN cuentasporpagar.importe  

   WHEN (
              cuentasporpagar.tipo = 'IR' 
              AND ((compras.asumirretencion = 1 AND vTipo = 1 ) or (vTipo = 0 and compras.asientocontable=compras.asientocontable_retencion))
              AND 
                (
                  (
                      cuentasporpagar.relaciondocumentoid = compras.comprasid 
                      AND compras.sri_documentoscodigo IN ( '04', '05', '372', '373', '47', '48' )
                  ) 
                  OR 
                  (
                    cuentasporpagar.documentosid = compras.comprasid 
                    AND compras.sri_documentoscodigo NOT IN ( '04', '05', '372', '373', '47', '48' ) 
                    AND cuentasporpagar.relaciondocumentoid = 0 
                  ) 
                )  
            ) THEN cuentasporpagar.importe
              
        
  ELSE 0 
    END 
  )AS valor,
-- 'Proveedor' AS consulta
  proveedores.codigocontable AS codigocontable
FROM
cuentasporpagar,
compras,
proveedores
WHERE
proveedores.proveedoresid = compras.proveedoresid
AND cuentasporpagar.origen = 'Compras'
AND compras.forma_pago_empresaid <> 1
AND compras.asientocontable = 0
AND compras.comprasid = nDocumentoid
GROUP BY
proveedores.codigocontable,	
compras.centros_costosid
HAVING
SUM(CASE WHEN (
              (
                cuentasporpagar.documentosid = compras.comprasid 
                AND cuentasporpagar.tipo NOT IN ( 'NC', 'ND','IR' ) 
                AND compras.sri_documentoscodigo NOT IN ( '04', '05', '372', '373', '47', '48' ) 
                AND cuentasporpagar.relaciondocumentoid = 0 
               
              ) 
              OR
            (
                cuentasporpagar.relaciondocumentoid = compras.comprasid 
                AND cuentasporpagar.tipo IN ( 'NC', 'ND' ) 
                AND compras.sri_documentoscodigo IN ( '04', '05', '372', '373', '47', '48' )
            )
          ) THEN cuentasporpagar.importe  

   WHEN (
              cuentasporpagar.tipo = 'IR' 
              AND ((compras.asumirretencion = 1 AND vTipo = 1 ) or (vTipo = 0 and compras.asientocontable=compras.asientocontable_retencion))
              AND 
                (
                  (
                      cuentasporpagar.relaciondocumentoid = compras.comprasid 
                      AND compras.sri_documentoscodigo IN ( '04', '05', '372', '373', '47', '48' )
                  ) 
                  OR 
                  (
                    cuentasporpagar.documentosid = compras.comprasid 
                    AND compras.sri_documentoscodigo NOT IN ( '04', '05', '372', '373', '47', '48' ) 
                    AND cuentasporpagar.relaciondocumentoid = 0 
                  ) 
                )  
            ) THEN cuentasporpagar.importe
              
              
  ELSE 0 
    END
  ) <> 0

UNION

  SELECT
DATE(compras.emision) as fechamovimiento,
compras.centros_costosid AS centros_costosid,
compras.concepto AS concepto,
compras.secuencia AS referencia,
-SUM(compras.total_gastoImportacion) AS valor,
-- 'Importacion' AS consulta
  compras.codigocontable_gastoimportacion AS codigocontable
FROM
compras
WHERE
compras.comprasid = nDocumentoid
HAVING
-SUM(compras.total_gastoImportacion)<>0;

-- Controlamos si hubo error
DECLARE exit handler FOR SQLEXCEPTION, SQLWARNING
  BEGIN
  	SHOW WARNINGS limit 1;
    ROLLBACK;
    RESIGNAL;
  END;

-- Declaramos el control de salida del loop
DECLARE CONTINUE HANDLER FOR NOT FOUND SET termino = TRUE;
SET vTipo = sTipo;
-- Abrimos el Cursor
OPEN Datos_Asiento;

-- Iniciamos la Transaccion
START TRANSACTION;

-- Leeemos el Cursor
read_loop: LOOP
FETCH Datos_Asiento INTO fechamovimiento,centros_costosid, concepto, referencia, valor, codigocontable;

-- Verificamos si no hay mas registros
IF termino THEN
LEAVE read_loop;
END IF;

SET diferencia = ROUND(diferencia+(Round(valor,2)),2);
-- Sumamos valores de debe y haber
-- IF valor<0 THEN
--   SET haber = (haber + (Abs((valor))));
-- ELSE
--  SET debe  = (debe + (Abs((valor))));
-- END IF;

-- INSERTAMOS LA CABECERA DEL ASIENTO
  IF gravocabecera=FALSE THEN
    -- Optenemos el nuevo secuencial
    call SP_Consulta_Secuencias_Internas('LIBRODIARIO',codigoasiento);
  
    -- Insertamos Registro Cabecera
    INSERT INTO libros_diarios 
    (
      codigoasiento, 
      fecha, 
      referencia, 
      concepto, 
      origen, 
      usuariocreacion, 
      fechacreacion
    ) 
    VALUES 
    (
      codigoasiento,
      fechamovimiento,
      referencia, 
      concepto,
      'Compras', 
      sUsuario, 
      NOW(3)
    );
   
   -- obtenemos el ultimo ID insertado
    SET libros_diariosid=(select LAST_INSERT_ID());
    
    -- Actualizamos el secuencial de libros diarios
    call SP_Actualiza_Secuencias_Internas('LIBRODIARIO');

    -- Ponemos que gravo la cabecera
    SET gravocabecera=TRUE;

  END IF;

-- INSERTAMOS LOS DETALLES
set valor = round(valor,2);
INSERT INTO libros_diarios_detalles
( 	
libros_diariosid,	
codigocontable,	
centros_costosid,	
referencia,	
concepto,	
importe
)
VALUES
( 
libros_diariosid,	
codigocontable,	
centros_costosid,	
referencia,	
concepto,
valor
 );

-- Toma la primer cuenta del asiento contable
IF cuenta_fija=0 THEN 
SET cuenta_fija = (select LAST_INSERT_ID());
END IF;

END LOOP;

CALL SP_Contabiliza_Verificar_Asiento(libros_diariosid,verificado);


-- Cuadramos el asiento contable si esta descuadrado
IF diferencia<0.11 AND diferencia>-0.11 AND diferencia<>0  THEN
UPDATE libros_diarios_detalles
SET
libros_diarios_detalles.importe = libros_diarios_detalles.importe-diferencia
WHERE
libros_diarios_detalles.libros_diarios_detallesid = cuenta_fija;
SET diferencia=0;
END IF;

-- Verificamos si el asiento esta cuadrado
IF diferencia<>0 THEN
SET verificado=0;
END IF;

-- LLenamos la cabecera debe y haber sumando los detalles
set VCuadrarH = (SELECT SUM(libros_diarios_detalles.importe) FROM libros_diarios_detalles WHERE libros_diarios_detalles.libros_diariosid = libros_diariosid AND libros_diarios_detalles.importe < 0);
set VCuadrarD = (SELECT SUM(libros_diarios_detalles.importe) FROM libros_diarios_detalles WHERE libros_diarios_detalles.libros_diariosid = libros_diariosid AND libros_diarios_detalles.importe > 0);

-- Actualizamos el libro diario
SET debe = Round(ABS(VCuadrarD),2);
SET haber = Round(ABS(VCuadrarH),2);
UPDATE 
libros_diarios
SET
libros_diarios.debito = debe,
libros_diarios.credito = haber,
libros_diarios.mayorizado = verificado,
libros_diarios.verificado = verificado,
libros_diarios.fechamodificacion = libros_diarios.fechamodificacion
WHERE
libros_diarios.libros_diariosid = libros_diariosid;


-- Actualizamos el ID del libro diario a todos los movimient que intervenga en la compra
UPDATE
movcaja 
SET
movcaja.asientocontable=libros_diariosid,
movcaja.fechamodificacion=movcaja.fechamodificacion
WHERE
movcaja.asientocontable = 0
AND movcaja.origen = 'Compras'
AND movcaja.documentosid = nDocumentoid;
UPDATE
movbanco 
SET
movbanco.asientocontable=libros_diariosid,
movbanco.fechamodificacion=movbanco.fechamodificacion
WHERE
movbanco.asientocontable = 0
AND movbanco.documentosid = nDocumentoid
AND movbanco.origen = 'Compras';
UPDATE
cuentasporpagar 
SET
cuentasporpagar.asientocontable=libros_diariosid,
cuentasporpagar.fechamodificacion=cuentasporpagar.fechamodificacion
WHERE
cuentasporpagar.origen = 'Compras'
AND ((cuentasporpagar.tipo <> 'IR' AND vtipo = 1 ) OR (vtipo <> 1))
AND cuentasporpagar.asientocontable = 0
AND ((cuentasporpagar.documentosid = nDocumentoid AND cuentasporpagar.relaciondocumentoid = 0) OR (cuentasporpagar.relaciondocumentoid = nDocumentoid));
UPDATE
compras
SET
compras.asientocontable = libros_diariosid,
compras.fechamodificacion = compras.fechamodificacion
WHERE
compras.comprasid = nDocumentoid
AND compras.asientocontable = 0;
UPDATE
compras
SET
compras.asientocontable_retencion = libros_diariosid
WHERE
compras.comprasid = nDocumentoid
AND compras.asientocontable_retencion = 0 and vtipo = 0;

-- Finalizamos la transaccion
COMMIT;

-- Cerramos el Cursor
CLOSE Datos_Asiento;

-- Devolvemos el ID del Asiento Contable
select libros_diariosid;

END
;;
delimiter ;

-- ----------------------------
-- Procedure structure for SP_Contabiliza_Compras_Retenciones_Agrupado
-- ----------------------------
DROP PROCEDURE IF EXISTS `SP_Contabiliza_Compras_Retenciones_Agrupado`;
delimiter ;;
CREATE PROCEDURE `SP_Contabiliza_Compras_Retenciones_Agrupado`(IN dFechaDesde DATE, IN dFechaHasta DATE,IN sCCAsumeRenta VARCHAR(255),IN sUsuario VARCHAR(25))
  MODIFIES SQL DATA 
BEGIN

-- Declaramos variables de Cursor
DECLARE termino INT DEFAULT FALSE;
-- DECLARE fechamovimiento date;
DECLARE usuariocreacion varchar(25);
DECLARE centros_costosid int(11);
DECLARE concepto varchar(200);
DECLARE referencia varchar(15);
DECLARE valor decimal(16,8) DEFAULT 0;
DECLARE codigocontable varchar(30);
DECLARE codigoasiento varchar(10);
DECLARE gravocabecera INT DEFAULT FALSE;
DECLARE libros_diariosid bigint DEFAULT 0;
DECLARE debe  decimal(16,8) DEFAULT 0;
DECLARE haber decimal(16,8) DEFAULT 0;
DECLARE diferencia decimal(12,2) DEFAULT 0;
DECLARE verificado INT DEFAULT TRUE;
DECLARE cuenta_fija bigint DEFAULT 0;


DECLARE Datos_Asiento CURSOR FOR
SELECT
compras.centros_costosid AS CentroCostoID,
compras.concepto AS concepto,
compras.retencionsecuencia AS referencia,
-SUM(compras_retenciones.valor) AS valor,
-- 'Retenciones' AS consulta
  compras_retenciones.codigocontable AS codigocontable
FROM
compras
JOIN
compras_retenciones ON compras.comprasid = compras_retenciones.comprasid
WHERE
 compras.asientocontable_retencion = 0
AND compras_retenciones.anulado =0
AND DATE(compras.emision) BETWEEN dFechaDesde AND dFechaHasta
GROUP BY
compras_retenciones.codigocontable,
compras.centros_costosid
HAVING
SUM(compras_retenciones.valor)<>0


UNION

  SELECT 

  compras.centros_costosid AS CentroCostoID,
  compras.concepto AS concepto,
  compras.secuencia AS referencia,
 SUM( cxp.importe ) AS valor,
  (
  CASE
     WHEN compras.asumirretencion = 1 THEN
      sCCAsumeRenta
      WHEN cxp.forma_pago_empresaid = 1 THEN
      cajas.codigocontable 
      WHEN cxp.forma_pago_empresaid = 2 THEN
      proveedores.codigocontable 
      WHEN cxp.forma_pago_empresaid IN ( 3, 7 ) THEN
      bancos.codigocontable 
      ELSE
      proveedores.codigocontable 
    END  
    ) AS codigocontable 
  FROM
    cuentasporpagar AS cxp
    JOIN compras ON cxp.documentosid = compras.comprasid
    JOIN proveedores ON proveedores.proveedoresid = compras.proveedoresid
    LEFT JOIN cajas ON cajas.cajasid = (
    SELECT
      cajas.cajasid 
    FROM
      cajas
      JOIN cuentasporpagar ON cxp.forma_pago_empresaid = 1 AND cajas.cajasid = cuentasporpagar.cajasid 
    WHERE
      cuentasporpagar.documentosid = cxp.documentosid 
      AND cuentasporpagar.tipo = 'AB' 
      AND cuentasporpagar.cajasid <> 0 
      AND cuentasporpagar.forma_pago_empresaid = cxp.forma_pago_empresaid 
      LIMIT 1 
    )
    LEFT JOIN bancos ON cxp.forma_pago_empresaid IN (3,7) AND bancos.bancosid = (
    SELECT
      bancos.bancosid 
    FROM
      bancos
      JOIN cuentasporpagar ON bancos.bancosid = cuentasporpagar.bancosid 
    WHERE
      cuentasporpagar.documentosid = cxp.documentosid 
      AND cuentasporpagar.tipo = 'AB' 
      AND cuentasporpagar.bancosid <> 0 
      AND cuentasporpagar.forma_pago_empresaid = cxp.forma_pago_empresaid 
      LIMIT 1 
    ) 
  WHERE
    cxp.origen = 'Compras' 
    AND compras.asientocontable_retencion = 0 
    AND DATE(compras.emision) BETWEEN dFechaDesde AND dFechaHasta
    AND cxp.tipo IN ( "IR" ) 
  GROUP BY
    compras.centros_costosid,
  CASE
     WHEN compras.asumirretencion = 1 THEN
      sCCAsumeRenta
      WHEN cxp.forma_pago_empresaid = 1 THEN
      cajas.codigocontable 
      WHEN cxp.forma_pago_empresaid = 2 THEN
      proveedores.codigocontable 
      WHEN cxp.forma_pago_empresaid IN ( 3, 7 ) THEN
      bancos.codigocontable 
      ELSE
      proveedores.codigocontable 
    END  
    HAVING
    SUM(
   cxp.importe ) > 0;





-- Controlamos si hubo error
DECLARE exit handler FOR SQLEXCEPTION, SQLWARNING
  BEGIN
  	SHOW WARNINGS limit 1;
    ROLLBACK;
    RESIGNAL;
  END;

-- Declaramos el control de salida del loop
DECLARE CONTINUE HANDLER FOR NOT FOUND SET termino = TRUE;
-- Abrimos el Cursor
OPEN Datos_Asiento;

-- Iniciamos la Transaccion
START TRANSACTION;

-- Leeemos el Cursor
read_loop: LOOP
FETCH Datos_Asiento INTO centros_costosid, concepto, referencia, valor, codigocontable;

-- Verificamos si no hay mas registros
IF termino THEN
LEAVE read_loop;
END IF;

SET diferencia = ROUND(diferencia+(Round(valor,2)),2);
-- Sumamos valores de debe y haber
IF valor<0 THEN
  SET haber = (haber + (Abs((valor))));
ELSE
  SET debe  = (debe + (Abs((valor))));
END IF;

-- INSERTAMOS LA CABECERA DEL ASIENTO
  IF gravocabecera=FALSE THEN
    -- Optenemos el nuevo secuencial
    call SP_Consulta_Secuencias_Internas('LIBRODIARIO',codigoasiento);
  
    -- Insertamos Registro Cabecera
    INSERT INTO libros_diarios 
    (
      codigoasiento, 
      fecha, 
      referencia, 
      concepto, 
      origen, 
      usuariocreacion, 
      fechacreacion
    ) 
    VALUES 
    (
      codigoasiento,
      dFechaHasta,
      codigoasiento, 
      CONCAT('Compras de ',DATE_FORMAT(dFechaDesde,"%d-%m-%Y"),' a ',DATE_FORMAT(dFechaHasta,"%d-%m-%Y")),
      'Retenciones', 
      sUsuario, 
      NOW()
    );
   
   -- obtenemos el ultimo ID insertado
    SET libros_diariosid=(select LAST_INSERT_ID());
    
    -- Actualizamos el secuencial de libros diarios
    call SP_Actualiza_Secuencias_Internas('LIBRODIARIO');

    -- Ponemos que gravo la cabecera
    SET gravocabecera=TRUE;

  END IF;

-- INSERTAMOS LOS DETALLES
set valor = round(valor,2);
INSERT INTO libros_diarios_detalles
( 	
libros_diariosid,	
codigocontable,	
centros_costosid,	
referencia,	
concepto,	
importe
)
VALUES
( 
libros_diariosid,	
codigocontable,	
centros_costosid,	
codigoasiento,	
CONCAT('Compras de ',DATE_FORMAT(dFechaDesde,"%d-%m-%Y"),' a ',DATE_FORMAT(dFechaHasta,"%d-%m-%Y")),
ROUND(valor,2)
 );

-- Toma la primer cuenta del asiento contable
IF cuenta_fija=0 THEN 
SET cuenta_fija = (select LAST_INSERT_ID());
END IF;

END LOOP;

CALL SP_Contabiliza_Verificar_Asiento(libros_diariosid,verificado);


-- Cuadramos el asiento contable si esta descuadrado
IF diferencia<0.11 AND diferencia>-0.11 AND diferencia<>0  THEN
UPDATE libros_diarios_detalles
SET
libros_diarios_detalles.importe = libros_diarios_detalles.importe-diferencia
WHERE
libros_diarios_detalles.libros_diarios_detallesid = cuenta_fija;
SET diferencia=0;
END IF;

-- Verificamos si el asiento esta cuadrado
IF diferencia<>0 THEN
SET verificado=0;
END IF;

-- Actualizamos el libro diario
SET debe = Round(debe,2);
SET haber = Round(haber,2);
UPDATE 
libros_diarios
SET
libros_diarios.debito = debe,
libros_diarios.credito = haber,
libros_diarios.mayorizado = verificado,
libros_diarios.verificado = verificado,
libros_diarios.fechamodificacion = libros_diarios.fechamodificacion
WHERE
libros_diarios.libros_diariosid = libros_diariosid;


-- Actualizamos el ID del libro diario a los movimientos de la compra

UPDATE
cuentasporpagar 
SET
cuentasporpagar.asientocontable=libros_diariosid,
cuentasporpagar.fechamodificacion=cuentasporpagar.fechamodificacion 
WHERE
cuentasporpagar.origen = 'Compras'
AND cuentasporpagar.asientocontable = 0
AND cuentasporpagar.tipo = "IR"
AND cuentasporpagar.emision BETWEEN dFechaDesde AND dFechaHasta;
UPDATE
compras
JOIN
compras_retenciones on compras.comprasid = compras_retenciones.comprasid
SET
compras.asientocontable_retencion = libros_diariosid,
compras.fechamodificacion = compras.fechamodificacion
WHERE
DATE(compras.emision) BETWEEN dFechaDesde AND dFechaHasta
AND compras.asientocontable_retencion = 0  ;

-- Finalizamos la transaccion
COMMIT;

-- Cerramos el Cursor
CLOSE Datos_Asiento;

-- Devolvemos el ID del Asiento Contable
select libros_diariosid;
 
END
;;
delimiter ;

-- ----------------------------
-- Procedure structure for SP_Contabiliza_Compras_Retenciones_Individual
-- ----------------------------
DROP PROCEDURE IF EXISTS `SP_Contabiliza_Compras_Retenciones_Individual`;
delimiter ;;
CREATE PROCEDURE `SP_Contabiliza_Compras_Retenciones_Individual`(IN nDocumentoid BIGINT, IN sCCAsumeRenta VARCHAR(255),IN sUsuario VARCHAR(25))
  MODIFIES SQL DATA 
BEGIN

-- Declaramos variables de Cursor
DECLARE termino INT DEFAULT FALSE;
DECLARE fechamovimiento date;
DECLARE usuariocreacion varchar(25);
DECLARE centros_costosid int(11);
DECLARE concepto varchar(200);
DECLARE referencia varchar(15);
DECLARE valor decimal(16,8) DEFAULT 0;
DECLARE codigocontable varchar(30);
DECLARE codigoasiento varchar(15);
DECLARE gravocabecera INT DEFAULT FALSE;
DECLARE libros_diariosid bigint DEFAULT 0;
DECLARE debe  decimal(16,8) DEFAULT 0;
DECLARE haber decimal(16,8) DEFAULT 0;
DECLARE diferencia decimal(12,2) DEFAULT 0;
DECLARE verificado INT DEFAULT TRUE;
DECLARE cuenta_fija bigint DEFAULT 0;
DECLARE VCuadrarH  decimal(12,2) DEFAULT 0;
DECLARE VCuadrarD  decimal(12,2) DEFAULT 0;

DECLARE Datos_Asiento CURSOR FOR

 
  SELECT
DATE(compras.emision) as fechamovimiento,
compras.centros_costosid AS CentroCostoID,
compras.concepto AS concepto,
compras.retencionsecuencia AS referencia,
-SUM(compras_retenciones.valor) AS valor,
-- 'Retencion' AS consulta
  compras_retenciones.codigocontable AS codigocontable
FROM
compras,
compras_retenciones
WHERE
compras.comprasid = nDocumentoid
AND compras.asientocontable_retencion = 0
AND compras_retenciones.anulado =0
AND compras_retenciones.comprasid = compras.comprasid 
GROUP BY
compras_retenciones.codigocontable,
compras.centros_costosid
HAVING
SUM(compras_retenciones.valor)<>0

UNION

SELECT 
DATE ( compras.emision ) AS fechamovimiento,
  compras.centros_costosid AS CentroCostoID,
  compras.concepto AS concepto,
  compras.secuencia AS referencia,
 SUM( cxp.importe ) AS valor,
  (
  CASE
    WHEN compras.asumirretencion = 1 THEN
      sCCAsumeRenta
      WHEN cxp.forma_pago_empresaid = 1 THEN
      cajas.codigocontable 
      WHEN cxp.forma_pago_empresaid = 2 THEN
      proveedores.codigocontable 
      WHEN cxp.forma_pago_empresaid IN ( 3, 7 ) THEN
      bancos.codigocontable 
      ELSE
      proveedores.codigocontable 
    END  
    ) AS codigocontable 
  FROM
    cuentasporpagar AS cxp
    JOIN compras ON cxp.documentosid = compras.comprasid
    JOIN proveedores ON proveedores.proveedoresid = compras.proveedoresid
    LEFT JOIN cajas ON cajas.cajasid = (
    SELECT
      cajas.cajasid 
    FROM
      cajas
      JOIN cuentasporpagar ON cxp.forma_pago_empresaid = 1 AND cajas.cajasid = cuentasporpagar.cajasid 
    WHERE
      cuentasporpagar.documentosid = cxp.documentosid 
      AND cuentasporpagar.tipo = 'AB' 
      AND cuentasporpagar.cajasid <> 0 
      AND cuentasporpagar.forma_pago_empresaid = cxp.forma_pago_empresaid 
      LIMIT 1 
    )
    LEFT JOIN bancos ON cxp.forma_pago_empresaid IN (3,7) AND bancos.bancosid = (
    SELECT
      bancos.bancosid 
    FROM
      bancos
      JOIN cuentasporpagar ON bancos.bancosid = cuentasporpagar.bancosid 
    WHERE
      cuentasporpagar.documentosid = cxp.documentosid 
      AND cuentasporpagar.tipo = 'AB' 
      AND cuentasporpagar.bancosid <> 0 
      AND cuentasporpagar.forma_pago_empresaid = cxp.forma_pago_empresaid 
      LIMIT 1 
    ) 
  WHERE
    cxp.origen = 'Compras' 
    AND compras.asientocontable_retencion = 0 
    AND compras.comprasid = nDocumentoid
    AND cxp.tipo IN ( "IR" ) 
  GROUP BY
    compras.centros_costosid,
  CASE WHEN compras.asumirretencion = 1 THEN
      sCCAsumeRenta
      WHEN cxp.forma_pago_empresaid = 1 THEN
      cajas.codigocontable 
      WHEN cxp.forma_pago_empresaid = 2 THEN
      proveedores.codigocontable 
      WHEN cxp.forma_pago_empresaid IN ( 3, 7 ) THEN
      bancos.codigocontable 
      ELSE
      proveedores.codigocontable 
    END  
    HAVING
    SUM(
   cxp.importe ) > 0;

-- Controlamos si hubo error
DECLARE exit handler FOR SQLEXCEPTION, SQLWARNING
  BEGIN
  	SHOW WARNINGS limit 1;
    ROLLBACK;
    RESIGNAL;
  END;

-- Declaramos el control de salida del loop
DECLARE CONTINUE HANDLER FOR NOT FOUND SET termino = TRUE;

-- Abrimos el Cursor
OPEN Datos_Asiento;

-- Iniciamos la Transaccion
START TRANSACTION;

-- Leeemos el Cursor
read_loop: LOOP
FETCH Datos_Asiento INTO fechamovimiento,centros_costosid, concepto, referencia, valor, codigocontable;

-- Verificamos si no hay mas registros
IF termino THEN
LEAVE read_loop;
END IF;

SET diferencia = ROUND(diferencia+(Round(valor,2)),2);
-- Sumamos valores de debe y haber
-- IF valor<0 THEN
--   SET haber = (haber + (Abs((valor))));
-- ELSE
--  SET debe  = (debe + (Abs((valor))));
-- END IF;

-- INSERTAMOS LA CABECERA DEL ASIENTO
  IF gravocabecera=FALSE THEN
    -- Optenemos el nuevo secuencial
    call SP_Consulta_Secuencias_Internas('LIBRODIARIO',codigoasiento);
  
    -- Insertamos Registro Cabecera
    INSERT INTO libros_diarios 
    (
      codigoasiento, 
      fecha, 
      referencia, 
      concepto, 
      origen, 
      usuariocreacion, 
      fechacreacion
    ) 
    VALUES 
    (
      codigoasiento,
      fechamovimiento,
      referencia, 
      concepto,
      'Retenciones', 
      sUsuario, 
      NOW(3)
    );
   
   -- obtenemos el ultimo ID insertado
    SET libros_diariosid=(select LAST_INSERT_ID());
    
    -- Actualizamos el secuencial de libros diarios
    call SP_Actualiza_Secuencias_Internas('LIBRODIARIO');

    -- Ponemos que gravo la cabecera
    SET gravocabecera=TRUE;

  END IF;

-- INSERTAMOS LOS DETALLES
set valor = round(valor,2);
INSERT INTO libros_diarios_detalles
( 	
libros_diariosid,	
codigocontable,	
centros_costosid,	
referencia,	
concepto,	
importe
)
VALUES
( 
libros_diariosid,	
codigocontable,	
centros_costosid,	
referencia,	
concepto,
valor
 );

-- Toma la primer cuenta del asiento contable
IF cuenta_fija=0 THEN 
SET cuenta_fija = (select LAST_INSERT_ID());
END IF;

END LOOP;

CALL SP_Contabiliza_Verificar_Asiento(libros_diariosid,verificado);


-- Cuadramos el asiento contable si esta descuadrado
IF diferencia<0.11 AND diferencia>-0.11 AND diferencia<>0  THEN
UPDATE libros_diarios_detalles
SET
libros_diarios_detalles.importe = libros_diarios_detalles.importe-diferencia
WHERE
libros_diarios_detalles.libros_diarios_detallesid = cuenta_fija;
SET diferencia=0;
END IF;

-- Verificamos si el asiento esta cuadrado
IF diferencia<>0 THEN
SET verificado=0;
END IF;

-- LLenamos la cabecera debe y haber sumando los detalles
set VCuadrarH = (SELECT SUM(libros_diarios_detalles.importe) FROM libros_diarios_detalles WHERE libros_diarios_detalles.libros_diariosid = libros_diariosid AND libros_diarios_detalles.importe < 0);
set VCuadrarD = (SELECT SUM(libros_diarios_detalles.importe) FROM libros_diarios_detalles WHERE libros_diarios_detalles.libros_diariosid = libros_diariosid AND libros_diarios_detalles.importe > 0);

-- Actualizamos el libro diario
SET debe = Round(ABS(VCuadrarD),2);
SET haber = Round(ABS(VCuadrarH),2);
UPDATE 
libros_diarios
SET
libros_diarios.debito = debe,
libros_diarios.credito = haber,
libros_diarios.mayorizado = verificado,
libros_diarios.verificado = verificado,
libros_diarios.fechamodificacion = libros_diarios.fechamodificacion
WHERE
libros_diarios.libros_diariosid = libros_diariosid;


-- Actualizamos el ID del libro diario a todos los movimient que intervenga en la compra
UPDATE
cuentasporpagar 
SET
cuentasporpagar.asientocontable=libros_diariosid,
cuentasporpagar.fechamodificacion=cuentasporpagar.fechamodificacion
WHERE
cuentasporpagar.origen = 'Compras'
AND cuentasporpagar.asientocontable = 0
AND cuentasporpagar.tipo = "IR"
AND ((cuentasporpagar.documentosid = nDocumentoid AND cuentasporpagar.relaciondocumentoid = 0) OR (cuentasporpagar.relaciondocumentoid = nDocumentoid));
UPDATE
compras
SET
compras.asientocontable_retencion = libros_diariosid,
compras.fechamodificacion = compras.fechamodificacion
WHERE
compras.comprasid = nDocumentoid
AND compras.asientocontable_retencion = 0;


-- Finalizamos la transaccion
COMMIT;

-- Cerramos el Cursor
CLOSE Datos_Asiento;

-- Devolvemos el ID del Asiento Contable
select libros_diariosid;
END
;;
delimiter ;

-- ----------------------------
-- Procedure structure for SP_Contabiliza_Compra_Recepcion_Agrupado
-- ----------------------------
DROP PROCEDURE IF EXISTS `SP_Contabiliza_Compra_Recepcion_Agrupado`;
delimiter ;;
CREATE PROCEDURE `SP_Contabiliza_Compra_Recepcion_Agrupado`(IN dFechaDesde DATE, IN dFechaHasta DATE, IN sCCRecepcion VARCHAR(255), IN sUsuario VARCHAR(25))
  MODIFIES SQL DATA 
BEGIN

-- Declaramos variables de Cursor
DECLARE termino INT DEFAULT FALSE;
-- DECLARE fechamovimiento date;
DECLARE usuariocreacion varchar(25);
DECLARE centros_costosid int(11);
DECLARE concepto varchar(200);
DECLARE referencia varchar(15);
DECLARE valor decimal(16,8) DEFAULT 0;
DECLARE codigocontable varchar(30);
DECLARE codigoasiento varchar(10);
DECLARE gravocabecera INT DEFAULT FALSE;
DECLARE libros_diariosid bigint DEFAULT 0;
DECLARE debe  decimal(16,8) DEFAULT 0;
DECLARE haber decimal(16,8) DEFAULT 0;
DECLARE diferencia decimal(12,2) DEFAULT 0;
DECLARE verificado INT DEFAULT TRUE;
DECLARE cuenta_fija bigint DEFAULT 0;

DECLARE Datos_Asiento CURSOR FOR
SELECT 
  compras_recepciones_detalles.centros_costosid AS centros_costosid,
compras_recepciones.concepto AS concepto, 
compras_recepciones.compras_recepciones_codigo AS referencia,
ROUND(SUM((compras_recepciones_detalles.costoneto*compras_recepciones_detalles.cantidad)),8) AS valor, 
  productos.cuentacontable_inventarios AS codigocontable
FROM compras_recepciones
INNER JOIN (compras_recepciones_detalles
INNER JOIN ( productos) ON compras_recepciones_detalles.productosid = productos.productosid
) ON compras_recepciones.compras_recepcionesid = compras_recepciones_detalles.compras_recepcionesid
WHERE 	
compras_recepciones.asientocontable = 0
AND  DATE(compras_recepciones.emision) BETWEEN dFechaDesde AND dFechaHasta	
GROUP BY 
compras_recepciones_detalles.centros_costosid, 
productos.cuentacontable_inventarios	
HAVING
SUM((compras_recepciones_detalles.costoneto*compras_recepciones_detalles.cantidad))<>0

UNION 

SELECT compras_recepciones_detalles.centros_costosid AS CentroCostoID,
  compras_recepciones.concepto AS concepto, 
compras_recepciones.compras_recepciones_codigo AS referencia,
ROUND(-SUM((compras_recepciones_detalles.costoneto*compras_recepciones_detalles.cantidad)),8) AS valor, 
sCCRecepcion AS codigocontable
FROM compras_recepciones
INNER JOIN (compras_recepciones_detalles
) ON compras_recepciones.compras_recepcionesid = compras_recepciones_detalles.compras_recepcionesid
WHERE 
compras_recepciones.asientocontable = 0
AND  DATE(compras_recepciones.emision) BETWEEN dFechaDesde AND dFechaHasta
GROUP BY 
compras_recepciones_detalles.centros_costosid
HAVING
SUM((compras_recepciones_detalles.costoneto*compras_recepciones_detalles.cantidad))<>0;


-- Controlamos si hubo error
DECLARE exit handler FOR SQLEXCEPTION, SQLWARNING
  BEGIN
  	SHOW WARNINGS limit 1;
    ROLLBACK;
    RESIGNAL;
  END;

-- Declaramos el control de salida del loop
DECLARE CONTINUE HANDLER FOR NOT FOUND SET termino = TRUE;

-- Abrimos el Cursor
OPEN Datos_Asiento;

-- Iniciamos la Transaccion
START TRANSACTION;

-- Leeemos el Cursor
read_loop: LOOP
FETCH Datos_Asiento INTO centros_costosid, concepto, referencia, valor, codigocontable;

-- Verificamos si no hay mas registros
IF termino THEN
LEAVE read_loop;
END IF;

SET diferencia = diferencia+(Round(valor,2));
-- Sumamos valores de debe y haber
IF valor<0 THEN
  SET haber = (haber + (Abs((valor))));
ELSE
  SET debe  = (debe + (Abs((valor))));
END IF;

-- INSERTAMOS LA CABECERA DEL ASIENTO
  IF gravocabecera=FALSE THEN
    -- Optenemos el nuevo secuencial
    call SP_Consulta_Secuencias_Internas('LIBRODIARIO',codigoasiento);
  
    -- Insertamos Registro Cabecera
    INSERT INTO libros_diarios 
    (
      codigoasiento, 
      fecha, 
      referencia, 
      concepto, 
      origen, 
      usuariocreacion, 
      fechacreacion
    ) 
    VALUES 
    (
      codigoasiento,
      dFechaHasta,
      codigoasiento, 
      CONCAT('Recepciones de ',DATE_FORMAT(dFechaDesde,"%d-%m-%Y"),' a ',DATE_FORMAT(dFechaHasta,"%d-%m-%Y")),
      'Recepciones', 
      sUsuario, 
      NOW()
    );
   
   -- obtenemos el ultimo ID insertado
    SET libros_diariosid=(select LAST_INSERT_ID());
    
    -- Actualizamos el secuencial de libros diarios
    call SP_Actualiza_Secuencias_Internas('LIBRODIARIO');

    -- Ponemos que gravo la cabecera
    SET gravocabecera=TRUE;

  END IF;

-- INSERTAMOS LOS DETALLES
set valor = round(valor,2);
INSERT INTO libros_diarios_detalles
( 	
libros_diariosid,	
codigocontable,	
centros_costosid,	
referencia,	
concepto,	
importe
)
VALUES
( 
libros_diariosid,	
codigocontable,	
centros_costosid,	
referencia,	
concepto,	
valor
 );

-- Toma la primer cuenta del asiento contable
IF cuenta_fija=0 THEN 
SET cuenta_fija = (select LAST_INSERT_ID());
END IF;

END LOOP;

CALL SP_Contabiliza_Verificar_Asiento(libros_diariosid,verificado);


-- Cuadramos el asiento contable si esta descuadrado
IF diferencia<0.11 AND diferencia>-0.11 AND diferencia<>0  THEN
UPDATE libros_diarios_detalles
SET
libros_diarios_detalles.importe = libros_diarios_detalles.importe-diferencia
WHERE
libros_diarios_detalles.libros_diarios_detallesid = cuenta_fija;
SET diferencia=0;
END IF;

-- Verificamos si el asiento esta cuadrado
IF diferencia<>0 THEN
SET verificado=0;
END IF;

-- Actualizamos el libro diario
SET debe = Round(debe,2);
SET haber = Round(haber,2);
UPDATE 
libros_diarios
SET
libros_diarios.debito = debe,
libros_diarios.credito = haber,
libros_diarios.mayorizado = verificado,
libros_diarios.verificado = verificado,
libros_diarios.fechamodificacion = libros_diarios.fechamodificacion
WHERE
libros_diarios.libros_diariosid = libros_diariosid;


-- Actualizamos el ID del libro diario a la recepcion de compras
UPDATE
compras_recepciones
SET
compras_recepciones.asientocontable = libros_diariosid,
compras_recepciones.fechamodificacion = compras_recepciones.fechamodificacion
WHERE
DATE(compras_recepciones.emision) BETWEEN dFechaDesde AND dFechaHasta
AND compras_recepciones.asientocontable = 0;


-- Finalizamos la transaccion
COMMIT;

-- Cerramos el Cursor
CLOSE Datos_Asiento;

-- Devolvemos el ID del Asiento Contable
select libros_diariosid;

END
;;
delimiter ;

