-- ----------------------------
-- Procedure structure for SP_Contabiliza_Cruce_CliProv_Agrupado
-- ----------------------------
DROP PROCEDURE IF EXISTS `SP_Contabiliza_Cruce_CliProv_Agrupado`;
delimiter ;;
CREATE PROCEDURE `SP_Contabiliza_Cruce_CliProv_Agrupado`(IN sCodigoContableNC VARCHAR(255), IN dFechaDesde DATE, IN dFechaHasta DATE, IN sUsuario VARCHAR(25))
  MODIFIES SQL DATA 
BEGIN

-- Declaramos variables de Cursor
DECLARE termino INT DEFAULT FALSE;
DECLARE usuariocreacion varchar(25);
DECLARE centros_costosid int(11);
DECLARE concepto varchar(200);
DECLARE valor decimal(16,8) DEFAULT 0;
DECLARE codigocontable varchar(30);
DECLARE codigoasiento varchar(10);
DECLARE grabocabecera INT DEFAULT FALSE;
DECLARE libros_diariosidNC bigint DEFAULT 0;
DECLARE libros_diariosidND bigint DEFAULT 0;
DECLARE debe  decimal(16,8) DEFAULT 0;
DECLARE haber decimal(16,8) DEFAULT 0;
DECLARE diferencia decimal(12,2) DEFAULT 0;
DECLARE verificado INT DEFAULT TRUE;
DECLARE cuenta_fija bigint DEFAULT 0;
DECLARE idMovimiento bigint DEFAULT 0;
DECLARE sTipo varchar(30);

-- ------------------------------------------------
-- Cuentas por Cobrar
-- ------------------------------------------------
DECLARE Datos_Asiento_NC_Cobros CURSOR FOR

SELECT 
  cuentasporcobrar.centros_costosid as centros_costosid,
SUM(cuentasporcobrar.Importe) AS valor,
clientes.CodigoContable AS codigocontable
From
cuentasporcobrar,
clientes
Where
cuentasporcobrar.ClientesID=clientes.ClientesID
AND cuentasporcobrar.CuentasporCobrarID IN (
  SELECT 
CuentasporCobrar.CuentasporCobrarID
FROM
CuentasporCobrar
WHERE
CuentasporCobrar.Concepto like 'CRUCE CLIENTES PROVEEDORES%'
AND (CuentasporCobrar.Emision BETWEEN dFechaDesde AND dFechaHasta)
AND CuentasporCobrar.AsientoContable=0 AND CuentasporCobrar.Tipo = 'NC'
group by
cuentasporcobrar.concepto,
cuentasporcobrar.tipo,
abs(cuentasporcobrar.importe)
  )
AND cuentasporcobrar.tipo ='NC'
GROUP BY 
clientes.CodigoContable,
centros_costosid
having
SUM(cuentasporcobrar.importe)<>0

union 

SELECT 
cuentasporcobrar.centros_costosid AS centros_costosid,
-SUM(cuentasporcobrar.importe) AS valor,
sCodigoContableNC AS codigocontable
From
cuentasporcobrar
Where
cuentasporcobrar.CuentasporCobrarID IN (
    SELECT 
CuentasporCobrar.CuentasporCobrarID
FROM
CuentasporCobrar
WHERE
CuentasporCobrar.Concepto like 'CRUCE CLIENTES PROVEEDORES%'
AND (CuentasporCobrar.Emision BETWEEN dFechaDesde AND dFechaHasta)
AND CuentasporCobrar.AsientoContable=0 AND CuentasporCobrar.Tipo = 'NC'
group by
cuentasporcobrar.concepto,
cuentasporcobrar.tipo,
abs(cuentasporcobrar.importe)
  )
AND cuentasporcobrar.tipo ='NC'
GROUP BY 
cuentasporcobrar.centros_costosid
HAVING
SUM(cuentasporcobrar.importe)<>0;

-- ------------------------------------------------------------
-- Cuentas por pagar
-- ------------------------------------------------------------
DECLARE Datos_Asiento_NC_Pagos CURSOR FOR
SELECT 
cuentasporpagar.centros_costosid AS centros_costosid,
SUM(cuentasporpagar.importe) AS valor,
Proveedores.codigocontable AS codigocontable
FROM
cuentasporpagar,
proveedores
WHERE
cuentasporpagar.proveedoresid=proveedores.proveedoresid
AND cuentasporpagar.cuentasporpagarid IN (
SELECT 
cuentasporpagar.cuentasporpagarid
FROM
cuentasporpagar
WHERE
cuentasporpagar.concepto LIKE 'CRUCE CLIENTES PROVEEDORES%'
AND (cuentasporpagar.emision BETWEEN dFechaDesde AND dFechaHasta)
AND cuentasporpagar.asientocontable=0 AND cuentasporpagar.tipo = 'NC'
group by
cuentasporpagar.concepto,
cuentasporpagar.tipo,
 abs(cuentasporpagar.importe)
)
AND cuentasporpagar.tipo ='NC'
GROUP BY 
proveedores.codigocontable,
centros_costosid
HAVING
SUM(cuentasporpagar.importe)<>0

UNION 

SELECT 
cuentasporpagar.centros_costosid AS centros_costosid,
-SUM(cuentasporpagar.importe) AS valor,
sCodigoContableNC AS codigocontable
FROM
cuentasporpagar
WHERE
cuentasporpagar.cuentasporpagarid IN (
SELECT 
cuentasporpagar.cuentasporpagarid
FROM
cuentasporpagar
WHERE
cuentasporpagar.concepto LIKE 'CRUCE CLIENTES PROVEEDORES%'
AND (cuentasporpagar.emision BETWEEN dFechaDesde AND dFechaHasta)
AND cuentasporpagar.asientocontable=0 AND cuentasporpagar.tipo = 'NC'
group by
cuentasporpagar.concepto,
cuentasporpagar.tipo,
 abs(cuentasporpagar.importe)
)
AND cuentasporpagar.tipo ='NC'
GROUP BY 
cuentasporpagar.centros_costosid
HAVING
SUM(cuentasporpagar.importe)<>0;


-- Controlamos si hubo error
DECLARE exit handler FOR SQLEXCEPTION, SQLWARNING
  BEGIN
  	SHOW WARNINGS limit 1;
    ROLLBACK;
    RESIGNAL;
  END;

-- Declaramos el control de salida del loop
DECLARE CONTINUE HANDLER FOR NOT FOUND SET termino = TRUE;

-- CREAMOS EL ASIENTO DE LA NOTA DE CREDITO
-- Abrimos el Cursor de la nc
OPEN Datos_Asiento_NC_Cobros;

-- Leeemos el Cursor
read_loop_nc_cobros: LOOP
FETCH Datos_Asiento_NC_Cobros INTO centros_costosid, valor, codigocontable;

  -- Verificamos si no hay mas registros
  IF termino THEN
  LEAVE read_loop_nc_cobros;
  END IF;
  
  SET diferencia = diferencia+(Round(valor,2));
  -- Sumamos valores de debe y haber
IF valor<0 THEN
  SET haber = (haber + (Abs((valor))));
ELSE
  SET debe  = (debe + (Abs((valor))));
END IF;
  
  -- INSERTAMOS LA CABECERA DEL ASIENTO de nc
    IF grabocabecera=FALSE THEN
      set concepto = CONCAT('Cruce Clientes Proveedores de ',DATE_FORMAT(dFechaDesde,"%d-%m-%Y"),' a ',DATE_FORMAT(dFechaHasta,"%d-%m-%Y"));
      -- Optenemos el nuevo secuencial
      call SP_Consulta_Secuencias_Internas('LIBRODIARIO',codigoasiento);
    
      -- Insertamos Registro Cabecera
      INSERT INTO libros_diarios 
      (
        codigoasiento, 
        fecha, 
        referencia, 
        concepto, 
        origen, 
        usuariocreacion, 
        fechacreacion
      ) 
      VALUES 
      (
        codigoasiento,
        dFechaHasta,
        codigoasiento, 
        concepto,
        'Ajuste CXC', 
        sUsuario, 
        NOW()
      );
     
     -- obtenemos el ultimo ID insertado
      SET libros_diariosidNC=(select LAST_INSERT_ID());
      
      -- Actualizamos el secuencial de libros diarios
      call SP_Actualiza_Secuencias_Internas('LIBRODIARIO');
  
      -- Ponemos que gravo la cabecera
      SET grabocabecera=TRUE;
  
    END IF;
  
  -- INSERTAMOS LOS DETALLES de la nc
  SET valor = round(valor,2);
  INSERT INTO libros_diarios_detalles
  ( 	
  libros_diariosid,	
  codigocontable,	
  centros_costosid,	
  referencia,	
  concepto,	
  importe
  )
  VALUES
  ( 
  libros_diariosidNC,	
  codigocontable,	
  centros_costosid,	
  codigoasiento,	
  concepto,
  valor
   );
  
  -- Toma la primer cuenta del asiento contable de la nc
  IF cuenta_fija=0 THEN 
  SET cuenta_fija = (select LAST_INSERT_ID());
  END IF;

END LOOP; -- fin del loop nc

-- iniciamos la verificacion del asiento de NC
CALL SP_Contabiliza_Verificar_Asiento(libros_diariosidNC,verificado);

-- Cuadramos el asiento contable si esta descuadrado
IF diferencia<0.11 AND diferencia>-0.11 AND diferencia<>0  THEN
UPDATE libros_diarios_detalles
SET
libros_diarios_detalles.importe = libros_diarios_detalles.importe-diferencia
WHERE
libros_diarios_detalles.libros_diarios_detallesid = cuenta_fija;
SET diferencia=0;
END IF;

-- Verificamos si el asiento esta cuadrado
IF diferencia<>0 THEN
SET verificado=0;
END IF;

-- Actualizamos el libro diario
SET debe = Round(debe,2);
SET haber = Round(haber,2);
UPDATE 
libros_diarios
SET
libros_diarios.debito = debe,
libros_diarios.credito = haber,
libros_diarios.mayorizado = verificado,
libros_diarios.verificado = verificado
WHERE
libros_diarios.libros_diariosid = libros_diariosidNC;

-- ---------------------------------------------------------------------------------------------
-- CREAMOS EL ASIENTO CONTABLE DE NC Pagos
-- Abrimos el Cursor de la nd
OPEN Datos_Asiento_NC_Pagos;

-- enceramos las variables para el asiento de nd
set termino = FALSE;
set diferencia = 0;
set haber = 0;
set debe = 0;
set grabocabecera = FALSE;

-- Leeemos el Cursor
read_loop_nd: LOOP
FETCH Datos_Asiento_NC_Pagos INTO centros_costosid, valor, codigocontable;

  -- Verificamos si no hay mas registros
  IF termino THEN
  LEAVE read_loop_nd;
  END IF;
  
  SET diferencia = diferencia+(Round(valor,2));
  -- Sumamos valores de debe y haber
  IF valor<0 THEN
    SET haber = haber + (Abs(Round(valor,2)));
  ELSE
    SET debe  = debe + (Abs(Round(valor,2)));
  END IF;
  
  -- INSERTAMOS LA CABECERA DEL ASIENTO de nd
    IF grabocabecera=FALSE THEN
    set concepto = CONCAT('Cruce Clientes Proveedores de ',DATE_FORMAT(dFechaDesde,"%d-%m-%Y"),' a ',DATE_FORMAT(dFechaHasta,"%d-%m-%Y"));
      -- Optenemos el nuevo secuencial
      call SP_Consulta_Secuencias_Internas('LIBRODIARIO',codigoasiento);
    
      -- Insertamos Registro Cabecera de la nd
      INSERT INTO libros_diarios 
      (
        codigoasiento, 
        fecha, 
        referencia, 
        concepto, 
        origen, 
        usuariocreacion, 
        fechacreacion
      ) 
      VALUES 
      (
        codigoasiento,
        dFechaHasta,
        codigoasiento, 
        concepto,
        'Ajuste CXP', 
        sUsuario, 
        NOW()
      );
     
     -- obtenemos el ultimo ID insertado de la nd
      SET libros_diariosidND=(select LAST_INSERT_ID());
      
      -- Actualizamos el secuencial de libros diarios
      call SP_Actualiza_Secuencias_Internas('LIBRODIARIO');
  
      -- Ponemos que gravo la cabecera
      SET grabocabecera=TRUE;
  
    END IF;
  
  -- INSERTAMOS LOS DETALLES de la nd
  SET valor = round(valor,2);
  INSERT INTO libros_diarios_detalles
  ( 	
  libros_diariosid,	
  codigocontable,	
  centros_costosid,	
  referencia,	
  concepto,	
  importe
  )
  VALUES
  ( 
  libros_diariosidND,	
  codigocontable,	
  centros_costosid,	
  codigoasiento,	
  concepto,
  ROUND(valor,2)
   );
  
  -- Toma la primer cuenta del asiento contable
  IF cuenta_fija=0 THEN 
  SET cuenta_fija = (select LAST_INSERT_ID());
  END IF;

END LOOP; -- fin del loop nd

CALL SP_Contabiliza_Verificar_Asiento(libros_diariosidND,verificado);


-- Cuadramos el asiento contable si esta descuadrado
IF diferencia<0.11 AND diferencia>-0.11 AND diferencia<>0  THEN
UPDATE libros_diarios_detalles
SET
libros_diarios_detalles.importe = libros_diarios_detalles.importe-diferencia
WHERE
libros_diarios_detalles.libros_diarios_detallesid = cuenta_fija;
END IF;

-- Verificamos si el asiento esta cuadrado
IF diferencia<>0 THEN
SET verificado=0;
END IF;

-- Actualizamos el libro diario
UPDATE 
libros_diarios
SET
libros_diarios.debito = debe,
libros_diarios.credito = haber,
libros_diarios.mayorizado = verificado,
libros_diarios.verificado = verificado
WHERE
libros_diarios.libros_diariosid = libros_diariosidND;


-- Actualizamos el ID del libro diario en la nota de credito Cobro
UPDATE cuentasporcobrar SET AsientoContable=libros_diariosidNC 
WHERE 
CuentasporCobrar.CuentasporCobrarID IN (
  SELECT 
CuentasporCobrar.CuentasporCobrarID
FROM
CuentasporCobrar
WHERE
CuentasporCobrar.Concepto like 'CRUCE CLIENTES PROVEEDORES%'
AND (CuentasporCobrar.Emision BETWEEN dFechaDesde AND dFechaHasta)
AND CuentasporCobrar.AsientoContable=0 AND CuentasporCobrar.Tipo = 'NC'
group by
cuentasporcobrar.concepto,
cuentasporcobrar.tipo,
abs(cuentasporcobrar.importe)
);

-- Actualizamos el ID del libro diario en la nota de debito Pagos
UPDATE cuentasporpagar SET asientocontable=libros_diariosidND
WHERE 
cuentasporpagar.cuentasporpagarid IN (
SELECT 
cuentasporpagar.cuentasporpagarid
FROM
cuentasporpagar
WHERE
cuentasporpagar.concepto LIKE 'CRUCE CLIENTES PROVEEDORES%'
AND (cuentasporpagar.emision BETWEEN dFechaDesde AND dFechaHasta)
AND cuentasporpagar.asientocontable=0 AND cuentasporpagar.tipo = 'NC'
group by
cuentasporpagar.concepto,
cuentasporpagar.tipo,
 abs(cuentasporpagar.importe)
)
AND cuentasporpagar.asientocontable=0;


-- Finalizamos la transaccion
COMMIT;

-- Cerramos el Cursor de la nc
CLOSE Datos_Asiento_NC_Cobros;

-- Cerramos el Cursor de la nd
CLOSE Datos_Asiento_NC_Pagos;

-- Devolvemos el ID del Asiento Contable de la nd y la nc
SELECT libros_diariosidNC, libros_diariosidND;

END
;;
delimiter ;

-- ----------------------------
-- Procedure structure for SP_Contabiliza_Cruce_CliProv_Individual
-- ----------------------------
DROP PROCEDURE IF EXISTS `SP_Contabiliza_Cruce_CliProv_Individual`;
delimiter ;;
CREATE PROCEDURE `SP_Contabiliza_Cruce_CliProv_Individual`(IN sCombinacion VARCHAR(255), IN sTipo VARCHAR(255), IN sCcNCInterna VARCHAR(255), IN sUsuario VARCHAR(25), IN sOrigen VARCHAR(25))
  MODIFIES SQL DATA 
BEGIN

-- Declaramos variables de Cursor
DECLARE termino INT DEFAULT FALSE;
DECLARE fechamovimiento date;
DECLARE usuariocreacion varchar(25);
DECLARE centros_costosid int(11);
DECLARE concepto varchar(200);
DECLARE referencia varchar(15);
DECLARE valor decimal(16,8) DEFAULT 0;
DECLARE codigocontable varchar(30);
DECLARE codigoasiento varchar(10);
DECLARE grabocabecera INT DEFAULT FALSE;
DECLARE libros_diariosid bigint DEFAULT 0;
DECLARE debe  decimal(16,8) DEFAULT 0;
DECLARE haber decimal(16,8) DEFAULT 0;
DECLARE diferencia decimal(12,2) DEFAULT 0;
DECLARE verificado INT DEFAULT TRUE;
DECLARE cuenta_fija bigint DEFAULT 0;



DECLARE Datos_Generales_Cobros CURSOR FOR
SELECT 
cuentasporcobrar.emision AS fechamovimiento,
cuentasporcobrar.concepto AS concepto,
cuentasporcobrar.secuencial as referencia
from
cuentasporcobrar
where
cuentasporcobrar.origen = 'Cobros'
AND cuentasporcobrar.concepto =  sCombinacion
AND cuentasporcobrar.asientocontable = 0
AND cuentasporcobrar.tipo=sTipo;

DECLARE Datos_Generales_Pagos CURSOR FOR
SELECT 
cuentasporpagar.emision AS fechamovimiento,
cuentasporpagar.concepto,
 cuentasporpagar.secuencia AS referencia
FROM
cuentasporpagar
WHERE
cuentasporpagar.origen='Pagos'
AND cuentasporpagar.concepto = sCombinacion
AND cuentasporpagar.asientocontable=0
AND cuentasporpagar.tipo=sTipo;


-- -------------------------------------------------
-- Dtos de NC cobros
-- -------------------------------------------------
DECLARE Datos_Asiento_NC_Cobros CURSOR FOR

SELECT 
CuentasporCobrar.centros_costosid AS centros_costosid,
SUM(CuentasporCobrar.Importe) AS valor,
Clientes.CodigoContable AS codigocontable
FROM
CuentasporCobrar,
Clientes
WHERE
CuentasporCobrar.ClientesID=Clientes.ClientesID
AND cuentasporcobrar.concepto=sCombinacion
AND CuentasporCobrar.Tipo=sTipo
AND cuentasporcobrar.asientocontable=0
GROUP BY 
Clientes.CodigoContable,
cuentasporcobrar.centros_costosid 
HAVING
SUM(cuentasporcobrar.importe)<>0
UNION
SELECT 
    CuentasporCobrar.centros_costosid AS centros_costosid,
-SUM(CuentasporCobrar.Importe) AS valor,
sCcNCInterna AS codigocontable
FROM
cuentasporcobrar
Where
cuentasporcobrar.Origen='Cobros'
AND cuentasporcobrar.concepto=sCombinacion
AND cuentasporcobrar.asientocontable=0
AND CuentasporCobrar.Tipo=sTipo
GROUP BY 
cuentasporcobrar.centros_costosid
HAVING
SUM(cuentasporcobrar.importe)<>0;


-- -------------------------------------------------
-- Datos NC de Pagos
-- -------------------------------------------------
DECLARE Datos_Asiento_NC_Pagos CURSOR FOR
SELECT 
cuentasporpagar.centros_costosid AS centros_costosid,
SUM(cuentasporpagar.Importe) AS valor,
proveedores.CodigoContable AS codigocontable
FROM
cuentasporpagar,
proveedores
WHERE
cuentasporpagar.proveedoresid=proveedores.proveedoresid
AND cuentasporpagar.concepto=sCombinacion
AND cuentasporpagar.Tipo=sTipo
AND cuentasporpagar.asientocontable=0
GROUP BY 
proveedores.CodigoContable,
cuentasporpagar.centros_costosid 
HAVING
SUM(cuentasporpagar.importe)<>0
UNION
SELECT 
 cuentasporpagar.centros_costosid AS centros_costosid,
-SUM(cuentasporpagar.Importe) AS valor,
sCcNCInterna AS codigocontable
FROM
cuentasporpagar
Where
cuentasporpagar.Origen='Pagos'
AND cuentasporpagar.concepto=sCombinacion
AND cuentasporpagar.asientocontable=0
AND cuentasporpagar.Tipo=sTipo
GROUP BY 
cuentasporpagar.centros_costosid
HAVING
SUM(cuentasporpagar.importe)<>0;


-- Controlamos si hubo error
DECLARE exit handler FOR SQLEXCEPTION, SQLWARNING
  BEGIN
    ROLLBACK;
    RESIGNAL;
  END;

-- Declaramos el control de salida del loop
DECLARE CONTINUE HANDLER FOR NOT FOUND SET termino = TRUE;

-- Abrimos el Cursor
OPEN Datos_Generales_Cobros;
OPEN Datos_Generales_Pagos;
-- Iniciamos la Transaccion
START TRANSACTION;

-- Leeemos el Cursor
read_loop: LOOP
FETCH Datos_Generales_Cobros INTO fechamovimiento, concepto, referencia;
FETCH Datos_Generales_Pagos INTO fechamovimiento, concepto, referencia;
-- Verificamos si no hay mas registros
IF termino THEN
LEAVE read_loop;
END IF;

END LOOP;

set termino = FALSE;


IF  sOrigen = 'Cobros' THEN -- inicio de comparacion del tipo de transaccion

  -- CREAMOS EL ASIENTO DE LA NOTA DE CREDITO
  -- Abrimos el Cursor de la nc
  OPEN Datos_Asiento_NC_Cobros;
  
  -- Leeemos el Cursor
  read_loop_nc: LOOP
  FETCH Datos_Asiento_NC_Cobros INTO centros_costosid, valor, codigocontable;
  
    -- Verificamos si no hay mas registros
    IF termino THEN
    LEAVE read_loop_nc;
    END IF;
    
    SET diferencia = diferencia+(Round(valor,2));
    -- Sumamos valores de debe y haber
IF valor<0 THEN
  SET haber = (haber + (Abs((valor))));
ELSE
  SET debe  = (debe + (Abs((valor))));
END IF;
    
    -- INSERTAMOS LA CABECERA DEL ASIENTO de nc
      IF grabocabecera=FALSE THEN
        -- Optenemos el nuevo secuencial
        call SP_Consulta_Secuencias_Internas('LIBRODIARIO',codigoasiento);
      
        -- Insertamos Registro Cabecera
        INSERT INTO libros_diarios 
        (
          codigoasiento, 
          fecha, 
          referencia, 
          concepto, 
          origen, 
          usuariocreacion, 
          fechacreacion
        ) 
        VALUES 
        (
          codigoasiento,
          fechamovimiento,
          referencia, 
          concepto,
          'Ajuste CXC', 
          sUsuario, 
          NOW()
        );
       
       -- obtenemos el ultimo ID insertado
        SET libros_diariosid=(select LAST_INSERT_ID());
        
        -- Actualizamos el secuencial de libros diarios
        call SP_Actualiza_Secuencias_Internas('LIBRODIARIO');
    
        -- Ponemos que gravo la cabecera
        SET grabocabecera=TRUE;
    
      END IF;
    
    -- INSERTAMOS LOS DETALLES de la nc
    SET valor = round(valor,2);
    INSERT INTO libros_diarios_detalles
    ( 	
    libros_diariosid,	
    codigocontable,	
    centros_costosid,	
    referencia,	
    concepto,	
    importe
    )
    VALUES
    ( 
    libros_diariosid,	
    codigocontable,	
    centros_costosid,	
    referencia,	
    concepto,
    valor
     );
    
    -- Toma la primer cuenta del asiento contable de la nc
    IF cuenta_fija=0 THEN 
    SET cuenta_fija = (select LAST_INSERT_ID());
    END IF;
  
  END LOOP; -- fin del loop nc
  
ELSE

  -- CREAMOS EL ASIENTO CONTABLE DE ND
  -- Abrimos el Cursor de la nd
  OPEN Datos_Asiento_NC_Pagos;
  
  -- enceramos las variables para el asiento de nd
  set termino = FALSE;
  set diferencia = 0;
  set haber = 0;
  set debe = 0;
  set grabocabecera = FALSE;
  
  -- Leeemos el Cursor
  read_loop_nd: LOOP
  FETCH Datos_Asiento_NC_Pagos INTO centros_costosid, valor, codigocontable;
  
    -- Verificamos si no hay mas registros
    IF termino THEN
    LEAVE read_loop_nd;
    END IF;
    
    SET diferencia = diferencia+(Round(valor,2));
    -- Sumamos valores de debe y haber
    IF valor<0 THEN
      SET haber = haber + (Abs(Round(valor,2)));
    ELSE
      SET debe  = debe + (Abs(Round(valor,2)));
    END IF;
    
    -- INSERTAMOS LA CABECERA DEL ASIENTO de nd
      IF grabocabecera=FALSE THEN
        -- Optenemos el nuevo secuencial
        call SP_Consulta_Secuencias_Internas('LIBRODIARIO',codigoasiento);
      
        -- Insertamos Registro Cabecera de la nd
        INSERT INTO libros_diarios 
        (
          codigoasiento, 
          fecha, 
          referencia, 
          concepto, 
          origen, 
          usuariocreacion, 
          fechacreacion
        ) 
        VALUES 
        (
          codigoasiento,
          fechamovimiento,
          referencia, 
          concepto,
          'Ajuste CXP', 
          sUsuario, 
          NOW()
        );
       
       -- obtenemos el ultimo ID insertado de la nd
        SET libros_diariosid=(select LAST_INSERT_ID());
        
        -- Actualizamos el secuencial de libros diarios
        call SP_Actualiza_Secuencias_Internas('LIBRODIARIO');
    
        -- Ponemos que gravo la cabecera
        SET grabocabecera=TRUE;
    
      END IF;
    
    -- INSERTAMOS LOS DETALLES de la nd
    SET valor = round(valor,2);
    INSERT INTO libros_diarios_detalles
    ( 	
    libros_diariosid,	
    codigocontable,	
    centros_costosid,	
    referencia,	
    concepto,	
    importe
    )
    VALUES
    ( 
    libros_diariosid,	
    codigocontable,	
    centros_costosid,	
    referencia,	
    concepto,
    valor
     );
    
    -- Toma la primer cuenta del asiento contable
    IF cuenta_fija=0 THEN 
    SET cuenta_fija = (select LAST_INSERT_ID());
    END IF;
  
  END LOOP; -- fin del loop nd
END IF; -- FIN DEL IF DE COMPARACION DEL TIPO


 CALL SP_Contabiliza_Verificar_Asiento(libros_diariosid,verificado);
  
  -- Cuadramos el asiento contable si esta descuadrado
  IF diferencia<0.11 AND diferencia>-0.11 AND diferencia<>0  THEN
  UPDATE libros_diarios_detalles
  SET
  libros_diarios_detalles.importe = libros_diarios_detalles.importe-diferencia
  WHERE
  libros_diarios_detalles.libros_diarios_detallesid = cuenta_fija;
  SET diferencia=0;
END IF;

-- Verificamos si el asiento esta cuadrado
IF diferencia<>0 THEN
SET verificado=0;
END IF;

-- Actualizamos el libro diario
SET debe = Round(debe,2);
SET haber = Round(haber,2);
  UPDATE 
  libros_diarios
  SET
  libros_diarios.debito = debe,
  libros_diarios.credito = haber,
  libros_diarios.mayorizado = verificado,
  libros_diarios.verificado = verificado
  WHERE
  libros_diarios.libros_diariosid = libros_diariosid;


IF  sOrigen = 'Cobros' THEN
-- Actualizamos el ID del libro diario a el movimiento de cuentas por cobrar
UPDATE cuentasporcobrar SET cuentasporcobrar.AsientoContable=libros_diariosid
WHERE 
cuentasporcobrar.concepto=sCombinacion
AND cuentasporcobrar.tipo=sTipo
AND cuentasporcobrar.asientocontable=0;

ELSE

-- Actualizamos el ID del libro diario a el movimiento de cuentas por pagar
UPDATE cuentasporpagar SET cuentasporpagar.asientocontable=libros_diariosid
WHERE 
cuentasporpagar.concepto = sCombinacion
AND cuentasporpagar.tipo=sTipo
AND cuentasporpagar.asientocontable=0;

END IF;
-- Finalizamos la transaccion
COMMIT;

-- Cerramos el Cursor de datos generales
CLOSE Datos_Generales_Cobros;
CLOSE Datos_Generales_Pagos;

IF sOrigen = 'Cobros' THEN
  -- Cerramos el Cursor de la nc
  CLOSE Datos_Asiento_NC_Cobros;
ELSE
  -- Cerramos el Cursor de la nd
  CLOSE Datos_Asiento_NC_Pagos;
END IF;

-- Devolvemos el ID del Asiento Contable
select libros_diariosid;

END
;;
delimiter ;

-- ----------------------------
-- Procedure structure for SP_Contabiliza_Cruce_CxC_Agrupado
-- ----------------------------
DROP PROCEDURE IF EXISTS `SP_Contabiliza_Cruce_CxC_Agrupado`;
delimiter ;;
CREATE PROCEDURE `SP_Contabiliza_Cruce_CxC_Agrupado`(IN sCodigoContableAnticipo VARCHAR(255), IN sCodigoContableNC VARCHAR(255), IN dFechaDesde DATE, IN dFechaHasta DATE, IN sUsuario VARCHAR(25))
  MODIFIES SQL DATA 
BEGIN

-- Declaramos variables de Cursor
DECLARE termino INT DEFAULT FALSE;
DECLARE usuariocreacion varchar(25);
DECLARE centros_costosid int(11);
DECLARE concepto varchar(200);
DECLARE valor decimal(16,8) DEFAULT 0;
DECLARE codigocontable varchar(30);
DECLARE codigoasiento varchar(10);
DECLARE grabocabecera INT DEFAULT FALSE;
DECLARE libros_diariosidNC bigint DEFAULT 0;
DECLARE libros_diariosidND bigint DEFAULT 0;
DECLARE debe  decimal(16,8) DEFAULT 0;
DECLARE haber decimal(16,8) DEFAULT 0;
DECLARE diferencia decimal(12,2) DEFAULT 0;
DECLARE verificado INT DEFAULT TRUE;
DECLARE cuenta_fija bigint DEFAULT 0;
DECLARE idMovimiento bigint DEFAULT 0;
DECLARE sTipo varchar(30);

DECLARE Datos_Asiento_NC CURSOR FOR
SELECT 
cuentasporcobrar.centros_costosid as centros_costosid,
SUM(cuentasporcobrar.Importe) AS valor,
clientes.CodigoContable AS codigocontable
From
cuentasporcobrar,
clientes
Where
cuentasporcobrar.ClientesID=clientes.ClientesID
AND cuentasporcobrar.CuentasporCobrarID IN (
  SELECT 
CuentasporCobrar.CuentasporCobrarID
FROM
CuentasporCobrar
WHERE
CuentasporCobrar.Concepto like 'CRUCE ANTICIPO%'
AND (CuentasporCobrar.Emision BETWEEN dFechaDesde AND dFechaHasta)
AND CuentasporCobrar.AsientoContable=0 AND CuentasporCobrar.Tipo = 'NC'
group by
cuentasporcobrar.concepto,
cuentasporcobrar.tipo,
abs(cuentasporcobrar.importe)
  )
AND cuentasporcobrar.tipo ='NC'
GROUP BY 
clientes.CodigoContable,
centros_costosid
having
SUM(cuentasporcobrar.importe)<>0

union 

SELECT 
cuentasporcobrar.centros_costosid AS centros_costosid,
-SUM(cuentasporcobrar.importe) AS valor,
sCodigoContableNC AS codigocontable
From
cuentasporcobrar
Where
cuentasporcobrar.CuentasporCobrarID IN (
    SELECT 
CuentasporCobrar.CuentasporCobrarID
FROM
CuentasporCobrar
WHERE
CuentasporCobrar.Concepto like 'CRUCE ANTICIPO%'
AND (CuentasporCobrar.Emision BETWEEN dFechaDesde AND dFechaHasta)
AND CuentasporCobrar.AsientoContable=0 AND CuentasporCobrar.Tipo = 'NC'
group by
cuentasporcobrar.concepto,
cuentasporcobrar.tipo,
abs(cuentasporcobrar.importe)
  )
AND cuentasporcobrar.tipo ='NC'
GROUP BY 
cuentasporcobrar.centros_costosid
HAVING
SUM(cuentasporcobrar.importe)<>0;

DECLARE Datos_Asiento_ND CURSOR FOR
SELECT 
cuentasporcobrar.Centros_CostosID as centros_costosid,
SUM(cuentasporcobrar.Importe) AS valor,
sCodigoContableAnticipo AS codigocontable
From
cuentasporcobrar
Where
CuentasporCobrar.CuentasporCobrarID IN (
    SELECT 
CuentasporCobrar.CuentasporCobrarID
FROM
CuentasporCobrar
WHERE
CuentasporCobrar.Concepto like 'CRUCE ANTICIPO%'
AND (CuentasporCobrar.Emision BETWEEN dFechaDesde AND dFechaHasta)
AND CuentasporCobrar.AsientoContable=0 AND CuentasporCobrar.Tipo = 'ND'
group by
cuentasporcobrar.concepto,
cuentasporcobrar.tipo,
abs(cuentasporcobrar.importe)
  )
AND cuentasporcobrar.tipo  = 'ND'
GROUP BY 
centros_costosid
HAVING
SUM(cuentasporcobrar.importe)<>0

UNION

SELECT 
cuentasporcobrar.centros_costosid as centros_costosid,
-SUM(cuentasporcobrar.Importe) AS valor,
sCodigoContableNC AS codigocontable
From
cuentasporcobrar
Where
CuentasporCobrar.CuentasporCobrarID IN (
    SELECT 
CuentasporCobrar.CuentasporCobrarID
FROM
CuentasporCobrar
WHERE
CuentasporCobrar.Concepto like 'CRUCE ANTICIPO%'
AND (CuentasporCobrar.Emision BETWEEN dFechaDesde AND dFechaHasta)
AND CuentasporCobrar.AsientoContable=0 AND CuentasporCobrar.Tipo = 'ND'
group by
cuentasporcobrar.concepto,
cuentasporcobrar.tipo,
abs(cuentasporcobrar.importe)
  )
AND cuentasporcobrar.tipo  = 'ND'
GROUP BY 
centros_costosid
HAVING
SUM(cuentasporcobrar.importe)<>0;


-- Controlamos si hubo error
DECLARE exit handler FOR SQLEXCEPTION, SQLWARNING
  BEGIN
  	SHOW WARNINGS limit 1;
    ROLLBACK;
    RESIGNAL;
  END;

-- Declaramos el control de salida del loop
DECLARE CONTINUE HANDLER FOR NOT FOUND SET termino = TRUE;

-- CREAMOS EL ASIENTO DE LA NOTA DE CREDITO
-- Abrimos el Cursor de la nc
OPEN Datos_Asiento_NC;

-- Leeemos el Cursor
read_loop_nc: LOOP
FETCH Datos_Asiento_NC INTO centros_costosid, valor, codigocontable;

  -- Verificamos si no hay mas registros
  IF termino THEN
  LEAVE read_loop_nc;
  END IF;
  
  SET diferencia = diferencia+(Round(valor,2));
  -- Sumamos valores de debe y haber
IF valor<0 THEN
  SET haber = (haber + (Abs((valor))));
ELSE
  SET debe  = (debe + (Abs((valor))));
END IF;
  
  -- INSERTAMOS LA CABECERA DEL ASIENTO de nc
    IF grabocabecera=FALSE THEN
      set concepto = CONCAT('Ajuste CxC Nota de Crédito de ',DATE_FORMAT(dFechaDesde,"%d-%m-%Y"),' a ',DATE_FORMAT(dFechaHasta,"%d-%m-%Y"));
      -- Optenemos el nuevo secuencial
      call SP_Consulta_Secuencias_Internas('LIBRODIARIO',codigoasiento);
    
      -- Insertamos Registro Cabecera
      INSERT INTO libros_diarios 
      (
        codigoasiento, 
        fecha, 
        referencia, 
        concepto, 
        origen, 
        usuariocreacion, 
        fechacreacion
      ) 
      VALUES 
      (
        codigoasiento,
        dFechaHasta,
        codigoasiento, 
        concepto,
        'Ajuste CXC', 
        sUsuario, 
        NOW()
      );
     
     -- obtenemos el ultimo ID insertado
      SET libros_diariosidNC=(select LAST_INSERT_ID());
      
      -- Actualizamos el secuencial de libros diarios
      call SP_Actualiza_Secuencias_Internas('LIBRODIARIO');
  
      -- Ponemos que gravo la cabecera
      SET grabocabecera=TRUE;
  
    END IF;
  
  -- INSERTAMOS LOS DETALLES de la nc
  SET valor = round(valor,2);
  INSERT INTO libros_diarios_detalles
  ( 	
  libros_diariosid,	
  codigocontable,	
  centros_costosid,	
  referencia,	
  concepto,	
  importe
  )
  VALUES
  ( 
  libros_diariosidNC,	
  codigocontable,	
  centros_costosid,	
  codigoasiento,	
  concepto,
  valor
   );
  
  -- Toma la primer cuenta del asiento contable de la nc
  IF cuenta_fija=0 THEN 
  SET cuenta_fija = (select LAST_INSERT_ID());
  END IF;

END LOOP; -- fin del loop nc

-- iniciamos la verificacion del asiento de NC
CALL SP_Contabiliza_Verificar_Asiento(libros_diariosidNC,verificado);

-- Cuadramos el asiento contable si esta descuadrado
IF diferencia<0.11 AND diferencia>-0.11 AND diferencia<>0  THEN
UPDATE libros_diarios_detalles
SET
libros_diarios_detalles.importe = libros_diarios_detalles.importe-diferencia
WHERE
libros_diarios_detalles.libros_diarios_detallesid = cuenta_fija;
SET diferencia=0;
END IF;

-- Verificamos si el asiento esta cuadrado
IF diferencia<>0 THEN
SET verificado=0;
END IF;

-- Actualizamos el libro diario
SET debe = Round(debe,2);
SET haber = Round(haber,2);
UPDATE 
libros_diarios
SET
libros_diarios.debito = debe,
libros_diarios.credito = haber,
libros_diarios.mayorizado = verificado,
libros_diarios.verificado = verificado
WHERE
libros_diarios.libros_diariosid = libros_diariosidNC;


-- CREAMOS EL ASIENTO CONTABLE DE ND
-- Abrimos el Cursor de la nd
OPEN Datos_Asiento_ND;

-- enceramos las variables para el asiento de nd
set termino = FALSE;
set diferencia = 0;
set haber = 0;
set debe = 0;
set grabocabecera = FALSE;

-- Leeemos el Cursor
read_loop_nd: LOOP
FETCH Datos_Asiento_ND INTO centros_costosid, valor, codigocontable;

  -- Verificamos si no hay mas registros
  IF termino THEN
  LEAVE read_loop_nd;
  END IF;
  
  SET diferencia = diferencia+(Round(valor,2));
  -- Sumamos valores de debe y haber
  IF valor<0 THEN
    SET haber = haber + (Abs(Round(valor,2)));
  ELSE
    SET debe  = debe + (Abs(Round(valor,2)));
  END IF;
  
  -- INSERTAMOS LA CABECERA DEL ASIENTO de nd
    IF grabocabecera=FALSE THEN
    set concepto = CONCAT('Ajuste CxC Nota de Débito de ',DATE_FORMAT(dFechaDesde,"%d-%m-%Y"),' a ',DATE_FORMAT(dFechaHasta,"%d-%m-%Y"));
      -- Optenemos el nuevo secuencial
      call SP_Consulta_Secuencias_Internas('LIBRODIARIO',codigoasiento);
    
      -- Insertamos Registro Cabecera de la nd
      INSERT INTO libros_diarios 
      (
        codigoasiento, 
        fecha, 
        referencia, 
        concepto, 
        origen, 
        usuariocreacion, 
        fechacreacion
      ) 
      VALUES 
      (
        codigoasiento,
        dFechaDesde,
        codigoasiento, 
        concepto,
        'Ajuste CXC', 
        sUsuario, 
        NOW()
      );
     
     -- obtenemos el ultimo ID insertado de la nd
      SET libros_diariosidND=(select LAST_INSERT_ID());
      
      -- Actualizamos el secuencial de libros diarios
      call SP_Actualiza_Secuencias_Internas('LIBRODIARIO');
  
      -- Ponemos que gravo la cabecera
      SET grabocabecera=TRUE;
  
    END IF;
  
  -- INSERTAMOS LOS DETALLES de la nd
  SET valor = round(valor,2);
  INSERT INTO libros_diarios_detalles
  ( 	
  libros_diariosid,	
  codigocontable,	
  centros_costosid,	
  referencia,	
  concepto,	
  importe
  )
  VALUES
  ( 
  libros_diariosidND,	
  codigocontable,	
  centros_costosid,	
  codigoasiento,	
  concepto,
  ROUND(valor,2)
   );
  
  -- Toma la primer cuenta del asiento contable
  IF cuenta_fija=0 THEN 
  SET cuenta_fija = (select LAST_INSERT_ID());
  END IF;

END LOOP; -- fin del loop nd

CALL SP_Contabiliza_Verificar_Asiento(libros_diariosidND,verificado);


-- Cuadramos el asiento contable si esta descuadrado
IF diferencia<0.11 AND diferencia>-0.11 AND diferencia<>0  THEN
UPDATE libros_diarios_detalles
SET
libros_diarios_detalles.importe = libros_diarios_detalles.importe-diferencia
WHERE
libros_diarios_detalles.libros_diarios_detallesid = cuenta_fija;
END IF;

-- Verificamos si el asiento esta cuadrado
IF diferencia<>0 THEN
SET verificado=0;
END IF;

-- Actualizamos el libro diario
UPDATE 
libros_diarios
SET
libros_diarios.debito = debe,
libros_diarios.credito = haber,
libros_diarios.mayorizado = verificado,
libros_diarios.verificado = verificado
WHERE
libros_diarios.libros_diariosid = libros_diariosidND;


-- Actualizamos el ID del libro diario en la nota de credito
UPDATE cuentasporcobrar SET AsientoContable=libros_diariosidNC 
WHERE 
CuentasporCobrar.CuentasporCobrarID IN (
  SELECT 
CuentasporCobrar.CuentasporCobrarID
FROM
CuentasporCobrar
WHERE
CuentasporCobrar.Concepto like 'CRUCE ANTICIPO%'
AND (CuentasporCobrar.Emision BETWEEN dFechaDesde AND dFechaHasta)
AND CuentasporCobrar.AsientoContable=0 AND CuentasporCobrar.Tipo = 'NC'
group by
cuentasporcobrar.concepto,
cuentasporcobrar.tipo,
abs(cuentasporcobrar.importe)
);

-- Actualizamos el ID del libro diario en la nota de debito
UPDATE cuentasporcobrar SET AsientoContable=libros_diariosidND
WHERE 
CuentasporCobrar.CuentasporCobrarID IN (
  SELECT 
CuentasporCobrar.CuentasporCobrarID
FROM
CuentasporCobrar
WHERE
CuentasporCobrar.Concepto like 'CRUCE ANTICIPO%'
AND (CuentasporCobrar.Emision BETWEEN dFechaDesde AND dFechaHasta)
AND CuentasporCobrar.AsientoContable=0 AND CuentasporCobrar.Tipo = 'ND'
group by
cuentasporcobrar.concepto,
cuentasporcobrar.tipo,
abs(cuentasporcobrar.importe)
);

-- Finalizamos la transaccion
COMMIT;

-- Cerramos el Cursor de la nc
CLOSE Datos_Asiento_NC;

-- Cerramos el Cursor de la nd
CLOSE Datos_Asiento_ND;

-- Devolvemos el ID del Asiento Contable de la nd y la nc
SELECT libros_diariosidNC, libros_diariosidND;

END
;;
delimiter ;

-- ----------------------------
-- Procedure structure for SP_Contabiliza_Cruce_CxC_Individual
-- ----------------------------
DROP PROCEDURE IF EXISTS `SP_Contabiliza_Cruce_CxC_Individual`;
delimiter ;;
CREATE PROCEDURE `SP_Contabiliza_Cruce_CxC_Individual`(IN sCombinacion VARCHAR(255), IN sTipo VARCHAR(255), IN sCcNCInterna VARCHAR(255), IN sCcAnticipo VARCHAR(255), IN sUsuario VARCHAR(25))
  MODIFIES SQL DATA 
BEGIN

-- Declaramos variables de Cursor
DECLARE termino INT DEFAULT FALSE;
DECLARE fechamovimiento date;
DECLARE usuariocreacion varchar(25);
DECLARE centros_costosid int(11);
DECLARE concepto varchar(200);
DECLARE referencia varchar(15);
DECLARE valor decimal(16,8) DEFAULT 0;
DECLARE codigocontable varchar(30);
DECLARE codigoasiento varchar(10);
DECLARE grabocabecera INT DEFAULT FALSE;
DECLARE libros_diariosid bigint DEFAULT 0;
DECLARE debe  decimal(16,8) DEFAULT 0;
DECLARE haber decimal(16,8) DEFAULT 0;
DECLARE diferencia decimal(12,2) DEFAULT 0;
DECLARE verificado INT DEFAULT TRUE;
DECLARE cuenta_fija bigint DEFAULT 0;

DECLARE Datos_Generales CURSOR FOR
select 
cuentasporcobrar.emision AS fechamovimiento,
  cuentasporcobrar.concepto AS concepto,
cuentasporcobrar.secuencial as referencia
from
cuentasporcobrar
where
cuentasporcobrar.origen = 'Cobros'
AND cuentasporcobrar.concepto = sCombinacion
AND cuentasporcobrar.asientocontable = 0
AND cuentasporcobrar.tipo=sTipo;

DECLARE Datos_Asiento_NC CURSOR FOR
SELECT 
    CuentasporCobrar.centros_costosid AS centros_costosid,
SUM(CuentasporCobrar.Importe) AS valor,
Clientes.CodigoContable AS codigocontable
FROM
CuentasporCobrar,
Clientes
WHERE
CuentasporCobrar.ClientesID=Clientes.ClientesID
AND cuentasporcobrar.concepto=sCombinacion
AND CuentasporCobrar.Tipo=sTipo
AND cuentasporcobrar.asientocontable=0
GROUP BY 
Clientes.CodigoContable,
cuentasporcobrar.centros_costosid 
HAVING
SUM(cuentasporcobrar.importe)<>0
UNION
SELECT 
    CuentasporCobrar.centros_costosid AS centros_costosid,
-SUM(CuentasporCobrar.Importe) AS valor,
sCcNCInterna AS codigocontable
FROM
cuentasporcobrar
Where
cuentasporcobrar.Origen='Cobros'
AND cuentasporcobrar.concepto=sCombinacion
AND cuentasporcobrar.asientocontable=0
AND CuentasporCobrar.Tipo=sTipo
GROUP BY 
cuentasporcobrar.centros_costosid
HAVING
SUM(cuentasporcobrar.importe)<>0;

DECLARE Datos_Asiento_ND CURSOR FOR
SELECT 
cuentasporcobrar.centros_costosid AS centros_costosid,
    -SUM(cuentasporcobrar.importe) AS valor,
sCcNCInterna AS codigocontable
FROM
cuentasporcobrar
WHERE
cuentasporcobrar.origen='Cobros'
AND cuentasporcobrar.concepto=sCombinacion
AND cuentasporcobrar.tipo=sTipo
AND cuentasporcobrar.asientocontable=0
GROUP BY 
cuentasporcobrar.centros_costosid
HAVING
SUM(cuentasporcobrar.importe)<>0 
UNION
SELECT 
    cuentasporcobrar.centros_costosid AS centros_costosid,
SUM(cuentasporcobrar.importe) AS valor,
sCcAnticipo AS codigocontable
FROM
cuentasporcobrar		
WHERE
cuentasporcobrar.origen='Cobros'
AND cuentasporcobrar.concepto = sCombinacion
AND cuentasporcobrar.tipo=sTipo
AND cuentasporcobrar.asientocontable=0
GROUP BY 
cuentasporcobrar.centros_costosid 
HAVING
SUM(cuentasporcobrar.importe)<>0;

-- Controlamos si hubo error
DECLARE exit handler FOR SQLEXCEPTION, SQLWARNING
  BEGIN
    ROLLBACK;
    RESIGNAL;
  END;

-- Declaramos el control de salida del loop
DECLARE CONTINUE HANDLER FOR NOT FOUND SET termino = TRUE;

-- Abrimos el Cursor
OPEN Datos_Generales;

-- Iniciamos la Transaccion
START TRANSACTION;

-- Leeemos el Cursor
read_loop: LOOP
FETCH Datos_Generales INTO fechamovimiento, concepto, referencia;

-- Verificamos si no hay mas registros
IF termino THEN
LEAVE read_loop;
END IF;

END LOOP;

set termino = FALSE;
IF sTipo = 'NC' THEN -- inicio de comparacion del tipo de transaccion

  -- CREAMOS EL ASIENTO DE LA NOTA DE CREDITO
  -- Abrimos el Cursor de la nc
  OPEN Datos_Asiento_NC;
  
  -- Leeemos el Cursor
  read_loop_nc: LOOP
  FETCH Datos_Asiento_NC INTO centros_costosid, valor, codigocontable;
  
    -- Verificamos si no hay mas registros
    IF termino THEN
    LEAVE read_loop_nc;
    END IF;
    
    SET diferencia = diferencia+(Round(valor,2));
    -- Sumamos valores de debe y haber
IF valor<0 THEN
  SET haber = (haber + (Abs((valor))));
ELSE
  SET debe  = (debe + (Abs((valor))));
END IF;
    
    -- INSERTAMOS LA CABECERA DEL ASIENTO de nc
      IF grabocabecera=FALSE THEN
        -- Optenemos el nuevo secuencial
        call SP_Consulta_Secuencias_Internas('LIBRODIARIO',codigoasiento);
      
        -- Insertamos Registro Cabecera
        INSERT INTO libros_diarios 
        (
          codigoasiento, 
          fecha, 
          referencia, 
          concepto, 
          origen, 
          usuariocreacion, 
          fechacreacion
        ) 
        VALUES 
        (
          codigoasiento,
          fechamovimiento,
          referencia, 
          concepto,
          'Ajuste CXC', 
          sUsuario, 
          NOW()
        );
       
       -- obtenemos el ultimo ID insertado
        SET libros_diariosid=(select LAST_INSERT_ID());
        
        -- Actualizamos el secuencial de libros diarios
        call SP_Actualiza_Secuencias_Internas('LIBRODIARIO');
    
        -- Ponemos que gravo la cabecera
        SET grabocabecera=TRUE;
    
      END IF;
    
    -- INSERTAMOS LOS DETALLES de la nc
    SET valor = round(valor,2);
    INSERT INTO libros_diarios_detalles
    ( 	
    libros_diariosid,	
    codigocontable,	
    centros_costosid,	
    referencia,	
    concepto,	
    importe
    )
    VALUES
    ( 
    libros_diariosid,	
    codigocontable,	
    centros_costosid,	
    referencia,	
    concepto,
    valor
     );
    
    -- Toma la primer cuenta del asiento contable de la nc
    IF cuenta_fija=0 THEN 
    SET cuenta_fija = (select LAST_INSERT_ID());
    END IF;
  
  END LOOP; -- fin del loop nc
  
ELSE

  -- CREAMOS EL ASIENTO CONTABLE DE ND
  -- Abrimos el Cursor de la nd
  OPEN Datos_Asiento_ND;
  
  -- enceramos las variables para el asiento de nd
  set termino = FALSE;
  set diferencia = 0;
  set haber = 0;
  set debe = 0;
  set grabocabecera = FALSE;
  
  -- Leeemos el Cursor
  read_loop_nd: LOOP
  FETCH Datos_Asiento_ND INTO centros_costosid, valor, codigocontable;
  
    -- Verificamos si no hay mas registros
    IF termino THEN
    LEAVE read_loop_nd;
    END IF;
    
    SET diferencia = diferencia+(Round(valor,2));
    -- Sumamos valores de debe y haber
    IF valor<0 THEN
      SET haber = haber + (Abs(Round(valor,2)));
    ELSE
      SET debe  = debe + (Abs(Round(valor,2)));
    END IF;
    
    -- INSERTAMOS LA CABECERA DEL ASIENTO de nd
      IF grabocabecera=FALSE THEN
        -- Optenemos el nuevo secuencial
        call SP_Consulta_Secuencias_Internas('LIBRODIARIO',codigoasiento);
      
        -- Insertamos Registro Cabecera de la nd
        INSERT INTO libros_diarios 
        (
          codigoasiento, 
          fecha, 
          referencia, 
          concepto, 
          origen, 
          usuariocreacion, 
          fechacreacion
        ) 
        VALUES 
        (
          codigoasiento,
          fechamovimiento,
          referencia, 
          concepto,
          'Ajuste CXC', 
          sUsuario, 
          NOW()
        );
       
       -- obtenemos el ultimo ID insertado de la nd
        SET libros_diariosid=(select LAST_INSERT_ID());
        
        -- Actualizamos el secuencial de libros diarios
        call SP_Actualiza_Secuencias_Internas('LIBRODIARIO');
    
        -- Ponemos que gravo la cabecera
        SET grabocabecera=TRUE;
    
      END IF;
    
    -- INSERTAMOS LOS DETALLES de la nd
    SET valor = round(valor,2);
    INSERT INTO libros_diarios_detalles
    ( 	
    libros_diariosid,	
    codigocontable,	
    centros_costosid,	
    referencia,	
    concepto,	
    importe
    )
    VALUES
    ( 
    libros_diariosid,	
    codigocontable,	
    centros_costosid,	
    referencia,	
    concepto,
    ROUND(valor,2)
     );
    
    -- Toma la primer cuenta del asiento contable
    IF cuenta_fija=0 THEN 
    SET cuenta_fija = (select LAST_INSERT_ID());
    END IF;
  
  END LOOP; -- fin del loop nd
END IF; -- FIN DEL IF DE COMPARACION DEL TIPO


 CALL SP_Contabiliza_Verificar_Asiento(libros_diariosid,verificado);
  
  -- Cuadramos el asiento contable si esta descuadrado
  IF diferencia<0.11 AND diferencia>-0.11 AND diferencia<>0  THEN
  UPDATE libros_diarios_detalles
  SET
  libros_diarios_detalles.importe = libros_diarios_detalles.importe-diferencia
  WHERE
  libros_diarios_detalles.libros_diarios_detallesid = cuenta_fija;
  SET diferencia=0;
END IF;

-- Verificamos si el asiento esta cuadrado
IF diferencia<>0 THEN
SET verificado=0;
END IF;

-- Actualizamos el libro diario
SET debe = Round(debe,2);
SET haber = Round(haber,2);
  UPDATE 
  libros_diarios
  SET
  libros_diarios.debito = debe,
  libros_diarios.credito = haber,
  libros_diarios.mayorizado = verificado,
  libros_diarios.verificado = verificado
  WHERE
  libros_diarios.libros_diariosid = libros_diariosid;

-- Actualizamos el ID del libro diario a el movimiento de cuentas por cobrar
UPDATE cuentasporcobrar SET AsientoContable=libros_diariosid
WHERE 
cuentasporcobrar.concepto=sCombinacion
AND cuentasporcobrar.tipo=sTipo
AND cuentasporcobrar.asientocontable=0;

-- Finalizamos la transaccion
COMMIT;

-- Cerramos el Cursor de datos generales
CLOSE Datos_Generales;

IF sTipo = 'NC' THEN
  -- Cerramos el Cursor de la nc
  CLOSE Datos_Asiento_NC;
ELSE
  -- Cerramos el Cursor de la nd
  CLOSE Datos_Asiento_ND;
END IF;

-- Devolvemos el ID del Asiento Contable
select libros_diariosid;

END
;;
delimiter ;

-- ----------------------------
-- Procedure structure for SP_Contabiliza_Cruce_CxP_Agrupado
-- ----------------------------
DROP PROCEDURE IF EXISTS `SP_Contabiliza_Cruce_CxP_Agrupado`;
delimiter ;;
CREATE PROCEDURE `SP_Contabiliza_Cruce_CxP_Agrupado`(IN sCodigoContableAnticipo VARCHAR(255), IN sCodigoContableNC VARCHAR(255), IN dFechaDesde DATE, IN dFechaHasta DATE, IN sUsuario VARCHAR(25))
  MODIFIES SQL DATA 
BEGIN

-- Declaramos variables de Cursor
DECLARE termino INT DEFAULT FALSE;
DECLARE usuariocreacion varchar(25);
DECLARE centros_costosid int(11);
DECLARE concepto varchar(200);
DECLARE valor decimal(12,2) DEFAULT 0;
DECLARE codigocontable varchar(30);
DECLARE codigoasiento varchar(15);
DECLARE grabocabecera INT DEFAULT FALSE;
DECLARE libros_diariosidNC bigint DEFAULT 0;
DECLARE libros_diariosidND bigint DEFAULT 0;
DECLARE debe  decimal(12,2) DEFAULT 0;
DECLARE haber decimal(12,2) DEFAULT 0;
DECLARE diferencia decimal(12,2) DEFAULT 0;
DECLARE verificado INT DEFAULT TRUE;
DECLARE cuenta_fija bigint DEFAULT 0;
DECLARE ListaNC varchar(255);
DECLARE ListaND varchar(255);


DECLARE Datos_Asiento_NC CURSOR FOR
SELECT 
cuentasporpagar.centros_costosid AS centros_costosid,
SUM(cuentasporpagar.importe) AS valor,
Proveedores.codigocontable AS codigocontable
FROM
cuentasporpagar,
proveedores
WHERE
cuentasporpagar.proveedoresid=proveedores.proveedoresid
AND cuentasporpagar.cuentasporpagarid IN (
SELECT 
cuentasporpagar.cuentasporpagarid
FROM
cuentasporpagar
WHERE
cuentasporpagar.concepto LIKE 'CRUCE ANTICIPO%'
AND (cuentasporpagar.emision BETWEEN dFechaDesde AND dFechaHasta)
AND cuentasporpagar.asientocontable=0 AND cuentasporpagar.tipo = 'NC'
group by
cuentasporpagar.concepto,
cuentasporpagar.tipo,
 abs(cuentasporpagar.importe)
)
AND cuentasporpagar.tipo ='NC'
GROUP BY 
proveedores.codigocontable,
centros_costosid
HAVING
SUM(cuentasporpagar.importe)<>0
UNION 
SELECT 
cuentasporpagar.centros_costosid AS centros_costosid,
-SUM(cuentasporpagar.importe) AS valor,
sCodigoContableNC AS codigocontable
FROM
cuentasporpagar
WHERE
cuentasporpagar.cuentasporpagarid IN (
SELECT 
cuentasporpagar.cuentasporpagarid
FROM
cuentasporpagar
WHERE
cuentasporpagar.concepto LIKE 'CRUCE ANTICIPO%'
AND (cuentasporpagar.emision BETWEEN dFechaDesde AND dFechaHasta)
AND cuentasporpagar.asientocontable=0 AND cuentasporpagar.tipo = 'NC'
group by
cuentasporpagar.concepto,
cuentasporpagar.tipo,
 abs(cuentasporpagar.importe)
)
AND cuentasporpagar.tipo ='NC'
GROUP BY 
cuentasporpagar.centros_costosid
HAVING
SUM(cuentasporpagar.importe)<>0;

DECLARE Datos_Asiento_ND CURSOR FOR
SELECT 
cuentasporpagar.centros_costosid AS centros_costosid,
-SUM(cuentasporpagar.importe) AS valor,
sCodigoContableNC AS codigocontable
FROM
cuentasporpagar
WHERE
cuentasporpagar.cuentasporpagarid IN (
SELECT 
cuentasporpagar.cuentasporpagarid
FROM
cuentasporpagar
WHERE
cuentasporpagar.concepto LIKE 'CRUCE ANTICIPO%'
AND (cuentasporpagar.emision BETWEEN dFechaDesde AND dFechaHasta)
AND cuentasporpagar.asientocontable=0 AND cuentasporpagar.tipo = 'ND'
group by
cuentasporpagar.concepto,
cuentasporpagar.tipo,
  abs(cuentasporpagar.importe)
)
AND cuentasporpagar.tipo  = 'ND'
GROUP BY 
centros_costosid
HAVING
SUM(cuentasporpagar.importe)<>0
UNION
SELECT 
cuentasporpagar.centros_costosid AS centros_costosid,
SUM(cuentasporpagar.importe) AS valor,
sCodigoContableAnticipo AS codigocontable
FROM
cuentasporpagar
WHERE
cuentasporpagar.cuentasporpagarid IN (
SELECT 
cuentasporpagar.cuentasporpagarid
FROM
cuentasporpagar
WHERE
cuentasporpagar.concepto LIKE 'CRUCE ANTICIPO%'
AND (cuentasporpagar.emision BETWEEN dFechaDesde AND dFechaHasta)
AND cuentasporpagar.asientocontable=0 AND cuentasporpagar.tipo = 'ND'
group by
cuentasporpagar.concepto,
cuentasporpagar.tipo,
 abs(cuentasporpagar.importe)
)
AND cuentasporpagar.tipo  = 'ND'
GROUP BY 
centros_costosid
HAVING
SUM(cuentasporpagar.importe)<>0;


-- Controlamos si hubo error
DECLARE exit handler FOR SQLEXCEPTION, SQLWARNING
  BEGIN
  	SHOW WARNINGS limit 1;
    ROLLBACK;
    RESIGNAL;
  END;

-- Declaramos el control de salida del loop
DECLARE CONTINUE HANDLER FOR NOT FOUND SET termino = TRUE;

-- Iniciamos la Transaccion
START TRANSACTION;

  set ListaNC = '';
  set ListaND = '';

-- enceramos las variables para el asiento de nc
set termino = FALSE;

-- CREAMOS EL ASIENTO DE LA NOTA DE CREDITO
-- Abrimos el Cursor de la nc
OPEN Datos_Asiento_NC;

-- Leeemos el Cursor
read_loop_nc: LOOP
FETCH Datos_Asiento_NC INTO centros_costosid, valor, codigocontable;

  -- Verificamos si no hay mas registros
  IF termino THEN
  LEAVE read_loop_nc;
  END IF;
  
  SET diferencia = diferencia+(Round(valor,2));
  -- Sumamos valores de debe y haber
IF valor<0 THEN
  SET haber = (haber + (Abs((valor))));
ELSE
  SET debe  = (debe + (Abs((valor))));
END IF;
  
  -- INSERTAMOS LA CABECERA DEL ASIENTO de nc
    IF grabocabecera=FALSE THEN
      set concepto = CONCAT('Ajuste CxP Nota de Crédito de ',DATE_FORMAT(dFechaDesde,"%d-%m-%Y"),' a ',DATE_FORMAT(dFechaHasta,"%d-%m-%Y"));
      -- Optenemos el nuevo secuencial
      call SP_Consulta_Secuencias_Internas('LIBRODIARIO',codigoasiento);
    
      -- Insertamos Registro Cabecera
      INSERT INTO libros_diarios 
      (
        codigoasiento, 
        fecha, 
        referencia, 
        concepto, 
        origen, 
        usuariocreacion, 
        fechacreacion
      ) 
      VALUES 
      (
        codigoasiento,
        dFechaHasta,
        codigoasiento, 
        concepto,
        'Ajuste CXP', 
        sUsuario, 
        NOW()
      );
     
     -- obtenemos el ultimo ID insertado
      SET libros_diariosidNC=(select LAST_INSERT_ID());
      
      -- Actualizamos el secuencial de libros diarios
      call SP_Actualiza_Secuencias_Internas('LIBRODIARIO');
  
      -- Ponemos que gravo la cabecera
      SET grabocabecera=TRUE;
  
    END IF;
  
  -- INSERTAMOS LOS DETALLES de la nc
  INSERT INTO libros_diarios_detalles
  ( 	
  libros_diariosid,	
  codigocontable,	
  centros_costosid,	
  referencia,	
  concepto,	
  importe
  )
  VALUES
  ( 
  libros_diariosidNC,	
  codigocontable,	
  centros_costosid,	
  codigoasiento,	
  concepto,
  valor
   );
  
  -- Toma la primer cuenta del asiento contable de la nc
  IF cuenta_fija=0 THEN 
  SET cuenta_fija = (select LAST_INSERT_ID());
  END IF;

END LOOP; -- fin del loop nc

-- iniciamos la verificacion del asiento de NC
CALL SP_Contabiliza_Verificar_Asiento(libros_diariosidNC,verificado);

-- Cuadramos el asiento contable si esta descuadrado
IF diferencia<0.11 AND diferencia>-0.11 AND diferencia<>0  THEN
UPDATE libros_diarios_detalles
SET
libros_diarios_detalles.importe = libros_diarios_detalles.importe-diferencia
WHERE
libros_diarios_detalles.libros_diarios_detallesid = cuenta_fija;
SET diferencia=0;
END IF;

-- Verificamos si el asiento esta cuadrado
IF diferencia<>0 THEN
SET verificado=0;
END IF;

-- Actualizamos el libro diario
SET debe = Round(debe,2);
SET haber = Round(haber,2);
UPDATE 
libros_diarios
SET
libros_diarios.debito = debe,
libros_diarios.credito = haber,
libros_diarios.mayorizado = verificado,
libros_diarios.verificado = verificado
WHERE
libros_diarios.libros_diariosid = libros_diariosidNC;


-- CREAMOS EL ASIENTO CONTABLE DE ND
-- Abrimos el Cursor de la nd
OPEN Datos_Asiento_ND;

-- enceramos las variables para el asiento de nd
set termino = FALSE;
set diferencia = 0;
set haber = 0;
set debe = 0;
set grabocabecera = FALSE;

-- Leeemos el Cursor
read_loop_nd: LOOP
FETCH Datos_Asiento_ND INTO centros_costosid, valor, codigocontable;

  -- Verificamos si no hay mas registros
  IF termino THEN
  LEAVE read_loop_nd;
  END IF;
  
  SET diferencia = diferencia+(Round(valor,2));
  -- Sumamos valores de debe y haber
  IF valor<0 THEN
    SET haber = haber + (Abs(Round(valor,2)));
  ELSE
    SET debe  = debe + (Abs(Round(valor,2)));
  END IF;
  
  -- INSERTAMOS LA CABECERA DEL ASIENTO de nd
    IF grabocabecera=FALSE THEN
    set concepto = CONCAT('Ajuste CxP Nota de Débito de ',DATE_FORMAT(dFechaDesde,"%d-%m-%Y"),' a ',DATE_FORMAT(dFechaHasta,"%d-%m-%Y"));
      -- Optenemos el nuevo secuencial
      call SP_Consulta_Secuencias_Internas('LIBRODIARIO',codigoasiento);
    
      -- Insertamos Registro Cabecera de la nd
      INSERT INTO libros_diarios 
      (
        codigoasiento, 
        fecha, 
        referencia, 
        concepto, 
        origen, 
        usuariocreacion, 
        fechacreacion
      ) 
      VALUES 
      (
        codigoasiento,
        dFechaDesde,
        codigoasiento, 
        concepto,
        'Ajuste CXP', 
        sUsuario, 
        NOW()
      );
     
     -- obtenemos el ultimo ID insertado de la nd
      SET libros_diariosidND=(select LAST_INSERT_ID());
      
      -- Actualizamos el secuencial de libros diarios
      call SP_Actualiza_Secuencias_Internas('LIBRODIARIO');
  
      -- Ponemos que gravo la cabecera
      SET grabocabecera=TRUE;
  
    END IF;
  
  -- INSERTAMOS LOS DETALLES de la nd
  INSERT INTO libros_diarios_detalles
  ( 	
  libros_diariosid,	
  codigocontable,	
  centros_costosid,	
  referencia,	
  concepto,	
  importe
  )
  VALUES
  ( 
  libros_diariosidND,	
  codigocontable,	
  centros_costosid,	
  codigoasiento,	
  concepto,
  ROUND(valor,2)
   );
  
  -- Toma la primer cuenta del asiento contable
  IF cuenta_fija=0 THEN 
  SET cuenta_fija = (select LAST_INSERT_ID());
  END IF;

END LOOP; -- fin del loop nd

CALL SP_Contabiliza_Verificar_Asiento(libros_diariosidND,verificado);


-- Cuadramos el asiento contable si esta descuadrado
IF diferencia<0.11 AND diferencia>-0.11 AND diferencia<>0  THEN
UPDATE libros_diarios_detalles
SET
libros_diarios_detalles.importe = libros_diarios_detalles.importe-diferencia
WHERE
libros_diarios_detalles.libros_diarios_detallesid = cuenta_fija;
END IF;

-- Verificamos si el asiento esta cuadrado
IF diferencia<>0 THEN
SET verificado=0;
END IF;

-- Actualizamos el libro diario
UPDATE 
libros_diarios
SET
libros_diarios.debito = debe,
libros_diarios.credito = haber,
libros_diarios.mayorizado = verificado,
libros_diarios.verificado = verificado
WHERE
libros_diarios.libros_diariosid = libros_diariosidND;


-- Actualizamos el ID del libro diario en la nota de credito
UPDATE cuentasporpagar SET asientocontable=libros_diariosidNC
WHERE 
cuentasporpagar.cuentasporpagarid IN (
SELECT 
cuentasporpagar.cuentasporpagarid
FROM
cuentasporpagar
WHERE
cuentasporpagar.concepto LIKE 'CRUCE ANTICIPO%'
AND (cuentasporpagar.emision BETWEEN dFechaDesde AND dFechaHasta)
AND cuentasporpagar.asientocontable=0 AND cuentasporpagar.tipo = 'NC'
group by
cuentasporpagar.concepto,
cuentasporpagar.tipo,
 abs(cuentasporpagar.importe)
)
AND cuentasporpagar.asientocontable=0;

-- Actualizamos el ID del libro diario en la nota de debito
UPDATE cuentasporpagar SET asientocontable=libros_diariosidND
WHERE 
cuentasporpagar.cuentasporpagarid IN (
SELECT 
cuentasporpagar.cuentasporpagarid
FROM
cuentasporpagar
WHERE
cuentasporpagar.concepto LIKE 'CRUCE ANTICIPO%'
AND (cuentasporpagar.emision BETWEEN dFechaDesde AND dFechaHasta)
AND cuentasporpagar.asientocontable=0 AND cuentasporpagar.tipo = 'ND'
group by
cuentasporpagar.concepto,
cuentasporpagar.tipo,
 abs(cuentasporpagar.importe)
)
AND cuentasporpagar.asientocontable=0;

-- Finalizamos la transaccion
COMMIT;

-- Cerramos el Cursor de la nc
CLOSE Datos_Asiento_NC;

-- Cerramos el Cursor de la nd
CLOSE Datos_Asiento_ND;


-- Devolvemos el ID del Asiento Contable de la nd y la nc
SELECT libros_diariosidNC, libros_diariosidND;

END
;;
delimiter ;

-- ----------------------------
-- Procedure structure for SP_Contabiliza_Cruce_CxP_Individual
-- ----------------------------
DROP PROCEDURE IF EXISTS `SP_Contabiliza_Cruce_CxP_Individual`;
delimiter ;;
CREATE PROCEDURE `SP_Contabiliza_Cruce_CxP_Individual`(IN sCombinacion VARCHAR(255), IN sTipo VARCHAR(255), IN sCcNCInterna VARCHAR(255), IN sCcAnticipo VARCHAR(255), IN sUsuario VARCHAR(25))
  MODIFIES SQL DATA 
BEGIN

-- Declaramos variables de Cursor
DECLARE termino INT DEFAULT FALSE;
DECLARE fechamovimiento date;
DECLARE usuariocreacion varchar(25);
DECLARE centros_costosid int(11);
DECLARE concepto varchar(200);
DECLARE referencia varchar(15);
DECLARE valor decimal(12,2) DEFAULT 0;
DECLARE codigocontable varchar(30);
DECLARE codigoasiento varchar(10);
DECLARE grabocabecera INT DEFAULT FALSE;
DECLARE libros_diariosid bigint DEFAULT 0;
DECLARE debe  decimal(16,8) DEFAULT 0;
DECLARE haber decimal(16,8) DEFAULT 0;
DECLARE diferencia decimal(12,2) DEFAULT 0;
DECLARE verificado INT DEFAULT TRUE;
DECLARE cuenta_fija bigint DEFAULT 0;

DECLARE Datos_Generales CURSOR FOR
SELECT 
cuentasporpagar.emision AS fechamovimiento,
cuentasporpagar.concepto,
  cuentasporpagar.secuencia AS referencia
FROM
cuentasporpagar
WHERE
cuentasporpagar.origen='Pagos'
AND cuentasporpagar.concepto = sCombinacion
AND cuentasporpagar.asientocontable=0
AND cuentasporpagar.tipo=sTipo;


DECLARE Datos_Asiento_NC CURSOR FOR
SELECT 
    cuentasporpagar.centros_costosid AS centros_costosid,
SUM(cuentasporpagar.importe) AS valor,
proveedores.codigocontable AS codigocontable
FROM
cuentasporpagar,
proveedores
WHERE
cuentasporpagar.proveedoresid=proveedores.proveedoresid
AND cuentasporpagar.origen='Pagos'
AND cuentasporpagar.concepto = sCombinacion
AND cuentasporpagar.tipo=sTipo
AND cuentasporpagar.asientocontable=0
GROUP BY 
proveedores.codigocontable,
cuentasporpagar.centros_costosid 
HAVING
SUM(cuentasporpagar.importe)<>0
UNION
SELECT 
cuentasporpagar.centros_costosid AS centros_costosid,
-SUM(cuentasporpagar.importe) AS valor,
sCcNCInterna AS codigocontable
FROM
cuentasporpagar
WHERE
cuentasporpagar.origen='Pagos'
AND cuentasporpagar.concepto = sCombinacion
AND cuentasporpagar.asientocontable=0
AND cuentasporpagar.tipo=sTipo
GROUP BY 
cuentasporpagar.centros_costosid
HAVING
SUM(cuentasporpagar.importe)<>0;

DECLARE Datos_Asiento_ND CURSOR FOR
SELECT 
cuentasporpagar.centros_costosid AS centros_costosid,
-SUM(cuentasporpagar.importe) AS valor,
sCcNCInterna AS CuentaContable
FROM
cuentasporpagar		
WHERE
cuentasporpagar.origen='Pagos'
AND cuentasporpagar.concepto = sCombinacion
AND cuentasporpagar.asientocontable=0
AND cuentasporpagar.tipo=sTipo
GROUP BY 
cuentasporpagar.centros_costosid 
HAVING
SUM(cuentasporpagar.importe)<>0
UNION
SELECT 
cuentasporpagar.centros_costosid AS centros_costosid,
SUM(cuentasporpagar.importe) AS valor,
sCcAnticipo AS CuentaContable
FROM
cuentasporpagar
WHERE
cuentasporpagar.origen='Pagos'
AND cuentasporpagar.concepto = sCombinacion
AND cuentasporpagar.tipo=sTipo
AND cuentasporpagar.asientocontable=0
GROUP BY 
cuentasporpagar.centros_costosid
HAVING
SUM(cuentasporpagar.importe)<>0;

-- Controlamos si hubo error
DECLARE exit handler FOR SQLEXCEPTION, SQLWARNING
  BEGIN
    ROLLBACK;
    RESIGNAL;
  END;

-- Declaramos el control de salida del loop
DECLARE CONTINUE HANDLER FOR NOT FOUND SET termino = TRUE;

-- Abrimos el Cursor
OPEN Datos_Generales;

-- Iniciamos la Transaccion
START TRANSACTION;

-- Leeemos el Cursor
read_loop: LOOP
FETCH Datos_Generales INTO fechamovimiento, concepto, referencia;

-- Verificamos si no hay mas registros
IF termino THEN
LEAVE read_loop;
END IF;

END LOOP;

set termino = FALSE;
IF sTipo = 'NC' THEN -- inicio de comparacion del tipo de transaccion

  -- CREAMOS EL ASIENTO DE LA NOTA DE CREDITO
  -- Abrimos el Cursor de la nc
  OPEN Datos_Asiento_NC;
  
  -- Leeemos el Cursor
  read_loop_nc: LOOP
  FETCH Datos_Asiento_NC INTO centros_costosid, valor, codigocontable;
  
    -- Verificamos si no hay mas registros
    IF termino THEN
    LEAVE read_loop_nc;
    END IF;
    
    SET diferencia = diferencia+(Round(valor,2));
    -- Sumamos valores de debe y haber
IF valor<0 THEN
  SET haber = (haber + (Abs((valor))));
ELSE
  SET debe  = (debe + (Abs((valor))));
END IF;
    
    -- INSERTAMOS LA CABECERA DEL ASIENTO de nc
      IF grabocabecera=FALSE THEN
        -- Optenemos el nuevo secuencial
        call SP_Consulta_Secuencias_Internas('LIBRODIARIO',codigoasiento);
      
        -- Insertamos Registro Cabecera
        INSERT INTO libros_diarios 
        (
          codigoasiento, 
          fecha, 
          referencia, 
          concepto, 
          origen, 
          usuariocreacion, 
          fechacreacion
        ) 
        VALUES 
        (
          codigoasiento,
          fechamovimiento,
          referencia, 
          concepto,
          'Ajuste CXP', 
          sUsuario, 
          NOW()
        );
       
       -- obtenemos el ultimo ID insertado
        SET libros_diariosid=(select LAST_INSERT_ID());
        
        -- Actualizamos el secuencial de libros diarios
        call SP_Actualiza_Secuencias_Internas('LIBRODIARIO');
    
        -- Ponemos que gravo la cabecera
        SET grabocabecera=TRUE;
    
      END IF;
    
    -- INSERTAMOS LOS DETALLES de la nc
    INSERT INTO libros_diarios_detalles
    ( 	
    libros_diariosid,	
    codigocontable,	
    centros_costosid,	
    referencia,	
    concepto,	
    importe
    )
    VALUES
    ( 
    libros_diariosid,	
    codigocontable,	
    centros_costosid,	
    referencia,	
    concepto,
    valor
     );
    
    -- Toma la primer cuenta del asiento contable de la nc
    IF cuenta_fija=0 THEN 
    SET cuenta_fija = (select LAST_INSERT_ID());
    END IF;
  
  END LOOP; -- fin del loop nc
  
ELSE

  -- CREAMOS EL ASIENTO CONTABLE DE ND
  -- Abrimos el Cursor de la nd
  OPEN Datos_Asiento_ND;
  
  -- enceramos las variables para el asiento de nd
  set termino = FALSE;
  set diferencia = 0;
  set haber = 0;
  set debe = 0;
  set grabocabecera = FALSE;
  
  -- Leeemos el Cursor
  read_loop_nd: LOOP
  FETCH Datos_Asiento_ND INTO centros_costosid, valor, codigocontable;
  
    -- Verificamos si no hay mas registros
    IF termino THEN
    LEAVE read_loop_nd;
    END IF;
    
    SET diferencia = diferencia+(Round(valor,2));
    -- Sumamos valores de debe y haber
    IF valor<0 THEN
      SET haber = haber + (Abs(Round(valor,2)));
    ELSE
      SET debe  = debe + (Abs(Round(valor,2)));
    END IF;
    
    -- INSERTAMOS LA CABECERA DEL ASIENTO de nd
      IF grabocabecera=FALSE THEN
        -- Optenemos el nuevo secuencial
        call SP_Consulta_Secuencias_Internas('LIBRODIARIO',codigoasiento);
      
        -- Insertamos Registro Cabecera de la nd
        INSERT INTO libros_diarios 
        (
          codigoasiento, 
          fecha, 
          referencia, 
          concepto, 
          origen, 
          usuariocreacion, 
          fechacreacion
        ) 
        VALUES 
        (
          codigoasiento,
          fechamovimiento,
          referencia, 
          concepto,
          'Ajuste CXP', 
          sUsuario, 
          NOW()
        );
       
       -- obtenemos el ultimo ID insertado de la nd
        SET libros_diariosid=(select LAST_INSERT_ID());
        
        -- Actualizamos el secuencial de libros diarios
        call SP_Actualiza_Secuencias_Internas('LIBRODIARIO');
    
        -- Ponemos que gravo la cabecera
        SET grabocabecera=TRUE;
    
      END IF;
    
    -- INSERTAMOS LOS DETALLES de la nd
    INSERT INTO libros_diarios_detalles
    ( 	
    libros_diariosid,	
    codigocontable,	
    centros_costosid,	
    referencia,	
    concepto,	
    importe
    )
    VALUES
    ( 
    libros_diariosid,	
    codigocontable,	
    centros_costosid,	
    referencia,	
    concepto,
    ROUND(valor,2)
     );
    
    -- Toma la primer cuenta del asiento contable
    IF cuenta_fija=0 THEN 
    SET cuenta_fija = (select LAST_INSERT_ID());
    END IF;
  
  END LOOP; -- fin del loop nd
END IF; -- FIN DEL IF DE COMPARACION DEL TIPO


 CALL SP_Contabiliza_Verificar_Asiento(libros_diariosid,verificado);
  
  -- Cuadramos el asiento contable si esta descuadrado
  IF diferencia<0.11 AND diferencia>-0.11 AND diferencia<>0  THEN
  UPDATE libros_diarios_detalles
  SET
  libros_diarios_detalles.importe = libros_diarios_detalles.importe-diferencia
  WHERE
  libros_diarios_detalles.libros_diarios_detallesid = cuenta_fija;
  SET diferencia=0;
END IF;

-- Verificamos si el asiento esta cuadrado
IF diferencia<>0 THEN
SET verificado=0;
END IF;

-- Actualizamos el libro diario
SET debe = Round(debe,2);
SET haber = Round(haber,2);
  UPDATE 
  libros_diarios
  SET
  libros_diarios.debito = debe,
  libros_diarios.credito = haber,
  libros_diarios.mayorizado = verificado,
  libros_diarios.verificado = verificado
  WHERE
  libros_diarios.libros_diariosid = libros_diariosid;

-- Actualizamos el ID del libro diario a el movimiento de cuentas por cobrar
UPDATE cuentasporpagar SET cuentasporpagar.asientocontable=libros_diariosid
WHERE 
cuentasporpagar.concepto = sCombinacion
AND cuentasporpagar.tipo=sTipo
AND cuentasporpagar.asientocontable=0;

-- Finalizamos la transaccion
COMMIT;

-- Cerramos el Cursor de datos generales
CLOSE Datos_Generales;

IF sTipo = 'NC' THEN
  -- Cerramos el Cursor de la nc
  CLOSE Datos_Asiento_NC;
ELSE
  -- Cerramos el Cursor de la nd
  CLOSE Datos_Asiento_ND;
END IF;

-- Devolvemos el ID del Asiento Contable
select libros_diariosid;

END
;;
delimiter ;

-- ----------------------------
-- Procedure structure for SP_Contabiliza_Deposito_Agrupado
-- ----------------------------
DROP PROCEDURE IF EXISTS `SP_Contabiliza_Deposito_Agrupado`;
delimiter ;;
CREATE PROCEDURE `SP_Contabiliza_Deposito_Agrupado`(IN dFechaDesde DATE, IN dFechaHasta DATE, IN sCuentaContableComision VARCHAR(255) ,IN sUsuario VARCHAR(25))
  MODIFIES SQL DATA 
  SQL SECURITY INVOKER
BEGIN

-- Declaramos variables de Cursor
DECLARE termino INT DEFAULT FALSE;
-- DECLARE fechamovimiento date;
DECLARE usuariocreacion varchar(25);
DECLARE centros_costosid int(11);
DECLARE concepto varchar(200);
DECLARE referencia varchar(15);
DECLARE valor decimal(16,8) DEFAULT 0;
DECLARE codigocontable varchar(30);
DECLARE codigoasiento varchar(10);
DECLARE gravocabecera INT DEFAULT FALSE;
DECLARE libros_diariosid bigint DEFAULT 0;
DECLARE debe  decimal(16,8) DEFAULT 0;
DECLARE haber decimal(16,8) DEFAULT 0;
DECLARE diferencia decimal(12,2) DEFAULT 0;
DECLARE verificado INT DEFAULT TRUE;
DECLARE cuenta_fija bigint DEFAULT 0;

DECLARE Datos_Asiento CURSOR FOR
SELECT
depositos.centros_costosid AS centros_costosid,
LEFT ( depositos.Concepto, 200 ) AS concepto,
RIGHT ( depositos.numerodocumento, 10 ) AS referencia,
- SUM( depositos.total + depositos.comisionestarjetas ) AS valor,
cajas.CodigoContable AS codigocontable 
FROM
depositos
JOIN cajas ON cajas.cajasid = depositos.cajasid 
WHERE
depositos.asientocontable = 0 
AND depositos.cajasid <> 0 
AND ( depositos.Fecha BETWEEN dFechaDesde AND dFechaHasta ) 
AND (
EXISTS ( SELECT depositosid FROM movcaja WHERE movcaja.depositosid = depositos.depositosid AND movcaja.tarjetas_retencionesid > 0 LIMIT 1 ) 
OR depositos.total_efectivo > 0 
OR depositos.total_cheque > 0 
) 
GROUP BY
depositos.centros_costosid,
cajas.CodigoContable

HAVING
SUM( depositos.total )<> 0 

UNION ALL

select 
depositos.centros_costosid AS centros_costosid,
Left(depositos.concepto,200) AS concepto,
  	RIGHT(depositos.numerodocumento,10) AS referencia,
SUM(depositos.total) AS valor,
  bancos.CodigoContable as codigocontable
FROM
depositos,
bancos
WHERE
depositos.BancosID=bancos.BancosID
AND depositos.AsientoContable=0
AND depositos.Fecha BETWEEN dFechaDesde AND dFechaHasta
GROUP BY
depositos.centros_costosid,
bancos.CodigoContable
HAVING
SUM(depositos.total)<>0

UNION ALL

SELECT
depositos.centros_costosid AS centros_costosid,
LEFT ( depositos.Concepto, 200 ) AS concepto,
RIGHT ( depositos.numerodocumento, 10 ) AS referencia,
-SUM( movcaja.importe-movcaja.voucheriva-movcaja.voucherrenta ) AS valor,
cajas.CodigoContable AS codigocontable 
FROM
depositos
INNER JOIN movcaja ON depositos.depositosid = movcaja.depositosid
INNER JOIN cajas ON movcaja.cajasid = cajas.cajasid 
WHERE
depositos.asientocontable = 0 
AND ( depositos.Fecha BETWEEN dFechaDesde AND dFechaHasta ) 
AND movcaja.tipo IN ('AB','IN') 
AND movcaja.origen IN ("Facturacion", "Cobros","Caja") 
AND depositos.cajasid=0
AND depositos.total_cheque = 0 
AND depositos.total_efectivo = 0 
GROUP BY
depositos.centros_costosid,
cajas.CodigoContable
HAVING
SUM( movcaja.importe )<> 0 

UNION ALL
SELECT
movcaja.centros_costosid AS centros_costosid,
CONCAT( 'Retencion Voucher ', depositos.concepto ) AS concepto,
depositos.numerodocumento AS referencia,
SUM( movcaja.vouchercomicion ) AS valor,
sCuentaContableComision AS codigocontable 
FROM
depositos
INNER JOIN movcaja ON depositos.depositosid = movcaja.depositosid
WHERE 
depositos.Fecha BETWEEN dFechaDesde 
AND dFechaHasta 
AND depositos.asientocontable = 0 
AND movcaja.tipo IN ("AB","IN") 
AND movcaja.origen IN ("Facturacion", "Cobros","Caja") 
AND depositos.comisionestarjetas <>0
GROUP BY
movcaja.centros_costosid 
HAVING
SUM( movcaja.vouchercomicion )<> 0;



-- Controlamos si hubo error
DECLARE exit handler FOR SQLEXCEPTION, SQLWARNING
  BEGIN
  	SHOW WARNINGS limit 1;
    ROLLBACK;
    RESIGNAL;
  END;

-- Declaramos el control de salida del loop
DECLARE CONTINUE HANDLER FOR NOT FOUND SET termino = TRUE;

-- Abrimos el Cursor
OPEN Datos_Asiento;

-- Iniciamos la Transaccion
START TRANSACTION;

-- Leeemos el Cursor
read_loop: LOOP
FETCH Datos_Asiento INTO centros_costosid, concepto, referencia, valor, codigocontable;

-- Verificamos si no hay mas registros
IF termino THEN
LEAVE read_loop;
END IF;

SET diferencia = diferencia+(Round(valor,2));
-- Sumamos valores de debe y haber
IF valor<0 THEN
  SET haber = (haber + (Abs((valor))));
ELSE
  SET debe  = (debe + (Abs((valor))));
END IF;

-- INSERTAMOS LA CABECERA DEL ASIENTO
  IF gravocabecera=FALSE THEN
    -- Optenemos el nuevo secuencial
    call SP_Consulta_Secuencias_Internas('LIBRODIARIO',codigoasiento);
  
    -- Insertamos Registro Cabecera
    INSERT INTO libros_diarios 
    (
      codigoasiento, 
      fecha, 
      referencia, 
      concepto, 
      origen, 
      usuariocreacion, 
      fechacreacion
    ) 
    VALUES 
    (
      codigoasiento,
      dFechaHasta,
      codigoasiento, 
      CONCAT('Depósitos de ',DATE_FORMAT(dFechaDesde,"%d-%m-%Y"),' a ',DATE_FORMAT(dFechaHasta,"%d-%m-%Y")),
      'Depòsitos', 
      sUsuario, 
      NOW()
    );
   
   -- obtenemos el ultimo ID insertado
    SET libros_diariosid=(select LAST_INSERT_ID());
    
    -- Actualizamos el secuencial de libros diarios
    call SP_Actualiza_Secuencias_Internas('LIBRODIARIO');

    -- Ponemos que gravo la cabecera
    SET gravocabecera=TRUE;

  END IF;

-- INSERTAMOS LOS DETALLES
SET valor = round(valor,2);
INSERT INTO libros_diarios_detalles
( 	
libros_diariosid,	
codigocontable,	
centros_costosid,	
referencia,	
concepto,	
importe
)
VALUES
( 
libros_diariosid,	
codigocontable,	
centros_costosid,	
referencia,	
concepto,	
valor
 );

-- Toma la primer cuenta del asiento contable
IF cuenta_fija=0 THEN 
SET cuenta_fija = (select LAST_INSERT_ID());
END IF;

END LOOP;

CALL SP_Contabiliza_Verificar_Asiento(libros_diariosid,verificado);


-- Cuadramos el asiento contable si esta descuadrado
IF diferencia<0.11 AND diferencia>-0.11 AND diferencia<>0  THEN
UPDATE libros_diarios_detalles
SET
libros_diarios_detalles.importe = libros_diarios_detalles.importe-diferencia
WHERE
libros_diarios_detalles.libros_diarios_detallesid = cuenta_fija;
SET diferencia=0;
END IF;

-- Verificamos si el asiento esta cuadrado
IF diferencia<>0 THEN
SET verificado=0;
END IF;

-- Actualizamos el libro diario
SET debe = Round(debe,2);
SET haber = Round(haber,2);
UPDATE 
libros_diarios
SET
libros_diarios.debito = debe,
libros_diarios.credito = haber,
libros_diarios.mayorizado = verificado,
libros_diarios.verificado = verificado
WHERE
libros_diarios.libros_diariosid = libros_diariosid;


-- Actualizamos el ID del libro diario a el movimiento de Caja
UPDATE
movbanco 
SET
movbanco.asientocontable=libros_diariosid
WHERE
movbanco.asientocontable = 0
AND movbanco.fechamovimiento BETWEEN dFechaDesde AND dFechaHasta
AND movbanco.origen = 'Depositos';
UPDATE
movcaja 
SET
movcaja.asientocontable=libros_diariosid
WHERE
movcaja.asientocontable = 0
AND movcaja.tipo = 'DP'
AND movcaja.fechamovimiento BETWEEN dFechaDesde AND dFechaHasta
AND movcaja.origen = 'Depositos';
UPDATE
depositos 
SET
depositos.asientocontable=libros_diariosid
WHERE
depositos.asientocontable = 0
AND depositos.fecha BETWEEN dFechaDesde AND dFechaHasta;

-- Finalizamos la transaccion
COMMIT;

-- Cerramos el Cursor
CLOSE Datos_Asiento;

-- Devolvemos el ID del Asiento Contable
select libros_diariosid;

END
