-- ----------------------------
-- Procedure structure for SP_Contabiliza_Deposito_Retenciones_Individual
-- ----------------------------
DROP PROCEDURE IF EXISTS `SP_Contabiliza_Deposito_Retenciones_Individual`;
delimiter ;;
CREATE PROCEDURE `SP_Contabiliza_Deposito_Retenciones_Individual`(IN nDocumentoid BIGINT, IN sCuentaContable VARCHAR(255), IN sUsuario VARCHAR(25))
  MODIFIES SQL DATA 
BEGIN

-- Declaramos variables de Cursor
DECLARE termino INT DEFAULT FALSE;
DECLARE fechamovimiento date;
DECLARE usuariocreacion varchar(25);
DECLARE centros_costosid int(11);
DECLARE concepto varchar(200);
DECLARE referencia varchar(15);
DECLARE valor decimal(16,8) DEFAULT 0;
DECLARE codigocontable varchar(30);
DECLARE codigoasiento varchar(15);
DECLARE gravocabecera INT DEFAULT FALSE;
DECLARE libros_diariosid bigint DEFAULT 0;
DECLARE debe  decimal(16,8) DEFAULT 0;
DECLARE haber decimal(16,8) DEFAULT 0;
DECLARE diferencia decimal(12,2)  DEFAULT 0;
DECLARE verificado INT DEFAULT TRUE;
DECLARE cuenta_fija bigint DEFAULT 0;

DECLARE Datos_Asiento CURSOR FOR

SELECT 
tarjetas_retenciones.emision AS fechamovimiento,
movcaja.centros_costosid AS centros_costosid,
CONCAT('Retencion Voucher ',clientes.razonsocial) AS concepto,
tarjetas_retenciones.secuencia AS referencia,
SUM(movcaja.voucherrenta) AS valor,
facturas_retenciones.codigocontable AS codigocontable
FROM
tarjetas_retenciones
INNER JOIN
facturas_retenciones
ON
tarjetas_retenciones.tarjetas_retencionesid = facturas_retenciones.documentosid 
AND facturas_retenciones.origen = 'Voucher'
INNER JOIN movcaja 
ON movcaja.tarjetas_retencionesid = tarjetas_retenciones.tarjetas_retencionesid
INNER JOIN
clientes
ON facturas_retenciones.clientesid = clientes.clientesid
WHERE
tarjetas_retenciones.asientocontable=0
AND tarjetas_retenciones.tarjetas_retencionesid = nDocumentoid
and facturas_retenciones.tipo = 'IR'
GROUP BY
movcaja.centros_costosid,
facturas_retenciones.codigocontable
HAVING
SUM(facturas_retenciones.valor)<>0

UNION ALL

SELECT 
tarjetas_retenciones.emision AS fechamovimiento,
movcaja.centros_costosid AS centros_costosid,
CONCAT('Retencion Voucher ',clientes.razonsocial) AS concepto,
tarjetas_retenciones.secuencia AS referencia,
SUM(movcaja.voucheriva) AS valor,
facturas_retenciones.codigocontable AS codigocontable
FROM
tarjetas_retenciones
INNER JOIN
facturas_retenciones
ON
tarjetas_retenciones.tarjetas_retencionesid = facturas_retenciones.documentosid 
AND facturas_retenciones.origen = 'Voucher'
INNER JOIN movcaja 
ON movcaja.tarjetas_retencionesid = tarjetas_retenciones.tarjetas_retencionesid
INNER JOIN
clientes
ON facturas_retenciones.clientesid = clientes.clientesid
WHERE
tarjetas_retenciones.asientocontable=0
AND tarjetas_retenciones.tarjetas_retencionesid = nDocumentoid
and facturas_retenciones.tipo = 'IVA'
GROUP BY
movcaja.centros_costosid,
facturas_retenciones.codigocontable
HAVING
SUM(facturas_retenciones.valor)<>0

UNION ALL

SELECT 
tarjetas_retenciones.emision AS fechamovimiento,
movcaja.centros_costosid AS centros_costosid,
CONCAT('Retencion Voucher ',clientes.razonsocial) AS concepto,
tarjetas_retenciones.secuencia AS referencia,
(CASE WHEN (depositos.comisionestarjetas = 0 OR (depositos.depositosid IS NULL AND movcaja.depositosid = 0 and movcaja.tarjetas_retencionesid >0)) THEN
-SUM(movcaja.voucheriva+movcaja.voucherrenta+movcaja.vouchercomicion)
ELSE
-SUM(movcaja.voucheriva+movcaja.voucherrenta)
END ) AS valor,
cajas.codigocontable AS codigocontable
FROM
tarjetas_retenciones 
JOIN 
movcaja ON tarjetas_retenciones.tarjetas_retencionesid=movcaja.tarjetas_retencionesid
JOIN
cajas ON movcaja.cajasid=cajas.cajasid
LEFT JOIN
depositos ON movcaja.depositosid = depositos.depositosid
JOIN
clientes ON clientes.clientesid = (Select clientesid from facturas_retenciones where facturas_retenciones.documentosid = tarjetas_retenciones.tarjetas_retencionesid AND facturas_retenciones.origen = 'Voucher' LIMIT 1)
WHERE
tarjetas_retenciones.asientocontable=0
AND (tarjetas_retenciones.tarjetas_retencionesid = nDocumentoid )

GROUP BY
cajas.codigocontable,
movcaja.centros_costosid
HAVING
SUM(CASE WHEN (depositos.comisionestarjetas = 0  OR (depositos.depositosid IS NULL AND movcaja.depositosid = 0 and movcaja.tarjetas_retencionesid >0)) THEN
(movcaja.voucheriva+movcaja.voucherrenta+movcaja.vouchercomicion)
ELSE
(movcaja.voucheriva+movcaja.voucherrenta)
END )<>0

UNION ALL

SELECT 
tarjetas_retenciones.emision AS fechamovimiento,
movcaja.centros_costosid AS centros_costosid,
CONCAT('Retencion Voucher ',clientes.razonsocial) AS concepto,
tarjetas_retenciones.secuencia AS referencia,
SUM(movcaja.vouchercomicion) AS valor,
sCuentaContable AS codigocontable
FROM
tarjetas_retenciones
JOIN
movcaja ON tarjetas_retenciones.tarjetas_retencionesid=movcaja.tarjetas_retencionesid
LEFT JOIN
depositos ON depositos.depositosid = movcaja.depositosid
JOIN clientes ON clientes.clientesid = (Select clientesid from facturas_retenciones where facturas_retenciones.documentosid = tarjetas_retenciones.tarjetas_retencionesid AND facturas_retenciones.origen = 'Voucher' LIMIT 1 )
WHERE
tarjetas_retenciones.asientocontable=0
AND (tarjetas_retenciones.tarjetas_retencionesid = nDocumentoid)
AND    (
        (depositos.comisionestarjetas = 0 AND depositos.depositosid IS NOT NULL)
        OR (movcaja.depositosid = 0 AND movcaja.tarjetas_retencionesid > 0)
    )
GROUP BY
movcaja.centros_costosid
HAVING
SUM(movcaja.vouchercomicion)<>0
;

-- Controlamos si hubo error
DECLARE exit handler FOR SQLEXCEPTION, SQLWARNING
  BEGIN
  	SHOW WARNINGS limit 1;
    ROLLBACK;
    RESIGNAL;
  END;

-- Declaramos el control de salida del loop
DECLARE CONTINUE HANDLER FOR NOT FOUND SET termino = TRUE;

-- Abrimos el Cursor
OPEN Datos_Asiento;

-- Iniciamos la Transaccion
START TRANSACTION;

-- Leeemos el Cursor
read_loop: LOOP
FETCH Datos_Asiento INTO fechamovimiento,centros_costosid, concepto, referencia, valor, codigocontable;

-- Verificamos si no hay mas registros
IF termino THEN
LEAVE read_loop;
END IF;

SET diferencia = ROUND(diferencia+(Round(valor,2)),2);
-- Sumamos valores de debe y haber
IF valor<0 THEN
  SET haber = (haber + (Abs((valor))));
ELSE
  SET debe  = (debe + (Abs((valor))));
END IF;

-- INSERTAMOS LA CABECERA DEL ASIENTO
  IF gravocabecera=FALSE THEN
    -- Optenemos el nuevo secuencial
    call SP_Consulta_Secuencias_Internas('LIBRODIARIO',codigoasiento);
  
    -- Insertamos Registro Cabecera
    INSERT INTO libros_diarios 
    (
      codigoasiento, 
      fecha, 
      referencia, 
      concepto, 
      origen, 
      usuariocreacion, 
      fechacreacion
    ) 
    VALUES 
    (
      codigoasiento,
      fechamovimiento,
      referencia, 
      concepto,
      'Retenciones Vou', 
      sUsuario, 
      NOW(3)
    );
   
   -- obtenemos el ultimo ID insertado
    SET libros_diariosid=(select LAST_INSERT_ID());
    
    -- Actualizamos el secuencial de libros diarios
    call SP_Actualiza_Secuencias_Internas('LIBRODIARIO');

    -- Ponemos que gravo la cabecera
    SET gravocabecera=TRUE;

  END IF;

-- INSERTAMOS LOS DETALLES
SET valor = round(valor,2);
INSERT INTO libros_diarios_detalles
( 	
libros_diariosid,	
codigocontable,	
centros_costosid,	
referencia,	
concepto,	
importe
)
VALUES
( 
libros_diariosid,	
codigocontable,	
centros_costosid,	
referencia,	
concepto,	
valor
 );

-- Toma la primer cuenta del asiento contable
IF cuenta_fija=0 THEN 
SET cuenta_fija = (select LAST_INSERT_ID());
END IF;

END LOOP;

CALL SP_Contabiliza_Verificar_Asiento(libros_diariosid,verificado);


-- Cuadramos el asiento contable si esta descuadrado
IF diferencia<0.11 AND diferencia>-0.11 AND diferencia<>0  THEN
UPDATE libros_diarios_detalles
SET
libros_diarios_detalles.importe = libros_diarios_detalles.importe-diferencia
WHERE
libros_diarios_detalles.libros_diarios_detallesid = cuenta_fija;
SET diferencia=0;
END IF;

-- Verificamos si el asiento esta cuadrado
IF diferencia<>0 THEN
SET verificado=0;
END IF;

-- Actualizamos el libro diario
SET debe = Round(debe,2);
SET haber = Round(haber,2);
UPDATE 
libros_diarios
SET
libros_diarios.debito = debe,
libros_diarios.credito = haber,
libros_diarios.mayorizado = verificado,
libros_diarios.verificado = verificado
WHERE
libros_diarios.libros_diariosid = libros_diariosid;


-- Actualizamos el ID del libro diario a el movimiento de Caja
UPDATE
tarjetas_retenciones 
SET
tarjetas_retenciones.asientocontable=libros_diariosid
WHERE
tarjetas_retenciones.asientocontable = 0
AND tarjetas_retenciones.tarjetas_retencionesid = nDocumentoid;

-- Finalizamos la transaccion
COMMIT;

-- Cerramos el Cursor
CLOSE Datos_Asiento;

-- Devolvemos el ID del Asiento Contable
select libros_diariosid;

END
;;
delimiter ;

-- ----------------------------
-- Procedure structure for SP_Contabiliza_Eliminar_Asiento
-- ----------------------------
DROP PROCEDURE IF EXISTS `SP_Contabiliza_Eliminar_Asiento`;
delimiter ;;
CREATE PROCEDURE `SP_Contabiliza_Eliminar_Asiento`(IN nDocumentoid BIGINT, IN sOrigen VARCHAR(255))
  SQL SECURITY INVOKER
BEGIN

  DECLARE vFechaAsiento date DEFAULT '0000-00-00';
  DECLARE vFechadesde date DEFAULT '0000-00-00';
  DECLARE vFechahasta date DEFAULT '0000-00-00';
  DECLARE vOrigenMod varchar(21) DEFAULT '';

  -- Controlamos si hubo error
  DECLARE EXIT HANDLER FOR SQLEXCEPTION, SQLWARNING
  BEGIN
    SHOW WARNINGS LIMIT 1;
    -- Cancelamos la transaccion
    ROLLBACK;
    -- Devolvemos el error de la transaccion
    RESIGNAL;
  END;

  #Se ubica los origenes de contabilidad con los de bloqueo de periodos
  CASE sOrigen
    WHEN 'Facturacion' THEN SET vOrigenMod = 'Facturacion';
    WHEN 'Costo de Venta' THEN SET vOrigenMod = 'Facturacion';
    WHEN 'Entregas' THEN SET vOrigenMod = 'Facturacion';
    WHEN ('Caja') THEN SET vOrigenMod = 'Caja';
    WHEN ('Cobros') THEN SET vOrigenMod = 'Cartera';
    WHEN ('Compras') THEN SET vOrigenMod = 'Compras';
 	WHEN ('Retenciones') THEN SET vOrigenMod = 'Compras';    
    WHEN ('Pagos') THEN SET vOrigenMod = 'Pagos';
    WHEN ('Banco') THEN SET vOrigenMod = 'Bancos';
    WHEN ('Ingresos') THEN SET vOrigenMod = 'Ingresos';
    WHEN ('Salidas') THEN SET vOrigenMod = 'Salidas';
    WHEN ('Depositos') THEN SET vOrigenMod = 'Depositos';
    WHEN ('Tarjetas_Retenciones') THEN SET vOrigenMod = 'Vouchers';
    WHEN ('Nomina') THEN SET vOrigenMod = 'Nomina';
    WHEN ('Activos') THEN SET vOrigenMod = 'Activos';
    WHEN 'Garantias' THEN SET vOrigenMod = 'Garantias';
    WHEN 'Talleres' THEN SET vOrigenMod = 'Talleres';
    WHEN ('Contabilidad') THEN SET vOrigenMod = 'Contabilidad'; 
    ELSE SET vOrigenMod = sOrigen;
  END CASE;

  SET vFechaAsiento = (SELECT
      libros_diarios.fecha
    FROM libros_diarios
    WHERE libros_diarios.libros_diariosid = nDocumentoid
    LIMIT 1);

  SET vFechahasta =IFNULL( (SELECT
      contabilidad_bloqueo.fecha_bloqueo 
    FROM contabilidad_bloqueo
    WHERE contabilidad_bloqueo.modulos = vOrigenMod
    LIMIT 1), '2000-12-31');

  IF vFechaAsiento > vFechahasta THEN

    -- Iniciamos la Transaccion
    START TRANSACTION;

      -- Elimina el Detalles del asiento
      DELETE
        FROM libros_diarios_detalles
      WHERE libros_diarios_detalles.libros_diariosid = nDocumentoid;

      -- Elimina la Cabecera del asiento
      DELETE
        FROM libros_diarios
      WHERE libros_diarios.libros_diariosid = nDocumentoid;
      -- Ejecutamos la limpieza de los modulos
      CASE

        WHEN sOrigen IN ('Facturacion') THEN UPDATE facturas
            SET facturas.asientocontable = 0,
facturas.fechamodificacion = facturas.fechamodificacion            
            WHERE facturas.asientocontable = nDocumentoid;
            UPDATE movcaja
            SET movcaja.asientocontable = 0,
movcaja.fechamodificacion = movcaja.fechamodificacion            
            WHERE movcaja.asientocontable = nDocumentoid;
            UPDATE movbanco
            SET movbanco.asientocontable = 0,
movbanco.fechamodificacion = movbanco.fechamodificacion            
            WHERE movbanco.asientocontable = nDocumentoid;
            UPDATE cuentasporcobrar
            SET cuentasporcobrar.asientocontable = 0,
cuentasporcobrar.fechamodificacion= cuentasporcobrar.fechamodificacion  
            WHERE cuentasporcobrar.asientocontable = nDocumentoid;
        WHEN sOrigen IN ('Costo de Venta') THEN UPDATE facturas
            SET facturas.asientocosto = 0,
facturas.fechamodificacion = facturas.fechamodificacion             
            WHERE facturas.asientocosto = nDocumentoid;

        WHEN sOrigen IN ('Caja') THEN UPDATE movcaja
            SET movcaja.asientocontable = 0,
movcaja.fechamodificacion = movcaja.fechamodificacion               
            WHERE movcaja.asientocontable = nDocumentoid;

 WHEN sOrigen IN ('Retenciones') THEN 
 UPDATE compras
              SET compras.asientocontable = 0,
compras.fechamodificacion = compras.fechamodificacion            
            WHERE compras.asientocontable = nDocumentoid AND compras.asientocontable = compras.asientocontable_retencion;
            
            UPDATE movcaja
            SET movcaja.asientocontable = 0,
movcaja.fechamodificacion = movcaja.fechamodificacion             
            WHERE movcaja.asientocontable = nDocumentoid ;
            UPDATE movbanco
            SET movbanco.asientocontable = 0,
movbanco.fechamodificacion = movbanco.fechamodificacion             
            WHERE movbanco.asientocontable = nDocumentoid ;
 
 -- para las compras normales
 UPDATE compras
            SET compras.asientocontable_retencion = 0,
compras.fechamodificacion = compras.fechamodificacion            
            WHERE compras.asientocontable_retencion = nDocumentoid;
             UPDATE cuentasporpagar
            SET cuentasporpagar.asientocontable = 0,
cuentasporpagar.fechamodificacion = cuentasporpagar.fechamodificacion
            WHERE cuentasporpagar.asientocontable = nDocumentoid;

        WHEN sOrigen IN ('Cobros') THEN UPDATE cobros
            SET cobros.asientocontable = 0,		
            cobros.fechamodificacion = cobros.fechamodificacion            
            WHERE cobros.asientocontable = nDocumentoid;
            UPDATE movcaja
            SET movcaja.asientocontable = 0,
movcaja.fechamodificacion = movcaja.fechamodificacion               
            WHERE movcaja.asientocontable = nDocumentoid;
            UPDATE movbanco
            SET movbanco.asientocontable = 0,
movbanco.fechamodificacion = movbanco.fechamodificacion            
            WHERE movbanco.asientocontable = nDocumentoid;
            UPDATE cuentasporcobrar
            SET cuentasporcobrar.asientocontable = 0,
cuentasporcobrar.fechamodificacion= cuentasporcobrar.fechamodificacion             
            WHERE cuentasporcobrar.asientocontable = nDocumentoid;

        WHEN sOrigen IN ('Entregas') THEN UPDATE entregas
            SET entregas.asientocontable = 0,
entregas.fechamodificacion = entregas.fechamodificacion            
            WHERE entregas.asientocontable = nDocumentoid;


        WHEN sOrigen IN ('Compras') THEN 
         UPDATE compras
             SET compras.asientocontable_retencion = 0,
            compras.fechamodificacion = compras.fechamodificacion            
            WHERE compras.asientocontable_retencion = nDocumentoid AND compras.asientocontable = compras.asientocontable_retencion;
            
        UPDATE compras
            SET compras.asientocontable = 0,
compras.fechamodificacion = compras.fechamodificacion            
            WHERE compras.asientocontable = nDocumentoid;
            UPDATE compras_recepciones
            SET compras_recepciones.asientocontable = 0,
compras_recepciones.fechamodificacion= compras_recepciones.fechamodificacion           
            WHERE compras_recepciones.asientocontable = nDocumentoid;
            UPDATE movcaja
            SET movcaja.asientocontable = 0,
movcaja.fechamodificacion = movcaja.fechamodificacion             
            WHERE movcaja.asientocontable = nDocumentoid;
            UPDATE movbanco
            SET movbanco.asientocontable = 0,
movbanco.fechamodificacion = movbanco.fechamodificacion             
            WHERE movbanco.asientocontable = nDocumentoid;
            UPDATE cuentasporpagar
            SET cuentasporpagar.asientocontable = 0,
cuentasporpagar.fechamodificacion = cuentasporpagar.fechamodificacion
            WHERE cuentasporpagar.asientocontable = nDocumentoid;

        WHEN sOrigen IN ('Pagos') THEN UPDATE pagos
            SET pagos.asientocontable = 0
            WHERE pagos.asientocontable = nDocumentoid;
            UPDATE movcaja
            SET movcaja.asientocontable = 0,
movcaja.fechamodificacion = movcaja.fechamodificacion              
            WHERE movcaja.asientocontable = nDocumentoid;
            UPDATE movbanco
            SET movbanco.asientocontable = 0,
movbanco.fechamodificacion = movbanco.fechamodificacion            
            WHERE movbanco.asientocontable = nDocumentoid;
            UPDATE cuentasporpagar
            SET cuentasporpagar.asientocontable = 0,
cuentasporpagar.fechamodificacion = cuentasporpagar.fechamodificacion            
            WHERE cuentasporpagar.asientocontable = nDocumentoid;

        WHEN sOrigen IN ('Banco') THEN UPDATE movbanco
            SET movbanco.asientocontable = 0,
movbanco.fechamodificacion = movbanco.fechamodificacion            
            WHERE movbanco.asientocontable = nDocumentoid;

        WHEN sOrigen IN ('Salidas') THEN UPDATE salidas
            SET salidas.asientocontable = 0,
salidas.fechamodificacion = salidas.fechamodificacion            
            WHERE salidas.asientocontable = nDocumentoid;

        WHEN sOrigen IN ('Ingresos') THEN UPDATE ingresos
            SET ingresos.asientocontable = 0,
ingresos.fechamodificacion = ingresos.fechamodificacion            
            WHERE ingresos.asientocontable = nDocumentoid;

        WHEN sOrigen IN ('Depositos') THEN UPDATE depositos
            SET depositos.asientocontable = 0
            WHERE depositos.asientocontable = nDocumentoid;
            UPDATE movcaja
            SET movcaja.asientocontable = 0,
movcaja.fechamodificacion = movcaja.fechamodificacion             
            WHERE movcaja.asientocontable = nDocumentoid;
            UPDATE movbanco
            SET movbanco.asientocontable = 0,
movbanco.fechamodificacion = movbanco.fechamodificacion            
            WHERE movbanco.asientocontable = nDocumentoid;

        WHEN sOrigen IN ('Tarjetas_Retenciones') THEN UPDATE tarjetas_retenciones
            SET tarjetas_retenciones.asientocontable = 0
            WHERE tarjetas_retenciones.asientocontable = nDocumentoid;
            UPDATE movcaja
            SET movcaja.asientocontable = 0,
movcaja.fechamodificacion = movcaja.fechamodificacion             
            WHERE movcaja.asientocontable = nDocumentoid;
            UPDATE movbanco
            SET movbanco.asientocontable = 0,
            movbanco.fechamodificacion = movbanco.fechamodificacion   
            WHERE movbanco.asientocontable = nDocumentoid;

        WHEN sOrigen IN ('Nomina') THEN UPDATE nomina_roles
            SET nomina_roles.asientocontable = 0
            WHERE nomina_roles.asientocontable = nDocumentoid;
            UPDATE movcaja
            SET movcaja.asientocontable = 0,
movcaja.fechamodificacion = movcaja.fechamodificacion               
            WHERE movcaja.asientocontable = nDocumentoid;
            UPDATE movbanco
            SET movbanco.asientocontable = 0,
movbanco.fechamodificacion = movbanco.fechamodificacion               
            WHERE movbanco.asientocontable = nDocumentoid;

        WHEN sOrigen IN ('Activos') THEN UPDATE activos_depreciaciones
            SET activos_depreciaciones.libros_diariosid = 0
            WHERE activos_depreciaciones.libros_diariosid = nDocumentoid;

        WHEN sOrigen IN ('Talleres') THEN UPDATE talleres_seguimientos
            SET talleres_seguimientos.asientocontable = 0,
talleres_seguimientos.fechamodificiacion = talleres_seguimientos.fechamodificiacion            
            WHERE talleres_seguimientos.asientocontable = nDocumentoid;

        WHEN sOrigen IN ('Garantias') THEN UPDATE garantias_seguimientos
            SET garantias_seguimientos.asientocontable = 0,
garantias_seguimientos.fechamodificacion = garantias_seguimientos.fechamodificacion            
            WHERE garantias_seguimientos.asientocontable = nDocumentoid;

        WHEN sOrigen IN ('Contabilidad') THEN UPDATE tarjetas_retenciones
            SET tarjetas_retenciones.asientocontable = 0
            WHERE tarjetas_retenciones.asientocontable = nDocumentoid;
            UPDATE movcaja
            SET movcaja.asientocontable = 0,
movcaja.fechamodificacion = movcaja.fechamodificacion               
            WHERE movcaja.asientocontable = nDocumentoid;
            UPDATE movbanco
            SET movbanco.asientocontable = 0,
movbanco.fechamodificacion = movbanco.fechamodificacion               
            WHERE movbanco.asientocontable = nDocumentoid;
            UPDATE nomina_roles
            SET nomina_roles.asientocontable = 0
            WHERE nomina_roles.asientocontable = nDocumentoid;

            UPDATE activos_depreciaciones
            SET activos_depreciaciones.libros_diariosid = 0
            WHERE activos_depreciaciones.libros_diariosid = nDocumentoid;
            UPDATE talleres_seguimientos
            SET talleres_seguimientos.asientocontable = 0
            WHERE talleres_seguimientos.asientocontable = nDocumentoid;

            UPDATE ingresos
            SET ingresos.asientocontable = 0,
ingresos.fechamodificacion = ingresos.fechamodificacion            
            WHERE ingresos.asientocontable = nDocumentoid;

            UPDATE salidas
            SET salidas.asientocontable = 0,
salidas.fechamodificacion = salidas.fechamodificacion            
            WHERE salidas.asientocontable = nDocumentoid;

            UPDATE depositos
            SET depositos.asientocontable = 0
            WHERE depositos.asientocontable = nDocumentoid;

            UPDATE pagos
            SET pagos.asientocontable = 0
            WHERE pagos.asientocontable = nDocumentoid;

            UPDATE cuentasporpagar
            SET cuentasporpagar.asientocontable = 0,
cuentasporpagar.fechamodificacion  = cuentasporpagar.fechamodificacion 
            WHERE cuentasporpagar.asientocontable = nDocumentoid;

UPDATE compras
            SET compras.asientocontable_retencion = 0,
compras.fechamodificacion = compras.fechamodificacion            
            WHERE compras.asientocontable_retencion = nDocumentoid;
            
            UPDATE compras
            SET compras.asientocontable = 0,
compras.fechamodificacion = compras.fechamodificacion            
            WHERE compras.asientocontable = nDocumentoid;
            UPDATE compras_recepciones
            SET compras_recepciones.asientocontable = 0,
compras_recepciones.fechamodificacion = compras_recepciones.fechamodificacion            
            WHERE compras_recepciones.asientocontable = nDocumentoid;
            UPDATE cobros
            SET cobros.asientocontable = 0
            WHERE cobros.asientocontable = nDocumentoid;

            UPDATE cuentasporcobrar
            SET cuentasporcobrar.asientocontable = 0,
cuentasporcobrar.fechamodificacion = cuentasporcobrar.fechamodificacion 
            WHERE cuentasporcobrar.asientocontable = nDocumentoid;
            UPDATE entregas
            SET entregas.asientocontable = 0,
entregas.fechamodificacion =   entregas.fechamodificacion          
            WHERE entregas.asientocontable = nDocumentoid;
            UPDATE facturas
            SET facturas.asientocontable = 0,
facturas.fechamodificacion  =  facturas.fechamodificacion            
            WHERE facturas.asientocontable = nDocumentoid;
            UPDATE facturas
            SET facturas.asientocosto = 0,
facturas.fechamodificacion  =  facturas.fechamodificacion             
            WHERE facturas.asientocosto = nDocumentoid;
            UPDATE garantias_seguimientos
            SET garantias_seguimientos.asientocontable = 0,
garantias_seguimientos.fechamodificacion =  garantias_seguimientos.fechamodificacion           
            WHERE garantias_seguimientos.asientocontable = nDocumentoid;
     
      END CASE;


    -- Finalizamos la transaccion
    COMMIT;

  SELECT 1 AS resultado;
ELSE

  SELECT 0 AS resultado;
  END IF;


END
;;
delimiter ;

-- ----------------------------
-- Procedure structure for SP_Contabiliza_Eliminar_Asiento_Agrupado
-- ----------------------------
DROP PROCEDURE IF EXISTS `SP_Contabiliza_Eliminar_Asiento_Agrupado`;
delimiter ;;
CREATE PROCEDURE `SP_Contabiliza_Eliminar_Asiento_Agrupado`(IN nDocumentoid longtext, IN sOrigen VARCHAR(255), IN sRegistro JSON)
  SQL SECURITY INVOKER
BEGIN
   DECLARE vFechaAsiento date DEFAULT '0000-00-00';
   DECLARE vFechadesde date DEFAULT '0000-00-00';
   DECLARE vFechahasta date DEFAULT '0000-00-00';
   DECLARE vContador INT DEFAULT FALSE;
  
 # VARIABLE DE LOS DATOS DE LA AUDITORIA
   DECLARE p_sis_subcategoriasid int(11) DEFAULT 0;
   DECLARE p_sis_empresasid int(11) DEFAULT 0;
   DECLARE p_sis_usuariosid varchar(20) DEFAULT '';
   DECLARE p_equipo varchar(50) DEFAULT '';
   DECLARE p_tipooperacion varchar(50) DEFAULT '';
   DECLARE p_detalle longtext;  

  -- Controlamos si hubo error
  DECLARE EXIT HANDLER FOR SQLEXCEPTION, SQLWARNING
  BEGIN
    SHOW WARNINGS LIMIT 1;
    -- Cancelamos la transaccion
    ROLLBACK;
    -- Devolvemos el error de la transaccion
    RESIGNAL;
  END;

    -- Iniciamos la Transaccion
   
   START TRANSACTION;
-- Eliminamos la tabla usuario_temporal

-- verificamos el periodo de bloqueo
    DROP TEMPORARY TABLE IF EXISTS tabla_temporal_bloqueo;

CREATE TEMPORARY TABLE tabla_temporal_bloqueo AS
SELECT *
FROM JSON_TABLE(nDocumentoid, -- Reemplaza esto con tu arreglo JSON de IDs
  '$[*]' COLUMNS(libros_diariosid INT PATH '$')
) AS jt;

-- creamos la tabla con datos filtrados el contabilidad_bloqueo
DROP TEMPORARY TABLE IF EXISTS tabla_temporal;

CREATE TEMPORARY TABLE tabla_temporal AS
SELECT tabla_temporal_bloqueo.libros_diariosid FROM tabla_temporal_bloqueo INNER JOIN libros_diarios ON tabla_temporal_bloqueo.libros_diariosid=libros_diarios.libros_diariosid LEFT JOIN contabilidad_bloqueo
ON (CASE WHEN libros_diarios.origen='Recepciones' THEN 'Compras' WHEN libros_diarios.origen='Entregas' THEN 'Facturacion' WHEN libros_diarios.origen='Costo de Venta' THEN 'Facturacion' WHEN libros_diarios.origen='Cobros' THEN 'Cartera' WHEN libros_diarios.origen='Ajuste CXC' THEN 'Cartera' WHEN libros_diarios.origen='Ajuste CXP' THEN 'Pagos' WHEN libros_diarios.origen='Facturacion Ret' THEN 'Cartera' WHEN libros_diarios.origen='Retencion AC' THEN 'Cartera' WHEN libros_diarios.origen='Retencion AJ' THEN 'Cartera' WHEN libros_diarios.origen='Activos Fijos' THEN 'Activos' WHEN libros_diarios.origen='Retenciones' THEN 'Compras'  WHEN libros_diarios.origen='Retenciones Vou' THEN 'Vouchers' ELSE libros_diarios.origen END)=contabilidad_bloqueo.modulos WHERE (contabilidad_bloqueo.modulos IS NULL OR libros_diarios.fecha>contabilidad_bloqueo.fecha_bloqueo OR contabilidad_bloqueo.fecha_bloqueo is NULL);
SET vContador = (SELECT COUNT(*) AS cantidad_registros FROM tabla_temporal);

    -- RETURN SELECT * FROM tabla_temporal;
-- CALL SP_crear_tabla_temporal(nDocumentoid, ',');
      -- Elimina el Detalles del asiento
      DELETE libros_diarios_detalles
        FROM libros_diarios_detalles INNER JOIN tabla_temporal ON libros_diarios_detalles.libros_diariosid=tabla_temporal.libros_diariosid;
      -- WHERE libros_diarios_detalles.libros_diariosid IN (SELECT tabla_temporal.libros_diariosid FROM tabla_temporal);

      -- Elimina la Cabecera del asiento
      DELETE libros_diarios
        FROM libros_diarios INNER JOIN tabla_temporal ON libros_diarios.libros_diariosid=tabla_temporal.libros_diariosid;
     --  WHERE libros_diarios.libros_diariosid IN (SELECT tabla_temporal.libros_diariosid FROM tabla_temporal);
      -- Ejecutamos la limpieza de los modulos
      CASE

 
        WHEN sOrigen IN ('Contabilidad') THEN 
UPDATE tarjetas_retenciones INNER JOIN tabla_temporal ON tarjetas_retenciones.asientocontable=tabla_temporal.libros_diariosid
            SET tarjetas_retenciones.asientocontable = 0;
            UPDATE movcaja INNER JOIN tabla_temporal ON tabla_temporal.libros_diariosid=movcaja.asientocontable
            SET movcaja.asientocontable = 0, movcaja.fechamodificacion = movcaja.fechamodificacion;
            UPDATE movbanco INNER JOIN tabla_temporal ON tabla_temporal.libros_diariosid=movbanco.asientocontable
            SET movbanco.asientocontable = 0, movbanco.fechamodificacion = movbanco.fechamodificacion;
            UPDATE nomina_roles INNER JOIN tabla_temporal ON tabla_temporal.libros_diariosid=nomina_roles.asientocontable
            SET nomina_roles.asientocontable = 0; 

            UPDATE activos_depreciaciones
            SET activos_depreciaciones.libros_diariosid = 0
            WHERE activos_depreciaciones.libros_diariosid IN (SELECT tabla_temporal.libros_diariosid FROM tabla_temporal);

            UPDATE talleres_seguimientos INNER JOIN tabla_temporal ON tabla_temporal.libros_diariosid=talleres_seguimientos.asientocontable
            SET talleres_seguimientos.asientocontable = 0, talleres_seguimientos.fechamodificiacion = talleres_seguimientos.fechamodificiacion;

            UPDATE ingresos INNER JOIN tabla_temporal ON tabla_temporal.libros_diariosid=ingresos.asientocontable
            SET ingresos.asientocontable = 0, ingresos.fechamodificacion = ingresos.fechamodificacion; 


            UPDATE salidas INNER JOIN tabla_temporal ON tabla_temporal.libros_diariosid=salidas.asientocontable
            SET salidas.asientocontable = 0, salidas.fechamodificacion = salidas.fechamodificacion; 

            UPDATE depositos INNER JOIN tabla_temporal ON tabla_temporal.libros_diariosid=depositos.asientocontable
            SET depositos.asientocontable = 0;

            UPDATE pagos INNER JOIN tabla_temporal ON tabla_temporal.libros_diariosid=pagos.asientocontable
            SET pagos.asientocontable = 0;

UPDATE compras INNER JOIN tabla_temporal ON tabla_temporal.libros_diariosid=compras.asientocontable_retencion
            SET compras.asientocontable_retencion = 0;
            
            UPDATE cuentasporpagar INNER JOIN tabla_temporal ON tabla_temporal.libros_diariosid=cuentasporpagar.asientocontable
            SET cuentasporpagar.asientocontable = 0, cuentasporpagar.fechamodificacion = cuentasporpagar.fechamodificacion;

            UPDATE compras INNER JOIN tabla_temporal ON tabla_temporal.libros_diariosid=compras.asientocontable
            SET compras.asientocontable = 0, compras.fechamodificacion = compras.fechamodificacion; 
            UPDATE compras_recepciones INNER JOIN tabla_temporal ON tabla_temporal.libros_diariosid=compras_recepciones.asientocontable
            SET compras_recepciones.asientocontable = 0, compras_recepciones.fechamodificacion = compras_recepciones.fechamodificacion;
            UPDATE cobros INNER JOIN tabla_temporal ON tabla_temporal.libros_diariosid=cobros.asientocontable
            SET cobros.asientocontable = 0;

            UPDATE cuentasporcobrar INNER JOIN tabla_temporal ON tabla_temporal.libros_diariosid=cuentasporcobrar.asientocontable
            SET cuentasporcobrar.asientocontable = 0, cuentasporcobrar.fechamodificacion = cuentasporcobrar.fechamodificacion ;
            UPDATE entregas INNER JOIN tabla_temporal ON tabla_temporal.libros_diariosid=entregas.asientocontable
            SET entregas.asientocontable = 0, entregas.fechamodificacion = entregas.fechamodificacion;
            UPDATE facturas INNER JOIN tabla_temporal ON tabla_temporal.libros_diariosid=facturas.asientocontable
            SET facturas.asientocontable = 0, facturas.fechamodificacion = facturas.fechamodificacion; 
UPDATE facturas INNER JOIN tabla_temporal ON tabla_temporal.libros_diariosid=facturas.asientocosto
            SET facturas.asientocosto = 0,facturas.fechamodificacion = facturas.fechamodificacion;
            UPDATE garantias_seguimientos INNER JOIN tabla_temporal ON tabla_temporal.libros_diariosid=garantias_seguimientos.asientocontable
            SET garantias_seguimientos.asientocontable = 0, garantias_seguimientos.fechamodificacion = garantias_seguimientos.fechamodificacion;
      END CASE;

IF vContador > 0 THEN
SET p_sis_subcategoriasid = JSON_UNQUOTE(JSON_EXTRACT(sRegistro, '$.m_sis_subcategoriasid'));
        SET p_sis_empresasid = JSON_UNQUOTE(JSON_EXTRACT(sRegistro, '$.m_sis_empresasid'));
        SET p_sis_usuariosid = JSON_UNQUOTE(JSON_EXTRACT(sRegistro, '$.m_sis_usuariosid'));
        SET p_equipo = JSON_UNQUOTE(JSON_EXTRACT(sRegistro, '$.m_equipo'));
SET p_detalle =JSON_UNQUOTE(JSON_EXTRACT(sRegistro, '$.m_detalle'));
SET p_tipooperacion = 'E';
# INSERTAMOS LA AUDITORIA
        CALL sistemaperseo.SP_ABC_sis_log_sistema(p_sis_subcategoriasid, p_sis_empresasid, p_sis_usuariosid, p_tipooperacion, p_detalle, p_equipo);
END IF;

    -- Finalizamos la transaccion
   COMMIT;

  SELECT 1 AS resultado;

END
;;
delimiter ;

-- ----------------------------
-- Procedure structure for SP_Contabiliza_Entregas_Agrupado
-- ----------------------------
DROP PROCEDURE IF EXISTS `SP_Contabiliza_Entregas_Agrupado`;
delimiter ;;
CREATE PROCEDURE `SP_Contabiliza_Entregas_Agrupado`(IN dFechaDesde DATE, IN dFechaHasta DATE, IN sUsuario VARCHAR(25))
  MODIFIES SQL DATA 
BEGIN

-- Declaramos variables de Cursor
DECLARE termino INT DEFAULT FALSE;
-- DECLARE fechamovimiento date;
DECLARE usuariocreacion varchar(25);
DECLARE centros_costosid int(11);
DECLARE concepto varchar(200);
DECLARE referencia varchar(15);
DECLARE valor decimal(16,8) DEFAULT 0;
DECLARE codigocontable varchar(30);
DECLARE codigoasiento varchar(10);
DECLARE gravocabecera INT DEFAULT FALSE;
DECLARE libros_diariosid bigint DEFAULT 0;
DECLARE debe  decimal(16,8) DEFAULT 0;
DECLARE haber decimal(16,8) DEFAULT 0;
DECLARE diferencia decimal(12,2) DEFAULT 0;
DECLARE verificado INT DEFAULT TRUE;
DECLARE cuenta_fija bigint DEFAULT 0;

DECLARE Datos_Asiento CURSOR FOR
SELECT 
entregas_detalles.centros_costosid AS centros_costosid,
ROUND(SUM(entregas_detalles.costo*entregas_detalles.cantidad),8) AS valor, 
productos.cuentacontable_costo AS codigocontable
FROM entregas
INNER JOIN (entregas_detalles
INNER JOIN ( productos) ON entregas_detalles.productosid = productos.productosid
) ON (entregas.entregasid = entregas_detalles.entregasid)
WHERE 	
entregas.asientocontable = 0
AND DATE(entregas.emision) between dFechaDesde and dFechaHasta
AND ((entregas_detalles.compuestoid = 0 AND  entregas_detalles.servicio= 0) OR (entregas_detalles.compuestoid > 0 AND  entregas_detalles.servicio= 0) )	
GROUP BY 
entregas_detalles.centros_costosid, 
productos.cuentacontable_inventarios	
HAVING
SUM(entregas_detalles.costo*entregas_detalles.cantidad)<>0

UNION

SELECT 
entregas_detalles.centros_costosid AS centros_costosid,
ROUND(SUM(-entregas_detalles.costo*entregas_detalles.cantidad),8) AS valor, 
productos.cuentacontable_inventarios AS codigocontable
FROM entregas
INNER JOIN (entregas_detalles
INNER JOIN ( productos) ON entregas_detalles.productosid = productos.productosid
) ON (entregas.entregasid = entregas_detalles.entregasid)
WHERE 	
entregas.asientocontable = 0
AND  DATE(entregas.emision) BETWEEN dFechaDesde and dFechaHasta
AND ((entregas_detalles.compuestoid = 0 AND  entregas_detalles.servicio= 0) OR (entregas_detalles.compuestoid > 0 AND  entregas_detalles.servicio= 0) )	
GROUP BY 
entregas_detalles.centros_costosid, 
productos.cuentacontable_inventarios
HAVING
SUM(-entregas_detalles.costo*entregas_detalles.cantidad)<>0;



-- Controlamos si hubo error
DECLARE exit handler FOR SQLEXCEPTION, SQLWARNING
  BEGIN
  	SHOW WARNINGS limit 1;
    ROLLBACK;
    RESIGNAL;
  END;

-- Declaramos el control de salida del loop
DECLARE CONTINUE HANDLER FOR NOT FOUND SET termino = TRUE;

-- Abrimos el Cursor
OPEN Datos_Asiento;

-- Iniciamos la Transaccion
START TRANSACTION;

-- Leeemos el Cursor
read_loop: LOOP
FETCH Datos_Asiento INTO centros_costosid, valor, codigocontable;

-- Verificamos si no hay mas registros
IF termino THEN
LEAVE read_loop;
END IF;

SET diferencia = ROUND(diferencia+(Round(valor,2)),2);
-- Sumamos valores de debe y haber
IF valor<0 THEN
  SET haber = (haber + (Abs((valor))));
ELSE
  SET debe  = (debe + (Abs((valor))));
END IF;

-- INSERTAMOS LA CABECERA DEL ASIENTO
  IF gravocabecera=FALSE THEN
    -- Optenemos el nuevo secuencial
    call SP_Consulta_Secuencias_Internas('LIBRODIARIO',codigoasiento);
  
    -- Insertamos Registro Cabecera
    INSERT INTO libros_diarios 
    (
      codigoasiento, 
      fecha, 
      referencia, 
      concepto, 
      origen, 
      usuariocreacion, 
      fechacreacion
    ) 
    VALUES 
    (
      codigoasiento,
      dFechaHasta,
      codigoasiento, 
      CONCAT('Entregas del ',DATE_FORMAT(dFechaDesde,"%d-%m-%Y"),' al ',DATE_FORMAT(dFechaHasta,"%d-%m-%Y")),
      'Entregas', 
      sUsuario, 
      NOW()
    );
   
   -- obtenemos el ultimo ID insertado
    SET libros_diariosid=(select LAST_INSERT_ID());
    
    -- Actualizamos el secuencial de libros diarios
    call SP_Actualiza_Secuencias_Internas('LIBRODIARIO');

    -- Ponemos que gravo la cabecera
    SET gravocabecera=TRUE;

  END IF;

-- INSERTAMOS LOS DETALLES
SET valor = round(valor,2);
INSERT INTO libros_diarios_detalles
( 	
libros_diariosid,	
codigocontable,	
centros_costosid,	
referencia,	
concepto,	
importe
)
VALUES
( 
libros_diariosid,	
codigocontable,	
centros_costosid,	
codigoasiento,	
CONCAT('Entregas del ',DATE_FORMAT(dFechaDesde,"%d-%m-%Y"),' al ',DATE_FORMAT(dFechaHasta,"%d-%m-%Y")),	
valor
 );

-- Toma la primer cuenta del asiento contable
IF cuenta_fija=0 THEN 
SET cuenta_fija = (select LAST_INSERT_ID());
END IF;

END LOOP;

CALL SP_Contabiliza_Verificar_Asiento(libros_diariosid,verificado);


-- Cuadramos el asiento contable si esta descuadrado
IF diferencia<0.11 AND diferencia>-0.11 AND diferencia<>0  THEN
UPDATE libros_diarios_detalles
SET
libros_diarios_detalles.importe = libros_diarios_detalles.importe-diferencia
WHERE
libros_diarios_detalles.libros_diarios_detallesid = cuenta_fija;
SET diferencia=0;
END IF;

-- Verificamos si el asiento esta cuadrado
IF diferencia<>0 THEN
SET verificado=0;
END IF;

-- Actualizamos el libro diario
SET debe = Round(debe,2);
SET haber = Round(haber,2);
UPDATE 
libros_diarios
SET
libros_diarios.debito = debe,
libros_diarios.credito = haber,
libros_diarios.mayorizado = verificado,
libros_diarios.verificado = verificado,
libros_diarios.fechamodificacion = libros_diarios.fechamodificacion
WHERE
libros_diarios.libros_diariosid = libros_diariosid;


-- Actualizamos el ID del libro diario a el movimiento de Caja
UPDATE 
entregas 
SET 
entregas.asientocontable = libros_diariosid,
entregas.fechamodificacion = entregas.fechamodificacion
WHERE 
entregas.asientocontable = 0 
AND DATE(entregas.emision) BETWEEN dFechaDesde AND dFechaHasta;

-- Finalizamos la transaccion
COMMIT;

-- Cerramos el Cursor
CLOSE Datos_Asiento;

-- Devolvemos el ID del Asiento Contable
select libros_diariosid;

END
;;
delimiter ;

-- ----------------------------
-- Procedure structure for SP_Contabiliza_Entregas_Individual
-- ----------------------------
DROP PROCEDURE IF EXISTS `SP_Contabiliza_Entregas_Individual`;
delimiter ;;
CREATE PROCEDURE `SP_Contabiliza_Entregas_Individual`(IN nDocumentoid BIGINT, IN sUsuario VARCHAR(25))
  MODIFIES SQL DATA 
BEGIN

-- Declaramos variables de Cursor
DECLARE termino INT DEFAULT FALSE;
DECLARE fechamovimiento date;
DECLARE usuariocreacion varchar(25);
DECLARE centros_costosid int(11);
DECLARE concepto varchar(200);
DECLARE referencia varchar(15);
DECLARE valor decimal(16,8) DEFAULT 0;
DECLARE codigocontable varchar(30);
DECLARE codigoasiento varchar(15);
DECLARE gravocabecera INT DEFAULT FALSE;
DECLARE libros_diariosid bigint DEFAULT 0;
DECLARE debe  decimal(16,8) DEFAULT 0;
DECLARE haber decimal(16,8) DEFAULT 0;
DECLARE diferencia decimal(12,2) DEFAULT 0;
DECLARE verificado INT DEFAULT TRUE;
DECLARE cuenta_fija bigint DEFAULT 0;

DECLARE Datos_Asiento CURSOR FOR
SELECT 
DATE(entregas.emision) AS fechamovimiento,
entregas_detalles.centros_costosid AS centros_costosid,
entregas.concepto AS concepto, 
entregas.entregas_codigo AS referencia,
CASE WHEN SUBSTRING(entregas.entregas_codigo, 1,1) = 'D' THEN 

ROUND(SUM(-entregas_detalles.costo*entregas_detalles.cantidad),8)  
ELSE
ROUND(SUM(entregas_detalles.costo*entregas_detalles.cantidad),8)
END
AS valor,
productos.cuentacontable_costo AS codigocontable
FROM entregas
INNER JOIN (entregas_detalles
INNER JOIN ( productos) ON entregas_detalles.productosid = productos.productosid
) ON (entregas.entregasid = entregas_detalles.entregasid)
WHERE 	
entregas.asientocontable = 0
AND  entregas.entregasid = nDocumentoid	
AND ((entregas_detalles.compuestoid = 0 AND  entregas_detalles.servicio= 0) OR (entregas_detalles.compuestoid > 0 AND  entregas_detalles.servicio= 0) )	
GROUP BY 
entregas_detalles.centros_costosid, 
productos.cuentacontable_inventarios	
HAVING
SUM(entregas_detalles.costo*entregas_detalles.cantidad)<>0

UNION

SELECT 
DATE(entregas.emision) AS fechamovimiento,
entregas_detalles.centros_costosid AS centros_costosid,
  entregas.concepto AS concepto, 
entregas.entregas_codigo AS referencia,
CASE WHEN SUBSTRING(entregas.entregas_codigo, 1,1) = 'D' THEN
ROUND(SUM(entregas_detalles.costo*entregas_detalles.cantidad),8)  
ELSE
ROUND(SUM(-entregas_detalles.costo*entregas_detalles.cantidad),8) 
END
AS valor,
  productos.cuentacontable_inventarios AS codigocontable
FROM entregas
INNER JOIN (entregas_detalles
INNER JOIN ( productos) ON entregas_detalles.productosid = productos.productosid
) ON (entregas.entregasid = entregas_detalles.entregasid)
WHERE 	
entregas.asientocontable = 0
AND  entregas.entregasid = nDocumentoid
AND ((entregas_detalles.compuestoid = 0 AND  entregas_detalles.servicio= 0) OR (entregas_detalles.compuestoid > 0 AND  entregas_detalles.servicio= 0) )	
GROUP BY 
entregas_detalles.centros_costosid, 
productos.cuentacontable_inventarios
HAVING
SUM(entregas_detalles.costo*entregas_detalles.cantidad)<>0;

-- Controlamos si hubo error
DECLARE exit handler FOR SQLEXCEPTION, SQLWARNING
  BEGIN
  	SHOW WARNINGS limit 1;
    ROLLBACK;
    RESIGNAL;
  END;

-- Declaramos el control de salida del loop
DECLARE CONTINUE HANDLER FOR NOT FOUND SET termino = TRUE;

-- Abrimos el Cursor
OPEN Datos_Asiento;

-- Iniciamos la Transaccion
START TRANSACTION;

-- Leeemos el Cursor
read_loop: LOOP
FETCH Datos_Asiento INTO fechamovimiento,centros_costosid, concepto, referencia, valor, codigocontable;

-- Verificamos si no hay mas registros
IF termino THEN
LEAVE read_loop;
END IF;

SET diferencia = ROUND(diferencia+(Round(valor,2)),2);
-- Sumamos valores de debe y haber
IF valor<0 THEN
  SET haber = (haber + (Abs((valor))));
ELSE
  SET debe  = (debe + (Abs((valor))));
END IF;

-- INSERTAMOS LA CABECERA DEL ASIENTO
  IF gravocabecera=FALSE THEN
    -- Optenemos el nuevo secuencial
    call SP_Consulta_Secuencias_Internas('LIBRODIARIO',codigoasiento);
  
    -- Insertamos Registro Cabecera
    INSERT INTO libros_diarios 
    (
      codigoasiento, 
      fecha, 
      referencia, 
      concepto, 
      origen, 
      usuariocreacion, 
      fechacreacion
    ) 
    VALUES 
    (
      codigoasiento,
      fechamovimiento,
      referencia, 
      concepto,
      'Entregas', 
      sUsuario, 
      NOW(3)
    );
   
   -- obtenemos el ultimo ID insertado
    SET libros_diariosid=(select LAST_INSERT_ID());
    
    -- Actualizamos el secuencial de libros diarios
    call SP_Actualiza_Secuencias_Internas('LIBRODIARIO');

    -- Ponemos que gravo la cabecera
    SET gravocabecera=TRUE;

  END IF;

-- INSERTAMOS LOS DETALLES
SET valor = round(valor,2);
INSERT INTO libros_diarios_detalles
( 	
libros_diariosid,	
codigocontable,	
centros_costosid,	
referencia,	
concepto,	
importe
)
VALUES
( 
libros_diariosid,	
codigocontable,	
centros_costosid,	
referencia,	
concepto,	
valor
 );

-- Toma la primer cuenta del asiento contable
IF cuenta_fija=0 THEN 
SET cuenta_fija = (select LAST_INSERT_ID());
END IF;

END LOOP;

CALL SP_Contabiliza_Verificar_Asiento(libros_diariosid,verificado);


-- Cuadramos el asiento contable si esta descuadrado
IF diferencia<0.11 AND diferencia>-0.11 AND diferencia<>0  THEN
UPDATE libros_diarios_detalles
SET
libros_diarios_detalles.importe = libros_diarios_detalles.importe-diferencia
WHERE
libros_diarios_detalles.libros_diarios_detallesid = cuenta_fija;
SET diferencia=0;
END IF;

-- Verificamos si el asiento esta cuadrado
IF diferencia<>0 THEN
SET verificado=0;
END IF;

-- Actualizamos el libro diario
SET debe = Round(debe,2);
SET haber = Round(haber,2);
UPDATE 
libros_diarios
SET
libros_diarios.debito = debe,
libros_diarios.credito = haber,
libros_diarios.mayorizado = verificado,
libros_diarios.verificado = verificado,
libros_diarios.fechamodificacion = libros_diarios.fechamodificacion
WHERE
libros_diarios.libros_diariosid = libros_diariosid;


-- Actualizamos el ID del libro diario a el movimiento de Caja
UPDATE 
entregas 
SET 
entregas.asientocontable = libros_diariosid,
entregas.fechamodificacion = entregas.fechamodificacion
WHERE 
entregas.asientocontable = 0 
AND entregas.entregasid =nDocumentoid;

-- Finalizamos la transaccion
COMMIT;

-- Cerramos el Cursor
CLOSE Datos_Asiento;

-- Devolvemos el ID del Asiento Contable
select libros_diariosid;

END
;;
delimiter ;

-- ----------------------------
-- Procedure structure for SP_Contabiliza_Facturacion_Agrupado
-- ----------------------------
DROP PROCEDURE IF EXISTS `SP_Contabiliza_Facturacion_Agrupado`;
delimiter ;;
CREATE PROCEDURE `SP_Contabiliza_Facturacion_Agrupado`(IN dFechaDesde DATE, IN dFechaHasta DATE, IN sCCIvaVentas VARCHAR(255), IN sCCIceVentas VARCHAR(255),IN ccPropinaVentas VARCHAR(255), IN ccAnticipoVentas VARCHAR(255),IN ccInteresesDiferidos VARCHAR(255), IN sUsuario VARCHAR(25))
  MODIFIES SQL DATA 
BEGIN

-- Declaramos variables de Cursor
DECLARE termino INT DEFAULT FALSE;
-- DECLARE fechamovimiento date;
DECLARE usuariocreacion varchar(25);
DECLARE centros_costosid int(11);
DECLARE ccentros_costosid int(11);
DECLARE concepto varchar(200);
DECLARE referencia varchar(15);
DECLARE valor decimal(16,8) DEFAULT 0;
DECLARE codigocontable varchar(30);
DECLARE codigoasiento varchar(10);
DECLARE gravocabecera INT DEFAULT FALSE;
DECLARE libros_diariosid bigint DEFAULT 0;
DECLARE debe  decimal(16,8) DEFAULT 0;
DECLARE haber decimal(16,8) DEFAULT 0;
DECLARE diferencia decimal(12,2) DEFAULT 0;
DECLARE diferencia2 decimal(12,2) DEFAULT 0;
DECLARE nregistros INT DEFAULT FALSE;
DECLARE VCuadrarH  decimal(12,2) DEFAULT 0;
DECLARE VCuadrarD  decimal(12,2) DEFAULT 0;
DECLARE diferenciacabecera decimal(12,8) DEFAULT 0;
DECLARE verificado INT DEFAULT TRUE;
DECLARE cuenta_fija bigint DEFAULT 0;
DECLARE cuenta_fija2 bigint DEFAULT 0;


DECLARE Datos_Centro CURSOR FOR 
SELECT
facturas_detalles.centros_costosid AS ccentros_costosid

FROM
facturas
INNER JOIN
facturas_detalles
ON
(facturas.facturasid = facturas_detalles.facturasid AND facturas_detalles.anulado = 0)
WHERE
facturas.asientocontable = 0
AND DATE(facturas.emision) BETWEEN dFechaDesde AND dFechaHasta
GROUP BY
facturas_detalles.centros_costosid
ORDER BY
facturas_detalles.centros_costosid ASC;



DECLARE Datos_Asiento CURSOR FOR

SELECT -- query de los productos
facturas_detalles.centros_costosid AS centros_costosid,

ROUND(SUM(	CASE	WHEN facturas.sri_documentoscodigo = '04' THEN
(ROUND((facturas_detalles.cantidad*facturas_detalles.precio),8)
-((round((facturas_detalles.cantidad*facturas_detalles.precio),8)*facturas_detalles.descuento/100)))
ELSE 
-(ROUND((facturas_detalles.cantidad*facturas_detalles.precio),8)
-((round((facturas_detalles.cantidad*facturas_detalles.precio),8)*facturas_detalles.descuento/100)))END),8) AS valor,

productos.cuentacontable_ventas AS codigocontable
FROM
facturas
INNER JOIN
(facturas_detalles
INNER JOIN
(productos
) ON (facturas_detalles.productosid = productos.productosid and facturas_detalles.anulado = 0)
)ON (facturas.facturasid = facturas_detalles.facturasid AND facturas_detalles.anulado = 0)
WHERE
facturas.asientocontable = 0
AND DATE(facturas.emision) BETWEEN dFechaDesde AND dFechaHasta
GROUP BY
facturas_detalles.centros_costosid,
productos.cuentacontable_ventas
HAVING
ROUND(SUM(	CASE	WHEN facturas.sri_documentoscodigo = '04' THEN
(ROUND((facturas_detalles.cantidad*facturas_detalles.precio),8)
-((round((facturas_detalles.cantidad*facturas_detalles.precio),8)*facturas_detalles.descuento/100)))
ELSE 
-(ROUND((facturas_detalles.cantidad*facturas_detalles.precio),8)
-((round((facturas_detalles.cantidad*facturas_detalles.precio),8)*facturas_detalles.descuento/100)))END),8)<>0

  UNION
SELECT -- query del iva
facturas.centros_costosid AS centros_costosid,
SUM(ROUND(CASE WHEN facturas.sri_documentoscodigo = '04' THEN (facturas.total_iva + facturas.total_iva2) ELSE -(facturas.total_iva + facturas.total_iva2) END,3)) AS valor,
  sCCIvaVentas AS codigocontable
FROM
facturas 
WHERE
facturas.asientocontable = 0
AND (facturas.total_iva <> 0  OR facturas.total_iva2 <> 0)
AND DATE(facturas.emision) BETWEEN dFechaDesde AND dFechaHasta
GROUP BY
facturas.centros_costosid
HAVING
SUM(CASE WHEN facturas.sri_documentoscodigo = '04' THEN (facturas.total_iva + facturas.total_iva2) ELSE -(facturas.total_iva + facturas.total_iva2) END)<>0

UNION
-- query del interes
SELECT 
facturas.centros_costosid AS centros_costosid,
SUM(CASE WHEN facturas.sri_documentoscodigo = '04' THEN (facturas.interes) ELSE -(facturas.interes) END) AS valor,
  ccInteresesDiferidos AS codigocontable
FROM
facturas 
WHERE
facturas.asientocontable = 0
AND facturas.interes <> 0
AND DATE(facturas.emision) BETWEEN dFechaDesde AND dFechaHasta
GROUP BY
facturas.centros_costosid
HAVING
SUM(CASE WHEN facturas.sri_documentoscodigo = '04' THEN facturas.interes ELSE -facturas.interes END)<>0

UNION

SELECT -- query pago con caja: efectivo, tarjeta, cheque
movcaja.centros_costosid AS centros_costosid,
SUM(movcaja.importe) AS valor,
  cajas.codigocontable AS codigocontable
FROM
cajas
INNER JOIN
(movcaja
)ON 	cajas.cajasid = movcaja.cajasid
WHERE
movcaja.origen = 'Facturacion'
AND movcaja.asientocontable = 0
AND DATE(movcaja.fechamovimiento) BETWEEN dFechaDesde AND dFechaHasta
AND movcaja.forma_pago_empresaid IN (1,3,4,8,11)
GROUP BY
cajas.codigocontable,
movcaja.centros_costosid
HAVING
SUM(movcaja.importe)<>0

UNION
SELECT 
cuentasporcobrar.centros_costosid AS centros_costosid,
-SUM(cuentasporcobrar.importe) AS valor,
bancos.codigocontable AS codigocontable
FROM
bancos
INNER JOIN
cuentasporcobrar
ON bancos.bancosid = cuentasporcobrar.bancosid
WHERE
cuentasporcobrar.origen = 'Facturacion'
AND DATE(cuentasporcobrar.emision) BETWEEN dFechaDesde AND dFechaHasta
AND cuentasporcobrar.forma_pago_empresaid IN (5)
AND cuentasporcobrar.tipo = 'AB'
AND cuentasporcobrar.asientocontable = 0
GROUP BY
bancos.codigocontable,
cuentasporcobrar.centros_costosid
HAVING
SUM(cuentasporcobrar.importe)<>0

UNION

-- cuando importe es > sale codigo contable del cliente

SELECT cxc.centros_costosid,SUM(cxc.valor),cxc.codigocontable

FROM
(SELECT 
cuentasporcobrar.centros_costosid AS centros_costosid,
sum(cuentasporcobrar.importe)  AS valor,
clientes.codigocontable AS codigocontable
FROM
cuentasporcobrar,
facturas,
clientes
WHERE
facturas.clientesid = clientes.clientesid
and cuentasporcobrar.asientocontable = 0
AND cuentasporcobrar.origen = 'Facturacion'
AND cuentasporcobrar.documentosid = facturas.facturasid AND cuentasporcobrar.tipo NOT IN ('NC','ND')
AND cuentasporcobrar.relaciondocumentoid =0
AND DATE(facturas.emision) BETWEEN dFechaDesde AND dFechaHasta
GROUP BY
cuentasporcobrar.centros_costosid,
clientes.codigocontable,
facturas.facturasid
HAVING SUM(cuentasporcobrar.importe) >0) AS cxc
GROUP BY
cxc.centros_costosid,
cxc.codigocontable

UNION

SELECT -- cuando importe es > sale codigo contable del cliente
cuentasporcobrar.centros_costosid AS centros_costosid,
SUM(cuentasporcobrar.importe) AS valor,
clientes.codigocontable AS codigocontable
FROM
cuentasporcobrar,
facturas,
clientes
WHERE
facturas.clientesid = clientes.clientesid
and cuentasporcobrar.asientocontable = 0
AND cuentasporcobrar.origen = 'Facturacion'
AND cuentasporcobrar.relaciondocumentoid = facturas.facturasid	AND cuentasporcobrar.tipo IN ('NC','ND','AB','IR')
AND DATE(facturas.emision) BETWEEN dFechaDesde AND dFechaHasta
GROUP BY
cuentasporcobrar.centros_costosid,
clientes.codigocontable
HAVING SUM(cuentasporcobrar.importe) >0 

UNION
-- cuando importe es < sale codigo contable del anticipo
SELECT
facturas.centros_costosid AS centros_costosid,
-(SUM(facturas.anticipo)) AS valor,
ccAnticipoVentas AS codigocontable
FROM
facturas
WHERE
facturas.asientocontable = 0
AND DATE(facturas.emision) BETWEEN dFechaDesde AND dFechaHasta
GROUP BY
facturas.centros_costosid

HAVING SUM(facturas.anticipo)<>0 

UNION
SELECT -- cuando importe es < sale codigo contable del cliente
cuentasporcobrar.centros_costosid AS centros_costosid,
SUM(cuentasporcobrar.importe) AS valor,
ccAnticipoVentas AS codigocontable
FROM
cuentasporcobrar,
facturas,
clientes
WHERE
facturas.clientesid = clientes.clientesid
and cuentasporcobrar.asientocontable = 0
AND cuentasporcobrar.origen = 'Facturacion'
AND cuentasporcobrar.relaciondocumentoid = facturas.facturasid	AND cuentasporcobrar.tipo IN ('NC','ND','AB')
AND facturas.sri_documentoscodigo  not IN (04)
AND DATE(facturas.emision) BETWEEN dFechaDesde AND dFechaHasta
GROUP BY
cuentasporcobrar.centros_costosid,
clientes.codigocontable
HAVING SUM(cuentasporcobrar.importe) <>0
UNION

SELECT -- para solo nc 
cuentasporcobrar.centros_costosid AS centros_costosid,
SUM(cuentasporcobrar.importe) AS valor,
clientes.codigocontable AS codigocontable
FROM
cuentasporcobrar,
facturas,
clientes
WHERE
facturas.clientesid = clientes.clientesid
and cuentasporcobrar.asientocontable = 0
AND cuentasporcobrar.origen = 'Facturacion'
AND cuentasporcobrar.relaciondocumentoid = facturas.facturasid	AND cuentasporcobrar.tipo IN ('NC','ND','AB')
AND facturas.sri_documentoscodigo  IN (04)
AND DATE(facturas.emision) BETWEEN dFechaDesde AND dFechaHasta
GROUP BY
cuentasporcobrar.centros_costosid,
clientes.codigocontable
HAVING SUM(cuentasporcobrar.importe) <0

UNION
SELECT
facturas.centros_costosid AS centros_costosid,
SUM(CASE WHEN facturas.sri_documentoscodigo = '04' THEN -(facturas_retenciones.valor) ELSE (facturas_retenciones.valor) END) AS valor,
facturas_retenciones.codigocontable AS codigocontable
FROM
facturas 
INNER JOIN
(facturas_retenciones
) ON 	facturas.facturasid = facturas_retenciones.documentosid
WHERE
facturas_retenciones.origen = 'FACTURACION'
AND facturas.asientocontable = 0
AND facturas.total <> 0
AND DATE(facturas.emision) BETWEEN dFechaDesde AND dFechaHasta
GROUP BY
facturas_retenciones.codigocontable,
facturas.centros_costosid
HAVING
ROUND(SUM(CASE WHEN facturas.sri_documentoscodigo = '04' THEN -facturas_retenciones.valor ELSE facturas_retenciones.valor END),8)<>0

UNION	
SELECT
facturas.centros_costosid AS CentroCostoID,
SUM(CASE WHEN facturas.sri_documentoscodigo = '04' THEN (facturas.total_ice) ELSE -(facturas.total_ice) END) AS valor,
sCCIceVentas AS codigocontable
FROM
facturas 
WHERE
facturas.asientocontable = 0
AND facturas.total_ice <> 0
AND DATE(facturas.emision) BETWEEN dFechaDesde AND dFechaHasta
GROUP BY
facturas.centros_costosid
HAVING
SUM(CASE WHEN facturas.sri_documentoscodigo = '04' THEN facturas.total_ice ELSE -facturas.total_ice END)<>0
-- propina
UNION	
SELECT
facturas.centros_costosid AS CentroCostoID,
SUM(CASE WHEN facturas.sri_documentoscodigo = '04' THEN (facturas.propina) ELSE -(facturas.propina) END) AS valor,
ccPropinaVentas AS codigocontable
FROM
facturas 
WHERE
facturas.asientocontable = 0
AND facturas.propina <> 0
AND DATE(facturas.emision) BETWEEN dFechaDesde AND dFechaHasta
GROUP BY
facturas.centros_costosid
HAVING
SUM(CASE WHEN facturas.sri_documentoscodigo = '04' THEN facturas.propina ELSE -facturas.propina END)<>0;


-- Controlamos si hubo error
DECLARE exit handler FOR SQLEXCEPTION, SQLWARNING
  BEGIN
  	SHOW WARNINGS limit 1;
    ROLLBACK;
    RESIGNAL;
  END;

-- Declaramos el control de salida del loop
DECLARE CONTINUE HANDLER FOR NOT FOUND SET termino = TRUE;


-- Iniciamos la Transaccion
START TRANSACTION;

-- Abrimos el Cursor
OPEN Datos_Centro;

-- Leeemos el Cursor
read_loopc: LOOP
FETCH Datos_Centro INTO ccentros_costosid;

IF termino THEN
LEAVE read_loopc;
END IF;

OPEN Datos_Asiento;
read_loop: LOOP
FETCH Datos_Asiento INTO centros_costosid, valor, codigocontable;

-- Verificamos si no hay mas registros
IF termino THEN
set termino = FALSE;
LEAVE read_loop;
END IF;

IF ccentros_costosid = centros_costosid THEN
SET diferencia = ROUND(diferencia+(Round(valor,2)),2);


-- INSERTAMOS LA CABECERA DEL ASIENTO
  IF gravocabecera=FALSE THEN
    -- Optenemos el nuevo secuencial
    call SP_Consulta_Secuencias_Internas('LIBRODIARIO',codigoasiento);
  
    -- Insertamos Registro Cabecera
    INSERT INTO libros_diarios 
    (
      codigoasiento, 
      fecha, 
      referencia, 
      concepto, 
      origen, 
      usuariocreacion, 
      fechacreacion
    ) 
    VALUES 
    (
      codigoasiento,
      dFechaHasta,
      codigoasiento, 
      CONCAT('Facturacion del ',DATE_FORMAT(dFechaDesde,"%d-%m-%Y"),' al ',DATE_FORMAT(dFechaHasta,"%d-%m-%Y")),
      'Facturacion', 
      sUsuario, 
      NOW()
    );
   
   -- obtenemos el ultimo ID insertado
    SET libros_diariosid=(select LAST_INSERT_ID());
    
    -- Actualizamos el secuencial de libros diarios
    call SP_Actualiza_Secuencias_Internas('LIBRODIARIO');

    -- Ponemos que gravo la cabecera
    SET gravocabecera=TRUE;

  END IF;

-- INSERTAMOS LOS DETALLES
SET valor = Round(valor,2);
INSERT INTO libros_diarios_detalles
( 	
libros_diariosid,	
codigocontable,	
centros_costosid,	
referencia,	
concepto,	
importe
)
VALUES
( 
libros_diariosid,	
codigocontable,	
centros_costosid,	
codigoasiento,	
CONCAT('Facturacion del ',DATE_FORMAT(dFechaDesde,"%d-%m-%Y"),' al ',DATE_FORMAT(dFechaHasta,"%d-%m-%Y")),
valor
 );

-- Toma la primer cuenta del asiento contable
IF cuenta_fija=0 THEN 
SET cuenta_fija = (select LAST_INSERT_ID());
END IF;
END IF;
END LOOP;
CLOSE Datos_Asiento;

IF diferencia <> 0 AND diferencia <= 0.11 AND diferencia>=-0.11  THEN
-- Cuadramos el asiento contable si esta descuadrado
UPDATE libros_diarios_detalles
SET
libros_diarios_detalles.importe = libros_diarios_detalles.importe-diferencia
WHERE
libros_diarios_detalles.libros_diarios_detallesid = cuenta_fija;
ELSE
SET diferencia2 = diferencia2 + diferencia;
SET cuenta_fija2 = (cuenta_fija);
IF diferencia2 <> 0 AND diferencia2 <= 0.50 AND diferencia2>=-0.50  THEN
UPDATE libros_diarios_detalles
SET
libros_diarios_detalles.importe = libros_diarios_detalles.importe-diferencia2
WHERE
libros_diarios_detalles.libros_diarios_detallesid = cuenta_fija2;
SET diferencia2=0;
SET cuenta_fija2=0;
END IF;

END IF ;
SET diferencia=0;
SET cuenta_fija =0;
END LOOP;


CALL SP_Contabiliza_Verificar_Asiento(libros_diariosid,verificado);

-- llenamos contando detalles 

-- set nregistros =(SELECT COUNT(facturas.facturasid) FROM facturas WHERE facturas.emision BETWEEN dFechaDesde AND dFechaHasta) ;

set VCuadrarH = (SELECT SUM(libros_diarios_detalles.importe) FROM libros_diarios_detalles WHERE libros_diarios_detalles.libros_diariosid = libros_diariosid AND libros_diarios_detalles.importe < 0);
set VCuadrarD = (SELECT SUM(libros_diarios_detalles.importe) FROM libros_diarios_detalles WHERE libros_diarios_detalles.libros_diariosid = libros_diariosid AND libros_diarios_detalles.importe > 0);

-- Cuadrar cabecera 
SET haber =ROUND(VCuadrarH,2);
SET debe = ROUND(VCuadrarD,2);
SET diferenciacabecera=ROUND(debe+haber,2);
IF debe <> haber AND  diferencia2 = 0 THEN
-- si debe esta desigual
IF  ABS(debe-diferenciacabecera) = haber THEN
SET debe = ABS(Round((debe-diferenciacabecera),2));
END IF;
-- si haber esta desigual
IF  ABS(haber-diferenciacabecera) = debe THEN
SET haber = ABS(Round((haber-diferenciacabecera),2));
END IF;

IF debe = haber THEN
  SET diferenciacabecera=0;
END IF;
END IF;

-- Verificamos si el asiento esta cuadrado
IF diferencia<>0 OR diferenciacabecera <> 0 THEN
SET verificado=0;
END IF;


-- Actualizamos el libro diario
SET debe = ROUND(ABS(debe),2);
SET haber = ROUND(ABS(haber),2);



UPDATE 
libros_diarios
SET
libros_diarios.debito = debe,
libros_diarios.credito = haber,
libros_diarios.mayorizado = verificado,
libros_diarios.verificado = verificado,
libros_diarios.fechamodificacion = libros_diarios.fechamodificacion
WHERE
libros_diarios.libros_diariosid = libros_diariosid;


-- Actualizamos el ID del libro diario a los movimientos de la factura
UPDATE
movcaja 
SET
movcaja.asientocontable=libros_diariosid,
movcaja.fechamodificacion=movcaja.fechamodificacion
WHERE
movcaja.asientocontable = 0
AND movcaja.origen = 'FACTURACION'
AND movcaja.fechamovimiento BETWEEN dFechaDesde AND dFechaHasta;
UPDATE
movbanco 
SET
movbanco.asientocontable=libros_diariosid,
movbanco.fechamodificacion=movbanco.fechamodificacion
WHERE
movbanco.asientocontable = 0
AND movbanco.fechamovimiento BETWEEN dFechaDesde AND dFechaHasta
AND movbanco.origen = 'FACTURACION';
UPDATE
cuentasporcobrar 
SET
cuentasporcobrar.asientocontable=libros_diariosid,
cuentasporcobrar.fechamodificacion = cuentasporcobrar.fechamodificacion
WHERE
cuentasporcobrar.origen = 'FACTURACION'
AND cuentasporcobrar.asientocontable = 0
AND cuentasporcobrar.emision BETWEEN dFechaDesde AND dFechaHasta;
UPDATE
facturas
SET
facturas.asientocontable=libros_diariosid,
facturas.fechamodificacion=facturas.fechamodificacion
WHERE
DATE(facturas.emision) BETWEEN dFechaDesde AND dFechaHasta
AND facturas.asientocontable = 0;

-- Cerramos el Cursor
CLOSE Datos_Centro;

-- Finalizamos la transaccion
COMMIT;


-- Devolvemos el ID del Asiento Contable
select libros_diariosid;

END
;;
delimiter ;

-- ----------------------------
-- Procedure structure for SP_Contabiliza_Facturacion_Individual
-- ----------------------------
DROP PROCEDURE IF EXISTS `SP_Contabiliza_Facturacion_Individual`;
delimiter ;;
CREATE PROCEDURE `SP_Contabiliza_Facturacion_Individual`(IN nDocumentoid BIGINT, IN CCIvaVentas VARCHAR(255), IN ccIceVentas VARCHAR(255),IN ccPropinaVentas VARCHAR(255), IN ccAnticipoVentas VARCHAR(255), IN ccInteresesDiferidos VARCHAR(255), IN sUsuario VARCHAR(25))
  MODIFIES SQL DATA 
BEGIN

-- Declaramos variables de Cursor
DECLARE termino INT DEFAULT FALSE;
DECLARE fechamovimiento date;
DECLARE usuariocreacion varchar(25);
DECLARE centros_costosid int(11);
DECLARE concepto varchar(200);
DECLARE referencia varchar(15);
DECLARE valor decimal(16,8) DEFAULT 0;
DECLARE codigocontable varchar(30);
DECLARE codigoasiento varchar(15);
DECLARE gravocabecera INT DEFAULT FALSE;
DECLARE libros_diariosid bigint DEFAULT 0;
DECLARE debe  decimal(16,8) DEFAULT 0;
DECLARE haber decimal(16,8) DEFAULT 0;
DECLARE diferencia decimal(12,2) DEFAULT 0;
DECLARE diferenciacabecera decimal(12,8) DEFAULT 0;
DECLARE verificado INT DEFAULT TRUE;
DECLARE cuenta_fija bigint DEFAULT 0;

DECLARE Datos_Asiento CURSOR FOR
SELECT
  DATE(facturas.emision) AS fechamovimiento,
facturas_detalles.centros_costosid AS centros_costosid,
  LEFT(facturas.concepto,200) AS concepto,
facturas.secuencial AS referencia,
ROUND(SUM(CASE	WHEN facturas.sri_documentoscodigo = '04' THEN
((facturas_detalles.cantidad*facturas_detalles.precio)-(facturas_detalles.cantidad*facturas_detalles.precio*facturas_detalles.descuento/100))
ELSE -((facturas_detalles.cantidad*facturas_detalles.precio)-(facturas_detalles.cantidad*facturas_detalles.precio*facturas_detalles.descuento/100))END),8) AS valor,
  productos.cuentacontable_ventas AS codigocontable
FROM
facturas
INNER JOIN
(facturas_detalles
INNER JOIN
(productos
) ON (facturas_detalles.productosid = productos.productosid AND facturas_detalles.anulado = 0)
)ON (facturas.facturasid = facturas_detalles.facturasid AND facturas_detalles.anulado = 0)
WHERE
facturas.asientocontable = 0
AND facturas.facturasid = nDocumentoid
GROUP BY
facturas_detalles.centros_costosid,
productos.cuentacontable_ventas
HAVING
SUM(	CASE	WHEN facturas.sri_documentoscodigo = '04' THEN	((facturas_detalles.cantidad*facturas_detalles.precio)-(facturas_detalles.cantidad*facturas_detalles.precio*facturas_detalles.descuento/100))
ELSE -((facturas_detalles.cantidad*facturas_detalles.precio)-(facturas_detalles.cantidad*facturas_detalles.precio*facturas_detalles.descuento/100))END)<>0

  UNION
SELECT
  DATE(facturas.emision) AS fechamovimiento,
facturas.centros_costosid AS centros_costosid,
  LEFT(facturas.concepto,200) AS concepto,
facturas.secuencial AS referencia,
  SUM(CASE WHEN facturas.sri_documentoscodigo = '04' THEN (facturas.total_iva + facturas.total_iva2) ELSE -(facturas.total_iva + facturas.total_iva2) END) AS valor,
CCIvaVentas AS codigocontable
FROM
facturas 
WHERE
facturas.asientocontable = 0
AND (facturas.total_iva <> 0  OR facturas.total_iva2 <> 0)
AND facturas.facturasid = nDocumentoid
GROUP BY
facturas.centros_costosid
HAVING
SUM(CASE WHEN facturas.sri_documentoscodigo = '04' THEN (facturas.total_iva + facturas.total_iva2) ELSE -(facturas.total_iva + facturas.total_iva2) END)<>0

UNION
-- interes
SELECT
  DATE(facturas.emision) AS fechamovimiento,
facturas.centros_costosid AS centros_costosid,
  LEFT(facturas.concepto,200) AS concepto,
facturas.secuencial AS referencia,
SUM(CASE WHEN facturas.sri_documentoscodigo = '04' THEN facturas.interes ELSE -facturas.interes END) AS valor,
ccInteresesDiferidos AS codigocontable
FROM
facturas 
WHERE
facturas.asientocontable = 0
AND facturas.interes <> 0
AND facturas.facturasid = nDocumentoid
GROUP BY
facturas.centros_costosid
HAVING
SUM(CASE WHEN facturas.sri_documentoscodigo = '04' THEN facturas.interes ELSE -facturas.interes END)<>0
UNION

SELECT
  DATE(movcaja.fechamovimiento) AS fechamovimiento,
movcaja.centros_costosid AS centros_costosid,
LEFT(movcaja.concepto,200) AS concepto,
movcaja.documentoorigen AS referencia,
SUM(movcaja.importe) AS valor,
  cajas.codigocontable AS codigocontable
FROM
cajas
INNER JOIN
(movcaja
)ON 	cajas.cajasid = movcaja.cajasid
WHERE
movcaja.origen = 'Facturacion'
AND movcaja.asientocontable = 0
AND movcaja.documentosid = nDocumentoid
AND movcaja.forma_pago_empresaid IN (1,3,4,8,11)
GROUP BY
cajas.codigocontable,
movcaja.centros_costosid
HAVING
SUM(movcaja.importe)<>0

UNION
SELECT
  DATE(cuentasporcobrar.emision) AS fechamovimiento,
cuentasporcobrar.centros_costosid AS centros_costosid,
  LEFT(cuentasporcobrar.concepto,200) AS concepto,
cuentasporcobrar.secuencial AS referencia,
-SUM(cuentasporcobrar.importe) AS valor,
bancos.codigocontable AS codigocontable
FROM
bancos
INNER JOIN
cuentasporcobrar
ON bancos.bancosid = cuentasporcobrar.bancosid
WHERE
cuentasporcobrar.origen = 'Facturacion'
AND cuentasporcobrar.documentosid = nDocumentoid
AND cuentasporcobrar.forma_pago_empresaid IN (5)
AND cuentasporcobrar.tipo = 'AB'
GROUP BY
bancos.codigocontable,
cuentasporcobrar.centros_costosid
HAVING
SUM(cuentasporcobrar.importe)<>0

UNION

SELECT -- cuando importe es > sale codigo contable del cliente
DATE(cuentasporcobrar.emision) AS fechamovimiento,
cuentasporcobrar.centros_costosid AS centros_costosid,
LEFT(cuentasporcobrar.concepto,200) AS concepto,
cuentasporcobrar.secuencial AS referencia,
ROUND(SUM(cuentasporcobrar.importe),8) AS valor,
clientes.codigocontable AS codigocontable
FROM
cuentasporcobrar,
facturas,
clientes
WHERE
facturas.clientesid = clientes.clientesid
AND cuentasporcobrar.asientocontable = 0
and (cuentasporcobrar.documentosid = facturas.facturasid AND cuentasporcobrar.tipo NOT IN ('NC','ND'))
AND cuentasporcobrar.relaciondocumentoid =0
AND cuentasporcobrar.origen = 'Facturacion'
AND facturas.facturasid = nDocumentoid
GROUP BY
cuentasporcobrar.centros_costosid,
clientes.codigocontable
HAVING ROUND(SUM(cuentasporcobrar.importe),8) >0

UNION

SELECT -- cuando importe es > sale codigo contable del cliente
DATE(cuentasporcobrar.emision) AS fechamovimiento,
cuentasporcobrar.centros_costosid AS centros_costosid,
LEFT(cuentasporcobrar.concepto,200) AS concepto,
cuentasporcobrar.secuencial AS referencia,
ROUND(SUM(cuentasporcobrar.importe),8) AS valor,
clientes.codigocontable AS codigocontable
FROM
cuentasporcobrar,
facturas,
clientes
WHERE
facturas.clientesid = clientes.clientesid
AND cuentasporcobrar.asientocontable = 0
AND	(cuentasporcobrar.relaciondocumentoid = facturas.facturasid	AND cuentasporcobrar.tipo IN ('NC','ND','AB','IR'))
AND cuentasporcobrar.origen = 'Facturacion'
AND facturas.facturasid = nDocumentoid
GROUP BY
cuentasporcobrar.centros_costosid,
clientes.codigocontable
HAVING ROUND(SUM(cuentasporcobrar.importe),8)>0

UNION

SELECT -- cuando importe es < sale codigo contable anticipo
DATE(cuentasporcobrar.emision) AS fechamovimiento,
cuentasporcobrar.centros_costosid AS centros_costosid,
LEFT(cuentasporcobrar.concepto,200) AS concepto,
cuentasporcobrar.secuencial AS referencia,
ROUND(SUM(cuentasporcobrar.importe),8) AS valor,
ccAnticipoVentas AS codigocontable
FROM
cuentasporcobrar,
facturas,
clientes
WHERE
facturas.clientesid = clientes.clientesid
AND cuentasporcobrar.asientocontable = 0
and (cuentasporcobrar.documentosid = facturas.facturasid AND cuentasporcobrar.tipo NOT IN ('NC','ND'))
AND cuentasporcobrar.origen = 'Facturacion'
AND facturas.facturasid = nDocumentoid
AND (
        cuentasporcobrar.relaciondocumentoid = 0
        OR (
            cuentasporcobrar.relaciondocumentoid > 0
            AND EXISTS (
                SELECT *
                FROM facturas
                WHERE facturas.facturasid = cuentasporcobrar.relaciondocumentoid
                AND facturas.sri_documentoscodigo NOT IN ('05')
            )
        )
    )
GROUP BY
cuentasporcobrar.centros_costosid,
clientes.codigocontable
HAVING ROUND(SUM(cuentasporcobrar.importe),8) <0

UNION

SELECT -- cuando importe es > sale codigo contable anticipo
DATE(cuentasporcobrar.emision) AS fechamovimiento,
cuentasporcobrar.centros_costosid AS centros_costosid,
LEFT(cuentasporcobrar.concepto,200) AS concepto,
cuentasporcobrar.secuencial AS referencia,
ROUND(SUM(cuentasporcobrar.importe),8) AS valor,
ccAnticipoVentas AS codigocontable
FROM
cuentasporcobrar,
facturas,
clientes
WHERE
facturas.clientesid = clientes.clientesid
AND cuentasporcobrar.asientocontable = 0
AND	(cuentasporcobrar.relaciondocumentoid = facturas.facturasid	AND cuentasporcobrar.tipo IN ('NC','ND','AB'))
AND facturas.sri_documentoscodigo  not IN (04)
AND cuentasporcobrar.origen = 'Facturacion'
AND facturas.facturasid = nDocumentoid
GROUP BY
cuentasporcobrar.centros_costosid,
clientes.codigocontable
HAVING ROUND(SUM(cuentasporcobrar.importe),8) < 0
UNION

SELECT -- solo para nc 
DATE(cuentasporcobrar.emision) AS fechamovimiento,
cuentasporcobrar.centros_costosid AS centros_costosid,
LEFT(cuentasporcobrar.concepto,200) AS concepto,
cuentasporcobrar.secuencial AS referencia,
ROUND(SUM(cuentasporcobrar.importe),8) AS valor,
clientes.codigocontable AS codigocontable
FROM
cuentasporcobrar,
facturas,
clientes
WHERE
facturas.clientesid = clientes.clientesid
AND cuentasporcobrar.asientocontable = 0
AND	(cuentasporcobrar.relaciondocumentoid = facturas.facturasid	AND cuentasporcobrar.tipo IN ('NC','ND','AB'))
AND facturas.sri_documentoscodigo  IN (04)
AND cuentasporcobrar.origen = 'Facturacion'
AND facturas.facturasid = nDocumentoid
GROUP BY
cuentasporcobrar.centros_costosid,
clientes.codigocontable
HAVING ROUND(SUM(cuentasporcobrar.importe),8) < 0


UNION
SELECT
DATE(facturas.emision) AS fechamovimiento,
facturas.centros_costosid AS centros_costosid,
LEFT(facturas.concepto,200) AS concepto,
facturas.secuencial AS referencia,
SUM(CASE WHEN facturas.sri_documentoscodigo = '04' THEN -(facturas_retenciones.valor) ELSE (facturas_retenciones.valor) END) AS valor,
facturas_retenciones.codigocontable AS codigocontable
FROM
facturas 
INNER JOIN
(facturas_retenciones
) ON 	facturas.facturasid = facturas_retenciones.documentosid
WHERE
facturas_retenciones.origen = 'Facturacion'
AND facturas.asientocontable = 0
AND facturas.total <> 0
AND facturas.facturasid = nDocumentoid
GROUP BY
facturas_retenciones.codigocontable,
facturas.centros_costosid
HAVING
SUM(CASE WHEN facturas.sri_documentoscodigo = '04' THEN -facturas_retenciones.valor ELSE facturas_retenciones.valor END)<>0

UNION	
SELECT
DATE(facturas.emision) AS fechamovimiento,
facturas.centros_costosid AS centros_costosid,
LEFT(facturas.concepto,200) AS concepto,
facturas.secuencial AS referencia,
SUM(CASE WHEN facturas.sri_documentoscodigo = '04' THEN (facturas.total_ice) ELSE -(facturas.total_ice) END) AS valor,
ccIceVentas AS codigocontable
FROM
facturas 
WHERE
facturas.asientocontable = 0
AND facturas.total_ice <> 0
AND facturas.facturasid = nDocumentoid
GROUP BY
facturas.centros_costosid
-- propina
UNION	
SELECT
DATE(facturas.emision) AS fechamovimiento,
facturas.centros_costosid AS centros_costosid,
LEFT(facturas.concepto,200) AS concepto,
facturas.secuencial AS referencia,
SUM(CASE WHEN facturas.sri_documentoscodigo = '04' THEN (facturas.propina) ELSE -(facturas.propina) END) AS valor,
ccPropinaVentas AS codigocontable
FROM
facturas 
WHERE
facturas.asientocontable = 0
AND facturas.propina <> 0
AND facturas.facturasid = nDocumentoid
GROUP BY
facturas.centros_costosid;

-- Controlamos si hubo error
DECLARE exit handler FOR SQLEXCEPTION, SQLWARNING
  BEGIN
  	SHOW WARNINGS limit 1;
    ROLLBACK;
    RESIGNAL;
  END;

-- Declaramos el control de salida del loop
DECLARE CONTINUE HANDLER FOR NOT FOUND SET termino = TRUE;

-- Abrimos el Cursor
OPEN Datos_Asiento;

-- Iniciamos la Transaccion
START TRANSACTION;

-- Leeemos el Cursor
read_loop: LOOP
FETCH Datos_Asiento INTO fechamovimiento,centros_costosid, concepto, referencia, valor, codigocontable;

-- Verificamos si no hay mas registros
IF termino THEN
LEAVE read_loop;
END IF;

SET diferencia = ROUND(diferencia+(Round(valor,2)),2);
-- Sumamos valores de debe y haber
IF valor<0 THEN
  SET haber = (haber + (Abs((valor))));
ELSE
  SET debe  = (debe + (Abs((valor))));
END IF;

-- INSERTAMOS LA CABECERA DEL ASIENTO
  IF gravocabecera=FALSE THEN
    -- Optenemos el nuevo secuencial
    call SP_Consulta_Secuencias_Internas('LIBRODIARIO',codigoasiento);
  
    -- Insertamos Registro Cabecera
    INSERT INTO libros_diarios 
    (
      codigoasiento, 
      fecha, 
      referencia, 
      concepto, 
      origen, 
      usuariocreacion, 
      fechacreacion
    ) 
    VALUES 
    (
      codigoasiento,
      fechamovimiento,
      referencia, 
      concepto,
      'Facturacion', 
      sUsuario, 
      NOW(3)
    );
   
   -- obtenemos el ultimo ID insertado
    SET libros_diariosid=(select LAST_INSERT_ID());
    
    -- Actualizamos el secuencial de libros diarios
    call SP_Actualiza_Secuencias_Internas('LIBRODIARIO');

    -- Ponemos que gravo la cabecera
    SET gravocabecera=TRUE;

  END IF;

-- INSERTAMOS LOS DETALLES
SET valor = Round(valor,2);
INSERT INTO libros_diarios_detalles
( 	
libros_diariosid,	
codigocontable,	
centros_costosid,	
referencia,	
concepto,	
importe
)
VALUES
( 
libros_diariosid,	
codigocontable,	
centros_costosid,	
referencia,	
concepto,	
valor
 );

-- Toma la primer cuenta del asiento contable
IF cuenta_fija=0 THEN 
SET cuenta_fija = (select LAST_INSERT_ID());
END IF;

END LOOP;

CALL SP_Contabiliza_Verificar_Asiento(libros_diariosid,verificado);


-- Cuadramos el asiento contable si esta descuadrado
IF diferencia<0.11 AND diferencia>-0.11 AND diferencia<>0  THEN
UPDATE libros_diarios_detalles
SET
libros_diarios_detalles.importe = libros_diarios_detalles.importe-diferencia
WHERE
libros_diarios_detalles.libros_diarios_detallesid = cuenta_fija;


-- Cuadrar cabecera 
set haber =ROUND((haber*-1),2);
SET diferenciacabecera=ROUND(debe+haber,2);
IF debe <> haber THEN
-- si debe esta desigual
IF  ABS(debe-diferenciacabecera) = haber THEN
SET debe = ABS(Round((debe-diferenciacabecera),2));
END IF;
-- si haber esta desigual
IF  ABS(haber-diferenciacabecera) = debe THEN
SET haber = ABS(Round((haber-diferenciacabecera),2));
END IF;

SET diferenciacabecera=0;
END IF;

SET diferencia=0;
END IF;


-- Verificamos si el asiento esta cuadrado
IF diferencia<>0 THEN
SET verificado=0;
END IF;

-- Actualizamos el libro diario
SET debe = Round(debe,2);
SET haber = Round(haber,2);
UPDATE 
libros_diarios
SET
libros_diarios.debito = debe,
libros_diarios.credito = haber,
libros_diarios.mayorizado = verificado,
libros_diarios.verificado = verificado,
libros_diarios.fechamodificacion = libros_diarios.fechamodificacion
WHERE
libros_diarios.libros_diariosid = libros_diariosid;


-- Actualizamos el ID del libro diario a el movimiento de Caja
UPDATE
movcaja 
SET
movcaja.asientocontable=libros_diariosid,
movcaja.fechamodificacion=movcaja.fechamodificacion
WHERE
movcaja.asientocontable = 0
AND movcaja.origen = 'Facturacion'
AND movcaja.documentosid = nDocumentoid;

UPDATE
movbanco 
SET
movbanco.asientocontable=libros_diariosid,
movbanco.fechamodificacion=movbanco.fechamodificacion
WHERE
movbanco.asientocontable = 0
AND movbanco.documentosid = nDocumentoid
AND movbanco.origen = 'Facturacion';

UPDATE
cuentasporcobrar 
SET
cuentasporcobrar.asientocontable=libros_diariosid,
cuentasporcobrar.fechamodificacion = cuentasporcobrar.fechamodificacion
WHERE
cuentasporcobrar.origen = 'Facturacion'
AND cuentasporcobrar.asientocontable = 0
AND ((cuentasporcobrar.documentosid = nDocumentoid and cuentasporcobrar.relaciondocumentoid = 0) or (cuentasporcobrar.relaciondocumentoid = nDocumentoid) );

UPDATE
facturas
SET
facturas.asientocontable=libros_diariosid,
facturas.fechamodificacion=facturas.fechamodificacion
WHERE
facturas.facturasid = nDocumentoid
AND facturas.asientocontable = 0;

-- Finalizamos la transaccion
COMMIT;

-- Cerramos el Cursor
CLOSE Datos_Asiento;

-- Devolvemos el ID del Asiento Contable
select libros_diariosid;

END
;;
delimiter ;

-- ----------------------------
-- Procedure structure for SP_Contabiliza_Garantias_Agrupado
-- ----------------------------
DROP PROCEDURE IF EXISTS `SP_Contabiliza_Garantias_Agrupado`;
delimiter ;;
CREATE PROCEDURE `SP_Contabiliza_Garantias_Agrupado`(IN dFechaDesde DATE, IN dFechaHasta DATE, IN sUsuario VARCHAR(25))
  MODIFIES SQL DATA 
BEGIN

-- Declaramos variables de Cursor
DECLARE termino INT DEFAULT FALSE;
-- DECLARE fechamovimiento date;
DECLARE usuariocreacion varchar(25);
DECLARE centros_costosid int(11);
DECLARE concepto varchar(200);
DECLARE referencia varchar(15);
DECLARE valor decimal(16,8) DEFAULT 0;
DECLARE codigocontable varchar(30);
DECLARE codigoasiento varchar(10);
DECLARE gravocabecera INT DEFAULT FALSE;
DECLARE libros_diariosid bigint DEFAULT 0;
DECLARE debe  decimal(16,8) DEFAULT 0;
DECLARE haber decimal(16,8) DEFAULT 0;
DECLARE diferencia decimal(12,2) DEFAULT 0;
DECLARE verificado INT DEFAULT TRUE;
DECLARE cuenta_fija bigint DEFAULT 0;

DECLARE Datos_Asiento CURSOR FOR
SELECT 
garantias_repuestos.centros_costosid AS centros_costosid,
SUM((garantias_repuestos.costo)*(garantias_repuestos.cantidad)) AS valor, 
productos.cuentacontable_costo AS codigocontable
FROM garantias_seguimientos
INNER JOIN (garantias_repuestos
INNER JOIN ( productos) ON garantias_repuestos.productosid = productos.productosid
) ON garantias_repuestos.garantias_seguimientosid = garantias_seguimientos.garantias_seguimientosid
WHERE 	
garantias_seguimientos.asientocontable = 0
AND productos.servicio =0 
AND productos.bien =0 	
AND   DATE(garantias_seguimientos.fecha) BETWEEN dFechaDesde AND dFechaHasta
GROUP BY 
productos.cuentacontable_costo
 HAVING
 SUM((garantias_repuestos.costo)*(garantias_repuestos.cantidad))<>0

UNION
SELECT 
garantias_repuestos.centros_costosid AS centros_costosid,
-SUM((garantias_repuestos.costo)*(garantias_repuestos.cantidad)) AS valor,
 productos.cuentacontable_inventarios AS codigocontable
FROM garantias_seguimientos
INNER JOIN (garantias_repuestos
INNER JOIN ( productos) ON garantias_repuestos.productosid = productos.productosid
) ON garantias_repuestos.garantias_seguimientosid = garantias_seguimientos.garantias_seguimientosid
WHERE 	
garantias_seguimientos.asientocontable = 0
AND productos.servicio =0 
AND productos.bien =0 		
AND   DATE(garantias_seguimientos.fecha) BETWEEN dFechaDesde AND dFechaHasta
GROUP BY 
productos.cuentacontable_inventarios
  HAVING
SUM((garantias_repuestos.costo)*(garantias_repuestos.cantidad))<>0;

-- Controlamos si hubo error
DECLARE exit handler FOR SQLEXCEPTION, SQLWARNING
  BEGIN
  	SHOW WARNINGS limit 1;
    ROLLBACK;
    RESIGNAL;
  END;

-- Declaramos el control de salida del loop
DECLARE CONTINUE HANDLER FOR NOT FOUND SET termino = TRUE;

-- Abrimos el Cursor
OPEN Datos_Asiento;

-- Iniciamos la Transaccion
START TRANSACTION;

-- Leeemos el Cursor
read_loop: LOOP
FETCH Datos_Asiento INTO centros_costosid, valor, codigocontable;

-- Verificamos si no hay mas registros
IF termino THEN
LEAVE read_loop;
END IF;

SET diferencia = diferencia+(Round(valor,2));
-- Sumamos valores de debe y haber
IF valor<0 THEN
  SET haber = (haber + (Abs((valor))));
ELSE
  SET debe  = (debe + (Abs((valor))));
END IF;

-- INSERTAMOS LA CABECERA DEL ASIENTO
  IF gravocabecera=FALSE THEN
    -- Optenemos el nuevo secuencial
    call SP_Consulta_Secuencias_Internas('LIBRODIARIO',codigoasiento);
  
    -- Insertamos Registro Cabecera
    INSERT INTO libros_diarios 
    (
      codigoasiento, 
      fecha, 
      referencia, 
      concepto, 
      origen, 
      usuariocreacion, 
      fechacreacion
    ) 
    VALUES 
    (
      codigoasiento,
      dFechaHasta,
      codigoasiento, 
      CONCAT('Mantenimiento de ',DATE_FORMAT(dFechaDesde,"%d-%m-%Y"),' a ',DATE_FORMAT(dFechaHasta,"%d-%m-%Y")),
      'Garantias', 
      sUsuario, 
      NOW()
    );
   
   -- obtenemos el ultimo ID insertado
    SET libros_diariosid=(select LAST_INSERT_ID());
    
    -- Actualizamos el secuencial de libros diarios
    call SP_Actualiza_Secuencias_Internas('LIBRODIARIO');

    -- Ponemos que gravo la cabecera
    SET gravocabecera=TRUE;

  END IF;

-- INSERTAMOS LOS DETALLES
SET valor = round(valor,2);
INSERT INTO libros_diarios_detalles
( 	
libros_diariosid,	
codigocontable,	
centros_costosid,	
referencia,	
concepto,	
importe
)
VALUES
( 
libros_diariosid,	
codigocontable,	
centros_costosid,	
codigoasiento,	
CONCAT('Mantenimiento de ',DATE_FORMAT(dFechaDesde,"%d-%m-%Y"),' a ',DATE_FORMAT(dFechaHasta,"%d-%m-%Y")),	
valor
 );

-- Toma la primer cuenta del asiento contable
IF cuenta_fija=0 THEN 
SET cuenta_fija = (select LAST_INSERT_ID());
END IF;

END LOOP;

CALL SP_Contabiliza_Verificar_Asiento(libros_diariosid,verificado);


-- Cuadramos el asiento contable si esta descuadrado
IF diferencia<0.11 AND diferencia>-0.11 AND diferencia<>0  THEN
UPDATE libros_diarios_detalles
SET
libros_diarios_detalles.importe = libros_diarios_detalles.importe-diferencia
WHERE
libros_diarios_detalles.libros_diarios_detallesid = cuenta_fija;
SET diferencia=0;
END IF;

-- Verificamos si el asiento esta cuadrado
IF diferencia<>0 THEN
SET verificado=0;
END IF;

-- Actualizamos el libro diario
SET debe = Round(debe,2);
SET haber = Round(haber,2);
UPDATE 
libros_diarios
SET
libros_diarios.debito = debe,
libros_diarios.credito = haber,
libros_diarios.mayorizado = verificado,
libros_diarios.verificado = verificado,
libros_diarios.fechamodificacion = libros_diarios.fechamodificacion
WHERE
libros_diarios.libros_diariosid = libros_diariosid;


-- Actualizamos el ID del libro diario a el movimiento de Caja
UPDATE 
 	garantias_seguimientos 
SET 
garantias_seguimientos.asientocontable = libros_diariosid,
garantias_seguimientos.fechamodificacion = garantias_seguimientos.fechamodificacion
WHERE 
 garantias_seguimientos.asientocontable = 0 
AND  DATE(garantias_seguimientos.fecha) BETWEEN dFechaDesde AND dFechaHasta;

-- Finalizamos la transaccion
COMMIT;

-- Cerramos el Cursor
CLOSE Datos_Asiento;

-- Devolvemos el ID del Asiento Contable
select libros_diariosid;

END
;;
delimiter ;

-- ----------------------------
-- Procedure structure for SP_Contabiliza_Garantia_Individual
-- ----------------------------
DROP PROCEDURE IF EXISTS `SP_Contabiliza_Garantia_Individual`;
delimiter ;;
CREATE PROCEDURE `SP_Contabiliza_Garantia_Individual`(IN nDocumentoid BIGINT, IN sUsuario VARCHAR(25))
  MODIFIES SQL DATA 
BEGIN

-- Declaramos variables de Cursor
DECLARE termino INT DEFAULT FALSE;
DECLARE fechamovimiento date;
DECLARE usuariocreacion varchar(25);
DECLARE centros_costosid int(11);
DECLARE concepto varchar(200);
DECLARE referencia varchar(15);
DECLARE valor decimal(16,8) DEFAULT 0;
DECLARE codigocontable varchar(30);
DECLARE codigoasiento varchar(10);
DECLARE gravocabecera INT DEFAULT FALSE;
DECLARE libros_diariosid bigint DEFAULT 0;
DECLARE debe  decimal(16,8) DEFAULT 0;
DECLARE haber decimal(16,8) DEFAULT 0;
DECLARE diferencia decimal(12,2) DEFAULT 0;
DECLARE verificado INT DEFAULT TRUE;
DECLARE cuenta_fija bigint DEFAULT 0;

DECLARE Datos_Asiento CURSOR FOR
SELECT 
DATE(garantias_seguimientos.fecha)							AS fechamovimiento,
garantias_repuestos.centros_costosid 						AS centros_costosid,
LEFT(CONCAT(garantias.garantias_codigo,' ',garantias_seguimientos.mantenimiento,' ',garantias_detalles.descripcion),200) 	AS concepto, 
garantias_seguimientos.garantias_seguimientosid AS referencia,
SUM((garantias_repuestos.costo)*(garantias_repuestos.cantidad)) AS valor, 
 productos.cuentacontable_costo AS codigocontable
FROM garantias_seguimientos
INNER JOIN garantias_detalles on garantias_detalles.garantias_detallesid = garantias_seguimientos.garantias_detallesid
INNER JOIN garantias on garantias.garantiasid = garantias_detalles.garantiasid
INNER JOIN garantias_repuestos ON garantias_repuestos.garantias_seguimientosid = garantias_seguimientos.garantias_seguimientosid
INNER JOIN productos ON garantias_repuestos.productosid = productos.productosid
WHERE 	
garantias_seguimientos.asientocontable = 0
AND  garantias_seguimientos.garantias_seguimientosid = nDocumentoid
AND productos.servicio =0 
AND productos.bien =0 		
GROUP BY 
productos.cuentacontable_costo
HAVING
SUM((garantias_repuestos.costo)*(garantias_repuestos.cantidad))<>0

-- --------------------------------------
UNION

SELECT 
DATE(garantias_seguimientos.fecha)								AS fechamovimiento,
garantias_repuestos.centros_costosid 							AS centros_costosid,
LEFT(CONCAT(garantias.garantias_codigo,' ',garantias_seguimientos.mantenimiento,' ',garantias_detalles.descripcion),200) 	AS concepto, 
garantias_seguimientos.garantias_seguimientosid 		AS referencia,
-SUM((garantias_repuestos.costo)*(garantias_repuestos.cantidad)) AS valor, 
  productos.cuentacontable_inventarios AS codigocontable
FROM garantias_seguimientos
INNER JOIN garantias_detalles on garantias_detalles.garantias_detallesid = garantias_seguimientos.garantias_detallesid
INNER JOIN garantias on garantias.garantiasid = garantias_detalles.garantiasid
INNER JOIN garantias_repuestos ON garantias_repuestos.garantias_seguimientosid = garantias_seguimientos.garantias_seguimientosid
INNER JOIN productos ON garantias_repuestos.productosid = productos.productosid
WHERE 	
garantias_seguimientos.asientocontable = 0
AND  garantias_seguimientos.garantias_seguimientosid = nDocumentoid
AND productos.servicio =0 
AND productos.bien =0 		
GROUP BY 
productos.cuentacontable_inventarios
HAVING
SUM((garantias_repuestos.costo)*(garantias_repuestos.cantidad))<>0;

-- Controlamos si hubo error
DECLARE exit handler FOR SQLEXCEPTION, SQLWARNING
  BEGIN
  	SHOW WARNINGS limit 1;
    ROLLBACK;
    RESIGNAL;
  END;

-- Declaramos el control de salida del loop
DECLARE CONTINUE HANDLER FOR NOT FOUND SET termino = TRUE;

-- Abrimos el Cursor
OPEN Datos_Asiento;

-- Iniciamos la Transaccion
START TRANSACTION;

-- Leeemos el Cursor
read_loop: LOOP
FETCH Datos_Asiento INTO fechamovimiento,centros_costosid, concepto, referencia, valor, codigocontable;

-- Verificamos si no hay mas registros
IF termino THEN
LEAVE read_loop;
END IF;

SET diferencia = diferencia+(Round(valor,2));
-- Sumamos valores de debe y haber
IF valor<0 THEN
  SET haber = (haber + (Abs((valor))));
ELSE
  SET debe  = (debe + (Abs((valor))));
END IF;

-- INSERTAMOS LA CABECERA DEL ASIENTO
  IF gravocabecera=FALSE THEN
    -- Optenemos el nuevo secuencial
    call SP_Consulta_Secuencias_Internas('LIBRODIARIO',codigoasiento);
  
    -- Insertamos Registro Cabecera
    INSERT INTO libros_diarios 
    (
      codigoasiento, 
      fecha, 
      referencia, 
      concepto, 
      origen, 
      usuariocreacion, 
      fechacreacion
    ) 
    VALUES 
    (
      codigoasiento,
      fechamovimiento,
      referencia, 
      concepto,
      'Garantias', 
      sUsuario, 
      NOW(3)
    );
   
   -- obtenemos el ultimo ID insertado
    SET libros_diariosid=(select LAST_INSERT_ID());
    
    -- Actualizamos el secuencial de libros diarios
    call SP_Actualiza_Secuencias_Internas('LIBRODIARIO');

    -- Ponemos que gravo la cabecera
    SET gravocabecera=TRUE;

  END IF;

-- INSERTAMOS LOS DETALLES
SET valor = round(valor,2);
INSERT INTO libros_diarios_detalles
( 	
libros_diariosid,	
codigocontable,	
centros_costosid,	
referencia,	
concepto,	
importe
)
VALUES
( 
libros_diariosid,	
codigocontable,	
centros_costosid,	
referencia,	
concepto,	
valor
 );

-- Toma la primer cuenta del asiento contable
IF cuenta_fija=0 THEN 
SET cuenta_fija = (select LAST_INSERT_ID());
END IF;

END LOOP;

CALL SP_Contabiliza_Verificar_Asiento(libros_diariosid,verificado);


-- Cuadramos el asiento contable si esta descuadrado
IF diferencia<0.11 AND diferencia>-0.11 AND diferencia<>0  THEN
UPDATE libros_diarios_detalles
SET
libros_diarios_detalles.importe = libros_diarios_detalles.importe-diferencia
WHERE
libros_diarios_detalles.libros_diarios_detallesid = cuenta_fija;
SET diferencia=0;
END IF;

-- Verificamos si el asiento esta cuadrado
IF diferencia<>0 THEN
SET verificado=0;
END IF;

-- Actualizamos el libro diario
SET debe = Round(debe,2);
SET haber = Round(haber,2);
UPDATE 
libros_diarios
SET
libros_diarios.debito = debe,
libros_diarios.credito = haber,
libros_diarios.mayorizado = verificado,
libros_diarios.verificado = verificado,
libros_diarios.fechamodificacion = libros_diarios.fechamodificacion
WHERE
libros_diarios.libros_diariosid = libros_diariosid;


-- Actualizamos el ID del libro diario a el movimiento de Caja
  UPDATE 
 	garantias_seguimientos 
SET 
garantias_seguimientos.asientocontable = libros_diariosid,
garantias_seguimientos.fechamodificacion = garantias_seguimientos.fechamodificacion
WHERE 
 garantias_seguimientos.asientocontable = 0 
AND garantias_seguimientos.garantias_seguimientosid = nDocumentoid;	

-- Finalizamos la transaccion
COMMIT;

-- Cerramos el Cursor
CLOSE Datos_Asiento;

-- Devolvemos el ID del Asiento Contable
select libros_diariosid;

END
;;
delimiter ;

-- ----------------------------
-- Procedure structure for SP_Contabiliza_Ingreso_Agrupado
-- ----------------------------
DROP PROCEDURE IF EXISTS `SP_Contabiliza_Ingreso_Agrupado`;
delimiter ;;
CREATE PROCEDURE `SP_Contabiliza_Ingreso_Agrupado`(IN dFechaDesde DATE, IN dFechaHasta DATE, IN sUsuario VARCHAR(25))
  MODIFIES SQL DATA 
BEGIN

-- Declaramos variables de Cursor
DECLARE termino INT DEFAULT FALSE;
-- DECLARE fechamovimiento date;
DECLARE usuariocreacion varchar(25);
DECLARE centros_costosid int(11);
DECLARE concepto varchar(200);
DECLARE referencia varchar(15);
DECLARE valor decimal(16,8) DEFAULT 0;
DECLARE codigocontable varchar(30);
DECLARE codigoasiento varchar(10);
DECLARE gravocabecera INT DEFAULT FALSE;
DECLARE libros_diariosid bigint DEFAULT 0;
DECLARE debe  decimal(16,8) DEFAULT 0;
DECLARE haber decimal(16,8) DEFAULT 0;
DECLARE diferencia decimal(12,2) DEFAULT 0;
DECLARE verificado INT DEFAULT TRUE;
DECLARE cuenta_fija bigint DEFAULT 0;

DECLARE Datos_Asiento CURSOR FOR

SELECT 
ingresos_detalles.centros_costosid AS centros_costosid,
LEFT(ingresos.concepto,200) AS concepto, 
ingresos.ingresoscodigo AS referencia,
(SUM(ingresos_detalles.costo*ingresos_detalles.cantidad)) AS valor, 
productos.cuentacontable_inventarios AS codigocontable
FROM ingresos
INNER JOIN (ingresos_detalles
INNER JOIN ( productos) ON ingresos_detalles.productosid = productos.productosid
) ON ingresos.ingresosid = ingresos_detalles.ingresosid
WHERE 	
ingresos.movimientos_conceptosid NOT IN (17)
AND ingresos.asientocontable = 0
AND DATE(ingresos.fecha) BETWEEN dFechaDesde AND dFechaHasta
GROUP BY 
ingresos_detalles.centros_costosid, 
productos.cuentacontable_inventarios	
HAVING
SUM(ingresos_detalles.costo*ingresos_detalles.cantidad)<>0

UNION ALL
SELECT 
ingresos_detalles.centros_costosid AS centros_costosid,
LEFT(ingresos.concepto,200) AS concepto,
ingresos.ingresoscodigo AS referencia,

-ROUND(IF (ingresos.origen ='Produccion' , SUM((ingresos_detalles.costo*ingresos_detalles.cantidad) -
 (SELECT  sum((produccion_detalles.cantidad * produccion_detalles.valor_mod) + (produccion_detalles.cantidad * produccion_detalles.valor_cif)) FROM produccion INNER JOIN produccion_detalles ON produccion_detalles.produccionesid = produccion.produccionesid
where produccion.ingresosid = ingresos.ingresosid )) , SUM(ingresos_detalles.costo*ingresos_detalles.cantidad)),8) AS valor, 

movimientos_conceptos.codigocontable AS codigocontable
FROM movimientos_conceptos
INNER JOIN (ingresos
INNER JOIN (ingresos_detalles
) ON ingresos.ingresosid = ingresos_detalles.ingresosid
) ON movimientos_conceptos.movimientos_conceptosid = ingresos.movimientos_conceptosid
WHERE 
ingresos.movimientos_conceptosid NOT IN ( 17)
and ingresos.asientocontable = 0
AND DATE(ingresos.fecha) BETWEEN dFechaDesde AND dFechaHasta
GROUP BY 
ingresos_detalles.centros_costosid, 
movimientos_conceptos.codigocontable
HAVING
SUM(ingresos_detalles.costo*ingresos_detalles.cantidad)<>0
-- ----------------------------------------
-- MOVIMIENTO DE PRODUCCION suma mod y cif
-- --------------------------------------
UNION ALL
SELECT 
ingresos.centros_costosid AS centros_costosid,
LEFT(ingresos.concepto,200) AS concepto,
ingresos.ingresoscodigo AS referencia,
-(SUM(produccion_detalles.cantidad * produccion_detalles.valor_mod)) AS valor,
(select movimientos_conceptos.codigocontable from movimientos_conceptos where movimientos_conceptos.movimientos_conceptosid =27 ) AS codigocontable
FROM movimientos_conceptos
INNER JOIN ingresos ON movimientos_conceptos.movimientos_conceptosid = ingresos.movimientos_conceptosid , produccion , produccion_detalles
WHERE 
ingresos.movimientos_conceptosid = 18
and ingresos.asientocontable = 0
AND DATE(ingresos.fecha) BETWEEN dFechaDesde AND dFechaHasta
AND produccion.ingresosid = ingresos.ingresosid
AND produccion.produccionesid = produccion_detalles.produccionesid
GROUP BY 
movimientos_conceptos.codigocontable
HAVING
SUM(produccion_detalles.cantidad * produccion_detalles.valor_mod)<>0
UNION ALL
SELECT 
ingresos.centros_costosid AS centros_costosid,
LEFT(ingresos.concepto,200) AS concepto,
ingresos.ingresoscodigo AS referencia,
-(SUM(produccion_detalles.cantidad * produccion_detalles.valor_cif)) AS valor,
(select movimientos_conceptos.codigocontable from movimientos_conceptos where movimientos_conceptos.movimientos_conceptosid =28 ) AS codigocontable
FROM movimientos_conceptos
INNER JOIN ingresos ON movimientos_conceptos.movimientos_conceptosid = ingresos.movimientos_conceptosid , produccion , produccion_detalles
WHERE 
ingresos.movimientos_conceptosid = 18
and ingresos.asientocontable = 0
AND DATE(ingresos.fecha) BETWEEN dFechaDesde AND dFechaHasta
AND produccion.ingresosid = ingresos.ingresosid
AND produccion.produccionesid = produccion_detalles.produccionesid
GROUP BY 
movimientos_conceptos.codigocontable
HAVING
SUM(produccion_detalles.cantidad * produccion_detalles.valor_cif)<>0;



-- Controlamos si hubo error
DECLARE exit handler FOR SQLEXCEPTION, SQLWARNING
  BEGIN
  	SHOW WARNINGS limit 1;
    ROLLBACK;
    RESIGNAL;
  END;

-- Declaramos el control de salida del loop
DECLARE CONTINUE HANDLER FOR NOT FOUND SET termino = TRUE;

-- Abrimos el Cursor
OPEN Datos_Asiento;

-- Iniciamos la Transaccion
START TRANSACTION;

-- Leeemos el Cursor
read_loop: LOOP
FETCH Datos_Asiento INTO centros_costosid, concepto, referencia, valor, codigocontable;

-- Verificamos si no hay mas registros
IF termino THEN
LEAVE read_loop;
END IF;

SET diferencia = diferencia+(Round(valor,2));
-- Sumamos valores de debe y haber
IF valor<0 THEN
  SET haber = (haber + (Abs((valor))));
ELSE
  SET debe  = (debe + (Abs((valor))));
END IF;

-- INSERTAMOS LA CABECERA DEL ASIENTO
  IF gravocabecera=FALSE THEN
    -- Optenemos el nuevo secuencial
    call SP_Consulta_Secuencias_Internas('LIBRODIARIO',codigoasiento);
  
    -- Insertamos Registro Cabecera
    INSERT INTO libros_diarios 
    (
      codigoasiento, 
      fecha, 
      referencia, 
      concepto, 
      origen, 
      usuariocreacion, 
      fechacreacion
    ) 
    VALUES 
    (
      codigoasiento,
      dFechaHasta,
      codigoasiento, 
      CONCAT('Ingresos del ',DATE_FORMAT(dFechaDesde,"%d-%m-%Y"),' al ',DATE_FORMAT(dFechaHasta,"%d-%m-%Y")),
      'Ingresos', 
      sUsuario, 
      NOW()
    );
   
   -- obtenemos el ultimo ID insertado
    SET libros_diariosid=(select LAST_INSERT_ID());
    
    -- Actualizamos el secuencial de libros diarios
    call SP_Actualiza_Secuencias_Internas('LIBRODIARIO');

    -- Ponemos que gravo la cabecera
    SET gravocabecera=TRUE;

  END IF;

-- INSERTAMOS LOS DETALLES
SET valor = round(valor,2);
INSERT INTO libros_diarios_detalles
( 	
libros_diariosid,	
codigocontable,	
centros_costosid,	
referencia,	
concepto,	
importe
)
VALUES
( 
libros_diariosid,	
codigocontable,	
centros_costosid,	
referencia,	
concepto,	
valor
 );

-- Toma la primer cuenta del asiento contable
IF cuenta_fija=0 THEN 
SET cuenta_fija = (select LAST_INSERT_ID());
END IF;

END LOOP;

CALL SP_Contabiliza_Verificar_Asiento(libros_diariosid,verificado);


-- Cuadramos el asiento contable si esta descuadrado
IF diferencia<0.11 AND diferencia>-0.11 AND diferencia<>0  THEN
UPDATE libros_diarios_detalles
SET
libros_diarios_detalles.importe = libros_diarios_detalles.importe-diferencia
WHERE
libros_diarios_detalles.libros_diarios_detallesid = cuenta_fija;
SET diferencia=0;
END IF;

-- Verificamos si el asiento esta cuadrado
IF diferencia<>0 THEN
SET verificado=0;
END IF;

-- Actualizamos el libro diario
SET debe = Round(debe,2);
SET haber = Round(haber,2);
UPDATE 
libros_diarios
SET
libros_diarios.debito = debe,
libros_diarios.credito = haber,
libros_diarios.mayorizado = verificado,
libros_diarios.verificado = verificado,
libros_diarios.fechamodificacion = libros_diarios.fechamodificacion
WHERE
libros_diarios.libros_diariosid = libros_diariosid;


-- Actualizamos el ID del libro diario a el movimiento de Caja
UPDATE 
Ingresos 
SET 
ingresos.AsientoContable = libros_diariosid,
ingresos.fechamodificacion= ingresos.fechamodificacion
WHERE 
Ingresos.movinventarios_tiposid <> 5 
AND Ingresos.AsientoContable = 0 
AND DATE(Ingresos.Fecha) BETWEEN dFechaDesde AND dFechaHasta;


-- Finalizamos la transaccion
COMMIT;

-- Cerramos el Cursor
CLOSE Datos_Asiento;

-- Devolvemos el ID del Asiento Contable
select libros_diariosid;

END
;;
delimiter ;

