DROP PROCEDURE IF EXISTS `SP_Contabiliza_Ingreso_Individual`;
delimiter ;;
CREATE PROCEDURE `SP_Contabiliza_Ingreso_Individual`(IN nDocumentoid BIGINT, IN sUsuario VARCHAR(25))
  MODIFIES SQL DATA 
BEGIN

-- Declaramos variables de Cursor
DECLARE termino INT DEFAULT FALSE;
DECLARE fechamovimiento date;
DECLARE usuariocreacion varchar(25);
DECLARE centros_costosid int(11);
DECLARE concepto varchar(200);
DECLARE referencia varchar(15);
DECLARE valor decimal(16,8) DEFAULT 0;
DECLARE codigocontable varchar(30);
DECLARE codigoasiento varchar(15);
DECLARE gravocabecera INT DEFAULT FALSE;
DECLARE libros_diariosid bigint DEFAULT 0;
DECLARE debe  decimal(16,8) DEFAULT 0;
DECLARE haber decimal(16,8) DEFAULT 0;
DECLARE diferencia decimal(12,2) DEFAULT 0;
DECLARE verificado INT DEFAULT TRUE;
DECLARE cuenta_fija bigint DEFAULT 0;

DECLARE Datos_Asiento CURSOR FOR
SELECT 
DATE(ingresos.fecha) AS fechamovimiento,
ingresos_detalles.centros_costosid AS centros_costosid,
LEFT(ingresos.concepto,200) AS concepto, 
ingresos.ingresoscodigo AS referencia,
ROUND(SUM(ingresos_detalles.costo*ingresos_detalles.cantidad),8) AS valor, 
productos.cuentacontable_inventarios AS codigocontable
FROM ingresos
INNER JOIN (ingresos_detalles
INNER JOIN ( productos) ON ingresos_detalles.productosid = productos.productosid
) ON ingresos.ingresosid = ingresos_detalles.ingresosid
WHERE 	
ingresos.movimientos_conceptosid NOT IN (17)
AND ingresos.asientocontable = 0
AND  ingresos.ingresosid = nDocumentoid
GROUP BY 
ingresos_detalles.centros_costosid, 
productos.cuentacontable_inventarios	
HAVING
SUM(ingresos_detalles.costo*ingresos_detalles.cantidad)<>0

UNION 

SELECT 
DATE(ingresos.fecha) AS fechamovimiento,
ingresos_detalles.centros_costosid AS centros_costosid,
LEFT(ingresos.concepto,200) AS concepto,
ingresos.ingresoscodigo AS referencia,

- ROUND(IF (ingresos.origen ="Produccion" , SUM(ingresos_detalles.costo*ingresos_detalles.cantidad) -
 (SELECT  sum((produccion_detalles.cantidad * produccion_detalles.valor_mod) + (produccion_detalles.cantidad * produccion_detalles.valor_cif)) FROM produccion INNER JOIN produccion_detalles ON produccion_detalles.produccionesid = produccion.produccionesid
where produccion.ingresosid = nDocumentoid ) , SUM(ingresos_detalles.costo*ingresos_detalles.cantidad)),8 ) AS valor, 

movimientos_conceptos.codigocontable AS codigocontable
FROM movimientos_conceptos
INNER JOIN (ingresos
INNER JOIN (ingresos_detalles
) ON ingresos.ingresosid = ingresos_detalles.ingresosid
) ON movimientos_conceptos.movimientos_conceptosid = ingresos.movimientos_conceptosid
WHERE 
ingresos.movimientos_conceptosid NOT IN ( 17)
and ingresos.asientocontable = 0
AND  ingresos.ingresosid = nDocumentoid
GROUP BY 
ingresos_detalles.centros_costosid, 
movimientos_conceptos.codigocontable
HAVING
SUM(ingresos_detalles.costo*ingresos_detalles.cantidad)<>0
-- ----------------------------------------
-- MOVIMIENTO DE PRODUCCION suma mod y cif
-- --------------------------------------
UNION ALL
SELECT 
DATE(ingresos.fecha) AS fechamovimiento,
ingresos.centros_costosid AS centros_costosid,
LEFT(ingresos.concepto,200) AS concepto,
ingresos.ingresoscodigo AS referencia,
-ROUND(SUM(produccion_detalles.cantidad * produccion_detalles.valor_mod),8) AS valor,
(select movimientos_conceptos.codigocontable from movimientos_conceptos where movimientos_conceptos.movimientos_conceptosid =27 ) AS codigocontable
FROM movimientos_conceptos
INNER JOIN ingresos ON movimientos_conceptos.movimientos_conceptosid = ingresos.movimientos_conceptosid , produccion , produccion_detalles
WHERE 
ingresos.movimientos_conceptosid = 18
and ingresos.asientocontable = 0
AND ingresos.ingresosid = nDocumentoid
AND produccion.ingresosid = ingresos.ingresosid
AND produccion.produccionesid = produccion_detalles.produccionesid
GROUP BY 
movimientos_conceptos.codigocontable
HAVING
SUM(produccion_detalles.valor_mod)<>0
UNION ALL
SELECT 
DATE(ingresos.fecha) AS fechamovimiento,
ingresos.centros_costosid AS centros_costosid,
LEFT(ingresos.concepto,200) AS concepto,
ingresos.ingresoscodigo AS referencia,
-ROUND(SUM(produccion_detalles.cantidad * produccion_detalles.valor_cif),8) AS valor,
(select movimientos_conceptos.codigocontable from movimientos_conceptos where movimientos_conceptos.movimientos_conceptosid =28 ) AS codigocontable
FROM movimientos_conceptos
INNER JOIN ingresos ON movimientos_conceptos.movimientos_conceptosid = ingresos.movimientos_conceptosid , produccion , produccion_detalles
WHERE 
ingresos.movimientos_conceptosid = 18
and ingresos.asientocontable = 0
AND ingresos.ingresosid = nDocumentoid
AND produccion.ingresosid = ingresos.ingresosid
AND produccion.produccionesid = produccion_detalles.produccionesid
GROUP BY 
movimientos_conceptos.codigocontable
HAVING
SUM(produccion_detalles.valor_cif)<>0;

-- Controlamos si hubo error
DECLARE exit handler FOR SQLEXCEPTION, SQLWARNING
  BEGIN
  	SHOW WARNINGS limit 1;
    ROLLBACK;
    RESIGNAL;
  END;

-- Declaramos el control de salida del loop
DECLARE CONTINUE HANDLER FOR NOT FOUND SET termino = TRUE;

-- Abrimos el Cursor
OPEN Datos_Asiento;

-- Iniciamos la Transaccion
START TRANSACTION;

-- Leeemos el Cursor
read_loop: LOOP
FETCH Datos_Asiento INTO fechamovimiento,centros_costosid, concepto, referencia, valor, codigocontable;

-- Verificamos si no hay mas registros
IF termino THEN
LEAVE read_loop;
END IF;

SET diferencia = ROUND(diferencia+(Round(valor,2)),2);
-- Sumamos valores de debe y haber
IF valor<0 THEN
  SET haber = (haber + (Abs((valor))));
ELSE
  SET debe  = (debe + (Abs((valor))));
END IF;

-- INSERTAMOS LA CABECERA DEL ASIENTO
  IF gravocabecera=FALSE THEN
    -- Optenemos el nuevo secuencial
    call SP_Consulta_Secuencias_Internas('LIBRODIARIO',codigoasiento);
  
    -- Insertamos Registro Cabecera
    INSERT INTO libros_diarios 
    (
      codigoasiento, 
      fecha, 
      referencia, 
      concepto, 
      origen, 
      usuariocreacion, 
      fechacreacion
    ) 
    VALUES 
    (
      codigoasiento,
      fechamovimiento,
      referencia, 
      concepto,
      'Ingresos', 
      sUsuario, 
      NOW(3)
    );
   
   -- obtenemos el ultimo ID insertado
    SET libros_diariosid=(select LAST_INSERT_ID());
    
    -- Actualizamos el secuencial de libros diarios
    call SP_Actualiza_Secuencias_Internas('LIBRODIARIO');

    -- Ponemos que gravo la cabecera
    SET gravocabecera=TRUE;

  END IF;

-- INSERTAMOS LOS DETALLES
SET valor = round(valor,2);
INSERT INTO libros_diarios_detalles
( 	
libros_diariosid,	
codigocontable,	
centros_costosid,	
referencia,	
concepto,	
importe
)
VALUES
( 
libros_diariosid,	
codigocontable,	
centros_costosid,	
referencia,	
concepto,	
valor
 );

-- Toma la primer cuenta del asiento contable
IF cuenta_fija=0 THEN 
SET cuenta_fija = (select LAST_INSERT_ID());
END IF;

END LOOP;

CALL SP_Contabiliza_Verificar_Asiento(libros_diariosid,verificado);


-- Cuadramos el asiento contable si esta descuadrado
IF diferencia<0.11 AND diferencia>-0.11 AND diferencia<>0  THEN
UPDATE libros_diarios_detalles
SET
libros_diarios_detalles.importe = libros_diarios_detalles.importe-diferencia
WHERE
libros_diarios_detalles.libros_diarios_detallesid = cuenta_fija;
SET diferencia=0;
END IF;

-- Verificamos si el asiento esta cuadrado
IF diferencia<>0 THEN
SET verificado=0;
END IF;

-- Actualizamos el libro diario
SET debe = Round(debe,2);
SET haber = Round(haber,2);
UPDATE 
libros_diarios
SET
libros_diarios.debito = debe,
libros_diarios.credito = haber,
libros_diarios.mayorizado = verificado,
libros_diarios.verificado = verificado
WHERE
libros_diarios.libros_diariosid = libros_diariosid;


-- Actualizamos el ID del libro diario a el movimiento de Caja
UPDATE 
ingresos 
SET 
ingresos.asientocontable = libros_diariosid,
ingresos.fechamodificacion= ingresos.fechamodificacion
WHERE 
ingresos.movinventarios_tiposid <> 5 
AND ingresos.asientocontable = 0 
AND ingresos.ingresosid = nDocumentoid;

-- Finalizamos la transaccion
COMMIT;

-- Cerramos el Cursor
CLOSE Datos_Asiento;

-- Devolvemos el ID del Asiento Contable
select libros_diariosid;

END
;;
delimiter ;

-- ----------------------------
-- Procedure structure for SP_Contabiliza_Libro_Diario_Crear
-- ----------------------------
DROP PROCEDURE IF EXISTS `SP_Contabiliza_Libro_Diario_Crear`;
delimiter ;;
CREATE PROCEDURE `SP_Contabiliza_Libro_Diario_Crear`(IN PaJson JSON, IN dFecha DATE, IN sUsuario VARCHAR(255))
  MODIFIES SQL DATA 
BEGIN

  -- Declaramos variables de Cursor
  DECLARE vJsonValido int;
  DECLARE vItems int DEFAULT 0;
  DECLARE vItemsDetalles int DEFAULT 0;
  DECLARE vIndex int DEFAULT 0;
  DECLARE vIndexDetalle int DEFAULT 0;
  DECLARE JsonDetalle json;
  DECLARE JsonDetalletexto varchar(250);
  DECLARE termino int DEFAULT FALSE;
  DECLARE fechamovimiento date;
  DECLARE usuariocreacion varchar(25);
  DECLARE centros_costosid int(11);
  DECLARE concepto varchar(200);
  DECLARE conceptodetalle varchar(200);
  DECLARE referencia varchar(15);
  DECLARE referenciaDetalles varchar(15);
  DECLARE valor decimal(12,2) DEFAULT 0;
  DECLARE codigocontable varchar(30);
  DECLARE codigoasiento varchar(10);
  DECLARE libros_diariosid bigint DEFAULT 0;
  DECLARE debe decimal(12, 2) DEFAULT 0;
  DECLARE haber decimal(12, 2) DEFAULT 0;
  DECLARE verificado int DEFAULT TRUE;
  DECLARE mayorizado int DEFAULT false;

  DECLARE EXIT HANDLER FOR SQLEXCEPTION, SQLWARNING
  BEGIN
  	SHOW WARNINGS limit 1;
    ROLLBACK;
    RESIGNAL;
  END;

  -- Validamos el archivo JSON
  SET vJsonValido = JSON_VALID(paJson);


  IF vJsonValido = 1 THEN
    -- obtenermos el numero de registros del JSON
    SET vItems = JSON_LENGTH(PaJson);

    -- verificamos que el json tenga datos
    IF vItems > 0 THEN

      -- Iniciamos la Transaccion
      START TRANSACTION;


        WHILE vIndex < vItems DO
          -- extraigo el contenido del json
          SET PaJson = JSON_EXTRACT(PaJson, CONCAT('$[0].registro'));
          -- guardamos el detalle del asiento en otro json
          SET JsonDetalle = JSON_EXTRACT(PaJson, CONCAT('$[', vIndex, '].detalle'));

          -- asignamos los valores del json a las variables correspondientes
          -- set concepto        = sConcepto;
          set concepto        = UNHEX(JSON_UNQUOTE(JSON_EXTRACT(PaJson, CONCAT('$[', vIndex, '].concepto'))));
          SET referencia      = JSON_UNQUOTE(JSON_EXTRACT(PaJson, CONCAT('$[', vIndex, '].referencia')));
          set codigoasiento   = JSON_UNQUOTE(JSON_EXTRACT(PaJson, CONCAT('$[', vIndex, '].codigoasiento')));
          SET debe            = JSON_EXTRACT(PaJson, CONCAT('$[', vIndex, '].debe'));
          SET haber           = JSON_EXTRACT(PaJson, CONCAT('$[', vIndex, '].haber'));
          set mayorizado      =  JSON_UNQUOTE(JSON_EXTRACT(PaJson, CONCAT('$[', vIndex, '].mayorizado')));
          SET fechamovimiento = dFecha;
          -- set fechamovimiento = DATE_FORMAT(((PaJson, CONCAT('$[',vIndex,'].fechamovimiento'))),"%d-%m-%Y");

          -- INSERTAMOS LA CABECERA DEL ASIENTO    
          -- Insertamos Registro Cabecera
          INSERT INTO libros_diarios (codigoasiento,
          fecha,
          referencia,
          concepto,
          origen,
          mayorizado,
          usuariocreacion,
          fechacreacion)
          VALUES (codigoasiento, fechamovimiento, referencia, concepto, 'Contabilidad', mayorizado, sUsuario, NOW(3));

          -- obtenemos el ultimo ID insertado
          SET libros_diariosid = (SELECT
              LAST_INSERT_ID());

          -- Actualizamos el secuencial de libros diarios
          CALL SP_Actualiza_Secuencias_Internas('LIBRODIARIO');

          -- Iniciamos el recorrido para el detalle del asiento
          -- validamos el json del detalle
          SET vJsonValido = JSON_VALID(JsonDetalle);

          IF vJsonValido = 1 THEN
            SET vItemsDetalles = JSON_LENGTH(JsonDetalle);

            IF vItemsDetalles > 0 THEN
              SET vIndexDetalle = 0;

              -- recorremos el json del detalle del asiento
              WHILE vIndexDetalle < vItemsDetalles DO
                SET conceptodetalle     = UNHEX(JSON_UNQUOTE(JSON_EXTRACT(JsonDetalle, CONCAT('$[', vIndexDetalle, '].conceptodetalle'))));
                SET codigocontable      = JSON_UNQUOTE(JSON_EXTRACT(JsonDetalle, CONCAT('$[', vIndexDetalle, '].codigocontable')));
                SET referenciaDetalles  = JSON_UNQUOTE(JSON_EXTRACT(JsonDetalle, CONCAT('$[', vIndexDetalle, '].referenciaDetalles')));
                set valor               = JSON_EXTRACT(JsonDetalle, CONCAT('$[', vIndexDetalle, '].valor'));
                SET centros_costosid    = JSON_UNQUOTE(JSON_EXTRACT(JsonDetalle, CONCAT('$[', vIndexDetalle, '].centros_costosid')));

                -- INSERTAMOS LOS DETALLES
                INSERT INTO libros_diarios_detalles (libros_diariosid,
                codigocontable,
                centros_costosid,
                referencia,
                concepto,
                importe)
                VALUES (libros_diariosid, 
                codigocontable, 
                centros_costosid, 
                referenciaDetalles, 
                conceptodetalle, 
                ROUND(valor, 2));

                SET vIndexDetalle = vIndexDetalle + 1;
              END WHILE; -- fin while detalles

            END IF; -- fin vItemsDetalles > 0 detalle
          END IF; -- fin vJsonValido = 1 detalle

          -- END LOOP;
          SET vIndex = vIndex + 1;
        END WHILE; -- fin while encabezado

        CALL SP_Contabiliza_Verificar_Asiento(libros_diariosid, verificado);


        -- Actualizamos el libro diario
        UPDATE libros_diarios
        SET libros_diarios.debito = debe,
            libros_diarios.credito = haber,
            libros_diarios.verificado = verificado,
 			libros_diarios.fechamodificacion = libros_diarios.fechamodificacion            
        WHERE libros_diarios.libros_diariosid = libros_diariosid;

      -- Finalizamos la transaccion
      COMMIT;

      -- Devolvemos el ID del Asiento Contable
      SELECT
        libros_diariosid;


    END IF;
  END IF;
END
;;
delimiter ;

-- ----------------------------
-- Procedure structure for SP_Contabiliza_Libro_Diario_Editar
-- ----------------------------
DROP PROCEDURE IF EXISTS `SP_Contabiliza_Libro_Diario_Editar`;
delimiter ;;
CREATE PROCEDURE `SP_Contabiliza_Libro_Diario_Editar`(IN nDocumentoid BIGINT, IN PaJson JSON, IN dFecha DATE, IN sUsuario VARCHAR(255))
  MODIFIES SQL DATA 
BEGIN

  -- Declaramos variables de Cursor
  DECLARE vJsonValido int;
  DECLARE vItems int DEFAULT 0;
  DECLARE vItemsDetalles int DEFAULT 0;
  DECLARE vIndex int DEFAULT 0;
  DECLARE vIndexDetalle int DEFAULT 0;
  DECLARE JsonDetalle json;
  DECLARE JsonDetalletexto varchar(250);
  DECLARE termino int DEFAULT FALSE;
  DECLARE fechamovimiento date;
  DECLARE usuariocreacion varchar(25);
  DECLARE centros_costosid int(11);
  DECLARE concepto varchar(200);
  DECLARE conceptodetalle varchar(200);
  DECLARE referencia varchar(15);
  DECLARE referenciaDetalles varchar(15);
  DECLARE valor decimal(12,2) DEFAULT 0;
  DECLARE codigocontable varchar(30);
  DECLARE codigoasiento varchar(10);
  DECLARE debe decimal(12, 2) DEFAULT 0;
  DECLARE haber decimal(12, 2) DEFAULT 0;
  DECLARE verificado int DEFAULT TRUE;
  DECLARE mayorizado int DEFAULT TRUE;

  DECLARE EXIT HANDLER FOR SQLEXCEPTION, SQLWARNING
  BEGIN
  	SHOW WARNINGS limit 1;
    ROLLBACK;
    RESIGNAL;
  END;

  -- Validamos el archivo JSON
  SET vJsonValido = JSON_VALID(paJson);


  IF vJsonValido = 1 THEN
    -- obtenermos el numero de registros del JSON
    SET vItems = JSON_LENGTH(PaJson);

    -- verificamos que el json tenga datos
    IF vItems > 0 THEN

      -- Iniciamos la Transaccion
      START TRANSACTION;


        WHILE vIndex < vItems DO
          -- extraigo el contenido del json
          SET PaJson = JSON_EXTRACT(PaJson, CONCAT('$[0].registro'));
          -- guardamos el detalle del asiento en otro json
          SET JsonDetalle = JSON_EXTRACT(PaJson, CONCAT('$[', vIndex, '].detalle'));

          -- asignamos los valores del json a las variables correspondientes
          -- set concepto        = sConcepto;
          set concepto        = UNHEX(JSON_UNQUOTE(JSON_EXTRACT(PaJson, CONCAT('$[', vIndex, '].concepto'))));
          set referencia      = JSON_UNQUOTE(JSON_EXTRACT(PaJson, CONCAT('$[', vIndex, '].referencia')));
          set codigoasiento   = JSON_UNQUOTE(JSON_EXTRACT(PaJson, CONCAT('$[', vIndex, '].codigoasiento')));
          set mayorizado      = JSON_UNQUOTE(JSON_EXTRACT(PaJson, CONCAT('$[', vIndex, '].mayorizado')));
          set debe            = JSON_EXTRACT(PaJson, CONCAT('$[', vIndex, '].debe'));
          set haber           = JSON_EXTRACT(PaJson, CONCAT('$[', vIndex, '].haber'));
          SET fechamovimiento = dFecha;
          -- set fechamovimiento = DATE_FORMAT(((PaJson, CONCAT('$[',vIndex,'].fechamovimiento'))),"%d-%m-%Y");
  
          -- actualizamos los registros de la cabecera

          UPDATE libros_diarios SET libros_diarios.fecha = fechamovimiento, 
          libros_diarios.referencia = referencia,
          libros_diarios.concepto = concepto,
          libros_diarios.mayorizado = mayorizado,
          libros_diarios.usuariomodificacion = sUsuario,
          libros_diarios.fechamodificacion = NOW(3)
          WHERE libros_diarios.libros_diariosid = nDocumentoid;

          -- Actualizamos el secuencial de libros diarios
          -- CALL SP_Actualiza_Secuencias_Internas('LIBRODIARIO');

          -- INSERTAMOS EL DETALLE DEL ASIENTO
          -- validamos el json del detalle
          SET vJsonValido = JSON_VALID(JsonDetalle);

          IF vJsonValido = 1 THEN
            SET vItemsDetalles = JSON_LENGTH(JsonDetalle);

            IF vItemsDetalles > 0 THEN
              SET vIndexDetalle = 0;

              -- Eliminamos el detalle del asiento
              DELETE FROM libros_diarios_detalles WHERE libros_diarios_detalles.libros_diariosid = nDocumentoid;

              -- recorremos el json del detalle del asiento
              WHILE vIndexDetalle < vItemsDetalles DO
                SET conceptodetalle     = UNHEX(JSON_UNQUOTE(JSON_EXTRACT(JsonDetalle, CONCAT('$[', vIndexDetalle, '].conceptodetalle'))));
                set codigocontable      = JSON_UNQUOTE(JSON_EXTRACT(JsonDetalle, CONCAT('$[', vIndexDetalle, '].codigocontable')));
                set referenciaDetalles  = JSON_UNQUOTE(JSON_EXTRACT(JsonDetalle, CONCAT('$[', vIndexDetalle, '].referenciaDetalles')));
                set valor               = JSON_EXTRACT(JsonDetalle, CONCAT('$[', vIndexDetalle, '].valor'));
                set centros_costosid    = JSON_UNQUOTE(JSON_EXTRACT(JsonDetalle, CONCAT('$[', vIndexDetalle, '].centros_costosid')));

                -- INSERTAMOS LOS DETALLES
                INSERT INTO libros_diarios_detalles (libros_diariosid,
                codigocontable,
                centros_costosid,
                referencia,
                concepto,
                importe)
                VALUES 
                (nDocumentoid, 
                codigocontable, 
                centros_costosid, 
                referenciaDetalles, 
                conceptodetalle, 
                ROUND(valor, 2));

                -- incremento del indice de json de detalles
                SET vIndexDetalle = vIndexDetalle + 1;
              END WHILE; -- fin while detalles

            END IF; -- fin vItemsDetalles > 0 detalle
          END IF; -- fin vJsonValido = 1 detalle

          -- incremento del indice de json de encabezado
          SET vIndex = vIndex + 1;
        END WHILE; -- fin while encabezado

        CALL SP_Contabiliza_Verificar_Asiento(nDocumentoid, verificado);


        -- Actualizamos el libro diario
        UPDATE libros_diarios
        SET libros_diarios.debito = debe,
            libros_diarios.credito = haber,
            libros_diarios.verificado = verificado
        WHERE libros_diarios.libros_diariosid = nDocumentoid;

      -- Finalizamos la transaccion
      COMMIT;

      -- Devolvemos el ID del Asiento Contable
      SELECT
        nDocumentoid AS libros_diariosid;
    END IF;
  END IF;
END
;;
delimiter ;

