DROP PROCEDURE IF EXISTS `SP_Contabiliza_Limpiar_Asiento`;
delimiter ;;
CREATE PROCEDURE `SP_Contabiliza_Limpiar_Asiento`()
  MODIFIES SQL DATA 
  SQL SECURITY INVOKER
BEGIN 
-- Controlamos si hubo error
DECLARE exit handler FOR SQLEXCEPTION, SQLWARNING
