DECLARE cuenta_fija bigint DEFAULT 0;

DECLARE Datos_Asiento CURSOR FOR
SELECT
  movcaja.fechamovimiento AS fechamovimiento,
movcaja.centros_costosid AS centros_costosid,
LEFT(CONCAT(movcaja.concepto,' ',movcaja.comprobante),200)  AS concepto,
movcaja.documentoorigen AS referencia,
SUM(movcaja.importe) AS valor,
cajas.codigocontable AS codigocontable
FROM
cajas
INNER JOIN
movcaja
ON (cajas.cajasid = movcaja.cajasid)
WHERE
movcaja.origen = 'Nomina'
AND movcaja.movcajasid = nDocumentoid
HAVING
SUM(movcaja.importe)<>0

UNION
SELECT
  movcaja.fechamovimiento AS fechamovimiento,
movcaja.centros_costosid AS centros_costosid,
LEFT(CONCAT(movcaja.concepto,' ',movcaja.comprobante),200)  AS concepto,
movcaja.documentoorigen AS referencia,
SUM(-movcaja.importe) AS valor,
movimientos_conceptos.codigocontable AS codigocontable
FROM
movimientos_conceptos
INNER JOIN
movcaja
ON (movimientos_conceptos.movimientos_conceptosid = movcaja.movimientos_conceptosid)
WHERE
movcaja.origen = 'Nomina'
AND movcaja.movcajasid = nDocumentoid
HAVING
SUM(movcaja.importe)<>0;



-- Controlamos si hubo error
DECLARE exit handler FOR SQLEXCEPTION, SQLWARNING
  BEGIN
  	SHOW WARNINGS limit 1;
    ROLLBACK;
    RESIGNAL;
  END;

-- Declaramos el control de salida del loop
DECLARE CONTINUE HANDLER FOR NOT FOUND SET termino = TRUE;

-- Abrimos el Cursor
OPEN Datos_Asiento;

-- Iniciamos la Transaccion
START TRANSACTION;

-- Leeemos el Cursor
read_loop: LOOP
FETCH Datos_Asiento INTO fechamovimiento,centros_costosid, concepto, referencia, valor, codigocontable;

-- Verificamos si no hay mas registros
IF termino THEN
LEAVE read_loop;
END IF;

SET diferencia = diferencia+(Round(valor,2));
-- Sumamos valores de debe y haber
IF valor<0 THEN
  SET haber = (haber + (Abs((valor))));
ELSE
  SET debe  = (debe + (Abs((valor))));
END IF;

-- INSERTAMOS LA CABECERA DEL ASIENTO
  IF gravocabecera=FALSE THEN
    -- Optenemos el nuevo secuencial
    call SP_Consulta_Secuencias_Internas('LIBRODIARIO',codigoasiento);
  
    -- Insertamos Registro Cabecera
    INSERT INTO libros_diarios 
    (
      codigoasiento, 
      fecha, 
      referencia, 
      concepto, 
      origen, 
      usuariocreacion, 
      fechacreacion
    ) 
    VALUES 
    (
      codigoasiento,
      fechamovimiento,
      referencia, 
      concepto,
      'Nomina', 
      sUsuario, 
      NOW(3)
    );
   
   -- obtenemos el ultimo ID insertado
    SET libros_diariosid=(select LAST_INSERT_ID());
    
    -- Actualizamos el secuencial de libros diarios
    call SP_Actualiza_Secuencias_Internas('LIBRODIARIO');

    -- Ponemos que gravo la cabecera
    SET gravocabecera=TRUE;

  END IF;

-- INSERTAMOS LOS DETALLES
set valor = round(valor,2);
INSERT INTO libros_diarios_detalles
( 	
libros_diariosid,	
codigocontable,	
centros_costosid,	
referencia,	
concepto,	
importe
)
VALUES

( 
libros_diariosid,	
codigocontable,	
centros_costosid,	
referencia,	
concepto,	
valor
 );

-- Toma la primer cuenta del asiento contable
IF cuenta_fija=0 THEN 
SET cuenta_fija = (select LAST_INSERT_ID());
END IF;

END LOOP;

CALL SP_Contabiliza_Verificar_Asiento(libros_diariosid,verificado);


-- Cuadramos el asiento contable si esta descuadrado
IF diferencia<0.11 AND diferencia>-0.11 AND diferencia<>0  THEN
UPDATE libros_diarios_detalles
SET
libros_diarios_detalles.importe = libros_diarios_detalles.importe-diferencia
WHERE
libros_diarios_detalles.libros_diarios_detallesid = cuenta_fija;
SET diferencia=0;
END IF;

-- Verificamos si el asiento esta cuadrado
IF diferencia<>0 THEN
SET verificado=0;
END IF;

-- Actualizamos el libro diario
SET debe = Round(debe,2);
SET haber = Round(haber,2);
UPDATE 
libros_diarios
SET
libros_diarios.debito = debe,
libros_diarios.credito = haber,
libros_diarios.mayorizado = verificado,
libros_diarios.verificado = verificado,
libros_diarios.fechamodificacion = libros_diarios.fechamodificacion
WHERE
libros_diarios.libros_diariosid = libros_diariosid;


-- Actualizamos el ID del libro diario a el movimiento de Caja
UPDATE
   movcaja 
SET
   movcaja.asientocontable = libros_diariosid 
WHERE
   movcaja.movcajasid = nDocumentoid 
   AND movcaja.asientocontable = 0 
   AND movcaja.origen = 'Nomina';



-- Finalizamos la transaccion
COMMIT;

-- Cerramos el Cursor
CLOSE Datos_Asiento;

-- Devolvemos el ID del Asiento Contable
select libros_diariosid;

END
;;
delimiter ;

-- ----------------------------
-- Procedure structure for SP_Contabiliza_Pago_Agrupado
-- ----------------------------
DROP PROCEDURE IF EXISTS `SP_Contabiliza_Pago_Agrupado`;
delimiter ;;
CREATE PROCEDURE `SP_Contabiliza_Pago_Agrupado`(IN dFechaDesde DATE, IN dFechaHasta DATE, IN sCCAnticipo VARCHAR(255), IN sUsuario VARCHAR(25))
  MODIFIES SQL DATA 
BEGIN

-- Declaramos variables de Cursor
DECLARE termino INT DEFAULT FALSE;
DECLARE fechamovimiento date;
DECLARE usuariocreacion varchar(25);
DECLARE centros_costosid int(11);
DECLARE concepto varchar(200);
DECLARE referencia varchar(15);
DECLARE valor decimal(16,8) DEFAULT 0;
DECLARE codigocontable varchar(30);
DECLARE codigoasiento varchar(15);
DECLARE gravocabecera INT DEFAULT FALSE;
DECLARE libros_diariosid bigint DEFAULT 0;
DECLARE debe  decimal(16,8) DEFAULT 0;
DECLARE haber decimal(16,8) DEFAULT 0;
DECLARE diferencia decimal(12,2) DEFAULT 0;
DECLARE verificado INT DEFAULT TRUE;
DECLARE cuenta_fija bigint DEFAULT 0;

DECLARE Datos_Asiento CURSOR FOR
SELECT
pagos.centros_costosid AS centros_costosid,
LEFT(concat(pagos.concepto,' ',proveedores.razonsocial),200) AS concepto,
pagos.pagoscodigo AS referencia,
-SUM(cuentasporpagar.importe) AS valor,
movimientos_conceptos.codigocontable AS codigocontable
FROM
pagos
INNER JOIN
cuentasporpagar
ON (pagos.pagosid = cuentasporpagar.pagosid 
AND cuentasporpagar.tipo = 'AB' 
AND cuentasporpagar.forma_pago_empresaid = 9 
AND cuentasporpagar.origen = 'Pagos')
INNER JOIN movimientos_conceptos ON pagos.movimientos_conceptosid = movimientos_conceptos.movimientos_conceptosid,
proveedores
WHERE
proveedores.proveedoresid = pagos.proveedoresid
and pagos.tipo = 'AB'
AND pagos.asientocontable = 0	
AND pagos.fechaemision BETWEEN dFechaDesde AND dFechaHasta
HAVING
SUM(cuentasporpagar.importe)<>0

UNION

SELECT
pagos.centros_costosid AS centros_costosid,
LEFT(concat(pagos.concepto,' ',proveedores.razonsocial),200) AS concepto,
pagos.pagoscodigo AS referencia,
-SUM(cuentasporpagar.importe) AS valor,
movimientos_conceptos.codigocontable AS codigocontable
FROM
pagos
INNER JOIN
cuentasporpagar
ON (pagos.pagosid = cuentasporpagar.pagosid 
AND cuentasporpagar.tipo = 'AB' 
AND cuentasporpagar.forma_pago_empresaid = 10 
AND cuentasporpagar.origen = 'Pagos')
inner join movimientos_conceptos on pagos.movimientos_conceptosid = movimientos_conceptos.movimientos_conceptosid
,	
proveedores
WHERE
proveedores.proveedoresid = pagos.proveedoresid
and  pagos.tipo = 'AB'
AND pagos.asientocontable = 0	
AND pagos.fechaemision BETWEEN dFechaDesde AND dFechaHasta
HAVING
SUM(cuentasporpagar.importe)<>0

UNION

SELECT
pagos.centros_costosid AS centros_costosid,
LEFT(concat(pagos.concepto,' ',proveedores.razonsocial),200) AS concepto,
pagos.pagoscodigo AS referencia,
SUM(movcaja.importe) AS valor,
cajas.codigocontable AS codigocontable
FROM
cajas
INNER JOIN
(	movcaja
INNER JOIN
(	pagos)ON (pagos.pagosid= movcaja.documentosid AND movcaja.origen = 'Pagos')
)ON cajas.cajasid = movcaja.cajasid,
proveedores
WHERE
proveedores.proveedoresid = pagos.proveedoresid
and 
(pagos.asientocontable = 0	)
AND pagos.fechaemision BETWEEN dFechaDesde AND dFechaHasta
GROUP BY
cajas.codigocontable
HAVING
SUM(movcaja.importe)<>0

UNION

SELECT
pagos.centros_costosid AS centros_costosid,
LEFT(concat(pagos.concepto,' ',proveedores.razonsocial),200) AS concepto,
pagos.pagoscodigo AS referencia,
SUM(movbanco.importe) AS valor,
bancos.codigocontable AS codigocontable
FROM
bancos
INNER JOIN
(	movbanco
INNER JOIN
(	pagos)ON (pagos.pagosid= movbanco.documentosid AND movbanco.origen = 'Pagos')
)ON bancos.bancosid = movbanco.bancosid,
proveedores
WHERE
proveedores.proveedoresid = pagos.proveedoresid
and 	(pagos.asientocontable = 0	)
AND pagos.fechaemision BETWEEN dFechaDesde AND dFechaHasta
GROUP BY
bancos.codigocontable
HAVING
SUM(movbanco.importe)<>0

UNION

SELECT
pagos.centros_costosid AS centros_costosid,
LEFT(concat(pagos.concepto,' ',proveedores.razonsocial),200) AS concepto,
pagos.pagoscodigo AS referencia,
SUM(pagos.importe) AS valor,
movimientos_conceptos.codigocontable AS codigocontable
FROM
movimientos_conceptos
INNER JOIN
pagos
ON (movimientos_conceptos.movimientos_conceptosid = pagos.movimientos_conceptosid AND movimientos_conceptos.movimientos_conceptosid <> 9)
,
proveedores
WHERE
proveedores.proveedoresid = pagos.proveedoresid
and 
pagos.tipo = 'ND'
AND pagos.fechaemision BETWEEN dFechaDesde AND dFechaHasta
HAVING
SUM(-pagos.importe)<>0

UNION

SELECT
pagos.centros_costosid AS centros_costosid,
LEFT(concat(pagos.concepto,' ',proveedores.razonsocial),200) AS concepto,
pagos.pagoscodigo AS referencia,
SUM(CASE WHEN ((pagos.tipo = 'ND' ) OR (pagos.tipo='AB' AND pagos.forma_pago_empresaid = 10)) THEN -pagos.importe ELSE (pagos.importe-pagos.anticipo) END) AS valor,
proveedores.codigocontable  AS codigocontable
FROM
pagos
INNER JOIN
proveedores 
ON pagos.proveedoresid = proveedores.proveedoresid	
WHERE	
pagos.movimientos_conceptosid<>9
AND pagos.tipo <>'NC'
AND pagos.asientocontable = 0
AND pagos.fechaemision BETWEEN dFechaDesde AND dFechaHasta
GROUP BY
proveedores.codigocontable
HAVING
SUM(CASE WHEN ((pagos.tipo = 'ND' ) OR (pagos.tipo='AB' AND pagos.forma_pago_empresaid = 10)) THEN -pagos.importe ELSE (pagos.importe-pagos.anticipo) END)<>0

UNION

SELECT
pagos.centros_costosid AS centros_costosid,
LEFT(concat(pagos.concepto,' ',proveedores.razonsocial),200) AS concepto,
pagos.pagoscodigo AS referencia,
SUM(pagos.importe) AS valor,
sCCAnticipo  AS codigocontable
FROM
pagos
,
proveedores
WHERE
proveedores.proveedoresid = pagos.proveedoresid
and 
pagos.asientocontable = 0
AND pagos.tipo ='NC'
AND pagos.fechaemision BETWEEN dFechaDesde AND dFechaHasta
HAVING
SUM(pagos.importe)<>0

UNION

SELECT	
pagos.centros_costosid AS centros_costosid,
LEFT(concat(pagos.concepto,' ',proveedores.razonsocial),200) AS concepto,
pagos.pagoscodigo AS referencia,
(pagos.anticipo) AS valor,
sCCAnticipo  AS codigocontable
FROM
pagos
,
proveedores
WHERE
proveedores.proveedoresid = pagos.proveedoresid
and 
pagos.asientocontable = 0
AND pagos.fechaemision BETWEEN dFechaDesde AND dFechaHasta
HAVING
SUM(pagos.anticipo)<>0;



-- Controlamos si hubo error
DECLARE exit handler FOR SQLEXCEPTION, SQLWARNING
  BEGIN
  	SHOW WARNINGS limit 1;
    ROLLBACK;
    RESIGNAL;
  END;

-- Declaramos el control de salida del loop
DECLARE CONTINUE HANDLER FOR NOT FOUND SET termino = TRUE;

-- Abrimos el Cursor
OPEN Datos_Asiento;

-- Iniciamos la Transaccion
START TRANSACTION;

-- Leeemos el Cursor
read_loop: LOOP
FETCH Datos_Asiento INTO centros_costosid, concepto, referencia, valor, codigocontable;

-- Verificamos si no hay mas registros
IF termino THEN
LEAVE read_loop;
END IF;

SET diferencia = diferencia+(Round(valor,2));
-- Sumamos valores de debe y haber
IF valor<0 THEN
  SET haber = (haber + (Abs((valor))));
ELSE
  SET debe  = (debe + (Abs((valor))));
END IF;

-- INSERTAMOS LA CABECERA DEL ASIENTO
  IF gravocabecera=FALSE THEN
    -- Optenemos el nuevo secuencial
    call SP_Consulta_Secuencias_Internas('LIBRODIARIO',codigoasiento);
  
    -- Insertamos Registro Cabecera
    INSERT INTO libros_diarios 
    (
      codigoasiento, 
      fecha, 
      referencia, 
      concepto, 
      origen, 
      usuariocreacion, 
      fechacreacion
    ) 
    VALUES 
    (
      codigoasiento,
      dFechaDesde,
      codigoasiento, 
      CONCAT('Pagos de ',DATE_FORMAT(dFechaDesde,"%d-%m-%Y"),' a ',DATE_FORMAT(dFechaHasta,"%d-%m-%Y")),
      'Pagos', 
      sUsuario, 
      NOW()
    );
   
   -- obtenemos el ultimo ID insertado
    SET libros_diariosid=(select LAST_INSERT_ID());
    
    -- Actualizamos el secuencial de libros diarios
    call SP_Actualiza_Secuencias_Internas('LIBRODIARIO');

    -- Ponemos que gravo la cabecera
    SET gravocabecera=TRUE;

  END IF;

-- INSERTAMOS LOS DETALLES
SET valor = round(valor,2);
INSERT INTO libros_diarios_detalles
( 	
libros_diariosid,	
codigocontable,	
centros_costosid,	
referencia,	
concepto,	
importe
)
VALUES
( 
libros_diariosid,	
codigocontable,	
centros_costosid,	
referencia,	
concepto,	
valor
 );

-- Toma la primer cuenta del asiento contable
IF cuenta_fija=0 THEN 
SET cuenta_fija = (select LAST_INSERT_ID());
END IF;

END LOOP;

CALL SP_Contabiliza_Verificar_Asiento(libros_diariosid,verificado);


-- Cuadramos el asiento contable si esta descuadrado
IF diferencia<0.11 AND diferencia>-0.11 AND diferencia<>0  THEN
UPDATE libros_diarios_detalles
SET
libros_diarios_detalles.importe = libros_diarios_detalles.importe-diferencia
WHERE
libros_diarios_detalles.libros_diarios_detallesid = cuenta_fija;
SET diferencia=0;
END IF;

-- Verificamos si el asiento esta cuadrado
IF diferencia<>0 THEN
SET verificado=0;
END IF;

-- Actualizamos el libro diario
SET debe = Round(debe,2);
SET haber = Round(haber,2);
UPDATE 
libros_diarios
SET
libros_diarios.debito = debe,
libros_diarios.credito = haber,
libros_diarios.mayorizado = verificado,
libros_diarios.verificado = verificado
WHERE
libros_diarios.libros_diariosid = libros_diariosid;


-- Actualizamos el ID del libro diario a el pago
UPDATE
movcaja 
SET
movcaja.asientocontable=libros_diariosid
WHERE
movcaja.asientocontable = 0
AND movcaja.origen = 'Pagos'
AND movcaja.fechamovimiento BETWEEN dFechaDesde AND dFechaHasta;
UPDATE
movbanco 
SET
movbanco.asientocontable=libros_diariosid
WHERE
movbanco.asientocontable = 0
AND movbanco.fechamovimiento BETWEEN dFechaDesde AND dFechaHasta
AND movbanco.origen = 'Pagos';
UPDATE
cuentasporpagar 
SET
cuentasporpagar.asientocontable=libros_diariosid
WHERE
cuentasporpagar.origen = 'Pagos'
AND cuentasporpagar.asientocontable = 0
AND cuentasporpagar.emision BETWEEN dFechaDesde AND dFechaHasta
AND cuentasporpagar.concepto NOT LIKE 'CRUCE ANTICIPO %';
UPDATE
pagos
SET
pagos.asientocontable = libros_diariosid
WHERE
pagos.fechaemision BETWEEN dFechaDesde AND dFechaHasta
AND pagos.asientocontable = 0;



-- Finalizamos la transaccion
COMMIT;

-- Cerramos el Cursor
CLOSE Datos_Asiento;

-- Devolvemos el ID del Asiento Contable
select libros_diariosid;

END
;;
delimiter ;

-- ----------------------------
-- Procedure structure for SP_Contabiliza_Pago_Individual
-- ----------------------------
DROP PROCEDURE IF EXISTS `SP_Contabiliza_Pago_Individual`;
delimiter ;;
CREATE PROCEDURE `SP_Contabiliza_Pago_Individual`(IN nDocumentoid BIGINT, IN sCCAnticipo VARCHAR(255), IN sUsuario VARCHAR(25))
  MODIFIES SQL DATA 
BEGIN

-- Declaramos variables de Cursor
DECLARE termino INT DEFAULT FALSE;
DECLARE fechamovimiento date;
DECLARE usuariocreacion varchar(25);
DECLARE centros_costosid int(11);
DECLARE concepto varchar(200);
DECLARE referencia varchar(15);
DECLARE valor decimal(16,8) DEFAULT 0;
DECLARE codigocontable varchar(30);
DECLARE codigoasiento varchar(10);
DECLARE gravocabecera INT DEFAULT FALSE;
DECLARE libros_diariosid bigint DEFAULT 0;
DECLARE debe  decimal(16,8) DEFAULT 0;
DECLARE haber decimal(16,8) DEFAULT 0;
DECLARE diferencia decimal(12,2) DEFAULT 0;
DECLARE verificado INT DEFAULT TRUE;
DECLARE cuenta_fija bigint DEFAULT 0;

DECLARE Datos_Asiento CURSOR FOR
SELECT
pagos.fechaemision as fechamovimiento,
pagos.centros_costosid AS centros_costosid,
LEFT(concat(pagos.concepto,' ',proveedores.razonsocial),200) AS concepto,
pagos.pagoscodigo AS referencia,
-SUM(cuentasporpagar.importe) AS valor,
movimientos_conceptos.codigocontable AS codigocontable
FROM
pagos
INNER JOIN
cuentasporpagar
ON (pagos.pagosid = cuentasporpagar.pagosid 
AND cuentasporpagar.tipo = 'AB' 
AND cuentasporpagar.forma_pago_empresaid = 9 
AND cuentasporpagar.origen = 'Pagos')
INNER JOIN movimientos_conceptos ON pagos.movimientos_conceptosid = movimientos_conceptos.movimientos_conceptosid
,
proveedores
WHERE
proveedores.proveedoresid = pagos.proveedoresid
and 
pagos.tipo = 'AB'
AND pagos.asientocontable = 0	
AND pagos.pagosid = nDocumentoid
HAVING
SUM(cuentasporpagar.importe)<>0

UNION

SELECT
pagos.fechaemision as fechamovimiento,
pagos.centros_costosid AS centros_costosid,
LEFT(concat(pagos.concepto,' ',proveedores.razonsocial),200) AS concepto,
pagos.pagoscodigo AS referencia,
-SUM(cuentasporpagar.importe) AS valor,
movimientos_conceptos.codigocontable AS codigocontable
FROM
pagos
INNER JOIN
cuentasporpagar
ON (pagos.pagosid = cuentasporpagar.pagosid 
AND cuentasporpagar.tipo = 'AB' 
AND cuentasporpagar.forma_pago_empresaid = 10 
AND cuentasporpagar.origen = 'Pagos')
inner join movimientos_conceptos on pagos.movimientos_conceptosid = movimientos_conceptos.movimientos_conceptosid
,
proveedores
WHERE
proveedores.proveedoresid = pagos.proveedoresid
and 
pagos.tipo = 'AB'
AND pagos.asientocontable = 0	
AND pagos.pagosid = nDocumentoid
HAVING
SUM(cuentasporpagar.importe)<>0

UNION

SELECT
pagos.fechaemision as fechamovimiento,
pagos.centros_costosid AS centros_costosid,
LEFT(concat(pagos.concepto,' ',proveedores.razonsocial),200) AS concepto,
pagos.pagoscodigo AS referencia,
SUM(movcaja.importe) AS valor,
cajas.codigocontable AS codigocontable
FROM
cajas
INNER JOIN
(	movcaja
INNER JOIN
(	pagos)ON (pagos.pagosid= movcaja.documentosid AND movcaja.origen = 'Pagos')
)ON cajas.cajasid = movcaja.cajasid
,
proveedores
WHERE
proveedores.proveedoresid = pagos.proveedoresid
and 	
(pagos.asientocontable = 0	)
AND pagos.pagosid = nDocumentoid
HAVING
SUM(movcaja.importe)<>0

UNION

SELECT
pagos.fechaemision as fechamovimiento,
pagos.centros_costosid AS centros_costosid,
LEFT(concat(pagos.concepto,' ',proveedores.razonsocial),200) AS concepto,
pagos.pagoscodigo AS referencia,
SUM(movbanco.importe) AS valor,
bancos.codigocontable AS codigocontable
FROM
bancos
INNER JOIN
(	movbanco
INNER JOIN
(	pagos)ON (pagos.pagosid= movbanco.documentosid AND movbanco.origen = 'Pagos')
)ON bancos.bancosid = movbanco.bancosid
,
proveedores
WHERE
proveedores.proveedoresid = pagos.proveedoresid
and 	
(pagos.asientocontable = 0	)
AND pagos.pagosid = nDocumentoid
GROUP BY
bancos.codigocontable
HAVING
SUM(movbanco.importe)<>0

UNION

SELECT
pagos.fechaemision as fechamovimiento,
pagos.centros_costosid AS centros_costosid,
LEFT(concat(pagos.concepto,' ',proveedores.razonsocial),200) AS concepto,
pagos.pagoscodigo AS referencia,
SUM(pagos.importe) AS valor,
movimientos_conceptos.codigocontable AS codigocontable
FROM
movimientos_conceptos
INNER JOIN
pagos
ON (movimientos_conceptos.movimientos_conceptosid = pagos.movimientos_conceptosid AND movimientos_conceptos.movimientos_conceptosid <> 9)
,
proveedores
WHERE
proveedores.proveedoresid = pagos.proveedoresid
and 
pagos.tipo = 'ND'
AND pagos.pagosid = nDocumentoid
HAVING
SUM(-pagos.importe)<>0

UNION

SELECT
pagos.fechaemision as fechamovimiento,
pagos.centros_costosid AS centros_costosid,
left(concat(pagos.concepto,' ',proveedores.razonsocial),200) AS concepto,
pagos.pagoscodigo AS referencia,
SUM(CASE WHEN ((pagos.tipo = 'ND' ) OR (pagos.tipo='AB' AND pagos.forma_pago_empresaid = 10)) THEN -pagos.importe ELSE (pagos.importe-pagos.anticipo) END) AS valor,
proveedores.codigocontable  AS codigocontable
FROM
pagos
INNER JOIN
proveedores 
ON pagos.proveedoresid = proveedores.proveedoresid
WHERE	
pagos.movimientos_conceptosid<>9
AND pagos.tipo <>'NC'
AND pagos.asientocontable = 0
AND pagos.pagosid = nDocumentoid
GROUP BY
proveedores.codigocontable
HAVING
SUM(CASE WHEN ((pagos.tipo = 'ND' ) OR (pagos.tipo='AB' AND pagos.forma_pago_empresaid = 10)) THEN -pagos.importe ELSE (pagos.importe-pagos.anticipo) END)<>0

UNION

SELECT
pagos.fechaemision as fechamovimiento,
pagos.centros_costosid AS centros_costosid,
LEFT(concat(pagos.concepto,' ',proveedores.razonsocial),200) AS concepto,
pagos.pagoscodigo AS referencia,
(pagos.importe) AS valor,
sCCAnticipo AS codigocontable
FROM
pagos
,
proveedores
WHERE
proveedores.proveedoresid = pagos.proveedoresid
and 
pagos.asientocontable = 0
AND pagos.tipo ='NC'
AND pagos.pagosid = nDocumentoid
HAVING
SUM(pagos.importe)<>0

UNION

SELECT	
pagos.fechaemision as fechamovimiento,
pagos.centros_costosid AS centros_costosid,
LEFT(concat(pagos.concepto,' ',proveedores.razonsocial),200) AS concepto,
pagos.pagoscodigo AS referencia,
(pagos.anticipo) AS valor,
sCCAnticipo  AS codigocontable
FROM
pagos
,
proveedores
WHERE
proveedores.proveedoresid = pagos.proveedoresid
and 
pagos.asientocontable = 0
AND pagos.pagosid = nDocumentoid
HAVING
SUM(pagos.anticipo)<>0

UNION

SELECT
pagos.fechaemision as fechamovimiento,
pagos.centros_costosid AS centros_costosid,
LEFT(concat(pagos.concepto,' ',proveedores.razonsocial),200) AS concepto,
pagos.pagoscodigo AS referencia,
-SUM(pagos.importe) AS valor,
movimientos_conceptos.codigocontable AS codigocontable
FROM
movimientos_conceptos
INNER JOIN
pagos
ON (movimientos_conceptos.movimientos_conceptosid = pagos.movimientos_conceptosid AND movimientos_conceptos.movimientos_conceptosid <> 9)
,
proveedores
WHERE
proveedores.proveedoresid = pagos.proveedoresid
and 
pagos.tipo  ='NC'
AND pagos.movimientos_conceptosid <> 7
AND pagos.pagosid =  nDocumentoid
HAVING
Sum(pagos.importe)<>0;



-- Controlamos si hubo error
DECLARE exit handler FOR SQLEXCEPTION, SQLWARNING
  BEGIN
  	SHOW WARNINGS limit 1;
    ROLLBACK;
    RESIGNAL;
  END;

-- Declaramos el control de salida del loop
DECLARE CONTINUE HANDLER FOR NOT FOUND SET termino = TRUE;

-- Abrimos el Cursor
OPEN Datos_Asiento;

-- Iniciamos la Transaccion
START TRANSACTION;

-- Leeemos el Cursor
read_loop: LOOP
FETCH Datos_Asiento INTO fechamovimiento,centros_costosid, concepto, referencia, valor, codigocontable;

-- Verificamos si no hay mas registros
IF termino THEN
LEAVE read_loop;
END IF;

SET diferencia = diferencia+(Round(valor,2));
-- Sumamos valores de debe y haber
IF valor<0 THEN
  SET haber = (haber + (Abs((valor))));
ELSE
  SET debe  = (debe + (Abs((valor))));
END IF;

-- INSERTAMOS LA CABECERA DEL ASIENTO
  IF gravocabecera=FALSE THEN
    -- Optenemos el nuevo secuencial
    call SP_Consulta_Secuencias_Internas('LIBRODIARIO',codigoasiento);
  
    -- Insertamos Registro Cabecera
    INSERT INTO libros_diarios 
    (
      codigoasiento, 
      fecha, 
      referencia, 
      concepto, 
      origen, 
      usuariocreacion, 
      fechacreacion
    ) 
    VALUES 
    (
      codigoasiento,
      fechamovimiento,
      referencia, 
      concepto,
      'Pagos', 
      sUsuario, 
      NOW(3)
    );
   
   -- obtenemos el ultimo ID insertado
    SET libros_diariosid=(select LAST_INSERT_ID());
    
    -- Actualizamos el secuencial de libros diarios
    call SP_Actualiza_Secuencias_Internas('LIBRODIARIO');

    -- Ponemos que gravo la cabecera
    SET gravocabecera=TRUE;

  END IF;

-- INSERTAMOS LOS DETALLES
SET valor = round(valor,2);
INSERT INTO libros_diarios_detalles
( 	
libros_diariosid,	
codigocontable,	
centros_costosid,	
referencia,	
concepto,	
importe
)
VALUES
( 
libros_diariosid,	
codigocontable,	
centros_costosid,	
referencia,	
concepto,	
valor
 );

-- Toma la primer cuenta del asiento contable
IF cuenta_fija=0 THEN 
SET cuenta_fija = (select LAST_INSERT_ID());
END IF;

END LOOP;

CALL SP_Contabiliza_Verificar_Asiento(libros_diariosid,verificado);


-- Cuadramos el asiento contable si esta descuadrado
IF diferencia<0.11 AND diferencia>-0.11 AND diferencia<>0  THEN
UPDATE libros_diarios_detalles
SET
libros_diarios_detalles.importe = libros_diarios_detalles.importe-diferencia
WHERE
libros_diarios_detalles.libros_diarios_detallesid = cuenta_fija;
SET diferencia=0;
END IF;

-- Verificamos si el asiento esta cuadrado
IF diferencia<>0 THEN
SET verificado=0;
END IF;

-- Actualizamos el libro diario
SET debe = Round(debe,2);
SET haber = Round(haber,2);
UPDATE 
libros_diarios
SET
libros_diarios.debito = debe,
libros_diarios.credito = haber,
libros_diarios.mayorizado = verificado,
libros_diarios.verificado = verificado
WHERE
libros_diarios.libros_diariosid = libros_diariosid;


-- Actualizamos el ID del libro diario a el pago
UPDATE
movcaja 
SET
movcaja.asientocontable=libros_diariosid
WHERE
movcaja.asientocontable = 0
AND movcaja.origen = 'Pagos'
AND movcaja.documentosid = nDocumentoid;
UPDATE
movbanco 
SET
movbanco.asientocontable=libros_diariosid
WHERE
movbanco.asientocontable = 0
AND movbanco.documentosid = nDocumentoid
AND movbanco.origen = 'Pagos';
UPDATE
cuentasporpagar 
SET
cuentasporpagar.asientocontable=libros_diariosid
WHERE
cuentasporpagar.origen = 'Pagos'
AND cuentasporpagar.asientocontable = 0
AND cuentasporpagar.pagosid = nDocumentoid;
UPDATE
Pagos
SET
Pagos.asientocontable = libros_diariosid
WHERE
Pagos.Pagosid = nDocumentoid
AND Pagos.asientocontable = 0;

-- Finalizamos la transaccion
COMMIT;

-- Cerramos el Cursor
CLOSE Datos_Asiento;

-- Devolvemos el ID del Asiento Contable
select libros_diariosid;

END
;;
