DECLARE usuariocreacion varchar(25);
DECLARE centros_costosid int(11);
DECLARE concepto varchar(200);
DECLARE referencia varchar(15);
DECLARE valor decimal(16,8) DEFAULT 0;
DECLARE codigocontable varchar(30);
DECLARE codigoasiento varchar(10);
DECLARE gravocabecera INT DEFAULT FALSE;
