talleres_repuestos.centros_costosid AS centros_costosid,
LEFT(talleres_seguimientos.mantenimiento,200) AS concepto, 
talleres_seguimientos.talleres_seguimientosid AS referencia,
-ROUND(SUM((talleres_repuestos.costo)*(talleres_repuestos.cantidad)),8) AS valor, 
productos.cuentacontable_inventarios AS codigocontable
FROM talleres_seguimientos
INNER JOIN talleres_repuestos ON talleres_repuestos.talleres_seguimientosid = talleres_seguimientos.talleres_seguimientosid
INNER JOIN productos ON talleres_repuestos.productosid = productos.productosid
WHERE 	
talleres_seguimientos.asientocontable = 0
AND  talleres_seguimientos.talleres_seguimientosid = nDocumentoid
AND productos.servicio =0 
AND productos.bien =0 		
GROUP BY 
productos.cuentacontable_inventarios
HAVING
SUM((talleres_repuestos.costo)*(talleres_repuestos.cantidad))<>0;

-- Controlamos si hubo error
DECLARE exit handler FOR SQLEXCEPTION, SQLWARNING
  BEGIN
  	SHOW WARNINGS limit 1;
    ROLLBACK;
    RESIGNAL;
  END;

-- Declaramos el control de salida del loop
DECLARE CONTINUE HANDLER FOR NOT FOUND SET termino = TRUE;

-- Abrimos el Cursor
OPEN Datos_Asiento;

-- Iniciamos la Transaccion
START TRANSACTION;

-- Leeemos el Cursor
read_loop: LOOP
FETCH Datos_Asiento INTO fechamovimiento,centros_costosid, concepto, referencia, valor, codigocontable;

-- Verificamos si no hay mas registros
IF termino THEN
LEAVE read_loop;
END IF;

SET diferencia = diferencia+(Round(valor,2));
-- Sumamos valores de debe y haber
IF valor<0 THEN
  SET haber = (haber + (Abs((valor))));
ELSE
  SET debe  = (debe + (Abs((valor))));
END IF;

-- INSERTAMOS LA CABECERA DEL ASIENTO
  IF gravocabecera=FALSE THEN
    -- Optenemos el nuevo secuencial
    call SP_Consulta_Secuencias_Internas('LIBRODIARIO',codigoasiento);
  
    -- Insertamos Registro Cabecera
    INSERT INTO libros_diarios 
    (
      codigoasiento, 
      fecha, 
      referencia, 
      concepto, 
      origen, 
      usuariocreacion, 
      fechacreacion
    ) 
    VALUES 
    (
      codigoasiento,
      fechamovimiento,
      referencia, 
      concepto,
      'Talleres', 
      sUsuario, 
      NOW(3)
    );
   
   -- obtenemos el ultimo ID insertado
    SET libros_diariosid=(select LAST_INSERT_ID());
    
    -- Actualizamos el secuencial de libros diarios
    call SP_Actualiza_Secuencias_Internas('LIBRODIARIO');

    -- Ponemos que gravo la cabecera
    SET gravocabecera=TRUE;

  END IF;

-- INSERTAMOS LOS DETALLES
SET valor = round(valor,2);
INSERT INTO libros_diarios_detalles
( 	
libros_diariosid,	
codigocontable,	
centros_costosid,	
referencia,	
concepto,	
importe
)
VALUES
( 
libros_diariosid,	
codigocontable,	
centros_costosid,	
referencia,	
concepto,	
valor
 );

-- Toma la primer cuenta del asiento contable
IF cuenta_fija=0 THEN 
SET cuenta_fija = (select LAST_INSERT_ID());
END IF;

END LOOP;

CALL SP_Contabiliza_Verificar_Asiento(libros_diariosid,verificado);


-- Cuadramos el asiento contable si esta descuadrado
IF diferencia<0.11 AND diferencia>-0.11 AND diferencia<>0  THEN
UPDATE libros_diarios_detalles
SET
libros_diarios_detalles.importe = libros_diarios_detalles.importe-diferencia
WHERE
libros_diarios_detalles.libros_diarios_detallesid = cuenta_fija;
SET diferencia=0;
END IF;

-- Verificamos si el asiento esta cuadrado
IF diferencia<>0 THEN
SET verificado=0;
END IF;

-- Actualizamos el libro diario
SET debe = Round(debe,2);
SET haber = Round(haber,2);
UPDATE 
libros_diarios
SET
libros_diarios.debito = debe,
libros_diarios.credito = haber,
libros_diarios.mayorizado = verificado,
libros_diarios.verificado = verificado,
libros_diarios.fechamodificacion = libros_diarios.fechamodificacion
WHERE
libros_diarios.libros_diariosid = libros_diariosid;


-- Actualizamos el ID del libro diario a el movimiento de Caja
  UPDATE 
 	talleres_seguimientos 
SET 
talleres_seguimientos.asientocontable = libros_diariosid,
talleres_seguimientos.fechamodificiacion = talleres_seguimientos.fechamodificiacion
WHERE 
 talleres_seguimientos.asientocontable = 0 
AND talleres_seguimientos.talleres_seguimientosid = nDocumentoid;	

-- Finalizamos la transaccion
COMMIT;

-- Cerramos el Cursor
CLOSE Datos_Asiento;

-- Devolvemos el ID del Asiento Contable
select libros_diariosid;

END
;;
delimiter ;

-- ----------------------------
-- Procedure structure for SP_Contabiliza_Verificar_Asiento
-- ----------------------------
DROP PROCEDURE IF EXISTS `SP_Contabiliza_Verificar_Asiento`;
delimiter ;;
CREATE PROCEDURE `SP_Contabiliza_Verificar_Asiento`(IN nDocumentoid BIGINT, OUT verificado TINYINT(1))
  SQL SECURITY INVOKER
BEGIN

DECLARE termino tinyint(1) DEFAULT 0;
DECLARE codigocontable varchar(30) DEFAULT '';

-- Datos Validacion cuenta de grupo
DECLARE datos_validacion1 CURSOR FOR
SELECT
   libros_diarios_detalles.codigocontable 
FROM
   libros_diarios_detalles 
   LEFT JOIN
      cuentas_contables 
      ON libros_diarios_detalles.codigocontable = cuentas_contables.codigocontable 
WHERE
   RIGHT(cuentas_contables.codigocontable, 1) = '.' 
   AND libros_diarios_detalles.libros_diariosid = nDocumentoid;

-- Datos Validacion ceunta no existe en plan de cuentas
DECLARE datos_validacion2 CURSOR FOR
SELECT
   libros_diarios_detalles.codigocontable 
FROM
   libros_diarios_detalles 
   LEFT JOIN
      cuentas_contables 
      ON libros_diarios_detalles.codigocontable = cuentas_contables.codigocontable 
WHERE
   cuentas_contables.codigocontable IS NULL 
   AND libros_diarios_detalles.libros_diariosid =nDocumentoid;


-- Declaramos el control de salida del loop
DECLARE CONTINUE HANDLER FOR NOT FOUND SET termino = 1;

set verificado=1;

-- Abrimos el Cursor
OPEN datos_validacion1;

-- Leeemos el Cursor
read_loop: LOOP
FETCH datos_validacion1 INTO codigocontable;

-- Verificamos si hay cuenta contable que termina en punto
IF codigocontable<>'' THEN
set verificado=0;
LEAVE read_loop;
END IF;

-- Verificamos si no hay mas registros
IF termino=1 THEN
LEAVE read_loop;
END IF;

END LOOP;

-- Cerrar Cursor 
CLOSE datos_validacion1;

-- Abrimos el Cursor
OPEN datos_validacion2;

-- Reiniciamos la variable
set termino=0;

-- Leeemos el Cursor
read_loop: LOOP
FETCH datos_validacion2 INTO codigocontable;

-- Verificamos si existe registro
IF codigocontable<>'' THEN
set verificado=0;
LEAVE read_loop;
END IF;

-- Verificamos si no hay mas registros
IF termino=1 THEN
LEAVE read_loop;
END IF;
END LOOP;

CLOSE datos_validacion2;


END
;;
delimiter ;

-- ----------------------------
-- Procedure structure for SP_cuentas_contables_ABC
-- ----------------------------
DROP PROCEDURE IF EXISTS `SP_cuentas_contables_ABC`;
delimiter ;;
CREATE PROCEDURE `SP_cuentas_contables_ABC`(IN pAccion varchar(1), IN pRegistrosJson json)
BEGIN
  DECLARE vJsonEsValido int;
  DECLARE vItems int;
  DECLARE vIndex bigint UNSIGNED DEFAULT 0;
  DECLARE vErrorMensaje text;
  DECLARE vRegistroAnterior longtext;


  # VARIABLES DE LOS DATOS DE LA TABLA
  DECLARE p_cuentas_contablesid int(11);
  DECLARE p_codigocontable varchar(30) DEFAULT '';
  DECLARE p_descripcion varchar(100) DEFAULT '';
  DECLARE p_nivel tinyint(4) DEFAULT 0;
  DECLARE p_tipo varchar(1) DEFAULT '';
  DECLARE p_fechacreacion datetime(3) DEFAULT '0000-00-00 00:00:00.000';
  DECLARE p_usuariocreacion varchar(25) DEFAULT '';
  DECLARE p_fechamodificacion datetime(3) DEFAULT '0000-00-00 00:00:00.000';
  DECLARE p_usuariomodificacion varchar(25) DEFAULT '';


  # VARIABLE DE LOS DATOS DE LA AUDITORIA
  DECLARE p_sis_subcategoriasid int(11) DEFAULT 0;
  DECLARE p_sis_empresasid int(11) DEFAULT 0;
  DECLARE p_sis_usuariosid varchar(20) DEFAULT '';
  DECLARE p_equipo varchar(50) DEFAULT '';
  DECLARE p_tipooperacion varchar(50) DEFAULT '';
  DECLARE p_detalle longtext;

  # CONTROLAMOS SI HAY ERROR
  DECLARE EXIT HANDLER FOR SQLEXCEPTION, SQLWARNING
  BEGIN
    GET DIAGNOSTICS CONDITION 1 vErrorMensaje = MESSAGE_TEXT;
    SELECT
      JSON_ARRAYAGG(JSON_OBJECT('procesado', FALSE, 'mensaje', vErrorMensaje)) AS resultado;
    ROLLBACK;
  END;
  # VALIDAMOS SI EL OBJETO JSON ES VALIDO 
  SET vJsonEsValido = JSON_VALID(pRegistrosJson);

  IF vJsonEsValido = 0 THEN
    # EL OBJETO JSON NO ES VALIDO
    SELECT
      CASE WHEN LOCATE('Cannot delete or update a parent row',vErrorMensaje)>0 THEN JSON_ARRAYAGG(JSON_OBJECT('procesado', FALSE, 'mensaje', 'No Se Puede Eliminar, Cuenta Contable en Uso')) ELSE JSON_ARRAYAGG(JSON_OBJECT('procesado', FALSE, 'mensaje', vErrorMensaje)) END AS resultado;
  ELSE

    # VALIDAMOS QUE TENGA ALMENOS UN ELEMENTO
    SET vItems = JSON_LENGTH(pRegistrosJson, '$.cabecera');

    IF vItems > 0 THEN
      START TRANSACTION;
        WHILE vIndex < vItems DO

          # DATOS TABLA
          SET p_cuentas_contablesid = IFNULL(JSON_UNQUOTE(JSON_EXTRACT(pRegistrosJson, CONCAT('$.cabecera[', vIndex, '].cuentas_contablesid'))), p_cuentas_contablesid);
          SET p_codigocontable = IFNULL(JSON_UNQUOTE(JSON_EXTRACT(pRegistrosJson, CONCAT('$.cabecera[', vIndex, '].codigocontable'))), p_codigocontable);
          SET p_descripcion = IFNULL(JSON_UNQUOTE(JSON_EXTRACT(pRegistrosJson, CONCAT('$.cabecera[', vIndex, '].descripcion'))), p_descripcion);
          SET p_nivel = IFNULL(JSON_UNQUOTE(JSON_EXTRACT(pRegistrosJson, CONCAT('$.cabecera[', vIndex, '].nivel'))), p_nivel);
          SET p_tipo = IFNULL(JSON_UNQUOTE(JSON_EXTRACT(pRegistrosJson, CONCAT('$.cabecera[', vIndex, '].tipo'))), p_tipo);


          # DATOS AUDITORIA
          SET p_sis_subcategoriasid = JSON_UNQUOTE(JSON_EXTRACT(pRegistrosJson, CONCAT('$.cabecera[', vIndex, '].sis_subcategoriasid')));
          SET p_sis_empresasid = JSON_UNQUOTE(JSON_EXTRACT(pRegistrosJson, CONCAT('$.cabecera[', vIndex, '].sis_empresasid')));
          SET p_sis_usuariosid = JSON_UNQUOTE(JSON_EXTRACT(pRegistrosJson, CONCAT('$.cabecera[', vIndex, '].sis_usuariosid')));
          SET p_equipo = JSON_UNQUOTE(JSON_EXTRACT(pRegistrosJson, CONCAT('$.cabecera[', vIndex, '].equipo')));


          CASE pAccion
            WHEN 'C' THEN SET p_tipooperacion = 'N';
                SET p_fechacreacion = NOW(3);
                SET p_usuariocreacion = JSON_UNQUOTE(JSON_EXTRACT(pRegistrosJson, CONCAT('$.cabecera[', vIndex, '].usuariocreacion')));
                SET p_fechamodificacion = NULL;
                SET p_usuariomodificacion = '';
                SET p_detalle = REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(JSON_INSERT('{}', '$.cuentas_contables', JSON_EXTRACT(pRegistrosJson, CONCAT('$.cabecera[', vIndex, ']'))), '"[', '['), ']"', ']'), '\\', ''), '"{', '{'), '}"', '}');

                # INSERTAMOS LOS REGISTROS
                INSERT INTO cuentas_contables (cuentas_contablesid, codigocontable, descripcion, nivel, tipo, fechacreacion, usuariocreacion, fechamodificacion, usuariomodificacion)
                  VALUES (p_cuentas_contablesid, p_codigocontable, p_descripcion, p_nivel, p_tipo, p_fechacreacion, p_usuariocreacion, p_fechamodificacion, p_usuariomodificacion);

                SET p_cuentas_contablesid = LAST_INSERT_ID();

            WHEN 'M' THEN SET p_tipooperacion = 'M';
                SET p_fechamodificacion = NOW(3);
                SET p_usuariomodificacion = JSON_UNQUOTE(JSON_EXTRACT(pRegistrosJson, CONCAT('$.cabecera[', vIndex, '].usuariomodificacion')));


                SET vRegistroAnterior = (SELECT
                    JSON_OBJECT
                    (
                    'cuentas_contablesid', cuentas_contablesid,
                    'codigocontable', codigocontable,
                    'descripcion', descripcion,
                    'nivel', nivel,
                    'tipo', tipo,
                    'fechamodificacion', fechamodificacion,
                    'usuariomodificacion', usuariomodificacion
                    )
                  FROM cuentas_contables
                  WHERE cuentas_contables.cuentas_contablesid = p_cuentas_contablesid);

                SET p_detalle = REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(JSON_INSERT('{}', '$.cuentas_contables', vRegistroAnterior), '"[', '['), ']"', ']'), '\\', ''), '"{', '{'), '}"', '}');

                # ACTUALIZAMOS LOS REGISTROS
                UPDATE cuentas_contables
                SET cuentas_contablesid = p_cuentas_contablesid,
                    codigocontable = p_codigocontable,
                    descripcion = p_descripcion,
                    nivel = p_nivel,
                    tipo = p_tipo,
                    fechamodificacion = p_fechamodificacion,
                    usuariomodificacion = p_usuariomodificacion
                WHERE cuentas_contablesid = p_cuentas_contablesid;

            WHEN 'E' THEN SET p_tipooperacion = 'E';
                SET p_detalle = REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(JSON_INSERT('{}', '$.cuentas_contables', JSON_EXTRACT(pRegistrosJson, CONCAT('$.cabecera[', vIndex, ']'))), '"[', '['), ']"', ']'), '\\', ''), '"{', '{'), '}"', '}');

                # ELIMINAMOS LOS REGISTROS
                DELETE
                  FROM cuentas_contables
                WHERE cuentas_contablesid = p_cuentas_contablesid;

          END CASE;

          # INSERTAMOS LA AUDITORIA
          CALL sistemaperseo.SP_ABC_sis_log_sistema(p_sis_subcategoriasid, p_sis_empresasid, p_sis_usuariosid, p_tipooperacion, p_detalle, p_equipo);

          SET vIndex = vIndex + 1;
        END WHILE;
      COMMIT;


      # RETORNAMOS LA RESPUESTAS
      IF pAccion IN ('C', 'M') THEN

        SELECT
          cuentas_contables.cuentas_contablesid,
          cuentas_contables.codigocontable,
          cuentas_contables.descripcion,
          cuentas_contables.nivel,
          cuentas_contables.tipo,
          cuentas_contables.fechacreacion,
          cuentas_contables.usuariocreacion,
          cuentas_contables.fechamodificacion,
          cuentas_contables.usuariomodificacion,
          (SELECT
              JSON_ARRAYAGG(JSON_OBJECT('procesado', TRUE, 'mensaje', 'Completado con Éxito'))) AS resultado
        FROM cuentas_contables
        WHERE cuentas_contables.cuentas_contablesid = p_cuentas_contablesid;

      ELSE
        SELECT
          JSON_ARRAYAGG(JSON_OBJECT('procesado', TRUE, 'mensaje', 'Completado con Éxito')) AS resultado;
      END IF;
    END IF;
  END IF;
END
;;
delimiter ;

-- ----------------------------
-- Procedure structure for SP_cuentas_contables_ConsultarID
-- ----------------------------
DROP PROCEDURE IF EXISTS `SP_cuentas_contables_ConsultarID`;
delimiter ;;
CREATE PROCEDURE `SP_cuentas_contables_ConsultarID`(IN p_cuentas_contablesid int(11))
BEGIN

  SELECT
    cuentas_contables.cuentas_contablesid,
    cuentas_contables.codigocontable,
    cuentas_contables.descripcion,
    cuentas_contables.nivel,
    cuentas_contables.tipo,
    cuentas_contables.fechacreacion,
    cuentas_contables.usuariocreacion,
    cuentas_contables.fechamodificacion,
    cuentas_contables.usuariomodificacion
  FROM cuentas_contables
  WHERE cuentas_contables.cuentas_contablesid = p_cuentas_contablesid;

END
;;
delimiter ;

-- ----------------------------
-- Procedure structure for SP_Facturas_Lotes
-- ----------------------------
DROP PROCEDURE IF EXISTS `SP_Facturas_Lotes`;
delimiter ;;
CREATE PROCEDURE `SP_Facturas_Lotes`(IN dEmision date,
IN dMes date,
IN nFacturador int,
IN nCaja int,
IN nSecuencia int,
IN sFPSRI varchar(2),
IN nGrupo int,
IN sUser varchar(25))
BEGIN

  -- Variables para manejo de datos
  DECLARE v_finished integer DEFAULT 0;
  DECLARE v_producto_id bigint(20);
  DECLARE v_precio decimal(20, 8);
  DECLARE v_descuento decimal(20, 8);
  DECLARE v_ice_porcentaje decimal(20, 8);
  DECLARE v_ice_valor decimal(20, 8);
  DECLARE v_sri_tipos_ivas_codigo varchar(10);
  DECLARE v_servicio tinyint(4);
  DECLARE v_costoactual decimal(20, 8);
  DECLARE v_unidadinterna int(11);
  DECLARE v_ivavalor decimal(20, 8);
  DECLARE v_tipoiva tinyint(4);

  -- Variables para la factura (TODOS LOS CAMPOS)
  DECLARE p_facturasid bigint(20);
  DECLARE p_sucursalesid bigint(20) DEFAULT 1;
  DECLARE p_secuenciasid int(11) DEFAULT 1;
  DECLARE p_sri_documentoscodigo varchar(3) DEFAULT '';
  DECLARE p_forma_pago_empresaid int(11) DEFAULT 2;
  DECLARE p_forma_pago_sri_codigo varchar(2) DEFAULT '';
  DECLARE p_cajasid int(11) DEFAULT 1;
  DECLARE p_bancosid int(11) DEFAULT 1;
  DECLARE p_centros_costosid int(11) DEFAULT 1;
  DECLARE p_almacenesid int(11) DEFAULT 1;
  DECLARE p_facturadoresid int(11) DEFAULT 1;
  DECLARE p_vendedoresid int(11) DEFAULT 1;
  DECLARE p_clientesid bigint(20) DEFAULT 1;
  DECLARE p_clientes_sucursalesid bigint(20) DEFAULT 0;
  DECLARE p_clientes_contratosid bigint(20) DEFAULT 0;
  DECLARE p_tarifasid bigint(20) DEFAULT 1;
  DECLARE p_establecimiento varchar(3) DEFAULT '';
  DECLARE p_puntoemision varchar(3) DEFAULT '';
  DECLARE p_secuencial varchar(15) DEFAULT '';
  DECLARE p_emision datetime(3) DEFAULT '0000-00-00 00:00:00.000';
  DECLARE p_vence date DEFAULT '0000-00-00';
  DECLARE p_relaciondocumentoid bigint(20) DEFAULT 0;
  DECLARE p_concepto varchar(150) DEFAULT '';
  DECLARE p_promocionesid bigint(20) DEFAULT 1;
  DECLARE p_subtotal decimal(20, 8) DEFAULT 0.00;
  DECLARE p_total_descuento decimal(20, 8) DEFAULT 0.00;
  DECLARE p_subtotalconiva decimal(20, 8) DEFAULT 0.00;
  DECLARE p_subtotalconiva2 decimal(20, 8) DEFAULT 0.00;
  DECLARE p_subtotalsiniva decimal(20, 8) DEFAULT 0.00;
  DECLARE p_subtotalnoobjetoiva decimal(20, 8) DEFAULT 0.00;
  DECLARE p_subtotalexentoiva decimal(20, 8) DEFAULT 0.00;
  DECLARE p_subtotalneto decimal(20, 8) DEFAULT 0.00;
  DECLARE p_total_ice decimal(20, 8) DEFAULT 0.00;
  DECLARE p_total_iva decimal(16, 4) DEFAULT 0.00;
  DECLARE p_total_iva2 decimal(16, 4) DEFAULT 0.00;
  DECLARE p_propina decimal(14, 2) DEFAULT 0.00;
  DECLARE p_total decimal(20, 8) DEFAULT 0.00;
  DECLARE p_totalneto decimal(20, 8) DEFAULT 0.00;
  DECLARE p_totalretenidoiva decimal(14, 2) DEFAULT 0.00;
  DECLARE p_totalretenidorenta decimal(14, 2) DEFAULT 0.00;
  DECLARE p_puntoemisionretencion varchar(3) DEFAULT '';
  DECLARE p_establecimientoretencion varchar(3) DEFAULT '';
  DECLARE p_emisionretencion date DEFAULT '0000-00-00';
  DECLARE p_secuenciaretencion varchar(10) DEFAULT '';
  DECLARE p_autorizacionretencion varchar(49) DEFAULT '';
  DECLARE p_relacionemision date DEFAULT '0000-00-00';
  DECLARE p_relacionsecuencia varchar(10) DEFAULT '';
  DECLARE p_relacionestablecimiento varchar(3) DEFAULT '';
  DECLARE p_relacionpuentoemision varchar(3) DEFAULT '';
  DECLARE p_numeroautorizacion varchar(49) DEFAULT '';
  DECLARE p_autorizacionfecha datetime(3) DEFAULT '0000-00-00 00:00:00.000';
  DECLARE p_claveacceso varchar(49) DEFAULT '';
  DECLARE p_autorizacionintentos tinyint(3) DEFAULT 0;
  DECLARE p_de_enviado tinyint(4) DEFAULT 0;
  DECLARE p_mensajeerror varchar(500) DEFAULT '';
  DECLARE p_asientocontable bigint(20) DEFAULT 0;
  DECLARE p_asientocosto bigint(20) DEFAULT 0;
  DECLARE p_saldo decimal(14, 2) DEFAULT 0.00;
  DECLARE p_tipoplazo int(11) DEFAULT 0;
  DECLARE p_plazo int(11) DEFAULT 0;
  DECLARE p_plazodias int(11) DEFAULT 0;
  DECLARE p_numeropagos int(11) DEFAULT 1;
  DECLARE p_interes decimal(14, 2) DEFAULT 0.00;
  DECLARE p_valorcuota decimal(14, 2) DEFAULT 0.00;
  DECLARE p_totalacobrar decimal(14, 2) DEFAULT 0.00;
  DECLARE p_tipocredito tinyint(3) DEFAULT 0;
  DECLARE p_cambio decimal(12, 2) DEFAULT 0.00;
  DECLARE p_anulado tinyint(4) DEFAULT 0;
  DECLARE p_observacion varchar(1500) DEFAULT '';
  DECLARE p_archivo_xml longblob DEFAULT NULL;
  DECLARE p_restaurante_mesasid int(11) DEFAULT 0;
  DECLARE p_receptor_clientesid bigint(20) DEFAULT 0;
  DECLARE p_receptor_clientes_sucursalesid bigint(20) DEFAULT 0;
  DECLARE p_sucursales_destinosid bigint(20) DEFAULT 0;
  DECLARE p_uuid varchar(36) DEFAULT '';
  DECLARE p_estado tinyint(3) DEFAULT 0;
  DECLARE p_estado_sync tinyint(3) DEFAULT 0;
  DECLARE p_impresa tinyint(4) DEFAULT 0;
  DECLARE p_origen varchar(15) DEFAULT 'GeneradoLotes';
  DECLARE p_fechacreacion datetime(3) DEFAULT '0000-00-00 00:00:00.000';
  DECLARE p_fechamodificacion datetime(3) DEFAULT '0000-00-00 00:00:00.000';
  DECLARE p_usuariocreacion varchar(25) DEFAULT 'GeneradoLotes';
  DECLARE p_usuariomodificacion varchar(25) DEFAULT '';

  -- Variables para cálculos de totales
  DECLARE v_xSubtotalNoObjeto decimal(20, 8) DEFAULT 0;
  DECLARE v_xSubtotalExento decimal(20, 8) DEFAULT 0;
  DECLARE v_xSubtotalSinDescuentoConIVA decimal(20, 8) DEFAULT 0;
  DECLARE v_xSubtotalSinDescuentoConIVA2 decimal(20, 8) DEFAULT 0;
  DECLARE v_xSubtotalSinDescuentoSinIVA decimal(20, 8) DEFAULT 0;
  DECLARE v_xSubtotalDescuentoConIVA decimal(20, 8) DEFAULT 0;
  DECLARE v_xSubtotalDescuentoConIVA2 decimal(20, 8) DEFAULT 0;
  DECLARE v_xSubtotalDescuentoSinIVA decimal(20, 8) DEFAULT 0;
  DECLARE v_xTotal_DescuentoSinIVA decimal(20, 8) DEFAULT 0;
  DECLARE v_xTotal_DescuentoConIVA decimal(20, 8) DEFAULT 0;
  DECLARE v_xDescuentoSinIVA decimal(20, 8) DEFAULT 0;
  DECLARE v_xDescuentoConIVA decimal(20, 8) DEFAULT 0;
  DECLARE v_xICE decimal(20, 8) DEFAULT 0;
  DECLARE v_xTotal_IVA decimal(20, 8) DEFAULT 0;
  DECLARE v_xTotal_IVA2 decimal(20, 8) DEFAULT 0;
  DECLARE v_xTotal_ICE decimal(20, 8) DEFAULT 0;

  -- Variables auxiliares para cálculos
  DECLARE v_xPrecio decimal(20, 8);
  DECLARE v_xIva decimal(20, 8);
  DECLARE v_xCantD decimal(20, 8);
  DECLARE v_xTotSIva decimal(20, 8);
  DECLARE v_xTotStot decimal(20, 8);
  DECLARE v_xTotDeta decimal(20, 8);
  DECLARE v_xDescuen decimal(20, 8);
  DECLARE v_xDescuento decimal(20, 8);
  DECLARE v_baseParaIVA decimal(20, 8); -- Base que incluye ICE para cálculo de IVA
  DECLARE v_porcentajeIVA decimal(5, 2) DEFAULT 15.00; -- Porcentaje de IVA configurable

  -- Variables para otros datos
  DECLARE v_mes_texto varchar(20);
  DECLARE v_anio_texto varchar(4);
  DECLARE v_fecha_clave varchar(8);
  DECLARE v_ruc varchar(13);
  DECLARE v_ambiente varchar(1);
  DECLARE v_electronica tinyint(4);
  DECLARE v_facturas_detallesid bigint(20);
  DECLARE v_contador_facturas int DEFAULT 0;

  -- Cursores
  DECLARE cursor_clientes CURSOR FOR
  SELECT
    clientesid
  FROM clientes
  WHERE clientes_gruposid = nGrupo 	
AND
clientesid > 1
AND estado = 1;

  DECLARE cursor_servicios CURSOR FOR
  SELECT
    cp.productosid,
    cp.precio,
    cp.descuento,
    p.ice_porcentaje,
    p.ice_valor,
    p.sri_tipos_ivas_codigo,
    p.servicio,
    p.costoactual,
    p.unidadinterna,
    sti.valor AS ivavalor,
    sti.sri_tipos_ivas_codigo AS tipoiva
  FROM clientes_precios cp
    INNER JOIN productos p
      ON p.productosid = cp.productosid
    INNER JOIN sri_tipos_ivas sti
      ON sti.sri_tipos_ivas_codigo = p.sri_tipos_ivas_codigo
  WHERE cp.clientesid = p_clientesid
  AND cp.origen = 1 AND p.estado = 1;

  DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_finished = 1;

  -- Variables para manejo de errores
  DECLARE EXIT HANDLER FOR SQLEXCEPTION
  BEGIN
    ROLLBACK;
    RESIGNAL;
  END;

  -- Iniciar transacción
  START TRANSACTION;

    -- Inicializar variables
    SET p_fechacreacion = NOW();
    SET p_fechamodificacion = NOW();
    SET p_emision = STR_TO_DATE( CONCAT( dEmision, ' ', CURRENT_TIME ), '%Y-%m-%d %H:%i:%s' ) ;
    SET p_vence = LAST_DAY(dMes);
    SET p_cajasid = nCaja;
    SET p_facturadoresid = nFacturador;
    SET p_secuenciasid = nSecuencia;
    SET p_forma_pago_sri_codigo = sFPSRI;
    SET p_usuariomodificacion = sUser;

    -- Construir concepto con mes y año
    SET v_anio_texto = YEAR(dMes);
    CASE MONTH(dMes)
      WHEN 1 THEN SET v_mes_texto = 'Enero';
      WHEN 2 THEN SET v_mes_texto = 'Febrero';
      WHEN 3 THEN SET v_mes_texto = 'Marzo';
      WHEN 4 THEN SET v_mes_texto = 'Abril';
      WHEN 5 THEN SET v_mes_texto = 'Mayo';
      WHEN 6 THEN SET v_mes_texto = 'Junio';
      WHEN 7 THEN SET v_mes_texto = 'Julio';
      WHEN 8 THEN SET v_mes_texto = 'Agosto';
      WHEN 9 THEN SET v_mes_texto = 'Septiembre';
      WHEN 10 THEN SET v_mes_texto = 'Octubre';
      WHEN 11 THEN SET v_mes_texto = 'Noviembre';
      WHEN 12 THEN SET v_mes_texto = 'Diciembre';
    END CASE;

    SET p_concepto = CONCAT('Factura mes ', v_mes_texto, ' ', v_anio_texto);

    -- Obtener datos de la secuencia
    SELECT
      secuencias.establecimiento,
      secuencias.puntoemision,
      secuencias.sri_documentoscodigo,
      secuencias.autorizacion,
      secuencias.documentoelectronico INTO p_establecimiento,
    p_puntoemision,
    p_sri_documentoscodigo,
    p_numeroautorizacion,
    v_electronica
    FROM secuencias
    WHERE secuenciasid = nSecuencia;

    -- Obtener RUC y ambiente
    SELECT
      parametros_empresa.identificacion,
      parametros_empresa.de_ambiente INTO v_ruc, v_ambiente
    FROM parametros_empresa
    LIMIT 1;

    -- Abrir cursor de clientes
    OPEN cursor_clientes;

  read_clientes:
    LOOP
      SET v_finished = 0;
      FETCH cursor_clientes INTO p_clientesid;

      IF v_finished = 1 THEN
        LEAVE read_clientes;
      END IF;

      -- Verificar si ya existe una factura para este cliente en este mes
      IF EXISTS (SELECT
            1
          FROM facturas
          WHERE clientesid = p_clientesid
          AND YEAR(emision) = YEAR(dMes)
          AND MONTH(emision) = MONTH(dMes)
          AND concepto = p_concepto) THEN
        ITERATE read_clientes;
      END IF;

      -- Obtener vendedor y tarifa del cliente
      SELECT
        vendedoresid,
        tarifasid INTO p_vendedoresid, p_tarifasid
      FROM clientes
      WHERE clientesid = p_clientesid;

      -- Generar secuencial
      CALL SP_Fac_Secuencia(nSecuencia, p_secuencial);

      -- Generar clave de acceso si es electrónica
      IF v_electronica = 1 THEN
        SET v_fecha_clave = DATE_FORMAT(dEmision, '%d%m%Y');
        CALL SP_Fac_GenClave(v_fecha_clave,
        p_sri_documentoscodigo,
        v_ruc,
        v_ambiente,
        CONCAT(p_establecimiento, p_puntoemision),
        p_secuencial,
        '12345678',
        '1',
        p_claveacceso);
        SET p_numeroautorizacion = '';
      ELSE
        SET p_claveacceso = '';
        -- Para facturas físicas, usar el número de autorización de la secuencia
        SET p_numeroautorizacion = (SELECT
            autorizacion
          FROM secuencias
          WHERE secuenciasid = nSecuencia);
      END IF;

      -- INICIALIZAR VARIABLES DE TOTALES PARA ESTE CLIENTE
      SET v_xSubtotalNoObjeto = 0;
      SET v_xSubtotalExento = 0;
      SET v_xSubtotalSinDescuentoConIVA = 0;
      SET v_xSubtotalSinDescuentoConIVA2 = 0;
      SET v_xSubtotalSinDescuentoSinIVA = 0;
      SET v_xSubtotalDescuentoConIVA = 0;
      SET v_xSubtotalDescuentoConIVA2 = 0;
      SET v_xSubtotalDescuentoSinIVA = 0;
      SET v_xTotal_DescuentoSinIVA = 0;
      SET v_xTotal_DescuentoConIVA = 0;
      SET v_xTotal_IVA = 0;
      SET v_xTotal_IVA2 = 0;
      SET v_xTotal_ICE = 0;

      -- CÁLCULO DE TOTALES POR PRODUCTO/SERVICIO
      OPEN cursor_servicios;

    read_servicios:
      LOOP
        FETCH cursor_servicios INTO v_producto_id, v_precio, v_descuento, v_ice_porcentaje,
        v_ice_valor, v_sri_tipos_ivas_codigo, v_servicio,
        v_costoactual, v_unidadinterna, v_ivavalor, v_tipoiva;

        IF v_finished = 1 THEN
          LEAVE read_servicios;
        END IF;

        -- CALCULAR TOTALES SIGUIENDO LA LÓGICA DE WINDEV
        SET v_xPrecio = v_precio;
        SET v_xIva = v_ivavalor;
        SET v_xCantD = 1;
        SET v_xTotSIva = v_xCantD * v_xPrecio;
        SET v_xTotStot = v_xCantD * v_xPrecio;
        SET v_xTotDeta = v_xCantD * v_xPrecio;
        SET v_xDescuen = 0;
        SET v_xICE = 0;
        SET v_xDescuento = v_descuento;

        -- Aplicar descuento si existe
        IF v_xDescuento > 0 THEN
          SET v_xDescuentoSinIVA = v_xCantD * v_xPrecio * (v_xDescuento / 100);
          SET v_xDescuentoConIVA = ROUND((v_xTotSIva + ROUND(v_xTotSIva * (v_xIva / 100), 3)) * (v_xDescuento / 100), 4);
        ELSE
          SET v_xDescuentoConIVA = 0;
          SET v_xDescuentoSinIVA = 0;
        END IF;

        -- Acumular descuentos
        SET v_xTotal_DescuentoSinIVA = v_xTotal_DescuentoSinIVA + v_xDescuentoSinIVA;
        SET v_xTotal_DescuentoConIVA = v_xTotal_DescuentoConIVA + v_xDescuentoConIVA;

        SET v_xDescuen = v_xPrecio * (v_xDescuento / 100);
        SET v_xTotSIva = v_xCantD * (v_xPrecio - v_xDescuen);

        -- Calcular ICE si aplica
        IF v_ice_porcentaje > 0 THEN
          SET v_xICE = ROUND(v_xTotSIva * (v_ice_porcentaje / 100), 3);
          SET v_xTotal_ICE = v_xTotal_ICE + v_xICE;
        ELSEIF v_ice_valor > 0 THEN
          SET v_xICE = ROUND(v_xCantD * v_ice_valor, 3);
          SET v_xTotal_ICE = v_xTotal_ICE + v_xICE;
        END IF;

        SET v_xTotDeta = ROUND(v_xTotSIva + ROUND(v_xTotSIva * (v_xIva / 100), 3), 2);

        -- Clasificar por tipo de IVA
        IF v_xIva > 0 THEN
          IF v_xIva != 5 THEN
            SET v_xSubtotalSinDescuentoConIVA = v_xSubtotalSinDescuentoConIVA + v_xTotStot + v_xICE;
            SET v_xSubtotalDescuentoConIVA = v_xSubtotalDescuentoConIVA + v_xTotSIva;
            SET v_xTotal_IVA = v_xTotal_IVA + ROUND(v_xTotSIva * (v_xIva / 100), 3);
          ELSE
            SET v_xSubtotalSinDescuentoConIVA2 = v_xSubtotalSinDescuentoConIVA2 + v_xTotStot + v_xICE;
            SET v_xSubtotalDescuentoConIVA2 = v_xSubtotalDescuentoConIVA2 + v_xTotSIva;
            SET v_xTotal_IVA2 = v_xTotal_IVA2 + ROUND(v_xTotSIva * (v_xIva / 100), 3);
          END IF;
        ELSE
          -- Sin IVA - clasificar por tipo
          CASE v_tipoiva
            WHEN 6 THEN SET v_xSubtotalNoObjeto = v_xSubtotalNoObjeto + v_xTotSIva;
            WHEN 7 THEN SET v_xSubtotalExento = v_xSubtotalExento + v_xTotSIva;
            ELSE SET v_xSubtotalDescuentoSinIVA = v_xSubtotalDescuentoSinIVA + v_xTotSIva;
          END CASE;
          SET v_xSubtotalSinDescuentoSinIVA = v_xSubtotalSinDescuentoSinIVA + v_xTotStot;
        END IF;

      END LOOP;

      CLOSE cursor_servicios;
      SET v_finished = 0;

      -- ASIGNAR VALORES CALCULADOS A VARIABLES DE FACTURA
      SET p_subtotal = ROUND(v_xSubtotalSinDescuentoConIVA + v_xSubtotalSinDescuentoConIVA2 + v_xSubtotalSinDescuentoSinIVA, 4);
      SET p_total_descuento = v_xTotal_DescuentoSinIVA;
      SET p_subtotalneto = ROUND(v_xSubtotalDescuentoConIVA + v_xSubtotalDescuentoConIVA2 + v_xSubtotalDescuentoSinIVA + v_xSubtotalNoObjeto + v_xSubtotalExento, 4);
      SET p_subtotalconiva = ROUND(v_xSubtotalDescuentoConIVA, 4);
      SET p_subtotalconiva2 = ROUND(v_xSubtotalDescuentoConIVA2, 4);
      SET p_subtotalsiniva = ROUND(v_xSubtotalDescuentoSinIVA, 4);
      SET p_subtotalnoobjetoiva = ROUND(v_xSubtotalNoObjeto, 4);
      SET p_subtotalexentoiva = ROUND(v_xSubtotalExento, 4);
      SET p_total_ice = v_xTotal_ICE;
      SET p_total_iva = v_xTotal_IVA + ROUND(v_xTotal_ICE * (v_porcentajeIVA / 100), 3);
      SET p_total_iva2 = v_xTotal_IVA2;
      SET p_total = ROUND(v_xSubtotalDescuentoConIVA + v_xSubtotalDescuentoConIVA2 + v_xSubtotalDescuentoSinIVA + v_xSubtotalNoObjeto + v_xSubtotalExento + v_xTotal_IVA + v_xTotal_IVA2 + v_xTotal_ICE + p_propina + ROUND(v_xTotal_ICE * (v_porcentajeIVA / 100), 3), 2);
      SET p_totalneto = p_total;
      SET p_saldo = p_total;
      SET p_valorcuota = p_total;
      SET p_totalacobrar = p_total;

      IF p_total > 0 THEN

        -- Insertar factura con TODOS los campos
        INSERT INTO facturas (sucursalesid, secuenciasid, sri_documentoscodigo, forma_pago_empresaid,
        forma_pago_sri_codigo, cajasid, bancosid, centros_costosid, almacenesid,
        facturadoresid, vendedoresid, clientesid, clientes_sucursalesid,
        clientes_contratosid, tarifasid, establecimiento, puntoemision,
        secuencial, emision, vence, relaciondocumentoid, concepto,
        promocionesid, subtotal, total_descuento, subtotalconiva,
        subtotalconiva2, subtotalsiniva, subtotalnoobjetoiva, subtotalexentoiva,
        subtotalneto, total_ice, total_iva, total_iva2, propina, total,
        totalneto, totalretenidoiva, totalretenidorenta, puntoemisionretencion,
        establecimientoretencion, emisionretencion, secuenciaretencion,
        autorizacionretencion, relacionemision, relacionsecuencia,
        relacionestablecimiento, relacionpuentoemision, numeroautorizacion,
        autorizacionfecha, claveacceso, autorizacionintentos, de_enviado,
        mensajeerror, asientocontable, asientocosto, saldo, tipoplazo,
        plazo, plazodias, numeropagos, interes, valorcuota, totalacobrar,
        tipocredito, cambio, anulado, observacion, archivo_xml,
        restaurante_mesasid, receptor_clientesid, receptor_clientes_sucursalesid,
        sucursales_destinosid, uuid, estado, estado_sync, impresa, origen,
        fechacreacion, fechamodificacion, usuariocreacion, usuariomodificacion)
          VALUES (
          p_sucursalesid, p_secuenciasid, p_sri_documentoscodigo, p_forma_pago_empresaid,
          p_forma_pago_sri_codigo, p_cajasid, p_bancosid, p_centros_costosid, p_almacenesid,
          p_facturadoresid, p_vendedoresid, p_clientesid, p_clientes_sucursalesid,
          p_clientes_contratosid, p_tarifasid, p_establecimiento, p_puntoemision,
          p_secuencial, p_emision, p_vence, p_relaciondocumentoid, p_concepto,
          p_promocionesid, p_subtotal, p_total_descuento, p_subtotalconiva,
          p_subtotalconiva2, p_subtotalsiniva, p_subtotalnoobjetoiva, p_subtotalexentoiva,
          p_subtotalneto, p_total_ice, p_total_iva, p_total_iva2, p_propina, p_total,
          p_totalneto, p_totalretenidoiva, p_totalretenidorenta, p_puntoemisionretencion,
          p_establecimientoretencion, p_emisionretencion, p_secuenciaretencion,
          p_autorizacionretencion, p_relacionemision, p_relacionsecuencia,
          p_relacionestablecimiento, p_relacionpuentoemision, p_numeroautorizacion,
          p_autorizacionfecha, p_claveacceso, p_autorizacionintentos, p_de_enviado,
          p_mensajeerror, p_asientocontable, p_asientocosto, p_saldo, p_tipoplazo,
          p_plazo, p_plazodias, p_numeropagos, p_interes, p_valorcuota, p_totalacobrar,
          p_tipocredito, p_cambio, p_anulado, p_observacion, p_archivo_xml,
          p_restaurante_mesasid, p_receptor_clientesid, p_receptor_clientes_sucursalesid,
          p_sucursales_destinosid, p_uuid, p_estado, p_estado_sync, p_impresa, p_origen,
          p_fechacreacion, p_fechamodificacion, p_usuariocreacion, p_usuariomodificacion
          );

        SET p_facturasid = LAST_INSERT_ID();

        -- Actualizar secuencia
        -- UPDATE secuencias SET numeroactual = numeroactual + 1 WHERE secuenciasid = nSecuencia;

        -- Insertar cuenta por cobrar
        INSERT INTO cuentasporcobrar (documentosid, cobrosid, clientesid, clientes_contratosid, cajasid,
        bancosid, forma_pago_sri_codigo, emision, recepcion, vence,
        centros_costosid, secuencial, vendedoresid, cobradoresid, origen,
        tipo, forma_pago_empresaid, importe, concepto, numerochequedeposito,
        relaciondocumentoid, asientocontable, usuariocreacion, fechacreacion,
        usuariomodificacion, fechamodificacion)
          VALUES (
          p_facturasid, 0, p_clientesid, 1, p_cajasid,
          1, '01', p_emision, p_emision, p_vence,
          1, p_secuencial, p_vendedoresid, p_facturadoresid, 'Facturacion',
          'FC', 2, p_total, p_concepto, '',
          0, 0, p_usuariocreacion, p_fechacreacion,
          p_usuariomodificacion, p_fechamodificacion
          );

        OPEN cursor_servicios;

      read_servicios2:
        LOOP
          FETCH cursor_servicios INTO v_producto_id, v_precio, v_descuento, v_ice_porcentaje,
          v_ice_valor, v_sri_tipos_ivas_codigo, v_servicio,
          v_costoactual, v_unidadinterna, v_ivavalor, v_tipoiva;

          IF v_finished = 1 THEN
            LEAVE read_servicios2;
          END IF;

          -- Recalcular ICE para este detalle
          SET v_xICE = 0;
          SET v_xTotSIva = v_precio * (1 - v_descuento / 100);

          IF v_ice_porcentaje > 0 THEN
            SET v_xICE = ROUND(v_xTotSIva * (v_ice_porcentaje / 100), 3);
          ELSEIF v_ice_valor > 0 THEN
            SET v_xICE = ROUND(v_ice_valor, 3);
          END IF;

          -- Base para IVA incluye ICE
          SET v_baseParaIVA = v_xTotSIva + v_xICE;

-- Insertar detalle de factura con campo ICE
          INSERT INTO facturas_detalles (facturasid, productosid, medidasid, centros_costosid,
          cantidaddigitada, cantidadfactor, cantidad, almacenesid,
          precio, precioiva, preciovisible, descuento, descuentovalor,
          costo, iva, ice, servicio, informacion, informaciondetalle)
            VALUES (
            p_facturasid, v_producto_id, v_unidadinterna, 1,
            1, 1, 1, 1,
            v_precio, round(v_precio + (v_precio * v_ivavalor / 100),2), v_precio,
            v_descuento, v_precio * (v_descuento / 100), v_costoactual,
            v_ivavalor, v_xICE, v_servicio, p_concepto, ''
            );

          SET v_facturas_detallesid = LAST_INSERT_ID();

          -- Insertar movimiento de inventario
          INSERT INTO movinventarios (documentosid, documento_detallesid, productosid, centros_costosid,
          cantidaddigitada, cantidadfactor, beneficiarioid, medidasid,
          almacenesid, cantidad, precio, precioiva, preciovisible,
          movinventarios_tiposid, descuento, descuentovalor, costo,
          iva, servicio, fechamovimiento, referencia)
            VALUES (
            p_facturasid, v_facturas_detallesid, v_producto_id, 1,
            1, 1, p_clientesid,
            v_unidadinterna, 1, 1, v_precio,
            round(v_precio + (v_precio * v_ivavalor / 100),2), v_precio,
            3, v_descuento, v_precio * (v_descuento / 100), v_costoactual,
            v_ivavalor , v_servicio, p_emision,
            CONCAT(p_establecimiento, '-', p_puntoemision, '-', p_secuencial)
            );

        END LOOP;

        CLOSE cursor_servicios;
        SET v_finished = 0;

        -- Insertar cuota de crédito
        INSERT INTO clientes_creditos (documentosid, clientesid, origen, numerocuota, fecha_vence,
        valor_cuota, abono_cuota, abono_capital, interes, saldo_cuota, saldo)
          VALUES (
          p_facturasid, p_clientesid, 'Facturacion', 1, p_vence,
          p_total, 0, p_total, 0, p_total, 0
          );

        -- Incrementar contador de facturas procesadas
        SET v_contador_facturas = v_contador_facturas + 1;

      END IF;

    END LOOP;

    CLOSE cursor_clientes;

  -- Confirmar transacción
  COMMIT;

  -- Mostrar resultado del procesamiento
  SELECT
    v_contador_facturas AS facturas_generadas,
    p_concepto AS concepto_procesado,
    v_mes_texto AS mes,
    v_anio_texto AS anio,
    nGrupo AS grupo_procesado;

END
;;
delimiter ;

-- ----------------------------
-- Procedure structure for SP_Facturas_Lotes_Eliminar
-- ----------------------------
DROP PROCEDURE IF EXISTS `SP_Facturas_Lotes_Eliminar`;
delimiter ;;
CREATE PROCEDURE `SP_Facturas_Lotes_Eliminar`(IN dMes DATE,           -- Fecha del mes a eliminar
    IN nGrupo INT,          -- Grupo de clientes (0 = todos los grupos)
    IN sConfirmacion VARCHAR(10))
BEGIN
    -- Variables para contadores
    DECLARE v_facturas_eliminadas INT DEFAULT 0;
    DECLARE v_detalles_eliminados INT DEFAULT 0;
    DECLARE v_cuentas_eliminadas INT DEFAULT 0;
    DECLARE v_creditos_eliminados INT DEFAULT 0;
    DECLARE v_movimientos_eliminados INT DEFAULT 0;
    DECLARE v_facturas_candidatas INT DEFAULT 0;
    DECLARE v_facturas_excluidas INT DEFAULT 0;
    
    -- Variables para validación
    DECLARE v_mes_texto VARCHAR(20);
    DECLARE v_anio_texto VARCHAR(4);
    DECLARE v_concepto VARCHAR(150);
    DECLARE v_puede_continuar BOOLEAN DEFAULT TRUE;
    
    -- Manejador de errores
    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
        -- Limpiar tablas temporales si existen
        DROP TEMPORARY TABLE IF EXISTS tmp_facturas_candidatas;
        DROP TEMPORARY TABLE IF EXISTS tmp_facturas_eliminar;
        DROP TEMPORARY TABLE IF EXISTS tmp_facturas_excluidas;
        ROLLBACK;
        RESIGNAL;
    END;

    -- Validación de parámetro de confirmación
    IF sConfirmacion != 'CONFIRMAR' THEN
        SELECT 
            'ERROR: Debe enviar CONFIRMAR como tercer parámetro para ejecutar la eliminación' AS mensaje,
            'Uso: CALL SP_Facturas_Lotes_Eliminar(''2024-08-01'', 5, ''CONFIRMAR'')' AS ejemplo;
        SET v_puede_continuar = FALSE;
    END IF;

    -- Solo continuar si la validación pasó
    IF v_puede_continuar = TRUE THEN
        
        -- Iniciar transacción
        START TRANSACTION;

        -- Construir concepto esperado
        SET v_anio_texto = YEAR(dMes);
        CASE MONTH(dMes)
            WHEN 1 THEN SET v_mes_texto = 'Enero';
            WHEN 2 THEN SET v_mes_texto = 'Febrero';
            WHEN 3 THEN SET v_mes_texto = 'Marzo';
            WHEN 4 THEN SET v_mes_texto = 'Abril';
            WHEN 5 THEN SET v_mes_texto = 'Mayo';
            WHEN 6 THEN SET v_mes_texto = 'Junio';
            WHEN 7 THEN SET v_mes_texto = 'Julio';
            WHEN 8 THEN SET v_mes_texto = 'Agosto';
            WHEN 9 THEN SET v_mes_texto = 'Septiembre';
            WHEN 10 THEN SET v_mes_texto = 'Octubre';
            WHEN 11 THEN SET v_mes_texto = 'Noviembre';
            WHEN 12 THEN SET v_mes_texto = 'Diciembre';
        END CASE;
        
        SET v_concepto = CONCAT('Factura mes ', v_mes_texto, ' ', v_anio_texto);

        -- PASO 0: Crear tabla temporal con todas las facturas candidatas
        DROP TEMPORARY TABLE IF EXISTS tmp_facturas_candidatas;
        CREATE TEMPORARY TABLE tmp_facturas_candidatas (
            facturasid INT PRIMARY KEY,
            clientesid INT,
            secuencial VARCHAR(50),
            total DECIMAL(15,2)
        );

        INSERT INTO tmp_facturas_candidatas (facturasid, clientesid, secuencial, total)
        SELECT f.facturasid, f.clientesid, f.secuencial, f.total
        FROM facturas f
        INNER JOIN clientes c ON c.clientesid = f.clientesid
        WHERE f.usuariocreacion = 'GeneradoLotes'
        AND f.origen = 'GeneradoLotes'
        AND f.concepto = v_concepto
        AND YEAR(f.emision) = YEAR(dMes)
        AND MONTH(f.emision) = MONTH(dMes)
        AND (nGrupo = 0 OR c.clientes_gruposid = nGrupo);

        SET v_facturas_candidatas = (SELECT COUNT(*) FROM tmp_facturas_candidatas);

        -- Validar que existan facturas candidatas
        IF v_facturas_candidatas = 0 THEN
            SELECT 
                'No se encontraron facturas por lotes con los criterios especificados' AS mensaje,
                v_concepto AS concepto_buscado,
                nGrupo AS grupo_especificado,
                dMes AS fecha_inicio;
            DROP TEMPORARY TABLE IF EXISTS tmp_facturas_candidatas;
            ROLLBACK;
        ELSE
            -- Crear tabla temporal para facturas que SÍ se pueden eliminar
            DROP TEMPORARY TABLE IF EXISTS tmp_facturas_eliminar;
            CREATE TEMPORARY TABLE tmp_facturas_eliminar (
                facturasid INT PRIMARY KEY
            );

            -- Crear tabla temporal para facturas excluidas con razón
            DROP TEMPORARY TABLE IF EXISTS tmp_facturas_excluidas;
            CREATE TEMPORARY TABLE tmp_facturas_excluidas (
                facturasid INT,
                secuencial VARCHAR(50),
                razon VARCHAR(200)
            );

            -- FILTRO 1: Excluir facturas con asiento contable o de costo
            INSERT INTO tmp_facturas_excluidas (facturasid, secuencial, razon)
            SELECT fc.facturasid, fc.secuencial, 'Tiene asiento contable o de costo'
            FROM tmp_facturas_candidatas fc
            INNER JOIN facturas f ON f.facturasid = fc.facturasid
            WHERE COALESCE(f.asientocontable, 0) > 0 
               OR COALESCE(f.asientocosto, 0) > 0;

            -- FILTRO 2: Excluir facturas con notas de crédito o débito relacionadas
            INSERT INTO tmp_facturas_excluidas (facturasid, secuencial, razon)
            SELECT fc.facturasid, fc.secuencial, 'Tiene notas de crédito o débito relacionadas'
            FROM tmp_facturas_candidatas fc
            WHERE EXISTS (
                SELECT 1 FROM facturas f2
                WHERE f2.relaciondocumentoid = fc.facturasid
                AND f2.anulado = 0
            )
            AND fc.facturasid NOT IN (SELECT facturasid FROM tmp_facturas_excluidas);

            -- FILTRO 3: Excluir facturas que NO son físicas NI están anuladas
            -- Solo se pueden eliminar facturas físicas (autorización <= 10) o anuladas
            INSERT INTO tmp_facturas_excluidas (facturasid, secuencial, razon)
            SELECT fc.facturasid, fc.secuencial, 'No es factura física ni está anulada'
            FROM tmp_facturas_candidatas fc
            INNER JOIN facturas f ON f.facturasid = fc.facturasid
            WHERE LENGTH(TRIM(COALESCE(f.numeroautorizacion, ''))) > 10 
                  AND COALESCE(f.anulado, 0) = 0
            AND fc.facturasid NOT IN (SELECT facturasid FROM tmp_facturas_excluidas);

            -- FILTRO 4: Excluir facturas con cobros asociados
            INSERT INTO tmp_facturas_excluidas (facturasid, secuencial, razon)
            SELECT fc.facturasid, fc.secuencial, 'Tiene cobros registrados'
            FROM tmp_facturas_candidatas fc
            WHERE EXISTS (
                SELECT 1 FROM cuentasporcobrar cpc
                WHERE cpc.documentosid = fc.facturasid
                AND cpc.clientesid = fc.clientesid
                AND cpc.secuencial = fc.secuencial
                AND cpc.origen = 'Cobros'
            )
            AND fc.facturasid NOT IN (SELECT facturasid FROM tmp_facturas_excluidas);

            -- FILTRO 5: Excluir facturas en despachos
            INSERT INTO tmp_facturas_excluidas (facturasid, secuencial, razon)
            SELECT fc.facturasid, fc.secuencial, 'Se encuentra en un despacho'
            FROM tmp_facturas_candidatas fc
            WHERE EXISTS (
                SELECT 1 FROM cobranza_detalles cd
                WHERE cd.documentosid = fc.facturasid
                AND cd.tipo = 'FC'
                AND (cd.estado = 1 OR (cd.estado = 2 AND cd.cobrado > 0))
            )
            AND fc.facturasid NOT IN (SELECT facturasid FROM tmp_facturas_excluidas);

            -- FILTRO 6: Excluir facturas con retenciones de cobros
            INSERT INTO tmp_facturas_excluidas (facturasid, secuencial, razon)
            SELECT fc.facturasid, fc.secuencial, 'Tiene retenciones registradas'
            FROM tmp_facturas_candidatas fc
            WHERE EXISTS (
                SELECT 1 FROM facturas_retenciones fr
                WHERE fr.documentosid = fc.facturasid
                AND fr.origen = 'Cobros'
            )
            AND fc.facturasid NOT IN (SELECT facturasid FROM tmp_facturas_excluidas);

            -- Insertar facturas que SÍ se pueden eliminar (las que NO están en excluidas)
            INSERT INTO tmp_facturas_eliminar (facturasid)
            SELECT facturasid 
            FROM tmp_facturas_candidatas
            WHERE facturasid NOT IN (SELECT facturasid FROM tmp_facturas_excluidas);

            SET v_facturas_excluidas = (SELECT COUNT(*) FROM tmp_facturas_excluidas);

            -- Si hay facturas para eliminar, proceder con la eliminación
            IF EXISTS (SELECT 1 FROM tmp_facturas_eliminar) THEN
                
                -- PASO 1: Eliminar movimientos de inventario
                DELETE mi FROM movinventarios mi
                INNER JOIN facturas_detalles fd ON fd.facturas_detallesid = mi.documento_detallesid
                WHERE fd.facturasid IN (SELECT facturasid FROM tmp_facturas_eliminar);
                
                SET v_movimientos_eliminados = ROW_COUNT();

                -- PASO 2: Eliminar cuentas por cobrar
                DELETE cpc FROM cuentasporcobrar cpc
                WHERE cpc.documentosid IN (SELECT facturasid FROM tmp_facturas_eliminar)
                AND cpc.origen = 'Facturacion'
                AND cpc.usuariocreacion = 'GeneradoLotes';
                
                SET v_cuentas_eliminadas = ROW_COUNT();

                -- PASO 3: Eliminar créditos de clientes
                DELETE cc FROM clientes_creditos cc
                WHERE cc.documentosid IN (SELECT facturasid FROM tmp_facturas_eliminar)
                AND cc.origen = 'Facturacion';
                
                SET v_creditos_eliminados = ROW_COUNT();

                -- PASO 4: Eliminar detalles de facturas
                DELETE fd FROM facturas_detalles fd
                WHERE fd.facturasid IN (SELECT facturasid FROM tmp_facturas_eliminar);
                
                SET v_detalles_eliminados = ROW_COUNT();

                -- PASO 5: Eliminar facturas principales
                DELETE f FROM facturas f
                WHERE f.facturasid IN (SELECT facturasid FROM tmp_facturas_eliminar);
                
                SET v_facturas_eliminadas = ROW_COUNT();

                -- Confirmar transacción
                COMMIT;

                -- Mostrar resumen de eliminación
                SELECT 
                    'PROCESO COMPLETADO' AS resultado,
                    v_facturas_candidatas AS facturas_encontradas,
                    v_facturas_eliminadas AS facturas_eliminadas,
                    v_facturas_excluidas AS facturas_no_eliminadas,
                    v_detalles_eliminados AS detalles_eliminados,
                    v_cuentas_eliminadas AS cuentas_por_cobrar_eliminadas,
                    v_creditos_eliminados AS creditos_eliminados,
                    v_movimientos_eliminados AS movimientos_inventario_eliminados,
                    v_concepto AS concepto_procesado,
                    CASE 
                        WHEN nGrupo = 0 THEN 'TODOS LOS GRUPOS'
                        ELSE CONCAT('GRUPO ', nGrupo)
                    END AS grupo_procesado,
                    v_mes_texto AS mes,
                    v_anio_texto AS anio;

                -- Mostrar detalle de facturas excluidas si las hay
                IF v_facturas_excluidas > 0 THEN
                    SELECT 
                        'FACTURAS NO ELIMINADAS (no cumplen validaciones)' AS titulo,
                        secuencial,
                        razon
                    FROM tmp_facturas_excluidas
                    ORDER BY razon, secuencial;
                END IF;

            ELSE
                -- No hay facturas que se puedan eliminar
                ROLLBACK;
                
                SELECT 
                    'ADVERTENCIA: Ninguna factura cumple las validaciones para ser eliminada' AS mensaje,
                    v_facturas_candidatas AS facturas_encontradas,
                    v_facturas_excluidas AS facturas_no_aptas;

                -- Mostrar detalle de por qué no se pueden eliminar
                SELECT 
                    'RAZONES DE EXCLUSIÓN' AS titulo,
                    secuencial,
                    razon
                FROM tmp_facturas_excluidas
                ORDER BY razon, secuencial;
            END IF;

            -- Limpiar tablas temporales
            DROP TEMPORARY TABLE IF EXISTS tmp_facturas_candidatas;
            DROP TEMPORARY TABLE IF EXISTS tmp_facturas_eliminar;
            DROP TEMPORARY TABLE IF EXISTS tmp_facturas_excluidas;
        END IF;
    END IF;

END
;;
delimiter ;

-- ----------------------------
-- Procedure structure for SP_Fac_GenClave
-- ----------------------------
DROP PROCEDURE IF EXISTS `SP_Fac_GenClave`;
delimiter ;;
CREATE PROCEDURE `SP_Fac_GenClave`(IN vFE char(8) ,in vTC char(2),in vNRUC char(13),in vTA char (1),in vS char(6),in vNC char(9),in vCN char(8),in vTE char(1),out vClave varchar(49))
BEGIN

DECLARE vCATemporal varchar(50);
DECLARE vAcumulador int(11) DEFAULT 0;
DECLARE vSerie int DEFAULT 2 ;
DECLARE vDigitoVerificador int ;
DECLARE vI int ;

-- Se comienza a armar la clave de Acceso
SET vClave = REPLACE(vFE,'/','');
set vClave = concat(vclave,vTC,vNRUC,vTA,vS,vNC,vCN,vTE);

SET vCATemporal = REVERSE(vClave);
SET vI = 1 ;

WHILE vI < LENGTH(vClave) DO
IF vSerie = 8 Then 
SET vSerie = 2;
END IF;

SET vAcumulador = vAcumulador + ( CONVERT( MID(vCATemporal,vI,1)  ,int)  * vSerie );

SET vSerie = vSerie + 1 ;
Set vI = vI + 1 ;
END WHILE;

SET vDigitoVerificador = 11 - MOD(vAcumulador,11);

if vDigitoVerificador = 10 Then 
SET vDigitoVerificador = 1;
end if; 
if vDigitoVerificador = 11 Then 
SET vDigitoVerificador = 0;
end if; 

Set vClave = concat(vClave,vDigitoVerificador);

END
;;
delimiter ;

-- ----------------------------
-- Procedure structure for SP_Fac_Secuencia
-- ----------------------------
DROP PROCEDURE IF EXISTS `SP_Fac_Secuencia`;
delimiter ;;
CREATE PROCEDURE `SP_Fac_Secuencia`(IN pSecuencia int(11),OUT vSec char(15))
BEGIN

-- DECLARE vSec VARCHAR(15) DEFAULT '';
DECLARE vNum int;
SET vSec = CONVERT( (SELECT secuencias.numeroactual FROM secuencias WHERE secuencias.secuenciasid = pSecuencia) ,CHAR);

SET vNum = length( vSec );
CASE vNum 
WHEN 1 THEN
SET vSec = CONCAT("00000000" , vSec);
WHEN 2 THEN
SET vSec = CONCAT("0000000" , vSec);
WHEN 3 THEN
SET vSec = CONCAT("000000" , vSec);
WHEN 4 THEN
SET vSec = CONCAT("00000" , vSec);
WHEN 5 THEN
SET vSec = CONCAT("0000" , vSec);
WHEN 6 THEN
SET vSec = CONCAT("000" , vSec);
WHEN 7 THEN
SET vSec = CONCAT("00" , vSec);
WHEN 8 THEN
SET vSec = CONCAT("0" , vSec);
END CASE;

UPDATE secuencias set secuencias.numeroactual = secuencias.numeroactual + 1 ;

END
;;
delimiter ;

-- ----------------------------
-- Procedure structure for SP_medidas_ABC
-- ----------------------------
DROP PROCEDURE IF EXISTS `SP_medidas_ABC`;
delimiter ;;
CREATE PROCEDURE `SP_medidas_ABC`(IN pAccion varchar(1), IN pRegistrosJson json)
BEGIN
  DECLARE vJsonEsValido int;
  DECLARE vItems int;
  DECLARE vIndex bigint UNSIGNED DEFAULT 0;
  DECLARE vErrorMensaje text;
  DECLARE vRegistroAnterior longtext;


  # VARIABLES DE LOS DATOS DE LA TABLA
  DECLARE p_medidasid int(11);
  DECLARE p_descripcion varchar(30) DEFAULT '';
  DECLARE p_descripcioncorta varchar(10) DEFAULT '';
  DECLARE p_fechacreacion datetime(3) DEFAULT '0000-00-00 00:00:00.000';
  DECLARE p_usuariocreacion varchar(25) DEFAULT '';
  DECLARE p_fechamodificacion datetime(3) DEFAULT '0000-00-00 00:00:00.000';
  DECLARE p_usuariomodificacion varchar(25) DEFAULT '';


  # VARIABLE DE LOS DATOS DE LA AUDITORIA
  DECLARE p_sis_subcategoriasid int(11) DEFAULT 0;
  DECLARE p_sis_empresasid int(11) DEFAULT 0;
  DECLARE p_sis_usuariosid varchar(20) DEFAULT '';
  DECLARE p_equipo varchar(50) DEFAULT '';
  DECLARE p_tipooperacion varchar(50) DEFAULT '';
  DECLARE p_detalle longtext;

  # CONTROLAMOS SI HAY ERROR
  DECLARE EXIT HANDLER FOR SQLEXCEPTION, SQLWARNING
  BEGIN
    GET DIAGNOSTICS CONDITION 1 vErrorMensaje = MESSAGE_TEXT;
    SELECT
      CASE WHEN LOCATE('Cannot delete or update a parent row',vErrorMensaje)>0 THEN JSON_ARRAYAGG(JSON_OBJECT('procesado', FALSE, 'mensaje', 'No Se Puede Eliminar, Medida en Uso')) ELSE JSON_ARRAYAGG(JSON_OBJECT('procesado', FALSE, 'mensaje', vErrorMensaje)) END AS resultado;
    ROLLBACK;
  END;
  # VALIDAMOS SI EL OBJETO JSON ES VALIDO 
  SET vJsonEsValido = JSON_VALID(pRegistrosJson);

  IF vJsonEsValido = 0 THEN
    # EL OBJETO JSON NO ES VALIDO
    SELECT
      JSON_ARRAYAGG(JSON_OBJECT('procesado', FALSE, 'mensaje', 'Json no es valido')) AS resultado;
  ELSE

    # VALIDAMOS QUE TENGA ALMENOS UN ELEMENTO
    SET vItems = JSON_LENGTH(pRegistrosJson, '$.cabecera');

    IF vItems > 0 THEN
      START TRANSACTION;
        WHILE vIndex < vItems DO

          # DATOS TABLA
          SET p_medidasid = IFNULL(JSON_UNQUOTE(JSON_EXTRACT(pRegistrosJson, CONCAT('$.cabecera[', vIndex, '].medidasid'))), p_medidasid);
          SET p_descripcion = IFNULL(JSON_UNQUOTE(JSON_EXTRACT(pRegistrosJson, CONCAT('$.cabecera[', vIndex, '].descripcion'))), p_descripcion);
          SET p_descripcioncorta = IFNULL(JSON_UNQUOTE(JSON_EXTRACT(pRegistrosJson, CONCAT('$.cabecera[', vIndex, '].descripcioncorta'))), p_descripcioncorta);


          # DATOS AUDITORIA
          SET p_sis_subcategoriasid = JSON_UNQUOTE(JSON_EXTRACT(pRegistrosJson, CONCAT('$.cabecera[', vIndex, '].sis_subcategoriasid')));
          SET p_sis_empresasid = JSON_UNQUOTE(JSON_EXTRACT(pRegistrosJson, CONCAT('$.cabecera[', vIndex, '].sis_empresasid')));
          SET p_sis_usuariosid = JSON_UNQUOTE(JSON_EXTRACT(pRegistrosJson, CONCAT('$.cabecera[', vIndex, '].sis_usuariosid')));
          SET p_equipo = JSON_UNQUOTE(JSON_EXTRACT(pRegistrosJson, CONCAT('$.cabecera[', vIndex, '].equipo')));


          CASE pAccion
            WHEN 'C' THEN SET p_tipooperacion = 'N';
                SET p_fechacreacion = NOW(3);
                SET p_usuariocreacion = JSON_UNQUOTE(JSON_EXTRACT(pRegistrosJson, CONCAT('$.cabecera[', vIndex, '].usuariocreacion')));
                SET p_fechamodificacion = NULL;
                SET p_usuariomodificacion = '';
                SET p_detalle = REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(JSON_INSERT('{}', '$.medidas', JSON_EXTRACT(pRegistrosJson, CONCAT('$.cabecera[', vIndex, ']'))), '"[', '['), ']"', ']'), '\\', ''), '"{', '{'), '}"', '}');

                # INSERTAMOS LOS REGISTROS
                INSERT INTO medidas (medidasid, descripcion, descripcioncorta, fechacreacion, usuariocreacion, fechamodificacion, usuariomodificacion)
                  VALUES (p_medidasid, p_descripcion, p_descripcioncorta, p_fechacreacion, p_usuariocreacion, p_fechamodificacion, p_usuariomodificacion);

set p_medidasid = LAST_INSERT_ID();

            WHEN 'M' THEN SET p_tipooperacion = 'M';
                SET p_fechamodificacion = NOW(3);
                SET p_usuariomodificacion = JSON_UNQUOTE(JSON_EXTRACT(pRegistrosJson, CONCAT('$.cabecera[', vIndex, '].usuariomodificacion')));


                SET vRegistroAnterior = (SELECT
                    JSON_OBJECT
                    (
                    'medidasid', medidasid,
                    'descripcion', descripcion,
                    'descripcioncorta', descripcioncorta,
                    'fechamodificacion', fechamodificacion,
                    'usuariomodificacion', usuariomodificacion
                    )
                  FROM medidas
                  WHERE medidas.medidasid = p_medidasid);

                SET p_detalle = REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(JSON_INSERT('{}', '$.medidas', vRegistroAnterior), '"[', '['), ']"', ']'), '\\', ''), '"{', '{'), '}"', '}');

                # ACTUALIZAMOS LOS REGISTROS
                UPDATE medidas
                SET medidasid = p_medidasid,
                    descripcion = p_descripcion,
                    descripcioncorta = p_descripcioncorta,
                    fechamodificacion = p_fechamodificacion,
                    usuariomodificacion = p_usuariomodificacion
                WHERE medidasid = p_medidasid;

            WHEN 'E' THEN SET p_tipooperacion = 'E';
                SET p_detalle = REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(JSON_INSERT('{}', '$.medidas', JSON_EXTRACT(pRegistrosJson, CONCAT('$.cabecera[', vIndex, ']'))), '"[', '['), ']"', ']'), '\\', ''), '"{', '{'), '}"', '}');

                # ELIMINAMOS LOS REGISTROS
                DELETE
                  FROM medidas
                WHERE medidasid = p_medidasid;

          END CASE;

          # INSERTAMOS LA AUDITORIA
          CALL sistemaperseo.SP_ABC_sis_log_sistema(p_sis_subcategoriasid, p_sis_empresasid, p_sis_usuariosid, p_tipooperacion, p_detalle, p_equipo);

          SET vIndex = vIndex + 1;
        END WHILE;
      COMMIT;

      # RETORNAMOS LA RESPUESTAS
      IF pAccion IN ('C', 'M') THEN

        SELECT
          medidas.medidasid,
          medidas.descripcion,
          medidas.descripcioncorta,
          medidas.fechacreacion,
          medidas.usuariocreacion,
          medidas.fechamodificacion,
          medidas.usuariomodificacion,
          (SELECT
              JSON_ARRAYAGG(JSON_OBJECT('procesado', TRUE, 'mensaje', 'Completado con Éxito'))) AS resultado
        FROM medidas
        WHERE medidas.medidasid = p_medidasid;

      ELSE
        SELECT
          JSON_ARRAYAGG(JSON_OBJECT('procesado', TRUE, 'mensaje', 'Completado con Éxito')) AS resultado;
      END IF;

    END IF;
  END IF;
END
;;
delimiter ;

-- ----------------------------
-- Procedure structure for SP_medidas_ConsultarID
-- ----------------------------
DROP PROCEDURE IF EXISTS `SP_medidas_ConsultarID`;
delimiter ;;
CREATE PROCEDURE `SP_medidas_ConsultarID`(IN p_medidasid int(11))
BEGIN

  SELECT
    medidas.medidasid,
    medidas.descripcion,
    medidas.descripcioncorta,
    medidas.fechacreacion,
    medidas.usuariocreacion,
    medidas.fechamodificacion,
    medidas.usuariomodificacion
  FROM medidas
  WHERE medidas.medidasid = p_medidasid;

END
;;
delimiter ;

-- ----------------------------
-- Procedure structure for SP_movimientos_conceptos_ABC
-- ----------------------------
DROP PROCEDURE IF EXISTS `SP_movimientos_conceptos_ABC`;
delimiter ;;
CREATE PROCEDURE `SP_movimientos_conceptos_ABC`(IN pAccion varchar(1), IN pRegistrosJson json)
BEGIN
  DECLARE vJsonEsValido int;
  DECLARE vItems int;
  DECLARE vIndex bigint UNSIGNED DEFAULT 0;
  DECLARE vErrorMensaje text;
  DECLARE vRegistroAnterior longtext;


  # VARIABLES DE LOS DATOS DE LA TABLA
  DECLARE p_movimientos_conceptosid int(11);
  DECLARE p_descripcion varchar(50) DEFAULT '';
  DECLARE p_codigocontable varchar(30) DEFAULT '';
  DECLARE p_usuariocreacion varchar(25) DEFAULT '';
  DECLARE p_fechacreacion datetime(3) DEFAULT '0000-00-00 00:00:00.000';
  DECLARE p_usuariomodificacion varchar(25) DEFAULT '';
  DECLARE p_fechamodificacion datetime(3) DEFAULT '0000-00-00 00:00:00.000';
  DECLARE p_tipo tinyint(3) DEFAULT 0;
  DECLARE p_estado tinyint(3) DEFAULT 1;  


  # VARIABLE DE LOS DATOS DE LA AUDITORIA
  DECLARE p_sis_subcategoriasid int(11) DEFAULT 0;
  DECLARE p_sis_empresasid int(11) DEFAULT 0;
  DECLARE p_sis_usuariosid varchar(20) DEFAULT '';
  DECLARE p_equipo varchar(50) DEFAULT '';
  DECLARE p_tipooperacion varchar(50) DEFAULT '';
  DECLARE p_detalle longtext;

  # CONTROLAMOS SI HAY ERROR
  DECLARE EXIT HANDLER FOR SQLEXCEPTION, SQLWARNING
  BEGIN
    GET DIAGNOSTICS CONDITION 1 vErrorMensaje = MESSAGE_TEXT;
    SELECT
      CASE WHEN LOCATE('Cannot delete or update a parent row',vErrorMensaje)>0 THEN JSON_ARRAYAGG(JSON_OBJECT('procesado', FALSE, 'mensaje', 'No Se Puede Eliminar, Movimiento concepto en Uso')) ELSE JSON_ARRAYAGG(JSON_OBJECT('procesado', FALSE, 'mensaje', vErrorMensaje)) END AS resultado;
    ROLLBACK;
  END;
  # VALIDAMOS SI EL OBJETO JSON ES VALIDO 
  SET vJsonEsValido = JSON_VALID(pRegistrosJson);

  IF vJsonEsValido = 0 THEN
    # EL OBJETO JSON NO ES VALIDO
    SELECT
      JSON_ARRAYAGG(JSON_OBJECT('procesado', FALSE, 'mensaje', 'Json no es valido')) AS resultado;
  ELSE

    # VALIDAMOS QUE TENGA ALMENOS UN ELEMENTO
    SET vItems = JSON_LENGTH(pRegistrosJson, '$.cabecera');

    IF vItems > 0 THEN
      START TRANSACTION;
        WHILE vIndex < vItems DO

          # DATOS TABLA
          SET p_movimientos_conceptosid = IFNULL(JSON_UNQUOTE(JSON_EXTRACT(pRegistrosJson, CONCAT('$.cabecera[', vIndex, '].movimientos_conceptosid'))), p_movimientos_conceptosid);
          SET p_descripcion = IFNULL(JSON_UNQUOTE(JSON_EXTRACT(pRegistrosJson, CONCAT('$.cabecera[', vIndex, '].descripcion'))), p_descripcion);
          SET p_codigocontable = IFNULL(JSON_UNQUOTE(JSON_EXTRACT(pRegistrosJson, CONCAT('$.cabecera[', vIndex, '].codigocontable'))), p_codigocontable);
          SET p_tipo = IFNULL(JSON_UNQUOTE(JSON_EXTRACT(pRegistrosJson, CONCAT('$.cabecera[', vIndex, '].tipo'))), p_tipo);
  SET p_estado = IFNULL(JSON_UNQUOTE(JSON_EXTRACT(pRegistrosJson, CONCAT('$.cabecera[', vIndex, '].estado'))), p_estado);

          # DATOS AUDITORIA
          SET p_sis_subcategoriasid = JSON_UNQUOTE(JSON_EXTRACT(pRegistrosJson, CONCAT('$.cabecera[', vIndex, '].sis_subcategoriasid')));
          SET p_sis_empresasid = JSON_UNQUOTE(JSON_EXTRACT(pRegistrosJson, CONCAT('$.cabecera[', vIndex, '].sis_empresasid')));
          SET p_sis_usuariosid = JSON_UNQUOTE(JSON_EXTRACT(pRegistrosJson, CONCAT('$.cabecera[', vIndex, '].sis_usuariosid')));
          SET p_equipo = JSON_UNQUOTE(JSON_EXTRACT(pRegistrosJson, CONCAT('$.cabecera[', vIndex, '].equipo')));


          CASE pAccion
            WHEN 'C' THEN SET p_tipooperacion = 'N';
                SET p_fechacreacion = NOW(3);
                SET p_usuariocreacion = JSON_UNQUOTE(JSON_EXTRACT(pRegistrosJson, CONCAT('$.cabecera[', vIndex, '].usuariocreacion')));
                SET p_fechamodificacion = NULL;
                SET p_usuariomodificacion = '';
                SET p_detalle = REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(JSON_INSERT('{}', '$.movimientos_conceptos', JSON_EXTRACT(pRegistrosJson, CONCAT('$.cabecera[', vIndex, ']'))), '"[', '['), ']"', ']'), '\\', ''), '"{', '{'), '}"', '}');

                # INSERTAMOS LOS REGISTROS
                INSERT INTO movimientos_conceptos (movimientos_conceptosid, descripcion, codigocontable, usuariocreacion, fechacreacion, usuariomodificacion, fechamodificacion, tipo, estado)
                  VALUES (p_movimientos_conceptosid, p_descripcion, p_codigocontable, p_usuariocreacion, p_fechacreacion, p_usuariomodificacion, p_fechamodificacion, p_tipo, p_estado);

SET p_movimientos_conceptosid = LAST_INSERT_ID();

            WHEN 'M' THEN SET p_tipooperacion = 'M';
                SET p_fechamodificacion = NOW(3);
                SET p_usuariomodificacion = JSON_UNQUOTE(JSON_EXTRACT(pRegistrosJson, CONCAT('$.cabecera[', vIndex, '].usuariomodificacion')));


                SET vRegistroAnterior = (SELECT
                    JSON_OBJECT
                    (
                    'movimientos_conceptosid', movimientos_conceptosid,
                    'descripcion', descripcion,
                    'codigocontable', codigocontable,
                    'usuariomodificacion', usuariomodificacion,
                    'fechamodificacion', fechamodificacion,
                    'tipo', tipo,
'estado',estado                    
                    )
                  FROM movimientos_conceptos
                  WHERE movimientos_conceptos.movimientos_conceptosid = p_movimientos_conceptosid);

                SET p_detalle = REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(JSON_INSERT('{}', '$.movimientos_conceptos', vRegistroAnterior), '"[', '['), ']"', ']'), '\\', ''), '"{', '{'), '}"', '}');

                # ACTUALIZAMOS LOS REGISTROS
                UPDATE movimientos_conceptos
                SET movimientos_conceptosid = p_movimientos_conceptosid,
                    descripcion = p_descripcion,
                    codigocontable = p_codigocontable,
                    usuariomodificacion = p_usuariomodificacion,
                    fechamodificacion = p_fechamodificacion,
                    tipo = p_tipo,
estado = p_estado                    
                WHERE movimientos_conceptosid = p_movimientos_conceptosid;

            WHEN 'E' THEN SET p_tipooperacion = 'E';
                SET p_detalle = REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(JSON_INSERT('{}', '$.movimientos_conceptos', JSON_EXTRACT(pRegistrosJson, CONCAT('$.cabecera[', vIndex, ']'))), '"[', '['), ']"', ']'), '\\', ''), '"{', '{'), '}"', '}');

                # ELIMINAMOS LOS REGISTROS
                DELETE
                  FROM movimientos_conceptos
                WHERE movimientos_conceptosid = p_movimientos_conceptosid;

          END CASE;

          # INSERTAMOS LA AUDITORIA
          CALL sistemaperseo.SP_ABC_sis_log_sistema(p_sis_subcategoriasid, p_sis_empresasid, p_sis_usuariosid, p_tipooperacion, p_detalle, p_equipo);

          SET vIndex = vIndex + 1;
        END WHILE;
      COMMIT;

      # RETORNAMOS LA RESPUESTAS
      IF pAccion IN ('C', 'M') THEN

        SELECT
    movimientos_conceptos.movimientos_conceptosid,
    movimientos_conceptos.descripcion,
cuentas_contables.descripcion as cuentanombre,
    movimientos_conceptos.codigocontable,
    movimientos_conceptos.usuariocreacion,
    movimientos_conceptos.fechacreacion,
    movimientos_conceptos.usuariomodificacion,
    movimientos_conceptos.fechamodificacion,
    movimientos_conceptos.tipo,
(SELECT JSON_ARRAYAGG(JSON_OBJECT('procesado', TRUE, 'mensaje', 'Completado con Éxito'))) AS resultado,
movimientos_conceptos.estado	
  FROM movimientos_conceptos
LEFT JOIN cuentas_contables on cuentas_contables.codigocontable = movimientos_conceptos.codigocontable
  WHERE movimientos_conceptos.movimientos_conceptosid = p_movimientos_conceptosid;

      ELSE
        SELECT
          JSON_ARRAYAGG(JSON_OBJECT('procesado', TRUE, 'mensaje', 'Completado con Éxito')) AS resultado;
      END IF;
    END IF;
  END IF;
END
;;
delimiter ;

