-- ----------------------------
-- Procedure structure for SP_ObtenerPromocionesAplicables
-- ----------------------------
DROP PROCEDURE IF EXISTS `SP_ObtenerPromocionesAplicables`;
delimiter ;;
CREATE PROCEDURE `SP_ObtenerPromocionesAplicables`(IN _AlmacenesID int,
  IN _ClienteID bigint,
  IN _GrupoClienteID bigint,
  IN _CategoriaProductoID bigint,
  IN _LineaProductoID bigint,
  IN _SubcategoriaProductoID int,
  IN _SubgrupoProductoID int,
  IN _ProductoID bigint,
  IN _MedidaID int,
  IN _VarianteID bigint, 
  IN _FechaActual datetime)
BEGIN

  DECLARE _DiaActual varchar(9);
  SET _DiaActual = DAYNAME(_FechaActual);
  -- Verificar si existen promociones activas dentro del rango de fechas
  IF EXISTS (SELECT
        1
      FROM promociones
      WHERE estado = 1
      AND _FechaActual BETWEEN promociones.fecha_inicio AND promociones.fecha_fin
      AND (FIND_IN_SET(_DiaActual, dias_validos) > 0)) THEN
    -- Promociones aplicables por almacén
  
    -- Promociones por aplicabilidad
    SELECT
      p.*
    FROM promociones p
      JOIN promociones_aplicabilidad pa
        ON p.promocionesid = pa.promocionesid
    WHERE (
    -- Promociones específicas para un cliente
    pa.clientesid = _ClienteID
    OR
    -- Promociones para un grupo de clientes
    pa.clientes_gruposid = _GrupoClienteID
    OR
    -- Promociones por categoría de producto
    pa.productos_categoriasid = _CategoriaProductoID
    OR
    -- Promociones por Linea de producto
    pa.productos_lineasid = _LineaProductoID
    OR
    -- Promociones por Subcategoría de producto
    pa.productos_subcategoriasid = _SubcategoriaProductoID
    OR
    -- Promociones por SubGrupo de producto
    pa.productos_subgruposid = _SubgrupoProductoID
    )
    AND _FechaActual BETWEEN p.fecha_inicio AND p.fecha_fin
    AND p.estado = 1
    AND (FIND_IN_SET(_DiaActual, dias_validos) > 0)
    UNION
    -- Promociones por no aplicabilidad

    SELECT
      p.*
    FROM promociones p
      LEFT JOIN promociones_aplicabilidad pa
        ON p.promocionesid = pa.promocionesid
      LEFT JOIN promociones_detalles pd
        ON p.promocionesid = pd.promocionesid
    WHERE _FechaActual BETWEEN p.fecha_inicio AND p.fecha_fin
    AND p.estado = 1
    AND (FIND_IN_SET(_DiaActual, dias_validos) > 0)
    AND pa.promocionesid IS NULL
    AND pd.promocionesid IS NULL
    UNION

    -- Promociones específicas por producto, medida y variante Sin Aplicabilidad
    SELECT
      p.*
    FROM promociones p
      JOIN promociones_detalles pd
        ON p.promocionesid = pd.promocionesid
      LEFT JOIN promociones_aplicabilidad pa
        ON p.promocionesid = pa.promocionesid
    WHERE pd.productosid = _ProductoID
    AND (pd.medidasid = _MedidaID)
    AND (pd.productos_variantesid = _VarianteID
    OR pd.productos_variantesid = 0)
    AND _FechaActual BETWEEN p.fecha_inicio AND p.fecha_fin
    AND pa.promocionesid IS NULL
    AND p.estado = 1
    AND (FIND_IN_SET(_DiaActual, dias_validos) > 0)
    UNION

    -- Promociones específicas por producto, medida y variante manejando Aplicabilidad
    SELECT
      p.*
    FROM promociones p
      JOIN promociones_detalles pd
        ON p.promocionesid = pd.promocionesid
      INNER JOIN promociones_aplicabilidad pa
        ON p.promocionesid = pa.promocionesid
    WHERE (
    -- Promociones específicas para un cliente
    pa.clientesid = _ClienteID
    OR
    -- Promociones para un grupo de clientes
    pa.clientes_gruposid = _GrupoClienteID
    OR
    -- Promociones por categoría de producto
    pa.productos_categoriasid = _CategoriaProductoID
    OR
    -- Promociones por Linea de producto
    pa.productos_lineasid = _LineaProductoID
    OR
    -- Promociones por Subcategoría de producto
    pa.productos_subcategoriasid = _SubcategoriaProductoID
    OR
    -- Promociones por SubGrupo de producto
    pa.productos_subgruposid = _SubgrupoProductoID
    )
    AND pd.productosid = _ProductoID
    AND (pd.medidasid = _MedidaID)
    AND (pd.productos_variantesid = _VarianteID
    OR pd.productos_variantesid = 0)
    AND _FechaActual BETWEEN p.fecha_inicio AND p.fecha_fin
    AND p.estado = 1
    AND (FIND_IN_SET(_DiaActual, dias_validos) > 0);
  ELSE
  -- Seleccion de una promocion inexistente para obtener un registro vacío
    SELECT
      p.*
    FROM promociones p
    WHERE p.promocionesid = 0;
  END IF;
END
;;
delimiter ;

-- ----------------------------
-- Procedure structure for SP_Productos_Actualizar_Costos
-- ----------------------------
DROP PROCEDURE IF EXISTS `SP_Productos_Actualizar_Costos`;
delimiter ;;
CREATE PROCEDURE `SP_Productos_Actualizar_Costos`(IN nProductoid BIGINT, IN sDecimales bigint)
  MODIFIES SQL DATA 
  SQL SECURITY INVOKER
BEGIN

-- Declaramos variables de Cursor
DECLARE termino INT DEFAULT FALSE;
DECLARE movinventariosid bigint(20);
DECLARE cantidad  decimal(20,8) DEFAULT 0;
DECLARE costo decimal(20,8) DEFAULT 0;
DECLARE costea tinyint(4);
DECLARE tipocalculo int(11);
DECLARE costoglobal decimal(20,8) DEFAULT 0;
DECLARE cost decimal(20,8) DEFAULT 0;
DECLARE canti decimal(20,8) DEFAULT 0;
DECLARE total decimal(20,8) DEFAULT 0;
DECLARE canta decimal(20,8) DEFAULT 0;
DECLARE costa decimal(20,8) DEFAULT 0;
DECLARE totala decimal(20,8) DEFAULT 0;

DECLARE Datos_Productos CURSOR FOR
SELECT 	
movinventarios.movinventariosid,
movinventarios.cantidad AS cantidad,	
movinventarios.costo AS costo,		
movinventarios_tipos.tipocalculo AS tipocalculo,	
movinventarios_tipos.costea AS costea
FROM 
almacenes,	
movinventarios,	
movinventarios_tipos
WHERE 
almacenes.almacenesid = movinventarios.almacenesid
AND	movinventarios_tipos.movinventarios_tiposid = movinventarios.movinventarios_tiposid
AND
(
movinventarios.productosid = nProductoid
AND ( movinventarios.anulado = 0 AND movinventarios.servicio = 0)
)
ORDER BY 	
movinventarios.fechamovimiento ASC, movinventarios_tipos.orden ASC;



-- Controlamos si hubo error
DECLARE exit handler FOR SQLEXCEPTION, SQLWARNING
BEGIN
ROLLBACK;
RESIGNAL;
END;

-- Declaramos el control de salida del loop
DECLARE CONTINUE HANDLER FOR NOT FOUND SET termino = TRUE;

-- Abrimos el Cursor
OPEN Datos_Productos;

-- Iniciamos la Transaccion
START TRANSACTION;
-- Leer Costo global
set costa=IFNULL((SELECT 	
movinventarios.costo AS costo
FROM 
almacenes,	
movinventarios,	
movinventarios_tipos
WHERE 
almacenes.almacenesid = movinventarios.almacenesid
AND	movinventarios_tipos.movinventarios_tiposid = movinventarios.movinventarios_tiposid
AND
(
movinventarios.productosid = nProductoid
AND ( movinventarios.anulado = 0 AND movinventarios.servicio = 0)
)
ORDER BY 	
movinventarios.fechamovimiento ASC,movinventarios_tipos.orden ASC
LIMIT 1),'0.00');

-- Leeemos el Cursor
read_loop: LOOP
FETCH Datos_Productos INTO movinventariosid, cantidad, costo, tipocalculo, costea;

-- Verificamos si no hay mas registros
IF termino THEN
LEAVE read_loop;
END IF;
SET cost		= costo;
SET canti		= cantidad;
SET total		= ROUND((cost*canti),sDecimales);

-- Pregunta si Costea
IF costea=1 THEN

IF tipocalculo=0 THEN

IF (ABS(canta)-ABS(canti)) > 0 THEN
  -- Error / 0
IF (ABS(canta)-ABS(canti)) = 0 THEN
SET costa = ROUND(((ABS(totala)-ABS(total))/1),sDecimales);
ELSE
SET costa = ROUND(((ABS(totala)-ABS(total))/(ABS(canta)-ABS(canti))),sDecimales);
END IF;

END IF;

ELSE
-- Error / 0
IF (ABS(canta)+ABS(canti))=0 THEN
SET costa = ROUND(((ABS(totala)+ABS(total))/1),sDecimales);
  ELSE
SET costa = ROUND(((ABS(totala)+ABS(total))/(ABS(canta)+ABS(canti))),sDecimales);
END IF;

END IF;

ELSE
-- Error / 0
 IF (ABS(canta)+ABS(canti)) =0 THEN
SET costa = ROUND(((ABS(totala)+ABS(total))/1),sDecimales);
 ELSE
SET costa = ROUND(ABS(costa),sDecimales);
END IF;

END IF;

-- Pregunta tipo de Calculo
IF tipocalculo=1 THEN
SET canta = canta+canti;
ELSE
SET canta=canta - canti;
END IF;

SET totala	= ROUND((canta * costa),sDecimales);		
SET costa	= Round(costa,sDecimales);

-- Actualizamos el Costo en Movinventarios
IF costea<>1 THEN
UPDATE 
movinventarios
SET
movinventarios.costo = costa
WHERE
movinventarios.movinventariosid = movinventariosid;

END IF;


END LOOP;
-- Actualizamos Costo del producto
UPDATE productos
SET
productos.costoactual = costa		
WHERE
productos.productosid = nProductoid;


COMMIT;
-- Cerramos el Cursor
CLOSE Datos_Productos;
 
END
;;
delimiter ;

-- ----------------------------
-- Procedure structure for SP_Productos_Actualizar_Costos_Totales_Detalles
-- ----------------------------
DROP PROCEDURE IF EXISTS `SP_Productos_Actualizar_Costos_Totales_Detalles`;
delimiter ;;
CREATE PROCEDURE `SP_Productos_Actualizar_Costos_Totales_Detalles`(IN pid bigint)
  MODIFIES SQL DATA 
  SQL SECURITY INVOKER
BEGIN

-- Declaramos variables de Cursor
-- Controlamos si hubo error
DECLARE exit handler FOR SQLEXCEPTION, SQLWARNING
  BEGIN
    ROLLBACK;
    RESIGNAL;
  END;

-- Iniciamos la Transaccion
START TRANSACTION;
IF pid = 0 THEN
-- Actualizar facturas detalles
UPDATE facturas_detalles
INNER JOIN
movinventarios
ON (facturas_detalles.facturasid = movinventarios.documentosid AND facturas_detalles.facturas_detallesid = movinventarios.documento_detallesid AND movinventarios.movinventarios_tiposid IN (3,4))
SET
facturas_detalles.costo = movinventarios.costo;
-- Actualizar facturas detalles servicios compuestos
UPDATE facturas_detalles
INNER JOIN
movinventarios
ON (facturas_detalles.facturasid = movinventarios.documentosid AND facturas_detalles.facturas_detallesid = movinventarios.documento_detallesid AND movinventarios.movinventarios_tiposid IN (15,16))
SET
facturas_detalles.costo = movinventarios.costo;
-- Actualizamos Entregas Detalles
UPDATE entregas_detalles
INNER JOIN
movinventarios
ON (entregas_detalles.entregasid = movinventarios.documentosid AND entregas_detalles.entregas_detallesid = movinventarios.documento_detallesid AND movinventarios.movinventarios_tiposid IN (9))
SET
entregas_detalles.costo = movinventarios.costo;
-- Actualizamos Salidas detalles
UPDATE salidas_detalles
INNER JOIN
movinventarios
ON (salidas_detalles.salidasid = movinventarios.documentosid AND salidas_detalles.salidas_detallesid = movinventarios.documento_detallesid AND movinventarios.movinventarios_tiposid = 8)
SET
salidas_detalles.costo = movinventarios.costo;

-- Actualizamos Salidas detalles Produccion
UPDATE salidas_detalles
INNER JOIN
movinventarios
ON (salidas_detalles.salidasid = movinventarios.documentosid AND salidas_detalles.salidas_detallesid = movinventarios.documento_detallesid AND movinventarios.movinventarios_tiposid = 11 )
INNER JOIN 
movinventarios_tipos ON (movinventarios_tipos.movinventarios_tiposid = movinventarios.movinventarios_tiposid AND  movinventarios_tipos.costea = 0 )
SET
salidas_detalles.costo = movinventarios.costo;
-- Actualizar Transferencias detalles
UPDATE transferencias_detalles
INNER JOIN
movinventarios
ON (transferencias_detalles.transferenciasid = movinventarios.documentosid AND transferencias_detalles.transferencias_detallesid = movinventarios.documento_detallesid AND movinventarios.movinventarios_tiposid = 6)
SET
transferencias_detalles.costo = movinventarios.costo;

-- Actualizar Total Salidas
UPDATE salidas
SET
salidas.total = IFNULL(ROUND(( 
SELECT 
sum(salidas_detalles.cantidad*salidas_detalles.costo) as valor 
from 
salidas_detalles
where 
salidas_detalles.salidasid = salidas.salidasid),8),0.00);
-- Actualizar Total Transferencias
UPDATE transferencias
SET
transferencias.total = 	IFNULL(ROUND((
SELECT 
SUM(transferencias_detalles.cantidad*transferencias_detalles.costo) AS valor 
FROM 
transferencias_detalles 
WHERE 
transferencias_detalles.transferenciasid = transferencias.transferenciasid
),8),0.00);
ELSE
  -- Actualizar facturas detalles
    UPDATE facturas_detalles
    INNER JOIN
    movinventarios
    ON (facturas_detalles.facturasid = movinventarios.documentosid AND facturas_detalles.facturas_detallesid = movinventarios.documento_detallesid AND movinventarios.movinventarios_tiposid IN (3,4))
    SET
    facturas_detalles.costo = movinventarios.costo
    WHERE facturas_detalles.productosid = pid;
    -- Actualizar facturas detalles servicios compuestos
    UPDATE facturas_detalles
    INNER JOIN
    movinventarios
    ON (facturas_detalles.facturasid = movinventarios.documentosid AND facturas_detalles.facturas_detallesid = movinventarios.documento_detallesid AND movinventarios.movinventarios_tiposid IN (15,16))
    SET
    facturas_detalles.costo = movinventarios.costo
    WHERE facturas_detalles.productosid = pid;
    -- Actualizamos Entregas Detalles
    UPDATE entregas_detalles
    INNER JOIN
    movinventarios
    ON (entregas_detalles.entregasid = movinventarios.documentosid AND entregas_detalles.entregas_detallesid = movinventarios.documento_detallesid AND movinventarios.movinventarios_tiposid IN (9))
    SET
    entregas_detalles.costo = movinventarios.costo
    WHERE entregas_detalles.productosid = pid;
    -- Actualizamos Salidas detalles
    UPDATE salidas_detalles
    INNER JOIN
    movinventarios
    ON (salidas_detalles.salidasid = movinventarios.documentosid AND salidas_detalles.salidas_detallesid = movinventarios.documento_detallesid AND movinventarios.movinventarios_tiposid = 8)
    SET
    salidas_detalles.costo = movinventarios.costo
    WHERE salidas_detalles.productosid = pid;

   -- ASalidas detalles Produccion
    UPDATE salidas_detalles
    INNER JOIN
    movinventarios
    ON (salidas_detalles.salidasid = movinventarios.documentosid AND salidas_detalles.salidas_detallesid = movinventarios.documento_detallesid)
    INNER JOIN 
movinventarios_tipos ON (movinventarios_tipos.movinventarios_tiposid = movinventarios.movinventarios_tiposid)
    SET
    salidas_detalles.costo = movinventarios.costo
    WHERE salidas_detalles.productosid = pid
and  movinventarios_tipos.costea = 0    
    and movinventarios.movinventarios_tiposid = 11;
    
    -- Actualizar Transferencias detalles
    UPDATE transferencias_detalles
    INNER JOIN
    movinventarios
    ON (transferencias_detalles.transferenciasid = movinventarios.documentosid AND transferencias_detalles.transferencias_detallesid = movinventarios.documento_detallesid AND movinventarios.movinventarios_tiposid = 6)
    SET
    transferencias_detalles.costo = movinventarios.costo
    WHERE transferencias_detalles.productosid = pid;

    -- Actualizar Total Salidas
    UPDATE salidas s
    JOIN (
    SELECT sd.salidasid, SUM(sd.cantidad * sd.costo) AS total
    FROM salidas_detalles sd
    GROUP BY sd.salidasid
    ) AS totales ON totales.salidasid = s.salidasid
    SET s.total = IFNULL(ROUND(totales.total, 8), 0.00)
    WHERE s.salidasid IN (
    SELECT DISTINCT sd2.salidasid
    FROM salidas_detalles sd2
    WHERE sd2.productosid = pid
    );
   
    
    
    -- Actualizar Total Transferencias
   UPDATE transferencias t
    JOIN (
    SELECT td.transferenciasid, SUM(td.cantidad * td.costo) AS total
    FROM transferencias_detalles td
    GROUP BY td.transferenciasid
    ) AS totales ON totales.transferenciasid = t.transferenciasid
    SET t.total = IFNULL(ROUND(totales.total, 8), 0.00)
    WHERE t.transferenciasid IN (
    SELECT DISTINCT td2.transferenciasid
    FROM transferencias_detalles td2
    WHERE td2.productosid = pid
    );

END IF;

-- Actualizar Fecha Cero
UPDATE
productos
SET
productos.fechacreacion = Now()
where
productos.fechacreacion = '0000-00-00 00:00:00.000';
COMMIT;

END
;;
delimiter ;

-- ----------------------------
-- Procedure structure for SP_Productos_Actualizar_Costos_Totales_Detalles_Hora
-- ----------------------------
DROP PROCEDURE IF EXISTS `SP_Productos_Actualizar_Costos_Totales_Detalles_Hora`;
delimiter ;;
CREATE PROCEDURE `SP_Productos_Actualizar_Costos_Totales_Detalles_Hora`(IN nDocumentoid LONGTEXT, IN fecha DATETIME)
  MODIFIES SQL DATA 
  SQL SECURITY INVOKER
BEGIN

-- Declaramos variables de Cursor
-- Controlamos si hubo error
DECLARE exit handler FOR SQLEXCEPTION, SQLWARNING
  BEGIN
    ROLLBACK;
    RESIGNAL;
  END;

-- Iniciamos la Transaccion
START TRANSACTION;

DROP TEMPORARY TABLE IF EXISTS tabla_temporal_id;

CREATE TEMPORARY TABLE tabla_temporal_id AS
SELECT *
FROM JSON_TABLE(nDocumentoid, -- Reemplaza esto con tu arreglo JSON de IDs
  '$[*]' COLUMNS(productosid INT PATH '$')
) AS jt;

-- Actualizar facturas detalles
UPDATE facturas_detalles
INNER JOIN
movinventarios
ON (facturas_detalles.facturasid = movinventarios.documentosid AND facturas_detalles.facturas_detallesid = movinventarios.documento_detallesid AND movinventarios.movinventarios_tiposid IN (3,4))
JOIN tabla_temporal_id
    ON movinventarios.productosid = tabla_temporal_id.productosid
     SET
facturas_detalles.costo = movinventarios.costo
    WHERE movinventarios.fechamovimiento > fecha;
-- Actualizar facturas detalles servicios compuestos
UPDATE facturas_detalles
INNER JOIN
movinventarios
ON (facturas_detalles.facturasid = movinventarios.documentosid AND facturas_detalles.facturas_detallesid = movinventarios.documento_detallesid AND movinventarios.movinventarios_tiposid IN (15,16))
JOIN tabla_temporal_id
    ON movinventarios.productosid = tabla_temporal_id.productosid
    SET
facturas_detalles.costo = movinventarios.costo
    WHERE movinventarios.fechamovimiento > fecha;
-- Actualizamos Entregas Detalles
UPDATE entregas_detalles
INNER JOIN
movinventarios
ON (entregas_detalles.entregasid = movinventarios.documentosid AND entregas_detalles.entregas_detallesid = movinventarios.documento_detallesid AND movinventarios.movinventarios_tiposid IN (9))
JOIN tabla_temporal_id
    ON movinventarios.productosid = tabla_temporal_id.productosid
    SET
entregas_detalles.costo = movinventarios.costo
    WHERE movinventarios.fechamovimiento > fecha;
-- Actualizamos Salidas detalles
UPDATE salidas_detalles
INNER JOIN
movinventarios
ON (salidas_detalles.salidasid = movinventarios.documentosid AND salidas_detalles.salidas_detallesid = movinventarios.documento_detallesid AND movinventarios.movinventarios_tiposid = 8)
JOIN tabla_temporal_id
    ON movinventarios.productosid = tabla_temporal_id.productosid
    SET
salidas_detalles.costo = movinventarios.costo
    WHERE movinventarios.fechamovimiento > fecha;
    
-- Actualizar Salidas Produccion 
UPDATE salidas_detalles
INNER JOIN
movinventarios
ON (salidas_detalles.salidasid = movinventarios.documentosid AND salidas_detalles.salidas_detallesid = movinventarios.documento_detallesid AND movinventarios.movinventarios_tiposid = 11)
    JOIN 
    movinventarios_tipos ON (movinventarios_tipos.movinventarios_tiposid = movinventarios.movinventarios_tiposid AND  movinventarios_tipos.costea = 0 )
JOIN tabla_temporal_id
    ON movinventarios.productosid = tabla_temporal_id.productosid
    SET
salidas_detalles.costo = movinventarios.costo
    WHERE movinventarios.fechamovimiento > fecha;
    
-- Actualizar Transferencias detalles
UPDATE transferencias_detalles
INNER JOIN
movinventarios
ON (transferencias_detalles.transferenciasid = movinventarios.documentosid AND transferencias_detalles.transferencias_detallesid = movinventarios.documento_detallesid AND movinventarios.movinventarios_tiposid = 6)
JOIN tabla_temporal_id
    ON movinventarios.productosid = tabla_temporal_id.productosid
    SET
transferencias_detalles.costo = movinventarios.costo
    WHERE movinventarios.fechamovimiento > fecha;

-- Actualizar Total Salidas
UPDATE salidas
SET
salidas.total = IFNULL(ROUND(( 
SELECT 
sum(salidas_detalles.cantidad*salidas_detalles.costo) as valor 
from 
salidas_detalles
where 
salidas_detalles.salidasid = salidas.salidasid ),8),0.00)
   WHERE EXISTS (
    SELECT 1
    FROM salidas_detalles 
    INNER JOIN tabla_temporal_id  ON salidas_detalles.productosid = tabla_temporal_id.productosid
    WHERE salidas_detalles.salidasid = salidas.salidasid
) and salidas.fecha > fecha;
    
-- Actualizar Total Transferencias
UPDATE transferencias
SET
transferencias.total = 	IFNULL(ROUND((
SELECT 
SUM(transferencias_detalles.cantidad*transferencias_detalles.costo) AS valor 
FROM 
transferencias_detalles 
WHERE 
transferencias_detalles.transferenciasid = transferencias.transferenciasid
),8),0.00)
    WHERE EXISTS (
      SELECT 1
      FROM transferencias_detalles 
      INNER JOIN tabla_temporal_id  ON transferencias_detalles.productosid = tabla_temporal_id.productosid
      WHERE transferencias_detalles.transferenciasid = transferencias.transferenciasid
) AND transferencias.fecha > fecha;
    
-- Actualizar Fecha Cero
UPDATE
productos
SET
productos.fechacreacion = Now()
where
productos.fechacreacion = '0000-00-00 00:00:00.000';
COMMIT;

END
;;
delimiter ;

-- ----------------------------
-- Procedure structure for SP_Productos_Actualizar_Costos_UltimaCompra
-- ----------------------------
DROP PROCEDURE IF EXISTS `SP_Productos_Actualizar_Costos_UltimaCompra`;
delimiter ;;
CREATE PROCEDURE `SP_Productos_Actualizar_Costos_UltimaCompra`()
BEGIN
-- Controlamos SI hubo Error
DECLARE exit handler FOR SQLEXCEPTION, SQLWARNING
BEGIN
ROLLBACK;
RESIGNAL;
END;
-- Iniciamos la Transaccion
START TRANSACTION;

-- -Actualiza costos ultima compra de todos los productos 
UPDATE
productos
SET
productos.costoultimacompra = (
SELECT	movinventarios.costo
FROM
movinventarios
JOIN
movinventarios_tipos ON movinventarios.movinventarios_tiposid = movinventarios_tipos.movinventarios_tiposid
WHERE
movinventarios.movinventarios_tiposid IN (1,7,10,12)
AND
movinventarios.productosid = productos.productosid
ORDER BY
movinventarios.fechamovimiento DESC,
movinventarios_tipos.orden DESC,
movinventarios.movinventariosid DESC
LIMIT 1 ),
productos.fechaultimacompra = (
SELECT	DATE(movinventarios.fechamovimiento)
FROM
movinventarios
JOIN
movinventarios_tipos ON movinventarios.movinventarios_tiposid = movinventarios_tipos.movinventarios_tiposid
WHERE
movinventarios.movinventarios_tiposid IN (1,7,10,12)
AND
movinventarios.productosid = productos.productosid
ORDER BY
movinventarios.fechamovimiento DESC,
movinventarios_tipos.orden DESC,
movinventarios.movinventariosid DESC
LIMIT 1 )
WHERE
productos.productosid IN (
SELECT DISTINCT
movinventarios.productosid
FROM
movinventarios
WHERE
movinventarios.movinventarios_tiposid IN (1,7,10,12)
);


COMMIT;
END
;;
delimiter ;

