-- ----------------------------
-- Procedure structure for SP_Productos_Actualizar_Existencias
-- ----------------------------
DROP PROCEDURE IF EXISTS `SP_Productos_Actualizar_Existencias`;
delimiter ;;
CREATE PROCEDURE `SP_Productos_Actualizar_Existencias`()
  MODIFIES SQL DATA 
  SQL SECURITY INVOKER
BEGIN

-- Controlamos si hubo error
DECLARE exit handler FOR SQLEXCEPTION, SQLWARNING
BEGIN
ROLLBACK;
RESIGNAL;
END;



-- Iniciamos la Transaccion
START TRANSACTION;
-- Actualizamos Existencias del producto
UPDATE
productos
SET
productos.existenciastotales = 0
WHERE
productos.bien = 1
OR 
productos.servicio = 1
OR
productos.venta = 0;


/* Actuliza la existenia a los productos segun los movimientos de inventario  */	
UPDATE
productos
SET
productos.existenciastotales=
(SELECT 
IFNULL(SUM(CASE WHEN  movinventarios_tipos.tipocalculo=1
THEN movinventarios.cantidad
ELSE -movinventarios.cantidad END),0) AS stock
FROM 
movinventarios_tipos
INNER JOIN	
(movinventarios
)ON movinventarios_tipos.movinventarios_tiposid = movinventarios.movinventarios_tiposid
WHERE 
movinventarios.productosid = productos.productosid
AND ( movinventarios.anulado = 0 AND movinventarios.servicio = 0)
);

/* Actuliza la existenia a los productos a cada almacen segun los movimientos de inventario  */	
UPDATE movinventarios_almacenes
SET
movinventarios_almacenes.existencias=(
SELECT 
IFNULL(SUM(CASE WHEN movinventarios_tipos.tipocalculo=1 THEN movinventarios.cantidad  ELSE -movinventarios.cantidad  END ),0) AS stock
FROM 
movinventarios_tipos
INNER JOIN	
(movinventarios
)ON movinventarios_tipos.movinventarios_tiposid = movinventarios.movinventarios_tiposid
WHERE 
(
movinventarios.productosid = movinventarios_almacenes.productosid
AND	movinventarios.almacenesid = movinventarios_almacenes.almacenesid
AND ( movinventarios.anulado = 0 AND movinventarios.servicio = 0)
)
);

COMMIT;
END
;;
delimiter ;

-- ----------------------------
-- Procedure structure for SP_productos_categorias_ABC
-- ----------------------------
DROP PROCEDURE IF EXISTS `SP_productos_categorias_ABC`;
delimiter ;;
CREATE PROCEDURE `SP_productos_categorias_ABC`(IN pAccion varchar(1), IN pRegistrosJson json)
BEGIN
  DECLARE vJsonEsValido int;
  DECLARE vItems int;
  DECLARE vIndex bigint UNSIGNED DEFAULT 0;
  DECLARE vErrorMensaje text;
  DECLARE vRegistroAnterior longtext;


  # VARIABLES DE LOS DATOS DE LA TABLA
  DECLARE p_productos_categoriasid bigint(20);
  DECLARE p_descripcion varchar(50) DEFAULT '';
  DECLARE p_imagen longblob DEFAULT NULL;
  DECLARE p_ecommerceid int(11) DEFAULT 1;
  DECLARE p_parametros_json varchar(500) DEFAULT '';
  DECLARE p_fechacreacion datetime(3) DEFAULT '0000-00-00 00:00:00.000';
  DECLARE p_usuariocreacion varchar(25) DEFAULT '';
  DECLARE p_fechamodificacion datetime(3) DEFAULT '0000-00-00 00:00:00.000';
  DECLARE p_usuariomodificacion varchar(25) DEFAULT '';


  # VARIABLE DE LOS DATOS DE LA AUDITORIA
  DECLARE p_sis_subcategoriasid int(11) DEFAULT 0;
  DECLARE p_sis_empresasid int(11) DEFAULT 0;
  DECLARE p_sis_usuariosid varchar(20) DEFAULT '';
  DECLARE p_equipo varchar(50) DEFAULT '';
  DECLARE p_tipooperacion varchar(50) DEFAULT '';
  DECLARE p_detalle longtext;

  # CONTROLAMOS SI HAY ERROR
  DECLARE EXIT HANDLER FOR SQLEXCEPTION, SQLWARNING
  BEGIN
    GET DIAGNOSTICS CONDITION 1 vErrorMensaje = MESSAGE_TEXT;
    SELECT
      CASE WHEN LOCATE('Cannot delete or update a parent row',vErrorMensaje)>0 THEN JSON_ARRAYAGG(JSON_OBJECT('procesado', FALSE, 'mensaje', 'No Se Puede Eliminar, Categoría en Uso')) ELSE JSON_ARRAYAGG(JSON_OBJECT('procesado', FALSE, 'mensaje', vErrorMensaje)) END AS resultado;
    ROLLBACK;
  END;
  # VALIDAMOS SI EL OBJETO JSON ES VALIDO 
  SET vJsonEsValido = JSON_VALID(pRegistrosJson);

  IF vJsonEsValido = 0 THEN
    # EL OBJETO JSON NO ES VALIDO
    SELECT
      JSON_ARRAYAGG(JSON_OBJECT('procesado', FALSE, 'mensaje', 'Json no es valido')) AS resultado;
  ELSE

    # VALIDAMOS QUE TENGA ALMENOS UN ELEMENTO
    SET vItems = JSON_LENGTH(pRegistrosJson, '$.cabecera');

    IF vItems > 0 THEN
      START TRANSACTION;
        WHILE vIndex < vItems DO

          # DATOS TABLA
          SET p_productos_categoriasid = IFNULL(JSON_UNQUOTE(JSON_EXTRACT(pRegistrosJson, CONCAT('$.cabecera[', vIndex, '].productos_categoriasid'))), p_productos_categoriasid);
          SET p_descripcion = IFNULL(JSON_UNQUOTE(JSON_EXTRACT(pRegistrosJson, CONCAT('$.cabecera[', vIndex, '].descripcion'))), p_descripcion);
          SET p_ecommerceid = IFNULL(JSON_UNQUOTE(JSON_EXTRACT(pRegistrosJson, CONCAT('$.cabecera[', vIndex, '].ecommerceid'))), p_ecommerceid);


          # DATOS AUDITORIA
          SET p_sis_subcategoriasid = JSON_UNQUOTE(JSON_EXTRACT(pRegistrosJson, CONCAT('$.cabecera[', vIndex, '].sis_subcategoriasid')));
          SET p_sis_empresasid = JSON_UNQUOTE(JSON_EXTRACT(pRegistrosJson, CONCAT('$.cabecera[', vIndex, '].sis_empresasid')));
          SET p_sis_usuariosid = JSON_UNQUOTE(JSON_EXTRACT(pRegistrosJson, CONCAT('$.cabecera[', vIndex, '].sis_usuariosid')));
          SET p_equipo = JSON_UNQUOTE(JSON_EXTRACT(pRegistrosJson, CONCAT('$.cabecera[', vIndex, '].equipo')));


          CASE pAccion
            WHEN 'C' THEN SET p_tipooperacion = 'N';
            	
  SET p_imagen = FROM_BASE64(JSON_UNQUOTE(JSON_EXTRACT(pRegistrosJson, CONCAT('$.cabecera[', vIndex, '].imagen'))));
                IF p_imagen = '' THEN
                  set p_imagen = NULL;
                END IF;
  SET p_parametros_json = IFNULL(FROM_BASE64(JSON_UNQUOTE(JSON_EXTRACT(pRegistrosJson, CONCAT('$.cabecera[', vIndex, '].parametros_json')))),p_parametros_json);
                SET p_fechacreacion = NOW(3);
                SET p_usuariocreacion = JSON_UNQUOTE(JSON_EXTRACT(pRegistrosJson, CONCAT('$.cabecera[', vIndex, '].usuariocreacion')));
                SET p_fechamodificacion = NULL;
                SET p_usuariomodificacion = '';
                SET p_detalle = REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(JSON_INSERT('{}', '$.productos_categorias', JSON_EXTRACT(pRegistrosJson, CONCAT('$.cabecera[', vIndex, ']'))), '"[', '['), ']"', ']'), '\\', ''), '"{', '{'), '}"', '}');

                # INSERTAMOS LOS REGISTROS
                INSERT INTO productos_categorias (productos_categoriasid, descripcion, imagen, ecommerceid, parametros_json, fechacreacion, usuariocreacion, fechamodificacion, usuariomodificacion)
                  VALUES (p_productos_categoriasid, p_descripcion, p_imagen, p_ecommerceid, p_parametros_json, p_fechacreacion, p_usuariocreacion, p_fechamodificacion, p_usuariomodificacion);

                SET p_productos_categoriasid = LAST_INSERT_ID();

            WHEN 'M' THEN SET p_tipooperacion = 'M';
            	
  SET p_imagen = FROM_BASE64(JSON_UNQUOTE(JSON_EXTRACT(pRegistrosJson, CONCAT('$.cabecera[', vIndex, '].imagen'))));
                IF p_imagen = '' THEN
                  set p_imagen = NULL;
                END IF;
  SET p_parametros_json = IFNULL(FROM_BASE64(JSON_UNQUOTE(JSON_EXTRACT(pRegistrosJson, CONCAT('$.cabecera[', vIndex, '].parametros_json')))),p_parametros_json);
                SET p_fechamodificacion = NOW(3);
                SET p_usuariomodificacion = JSON_UNQUOTE(JSON_EXTRACT(pRegistrosJson, CONCAT('$.cabecera[', vIndex, '].usuariomodificacion')));


                SET vRegistroAnterior = (SELECT
                    JSON_OBJECT
                    (
                    'productos_categoriasid', productos_categoriasid,
                    'descripcion', descripcion,
                    'imagen', HEX(imagen),
                    'ecommerceid', ecommerceid,
                    'parametros_json', TO_BASE64(parametros_json),
                    'fechamodificacion', fechamodificacion,
                    'usuariomodificacion', usuariomodificacion
                    )
                  FROM productos_categorias
                  WHERE productos_categorias.productos_categoriasid = p_productos_categoriasid);

                SET p_detalle = REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(JSON_INSERT('{}', '$.productos_categorias', vRegistroAnterior), '"[', '['), ']"', ']'), '\\', ''), '"{', '{'), '}"', '}');

                # ACTUALIZAMOS LOS REGISTROS
                UPDATE productos_categorias
                SET productos_categoriasid = p_productos_categoriasid,
                    descripcion = p_descripcion,
                    imagen = p_imagen,
                    ecommerceid = p_ecommerceid,
                    parametros_json = p_parametros_json,
                    fechamodificacion = p_fechamodificacion,
                    usuariomodificacion = p_usuariomodificacion
                WHERE productos_categoriasid = p_productos_categoriasid;

            WHEN 'E' THEN SET p_tipooperacion = 'E';
                SET p_detalle = REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(JSON_INSERT('{}', '$.productos_categorias', JSON_EXTRACT(pRegistrosJson, CONCAT('$.cabecera[', vIndex, ']'))), '"[', '['), ']"', ']'), '\\', ''), '"{', '{'), '}"', '}');

                # ELIMINAMOS LOS REGISTROS
                DELETE
                  FROM productos_categorias
                WHERE productos_categoriasid = p_productos_categoriasid;

          END CASE;

          # INSERTAMOS LA AUDITORIA
          CALL sistemaperseo.SP_ABC_sis_log_sistema(p_sis_subcategoriasid, p_sis_empresasid, p_sis_usuariosid, p_tipooperacion, p_detalle, p_equipo);

          SET vIndex = vIndex + 1;
        END WHILE;
      COMMIT;


      # RETORNAMOS LA RESPUESTAS
      IF pAccion IN ('C', 'M') THEN

        SELECT
          productos_categorias.productos_categoriasid,
          productos_categorias.descripcion,
          productos_categorias.imagen,
          productos_categorias.ecommerceid,
          productos_categorias.parametros_json,
          productos_categorias.fechacreacion,
          productos_categorias.usuariocreacion,
          productos_categorias.fechamodificacion,
          productos_categorias.usuariomodificacion,
          (SELECT
              JSON_ARRAYAGG(JSON_OBJECT('procesado', TRUE, 'mensaje', 'Completado con Éxito'))) AS resultado
        FROM productos_categorias
        WHERE productos_categorias.productos_categoriasid = p_productos_categoriasid;

      ELSE
        SELECT
          JSON_ARRAYAGG(JSON_OBJECT('procesado', TRUE, 'mensaje', 'Completado con Éxito')) AS resultado;
      END IF;
    END IF;
  END IF;
END
;;
delimiter ;

-- ----------------------------
-- Procedure structure for SP_productos_categorias_ConsultarID
-- ----------------------------
DROP PROCEDURE IF EXISTS `SP_productos_categorias_ConsultarID`;
delimiter ;;
CREATE PROCEDURE `SP_productos_categorias_ConsultarID`(IN p_productos_categoriasid int(11))
BEGIN

  SELECT
    productos_categorias.productos_categoriasid,
    productos_categorias.descripcion,
    productos_categorias.imagen,
    productos_categorias.ecommerceid,
    productos_categorias.parametros_json,
    productos_categorias.fechacreacion,
    productos_categorias.usuariocreacion,
    productos_categorias.fechamodificacion,
    productos_categorias.usuariomodificacion
  FROM productos_categorias
  WHERE productos_categorias.productos_categoriasid = p_productos_categoriasid;

END
;;
delimiter ;

-- ----------------------------
-- Procedure structure for SP_productos_lineas_ABC
-- ----------------------------
DROP PROCEDURE IF EXISTS `SP_productos_lineas_ABC`;
delimiter ;;
CREATE PROCEDURE `SP_productos_lineas_ABC`(IN pAccion varchar(1), IN pRegistrosJson json)
BEGIN
  DECLARE vJsonEsValido int;
  DECLARE vItems int;
  DECLARE vIndex bigint UNSIGNED DEFAULT 0;
  DECLARE vErrorMensaje text;
  DECLARE vRegistroAnterior longtext;


  # VARIABLES DE LOS DATOS DE LA TABLA
  DECLARE p_productos_lineasid bigint(20);
  DECLARE p_descripcion varchar(50) DEFAULT '';
  DECLARE p_imagen longblob DEFAULT NULL;
  DECLARE p_ecommerceid int(11) DEFAULT 1;
  DECLARE p_cuentacontable_inventarios varchar(30) DEFAULT '';
  DECLARE p_cuentacontable_ventas varchar(30) DEFAULT '';
  DECLARE p_cuentacontable_costo varchar(30) DEFAULT '';
  DECLARE p_parametros_json varchar(500) DEFAULT '';
  DECLARE p_fechacreacion datetime(3) DEFAULT '0000-00-00 00:00:00.000';
  DECLARE p_usuariocreacion varchar(25) DEFAULT '';
  DECLARE p_fechamodificacion datetime(3) DEFAULT '0000-00-00 00:00:00.000';
  DECLARE p_usuariomodificacion varchar(25) DEFAULT '';


  # VARIABLE DE LOS DATOS DE LA AUDITORIA
  DECLARE p_sis_subcategoriasid int(11) DEFAULT 0;
  DECLARE p_sis_empresasid int(11) DEFAULT 0;
  DECLARE p_sis_usuariosid varchar(20) DEFAULT '';
  DECLARE p_equipo varchar(50) DEFAULT '';
  DECLARE p_tipooperacion varchar(50) DEFAULT '';
  DECLARE p_detalle longtext;

  # CONTROLAMOS SI HAY ERROR
  DECLARE EXIT HANDLER FOR SQLEXCEPTION, SQLWARNING
  BEGIN
    GET DIAGNOSTICS CONDITION 1 vErrorMensaje = MESSAGE_TEXT;
    SELECT
      CASE WHEN LOCATE('Cannot delete or update a parent row',vErrorMensaje)>0 THEN JSON_ARRAYAGG(JSON_OBJECT('procesado', FALSE, 'mensaje', 'No Se Puede Eliminar, Línea en Uso')) ELSE JSON_ARRAYAGG(JSON_OBJECT('procesado', FALSE, 'mensaje', vErrorMensaje)) END AS resultado;
    ROLLBACK;
  END;
  # VALIDAMOS SI EL OBJETO JSON ES VALIDO 
  SET vJsonEsValido = JSON_VALID(pRegistrosJson);

  IF vJsonEsValido = 0 THEN
    # EL OBJETO JSON NO ES VALIDO
    SELECT
      JSON_ARRAYAGG(JSON_OBJECT('procesado', FALSE, 'mensaje', 'Json no es valido')) AS resultado;
  ELSE

    # VALIDAMOS QUE TENGA ALMENOS UN ELEMENTO
    SET vItems = JSON_LENGTH(pRegistrosJson, '$.cabecera');

    IF vItems > 0 THEN
      START TRANSACTION;
        WHILE vIndex < vItems DO

          # DATOS TABLA
          SET p_productos_lineasid = IFNULL(JSON_UNQUOTE(JSON_EXTRACT(pRegistrosJson, CONCAT('$.cabecera[', vIndex, '].productos_lineasid'))), p_productos_lineasid);
          SET p_descripcion = IFNULL(JSON_UNQUOTE(JSON_EXTRACT(pRegistrosJson, CONCAT('$.cabecera[', vIndex, '].descripcion'))), p_descripcion);
          SET p_ecommerceid = IFNULL(JSON_UNQUOTE(JSON_EXTRACT(pRegistrosJson, CONCAT('$.cabecera[', vIndex, '].ecommerceid'))), p_ecommerceid);
          SET p_cuentacontable_inventarios = IFNULL(JSON_UNQUOTE(JSON_EXTRACT(pRegistrosJson, CONCAT('$.cabecera[', vIndex, '].cuentacontable_inventarios'))), p_cuentacontable_inventarios);
          SET p_cuentacontable_ventas = IFNULL(JSON_UNQUOTE(JSON_EXTRACT(pRegistrosJson, CONCAT('$.cabecera[', vIndex, '].cuentacontable_ventas'))), p_cuentacontable_ventas);
          SET p_cuentacontable_costo = IFNULL(JSON_UNQUOTE(JSON_EXTRACT(pRegistrosJson, CONCAT('$.cabecera[', vIndex, '].cuentacontable_costo'))), p_cuentacontable_costo);

          # DATOS AUDITORIA
          SET p_sis_subcategoriasid = JSON_UNQUOTE(JSON_EXTRACT(pRegistrosJson, CONCAT('$.cabecera[', vIndex, '].sis_subcategoriasid')));
          SET p_sis_empresasid = JSON_UNQUOTE(JSON_EXTRACT(pRegistrosJson, CONCAT('$.cabecera[', vIndex, '].sis_empresasid')));
          SET p_sis_usuariosid = JSON_UNQUOTE(JSON_EXTRACT(pRegistrosJson, CONCAT('$.cabecera[', vIndex, '].sis_usuariosid')));
          SET p_equipo = JSON_UNQUOTE(JSON_EXTRACT(pRegistrosJson, CONCAT('$.cabecera[', vIndex, '].equipo')));


          CASE pAccion

            WHEN 'C' THEN SET p_tipooperacion = 'N';

  SET p_imagen = FROM_BASE64(JSON_UNQUOTE(JSON_EXTRACT(pRegistrosJson, CONCAT('$.cabecera[', vIndex, '].imagen'))));
                IF p_imagen = '' THEN
                  set p_imagen = NULL;
                END IF;
  SET p_parametros_json = IFNULL(FROM_BASE64(JSON_UNQUOTE(JSON_EXTRACT(pRegistrosJson, CONCAT('$.cabecera[', vIndex, '].parametros_json')))),p_parametros_json);
                SET p_fechacreacion = NOW(3);
                SET p_usuariocreacion = JSON_UNQUOTE(JSON_EXTRACT(pRegistrosJson, CONCAT('$.cabecera[', vIndex, '].usuariocreacion')));
                SET p_fechamodificacion = NULL;
                SET p_usuariomodificacion = '';
                SET p_detalle = REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(JSON_INSERT('{}', '$.productos_lineas', JSON_EXTRACT(pRegistrosJson, CONCAT('$.cabecera[', vIndex, ']'))), '"[', '['), ']"', ']'), '\\', ''), '"{', '{'), '}"', '}');

                # INSERTAMOS LOS REGISTROS
                INSERT INTO productos_lineas (productos_lineasid, descripcion, imagen, ecommerceid, cuentacontable_inventarios, cuentacontable_ventas, cuentacontable_costo, parametros_json, fechacreacion, usuariocreacion, fechamodificacion, usuariomodificacion)
                  VALUES (p_productos_lineasid, p_descripcion, p_imagen, p_ecommerceid, p_cuentacontable_inventarios, p_cuentacontable_ventas, p_cuentacontable_costo, p_parametros_json, p_fechacreacion, p_usuariocreacion, p_fechamodificacion, p_usuariomodificacion);

#obtiene el id del registro
set p_productos_lineasid = LAST_INSERT_ID();

            WHEN 'M' THEN SET p_tipooperacion = 'M';

  SET p_imagen = FROM_BASE64(JSON_UNQUOTE(JSON_EXTRACT(pRegistrosJson, CONCAT('$.cabecera[', vIndex, '].imagen'))));
                IF p_imagen = '' THEN
                  set p_imagen = NULL;
                END IF;
  SET p_parametros_json = IFNULL(FROM_BASE64(JSON_UNQUOTE(JSON_EXTRACT(pRegistrosJson, CONCAT('$.cabecera[', vIndex, '].parametros_json')))),p_parametros_json);
                SET p_fechamodificacion = NOW(3);
                SET p_usuariomodificacion = JSON_UNQUOTE(JSON_EXTRACT(pRegistrosJson, CONCAT('$.cabecera[', vIndex, '].usuariomodificacion')));


                SET vRegistroAnterior = (SELECT
                    JSON_OBJECT
                    (
                    'productos_lineasid', productos_lineasid,
                    'descripcion', descripcion,
                    'imagen', HEX(imagen),
                    'ecommerceid', ecommerceid,
                    'cuentacontable_inventarios', cuentacontable_inventarios,
                    'cuentacontable_ventas', cuentacontable_ventas,
                    'cuentacontable_costo', cuentacontable_costo,
                    'parametros_json', TO_BASE64(parametros_json),
                    'fechamodificacion', fechamodificacion,
                    'usuariomodificacion', usuariomodificacion
                    )
                  FROM productos_lineas
                  WHERE productos_lineas.productos_lineasid = p_productos_lineasid);

                SET p_detalle = REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(JSON_INSERT('{}', '$.productos_lineas', vRegistroAnterior), '"[', '['), ']"', ']'), '\\', ''), '"{', '{'), '}"', '}');

                # ACTUALIZAMOS LOS REGISTROS
                UPDATE productos_lineas
                SET productos_lineasid = p_productos_lineasid,
                    descripcion = p_descripcion,
                    imagen = p_imagen,
                    ecommerceid = p_ecommerceid,
                    cuentacontable_inventarios = p_cuentacontable_inventarios,
                    cuentacontable_ventas = p_cuentacontable_ventas,
                    cuentacontable_costo = p_cuentacontable_costo,
                    parametros_json = p_parametros_json,
                    fechamodificacion = p_fechamodificacion,
                    usuariomodificacion = p_usuariomodificacion
                WHERE productos_lineasid = p_productos_lineasid;

            WHEN 'E' THEN SET p_tipooperacion = 'E';
                SET p_detalle = REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(JSON_INSERT('{}', '$.productos_lineas', JSON_EXTRACT(pRegistrosJson, CONCAT('$.cabecera[', vIndex, ']'))), '"[', '['), ']"', ']'), '\\', ''), '"{', '{'), '}"', '}');

                # ELIMINAMOS LOS REGISTROS
                DELETE
                  FROM productos_lineas
                WHERE productos_lineasid = p_productos_lineasid;

          END CASE;

          # INSERTAMOS LA AUDITORIA
          CALL sistemaperseo.SP_ABC_sis_log_sistema(p_sis_subcategoriasid, p_sis_empresasid, p_sis_usuariosid, p_tipooperacion, p_detalle, p_equipo);

          SET vIndex = vIndex + 1;
        END WHILE;
      COMMIT;


      # RETORNAMOS LA RESPUESTAS
      IF pAccion IN ('C', 'M') THEN

        SELECT
          productos_lineas.productos_lineasid,
          productos_lineas.descripcion,
          productos_lineas.imagen,
          productos_lineas.ecommerceid,
          productos_lineas.cuentacontable_inventarios,
          productos_lineas.cuentacontable_ventas,
          productos_lineas.cuentacontable_costo,
ccinv.descripcion as cuentanombreinventario,
cccost.descripcion as cuentanombrecosto,
ccvent.descripcion as cuentanombreventas,
          productos_lineas.parametros_json,
          productos_lineas.fechacreacion,
          productos_lineas.usuariocreacion,
          productos_lineas.fechamodificacion,
          productos_lineas.usuariomodificacion,
          (SELECT
              JSON_ARRAYAGG(JSON_OBJECT('procesado', TRUE, 'mensaje', 'Completado con Éxito'))) AS resultado
        FROM productos_lineas
LEFT JOIN cuentas_contables as ccinv on ccinv.codigocontable = productos_lineas.cuentacontable_inventarios
LEFT JOIN cuentas_contables as cccost on cccost.codigocontable = productos_lineas.cuentacontable_costo
LEFT JOIN cuentas_contables as ccvent on ccvent.codigocontable = productos_lineas.cuentacontable_ventas
        WHERE productos_lineas.productos_lineasid = p_productos_lineasid;

      ELSE
        SELECT
          JSON_ARRAYAGG(JSON_OBJECT('procesado', TRUE, 'mensaje', 'Completado con Éxito')) AS resultado;
      END IF;
    END IF;
  END IF;
END
;;
delimiter ;

-- ----------------------------
-- Procedure structure for SP_productos_lineas_ConsultarID
-- ----------------------------
DROP PROCEDURE IF EXISTS `SP_productos_lineas_ConsultarID`;
delimiter ;;
CREATE PROCEDURE `SP_productos_lineas_ConsultarID`(IN p_productos_lineasid int(11))
BEGIN

  SELECT
    productos_lineas.productos_lineasid,
    productos_lineas.descripcion,
    productos_lineas.imagen,
    productos_lineas.ecommerceid,
    productos_lineas.cuentacontable_inventarios,
    productos_lineas.cuentacontable_ventas,
    productos_lineas.cuentacontable_costo,
ccinv.descripcion as cuentanombreinventario,
cccost.descripcion as cuentanombrecosto,
ccvent.descripcion as cuentanombreventas,
    productos_lineas.parametros_json,
    productos_lineas.fechacreacion,
    productos_lineas.usuariocreacion,
    productos_lineas.fechamodificacion,
    productos_lineas.usuariomodificacion
  FROM productos_lineas
LEFT JOIN cuentas_contables as ccinv on ccinv.codigocontable = productos_lineas.cuentacontable_inventarios
LEFT JOIN cuentas_contables as cccost on cccost.codigocontable = productos_lineas.cuentacontable_costo
LEFT JOIN cuentas_contables as ccvent on ccvent.codigocontable = productos_lineas.cuentacontable_ventas
  WHERE productos_lineas.productos_lineasid = p_productos_lineasid;

END
;;
delimiter ;

-- ----------------------------
-- Procedure structure for SP_Productos_Regula_Inventario
-- ----------------------------
DROP PROCEDURE IF EXISTS `SP_Productos_Regula_Inventario`;
delimiter ;;
CREATE PROCEDURE `SP_Productos_Regula_Inventario`()
BEGIN 
-- Regula inventario eliminando e insertando movimientos por modulo

-- Controlamos si hubo error
DECLARE exit handler FOR SQLEXCEPTION, SQLWARNING
  BEGIN
  -- SHOW ERRORS;
  	SHOW WARNINGS LIMIT 1;
    ROLLBACK;
    RESIGNAL;
  END;

-- Mov. Modulo Compras
-- -------------------------------------------------------
UPDATE compras_detalles SET compras_detalles.origen=0 WHERE compras_detalles.origen='';

DELETE FROM movinventarios 	WHERE movinventarios.movinventarios_tiposid IN (1,2);

Insert INTO `movinventarios` (`movinventariosid`,`centros_costosid`, `documentosid`, `productosid`, `medidasid`, `movinventarios_tiposid`, `almacenesid`, `documento_detallesid`, `cantidaddigitada`, `cantidadfactor`, `cantidad`, `precioiva`, `precio`, `preciovisible`, `descuento`, `descuentovalor`, `costo`, `iva`, `servicio`, `anulado`, `fechamovimiento`, `fechaactulizacion`, `referencia`, `beneficiarioid`)
(
  SELECT
  0 AS movinventariosid,
compras_detalles.centros_costosid,
compras_detalles.comprasid,
compras_detalles.productosid,
compras_detalles.medidasid,
compras.movinventarios_tiposid,
compras_detalles.almacenesid,
compras_detalles.compras_detallesid,
compras_detalles.cantidaddigitada,
compras_detalles.cantidadfactor,
compras_detalles.cantidad,
0 AS piva,
0 AS precio,
0 AS PrecioVis,
0 AS dsto,
0 AS dscvalor,
compras_detalles.costoneto,
0 AS iva,
(CASE WHEN (productos.venta = 1 AND productos.servicio = 1) OR (productos.venta = 0 AND productos.servicio = 1) OR (productos.venta = 0 AND productos.bien = 1) THEN 1 ELSE 0 END) AS servicio,
compras_detalles.anulado AS anulado,
compras.emision,
DATE_FORMAT(compras.fechacreacion, '%Y-%m-%d') AS fechacreacion,
CONCAT(compras.establecimiento,'-',compras.puntoemision,'-',compras.secuencia) AS referencia,
compras.proveedoresid
FROM
compras
INNER JOIN
(
compras_detalles
INNER JOIN
(
productos
)ON (compras_detalles.productosid=productos.productosid)
)ON (compras.comprasid= compras_detalles.comprasid)	
WHERE compras_detalles.origen <> 2);

-- -------------------------------------------------------
-- Mov. Modulo Ingresos
-- -------------------------------------------------------
-- DELETE FROM movinventarios 	WHERE movinventarios.movinventarios_tiposid IN (IngresoID);
DELETE MV1 from  movinventarios AS  MV1, movinventarios_tipos AS MV2
WHERE MV1.movinventarios_tiposid=MV2.movinventarios_tiposid AND MV2.modulos = 'Ingresos';

Insert INTO `movinventarios`  (`movinventariosid`, `centros_costosid`, `documentosid`, `productosid`, `medidasid`, `movinventarios_tiposid`, `almacenesid`, `documento_detallesid`, `cantidaddigitada`, `cantidadfactor`, `cantidad`, `precioiva`, `precio`, `preciovisible`, `descuento`, `descuentovalor`, `costo`, `iva`, `servicio`, `anulado`, `fechamovimiento`, `fechaactulizacion`, `referencia`, `beneficiarioid`)
(
SELECT
0 AS movinventariosid,
ingresos_detalles.centros_costosid,
ingresos_detalles.ingresosid,
ingresos_detalles.productosid,
productos.unidadinterna,
7 as tipomovimiento,
ingresos_detalles.almacenesid,
ingresos_detalles.ingresos_detallesid,
ROUND(ingresos_detalles.cantidad,2) as cantidaddigitada,
1 as cantidadfactor,
ingresos_detalles.cantidad,
0 AS PIVA,
0 AS precio,
0 AS PrecioVis,
0 AS dsto,
0 AS dscvalor,
ingresos_detalles.costo,
0 AS iva,
productos.servicio AS servicio,
0 AS anulado,
ingresos.fecha,
DATE_FORMAT(ingresos.fechacreacion, '%Y-%m-%d') AS fechacreacion,
ingresos.ingresoscodigo AS referencia,
ingresos.movimientos_conceptosid
FROM
ingresos
INNER JOIN
(
ingresos_detalles
INNER JOIN
(
productos
)ON (ingresos_detalles.productosid=productos.productosid)
)ON (ingresos.ingresosid= ingresos_detalles.ingresosid)	
where
ingresos.movinventarios_tiposid in (SELECT 	mv.movinventarios_tiposid 	FROM	movinventarios_tipos as mv	WHERE	mv.modulos = 'Ingresos')
);

-- Recepcion de Compas
-- --------------------------------
DELETE MV1 from  movinventarios AS  MV1, movinventarios_tipos AS MV2
WHERE MV1.movinventarios_tiposid=MV2.movinventarios_tiposid AND MV2.modulos = 'Recepciones';
Insert INTO `movinventarios` (`movinventariosid`,`centros_costosid`, `documentosid`, `productosid`, `medidasid`, `movinventarios_tiposid`, `almacenesid`, `documento_detallesid`, `cantidaddigitada`, `cantidadfactor`, `cantidad`, `precioiva`, `precio`, `preciovisible`, `descuento`, `descuentovalor`, `costo`, `iva`, `servicio`, `anulado`, `fechamovimiento`, `fechaactulizacion`, `referencia`, `beneficiarioid`)
(
  SELECT
  0 AS movinventariosid,
compras_recepciones_detalles.centros_costosid, 
compras_recepciones_detalles.compras_recepcionesid, 
compras_recepciones_detalles.productosid, 
compras_recepciones_detalles.medidasid, 
compras_recepciones.movinventarios_tiposid, 
compras_recepciones_detalles.almacenesid, 
compras_recepciones_detalles.compras_recepciones_detallesid,
compras_recepciones_detalles.cantidaddigitada,
compras_recepciones_detalles.cantidadfactor,
compras_recepciones_detalles.cantidad,
0 AS piva,
0 AS precio,
0 AS PrecioVis,
0 AS dsto,
0 AS dscvalor,
compras_recepciones_detalles.costoneto,
0 AS iva,
(CASE WHEN (productos.venta = 1 AND productos.servicio = 1) OR (productos.venta = 0 AND productos.servicio = 1) OR (productos.venta = 0 AND productos.bien = 1) THEN 1 ELSE 0 END) AS servicio,
0 AS anulado,
compras_recepciones.emision,
DATE_FORMAT(compras_recepciones.fechacreacion, '%Y-%m-%d') AS fechacreacion,
compras_recepciones.compras_recepciones_codigo AS referencia,
compras_recepciones.proveedoresid
FROM
compras_recepciones
INNER JOIN
(
compras_recepciones_detalles
INNER JOIN
(
productos
)ON (compras_recepciones_detalles.productosid=productos.productosid)
)ON (compras_recepciones.compras_recepcionesid= compras_recepciones_detalles.compras_recepcionesid)	
)
;

-- -------------------------------------------------------
-- Mov. Modulo transferencias
-- -------------------------------------------------------

DELETE FROM movinventarios WHERE movinventarios.movinventarios_tiposid IN (5,6);
Insert INTO `movinventarios`  (`movinventariosid`, `centros_costosid`, `documentosid`, `productosid`, `medidasid`, `movinventarios_tiposid`, `almacenesid`, `documento_detallesid`, `cantidaddigitada`, `cantidadfactor`, `cantidad`, `precioiva`, `precio`, `preciovisible`, `descuento`, `descuentovalor`, `costo`, `iva`, `servicio`, `anulado`, `fechamovimiento`, `fechaactulizacion`, `referencia`, `beneficiarioid`)
(
SELECT
0 AS movinventariosid,
1 as centros_costosid,
transferencias_detalles.transferenciasid,
transferencias_detalles.productosid,
productos.unidadinterna,
6 AS tipomovimiento,
transferencias.origen_almacenesid,
transferencias_detalles.transferencias_detallesid,
ROUND(transferencias_detalles.cantidad,2) AS cantidaddigitada,
1 AS cantidadfactor,
transferencias_detalles.cantidad,
0 AS piva,
0 AS precio,
0 AS PrecioVis,
0 AS dsto,
0 AS dscvalor,
transferencias_detalles.costo,
0 AS iva,
0 AS servicio,
0 AS anulado,
transferencias.fecha,
DATE_FORMAT(transferencias.fechacreacion, '%Y-%m-%d') AS fechacreacion,
transferencias.transferenciascodigo AS referencia,
0
FROM
transferencias
INNER JOIN
(
transferencias_detalles
INNER JOIN
(
productos
)ON (transferencias_detalles.productosid=productos.productosid)
)ON (transferencias.transferenciasid= transferencias_detalles.transferenciasid)	
WHERE
transferencias.estado <> 4
 UNION
 
 SELECT
0 AS movinventariosid,
1 as centros_costosid,
transferencias_detalles.transferenciasid,
transferencias_detalles.productosid,
productos.unidadinterna,
5 AS tipomovimiento,
transferencias.destino_almacenesid,
transferencias_detalles.transferencias_detallesid,
ROUND(transferencias_detalles.cantidad,2) AS cantidaddigitada,
1 AS cantidadfactor,
transferencias_detalles.cantidad,
0 AS piva,
0 AS precio,
0 AS PrecioVis,
0 AS dsto,
0 AS dscvalor,
transferencias_detalles.costo,
0 AS iva,
0 AS servicio,
0 AS anulado,
transferencias.fecha,
DATE_FORMAT(transferencias.fechacreacion, '%Y-%m-%d') AS fechacreacion,
transferencias.transferenciascodigo AS referencia,
0
FROM
transferencias
INNER JOIN
(
transferencias_detalles
INNER JOIN
(
productos
)ON (transferencias_detalles.productosid=productos.productosid)
)ON (transferencias.transferenciasid= transferencias_detalles.transferenciasid)	
where
transferencias.aprobado = 1 AND transferencias.estado <>4
  
 );


-- -------------------------------------------------------
-- Mov. Modulo Ventas (Facturacion )  productos y prod compuestos
-- -------------------------------------------------------

DELETE FROM movinventarios	WHERE movinventarios.movinventarios_tiposid IN (3,4);
-- Inserta solo productos 
INSERT INTO `movinventarios` 
(`movinventariosid`, `centros_costosid`, `documentosid`, `productosid`, `medidasid`, `movinventarios_tiposid`, `almacenesid`, `documento_detallesid`, `cantidaddigitada`, `cantidadfactor`, `cantidad`, `precioiva`, `precio`, `preciovisible`, `descuento`, `descuentovalor`, `costo`, `iva`, `servicio`, `anulado`, `fechamovimiento`, `fechaactulizacion`, `referencia`, `beneficiarioid`)

(
SELECT
0 AS movinventariosid,
facturas_detalles.centros_costosid,
facturas_detalles.facturasid,
facturas_detalles.productosid,
facturas_detalles.medidasid,
(CASE WHEN facturas.sri_documentoscodigo='04' THEN 4 ELSE 3 END) AS tipomov,
facturas_detalles.almacenesid,
facturas_detalles.facturas_detallesid,
facturas_detalles.cantidaddigitada,
facturas_detalles.cantidadfactor,
facturas_detalles.cantidad,
facturas_detalles.preciovisible AS piva,
facturas_detalles.precio AS precio,
facturas_detalles.preciovisible AS PrecioVis,
facturas_detalles.descuento AS dsto,
facturas_detalles.descuentovalor AS dscvalor,
facturas_detalles.costo,
facturas_detalles.iva AS iva,
facturas_detalles.servicio AS servicio,
facturas_detalles.anulado AS anulado,
facturas.emision,
DATE_FORMAT(facturas.fechacreacion, '%Y-%m-%d') AS fechacreacion,
CONCAT(facturas.establecimiento,'-',facturas.puntoemision,'-',facturas.secuencial) AS referencia,
facturas.clientesid
FROM
facturas
INNER JOIN
(
facturas_detalles
INNER JOIN
(
productos
)ON (facturas_detalles.productosid = productos.productosid AND productos.venta=1)
)ON (facturas.facturasid = facturas_detalles.facturasid)	
WHERE
facturas_detalles.entrega = 0	
AND facturas_detalles.entrega_parcial = 0 
AND facturas_detalles.compuestoid = 0 
);
-- Inserta productos compuesto / produccion 


-- -------------------------------------------------------
-- Mov. Modulo Ventas (Facturacion) restaurantes serv compuestos
-- -------------------------------------------------------

DELETE FROM movinventarios	WHERE movinventarios.movinventarios_tiposid IN (15,16);


-- Inserta servicio compuesto 
Insert INTO `movinventarios` 
(`movinventariosid`, `centros_costosid`, `documentosid`, `productosid`, `medidasid`, `movinventarios_tiposid`, `almacenesid`, `documento_detallesid`, `cantidaddigitada`, `cantidadfactor`, `cantidad`, `precioiva`, `precio`, `preciovisible`, `descuento`, `descuentovalor`, `costo`, `iva`, `servicio`, `anulado`, `fechamovimiento`, `fechaactulizacion`, `referencia`, `beneficiarioid`)

(
SELECT
0 AS movinventariosid,
facturas_detalles.centros_costosid,
facturas_detalles.facturasid,
facturas_detalles.productosid,
facturas_detalles.medidasid,
(CASE WHEN facturas.sri_documentoscodigo='04' THEN 16 ELSE 15 END) AS tipomov,
facturas_detalles.almacenesid,
facturas_detalles.facturas_detallesid,
ROUND((facturas_detalles.cantidaddigitada),6) as cantidaddigitada,
ROUND((facturas_detalles.cantidadfactor),6) as cantidadfactor,
ROUND((facturas_detalles.cantidad),6) as cantidad,
facturas_detalles.preciovisible AS piva,
facturas_detalles.precio AS precio,
facturas_detalles.preciovisible AS PrecioVis,
facturas_detalles.descuento AS dsto,
facturas_detalles.descuentovalor AS dscvalor,
facturas_detalles.costo as costo,
facturas_detalles.iva AS iva,
0 AS servicio,
facturas_detalles.anulado AS anulado,
facturas.emision,
DATE_FORMAT(facturas.fechacreacion, '%Y-%m-%d') AS fechacreacion,
CONCAT(facturas.establecimiento,'-',facturas.puntoemision,'-',facturas.secuencial) AS referencia,
facturas.clientesid
FROM
facturas , facturas_detalles
WHERE
facturas.facturasid = facturas_detalles.facturasid 
-- AND productos.venta=1 and productos.servicio=0 and productos.bien=0 and productos.compuesto=1
AND facturas_detalles.compuestoid <> 0
-- AND facturas_detalles.productosid=productos.productosid
AND facturas_detalles.entrega = 0
);

-- -------------------------------------------------------	
-- Mov. Modulo Entregas
-- -------------------------------------------------------


DELETE FROM movinventarios	WHERE movinventarios.movinventarios_tiposid IN (9,19,20,21);
Insert INTO `movinventarios` 
(`movinventariosid`, `centros_costosid`, `documentosid`, `productosid`, `medidasid`, `movinventarios_tiposid`, `almacenesid`, `documento_detallesid`, `cantidaddigitada`, `cantidadfactor`, `cantidad`, `precioiva`, `precio`, `preciovisible`, `descuento`, `descuentovalor`, `costo`, `iva`, `servicio`, `anulado`, `fechamovimiento`, `fechaactulizacion`, `referencia`, `beneficiarioid`)

(
SELECT
0 AS movinventariosid,
entregas_detalles.centros_costosid,
entregas_detalles.entregasid,
entregas_detalles.productosid,
entregas_detalles.medidasid,
(CASE WHEN ( entregas.relaciondocumentoid = 0 AND entregas_detalles.compuestoid = 0 ) THEN 9 
  WHEN ( entregas.relaciondocumentoid > 0 AND entregas_detalles.compuestoid = 0 ) THEN 19 
  WHEN ( entregas.relaciondocumentoid = 0 AND entregas_detalles.compuestoid > 0 ) THEN 20
  ELSE 21  end) AS tipomov,
entregas_detalles.almacenesid,
entregas_detalles.entregas_detallesid,
entregas_detalles.cantidaddigitada,
entregas_detalles.cantidadfactor,
entregas_detalles.cantidad,
entregas_detalles.precioiva AS piva,
entregas_detalles.precio AS precio,
entregas_detalles.precioiva AS PrecioVis,
entregas_detalles.descuento AS dsto,
entregas_detalles.descuento AS dscvalor,
entregas_detalles.costo,
entregas_detalles.iva AS iva,
0 AS servicio,
0 AS anulado,
entregas.emision,
DATE_FORMAT(entregas.fechacreacion, '%Y-%m-%d') AS fechacreacion,
entregas.entregas_codigo AS referencia,
entregas.clientesid
FROM
entregas
INNER JOIN
(
entregas_detalles
INNER JOIN
(
productos
)ON (entregas_detalles.productosid = productos.productosid)
)ON (entregas.entregasid = entregas_detalles.entregasid)	
where
productos.venta = 1
);

-- -------------------------------------------------------
-- Mov. Modulo Salidas
-- -------------------------------------------------------
-- delete FROM movinventarios	WHERE movinventarios.movinventarios_tiposid IN ([TIpoMov]);
DELETE MV1 from  movinventarios AS  MV1, movinventarios_tipos AS MV2
WHERE MV1.movinventarios_tiposid=MV2.movinventarios_tiposid AND MV2.modulos = 'Salidas';

INSERT INTO `movinventarios`  (`movinventariosid`, `centros_costosid`, `documentosid`, `productosid`, `medidasid`, `movinventarios_tiposid`, `almacenesid`, `documento_detallesid`, `cantidaddigitada`, `cantidadfactor`, `cantidad`, `precioiva`, `precio`, `preciovisible`, `descuento`, `descuentovalor`, `costo`, `iva`, `servicio`, `anulado`, `fechamovimiento`, `fechaactulizacion`, `referencia`, `beneficiarioid`)
(
SELECT
0 AS movinventariosid,
salidas_detalles.centros_costosid,
salidas_detalles.salidasid,
salidas_detalles.productosid,
productos.unidadinterna,
8 AS tipomovimiento,
salidas_detalles.almacenesid,
salidas_detalles.salidas_detallesid,
ROUND(salidas_detalles.cantidad,2) AS cantidaddigitada,
1 AS cantidadfactor,
salidas_detalles.cantidad,
0 AS PIVA,
0 AS precio,
0 AS PrecioVis,
0 AS dsto,
0 AS dscvalor,
salidas_detalles.costo,
0 AS iva,
0 AS servicio,
0 AS anulado,
salidas.fecha,
DATE_FORMAT(salidas.fechacreacion, '%Y-%m-%d') AS fechacreacion,
salidas.salidascodigo AS referencia,
salidas.movimientos_conceptosid
FROM
salidas
INNER JOIN
(
salidas_detalles
INNER JOIN
(
productos
)ON (salidas_detalles.productosid=productos.productosid)
)ON (salidas.salidasid= salidas_detalles.salidasid)	
where
salidas.movinventarios_tiposid in (SELECT mv.movinventarios_tiposid 	FROM	movinventarios_tipos as mv	WHERE	mv.modulos = 'Salidas')
);




-- -------------------------------------------------------
-- Actualiza Movimientos Almacenes 
-- -------------------------------------------------------

/* Agrega indice si no existe para que no exista almacenes duplicados  */
INSERT INTO movinventarios_almacenes(productosid,almacenesid)
(SELECT
productos.productosid,
almacenes.almacenesid
FROM
productos,
almacenes 
WHERE
productos.productosid NOT IN ( SELECT movinventarios_almacenes.productosid FROM movinventarios_almacenes WHERE movinventarios_almacenes.productosid = productos.productosid AND movinventarios_almacenes.almacenesid = almacenes.almacenesid ) 
AND productos.venta = 1 AND productos.servicio=0);

/* Pone en cero las existencias de los Bienes y Servicios  */
UPDATE
productos
SET
productos.existenciastotales = 0
WHERE
productos.bien = 1
OR 
productos.servicio = 1
OR
productos.venta = 0;


/* Actuliza la existenia a los productos segun los movimientos de inventario  */	
UPDATE
productos
SET
productos.existenciastotales=
IFNULL((SELECT 
SUM(CASE WHEN  movinventarios_tipos.tipocalculo=1
THEN movinventarios.cantidad
ELSE -movinventarios.cantidad END) AS stock
FROM 
movinventarios_tipos
INNER JOIN	
(movinventarios
)ON movinventarios_tipos.movinventarios_tiposid = movinventarios.movinventarios_tiposid
WHERE 
movinventarios.productosid = productos.productosid
AND ( movinventarios.anulado = 0 AND movinventarios.servicio = 0)
),0);

UPDATE movinventarios_almacenes
SET
movinventarios_almacenes.existencias=IFNULL((
SELECT 
SUM(CASE WHEN movinventarios_tipos.tipocalculo=1 THEN movinventarios.cantidad  ELSE -movinventarios.cantidad  END ) AS stock
FROM 
movinventarios_tipos
INNER JOIN	
(movinventarios
)ON movinventarios_tipos.movinventarios_tiposid = movinventarios.movinventarios_tiposid
WHERE 
(
movinventarios.productosid = movinventarios_almacenes.productosid
AND	movinventarios.almacenesid = movinventarios_almacenes.almacenesid
AND ( movinventarios.anulado = 0 AND movinventarios.servicio = 0)
)
),0);

-- -------------------------------------------------------
-- Mov. Modulo Produccion 
-- -------------------------------------------------------
DELETE MV1 from  movinventarios AS  MV1, movinventarios_tipos AS MV2
WHERE MV1.movinventarios_tiposid=MV2.movinventarios_tiposid AND MV2.modulos = "Produccion";

-- Inserta solo Ingresos de Produccion
Insert INTO `movinventarios`  (`movinventariosid`, `centros_costosid`, `documentosid`, `productosid`, `medidasid`, `movinventarios_tiposid`, `almacenesid`, `documento_detallesid`, `cantidaddigitada`, `cantidadfactor`, `cantidad`, `precioiva`, `precio`, `preciovisible`, `descuento`, `descuentovalor`, `costo`, `iva`, `servicio`, `anulado`, `fechamovimiento`, `fechaactulizacion`, `referencia`, `beneficiarioid`)
(
SELECT
0 AS movinventariosid,
ingresos_detalles.centros_costosid,
ingresos_detalles.ingresosid,
ingresos_detalles.productosid,
productos.unidadinterna,
ingresos.movinventarios_tiposid ,
ingresos_detalles.almacenesid,
ingresos_detalles.ingresos_detallesid,
ROUND(ingresos_detalles.cantidad,2) as cantidaddigitada,
1 as cantidadfactor,
ingresos_detalles.cantidad,
0 AS PIVA,
0 AS precio,
0 AS PrecioVis,
0 AS dsto,
0 AS dscvalor,
ingresos_detalles.costo,
0 AS iva,
productos.servicio AS servicio,
0 AS anulado,
ingresos.fecha,
DATE_FORMAT(ingresos.fechacreacion, '%Y-%m-%d') AS fechacreacion,
ingresos.ingresoscodigo AS referencia,
ingresos.movimientos_conceptosid
FROM
ingresos
INNER JOIN
(
ingresos_detalles
INNER JOIN
(
productos
)ON (ingresos_detalles.productosid=productos.productosid)
)ON (ingresos.ingresosid= ingresos_detalles.ingresosid)	
where
ingresos.movinventarios_tiposid in (10)
);

-- Inserta solo Salidas de Produccion
Insert INTO `movinventarios`  (`movinventariosid`, `centros_costosid`, `documentosid`, `productosid`, `medidasid`, `movinventarios_tiposid`, `almacenesid`, `documento_detallesid`, `cantidaddigitada`, `cantidadfactor`, `cantidad`, `precioiva`, `precio`, `preciovisible`, `descuento`, `descuentovalor`, `costo`, `iva`, `servicio`, `anulado`, `fechamovimiento`, `fechaactulizacion`, `referencia`, `beneficiarioid`)
(
SELECT
0 AS movinventariosid,
salidas_detalles.centros_costosid,
salidas_detalles.salidasid,
salidas_detalles.productosid,
productos.unidadinterna,
salidas.movinventarios_tiposid,
salidas_detalles.almacenesid,
salidas_detalles.salidas_detallesid,
ROUND(salidas_detalles.cantidad,2) AS cantidaddigitada,
1 AS cantidadfactor,
salidas_detalles.cantidad,
0 AS PIVA,
0 AS precio,
0 AS PrecioVis,
0 AS dsto,
0 AS dscvalor,
salidas_detalles.costo,
0 AS iva,
productos.servicio AS servicio,
0 AS anulado,
salidas.fecha,
DATE_FORMAT(salidas.fechacreacion, '%Y-%m-%d') AS fechacreacion,
salidas.salidascodigo AS referencia,
salidas.movimientos_conceptosid
FROM
salidas
INNER JOIN
(
salidas_detalles
INNER JOIN
(
productos
)ON (salidas_detalles.productosid=productos.productosid)
)ON (salidas.salidasid= salidas_detalles.salidasid)	
where
salidas.movinventarios_tiposid in (11)
);

COMMIT;

END
;;
