-- ----------------------------
-- Procedure structure for SP_productos_subcategoria_ABC
-- ----------------------------
DROP PROCEDURE IF EXISTS `SP_productos_subcategoria_ABC`;
delimiter ;;
CREATE PROCEDURE `SP_productos_subcategoria_ABC`(IN pAccion VARCHAR(1), IN pRegistrosJson JSON)
BEGIN 
DECLARE vJsonEsValido INT;
DECLARE vItems INT;
DECLARE vIndex BIGINT UNSIGNED DEFAULT 0;
DECLARE vErrorMensaje TEXT;
DECLARE vRegistroAnterior longtext;


# VARIABLES DE LOS DATOS DE LA TABLA
DECLARE p_productos_subcategoriasid INT(11);
DECLARE p_descripcion VARCHAR(50) DEFAULT '';
DECLARE p_imagen LONGBLOB DEFAULT NULL;
DECLARE p_ecommerceid INT(11) DEFAULT 1;
DECLARE p_parametros_json VARCHAR(500) DEFAULT '';
DECLARE p_fechacreacion DATETIME(3) DEFAULT '0000-00-00 00:00:00.000';
DECLARE p_usuariocreacion VARCHAR(25) DEFAULT '';
DECLARE p_fechamodificacion DATETIME(3) DEFAULT '0000-00-00 00:00:00.000';
DECLARE p_usuariomodificacion VARCHAR(25) DEFAULT '';


# VARIABLE DE LOS DATOS DE LA AUDITORIA
DECLARE p_sis_subcategoriasid int(11) DEFAULT 0;
DECLARE p_sis_empresasid int(11) DEFAULT 0;
DECLARE p_sis_usuariosid VARCHAR(20) DEFAULT '';
DECLARE p_equipo varchar(50) DEFAULT '';
DECLARE p_tipooperacion VARCHAR(50) DEFAULT '';
DECLARE p_detalle longtext;

# CONTROLAMOS SI HAY ERROR
DECLARE exit handler FOR SQLEXCEPTION, SQLWARNING
BEGIN
GET DIAGNOSTICS CONDITION 1 vErrorMensaje = MESSAGE_TEXT;
SELECT	
 CASE WHEN LOCATE('Cannot delete or update a parent row',vErrorMensaje)>0 THEN JSON_ARRAYAGG(JSON_OBJECT('procesado', FALSE, 'mensaje', 'No Se Puede Eliminar, Subcategoría 1 en Uso')) ELSE JSON_ARRAYAGG(JSON_OBJECT('procesado', FALSE, 'mensaje', vErrorMensaje)) END AS resultado;
ROLLBACK;
END;
# VALIDAMOS SI EL OBJETO JSON ES VALIDO 
SET vJsonEsValido = JSON_VALID(pRegistrosJson);

IF vJsonEsValido = 0 THEN 
# EL OBJETO JSON NO ES VALIDO
SELECT	JSON_ARRAYAGG(JSON_OBJECT( 'procesado', false, 'mensaje', 'Json no es valido' )) AS resultado;
ELSE 

# VALIDAMOS QUE TENGA ALMENOS UN ELEMENTO
SET vItems = JSON_LENGTH(pRegistrosJson,'$.cabecera');

IF vItems > 0 THEN 
START TRANSACTION;
WHILE vIndex < vItems DO

# DATOS TABLA
SET p_productos_subcategoriasid = IFNULL(JSON_UNQUOTE(JSON_EXTRACT(pRegistrosJson, CONCAT('$.cabecera[', vIndex, '].productos_subcategoriasid'))),p_productos_subcategoriasid);
SET p_descripcion = IFNULL(JSON_UNQUOTE(JSON_EXTRACT(pRegistrosJson, CONCAT('$.cabecera[', vIndex, '].descripcion'))),p_descripcion);
SET p_ecommerceid = IFNULL(JSON_UNQUOTE(JSON_EXTRACT(pRegistrosJson, CONCAT('$.cabecera[', vIndex, '].ecommerceid'))),p_ecommerceid);



# DATOS AUDITORIA
SET p_sis_subcategoriasid	= JSON_UNQUOTE(JSON_EXTRACT(pRegistrosJson, CONCAT('$.cabecera[', vIndex, '].sis_subcategoriasid')));
SET p_sis_empresasid		= JSON_UNQUOTE(JSON_EXTRACT(pRegistrosJson, CONCAT('$.cabecera[', vIndex, '].sis_empresasid')));
SET p_sis_usuariosid		= JSON_UNQUOTE(JSON_EXTRACT(pRegistrosJson, CONCAT('$.cabecera[', vIndex, '].sis_usuariosid')));
SET p_equipo				= JSON_UNQUOTE(JSON_EXTRACT(pRegistrosJson, CONCAT('$.cabecera[', vIndex, '].equipo')));


CASE pAccion
WHEN 'C' THEN 

SET p_imagen = FROM_BASE64(JSON_UNQUOTE(JSON_EXTRACT(pRegistrosJson, CONCAT('$.cabecera[', vIndex, '].imagen'))));
IF p_imagen = '' THEN
  set p_imagen = NULL;
END IF;
SET p_parametros_json = IFNULL(FROM_BASE64(JSON_UNQUOTE(JSON_EXTRACT(pRegistrosJson, CONCAT('$.cabecera[', vIndex, '].parametros_json')))),p_parametros_json);
SET p_tipooperacion				= 'N';
SET p_fechacreacion				= NOW(3);
SET p_usuariocreacion			= JSON_UNQUOTE(JSON_EXTRACT(pRegistrosJson, CONCAT('$.cabecera[', vIndex, '].usuariocreacion')));
SET p_fechamodificacion			= NULL;
SET p_usuariomodificacion		= '';
SET p_detalle					= REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(JSON_INSERT('{}','$.productos_subcategoria',JSON_EXTRACT(pRegistrosJson, CONCAT('$.cabecera[', vIndex, ']'))),'"[','['),']"',']'),'\\',''),'"{','{'),'}"','}');

# INSERTAMOS LOS REGISTROS
INSERT INTO  productos_subcategoria(productos_subcategoriasid,descripcion,imagen,ecommerceid,parametros_json,fechacreacion,usuariocreacion,fechamodificacion,usuariomodificacion) VALUES (p_productos_subcategoriasid,p_descripcion,p_imagen,p_ecommerceid,p_parametros_json,p_fechacreacion,p_usuariocreacion,p_fechamodificacion,p_usuariomodificacion);

set p_productos_subcategoriasid = LAST_INSERT_ID();

WHEN 'M' THEN

SET p_imagen = FROM_BASE64(JSON_UNQUOTE(JSON_EXTRACT(pRegistrosJson, CONCAT('$.cabecera[', vIndex, '].imagen'))));
IF p_imagen = '' THEN
  set p_imagen = NULL;
END IF;
SET p_parametros_json = IFNULL(FROM_BASE64(JSON_UNQUOTE(JSON_EXTRACT(pRegistrosJson, CONCAT('$.cabecera[', vIndex, '].parametros_json')))),p_parametros_json);
SET p_tipooperacion			= 'M';
SET p_fechamodificacion		= NOW(3);
SET p_usuariomodificacion	= JSON_UNQUOTE(JSON_EXTRACT(pRegistrosJson, CONCAT('$.cabecera[', vIndex, '].usuariomodificacion')));


SET vRegistroAnterior		= (
SELECT JSON_OBJECT
(
'productos_subcategoriasid' , productos_subcategoriasid,
'descripcion' , descripcion,
'imagen' , HEX(imagen),
'ecommerceid' , ecommerceid,
'parametros_json' , TO_BASE64(parametros_json),
'fechamodificacion' , fechamodificacion,
'usuariomodificacion' , usuariomodificacion
)
FROM productos_subcategoria WHERE productos_subcategoria.productos_subcategoriasid	= p_productos_subcategoriasid);

SET p_detalle													= REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(JSON_INSERT('{}','$.productos_subcategoria',vRegistroAnterior),'"[','['),']"',']'),'\\',''),'"{','{'),'}"','}');

# ACTUALIZAMOS LOS REGISTROS
UPDATE productos_subcategoria SET productos_subcategoriasid = p_productos_subcategoriasid,descripcion = p_descripcion,imagen = p_imagen,ecommerceid = p_ecommerceid,parametros_json = p_parametros_json,fechamodificacion = p_fechamodificacion,usuariomodificacion = p_usuariomodificacion WHERE productos_subcategoriasid=p_productos_subcategoriasid;

WHEN 'E' THEN
SET p_tipooperacion	= 'E';
SET p_detalle		= REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(JSON_INSERT('{}','$.productos_subcategoria',JSON_EXTRACT(pRegistrosJson, CONCAT('$.cabecera[', vIndex, ']'))),'"[','['),']"',']'),'\\',''),'"{','{'),'}"','}');

# ELIMINAMOS LOS REGISTROS
DELETE FROM productos_subcategoria WHERE productos_subcategoriasid=p_productos_subcategoriasid;

END CASE;

# INSERTAMOS LA AUDITORIA
CALL sistemaperseo.SP_ABC_sis_log_sistema(p_sis_subcategoriasid, p_sis_empresasid, p_sis_usuariosid, p_tipooperacion, p_detalle, p_equipo);

SET vIndex = vIndex + 1;
END WHILE;
COMMIT;

 # RETORNAMOS LA RESPUESTAS
      IF pAccion IN ('C', 'M') THEN

        SELECT
          productos_subcategoria.productos_subcategoriasid,
          productos_subcategoria.descripcion,
          productos_subcategoria.imagen,
          productos_subcategoria.ecommerceid,
          productos_subcategoria.parametros_json,
          productos_subcategoria.fechacreacion,
          productos_subcategoria.usuariocreacion,
          productos_subcategoria.fechamodificacion,
          productos_subcategoria.usuariomodificacion,
          (SELECT
              JSON_ARRAYAGG(JSON_OBJECT('procesado', TRUE, 'mensaje', 'Completado con Éxito'))) AS resultado
        FROM productos_subcategoria
        WHERE productos_subcategoria.productos_subcategoriasid = p_productos_subcategoriasid;

      ELSE
        SELECT
          JSON_ARRAYAGG(JSON_OBJECT('procesado', TRUE, 'mensaje', 'Completado con Éxito')) AS resultado;
      END IF;
END IF;
END IF;
END
;;
delimiter ;

-- ----------------------------
-- Procedure structure for SP_productos_subcategoria_ConsultarID
-- ----------------------------
DROP PROCEDURE IF EXISTS `SP_productos_subcategoria_ConsultarID`;
delimiter ;;
CREATE PROCEDURE `SP_productos_subcategoria_ConsultarID`(IN p_productos_subcategoriasid int(11))
BEGIN

  SELECT
    productos_subcategoria.productos_subcategoriasid,
    productos_subcategoria.descripcion,
    productos_subcategoria.imagen,
    productos_subcategoria.ecommerceid,
    productos_subcategoria.parametros_json,
    productos_subcategoria.fechacreacion,
    productos_subcategoria.usuariocreacion,
    productos_subcategoria.fechamodificacion,
    productos_subcategoria.usuariomodificacion
  FROM productos_subcategoria
  WHERE productos_subcategoria.productos_subcategoriasid = p_productos_subcategoriasid;

END
