-- ----------------------------
-- Procedure structure for SP_resultado_recordatorios
-- ----------------------------
DROP PROCEDURE IF EXISTS `SP_resultado_recordatorios`;
delimiter ;;
CREATE PROCEDURE `SP_resultado_recordatorios`()
BEGIN
WITH consultacxc AS (
    SELECT
        cuentasporcobrar.documentosid AS documentosid,
        SUM(cuentasporcobrar.importe) AS saldo,
        'cxc' AS origen
    FROM
        cuentasporcobrar
    WHERE
        cuentasporcobrar.origen NOT IN ('Caja A')
    GROUP BY
        cuentasporcobrar.secuencial,
        cuentasporcobrar.documentosid
    HAVING
        saldo <> 0

    UNION ALL

    SELECT
        cuentasporpagar.documentosid AS documentosid,
        SUM(cuentasporpagar.importe) AS saldo,
        'cxp' AS origen
    FROM
        cuentasporpagar
    GROUP BY
        cuentasporpagar.secuencia,
        cuentasporpagar.documentosid
    HAVING
        saldo <> 0

    UNION ALL

    SELECT
        movcaja.movcajasid AS documentosid,
        0 AS saldo,
        'cobrado' AS origen
    FROM
        movcaja
    WHERE
        movcaja.forma_pago_empresaid = 3
        AND movcaja.depositosid = 0

    UNION ALL

    SELECT
        movbanco.movbancosid AS documentosid,
        0 AS saldo,
        'girado' AS origen
    FROM
        movbanco
    WHERE
        movbanco.tipo = 'EG'
        AND movbanco.tipomovimiento = 'CH'
        AND movbanco.conciliacion_bancariaid = 0

UNION ALL
SELECT
clientesid AS documentosid,
0 AS saldo,
    'cliente' AS origen
FROM
clientes
WHERE
MONTH(fechanacimiento) = MONTH(CURDATE())
AND DAY(fechanacimiento) = DAY(CURDATE())
UNION ALL 
SELECT 
nomina_empleados.nomina_empleadosid AS documentosid,
0 AS saldo,
      'empleado' AS origen
FROM 
nomina_empleados
WHERE
MONTH(fechanacimiento) = MONTH(CURDATE())
AND DAY(fechanacimiento) = DAY(CURDATE())
),
origenes AS (
    SELECT 'cxc' AS origen
    UNION ALL
    SELECT 'cxp'
    UNION ALL
    SELECT 'cobrado'
    UNION ALL
    SELECT 'girado'
UNION ALL
    SELECT 'cliente'
UNION ALL
    SELECT 'empleado'
)
SELECT 
    o.origen,
    IFNULL(COUNT(c.documentosid), 0) AS cantidad_documentos
FROM 
    origenes o
    LEFT JOIN consultacxc c ON o.origen = c.origen
GROUP BY 
    o.origen;
END
;;
delimiter ;

