  DECLARE vRegistroAnterior longtext;


  # VARIABLES DE LOS DATOS DE LA TABLA
  DECLARE p_rutasid int(11);
  DECLARE p_descripcion varchar(30) DEFAULT '';
  DECLARE p_tipooperacion varchar(50) DEFAULT '';



  # CONTROLAMOS SI HAY ERROR
  DECLARE EXIT HANDLER FOR SQLEXCEPTION, SQLWARNING
  BEGIN
    GET DIAGNOSTICS CONDITION 1 vErrorMensaje = MESSAGE_TEXT;
  SELECT
      CASE WHEN LOCATE('Cannot delete or update a parent row',vErrorMensaje)>0 THEN JSON_ARRAYAGG(JSON_OBJECT('procesado', FALSE, 'mensaje', 'No Se Puede Eliminar, Ruta en Uso')) ELSE JSON_ARRAYAGG(JSON_OBJECT('procesado', FALSE, 'mensaje', vErrorMensaje)) END AS resultado;
    ROLLBACK;
  END;
  # VALIDAMOS SI EL OBJETO JSON ES VALIDO 
  SET vJsonEsValido = JSON_VALID(pRegistrosJson);

  IF vJsonEsValido = 0 THEN
    # EL OBJETO JSON NO ES VALIDO
    SELECT
      JSON_ARRAYAGG(JSON_OBJECT('procesado', FALSE, 'mensaje', 'Json no es valido')) AS resultado;
  ELSE

    # VALIDAMOS QUE TENGA ALMENOS UN ELEMENTO
    SET vItems = JSON_LENGTH(pRegistrosJson, '$.cabecera');

    IF vItems > 0 THEN
      START TRANSACTION;
        WHILE vIndex < vItems DO

          # DATOS TABLA
          SET p_rutasid = IFNULL(JSON_UNQUOTE(JSON_EXTRACT(pRegistrosJson, CONCAT('$.cabecera[', vIndex, '].rutasid'))), p_rutasid);
          SET p_descripcion = IFNULL(JSON_UNQUOTE(JSON_EXTRACT(pRegistrosJson, CONCAT('$.cabecera[', vIndex, '].descripcion'))), p_descripcion);


         

          CASE pAccion
            WHEN 'C' THEN SET p_tipooperacion = 'N';
               
                # INSERTAMOS LOS REGISTROS
                INSERT INTO rutas (rutasid, descripcion)
                  VALUES (p_rutasid, p_descripcion);

                SET p_rutasid = LAST_INSERT_ID();

            WHEN 'M' THEN SET p_tipooperacion = 'M';
                

                SET vRegistroAnterior = (SELECT
                    JSON_OBJECT
                    (
                    'rutasid', rutasid,
                    'descripcion', descripcion
                    )
                  FROM rutas
                  WHERE rutas.rutasid = p_rutasid);

                
                # ACTUALIZAMOS LOS REGISTROS
                UPDATE rutas
                SET rutasid = p_rutasid,
                    descripcion = p_descripcion
                WHERE rutasid = p_rutasid;

            WHEN 'E' THEN SET p_tipooperacion = 'E';
                
                # ELIMINAMOS LOS REGISTROS
                DELETE
                  FROM rutas
                WHERE rutasid = p_rutasid;

          END CASE;

          # INSERTAMOS LA AUDITORIA
          
          SET vIndex = vIndex + 1;
        END WHILE;
      COMMIT;


      # RETORNAMOS LA RESPUESTAS
      IF pAccion IN ('C', 'M') THEN

        SELECT
          rutas.rutasid,
          rutas.descripcion,
          (SELECT
              JSON_ARRAYAGG(JSON_OBJECT('procesado', TRUE, 'mensaje', 'Completado con Éxito'))) AS resultado
        FROM rutas
        WHERE rutas.rutasid = p_rutasid;

      ELSE
        SELECT
          JSON_ARRAYAGG(JSON_OBJECT('procesado', TRUE, 'mensaje', 'Completado con Éxito')) AS resultado;
      END IF;
    END IF;
  END IF;

END
;;
delimiter ;

-- ----------------------------
-- Procedure structure for SP_rutas_ConsultarID
-- ----------------------------
DROP PROCEDURE IF EXISTS `SP_rutas_ConsultarID`;
delimiter ;;
CREATE PROCEDURE `SP_rutas_ConsultarID`(IN p_rutasid int(11))
BEGIN

  SELECT
    rutas.rutasid,
    rutas.descripcion
  FROM rutas
  WHERE rutas.rutasid = p_rutasid;

END
;;
delimiter ;

-- ----------------------------
-- Procedure structure for SP_secuencias_ABC
-- ----------------------------
DROP PROCEDURE IF EXISTS `SP_secuencias_ABC`;
delimiter ;;
CREATE PROCEDURE `SP_secuencias_ABC`(IN pAccion varchar(1), IN pRegistrosJson json)
secuencias:BEGIN
  DECLARE vJsonEsValido int;
  DECLARE vItems int;
  DECLARE vItemsC int;
  DECLARE vIndex bigint UNSIGNED DEFAULT 0;
  DECLARE vErrorMensaje text;
  DECLARE vRegistroAnterior longtext;


  # VARIABLES DE LOS DATOS DE LA TABLA
  DECLARE JsonDetalle json;
  DECLARE p_sri_documentoscodigo varchar(3) DEFAULT '';
  DECLARE p_secuenciasid int(11);
  DECLARE p_descripcion varchar(50) DEFAULT '';
  DECLARE p_estado tinyint(4) DEFAULT 0;
  DECLARE p_numerodigitos bigint(20) DEFAULT 0;
  DECLARE p_autorizacion varchar(10) DEFAULT '';
  DECLARE p_establecimiento varchar(3) DEFAULT '';
  DECLARE p_puntoemision varchar(3) DEFAULT '';
  DECLARE p_numeroactual bigint(20) DEFAULT 1;
  DECLARE p_formasecuencia varchar(3) DEFAULT '';
  DECLARE p_cantidaditems smallint(5) DEFAULT 1;
  DECLARE p_calculaiva tinyint(4) DEFAULT 0;
  DECLARE p_documentofiscal tinyint(4) DEFAULT 0;
  DECLARE p_documentoelectronico tinyint(4) DEFAULT 0;
  DECLARE p_transportista tinyint(4) DEFAULT 0;
  DECLARE p_tipocontribuyente tinyint(3) DEFAULT 0;
  DECLARE p_identificacion varchar(20) DEFAULT '';
  DECLARE p_razonsocial varchar(300) DEFAULT '';
  DECLARE p_direccionestablecimiento varchar(100) DEFAULT '';
  DECLARE p_telefono varchar(15) DEFAULT '';
  DECLARE p_placa varchar(8) DEFAULT '';
  DECLARE p_logo longblob DEFAULT NULL;
  DECLARE p_tiporegimen tinyint(3) DEFAULT 0;
  DECLARE p_agentederetencion tinyint(3) DEFAULT 0;
  DECLARE p_permite_recargo tinyint(3) DEFAULT 0;
  DECLARE p_ruta_impresora1 varchar(100) DEFAULT '';
  DECLARE p_ruta_impresora2 varchar(100) DEFAULT '';
  DECLARE p_ruta_impresora3 varchar(100) DEFAULT '';
  DECLARE p_fechacreacion datetime(3) DEFAULT '0000-00-00 00:00:00.000';
  DECLARE p_usuariocreacion varchar(25) DEFAULT '';
  DECLARE p_fechamodificacion datetime(3) DEFAULT '0000-00-00 00:00:00.000';
  DECLARE p_usuariomodificacion varchar(25) DEFAULT '';
  DECLARE p_empresas_certificadosid INT(11);
  DECLARE p_de_ambiente TINYINT(3) DEFAULT 0;
  DECLARE p_de_contriespecial VARCHAR(10) DEFAULT '';
  DECLARE p_de_llevacontabilidad TINYINT(3) DEFAULT 0;
  DECLARE p_de_tipoidentificacion VARCHAR(50) DEFAULT '';
  DECLARE p_de_identificacion_empresa VARCHAR(20) DEFAULT '';
  DECLARE p_de_razonsocial VARCHAR(300) DEFAULT '';
  DECLARE p_de_nombrecomercial VARCHAR(300) DEFAULT '';
  DECLARE p_de_direccion VARCHAR(150) DEFAULT '';
  DECLARE p_de_email VARCHAR(300) DEFAULT '';
  DECLARE p_de_telefono VARCHAR(15) DEFAULT '';
  DECLARE p_de_whtasapp VARCHAR(15) DEFAULT '';
  DECLARE p_de_caducacer DATE DEFAULT '0000-00-00';
  DECLARE p_de_certificadodigital longblob DEFAULT NULL;
  DECLARE p_de_clavecertificado VARCHAR(100) DEFAULT '';
  DECLARE p_de_fechacertificado DATE DEFAULT '0000-00-00';
  DECLARE p_de_correo_predeterminado VARCHAR(150) DEFAULT '';
  DECLARE p_de_informacion VARCHAR(800) DEFAULT '';
  DECLARE p_de_sql_factura LONGTEXT CHARACTER SET latin1 COLLATE latin1_spanish_ci DEFAULT NULL;
  DECLARE p_de_sql_retencion LONGTEXT CHARACTER SET latin1 COLLATE latin1_spanish_ci DEFAULT NULL;
  DECLARE p_de_sql_notacredito LONGTEXT CHARACTER SET latin1 COLLATE latin1_spanish_ci DEFAULT NULL;
  DECLARE p_de_sql_notadebito LONGTEXT CHARACTER SET latin1 COLLATE latin1_spanish_ci DEFAULT NULL;
  DECLARE p_de_sql_guiaremision LONGTEXT CHARACTER SET latin1 COLLATE latin1_spanish_ci DEFAULT NULL;
  DECLARE p_de_sql_liquidacioncompra LONGTEXT CHARACTER SET latin1 COLLATE latin1_spanish_ci DEFAULT NULL;
  DECLARE p_de_tiposql_factura TINYINT(3) DEFAULT 0;

  # VARIABLE DE LOS DATOS DE LA AUDITORIA
  DECLARE p_sis_subcategoriasid int(11) DEFAULT 0;
  DECLARE p_sis_empresasid int(11) DEFAULT 0;
  DECLARE p_sis_usuariosid varchar(20) DEFAULT '';
  DECLARE p_equipo varchar(50) DEFAULT '';
  DECLARE p_tipooperacion varchar(50) DEFAULT '';
  DECLARE p_detalle longtext;

  # CONTROLAMOS SI HAY ERROR
  DECLARE EXIT HANDLER FOR SQLEXCEPTION, SQLWARNING
  BEGIN
    GET DIAGNOSTICS CONDITION 1 vErrorMensaje = MESSAGE_TEXT;
    SELECT
      CASE WHEN LOCATE('Cannot delete or update a parent row',vErrorMensaje)>0 THEN JSON_ARRAYAGG(JSON_OBJECT('procesado', FALSE, 'mensaje', 'No Se Puede Eliminar, Secuencia en Uso')) ELSE JSON_ARRAYAGG(JSON_OBJECT('procesado', FALSE, 'mensaje', vErrorMensaje)) END AS resultado;
    ROLLBACK;
  END;
  # VALIDAMOS SI EL OBJETO JSON ES VALIDO 
  SET vJsonEsValido = JSON_VALID(pRegistrosJson);

  IF vJsonEsValido = 0 THEN
    # EL OBJETO JSON NO ES VALIDO
    SELECT
      JSON_ARRAYAGG(JSON_OBJECT('procesado', FALSE, 'mensaje', 'Json no es valido')) AS resultado;
  ELSE

    # VALIDAMOS QUE TENGA ALMENOS UN ELEMENTO
    SET vItems = JSON_LENGTH(pRegistrosJson, '$.cabecera');

    IF vItems > 0 THEN
      START TRANSACTION;
        WHILE vIndex < vItems DO
 
          -- guardamos el detalle del asiento en otro json
          SET JsonDetalle = JSON_EXTRACT(pRegistrosJson, CONCAT('$[', vIndex, '].certificados'));

          # DATOS TABLA
          SET p_sri_documentoscodigo = IFNULL(JSON_UNQUOTE(JSON_EXTRACT(pRegistrosJson, CONCAT('$.cabecera[', vIndex, '].sri_documentoscodigo'))), p_sri_documentoscodigo);
          SET p_secuenciasid = IFNULL(JSON_UNQUOTE(JSON_EXTRACT(pRegistrosJson, CONCAT('$.cabecera[', vIndex, '].secuenciasid'))), p_secuenciasid);
          SET p_empresas_certificadosid = IFNULL(JSON_UNQUOTE(JSON_EXTRACT(pRegistrosJson, CONCAT('$.cabecera[', vIndex, '].empresas_certificadosid'))), p_empresas_certificadosid);
          SET p_de_certificadodigital = FROM_BASE64(JSON_UNQUOTE(JSON_EXTRACT(pRegistrosJson, CONCAT('$.cabecera[', vIndex, '].de_certificadodigital'))));

          SET p_descripcion = IFNULL(JSON_UNQUOTE(JSON_EXTRACT(pRegistrosJson, CONCAT('$.cabecera[', vIndex, '].descripcion'))), p_descripcion);
          SET p_estado = IFNULL(JSON_UNQUOTE(JSON_EXTRACT(pRegistrosJson, CONCAT('$.cabecera[', vIndex, '].estado'))), p_estado);
          SET p_numerodigitos = IFNULL(JSON_UNQUOTE(JSON_EXTRACT(pRegistrosJson, CONCAT('$.cabecera[', vIndex, '].numerodigitos'))), p_numerodigitos);
          SET p_autorizacion = IFNULL(JSON_UNQUOTE(JSON_EXTRACT(pRegistrosJson, CONCAT('$.cabecera[', vIndex, '].autorizacion'))), p_autorizacion);
          SET p_establecimiento = IFNULL(JSON_UNQUOTE(JSON_EXTRACT(pRegistrosJson, CONCAT('$.cabecera[', vIndex, '].establecimiento'))), p_establecimiento);
          SET p_puntoemision = IFNULL(JSON_UNQUOTE(JSON_EXTRACT(pRegistrosJson, CONCAT('$.cabecera[', vIndex, '].puntoemision'))), p_puntoemision);
          SET p_numeroactual = IFNULL(JSON_UNQUOTE(JSON_EXTRACT(pRegistrosJson, CONCAT('$.cabecera[', vIndex, '].numeroactual'))), p_numeroactual);
          SET p_formasecuencia = IFNULL(JSON_UNQUOTE(JSON_EXTRACT(pRegistrosJson, CONCAT('$.cabecera[', vIndex, '].formasecuencia'))), p_formasecuencia);
          SET p_cantidaditems = IFNULL(JSON_UNQUOTE(JSON_EXTRACT(pRegistrosJson, CONCAT('$.cabecera[', vIndex, '].cantidaditems'))), p_cantidaditems);
          SET p_calculaiva = IFNULL(JSON_UNQUOTE(JSON_EXTRACT(pRegistrosJson, CONCAT('$.cabecera[', vIndex, '].calculaiva'))), p_calculaiva);
          SET p_documentofiscal = IFNULL(JSON_UNQUOTE(JSON_EXTRACT(pRegistrosJson, CONCAT('$.cabecera[', vIndex, '].documentofiscal'))), p_documentofiscal);
          SET p_documentoelectronico = IFNULL(JSON_UNQUOTE(JSON_EXTRACT(pRegistrosJson, CONCAT('$.cabecera[', vIndex, '].documentoelectronico'))), p_documentoelectronico);
          SET p_transportista = IFNULL(JSON_UNQUOTE(JSON_EXTRACT(pRegistrosJson, CONCAT('$.cabecera[', vIndex, '].transportista'))), p_transportista);
          SET p_tipocontribuyente = IFNULL(JSON_UNQUOTE(JSON_EXTRACT(pRegistrosJson, CONCAT('$.cabecera[', vIndex, '].tipocontribuyente'))), p_tipocontribuyente);
          SET p_identificacion = IFNULL(JSON_UNQUOTE(JSON_EXTRACT(pRegistrosJson, CONCAT('$.cabecera[', vIndex, '].identificacion'))), p_identificacion);
          SET p_razonsocial = IFNULL(JSON_UNQUOTE(JSON_EXTRACT(pRegistrosJson, CONCAT('$.cabecera[', vIndex, '].razonsocial'))), p_razonsocial);
          SET p_direccionestablecimiento = IFNULL(JSON_UNQUOTE(JSON_EXTRACT(pRegistrosJson, CONCAT('$.cabecera[', vIndex, '].direccionestablecimiento'))), p_direccionestablecimiento);
          SET p_telefono = IFNULL(JSON_UNQUOTE(JSON_EXTRACT(pRegistrosJson, CONCAT('$.cabecera[', vIndex, '].telefono'))), p_telefono);
          SET p_placa = IFNULL(JSON_UNQUOTE(JSON_EXTRACT(pRegistrosJson, CONCAT('$.cabecera[', vIndex, '].placa'))), p_placa);
          SET p_tiporegimen = IFNULL(JSON_UNQUOTE(JSON_EXTRACT(pRegistrosJson, CONCAT('$.cabecera[', vIndex, '].tiporegimen'))), p_tiporegimen);
          SET p_agentederetencion = IFNULL(JSON_UNQUOTE(JSON_EXTRACT(pRegistrosJson, CONCAT('$.cabecera[', vIndex, '].agentederetencion'))), p_agentederetencion);
          SET p_permite_recargo = IFNULL(JSON_UNQUOTE(JSON_EXTRACT(pRegistrosJson, CONCAT('$.cabecera[', vIndex, '].permite_recargo'))), p_permite_recargo);

          SET p_ruta_impresora1 = IFNULL(JSON_UNQUOTE(JSON_EXTRACT(pRegistrosJson, CONCAT('$.cabecera[', vIndex, '].ruta_impresora1'))), p_ruta_impresora1);
          SET p_ruta_impresora2 = IFNULL(JSON_UNQUOTE(JSON_EXTRACT(pRegistrosJson, CONCAT('$.cabecera[', vIndex, '].ruta_impresora2'))), p_ruta_impresora2);
          SET p_ruta_impresora3 = IFNULL(JSON_UNQUOTE(JSON_EXTRACT(pRegistrosJson, CONCAT('$.cabecera[', vIndex, '].ruta_impresora3'))), p_ruta_impresora3);

          # DATOS TABLA DE CERTIFICADOS
          # SET p_empresas_certificadosid = IFNULL(JSON_UNQUOTE(JSON_EXTRACT(pRegistrosJson, CONCAT('$.certificados[', vIndex, '].empresas_certificadosid'))),p_empresas_certificadosid);
          SET p_de_ambiente = IFNULL(JSON_UNQUOTE(JSON_EXTRACT(pRegistrosJson, CONCAT('$.cabecera[', vIndex, '].de_ambiente'))),p_de_ambiente);
          SET p_de_contriespecial = IFNULL(JSON_UNQUOTE(JSON_EXTRACT(pRegistrosJson, CONCAT('$.cabecera[', vIndex, '].de_contriespecial'))),p_de_contriespecial);
          SET p_de_llevacontabilidad = IFNULL(JSON_UNQUOTE(JSON_EXTRACT(pRegistrosJson, CONCAT('$.cabecera[', vIndex, '].de_llevacontabilidad'))),p_de_llevacontabilidad);
          SET p_de_tipoidentificacion = IFNULL(JSON_UNQUOTE(JSON_EXTRACT(pRegistrosJson, CONCAT('$.cabecera[', vIndex, '].de_tipoidentificacion'))),p_de_tipoidentificacion);
          SET p_de_identificacion_empresa = IFNULL(JSON_UNQUOTE(JSON_EXTRACT(pRegistrosJson, CONCAT('$.cabecera[', vIndex, '].de_identificacion_empresa'))),p_de_identificacion_empresa);
          SET p_de_razonsocial = IFNULL(JSON_UNQUOTE(JSON_EXTRACT(pRegistrosJson, CONCAT('$.cabecera[', vIndex, '].de_razonsocial'))),p_de_razonsocial);
          SET p_de_nombrecomercial = IFNULL(JSON_UNQUOTE(JSON_EXTRACT(pRegistrosJson, CONCAT('$.cabecera[', vIndex, '].de_nombrecomercial'))),p_de_nombrecomercial);
          SET p_de_direccion = IFNULL(JSON_UNQUOTE(JSON_EXTRACT(pRegistrosJson, CONCAT('$.cabecera[', vIndex, '].de_direccion'))),p_de_direccion);
          SET p_de_email = IFNULL(JSON_UNQUOTE(JSON_EXTRACT(pRegistrosJson, CONCAT('$.cabecera[', vIndex, '].de_email'))),p_de_email);
          SET p_de_telefono = IFNULL(JSON_UNQUOTE(JSON_EXTRACT(pRegistrosJson, CONCAT('$.cabecera[', vIndex, '].de_telefono'))),p_de_telefono);
          SET p_de_whtasapp = IFNULL(JSON_UNQUOTE(JSON_EXTRACT(pRegistrosJson, CONCAT('$.cabecera[', vIndex, '].de_whtasapp'))),p_de_whtasapp);
          SET p_de_caducacer = IFNULL(JSON_UNQUOTE(JSON_EXTRACT(pRegistrosJson, CONCAT('$.cabecera[', vIndex, '].de_caducacer'))),p_de_caducacer);
          SET p_de_clavecertificado = IFNULL(JSON_UNQUOTE(JSON_EXTRACT(pRegistrosJson, CONCAT('$.cabecera[', vIndex, '].de_clavecertificado'))),p_de_clavecertificado);
          SET p_de_fechacertificado = IFNULL(JSON_UNQUOTE(JSON_EXTRACT(pRegistrosJson, CONCAT('$.cabecera[', vIndex, '].de_fechacertificado'))),p_de_fechacertificado);
          SET p_de_correo_predeterminado = IFNULL(JSON_UNQUOTE(JSON_EXTRACT(pRegistrosJson, CONCAT('$.cabecera[', vIndex, '].de_correo_predeterminado'))),p_de_correo_predeterminado);
          SET p_de_informacion = IFNULL(JSON_UNQUOTE(JSON_EXTRACT(pRegistrosJson, CONCAT('$.cabecera[', vIndex, '].de_informacion'))),p_de_informacion);
          SET p_de_tiposql_factura = IFNULL(JSON_UNQUOTE(JSON_EXTRACT(pRegistrosJson, CONCAT('$.cabecera[', vIndex, '].de_tiposql_factura'))),p_de_tiposql_factura);
          
          SET p_de_sql_factura = FROM_BASE64(JSON_UNQUOTE(JSON_EXTRACT(pRegistrosJson, CONCAT('$.cabecera[', vIndex, '].de_sql_factura'))));
          SET p_de_sql_guiaremision = FROM_BASE64(JSON_UNQUOTE(JSON_EXTRACT(pRegistrosJson, CONCAT('$.cabecera[', vIndex, '].de_sql_guiaremision'))));
          SET p_de_sql_liquidacioncompra = FROM_BASE64(JSON_UNQUOTE(JSON_EXTRACT(pRegistrosJson, CONCAT('$.cabecera[', vIndex, '].de_sql_liquidacioncompra'))));
          SET p_de_sql_notacredito = FROM_BASE64(JSON_UNQUOTE(JSON_EXTRACT(pRegistrosJson, CONCAT('$.cabecera[', vIndex, '].de_sql_notacredito'))));
          SET p_de_sql_notadebito = FROM_BASE64(JSON_UNQUOTE(JSON_EXTRACT(pRegistrosJson, CONCAT('$.cabecera[', vIndex, '].de_sql_notadebito'))));
          SET p_de_sql_retencion = FROM_BASE64(JSON_UNQUOTE(JSON_EXTRACT(pRegistrosJson, CONCAT('$.cabecera[', vIndex, '].de_sql_retencion'))));
          
          # DATOS AUDITORIA
          SET p_sis_subcategoriasid = JSON_UNQUOTE(JSON_EXTRACT(pRegistrosJson, CONCAT('$.cabecera[', vIndex, '].sis_subcategoriasid')));
          SET p_sis_empresasid = JSON_UNQUOTE(JSON_EXTRACT(pRegistrosJson, CONCAT('$.cabecera[', vIndex, '].sis_empresasid')));
          SET p_sis_usuariosid = JSON_UNQUOTE(JSON_EXTRACT(pRegistrosJson, CONCAT('$.cabecera[', vIndex, '].sis_usuariosid')));
          SET p_equipo = JSON_UNQUOTE(JSON_EXTRACT(pRegistrosJson, CONCAT('$.cabecera[', vIndex, '].equipo')));

         /*PROCESO PARA VERIFICAR SI EXISTEN CERTIFICADOS O SE DEBE CREAR*/
          IF pAccion <> 'E' THEN
            IF p_de_certificadodigital = '' THEN# valida si se ingreso datos en el certificado
              SET p_de_certificadodigital = '';
            else
              IF p_empresas_certificadosid <= 0 THEN /*SE INSERTA UN NUEVO CERTIFICADO*/
    
                # INSERTAMOS LOS REGISTROS DEL CERTIFICADO
                INSERT INTO  empresas_certificado(empresas_certificadosid,fechacreacion,usuariocreacion,fechamodificacion,usuariomodificacion,de_ambiente,de_contriespecial,de_llevacontabilidad,de_tipoidentificacion,de_identificacion_empresa,de_razonsocial,de_nombrecomercial,de_direccion,de_email,de_telefono,de_whtasapp,de_caducacer,de_certificadodigital,de_clavecertificado,de_fechacertificado,de_correo_predeterminado,de_informacion,de_sql_factura,de_sql_retencion,de_sql_notacredito,de_sql_notadebito,de_sql_guiaremision,de_sql_liquidacioncompra,de_tiposql_factura) 
                VALUES (p_empresas_certificadosid,p_fechacreacion,p_usuariocreacion,p_fechamodificacion,p_usuariomodificacion,p_de_ambiente,p_de_contriespecial,p_de_llevacontabilidad,p_de_tipoidentificacion,p_de_identificacion_empresa,p_de_razonsocial,p_de_nombrecomercial,p_de_direccion,p_de_email,p_de_telefono,p_de_whtasapp,p_de_caducacer,p_de_certificadodigital,p_de_clavecertificado,p_de_fechacertificado,p_de_correo_predeterminado,p_de_informacion,p_de_sql_factura,p_de_sql_retencion,p_de_sql_notacredito,p_de_sql_notadebito,p_de_sql_guiaremision,p_de_sql_liquidacioncompra,p_de_tiposql_factura);
                
                SET p_empresas_certificadosid = LAST_INSERT_ID();
    
                IF p_empresas_certificadosid < 1 THEN
                  select
                  JSON_ARRAYAGG(JSON_OBJECT('procesado', FALSE, 'mensaje', 'No se insertó los datos del certificado')) AS resultado;
                END IF;
              ELSE
                # ACTUALIZAMOS LOS REGISTROS
                UPDATE empresas_certificado 
                SET fechamodificacion = p_fechamodificacion,
                    usuariomodificacion = p_usuariomodificacion,
                    de_ambiente = p_de_ambiente,
                    de_contriespecial = p_de_contriespecial,
                    de_llevacontabilidad = p_de_llevacontabilidad,
                    de_tipoidentificacion = p_de_tipoidentificacion,
                    de_identificacion_empresa = p_de_identificacion_empresa,
                    de_razonsocial = p_de_razonsocial,
                    de_nombrecomercial = p_de_nombrecomercial,
                    de_direccion = p_de_direccion,
                    de_email = p_de_email,
                    de_telefono = p_de_telefono,
                    de_whtasapp = p_de_whtasapp,
                    de_caducacer = p_de_caducacer,
                    de_certificadodigital = p_de_certificadodigital,
                    de_clavecertificado = p_de_clavecertificado,
                    de_fechacertificado = p_de_fechacertificado,
                    de_correo_predeterminado = p_de_correo_predeterminado,
                    de_informacion = p_de_informacion,
                    de_sql_factura = p_de_sql_factura,
                    de_sql_retencion = p_de_sql_retencion,
                    de_sql_notacredito = p_de_sql_notacredito,
                    de_sql_notadebito = p_de_sql_notadebito,
                    de_sql_guiaremision = p_de_sql_guiaremision,
                    de_sql_liquidacioncompra = p_de_sql_liquidacioncompra,
                    de_tiposql_factura = p_de_tiposql_factura
                  WHERE empresas_certificadosid=p_empresas_certificadosid;
      
                END IF;
              END IF;
            END IF;

          CASE pAccion
            WHEN 'C' THEN SET p_tipooperacion = 'N';

                SET p_logo = FROM_BASE64(JSON_UNQUOTE(JSON_EXTRACT(pRegistrosJson, CONCAT('$.cabecera[', vIndex, '].logo'))));
                IF p_logo = '' THEN
                  set p_logo = NULL;
                END IF;
                SET p_fechacreacion = NOW(3);
                SET p_usuariocreacion = JSON_UNQUOTE(JSON_EXTRACT(pRegistrosJson, CONCAT('$.cabecera[', vIndex, '].usuariocreacion')));
                SET p_fechamodificacion = NULL;
                SET p_usuariomodificacion = '';
                SET p_detalle = REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(JSON_INSERT('{}', '$.secuencias', JSON_EXTRACT(pRegistrosJson, CONCAT('$.cabecera[', vIndex, ']'))), '"[', '['), ']"', ']'), '\\', ''), '"{', '{'), '}"', '}');

                # INSERTAMOS LOS REGISTROS
                INSERT INTO secuencias (sri_documentoscodigo, secuenciasid, descripcion, estado, numerodigitos, autorizacion, establecimiento, puntoemision, numeroactual, formasecuencia, cantidaditems, calculaiva, documentofiscal, documentoelectronico, transportista, tipocontribuyente, identificacion, razonsocial, direccionestablecimiento, telefono, placa, logo, tiporegimen, agentederetencion, permite_recargo, ruta_impresora1, ruta_impresora2, ruta_impresora3, fechacreacion, usuariocreacion, fechamodificacion, usuariomodificacion, empresas_certificadosid)
                VALUES (p_sri_documentoscodigo, p_secuenciasid, p_descripcion, p_estado, p_numerodigitos, p_autorizacion, p_establecimiento, p_puntoemision, p_numeroactual, p_formasecuencia, p_cantidaditems, p_calculaiva, p_documentofiscal, p_documentoelectronico, p_transportista, p_tipocontribuyente, p_identificacion, p_razonsocial, p_direccionestablecimiento, p_telefono, p_placa, p_logo, p_tiporegimen, p_agentederetencion, p_permite_recargo, p_ruta_impresora1, p_ruta_impresora2, p_ruta_impresora3, p_fechacreacion, p_usuariocreacion, p_fechamodificacion, p_usuariomodificacion, p_empresas_certificadosid);

                SET p_secuenciasid = LAST_INSERT_ID();

            WHEN 'M' THEN SET p_tipooperacion = 'M';

                SET p_logo = FROM_BASE64(JSON_UNQUOTE(JSON_EXTRACT(pRegistrosJson, CONCAT('$.cabecera[', vIndex, '].logo'))));
                IF p_logo = '' THEN
                  set p_logo = NULL;
                END IF;
                SET p_fechamodificacion = NOW(3);
                SET p_usuariomodificacion = JSON_UNQUOTE(JSON_EXTRACT(pRegistrosJson, CONCAT('$.cabecera[', vIndex, '].usuariomodificacion')));


                SET vRegistroAnterior = (SELECT
                    JSON_OBJECT
                    (
                    'sri_documentoscodigo', sri_documentoscodigo,
                    'secuenciasid', secuenciasid,
                    'descripcion', descripcion,
                    'estado', estado,
                    'numerodigitos', numerodigitos,
                    'autorizacion', autorizacion,
                    'establecimiento', establecimiento,
                    'puntoemision', puntoemision,
                    'numeroactual', numeroactual,
                    'formasecuencia', formasecuencia,
                    'cantidaditems', cantidaditems,
                    'calculaiva', calculaiva,
                    'documentofiscal', documentofiscal,
                    'documentoelectronico', documentoelectronico,
                    'transportista', transportista,
                    'tipocontribuyente', tipocontribuyente,
                    'identificacion', identificacion,
                    'razonsocial', razonsocial,
                    'direccionestablecimiento', direccionestablecimiento,
                    'telefono', telefono,
                    'placa', placa,
                    'logo', HEX(logo),
                    'tiporegimen', tiporegimen,
                    'agentederetencion', agentederetencion,
                    'permite_recargo', permite_recargo,
                    'ruta_impresora1', ruta_impresora1,
                    'ruta_impresora2', ruta_impresora2,
                    'ruta_impresora3', ruta_impresora3,
                    'fechamodificacion', fechamodificacion,
                    'usuariomodificacion', usuariomodificacion,
                    'empresas_certificadosid',empresas_certificadosid
                    )
                  FROM secuencias
                  WHERE secuencias.secuenciasid = p_secuenciasid);

                SET p_detalle = REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(JSON_INSERT('{}', '$.secuencias', vRegistroAnterior), '"[', '['), ']"', ']'), '\\', ''), '"{', '{'), '}"', '}');

                # ACTUALIZAMOS LOS REGISTROS
                UPDATE secuencias
                SET sri_documentoscodigo = p_sri_documentoscodigo,
                    secuenciasid = p_secuenciasid,
                    descripcion = p_descripcion,
                    estado = p_estado,
                    numerodigitos = p_numerodigitos,
                    autorizacion = p_autorizacion,
                    establecimiento = p_establecimiento,
                    puntoemision = p_puntoemision,
                    numeroactual = p_numeroactual,
                    formasecuencia = p_formasecuencia,
                    cantidaditems = p_cantidaditems,
                    calculaiva = p_calculaiva,
                    documentofiscal = p_documentofiscal,
                    documentoelectronico = p_documentoelectronico,
                    transportista = p_transportista,
                    tipocontribuyente = p_tipocontribuyente,
                    identificacion = p_identificacion,
                    razonsocial = p_razonsocial,
                    direccionestablecimiento = p_direccionestablecimiento,
                    telefono = p_telefono,
                    placa = p_placa,
                    logo = p_logo,
                    tiporegimen = p_tiporegimen,
                    agentederetencion = p_agentederetencion,
                    permite_recargo = p_permite_recargo,
                    ruta_impresora1 = p_ruta_impresora1,
                    ruta_impresora2 = p_ruta_impresora2,
                    ruta_impresora3 = p_ruta_impresora3,
                    fechamodificacion = p_fechamodificacion,
                    usuariomodificacion = p_usuariomodificacion,
                    empresas_certificadosid = p_empresas_certificadosid
                WHERE secuencias.secuenciasid = p_secuenciasid;

            WHEN 'E' THEN SET p_tipooperacion = 'E';
                SET p_detalle = REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(JSON_INSERT('{}', '$.secuencias', JSON_EXTRACT(pRegistrosJson, CONCAT('$.cabecera[', vIndex, ']'))), '"[', '['), ']"', ']'), '\\', ''), '"{', '{'), '}"', '}');

                SET @p_docid = (SELECT DISTINCT COUNT(compras.comprasid) as comprasid FROM compras WHERE	compras.secuenciasid_retencion = p_secuenciasid OR
                compras.secuenciasid_liquidacion = p_secuenciasid);

                IF @p_docid > 0 THEN
                  SELECT
                  JSON_ARRAYAGG(JSON_OBJECT('procesado', FALSE, 'mensaje', 'La secuencia tiene documentos asociados')) AS resultado;
                  LEAVE secuencias;
                ELSE	

                  set @p_Cerid = (SELECT COUNT(secuencias.empresas_certificadosid) AS id FROM secuencias WHERE secuencias.empresas_certificadosid = p_empresas_certificadosid);
                  # ELIMINAMOS LOS REGISTROS
                  DELETE
                  FROM secuencias
                  WHERE secuencias.secuenciasid = p_secuenciasid;

                  IF @p_Cerid = 1 THEN 
                    # ELIMINAMOS LOS REGISTROS
                    DELETE FROM empresas_certificado WHERE empresas_certificadosid=p_empresas_certificadosid;
                  END IF;
                END IF;

          END CASE;

          # INSERTAMOS LA AUDITORIA
          CALL sistemaperseo.SP_ABC_sis_log_sistema(p_sis_subcategoriasid, p_sis_empresasid, p_sis_usuariosid, p_tipooperacion, p_detalle, p_equipo);

          SET vIndex = vIndex + 1;
        END WHILE;
      COMMIT;

      # RETORNAMOS LA RESPUESTAS
      IF pAccion IN ('C', 'M') THEN

        SELECT
          secuencias.sri_documentoscodigo,
          secuencias.secuenciasid,
          secuencias.descripcion,
          secuencias.estado,
          secuencias.numerodigitos,
          secuencias.autorizacion,
          secuencias.establecimiento,
          secuencias.puntoemision,
          secuencias.numeroactual,
          secuencias.formasecuencia,
          secuencias.cantidaditems,
          secuencias.calculaiva,
          secuencias.documentofiscal,
          secuencias.documentoelectronico,
  secuencias.transportista,
          secuencias.tipocontribuyente,
          secuencias.identificacion,
          secuencias.razonsocial,
          secuencias.direccionestablecimiento,
          secuencias.telefono,
          secuencias.placa,
          secuencias.logo,
          secuencias.tiporegimen,
          secuencias.agentederetencion,
          secuencias.permite_recargo,
          secuencias.ruta_impresora1,
          secuencias.ruta_impresora2,
          secuencias.ruta_impresora3,
          secuencias.fechacreacion,
          secuencias.usuariocreacion,
          secuencias.fechamodificacion,
          secuencias.usuariomodificacion,
          empresas_certificado.de_ambiente,
      		empresas_certificado.de_caducacer,
      		empresas_certificado.de_certificadodigital,
      		empresas_certificado.de_clavecertificado,
      		empresas_certificado.de_contriespecial,
      		empresas_certificado.de_correo_predeterminado,
      		empresas_certificado.de_direccion,
      		empresas_certificado.de_email,
      		empresas_certificado.de_fechacertificado,
      		empresas_certificado.de_identificacion_empresa,
      		empresas_certificado.de_informacion,
      		empresas_certificado.de_llevacontabilidad,
      		empresas_certificado.de_nombrecomercial,
      		empresas_certificado.de_razonsocial,
      		empresas_certificado.de_sql_factura,
      		empresas_certificado.de_sql_guiaremision,
      		empresas_certificado.de_sql_liquidacioncompra,
      		empresas_certificado.de_sql_notacredito,
      		empresas_certificado.de_sql_notadebito,
      		empresas_certificado.de_sql_retencion,
      		empresas_certificado.de_telefono,
      		empresas_certificado.de_tipoidentificacion,
      		empresas_certificado.de_whtasapp,
      		empresas_certificado.empresas_certificadosid,
      		empresas_certificado.de_tiposql_factura,
          (SELECT
              JSON_ARRAYAGG(JSON_OBJECT('procesado', TRUE, 'mensaje', 'Completado con Éxito'))) AS resultado
        FROM secuencias
        left JOIN empresas_certificado ON empresas_certificado.empresas_certificadosid = secuencias.secuenciasid
        WHERE secuencias.secuenciasid = p_secuenciasid;

      ELSE
        SELECT
          JSON_ARRAYAGG(JSON_OBJECT('procesado', TRUE, 'mensaje', 'Completado con Éxito')) AS resultado;
      END IF;
    END IF;
  END IF;
END
;;
delimiter ;

