-- ----------------------------
-- Procedure structure for SP_tarjetas_ABC
-- ----------------------------
DROP PROCEDURE IF EXISTS `SP_tarjetas_ABC`;
delimiter ;;
CREATE PROCEDURE `SP_tarjetas_ABC`(IN pAccion varchar(1), IN pRegistrosJson json)
tarjetas:BEGIN
  DECLARE vJsonEsValido int;
  DECLARE vItems int;
  DECLARE vIndex bigint UNSIGNED DEFAULT 0;
  DECLARE vErrorMensaje text;
  DECLARE vRegistroAnterior longtext;


  # VARIABLES DE LOS DATOS DE LA TABLA
  DECLARE p_tarjetasid int(11);
  DECLARE p_descripcion varchar(30) DEFAULT '';
  DECLARE p_fechacreacion datetime(3) DEFAULT '0000-00-00 00:00:00.000';
  DECLARE p_usuariocreacion varchar(25) DEFAULT '';
  DECLARE p_fechamodificacion datetime(3) DEFAULT '0000-00-00 00:00:00.000';
  DECLARE p_usuariomodificacion varchar(25) DEFAULT '';


  # VARIABLE DE LOS DATOS DE LA AUDITORIA
  DECLARE p_sis_subcategoriasid int(11) DEFAULT 0;
  DECLARE p_sis_empresasid int(11) DEFAULT 0;
  DECLARE p_sis_usuariosid varchar(20) DEFAULT '';
  DECLARE p_equipo varchar(50) DEFAULT '';
  DECLARE p_tipooperacion varchar(50) DEFAULT '';
  DECLARE p_detalle longtext;

    # CONTROLAMOS SI HAY ERROR
  DECLARE EXIT HANDLER FOR SQLEXCEPTION, SQLWARNING
  BEGIN
    GET DIAGNOSTICS CONDITION 1 vErrorMensaje = MESSAGE_TEXT;
    SELECT
      CASE WHEN LOCATE('Cannot delete or update a parent row',vErrorMensaje)>0 THEN JSON_ARRAYAGG(JSON_OBJECT('procesado', FALSE, 'mensaje', 'No Se Puede Eliminar, Tarjeta en Uso')) ELSE JSON_ARRAYAGG(JSON_OBJECT('procesado', FALSE, 'mensaje', vErrorMensaje)) END AS resultado;
    ROLLBACK;
  END;
  # VALIDAMOS SI EL OBJETO JSON ES VALIDO 
  SET vJsonEsValido = JSON_VALID(pRegistrosJson);

  IF vJsonEsValido = 0 THEN
    # EL OBJETO JSON NO ES VALIDO
    SELECT
      JSON_ARRAYAGG(JSON_OBJECT('procesado', FALSE, 'mensaje', 'Json no es valido')) AS resultado;
  ELSE

    # VALIDAMOS QUE TENGA ALMENOS UN ELEMENTO
    SET vItems = JSON_LENGTH(pRegistrosJson, '$.cabecera');

    IF vItems > 0 THEN
      START TRANSACTION;
        WHILE vIndex < vItems DO

          # DATOS TABLA
          SET p_tarjetasid = IFNULL(JSON_UNQUOTE(JSON_EXTRACT(pRegistrosJson, CONCAT('$.cabecera[', vIndex, '].tarjetasid'))), p_tarjetasid);
          SET p_descripcion = IFNULL(JSON_UNQUOTE(JSON_EXTRACT(pRegistrosJson, CONCAT('$.cabecera[', vIndex, '].descripcion'))), p_descripcion);


          # DATOS AUDITORIA
          SET p_sis_subcategoriasid = JSON_UNQUOTE(JSON_EXTRACT(pRegistrosJson, CONCAT('$.cabecera[', vIndex, '].sis_subcategoriasid')));
          SET p_sis_empresasid = JSON_UNQUOTE(JSON_EXTRACT(pRegistrosJson, CONCAT('$.cabecera[', vIndex, '].sis_empresasid')));
          SET p_sis_usuariosid = JSON_UNQUOTE(JSON_EXTRACT(pRegistrosJson, CONCAT('$.cabecera[', vIndex, '].sis_usuariosid')));
          SET p_equipo = JSON_UNQUOTE(JSON_EXTRACT(pRegistrosJson, CONCAT('$.cabecera[', vIndex, '].equipo')));


          CASE pAccion
            WHEN 'C' THEN SET p_tipooperacion = 'N';
                SET p_fechacreacion = NOW(3);
                SET p_usuariocreacion = JSON_UNQUOTE(JSON_EXTRACT(pRegistrosJson, CONCAT('$.cabecera[', vIndex, '].usuariocreacion')));
                SET p_fechamodificacion = NULL;
                SET p_usuariomodificacion = '';
                SET p_detalle = REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(JSON_INSERT('{}', '$.tarjetas', JSON_EXTRACT(pRegistrosJson, CONCAT('$.cabecera[', vIndex, ']'))), '"[', '['), ']"', ']'), '\\', ''), '"{', '{'), '}"', '}');

                # INSERTAMOS LOS REGISTROS
                INSERT INTO tarjetas (tarjetasid, descripcion, fechacreacion, usuariocreacion, fechamodificacion, usuariomodificacion)
                  VALUES (p_tarjetasid, p_descripcion, p_fechacreacion, p_usuariocreacion, p_fechamodificacion, p_usuariomodificacion);

SET p_tarjetasid = LAST_INSERT_ID();
            WHEN 'M' THEN SET p_tipooperacion = 'M';
                SET p_fechamodificacion = NOW(3);
                SET p_usuariomodificacion = JSON_UNQUOTE(JSON_EXTRACT(pRegistrosJson, CONCAT('$.cabecera[', vIndex, '].usuariomodificacion')));


                SET vRegistroAnterior = (SELECT
                    JSON_OBJECT
                    (
                    'tarjetasid', tarjetasid,
                    'descripcion', descripcion,
                    'fechamodificacion', fechamodificacion,
                    'usuariomodificacion', usuariomodificacion
                    )
                  FROM tarjetas
                  WHERE tarjetas.tarjetasid = p_tarjetasid);

                SET p_detalle = REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(JSON_INSERT('{}', '$.tarjetas', vRegistroAnterior), '"[', '['), ']"', ']'), '\\', ''), '"{', '{'), '}"', '}');

                # ACTUALIZAMOS LOS REGISTROS
                UPDATE tarjetas
                SET tarjetasid = p_tarjetasid,
                    descripcion = p_descripcion,
                    fechamodificacion = p_fechamodificacion,
                    usuariomodificacion = p_usuariomodificacion
                WHERE tarjetasid = p_tarjetasid;

            WHEN 'E' THEN SET p_tipooperacion = 'E';
                SET p_detalle = REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(JSON_INSERT('{}', '$.tarjetas', JSON_EXTRACT(pRegistrosJson, CONCAT('$.cabecera[', vIndex, ']'))), '"[', '['), ']"', ']'), '\\', ''), '"{', '{'), '}"', '}');

SET @p_docid = (
SELECT DISTINCT	COUNT(bancotarjetaid) as bancotarjetaid
FROM	movcaja	
WHERE	movcaja.forma_pago_empresaid = 4 AND 	movcaja.bancotarjetaid = p_tarjetasid);
 
IF @p_docid > 0 THEN
SELECT
JSON_ARRAYAGG(JSON_OBJECT('procesado', FALSE, 'mensaje', 'La tarjeta ya tiene documentos asociados')) AS resultado;
LEAVE tarjetas;
ELSE	
                # ELIMINAMOS LOS REGISTROS
                DELETE
                  FROM tarjetas
                WHERE tarjetasid = p_tarjetasid;
END IF;    
          END CASE;

          # INSERTAMOS LA AUDITORIA
          CALL sistemaperseo.SP_ABC_sis_log_sistema(p_sis_subcategoriasid, p_sis_empresasid, p_sis_usuariosid, p_tipooperacion, p_detalle, p_equipo);

          SET vIndex = vIndex + 1;
        END WHILE;
      COMMIT;


      # RETORNAMOS LA RESPUESTAS
      IF pAccion IN ('C', 'M') THEN

        SELECT
          tarjetas.tarjetasid,
          tarjetas.descripcion,
          tarjetas.fechacreacion,
          tarjetas.usuariocreacion,
          tarjetas.fechamodificacion,
          tarjetas.usuariomodificacion,
          (SELECT
              JSON_ARRAYAGG(JSON_OBJECT('procesado', TRUE, 'mensaje', 'Completado con Éxito'))) AS resultado
        FROM tarjetas
        WHERE tarjetas.tarjetasid = p_tarjetasid;

      ELSE
        SELECT
          JSON_ARRAYAGG(JSON_OBJECT('procesado', TRUE, 'mensaje', 'Completado con Éxito')) AS resultado;
      END IF;
    END IF;
  END IF;

END
;;
delimiter ;

-- ----------------------------
-- Procedure structure for SP_tarjetas_ConsultarID
-- ----------------------------
DROP PROCEDURE IF EXISTS `SP_tarjetas_ConsultarID`;
delimiter ;;
CREATE PROCEDURE `SP_tarjetas_ConsultarID`(IN p_tarjetasid int(11))
BEGIN

  SELECT
    tarjetas.tarjetasid,
    tarjetas.descripcion,
    tarjetas.fechacreacion,
    tarjetas.usuariocreacion,
    tarjetas.fechamodificacion,
    tarjetas.usuariomodificacion
  FROM tarjetas
  WHERE tarjetas.tarjetasid = p_tarjetasid;

END
;;
delimiter ;

-- ----------------------------
-- Procedure structure for SP_transportistas_ABC
-- ----------------------------
DROP PROCEDURE IF EXISTS `SP_transportistas_ABC`;
delimiter ;;
CREATE PROCEDURE `SP_transportistas_ABC`(IN pAccion varchar(1), IN pRegistrosJson json)
BEGIN
  DECLARE vJsonEsValido int;
  DECLARE vItems int;
  DECLARE vIndex bigint UNSIGNED DEFAULT 0;
  DECLARE vErrorMensaje text;
  DECLARE vRegistroAnterior longtext;


  # VARIABLES DE LOS DATOS DE LA TABLA
  DECLARE p_clientesid bigint(20) DEFAULT 1;
  DECLARE p_transportistasid bigint(20);
  DECLARE p_tipotransportista int(11) DEFAULT 0;
  DECLARE p_tipoidentificacion varchar(1) DEFAULT '';
  DECLARE p_nombres varchar(100) DEFAULT '';
  DECLARE p_direccion varchar(100) DEFAULT '';
  DECLARE p_email varchar(50) DEFAULT '';
  DECLARE p_vehiculo varchar(30) DEFAULT '';
  DECLARE p_telefono varchar(10) DEFAULT '';
  DECLARE p_celular varchar(10) DEFAULT '';
  DECLARE p_identificacion varchar(20) DEFAULT '';
  DECLARE p_placa varchar(8) DEFAULT '';
  DECLARE p_peso decimal(12, 2) DEFAULT 0.00;
  DECLARE p_observacion varchar(75) DEFAULT '';
  DECLARE p_estado tinyint(4) DEFAULT 0;
  DECLARE p_llevacontabilidad tinyint(4) DEFAULT 0;
  DECLARE p_fechacreacion datetime(3) DEFAULT '0000-00-00 00:00:00.000';
  DECLARE p_usuariocreacion varchar(25) DEFAULT '';
  DECLARE p_fechamodificacion datetime(3) DEFAULT '0000-00-00 00:00:00.000';
  DECLARE p_usuariomodificacion varchar(25) DEFAULT '';


  # VARIABLE DE LOS DATOS DE LA AUDITORIA
  DECLARE p_sis_subcategoriasid int(11) DEFAULT 0;
  DECLARE p_sis_empresasid int(11) DEFAULT 0;
  DECLARE p_sis_usuariosid varchar(20) DEFAULT '';
  DECLARE p_equipo varchar(50) DEFAULT '';
  DECLARE p_tipooperacion varchar(50) DEFAULT '';
  DECLARE p_detalle longtext;

  # CONTROLAMOS SI HAY ERROR
  DECLARE EXIT HANDLER FOR SQLEXCEPTION, SQLWARNING
  BEGIN
    GET DIAGNOSTICS CONDITION 1 vErrorMensaje = MESSAGE_TEXT;
    SELECT
      CASE WHEN LOCATE('Cannot delete or update a parent row',vErrorMensaje)>0 THEN JSON_ARRAYAGG(JSON_OBJECT('procesado', FALSE, 'mensaje', 'No Se Puede Eliminar, Transportista en Uso')) ELSE JSON_ARRAYAGG(JSON_OBJECT('procesado', FALSE, 'mensaje', vErrorMensaje)) END AS resultado;
    ROLLBACK;
  END;
  # VALIDAMOS SI EL OBJETO JSON ES VALIDO 
  SET vJsonEsValido = JSON_VALID(pRegistrosJson);

  IF vJsonEsValido = 0 THEN
    # EL OBJETO JSON NO ES VALIDO
    SELECT
      JSON_ARRAYAGG(JSON_OBJECT('procesado', FALSE, 'mensaje', 'Json no es valido')) AS resultado;
  ELSE

    # VALIDAMOS QUE TENGA ALMENOS UN ELEMENTO
    SET vItems = JSON_LENGTH(pRegistrosJson, '$.cabecera');

    IF vItems > 0 THEN
      START TRANSACTION;
        WHILE vIndex < vItems DO

          # DATOS TABLA
          SET p_clientesid = IFNULL(JSON_UNQUOTE(JSON_EXTRACT(pRegistrosJson, CONCAT('$.cabecera[', vIndex, '].clientesid'))), p_clientesid);
          SET p_transportistasid = IFNULL(JSON_UNQUOTE(JSON_EXTRACT(pRegistrosJson, CONCAT('$.cabecera[', vIndex, '].transportistasid'))), p_transportistasid);
          SET p_tipotransportista = IFNULL(JSON_UNQUOTE(JSON_EXTRACT(pRegistrosJson, CONCAT('$.cabecera[', vIndex, '].tipotransportista'))), p_tipotransportista);
          SET p_tipoidentificacion = IFNULL(JSON_UNQUOTE(JSON_EXTRACT(pRegistrosJson, CONCAT('$.cabecera[', vIndex, '].tipoidentificacion'))), p_tipoidentificacion);
          SET p_nombres = IFNULL(JSON_UNQUOTE(JSON_EXTRACT(pRegistrosJson, CONCAT('$.cabecera[', vIndex, '].nombres'))), p_nombres);
          SET p_direccion = IFNULL(JSON_UNQUOTE(JSON_EXTRACT(pRegistrosJson, CONCAT('$.cabecera[', vIndex, '].direccion'))), p_direccion);
          SET p_email = IFNULL(JSON_UNQUOTE(JSON_EXTRACT(pRegistrosJson, CONCAT('$.cabecera[', vIndex, '].email'))), p_email);
          SET p_vehiculo = IFNULL(JSON_UNQUOTE(JSON_EXTRACT(pRegistrosJson, CONCAT('$.cabecera[', vIndex, '].vehiculo'))), p_vehiculo);
          SET p_telefono = IFNULL(JSON_UNQUOTE(JSON_EXTRACT(pRegistrosJson, CONCAT('$.cabecera[', vIndex, '].telefono'))), p_telefono);
          SET p_celular = IFNULL(JSON_UNQUOTE(JSON_EXTRACT(pRegistrosJson, CONCAT('$.cabecera[', vIndex, '].celular'))), p_celular);
          SET p_identificacion = IFNULL(JSON_UNQUOTE(JSON_EXTRACT(pRegistrosJson, CONCAT('$.cabecera[', vIndex, '].identificacion'))), p_identificacion);
          SET p_placa = IFNULL(JSON_UNQUOTE(JSON_EXTRACT(pRegistrosJson, CONCAT('$.cabecera[', vIndex, '].placa'))), p_placa);
          SET p_peso = IFNULL(JSON_UNQUOTE(JSON_EXTRACT(pRegistrosJson, CONCAT('$.cabecera[', vIndex, '].peso'))), p_peso);
          SET p_observacion = IFNULL(JSON_UNQUOTE(JSON_EXTRACT(pRegistrosJson, CONCAT('$.cabecera[', vIndex, '].observacion'))), p_observacion);
          SET p_estado = IFNULL(JSON_UNQUOTE(JSON_EXTRACT(pRegistrosJson, CONCAT('$.cabecera[', vIndex, '].estado'))), p_estado);
          SET p_llevacontabilidad = IFNULL(JSON_UNQUOTE(JSON_EXTRACT(pRegistrosJson, CONCAT('$.cabecera[', vIndex, '].llevacontabilidad'))), p_llevacontabilidad);


           CASE pAccion
            WHEN 'C' THEN SET p_tipooperacion = 'N';
                SET p_fechacreacion = NOW(3);
                SET p_usuariocreacion = JSON_UNQUOTE(JSON_EXTRACT(pRegistrosJson, CONCAT('$.cabecera[', vIndex, '].usuariocreacion')));
                SET p_fechamodificacion = NULL;
                SET p_usuariomodificacion = '';
                SET p_detalle = REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(JSON_INSERT('{}', '$.transportistas', JSON_EXTRACT(pRegistrosJson, CONCAT('$.cabecera[', vIndex, ']'))), '"[', '['), ']"', ']'), '\\', ''), '"{', '{'), '}"', '}');

                # INSERTAMOS LOS REGISTROS
                INSERT INTO transportistas (clientesid, transportistasid, tipotransportista, tipoidentificacion, nombres, direccion, email, vehiculo, telefono, celular, identificacion, placa, peso, observacion, estado, llevacontabilidad, fechacreacion, usuariocreacion, fechamodificacion, usuariomodificacion)
                  VALUES (p_clientesid, p_transportistasid, p_tipotransportista, p_tipoidentificacion, p_nombres, p_direccion, p_email, p_vehiculo, p_telefono, p_celular, p_identificacion, p_placa, p_peso, p_observacion, p_estado, p_llevacontabilidad, p_fechacreacion, p_usuariocreacion, p_fechamodificacion, p_usuariomodificacion);
SET p_transportistasid = LAST_INSERT_ID();
            WHEN 'M' THEN SET p_tipooperacion = 'M';
                SET p_fechamodificacion = NOW(3);
                SET p_usuariomodificacion = JSON_UNQUOTE(JSON_EXTRACT(pRegistrosJson, CONCAT('$.cabecera[', vIndex, '].usuariomodificacion')));


                SET vRegistroAnterior = (SELECT
                    JSON_OBJECT
                    (
                    'clientesid', clientesid,
                    'transportistasid', transportistasid,
                    'tipotransportista', tipotransportista,
                    'tipoidentificacion', tipoidentificacion,
                    'nombres', nombres,
                    'direccion', direccion,
                    'email', email,
                    'vehiculo', vehiculo,
                    'telefono', telefono,
                    'celular', celular,
                    'identificacion', identificacion,
                    'placa', placa,
                    'peso', peso,
                    'observacion', observacion,
                    'estado', estado,
                    'llevacontabilidad', llevacontabilidad,
                    'fechamodificacion', fechamodificacion,
                    'usuariomodificacion', usuariomodificacion
                    )
                  FROM transportistas
                  WHERE transportistas.transportistasid = p_transportistasid);

                SET p_detalle = REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(JSON_INSERT('{}', '$.transportistas', vRegistroAnterior), '"[', '['), ']"', ']'), '\\', ''), '"{', '{'), '}"', '}');

                # ACTUALIZAMOS LOS REGISTROS
                UPDATE transportistas
                SET clientesid = p_clientesid,
                    transportistasid = p_transportistasid,
                    tipotransportista = p_tipotransportista,
                    tipoidentificacion = p_tipoidentificacion,
                    nombres = p_nombres,
                    direccion = p_direccion,
                    email = p_email,
                    vehiculo = p_vehiculo,
                    telefono = p_telefono,
                    celular = p_celular,
                    identificacion = p_identificacion,
                    placa = p_placa,
                    peso = p_peso,
                    observacion = p_observacion,
                    estado = p_estado,
                    llevacontabilidad = p_llevacontabilidad,
                    fechamodificacion = p_fechamodificacion,
                    usuariomodificacion = p_usuariomodificacion
                WHERE transportistasid = p_transportistasid;

            WHEN 'E' THEN SET p_tipooperacion = 'E';
                SET p_detalle = REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(JSON_INSERT('{}', '$.transportistas', JSON_EXTRACT(pRegistrosJson, CONCAT('$.cabecera[', vIndex, ']'))), '"[', '['), ']"', ']'), '\\', ''), '"{', '{'), '}"', '}');

                # ELIMINAMOS LOS REGISTROS
                DELETE
                  FROM transportistas
                WHERE transportistasid = p_transportistasid;

          END CASE;

          SET vIndex = vIndex + 1;
        END WHILE;
      COMMIT;

      # RETORNAMOS LA RESPUESTAS
      IF pAccion IN ('C', 'M') THEN

SELECT
transportistas.clientesid, 
transportistas.transportistasid, 
transportistas.tipotransportista, 
transportistas.tipoidentificacion, 
transportistas.nombres, 
transportistas.direccion, 
transportistas.email, 
transportistas.vehiculo, 
transportistas.telefono, 
transportistas.celular, 
transportistas.identificacion, 
transportistas.placa, 
transportistas.peso, 
transportistas.observacion, 
transportistas.estado, 
transportistas.llevacontabilidad, 
transportistas.fechacreacion, 
transportistas.usuariocreacion, 
transportistas.fechamodificacion, 
transportistas.usuariomodificacion,
          (SELECT
              JSON_ARRAYAGG(JSON_OBJECT('procesado', TRUE, 'mensaje', 'Completado con Éxito'))) AS resultado
        FROM transportistas
        WHERE transportistas.transportistasid = p_transportistasid;

      ELSE
        SELECT
          JSON_ARRAYAGG(JSON_OBJECT('procesado', TRUE, 'mensaje', 'Completado con Éxito')) AS resultado;
      END IF;
    END IF;
  END IF;
END
;;
delimiter ;

-- ----------------------------
-- Procedure structure for SP_transportistas_ConsultarID
-- ----------------------------
DROP PROCEDURE IF EXISTS `SP_transportistas_ConsultarID`;
delimiter ;;
CREATE PROCEDURE `SP_transportistas_ConsultarID`(IN p_transportistasid int(11))
BEGIN

  SELECT
    transportistas.clientesid,
    transportistas.transportistasid,
    transportistas.tipotransportista,
    transportistas.tipoidentificacion,
    transportistas.nombres,
    transportistas.direccion,
    transportistas.email,
    transportistas.vehiculo,
    transportistas.telefono,
    transportistas.celular,
    transportistas.identificacion,
    transportistas.placa,
    transportistas.peso,
    transportistas.observacion,
    transportistas.estado,
    transportistas.llevacontabilidad,
    transportistas.fechacreacion,
    transportistas.usuariocreacion,
    transportistas.fechamodificacion,
    transportistas.usuariomodificacion
  FROM transportistas
  WHERE transportistas.transportistasid = p_transportistasid;

END
;;
delimiter ;

SET FOREIGN_KEY_CHECKS = 1;
